
/* === from: primitives.css === */
:where(.ui-text, .ui-heading) {
  margin: 0;
  color: var(--johnbot-text-primary);
  font-family: var(--johnbot-font-sans);
}

.ui-server-gradient-logo {
  width: var(--server-gradient-logo-size, 40px);
  height: var(--server-gradient-logo-size, 40px);
  display: block;
  flex: 0 0 auto;
  overflow: hidden;
  border-radius: var(--server-gradient-logo-radius, var(--johnbot-radius-lg));
  background-color: var(--server-gradient-base);
  background-image: var(--server-gradient-layers);
  background-repeat: no-repeat;
  outline: 1px solid var(--johnbot-image-outline);
  outline-offset: -1px;
}

:where(.ui-text)[data-tone="secondary"],
:where(.ui-heading)[data-tone="secondary"] {
  color: var(--johnbot-text-secondary);
}

:where(.ui-text)[data-tone="muted"],
:where(.ui-heading)[data-tone="muted"] {
  color: var(--johnbot-text-muted);
}

:where(.ui-text, .ui-heading)[data-tone="danger"] {
  color: var(--johnbot-danger);
}

:where(.ui-text, .ui-heading)[data-tone="success"] {
  color: var(--johnbot-success);
}

:where(.ui-text, .ui-heading)[data-tone="warning"] {
  color: var(--johnbot-warning);
}

:where(.ui-text)[data-variant="caption"] {
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-regular);
  line-height: var(--johnbot-leading-sm);
}

:where(.ui-text)[data-variant="label-sm"] {
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-sm);
}

:where(.ui-text)[data-variant="label"] {
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-md);
}

:where(.ui-text)[data-variant="body-sm"] {
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-regular);
  line-height: var(--johnbot-leading-md);
}

:where(.ui-text)[data-variant="body"] {
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-regular);
  line-height: var(--johnbot-leading-lg);
}

:where(.ui-heading)[data-size="sm"] {
  font-size: var(--johnbot-text-lg);
  line-height: var(--johnbot-leading-lg);
}

:where(.ui-heading)[data-size="md"] {
  font-size: var(--johnbot-text-xl);
  line-height: var(--johnbot-leading-xl);
}

:where(.ui-heading)[data-size="lg"] {
  font-size: var(--johnbot-text-2xl);
  line-height: var(--johnbot-leading-2xl);
}

:where(.ui-heading) {
  font-weight: var(--johnbot-weight-semibold);
  letter-spacing: var(--johnbot-tracking-tight);
}

.ui-text-truncate {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

:where(.ui-button) {
  min-width: 0;
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  gap: var(--johnbot-space-1-5);
  border: 1px solid transparent;
  border-radius: var(--johnbot-radius-md);
  padding: 0 var(--johnbot-space-4);
  color: var(--johnbot-text-primary);
  font-family: var(--johnbot-font-sans);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  line-height: 1;
  text-decoration: none;
  user-select: none;
  white-space: nowrap;
  transition:
    background-color var(--johnbot-duration-hover) ease,
    border-color var(--johnbot-duration-hover) ease,
    color var(--johnbot-duration-hover) ease,
    box-shadow var(--johnbot-duration-hover) ease,
    opacity var(--johnbot-duration-hover) ease;
}

.ui-button {
  font-family: var(--johnbot-font-sans);
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-medium);
}

:where(.ui-button-size-xs) {
  height: var(--johnbot-control-xs);
  padding-inline: var(--johnbot-space-2);
  font-size: var(--johnbot-text-sm);
}

:where(.ui-button-size-sm) {
  height: var(--johnbot-control-md);
  padding-inline: var(--johnbot-space-3);
  font-size: var(--johnbot-text-sm);
}

:where(.ui-button-size-default) {
  height: var(--johnbot-control-lg);
}

:where(.ui-button-size-lg) {
  height: var(--johnbot-control-xl);
  padding-inline: var(--johnbot-space-6);
}

/* A Lucide icon keeps width="24" when the caller sets no size, which is too large next to button
   text. These rules have no specificity, so a size prop or a feature rule still wins. */
:where(.ui-button > svg[width="24"]) {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  flex: 0 0 auto;
  stroke-width: var(--johnbot-icon-stroke);
}

:where(.ui-button-size-xs > svg[width="24"], .ui-button-size-sm > svg[width="24"]) {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

:where(.ui-button-variant-default) {
  background: var(--johnbot-surface-light);
  color: var(--johnbot-text-on-light);
}

:where(.ui-button-variant-outline) {
  border-color: var(--johnbot-border);
  background: var(--johnbot-bg-control);
  color: var(--johnbot-text-secondary);
}

:where(.ui-button-variant-secondary) {
  background: var(--johnbot-bg-control-hover);
  color: var(--johnbot-text-primary);
}

:where(.ui-button-variant-ghost) {
  background: transparent;
  color: var(--johnbot-text-muted);
}

:where(.ui-button-variant-destructive) {
  background: var(--johnbot-danger-soft);
  color: var(--johnbot-danger);
}

:where(.ui-button-variant-destructive-ghost) {
  background: transparent;
  color: var(--johnbot-text-muted);
}

:where(.ui-button-variant-link) {
  height: auto;
  border-radius: var(--johnbot-radius-xs);
  background: transparent;
  padding: 0;
  color: var(--johnbot-text-primary);
  text-underline-offset: 4px;
}

@media (hover: hover) and (pointer: fine) and (min-width: 601px) {
  :where(.ui-button-variant-default):hover:not(:disabled):not([data-disabled]) {
    background: color-mix(in srgb, var(--johnbot-surface-light) 82%, transparent);
  }

  :where(.ui-button-variant-outline):hover:not(:disabled):not([data-disabled]),
  :where(.ui-button-variant-ghost):hover:not(:disabled):not([data-disabled]) {
    background: var(--johnbot-bg-control-hover);
    color: var(--johnbot-text-primary);
  }

  :where(.ui-button-variant-secondary):hover:not(:disabled):not([data-disabled]) {
    background: var(--johnbot-bg-control-active);
  }

  :where(.ui-button-variant-destructive):hover:not(:disabled):not([data-disabled]) {
    background: var(--johnbot-danger-soft-hover);
    color: var(--johnbot-danger);
  }

  :where(.ui-button-variant-destructive-ghost):hover:not(:disabled):not([data-disabled]) {
    background: var(--johnbot-danger-soft);
    color: var(--johnbot-danger);
  }

  :where(.ui-button-variant-link):hover:not(:disabled):not([data-disabled]) {
    text-decoration: underline;
  }
}

:where(.ui-button-variant-outline, .ui-button-variant-secondary, .ui-button-variant-ghost)[aria-expanded="true"] {
  background: var(--johnbot-bg-control-hover);
  color: var(--johnbot-text-primary);
}

:where(.ui-button):focus-visible {
  outline: 0;
  box-shadow: var(--johnbot-focus-ring);
}

:where(.ui-button-variant-destructive):focus-visible {
  border-color: var(--johnbot-danger-focus);
}

:where(.ui-button)[aria-invalid="true"] {
  border-color: var(--johnbot-danger-border);
  box-shadow: 0 0 0 3px var(--johnbot-danger-focus);
}

:where(.ui-button):disabled,
:where(.ui-button)[data-disabled] {
  cursor: default;
  opacity: 0.42;
  pointer-events: none;
}

.ui-button-full {
  width: 100%;
}

:where(.ui-icon-button) {
  padding: 0;
}

:where(.ui-button-size-icon-xs) {
  width: var(--johnbot-control-xs);
  height: var(--johnbot-control-xs);
  padding: 0;
}

:where(.ui-button-size-icon-sm) {
  width: var(--johnbot-control-md);
  height: var(--johnbot-control-md);
  padding: 0;
}

:where(.ui-button-size-icon) {
  width: var(--johnbot-control-lg);
  height: var(--johnbot-control-lg);
  padding: 0;
}

:where(.ui-button-size-icon-lg) {
  width: var(--johnbot-control-xl);
  height: var(--johnbot-control-xl);
  padding: 0;
}

:where(.ui-icon-button) svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  flex: 0 0 auto;
  stroke-width: var(--johnbot-icon-stroke);
}

:where(.ui-button-size-icon-xs) svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.ui-removable-image {
  position: relative;
}

.ui-image-remove-button {
  position: absolute;
  z-index: 1;
  top: -8px;
  right: -8px;
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-pill);
  background: color-mix(in srgb, var(--johnbot-bg-surface-raised) 72%, transparent);
  backdrop-filter: blur(8px) saturate(1.1);
  -webkit-backdrop-filter: blur(8px) saturate(1.1);
  opacity: 0;
  scale: 0.9;
  transition:
    opacity var(--johnbot-duration-hover) ease,
    scale var(--johnbot-duration-hover) ease,
    background-color var(--johnbot-duration-hover) ease;
}

.ui-removable-image:hover > .ui-image-remove-button,
.ui-removable-image:focus-within > .ui-image-remove-button {
  opacity: 1;
  scale: 1;
}

@media (hover: none) {
  .ui-image-remove-button {
    opacity: 1;
    scale: 1;
  }
}

:where(.z-badge) {
  width: fit-content;
  height: 22px;
  min-width: 0;
  display: inline-flex;
  overflow: hidden;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  gap: var(--johnbot-space-1);
  border: 1px solid transparent;
  border-radius: var(--johnbot-radius-pill);
  padding: var(--johnbot-space-0-5) var(--johnbot-space-2);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-sm);
  transition:
    border-color var(--johnbot-duration-fast) var(--johnbot-ease-out),
    background-color var(--johnbot-duration-fast) var(--johnbot-ease-out),
    color var(--johnbot-duration-fast) var(--johnbot-ease-out);
  white-space: nowrap;
}

:where(.z-badge) > span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

:where(.z-badge) > svg {
  width: 12px;
  height: 12px;
  flex: 0 0 auto;
  pointer-events: none;
}

:where(.z-badge):has(> [data-icon="inline-start"]) {
  padding-left: var(--johnbot-space-1-5);
}

:where(.z-badge):has(> [data-icon="inline-end"]) {
  padding-right: var(--johnbot-space-1-5);
}

:where(.z-badge-variant-default) {
  background: var(--johnbot-accent);
  color: var(--johnbot-text-primary);
}

:where(.z-badge-variant-secondary) {
  background: var(--johnbot-bg-control);
  color: var(--johnbot-text-secondary);
}

:where(.z-badge-variant-outline) {
  border-color: var(--johnbot-border-strong);
  background: transparent;
  color: var(--johnbot-text-secondary);
}

:where(.z-badge-variant-ghost) {
  background: transparent;
  color: var(--johnbot-text-secondary);
}

:where(.z-badge-variant-link) {
  background: transparent;
  color: var(--johnbot-accent-text);
  text-decoration: underline;
  text-underline-offset: 4px;
}

:where(.z-badge-variant-primary-light) {
  background: var(--johnbot-accent-soft);
  color: var(--johnbot-accent-text);
}

:where(.z-badge-variant-success-light) {
  background: var(--johnbot-success-soft);
  color: var(--johnbot-success);
}

:where(.z-badge-variant-warning-light) {
  background: var(--johnbot-warning-soft);
  color: var(--johnbot-warning);
}

:where(.z-badge-variant-destructive),
:where(.z-badge-variant-destructive-light) {
  background: var(--johnbot-danger-soft);
  color: var(--johnbot-danger);
}

/* The design's "New" chip. Not a --johnbot-success or --johnbot-accent variant: an
 * announcement that something is newly available is neither a report that something
 * succeeded nor an action the user can take. The heavier weight and the open tracking
 * are part of the look, which is why this variant sets them and the others do not. */
:where(.z-badge-variant-new) {
  background: var(--johnbot-badge-new-soft);
  color: var(--johnbot-badge-new);
  font-weight: var(--johnbot-weight-semibold);
  letter-spacing: 0.01em;
}

:where(.z-badge-variant-info-light) {
  background: var(--johnbot-accent-soft);
  color: var(--johnbot-accent-text);
}

:where(.z-badge-variant-primary-outline) {
  border-color: var(--johnbot-border-strong);
  background: transparent;
  color: var(--johnbot-accent-text);
}

:where(.z-badge-variant-success-outline) {
  border-color: var(--johnbot-border-strong);
  background: transparent;
  color: var(--johnbot-success);
}

:where(.z-badge-variant-warning-outline) {
  border-color: var(--johnbot-border-strong);
  background: transparent;
  color: var(--johnbot-warning);
}

:where(.z-badge-variant-destructive-outline) {
  border-color: var(--johnbot-border-strong);
  background: transparent;
  color: var(--johnbot-danger);
}

:where(.z-badge-variant-info-outline) {
  border-color: var(--johnbot-border-strong);
  background: transparent;
  color: var(--johnbot-accent-text);
}

/* The hand-drawn SVGs, which are on a 20-unit viewBox where lucide's is 24. Feeding them
 * --johnbot-icon-stroke raw would paint them 20% heavier than every lucide icon beside
 * them, so it is scaled to the smaller grid instead. These carried 1.35 to 1.6 by hand
 * before, i.e. 1.08 to 1.43 device px against lucide's 1.0. */
:where(.ui-glyph-20) {
  stroke-width: calc(var(--johnbot-icon-stroke) * 20 / 24);
}

:where(.ui-glyph-16) {
  stroke-width: calc(var(--johnbot-icon-stroke) * 16 / 24);
}

:where(.ui-checkbox) {
  position: relative;
  display: inline-flex;
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  flex: 0 0 auto;
}

.ui-checkbox-input {
  position: absolute;
  z-index: 1;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  opacity: 0;
}

.ui-checkbox-visual {
  display: inline-flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-xs);
  background: var(--johnbot-bg-control);
  color: transparent;
}

.ui-checkbox-input:checked + .ui-checkbox-visual {
  border-color: var(--johnbot-accent);
  background: var(--johnbot-accent);
  color: var(--johnbot-text-primary);
}

.ui-checkbox-input:focus-visible + .ui-checkbox-visual {
  outline: 2px solid var(--johnbot-border-focus);
  outline-offset: 2px;
}

.ui-checkbox-visual svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  /* Heavier than --johnbot-icon-stroke deliberately: a tick is a state indicator, and the
   * shared weight paints 0.75 device px inside this 12px box. */
  stroke-width: 2.5;
}

:where(.ui-input, .ui-textarea, .ui-native-select) {
  width: 100%;
  min-width: 0;
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-md);
  outline: 0;
  background: var(--johnbot-bg-control);
  color: var(--johnbot-text-primary);
  font-family: var(--johnbot-font-sans);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
  transition:
    background-color var(--johnbot-duration-hover) ease,
    border-color var(--johnbot-duration-hover) ease,
    box-shadow var(--johnbot-duration-hover) ease;
}

:where(.ui-input, .ui-native-select)[data-size="sm"] {
  height: var(--johnbot-control-sm);
  padding-inline: var(--johnbot-space-2);
}

:where(.ui-input, .ui-native-select)[data-size="md"] {
  height: var(--johnbot-control-md);
  padding-inline: var(--johnbot-space-3);
}

:where(.ui-input, .ui-native-select)[data-size="lg"] {
  height: var(--johnbot-control-lg);
  padding-inline: var(--johnbot-space-3);
}

:where(.ui-textarea) {
  min-height: 76px;
  resize: vertical;
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
}

:where(.ui-textarea)::-webkit-resizer {
  background-color: var(--johnbot-bg-control);
  background-image: linear-gradient(
    135deg,
    transparent 46%,
    var(--johnbot-text-muted) 46% 50%,
    transparent 50% 62%,
    var(--johnbot-text-muted) 62% 66%,
    transparent 66%
  );
  background-repeat: no-repeat;
  background-position: 100% 100%;
  background-size: 50% 50%;
}

:where(.ui-input, .ui-textarea)::placeholder {
  color: var(--johnbot-text-placeholder);
}

/* A focused field gets a neutral border and no ring. */
:where(.ui-input, .ui-textarea, .ui-native-select):focus-visible {
  border-color: var(--johnbot-border-focus);
}

:where(.ui-input, .ui-textarea, .ui-native-select)[aria-invalid="true"] {
  border-color: var(--johnbot-danger);
}

:where(.ui-input, .ui-textarea, .ui-native-select):disabled {
  cursor: not-allowed;
  opacity: 0.42;
}

.ui-select {
  width: 100%;
  min-width: 0;
}

.ui-select-trigger {
  width: 100%;
  min-width: 0;
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-1-5);
  cursor: pointer;
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-md);
  outline: 0;
  background: transparent;
  padding: var(--johnbot-space-2) var(--johnbot-space-2) var(--johnbot-space-2) 10px;
  box-shadow: 0 1px 2px var(--johnbot-shadow-popover-ambient);
  color: var(--johnbot-text-primary);
  font-family: var(--johnbot-font-sans);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
  text-align: left;
  transition:
    background-color var(--johnbot-duration-hover) ease,
    border-color var(--johnbot-duration-hover) ease,
    box-shadow var(--johnbot-duration-hover) ease;
}

.ui-select-trigger[data-size="sm"] {
  height: var(--johnbot-control-md);
  font-size: var(--johnbot-text-sm);
}

.ui-select-trigger[data-size="md"] {
  height: var(--johnbot-control-lg);
}

.ui-select-trigger[data-expanded] {
  border-color: var(--johnbot-border-strong);
  background: var(--johnbot-hover);
}

.ui-select .ui-select-trigger:focus-visible {
  border-color: var(--johnbot-border-focus);
  outline: 0;
}

.ui-select-trigger[data-disabled] {
  cursor: not-allowed;
  opacity: 0.42;
}

.ui-select-trigger[aria-invalid="true"] {
  border-color: var(--johnbot-danger);
  box-shadow: 0 0 0 3px var(--johnbot-danger-soft);
}

@media (hover: hover) and (pointer: fine) {
  .ui-select-trigger:hover:not([data-disabled]) {
    background: var(--johnbot-hover);
  }
}

.ui-select-value {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ui-select-trigger-icon {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  color: var(--johnbot-text-muted);
}

.ui-select-trigger-icon svg {
  width: 100%;
  height: 100%;
}

.ui-select-content {
  z-index: var(--johnbot-layer-popover);
  max-height: 320px;
  min-width: 144px;
  overflow: hidden auto;
  border: 0;
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-surface-raised);
  box-shadow:
    0 4px 6px -1px var(--johnbot-shadow-popover-ambient),
    0 2px 4px -2px var(--johnbot-shadow-popover-ambient),
    0 0 0 1px var(--johnbot-border-strong);
  color: var(--johnbot-text-primary);
  transform-origin: var(--kb-select-content-transform-origin);
  animation: ui-select-content-in var(--johnbot-duration-dialog) var(--johnbot-ease-out) both;
}

.ui-select-listbox {
  margin: 0;
  padding: var(--johnbot-space-1);
  outline: 0;
}

/* The search field stays at the top; only the rows scroll, so Kobalte scrolls the listbox. */
.ui-search-select-content {
  display: flex;
  flex-direction: column;
  width: max(var(--kb-popper-anchor-width, 0px), 240px);
  overflow: hidden;
  transform-origin: var(--kb-popover-content-transform-origin);
}

.ui-search-select-search {
  position: relative;
  flex: 0 0 auto;
  border-bottom: 1px solid var(--johnbot-border);
  padding: var(--johnbot-space-1);
}

.ui-search-select-search > svg {
  position: absolute;
  top: 50%;
  left: var(--johnbot-space-3);
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  color: var(--johnbot-text-muted);
  transform: translateY(-50%);
  pointer-events: none;
}

.ui-search-select-input {
  width: 100%;
  padding-left: var(--johnbot-space-8);
}

.ui-search-select-root {
  min-height: 0;
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
}

.ui-search-select-content .ui-select-listbox {
  min-height: 0;
  flex: 1 1 auto;
  overflow-y: auto;
}

.ui-search-select-empty {
  margin: 0;
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
