}

/* inlined web-client.css */
/* removed cyclic import */
@source "../../";

.web-app {
  min-width: 0;
  height: 100dvh;
  color: var(--johnbot-text-primary);
  background: var(--johnbot-bg-canvas);
}
.web-app-frame {
  min-width: 0;
  height: 100%;
}

/* The browser has no window controls, so the rail starts at the top. */
.web-app-frame > .server-rail {
  padding-top: var(--johnbot-space-3);
}

.web-app-frame > .server-rail::before {
  display: none;
}

.web-app-frame > .server-rail::after {
  top: 0;
}

.web-mobile-navigation {
  display: none;
}

@media (max-width: 720px) {
  .web-app-window {
    --web-mobile-navigation-height: 64px;
  }

  /* The workspace pane shows the page rail at its left, so its pages stay in reach on a phone. */
  .web-app-window:has(> .web-app-frame[data-web-mobile-pane="workspace"]) > .window-rail {
    display: flex;
    padding-bottom: calc(
      var(--web-mobile-navigation-height) +
      env(safe-area-inset-bottom, 0px) +
      var(--johnbot-space-3)
    );
  }

  .web-app-frame {
    /* The workspace pane gives the rail a 56px column, also in the macOS geometry. */
    --server-rail-width: 56px;

    grid-template-columns: minmax(0, 1fr);
    padding-bottom: calc(var(--web-mobile-navigation-height) + env(safe-area-inset-bottom, 0px));
  }

  .web-app-frame[data-web-mobile-pane="conversation"] {
    grid-template-columns: minmax(0, 1fr);
  }

  .web-app-frame[data-web-mobile-pane="conversation"] > .server-rail,
  .web-app-frame[data-web-mobile-pane="conversation"] > .sidebar {
    display: none;
  }

  /* One pane at a time leaves nothing to resize. */
  .web-app-frame > .left-panel-resizer {
    display: none;
  }

  .web-app-frame[data-web-mobile-pane="conversation"] .conversation-panel,
  .web-app-frame[data-web-mobile-pane="conversation"] .diagram-view,
  .web-app-frame[data-web-mobile-pane="conversation"] .remote-compatibility-screen {
    grid-column: 1;
    min-width: 0;
  }

  .web-app-frame[data-web-mobile-pane="workspace"] {
    grid-template-columns: 56px minmax(0, 1fr);
  }

  .web-app-frame[data-web-mobile-pane="workspace"] .conversation-panel,
  .web-app-frame[data-web-mobile-pane="workspace"] .diagram-view,
  .web-app-frame[data-web-mobile-pane="workspace"] .remote-compatibility-screen,
  .web-app-frame[data-web-mobile-pane="workspace"] > .server-connection-workspace {
    display: none;
  }

  .web-app-frame[data-web-mobile-pane="workspace"] > .server-rail {
    display: flex;
    grid-column: 1;
    grid-row: 1;
  }

  .web-app-frame[data-web-mobile-pane="workspace"] > .sidebar {
    display: flex;
    grid-column: 2;
    grid-row: 1;
    width: auto;
  }

  /* The server menu view draws no rail, so the sidebar takes the full width. */
  .web-app-frame[data-web-mobile-pane="workspace"]:not(.app-frame-with-server-rail) {
    grid-template-columns: minmax(0, 1fr);
  }

  .web-app-frame[data-web-mobile-pane="workspace"]:not(.app-frame-with-server-rail) > .sidebar {
    grid-column: 1;
  }

  .web-mobile-navigation {
    position: fixed;
    z-index: var(--johnbot-layer-popover);
    right: 0;
    bottom: 0;
    left: 0;
    display: flex;
    min-height: var(--web-mobile-navigation-height);
    align-items: center;
    justify-content: center;
    border-top: 1px solid var(--johnbot-border);
    background: color-mix(in srgb, var(--johnbot-bg-sidebar) 94%, transparent);
    padding: var(--johnbot-space-2) max(var(--johnbot-space-3), env(safe-area-inset-left, 0px))
      calc(var(--johnbot-space-2) + env(safe-area-inset-bottom, 0px))
      max(var(--johnbot-space-3), env(safe-area-inset-right, 0px));
    -webkit-backdrop-filter: blur(18px);
    backdrop-filter: blur(18px);
  }

  .web-mobile-navigation-list {
    display: grid;
    width: min(100%, 360px);
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: var(--johnbot-space-1);
  }

  .web-mobile-navigation-button {
    display: flex;
    min-height: 44px;
    align-items: center;
    justify-content: center;
    gap: var(--johnbot-space-2);
    border: 1px solid transparent;
    border-radius: var(--johnbot-radius-lg);
    color: var(--johnbot-text-muted);
    font-size: var(--johnbot-text-sm);
    font-weight: var(--johnbot-weight-semibold);
  }

  .web-mobile-navigation-button > svg {
    width: var(--johnbot-icon-md);
    height: var(--johnbot-icon-md);
    stroke-width: var(--johnbot-icon-stroke);
  }

  .web-mobile-navigation-button[data-active="true"] {
    border-color: var(--johnbot-border);
    background: var(--johnbot-bg-control);
    color: var(--johnbot-text-primary);
  }

  .web-app-frame[data-web-mobile-pane="conversation"] .conversation-header {
    padding-inline: var(--johnbot-space-2);
  }

  .web-app-frame[data-web-mobile-pane="conversation"] .conversation-header-actions {
    gap: var(--johnbot-space-1);
  }

  .web-app-frame[data-web-mobile-pane="conversation"] .conversation-header .provider-model-trigger {
    max-width: 132px;
  }

  .web-app-frame[data-web-mobile-pane="conversation"] .conversation-panel:has(.settings-panel) .settings-panel {
    width: 100%;
  }

  .web-app-frame[data-web-mobile-pane="conversation"] .conversation-panel.browser-panel-active {
    padding-right: 0;
  }

  .web-app-frame[data-web-mobile-pane="conversation"] .browser-panel {
    width: 100%;
    max-width: 100%;
  }

  /*
   * A phone has no room beside the chat. An open pane takes the full width under the chat header,
   * which keeps its panel button, and the tab row is a second row. A maximized pane covers the chat
   * header, as on desktop.
   */
  .web-app-frame[data-web-mobile-pane="conversation"]
    .side-panel-docked:not(.side-panel-maximized)
    > .conversation-header {
    width: 100%;
  }

  .web-app-frame[data-web-mobile-pane="conversation"]
    .side-panel-docked
    > :is(.conversation-scroll, .composer-wrap, .unread-messages-banner, .chat-search) {
    visibility: hidden;
  }

  .web-app-frame[data-web-mobile-pane="conversation"] .side-panel-docked > .side-panel-header {
    width: 100%;
  }

  .web-app-frame[data-web-mobile-pane="conversation"]
    .side-panel-docked:not(.side-panel-maximized)
    > .side-panel-header {
    top: var(--left-header-height, 38px);
  }

  .web-app-frame[data-web-mobile-pane="conversation"] .side-panel-docked > .side-panel-header::before,
  .web-app-frame[data-web-mobile-pane="conversation"] .side-panel-docked .right-panel-resizer {
    display: none;
  }

  .web-app-frame[data-web-mobile-pane="conversation"]
    .side-panel-docked:not(.side-panel-maximized)
    > :is(.browser-panel, .settings-panel) {
    top: calc(2 * var(--left-header-height, 38px));
  }

  /* The pane list has no tabs, so it starts under the chat header. */
  .web-app-frame[data-web-mobile-pane="conversation"] .side-panel-docked:has(> .side-panel-empty) > .side-panel-header {
    display: none;
  }

  .web-app-frame[data-web-mobile-pane="conversation"] .side-panel-docked:has(> .side-panel-empty) > .side-panel-empty {
    top: var(--left-header-height, 38px);
  }

  .web-app .join-server-backdrop {
    padding: var(--johnbot-space-3);
  }

  .web-app .join-server-content {
    padding: var(--johnbot-space-6) var(--johnbot-space-4);
  }

  .web-app .ui-dialog-content {
    max-width: calc(100vw - 24px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .web-mobile-navigation-button {
    transition: none;
  }
}

/* Takes the conversation-panel grid cell, so it follows the same desktop and mobile placement. */
.web-connect.conversation-panel {
  display: grid;
  place-items: center;
  overflow-y: auto;
  padding: var(--johnbot-space-8) var(--johnbot-space-4);
}

.web-connect-card {
  display: flex;
  width: min(420px, 100%);
  flex-direction: column;
  gap: var(--johnbot-space-6);
}

.web-connect-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--johnbot-space-2);
  text-align: center;
}

.web-connect-header .ui-heading {
  font-size: var(--johnbot-text-3xl);
  font-weight: var(--johnbot-weight-bold);
  line-height: var(--johnbot-leading-3xl);
}

.web-connect-header .ui-text {
  max-width: 340px;
  line-height: var(--johnbot-leading-sm);
}

.web-connect-logo {
  --app-logo-background: var(--johnbot-surface-light);
  width: 64px;
  height: 64px;
  flex: 0 0 auto;
  margin-bottom: var(--johnbot-space-4);
  border-radius: var(--johnbot-radius-xl);
  box-shadow:
    0 12px 28px var(--johnbot-shadow-dialog),
    inset 0 1px 0 var(--johnbot-border-strong);
}

.web-connect-steps {
  display: grid;
  margin: 0;
  padding: var(--johnbot-space-1);
  list-style: none;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-surface);
}

.web-connect-steps li {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
}

.web-connect-steps li + li {
  border-top: 1px solid var(--johnbot-border);
}

.web-connect-steps .ui-text {
  min-width: 0;
  overflow-wrap: anywhere;
}

.web-connect-step-number {
  display: grid;
  width: var(--johnbot-control-xs);
  height: var(--johnbot-control-xs);
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-control-active);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-semibold);
}

.web-connect-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--johnbot-space-3);
}

/* Side by side; the buttons stack when the card is too narrow for both labels. */
.web-connect-primary-actions {
  display: flex;
  width: 100%;
  flex-wrap: wrap;
  gap: var(--johnbot-space-2);
}

.web-connect-primary-actions .ui-button {
  min-width: 160px;
  flex: 1 1 0;
}

/* The public site sets `a { color: inherit }`, which beats the zero-specificity button colour. */
.web-connect-download.ui-button-variant-default,
.web-connect-download.ui-button-variant-default:hover {
  color: var(--johnbot-text-on-light);
}

.web-connect-download.ui-button-variant-outline {
  color: var(--johnbot-text-secondary);
}

/* The same hover query as the shared outline button, so a tap leaves no hover colour. */
@media (hover: hover) and (pointer: fine) and (min-width: 601px) {
  .web-connect-download.ui-button-variant-outline:hover {
    color: var(--johnbot-text-primary);
  }
}

.web-connect-hosted.ui-button {
  width: 100%;
}

.web-connect-refresh.ui-button {
  color: var(--johnbot-text-muted);
}

.web-connect-hosted.ui-button svg,
.web-connect-actions .ui-button svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  flex: 0 0 auto;
  stroke-width: var(--johnbot-icon-stroke);
}

.web-connect-refresh.ui-button svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

/* inlined preview.css */
/* removed cyclic import */
@source "../";

.johnbot-playground-root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--johnbot-bg-canvas);
}

.johnbot-playground-loading {
  width: 100%;
  height: 100%;
  background: var(--johnbot-bg-canvas);
}

.johnbot-playground-root .unread-messages-banner {
  display: none;
}

@media (max-width: 640px) {
  .johnbot-playground-root .app-frame,
  .johnbot-playground-root .app-frame-with-server-rail {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: 68px minmax(0, 1fr);
  }

  .johnbot-playground-root .server-rail,
  .johnbot-playground-root .left-panel-resizer,
  .johnbot-playground-root .sidebar-topbar,
  .johnbot-playground-root .sidebar-search-wrap,
  .johnbot-playground-root .sidebar-list-context-trigger,
  .johnbot-playground-root .sidebar-chat-group > header {
    display: none;
  }

  .johnbot-playground-root .sidebar {
    grid-column: 1;
    grid-row: 1;
    flex-direction: row;
    border-right: 0;
    border-bottom: 1px solid var(--johnbot-border);
  }

  .johnbot-playground-root .agent-list,
  .johnbot-playground-root .sidebar-compact .agent-list {
    display: flex;
    overflow-x: auto;
    overflow-y: hidden;
    align-items: center;
    justify-content: center;
    gap: var(--johnbot-space-1-5);
    padding: var(--johnbot-space-2) var(--johnbot-space-3);
  }

  /* Every wrapper between the list and the rows becomes one row of avatars. */
  .johnbot-playground-root .agent-list-content,
  .johnbot-playground-root .sidebar-chat-group,
  .johnbot-playground-root .sidebar-section-collapse,
  .johnbot-playground-root .sidebar-section-body {
    display: flex;
    align-items: center;
    gap: var(--johnbot-space-1-5);
    margin: 0;
  }

  .johnbot-playground-root .agent-row,
  .johnbot-playground-root .sidebar-compact .agent-row {
    width: 48px;
    height: 48px;
    flex: 0 0 48px;
    margin: 0;
    padding: 6px;
  }

  .johnbot-playground-root .sidebar-compact .agent-row-avatar {
    transform: none;
  }

  .johnbot-playground-root .agent-row-copy {
    display: none;
  }

  /* The chat is inside the panes wrapper, which the frame puts in the first row. */
  .johnbot-playground-root .app-frame-panes,
  .johnbot-playground-root .conversation-panel,
  .johnbot-playground-root .app-frame-with-server-rail .conversation-panel {
    grid-column: 1;
    grid-row: 2;
  }
}

/* inlined primitives.css */
:where(.ui-text, .ui-heading) {
