    opacity var(--johnbot-duration-hover) ease;
}

.ui-switch[data-size="sm"] {
  --ui-switch-thumb-size: var(--johnbot-switch-sm-thumb);
  --ui-switch-inset: var(--johnbot-switch-sm-inset);
  --ui-switch-travel: calc(var(--johnbot-switch-sm-width) - var(--ui-switch-thumb-size) - (var(--ui-switch-inset) * 2));
  width: var(--johnbot-switch-sm-width);
  height: var(--johnbot-switch-sm-height);
}

.ui-switch[data-checked] {
