}

.ui-switch-control {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  overflow: hidden;
  border-radius: inherit;
  cursor: pointer;
}

.ui-switch-control[data-dragging] {
  cursor: grabbing;
}

.ui-switch-thumb {
  position: absolute;
  top: 50%;
  left: 0;
  width: var(--ui-switch-thumb-size);
  height: var(--ui-switch-thumb-size);
  display: block;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-text-primary);
  box-shadow: 0 1px 2px var(--johnbot-shadow-ring);
  transform: translate3d(
      calc(var(--ui-switch-inset) + (var(--ui-switch-position, 0) * var(--ui-switch-travel))),
      -50%,
      0
    )
    scale(var(--ui-switch-scale-x, 1), var(--ui-switch-scale-y, 1));
  transform-origin: center;
  will-change: transform;
  transition: background-color var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.ui-switch-thumb[data-checked] {
  background: var(--johnbot-text-on-light);
}

.ui-slider-field {
  width: 100%;
