  gap: var(--johnbot-space-1-5);
}

.ui-slider-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--johnbot-space-3);
}

.ui-slider-label {
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-md);
}

.ui-slider-value {
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
  line-height: var(--johnbot-leading-sm);
}

.ui-slider-description {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.ui-slider-track {
  position: relative;
  height: 4px;
  margin-block: var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-border-strong);
  cursor: pointer;
}

/* The drawn track is 4px high, too thin to hit. A press on this area belongs to the track, so it
   still sets the value from the pointer position and starts a drag. */
.ui-slider-track::before {
  content: "";
  position: absolute;
  inset: -10px 0;
}

/* Kobalte places the fill and the thumb with inline `left`/`right` percentages. */
.ui-slider-fill {
  position: absolute;
  height: 100%;
  border-radius: inherit;
  background: var(--johnbot-text-secondary);
}

/* Kobalte owns the inline `transform` that centres the thumb on its value, so the vertical centring
   uses `top` instead. */
.ui-slider-thumb {
  top: calc(50% - (var(--johnbot-switch-thumb) / 2));
  width: var(--johnbot-switch-thumb);
  height: var(--johnbot-switch-thumb);
  display: block;
  border-radius: var(--johnbot-radius-pill);
  outline: none;
  background: var(--johnbot-text-primary);
  box-shadow: 0 1px 2px var(--johnbot-shadow-ring);
  cursor: grab;
}

.ui-slider-thumb:focus-visible {
  box-shadow: var(--johnbot-focus-ring);
}

.ui-slider-thumb[data-dragging] {
  cursor: grabbing;
}

/* The seek slider draws its picture on the track; the playhead shows on hover, focus and drag. */
.ui-seek-slider {
  display: flex;
  touch-action: none;
}

.ui-seek-slider-track {
  position: relative;
  display: flex;
  align-items: center;
  cursor: pointer;
}

.ui-seek-slider-picture {
