}

.ui-seek-slider-thumb {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 2px;
  display: block;
  border-radius: var(--johnbot-radius-pill);
  outline: none;
  background: var(--johnbot-text-primary);
  opacity: 0;
}

.ui-seek-slider-track:hover .ui-seek-slider-thumb,
.ui-seek-slider-thumb:focus-visible,
.ui-seek-slider-thumb[data-dragging] {
  opacity: 1;
}

.ui-seek-slider-thumb:focus-visible {
  box-shadow: var(--johnbot-focus-ring);
}

.ui-slider-field[data-disabled] {
  opacity: 0.5;
}

.ui-slider-field[data-disabled] .ui-slider-track,
.ui-slider-field[data-disabled] .ui-slider-thumb {
  cursor: not-allowed;
}

.ui-switch[data-disabled] {
