  position: relative;
  z-index: 3;
  min-width: 0;
  display: inline-flex;
  align-items: center;
  transform: translate3d(0, 0, 0) scale(1);
  transform-origin: center;
  transition:
    color var(--johnbot-duration-normal) var(--johnbot-ease-out),
    filter var(--johnbot-duration-slow) var(--johnbot-ease-out),
    opacity var(--johnbot-duration-island-content) cubic-bezier(0.22, 1.08, 0.36, 1),
    transform var(--johnbot-duration-island-content) cubic-bezier(0.22, 1.08, 0.36, 1);
}

/* The compact content blurs a little while it moves with the surface, as much as the move is large.
   The blur bridges the old and the new place, and a transition keeps it interruptible. */
.dynamic-island-shell[data-compact-resize] .dynamic-island-ear-content {
  filter: blur(calc(0.4px * var(--dynamic-island-compact-motion, 1)));
}

.dynamic-island-hover-content {
  min-width: 0;
  display: inline-flex;
  align-items: center;
  transform: translate3d(0, 0, 0) scale(1);
  transform-origin: center;
}

.dynamic-island-status .dynamic-island-hover-leading {
  width: 100%;
}

.dynamic-island-toggle:hover .dynamic-island-ear,
.dynamic-island-toggle:focus-visible .dynamic-island-ear {
  color: var(--johnbot-text-primary);
}

.dynamic-island-trailing-content {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  justify-content: center;
}

.dynamic-island-trailing-compact {
  position: absolute;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition:
    opacity var(--johnbot-duration-island-content) cubic-bezier(0.22, 1.08, 0.36, 1),
    transform var(--johnbot-duration-island-content) cubic-bezier(0.22, 1.08, 0.36, 1);
}

.dynamic-island-trailing-compact {
  opacity: 1;
  filter: blur(0);
  transform: translateY(0) scale(1);
}

.dynamic-island-status .dynamic-island-trailing-compact {
  right: auto;
  left: 0;
  justify-content: flex-start;
  transform-origin: left center;
}

.dynamic-island-external.dynamic-island-status .dynamic-island-trailing-compact {
  right: 0;
  left: auto;
  justify-content: flex-end;
  transform-origin: right center;
}

/* The hidden badge moves onto the end of a panel row, so it must not take a press from a row button. */
.dynamic-island[data-layout-state="expanded"] .dynamic-island-trailing-compact {
  pointer-events: none;
  opacity: 0;
  filter: none;
  transform: scale(0.92);
  transition-duration: var(--johnbot-duration-island-content-exit);
  transition-timing-function: var(--dynamic-island-shared-ease);
}

.dynamic-island-panel {
  position: relative;
  z-index: 1;
  width: 100%;
  padding: var(--johnbot-space-2) var(--johnbot-space-4) var(--johnbot-space-4);
}

.dynamic-island-panel[data-phase="leaving"] {
  position: absolute;
  top: var(--dynamic-island-notch-height);
  left: 50%;
  transform: translateX(-50%);
}

.dynamic-island-panel[data-phase="exiting"],
.dynamic-island-panel[data-phase="leaving"] {
  pointer-events: none;
}

.dynamic-island-panel[data-phase="leaving"] {
  width: min(var(--dynamic-island-expanded-width), calc(100vw - var(--johnbot-space-6)));
}

.dynamic-island-content {
  opacity: 1;
  filter: none;
  transform: scale(1);
  transform-origin: top center;
}

/* The shell and content use separate, asymmetric springs. */
.dynamic-island[data-shared-leading="true"] .dynamic-island-ear-leading .dynamic-island-ear-content {
  opacity: 1;
  filter: none;
  transition:
    color var(--johnbot-duration-normal) var(--johnbot-ease-out),
    opacity var(--johnbot-duration-island-content-exit) var(--dynamic-island-shared-ease);
}

.dynamic-island:not([data-shared-leading="true"])[data-layout-state="expanded"]
  .dynamic-island-ear-leading
  .dynamic-island-ear-content {
  opacity: 0;
  filter: none;
  transform: scale(0.92);
  transition-duration:
    var(--johnbot-duration-normal), var(--johnbot-duration-island-content-exit),
    var(--johnbot-duration-island-content-exit);
  transition-timing-function:
    var(--johnbot-ease-out), var(--dynamic-island-shared-ease), var(--dynamic-island-shared-ease);
}

.dynamic-island[data-layout-state="expanded"] .dynamic-island-ear-trailing .dynamic-island-ear-content {
  opacity: 1;
  filter: none;
  transform: none;
}

.dynamic-island-status .dynamic-island-trailing-compact {
  transform: scale(1);
  transition: opacity var(--johnbot-duration-island-content) var(--dynamic-island-shared-ease);
}

.dynamic-island-status[data-layout-state="expanded"] .dynamic-island-trailing-compact {
  opacity: 0;
  transform: scale(1);
}

.dynamic-island-status .dynamic-island-trailing-content {
  transform-origin: left center;
}

.dynamic-island-status .dynamic-island-trailing-compact,
.dynamic-island-status .dynamic-island-hover-trailing,
.dynamic-island-status .dynamic-island-mode-swap[data-island-mode-slot="compact-trailing"] {
  width: max-content;
}

.dynamic-island-external.dynamic-island-status .dynamic-island-trailing-content {
  transform-origin: right center;
}

.dynamic-island-panel-wide {
  --dynamic-island-expanded-width: 590px;
}

.dynamic-island-idle .dynamic-island-ear-trailing {
  color: var(--johnbot-text-primary);
  transition: none;
}

/* Beside a notch, the logo and the greeting keep the same inset from the outer edges. Only the
   space between them changes with the island width. */
.dynamic-island.dynamic-island-idle:not(.dynamic-island-external) .dynamic-island-ear-leading {
  justify-content: flex-start;
  padding-right: 0;
  padding-left: var(--johnbot-space-4);
}

.dynamic-island.dynamic-island-idle:not(.dynamic-island-external) .dynamic-island-ear-trailing {
  justify-content: flex-end;
  padding-right: var(--johnbot-space-4);
  padding-left: 0;
}

.dynamic-island-hover-zone {
  position: absolute;
  top: calc(-1 * var(--dynamic-island-hover-hit-top));
  left: 50%;
  display: none;
  /* Acquiring the island takes no more room than the island shows: an ear reads as part of the
     notch, so a wider zone would only take the menu bar beside it away from the mouse. The band
     below is `--dynamic-island-hover-hit-bottom`, which stays inside the menu bar - taller than the
     notch on every notched MacBook - rather than reaching into the window under it. The retention
     zone below is the generous one, and it only applies once the pointer is already on the
     island. */
  width: min(var(--dynamic-island-compact-width), calc(100vw - var(--johnbot-space-6)));
  height: calc(
    var(--dynamic-island-notch-height) +
    var(--dynamic-island-hover-hit-top) +
    var(--dynamic-island-hover-hit-bottom)
  );
  pointer-events: auto;
  transform: translateX(-50%);
}

.dynamic-island[data-layout-state="compact"] > .dynamic-island-hover-zone {
  display: block;
}

.dynamic-island[data-layout-state="compact"][data-hovered="true"] > .dynamic-island-hover-zone {
  width: min(
    calc(
      var(--dynamic-island-compact-width) +
      var(--dynamic-island-hover-width-growth) +
      var(--dynamic-island-hover-retention-inline-growth)
    ),
    calc(100vw - var(--johnbot-space-6))
  );
  height: calc(
    var(--dynamic-island-notch-height) +
    var(--dynamic-island-hover-height-growth) +
    var(--dynamic-island-hover-hit-top) +
    var(--dynamic-island-hover-retention-bottom)
  );
}

.dynamic-island-status:not(.dynamic-island-external) .dynamic-island-ear-leading {
  justify-content: flex-start;
  padding-right: 0;
  padding-left: 12px;
}

.dynamic-island-status:not(.dynamic-island-external) .dynamic-island-ear-trailing {
  justify-content: flex-end;
  padding-right: 12px;
  padding-left: 0;
}

.dynamic-island-status:not(.dynamic-island-external) .dynamic-island-trailing-compact {
  right: 0;
  left: auto;
  justify-content: flex-end;
  transform-origin: right center;
}

.dynamic-island-status:not(.dynamic-island-external) .dynamic-island-trailing-content {
  transform-origin: right center;
}

.johnbot-dynamic-island[data-layout-state="expanded"] .dynamic-island-panel,
.johnbot-dynamic-island .dynamic-island-panel[data-phase="exiting"],
.johnbot-dynamic-island .dynamic-island-panel[data-phase="leaving"] {
  padding: 14px calc(var(--dynamic-island-expanded-shoulder-size) + 20px) 20px;
}

.dynamic-island-external.johnbot-dynamic-island[data-layout-state="expanded"] .dynamic-island-panel,
.dynamic-island-external.johnbot-dynamic-island .dynamic-island-panel[data-phase="exiting"],
.dynamic-island-external.johnbot-dynamic-island .dynamic-island-panel[data-phase="leaving"] {
  padding: 14px 20px 20px;
}

.johnbot-dynamic-island.dynamic-island-working[data-layout-state="expanded"] .dynamic-island-panel,
.johnbot-dynamic-island.dynamic-island-working .dynamic-island-panel[data-phase="exiting"],
.johnbot-dynamic-island.dynamic-island-working .dynamic-island-panel[data-phase="leaving"] {
  padding-bottom: 14px;
}

/* External displays use a detached capsule because there is no physical notch to join. */
.dynamic-island-external {
  --dynamic-island-notch-width: 16px;
  --dynamic-island-compact-width: 212px;
  --dynamic-island-external-inline-inset: 6px;
  padding-top: var(--dynamic-island-hover-hit-top);
}

.dynamic-island-external .dynamic-island-shoulder {
  display: none;
}

.dynamic-island-external .dynamic-island-silhouette {
  border-radius: var(--dynamic-island-external-compact-radius);
  background: var(--johnbot-bg-notch);
  box-shadow: inset 0 -1px 0 var(--johnbot-shadow-ring);
}

.dynamic-island-external .dynamic-island-silhouette-body {
  display: none;
}

.dynamic-island-external[data-layout-state="expanded"] .dynamic-island-silhouette {
  border-radius: var(--dynamic-island-external-expanded-radius);
}

/* Keyboard focus on the toggle draws the shared focus ring on the island outline. The shell clips
   its content, so the ring is inset: a ring outside the outline would be cut off. */
.dynamic-island-shell:has(.dynamic-island-toggle:focus-visible) .dynamic-island-silhouette-body,
.dynamic-island-external .dynamic-island-shell:has(.dynamic-island-toggle:focus-visible) .dynamic-island-silhouette {
  box-shadow:
    inset var(--johnbot-focus-ring),
    inset 0 -1px 0 var(--johnbot-shadow-ring);
}

.dynamic-island-external > .dynamic-island-hover-zone {
  top: 0;
}

.dynamic-island-external .dynamic-island-toggle {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  padding-inline: var(--dynamic-island-external-inline-inset);
}

.dynamic-island-external .dynamic-island-notch-safe-zone {
  display: none;
}

.dynamic-island-external .dynamic-island-ear-leading {
  position: relative;
  left: 0;
  justify-content: flex-start;
  padding-right: 0;
}

.dynamic-island-external .dynamic-island-ear-trailing {
  justify-content: flex-end;
  padding-left: 0;
}

.dynamic-island-external.dynamic-island-panel-wide {
  --dynamic-island-expanded-width: 552px;
}

.dynamic-island-external.dynamic-island-status .dynamic-island-ear-leading {
  left: 0;
  justify-content: flex-start;
  padding-right: 0;
  padding-left: 0;
}

/* === from: @johnbot/ui/features/dynamic-island/dynamic-island-surface.css === */
html:has(.dynamic-island-surface),
body:has(.dynamic-island-surface),
#root:has(.dynamic-island-surface) {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
}

.dynamic-island-surface {
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  background: transparent;
  color: var(--johnbot-text-primary);
  font-family: var(--johnbot-font-sans);
  user-select: none;
}

.johnbot-dynamic-island-transition-root {
  display: contents;
}

.dynamic-island-mode-swap {
  position: relative;
  min-width: 0;
  display: inline-grid;
  align-items: center;
}

.dynamic-island-mode-swap-block {
  width: 100%;
  display: grid;
  align-items: stretch;
}

.dynamic-island-mode-layer {
  min-width: 0;
  display: inline-flex;
  grid-area: 1 / 1;
  align-items: center;
  transform-origin: center;
}

.dynamic-island-mode-swap-block > .dynamic-island-mode-layer {
  width: 100%;
  display: block;
}

.dynamic-island-mode-layer-outgoing {
  position: absolute;
  z-index: 1;
  top: 0;
  pointer-events: none;
}

.dynamic-island-mode-swap[data-island-mode-slot="compact-leading"] > .dynamic-island-mode-layer-outgoing {
  right: 0;
}

.dynamic-island-external
  .dynamic-island-mode-swap[data-island-mode-slot="compact-leading"]
  > .dynamic-island-mode-layer-outgoing {
  right: auto;
  left: 0;
}

.dynamic-island-mode-swap[data-island-mode-slot="compact-trailing"] > .dynamic-island-mode-layer-outgoing {
  left: 0;
}

.dynamic-island-external
  .dynamic-island-mode-swap[data-island-mode-slot="compact-trailing"]
  > .dynamic-island-mode-layer-outgoing {
  right: 0;
  left: auto;
}

.dynamic-island-mode-swap-block > .dynamic-island-mode-layer-outgoing {
  inset: 0;
}

.johnbot-dynamic-island-transition-root[data-mode-transitioning="true"] .dynamic-island-mode-layer {
  will-change: opacity, transform;
}

.johnbot-dynamic-island-transition-root[data-mode-transitioning="true"]
  .dynamic-island-mode-layer[data-island-mode-layer="incoming"] {
  opacity: 0;
  transform: none;
}

.johnbot-dynamic-island-transition-root[data-mode-transitioning="true"]
  .dynamic-island-mode-swap[data-island-mode-slot="expanded"]
  > .dynamic-island-mode-layer[data-island-mode-layer="incoming"] {
  transform: scale(0.965);
}

.johnbot-dynamic-island-transition-root[data-mode-transitioning="true"]
  .dynamic-island[data-layout-state="expanded"]
  .dynamic-island-mode-swap[data-island-mode-slot="compact-leading"]
  > .dynamic-island-mode-layer[data-island-mode-layer="incoming"] {
  transform: none;
}

.johnbot-dynamic-island-transition-root[data-mode-transitioning="true"]
  .dynamic-island-mode-layer[data-island-mode-layer="incoming"]
  [data-island-motion-content] {
  filter: blur(4px);
}

.dynamic-island-surface-anchor {
  width: fit-content;
  height: fit-content;
  min-inline-size: 0;
  margin: 0;
  padding: 0;
  border: 0;
  pointer-events: none;
}

.dynamic-island-surface-logo {
  width: 100%;
  height: 100%;
  flex: 0 0 auto;
  border-radius: var(--johnbot-radius-xs);
  transition:
    border-radius var(--johnbot-duration-slow) var(--johnbot-ease-out),
    filter var(--johnbot-duration-slow) var(--johnbot-ease-out),
    scale var(--johnbot-duration-slow) var(--johnbot-ease-out);
}

/* While the island moves, the logo blurs more than the ear around it, so it reads as a shape in
   motion, gets a little smaller, and half closes its eyes. All three follow the size of the move
   (`--dynamic-island-compact-motion`, 0 to 1): a slow slider step barely changes the logo, and a
   large move changes it in full. A large move also rounds its corners a little. These are
   transitions, not a keyframe pulse, so they are interruptible and a drag keeps one steady state.
   The logo is sharp and square again as the island settles. The squint scales the eye group, not
   the eyes, so the blink keeps running. */
.dynamic-island-shell[data-compact-resize] .dynamic-island-surface-logo {
  --app-logo-eye-squint: calc(1 - 0.45 * var(--dynamic-island-compact-motion, 1));
  filter: blur(calc(0.8px * var(--dynamic-island-compact-motion, 1)));
  scale: calc(1 - 0.03 * var(--dynamic-island-compact-motion, 1));
}

.dynamic-island-shell[data-compact-motion="large"] .dynamic-island-surface-logo {
  border-radius: var(--johnbot-radius-sm);
}

.dynamic-island-external.dynamic-island-idle .dynamic-island-surface-logo {
  transform: translateX(4px);
}

.dynamic-island-surface-leading-anchor {
  position: relative;
  width: 20px;
  height: 20px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 20px;
}

/* The idle greeting is a little larger than the 14px trailing slot of a status. */
.dynamic-island-idle .dynamic-island-trailing-content {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
}

.dynamic-island-surface-idle-greeting {
  position: relative;
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  display: block;
  flex: 0 0 auto;
  font-family: "Apple Color Emoji", "Segoe UI Emoji", sans-serif;
  font-size: var(--johnbot-text-xl);
  line-height: 1;
  transition:
    opacity var(--johnbot-duration-slow) var(--johnbot-ease-out),
    scale var(--johnbot-duration-slow) var(--johnbot-ease-out);
}

/* While the island moves, the greeting gets a little fainter, as much as the move is large. When
   a large move lands, it pops: a short overshoot with a small tilt each way, then rest. A small move,
   such as one slow slider step, has no pop, so a slow drag stays quiet. */
.dynamic-island-shell[data-compact-resize] .dynamic-island-surface-idle-greeting {
  opacity: calc(1 - 0.1 * var(--dynamic-island-compact-motion, 1));
}

.dynamic-island-shell[data-compact-settled] .dynamic-island-surface-idle-greeting {
  animation: dynamic-island-greeting-pop 600ms var(--dynamic-island-greeting-pop-ease);
}

/* One damped spring (damping 0.5, response 0.4s, with a push), sampled, so the pop is one smooth
   overshoot to about 1.01 and back, not a curve per keyframe. The tilt rides the same spring. */
.dynamic-island-shell {
  --dynamic-island-greeting-pop-ease: linear(
    0,
    0.571 4.2%,
    1.01 8.3%,
    1.306 12.5%,
    1.467 16.7%,
    1.517 20.8%,
    1.485 25.0%,
    1.403 29.2%,
    1.297 33.3%,
    1.188 37.5%,
    1.09 41.7%,
    1.013 45.8%,
    0.96 50.0%,
    0.928 54.2%,
    0.916 58.3%,
    0.919 62.5%,
    0.931 66.7%,
    0.947 70.8%,
    0.965 75.0%,
    0.982 79.2%,
    0.995 83.3%,
    1.005 87.5%,
    1.011 91.7%,
    1.013 95.8%,
    1
  );
}

@keyframes dynamic-island-greeting-pop {
  from {
    opacity: 0.9;
    scale: 0.98;
    rotate: -1deg;
  }

  to {
    opacity: 1;
    scale: 1;
    rotate: 0deg;
  }
}

/* One greeting hands over to the next: the old one shrinks a little and blurs as it fades, and the
   new one comes out of the blur, so the two read as one change. */
.dynamic-island-surface-idle-greeting-layer {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  opacity: 0;
  transition:
    opacity 600ms var(--johnbot-ease-in-out),
    scale 650ms var(--johnbot-ease-in-out),
    filter 600ms var(--johnbot-ease-in-out);
}

@media (prefers-reduced-motion: no-preference) {
  .dynamic-island-surface-idle-greeting-layer:not([data-active]) {
    scale: 0.88;
    filter: blur(2px);
  }
}

/* Mirrors the logo: its 20px box sits 10px from the left edge, this 16px box sits 6px from the right. */
.dynamic-island-external.dynamic-island-idle .dynamic-island-surface-idle-greeting-layer {
  transform: translateX(-6px);
}

.dynamic-island-surface-idle-greeting[data-active-slot="0"] .dynamic-island-surface-idle-greeting-layer:first-child,
.dynamic-island-surface-idle-greeting[data-active-slot="1"] .dynamic-island-surface-idle-greeting-layer:last-child {
  opacity: 1;
}

/* Each greeting is a small 3D card with a front and a back face. `idle-greeting-motion.ts` moves it
   once as it shows: it turns the wave, the smile and the raised hands, and lights up and twinkles
   each sparkle. Reduce motion turns the motions off, so the front face stays. */
.dynamic-island-surface-idle-greeting-layer {
  perspective: 60px;
}

.dynamic-island-surface-idle-greeting-card {
  display: grid;
  place-items: center;
  transform-style: preserve-3d;
}

.dynamic-island-surface-idle-greeting-face {
  grid-area: 1 / 1;
  backface-visibility: hidden;
}

.dynamic-island-surface-idle-greeting-face-back {
  transform: rotateY(180deg);
}

/* Each copy of the sparkles glyph shows one star, through a star-shaped mask a little larger than the
   star. The transform origin is the star's centre, so it twinkles in place. */
.dynamic-island-surface-idle-greeting-face:has(.dynamic-island-surface-idle-greeting-sparkle) {
  display: grid;
}

.dynamic-island-surface-idle-greeting-sparkle {
  grid-area: 1 / 1;
  mask-repeat: no-repeat;
  mask-size: 100% 100%;
}

.dynamic-island-surface-idle-greeting-sparkle-large {
  transform-origin: 60% 48%;
  mask-image: url("data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%20100%20100'%3E%3Cpath%20d='M60%207.9Q70.3%2036.0%2094.2%2048Q70.3%2060.0%2060%2088.1Q49.7%2060.0%2025.8%2048Q49.7%2036.0%2060%207.9Z'/%3E%3C/svg%3E");
}

.dynamic-island-surface-idle-greeting-sparkle-upper {
  transform-origin: 24% 28%;
  mask-image: url("data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%20100%20100'%3E%3Cpath%20d='M24%207.4Q28.2%2021.8%2038.2%2028Q28.2%2034.2%2024%2048.6Q19.8%2034.2%209.8%2028Q19.8%2021.8%2024%207.4Z'/%3E%3C/svg%3E");
}

.dynamic-island-surface-idle-greeting-sparkle-lower {
  transform-origin: 36% 70%;
  mask-image: url("data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%20100%20100'%3E%3Cpath%20d='M36%2051.1Q40.8%2064.3%2051.9%2070Q40.8%2075.7%2036%2088.9Q31.2%2075.7%2020.1%2070Q31.2%2064.3%2036%2051.1Z'/%3E%3C/svg%3E");
}

.dynamic-island-surface-avatar-stack {
  position: absolute;
  top: 0;
  left: 0;
