.dynamic-island[data-layout-state="expanded"] .dynamic-island-surface-compact-name {
  opacity: 0;
}

.dynamic-island-surface-leading-anchor .dynamic-island-surface-avatar {
  width: 100%;
  height: 100%;
}

.dynamic-island-surface-avatar-stack .dynamic-island-surface-avatar {
