}

.dynamic-island-working[data-state="expanded"] .dynamic-island-surface-avatar-stack > :nth-child(2) {
  transform: translate3d(-14px, 28.75px, 0);
}

.dynamic-island-working[data-state="expanded"] .dynamic-island-surface-avatar-stack > :nth-child(3) {
  transform: translate3d(-28px, 57.5px, 0);
}

@media (prefers-reduced-motion: reduce) {
