}

.dynamic-island-reply-send {
  position: absolute;
  top: calc((var(--johnbot-control-md) - var(--johnbot-control-xs)) / 2);
  right: calc((var(--johnbot-control-md) - var(--johnbot-control-xs)) / 2);
  border-radius: var(--johnbot-radius-pill);
}

.dynamic-island-reply-send svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  stroke-width: var(--johnbot-icon-stroke);
}

.dynamic-island-surface-question-step .dynamic-island-reply {
  margin-top: 6px;
}

.dynamic-island-surface-request-copy {
  min-width: 0;
  width: 100%;
  display: grid;
  gap: var(--johnbot-space-2);
}

.dynamic-island-surface-command {
  min-width: 0;
  display: grid;
  gap: 3px;
  border-left: 1px solid var(--johnbot-warning);
  padding: 2px 0 2px 10px;
}

.dynamic-island-surface-command-meta {
  min-width: 0;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--johnbot-space-2);
}

.dynamic-island-surface-command-meta small,
.dynamic-island-surface-command-meta span {
  overflow: hidden;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dynamic-island-surface-command-meta small {
  flex: 0 0 auto;
}

.dynamic-island-surface-command-meta span {
  min-width: 0;
  text-align: right;
}

.dynamic-island-surface-command code {
  overflow: hidden;
  color: var(--johnbot-text-primary);
  font-family: var(--johnbot-font-mono);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dynamic-island-surface-context-line {
  min-width: 0;
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr);
  gap: var(--johnbot-space-2);
  align-items: baseline;
}

.dynamic-island-surface-context-line small,
.dynamic-island-surface-more {
  color: var(--johnbot-text-dim);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

div.dynamic-island-surface-context-line span {
  overflow: hidden;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dynamic-island-surface-question-options {
  min-width: 0;
  display: grid;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.dynamic-island-surface-question-options > li {
  min-width: 0;
}

.dynamic-island-surface-question-options button {
  width: 100%;
  min-height: 48px;
  min-width: 0;
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr);
  align-items: center;
  gap: var(--johnbot-space-2);
  border: 0;
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-question-option-soft);
  padding: 7px 10px;
  color: inherit;
  cursor: pointer;
  font: inherit;
  text-align: left;
  outline: none;
  transition:
    background-color var(--johnbot-duration-fast) var(--johnbot-ease-out),
