}

.dynamic-island-surface-question-option-copy {
  min-width: 0;
  display: grid;
  gap: 1px;
}

.dynamic-island-surface-question-option-copy strong,
.dynamic-island-surface-question-option-copy small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dynamic-island-surface-question-option-copy strong {
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-sm);
}

.dynamic-island-surface-question-option-copy small {
  min-width: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.dynamic-island-surface-question-option-index {
  width: 22px;
  height: 22px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--johnbot-radius-sm);
  background: var(--johnbot-question-option-hover);
  color: var(--johnbot-question-option);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-semibold);
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

@media (hover: hover) and (pointer: fine) {
  .dynamic-island-surface-question-options button:hover:not(:disabled):not([data-disabled]) {
    background: var(--johnbot-question-option-hover);
  }
}

.dynamic-island-surface-question-options button:active:not(:disabled):not([data-disabled]) {
  background: var(--johnbot-question-option-pressed);
  transform: scale(0.96);
}

.dynamic-island-surface-question-options button:focus-visible {
  box-shadow:
    inset 0 0 0 1px var(--johnbot-question-option),
    0 0 0 3px var(--johnbot-question-option-soft);
}

.dynamic-island-surface-actions {
  display: flex;
  justify-content: flex-end;
  gap: var(--johnbot-space-1);
  border-top: 1px solid var(--johnbot-border);
  padding-top: var(--johnbot-space-2);
}

.dynamic-island-surface-action-error {
  min-width: 0;
  margin: 0 auto 0 0;
  flex: 1 1 auto;
  align-self: center;
  color: var(--johnbot-danger-text);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.dynamic-island-surface-actions svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  stroke-width: var(--johnbot-icon-stroke);
}

.dynamic-island-surface-attention-panel .ui-button {
  transition: transform var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

.dynamic-island-surface-attention-panel .ui-button:active {
  transform: scale(0.96);
}

.dynamic-island-surface-question-panel {
  gap: 10px;
}

.dynamic-island-surface-question-progress {
  display: inline-flex;
  align-items: baseline;
  padding-top: 2px;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
  line-height: var(--johnbot-leading-sm);
  white-space: nowrap;
}

.dynamic-island-surface-question-progress-stack {
  position: relative;
  width: 1.5em;
  display: inline-grid;
  overflow: hidden;
  text-align: right;
}

.dynamic-island-surface-question-progress-digit {
  grid-area: 1 / 1;
  display: inline-block;
  text-align: right;
  will-change: transform, opacity, filter;
}

.dynamic-island-surface-question-progress-digit.is-outgoing {
  position: absolute;
  inset: 0;
}

.dynamic-island-surface-question-step {
  width: 100%;
  min-width: 0;
}

.dynamic-island-surface-question-actions {
  align-items: center;
}

.dynamic-island-surface-question-actions .dynamic-island-surface-more {
  margin-right: auto;
}

.dynamic-island-surface-animated-row {
  animation: dynamic-island-surface-row-in var(--johnbot-duration-slow) var(--johnbot-ease-out) both;
}

.dynamic-island-surface-row-group:nth-child(2) .dynamic-island-surface-animated-row {
  animation-delay: 40ms;
}

.dynamic-island-surface-row-group:nth-child(3) .dynamic-island-surface-animated-row {
  animation-delay: 80ms;
}

@keyframes dynamic-island-surface-swap {
  from {
    opacity: 0;
    filter: blur(var(--text-swap-blur));
    transform: translateY(calc(var(--text-swap-translate-y) * -1)) scale(0.98);
  }

  to {
    opacity: 1;
    filter: blur(0);
    transform: translateY(0) scale(1);
  }
}

@keyframes dynamic-island-surface-row-in {
  from {
    opacity: 0;
    filter: blur(var(--text-swap-blur));
    transform: translateY(var(--text-swap-translate-y)) scale(0.98);
  }

  to {
    opacity: 1;
    filter: blur(0);
    transform: translateY(0) scale(1);
  }
}

/* === from: @johnbot/ui/features/sidebar/sidebar-mobile-app.css === */
/* The mobile app announcement at the bottom of the sidebar. It is a quiet
 * surface card rather than an accent one: an announcement is not an action. The body text and the
 * button use the full card width, so a narrow sidebar wraps the text instead of making a thin
 * column beside the icon. */
.sidebar-mobile-app {
  display: flex;
  flex: 0 0 auto;
  flex-direction: column;
  gap: var(--johnbot-space-2);
  margin: var(--johnbot-space-2) var(--johnbot-space-3);
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-surface);
  padding: var(--johnbot-space-3);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.sidebar-mobile-app-header {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.sidebar-mobile-app-header > strong {
  overflow: hidden;
  font-weight: var(--johnbot-weight-semibold);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sidebar-mobile-app-icon {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  color: var(--johnbot-text-secondary);
}

.sidebar-mobile-app-dismiss {
  margin-right: calc(var(--johnbot-space-1) * -1);
  color: var(--johnbot-text-muted);
}

.sidebar-mobile-app-body {
  margin: 0;
  color: var(--johnbot-text-muted);
}

.sidebar-mobile-app > .ui-button {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The community invitation uses the same card. Discord takes the free width; X is an icon button. */
.sidebar-community-actions {
  display: flex;
  gap: var(--johnbot-space-1-5);
}

.sidebar-community-actions > .ui-button:first-child {
  flex: 1 1 auto;
  min-width: 0;
}

.sidebar-community-mark {
  flex: 0 0 auto;
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

/* The storage card uses the same card. At "full" the card uses the danger tone, and the ring follows the level. */
.sidebar-storage[data-level="full"] {
  border-color: var(--johnbot-danger-border);
  background: var(--johnbot-danger-soft);
}

.sidebar-storage-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--johnbot-space-3);
}

.sidebar-storage-row > .sidebar-mobile-app-dismiss {
  align-self: start;
}

.sidebar-storage-ring {
  width: 48px;
}

.sidebar-storage-percent {
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
  font-weight: var(--johnbot-weight-semibold);
  line-height: 1;
}

.sidebar-storage-text {
  display: grid;
  min-width: 0;
  gap: var(--johnbot-space-0-5);
}

.sidebar-storage-text > strong {
  font-weight: var(--johnbot-weight-semibold);
}

