body,
#root {
  width: 100%;
  height: 100%;
  min-width: 0;
  margin: 0;
  overflow: hidden;
}

body {
  background: var(--johnbot-bg-canvas);
  color: var(--johnbot-text-primary);
  -webkit-font-smoothing: antialiased;
}

button,
input,
textarea {
  font: inherit;
}

