}

.account-login-loader {
  min-height: 88px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  margin-top: 28px;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
}

.account-login-spinner,
.account-login-button-spinner {
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
  border: 1.5px solid var(--johnbot-border-strong);
  border-top-color: currentColor;
  border-radius: var(--johnbot-radius-pill);
  animation: account-login-spin 900ms linear infinite;
}

.account-login-button-spinner {
  width: 13px;
  height: 13px;
}

.account-login-primary {
  width: 100%;
  height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-surface-light);
  color: var(--johnbot-text-on-light);
  font-size: var(--johnbot-text-md);
  font-weight: 650;
  transition:
    background-color var(--johnbot-duration-hover) ease,
    border-color var(--johnbot-duration-hover) ease,
    transform var(--johnbot-duration-fast) cubic-bezier(0.23, 1, 0.32, 1);
}

.account-login > .account-login-primary {
  margin-top: 30px;
}

@keyframes account-login-spin {
  to {
    transform: rotate(360deg);
  }
}

.account-login-form {
  width: 100%;
  display: grid;
  gap: 12px;
  margin-top: 24px;
}

.account-login-local-data {
  margin: 4px 0 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: 17px;
  text-align: center;
  text-wrap: balance;
}

/* Inline, so the lock stays beside the first word when the sentence wraps. */
.account-login-local-data svg {
  display: inline-block;
  margin-right: 6px;
  vertical-align: -2px;
}

.account-login-email-field {
  display: grid;
  gap: 12px;
}

.account-login-form input:not(.otp-input-native) {
  width: 100%;
  height: 44px;
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-md);
  outline: 0;
  background: var(--johnbot-bg-control);
  padding: 0 12px;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
  transition:
    border-color var(--johnbot-duration-hover) ease,
    background-color var(--johnbot-duration-hover) ease,
    box-shadow var(--johnbot-duration-hover) ease;
}

.account-login-form input:not(.otp-input-native):focus {
  border-color: var(--johnbot-border-focus);
  background: var(--johnbot-bg-surface);
}

.account-login-form input:not(.otp-input-native)[aria-invalid="true"] {
  border-color: var(--johnbot-danger);
}

.account-login-form input:not(.otp-input-native)::placeholder {
  color: var(--johnbot-text-placeholder);
}

.account-login-field-error {
  height: 16px;
  overflow: hidden;
  margin: -2px 0 0;
  color: var(--johnbot-danger);
  font-size: var(--johnbot-text-sm);
  line-height: 16px;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.account-login-form input:not(.otp-input-native).t-input.is-error {
  border-color: var(--johnbot-danger);
}

.account-login-primary:disabled,
.account-login-primary[aria-disabled="true"],
.account-login-code-action:disabled,
.account-login-code-action[aria-disabled="true"] {
  cursor: default;
  opacity: 0.48;
}

.account-login-code-actions {
  width: 100%;
  min-height: var(--johnbot-control-sm);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.account-login-code-action {
  width: auto;
}

.account-login-code-action-change {
  justify-content: flex-start;
}

.account-login-code-action-resend {
  justify-content: flex-end;
}

.account-login-development-code {
  margin: 0;
  color: var(--johnbot-warning);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: var(--johnbot-text-sm);
  line-height: 16px;
  text-align: left;
}

@media (hover: hover) and (pointer: fine) {
  .account-login-primary:hover:not(:disabled, [aria-disabled="true"]) {
    background: var(--johnbot-text-primary);
  }

  .account-login-form input:not(.otp-input-native):hover:not(:focus) {
    border-color: var(--johnbot-border-strong);
    background: var(--johnbot-bg-surface);
  }
}

.account-login-primary:active:not(:disabled, [aria-disabled="true"]) {
  transform: scale(0.98);
}

.initial-setup {
  width: min(100%, 620px);
  display: flex;
  flex-direction: column;
  align-items: stretch;
  text-align: left;
  -webkit-app-region: no-drag;
}

.initial-setup-header {
  max-width: 560px;
}

.initial-setup-account-row {
  min-height: 28px;
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 28px;
}

.initial-setup-account {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 7px;
  overflow: hidden;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.initial-setup-account i {
  width: 6px;
  height: 6px;
  flex: 0 0 auto;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-success);
  box-shadow: 0 0 0 3px var(--johnbot-success-soft);
}

.initial-setup-signout,
.initial-setup-back {
  border: 0;
  background: transparent;
  color: var(--johnbot-text-muted);
}

.initial-setup-signout {
  margin-left: 2px;
  padding: 5px 7px;
  font-size: var(--johnbot-text-sm);
}

.initial-setup-signout:hover,
.initial-setup-back:hover {
  color: var(--johnbot-text-secondary);
}

.initial-setup-back {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  margin-right: 3px;
  border-radius: var(--johnbot-radius-pill);
  padding: 0;
}

.initial-setup-back:hover {
  background: var(--johnbot-hover);
}

.initial-setup-back svg {
  width: 18px;
  fill: none;
  stroke: currentcolor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: var(--johnbot-icon-stroke);
}

.initial-setup-eyebrow {
  margin: 0 0 9px;
  color: var(--text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.initial-setup h1 {
  margin: 0;
  color: var(--text-primary);
  font-size: var(--johnbot-text-display);
  font-weight: 560;
  letter-spacing: -0.035em;
  line-height: 1.1;
}

.initial-setup-intro {
  max-width: 540px;
  margin: 12px 0 0;
  color: var(--text-secondary);
  font-size: var(--johnbot-text-lg);
  line-height: 1.55;
}

.setup-route-list {
  display: grid;
  gap: 10px;
  margin-top: 30px;
  padding: 0;
  list-style: none;
}

.setup-route-button {
  width: 100%;
  min-height: 96px;
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr) 20px;
  align-items: center;
  gap: 15px;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-canvas);
  padding: 15px 17px;
  color: var(--johnbot-text-primary);
  text-align: left;
  transition:
    border-color var(--johnbot-duration-hover) ease,
    background-color var(--johnbot-duration-hover) ease,
    transform var(--johnbot-duration-hover) ease;
}

.setup-route-button:hover {
  border-color: var(--johnbot-text-dim);
  background: var(--johnbot-bg-sidebar);
  transform: translateY(-1px);
}

.setup-route-button:active {
  transform: translateY(0);
  transition-duration: var(--johnbot-duration-hover), var(--johnbot-duration-hover), var(--johnbot-duration-fast);
}

.setup-route-icon {
  position: relative;
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-hover);
  color: var(--johnbot-text-secondary);
}

.setup-route-icon svg {
  width: 23px;
  fill: none;
  stroke: currentcolor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: var(--johnbot-icon-stroke);
}

.setup-route-icon i {
  position: absolute;
  right: -2px;
  bottom: -2px;
  width: 9px;
  height: 9px;
  border: 2px solid var(--johnbot-bg-canvas);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-accent);
}

.setup-route-icon-local i {
  background: var(--johnbot-success);
}

.setup-route-copy {
  display: grid;
  gap: 4px;
}

.setup-route-copy strong {
  font-size: var(--johnbot-text-lg);
  font-weight: 600;
}

.setup-route-copy small {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: 17px;
}

.setup-route-arrow {
  width: 19px;
  fill: none;
  stroke: var(--johnbot-text-muted);
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: transform var(--johnbot-duration-hover) ease;
}

.setup-route-button:hover .setup-route-arrow {
  transform: translateX(2px);
}

.setup-local-content {
  margin-top: 28px;
}

.setup-remote-form {
  display: grid;
  gap: 15px;
  margin-top: 28px;
}

.setup-remote-form label {
  display: grid;
  gap: 7px;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  font-weight: 560;
}

.setup-remote-form input,
.setup-remote-form textarea {
  width: 100%;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-lg);
  outline: 0;
  background: var(--johnbot-bg-canvas);
  padding: 11px 12px;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  line-height: 18px;
  resize: none;
}

.setup-remote-form input {
  min-height: 43px;
}

.setup-remote-form input:focus,
.setup-remote-form textarea:focus {
  border-color: var(--johnbot-text-dim);
  background: var(--johnbot-bg-sidebar);
}

.setup-remote-form input::placeholder,
.setup-remote-form textarea::placeholder {
  color: var(--johnbot-text-dim);
}

.setup-remote-note {
  margin: -2px 1px 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: 16px;
}

.setup-remote-change {
  width: fit-content;
  border: 0;
  background: transparent;
  padding: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

.setup-remote-change:hover:not(:disabled) {
  color: var(--johnbot-text-secondary);
}

.provider-picker {
  min-width: 0;
  margin: 0;
  border: 0;
  padding: 0;
}

.provider-picker-standalone {
  margin-top: 24px;
}

.setup-local-content .provider-picker-standalone {
  margin-top: 0;
}

.provider-picker-label {
  margin-bottom: 7px;
  padding: 0;
  color: var(--text-secondary);
  font-size: var(--johnbot-text-sm);
  font-weight: 560;
}

.provider-picker-heading {
  display: flex;
  min-height: 25px;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-2);
  margin-bottom: 7px;
}

.provider-picker-heading .provider-picker-label {
  margin-bottom: 0;
}

.ui-button.provider-picker-refresh {
  min-height: 25px;
  gap: var(--johnbot-space-1);
  border-radius: var(--johnbot-radius-md);
  color: var(--johnbot-text-muted);
  padding-inline: var(--johnbot-space-2);
}

.ui-button.provider-picker-refresh:hover:not(:disabled, [aria-disabled="true"]) {
  color: var(--johnbot-text-primary);
}

.provider-picker-list {
  overflow: hidden;
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-sidebar);
}

.provider-picker-option {
  min-height: 44px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  color: var(--text-primary);
}

.provider-picker-option-selection {
  min-width: 0;
  min-height: 44px;
  display: grid;
  grid-template-columns: 16px 18px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 8px 0 8px 12px;
  cursor: pointer;
}

/* The custom row follows the radio group rather than a radio, so the sibling rule cannot reach it. */
.provider-picker-option + .provider-picker-option,
.provider-picker-option-custom {
  border-top: 1px solid var(--johnbot-border);
}

.provider-picker-option:hover:not(.provider-picker-option-unavailable),
.provider-picker-option:focus-within {
  background: var(--johnbot-hover);
}

.provider-picker-option-selected {
  background: var(--johnbot-hover);
}

.provider-picker-option-unavailable {
  color: var(--johnbot-text-muted);
}

.provider-picker-option-unavailable .provider-picker-option-selection {
  cursor: default;
}

.provider-picker-option-selectable-unavailable .provider-picker-option-selection {
  cursor: pointer;
}

.provider-picker-option-selectable-unavailable:hover {
  background: var(--johnbot-hover);
}

.provider-picker-option input {
  width: 14px;
  height: 14px;
  margin: 0;
  accent-color: var(--johnbot-text-primary);
}

/* The actions share the grid cell the row reserves for them. In this variant the buttons carry
   their own trailing margin, which both separates them and holds the last one off the edge. */
.provider-picker-actions {
  display: flex;
  align-items: center;
}

.ui-button.provider-picker-install {
  min-width: 58px;
  min-height: 28px;
  margin-right: 8px;
  border-radius: var(--johnbot-radius-md);
  padding-inline: 9px;
}

.ui-button.provider-picker-connect {
  background: var(--johnbot-accent);
  color: var(--johnbot-text-primary);
}

@media (hover: hover) and (pointer: fine) {
  .ui-button.provider-picker-connect:hover:not(:disabled):not([data-disabled]) {
    background: var(--johnbot-accent-hover);
  }
}

.provider-picker-logo {
  width: 18px;
  height: 18px;
  overflow: visible;
  fill: var(--johnbot-provider-current);
}

/* A custom endpoint has no brand mark, so a stroke icon takes the logo column. Until an endpoint
   exists the radio column before it stays empty, because the row can then only add. */
.provider-picker-custom-mark {
  width: 18px;
  height: 18px;
  grid-column: 2;
  color: var(--johnbot-text-secondary);
  stroke-width: var(--johnbot-icon-stroke);
}

.provider-picker-option-unavailable .provider-picker-logo,
.provider-picker-option-unavailable .provider-picker-custom-mark {
  opacity: 0.44;
}

.provider-picker-option-runtime {
  color: var(--johnbot-text-primary);
}

.provider-picker-option-runtime .provider-picker-logo {
  opacity: 1;
}

.provider-picker-identity {
  display: grid;
  min-width: 0;
}

.provider-picker-name,
.provider-picker-email {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.provider-picker-name {
  font-size: var(--johnbot-text-md);
  font-weight: 530;
  line-height: 18px;
}

.provider-picker-email {
  color: var(--text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: 15px;
}

.provider-picker-check-error {
  overflow: hidden;
  color: var(--johnbot-warning);
  font-size: var(--johnbot-text-sm);
  line-height: 15px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The reason a row is not ready is the sentence the user acts on, so it wraps rather than ends in an
   ellipsis. */
.provider-picker-status-message {
  overflow: visible;
  white-space: normal;
}

/* The agents that keep a provider on, on a line of its own below the row and in line with the name.
   The row grows to show the whole sentence, because the user must read which agents to change. */
.provider-picker-check-error.provider-picker-used-by {
  grid-column: 1 / -1;
  overflow: visible;
  margin-top: -6px;
  padding: 0 0 8px 66px;
  white-space: normal;
}

.provider-picker-option-selected .provider-picker-email {
  color: var(--johnbot-text-readable);
}

/* The same icon size as the other small buttons of the row. */
.provider-picker-add-account svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  stroke-width: var(--johnbot-icon-stroke);
}

/* The accounts of a provider, on lines of their own below its row and in line with its name. */
.provider-picker-accounts {
  grid-column: 1 / -1;
  display: grid;
  gap: 4px;
  margin-top: -6px;
  padding: 0 0 8px 66px;
}

.provider-picker-account-list {
  display: grid;
  margin: 0;
  padding: 0;
  list-style: none;
}

.provider-picker-account {
  min-height: 48px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 0;
}

.provider-picker-account + .provider-picker-account {
  border-top: 1px solid var(--johnbot-border);
}

.provider-picker-account-copy {
  min-width: 0;
  flex: 1 1 auto;
  display: grid;
  gap: 2px;
}

.provider-picker-account .provider-picker-check-error {
  white-space: normal;
}

.provider-picker-account-rename {
  max-width: 220px;
}

/* The version and the status badge, in the one cell the row's last column reserves. They are read
   together - "v2.1.246" and "Ready" answer one question between them - and a shared cell keeps a
   provider with no version to report from leaving a gap where the badge used to sit. */
.provider-picker-state {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}

/* The installed version. Muted, because it answers a question a user asks once and then stops
   asking, and tabular so that a version which changes under a running update replaces itself
   without shifting the badge beside it. */
.provider-picker-version {
  overflow: hidden;
  color: var(--text-muted);
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
  line-height: 16px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.provider-picker-option-selected .provider-picker-version {
  color: var(--johnbot-text-readable);
}

.provider-picker-status {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: 16px;
  white-space: nowrap;
}

/* How many endpoints the Custom provider row stands for. It reads like a status badge, because it
   sits in the same cell and answers the same kind of question, but it reports no state. */
.provider-picker-custom-count {
  color: var(--text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: 16px;
  white-space: nowrap;
}

/* The same count, as the button that opens the saved endpoints. It keeps the badge's quiet colour
   and sits with the row's other actions, so it needs their margin and the button's own specificity. */
.ui-button.provider-picker-custom-count {
  min-height: 28px;
  margin-right: 8px;
  border-radius: var(--johnbot-radius-md);
  padding-inline: 9px;
  color: var(--text-muted);
  font-size: var(--johnbot-text-sm);
}

.provider-picker-status-available {
  color: var(--johnbot-success);
}

.provider-picker-status-sign-in-required,
.provider-picker-status-outdated,
.provider-picker-status-update-available {
  color: var(--johnbot-warning);
}

.provider-picker-status-ready {
  color: var(--johnbot-success);
}

.provider-picker-status-download-error {
  color: var(--johnbot-danger);
}

.provider-picker-status-finishing {
  color: var(--johnbot-warning);
}

.provider-picker-status-not-installed,
.provider-picker-status-checking,
.provider-picker-status-error {
  color: var(--johnbot-text-muted);
}

.provider-picker-status i {
  width: 5px;
  height: 5px;
  flex: 0 0 auto;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-text-dim);
}

.provider-picker-status-available i {
  background: var(--johnbot-success);
}

.provider-picker-status-sign-in-required i,
.provider-picker-status-outdated i,
.provider-picker-status-update-available i {
  background: var(--johnbot-warning);
}

.provider-picker-status-not-installed i,
.provider-picker-status-checking i,
.provider-picker-status-error i {
  background: var(--johnbot-text-dim);
}

.provider-picker-hint {
  margin: 7px 0 0;
  color: var(--text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: 16px;
}

/* "More providers" is a button below the list, beside the hint. It uses the style of the heading's
 * Refresh button, so the picker has one kind of small list action. */
.provider-picker-footer {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-2);
  margin-top: 7px;
}

.provider-picker-footer .provider-picker-hint {
  margin: 0;
}

.ui-button.provider-picker-more {
  flex: 0 0 auto;
  gap: var(--johnbot-space-1-5);
  margin-inline-start: auto;
  margin-inline-end: calc(var(--johnbot-space-2) * -1);
}

.provider-picker-logo-stack {
  position: relative;
  z-index: 0;
  display: inline-flex;
}

.provider-picker-logo-stack-mark {
  position: relative;
  width: 20px;
  height: 20px;
  display: grid;
  place-items: center;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-control-active);
  box-shadow: 0 0 0 2px var(--johnbot-bg-canvas);
}

.provider-picker-logo-stack-mark + .provider-picker-logo-stack-mark {
  z-index: -1;
  margin-inline-start: -4px;
}

.provider-picker-logo-stack-mark .provider-picker-logo {
  width: 12px;
  height: 12px;
}

/* The "More providers" dialog uses the custom provider dialog frame: a title, a close button and
 * one plain list. It is pinned near the top, so it does not move when a search changes its height. */
.custom-provider-backdrop.provider-more-backdrop {
  align-items: start;
  padding-top: min(14vh, 120px);
}

.custom-provider-dialog.provider-more-dialog {
  width: min(400px, 100%);
  max-height: min(600px, calc(100dvh - min(14vh, 120px) - var(--johnbot-space-6)));
  padding: var(--johnbot-space-2);
}

.provider-more-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--johnbot-space-1) var(--johnbot-space-1) var(--johnbot-space-1) var(--johnbot-space-3);
}

.provider-more-title {
  margin: 0;
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-semibold);
}

.ui-input.provider-more-search {
  flex-shrink: 0;
  margin: var(--johnbot-space-1) 0 var(--johnbot-space-2);
}

.provider-more-search::-webkit-search-cancel-button {
  appearance: none;
}

.provider-more-list {
  min-height: 0;
  overflow-y: auto;
}

/* The name and description that the picker rows use; the full row is the target. */
.ui-button.provider-more-row {
  width: 100%;
  height: auto;
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  justify-content: stretch;
  align-items: center;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
  border: 0;
  border-radius: var(--johnbot-radius-md);
  color: inherit;
  font: inherit;
  line-height: normal;
  text-align: left;
  white-space: normal;
}

.ui-button.provider-more-row:focus-visible {
  outline: 2px solid var(--johnbot-border-focus);
  outline-offset: -2px;
}

.provider-more-row .provider-picker-custom-mark {
  grid-column: auto;
}

.provider-more-divider {
  height: 1px;
  margin: var(--johnbot-space-1) var(--johnbot-space-3);
  border: 0;
  background: var(--johnbot-border);
}

.provider-more-empty {
  margin: 0;
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

.initial-setup-error {
  margin: 12px 2px 0;
  color: var(--johnbot-danger);
  font-size: var(--johnbot-text-md);
  line-height: 1.45;
}

.initial-setup-actions {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  margin-top: 20px;
}

.initial-setup-save {
  min-height: 40px;
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-md);
  padding: 12px 18px;
  font-size: var(--johnbot-text-md);
  font-weight: 620;
}

.initial-setup-save {
  min-width: 180px;
  background: var(--johnbot-text-primary);
  color: var(--johnbot-bg-sidebar);
  transition:
    transform var(--johnbot-duration-normal) ease,
    background var(--johnbot-duration-hover) ease;
}

.initial-setup-save:hover:not(:disabled) {
  background: var(--johnbot-text-primary);
}

.initial-setup-save:disabled {
  cursor: default;
  opacity: 0.48;
}

.initial-setup-save:active:not(:disabled) {
  transform: scale(0.992);
}

@media (max-width: 620px) {
  .initial-setup-screen {
    place-items: start center;
    padding: 52px 18px 24px;
  }

  .account-login-screen {
    padding-inline: 18px;
  }

  .initial-setup-actions,
  .initial-setup-save {
    width: 100%;
  }

  .initial-setup-actions {
    flex-direction: column-reverse;
  }

  .setup-route-button {
    grid-template-columns: 42px minmax(0, 1fr) 18px;
    gap: 12px;
    padding-inline: 13px;
  }

  .setup-route-icon {
    width: 42px;
    height: 42px;
  }

  .initial-setup-account {
    max-width: 55vw;
  }
}

@media (max-width: 480px) {
  .account-login-screen {
    padding: 40px 20px;
  }

  .account-login-brand-lockup {
    margin-bottom: 24px;
  }
}

@media (prefers-reduced-motion: no-preference) {
  .account-login,
  .initial-setup {
    animation: setup-enter var(--johnbot-duration-overlay) cubic-bezier(0.2, 0.8, 0.2, 1) both;
  }

  .account-login[data-transition="forward"] .account-login-title,
  .account-login[data-transition="forward"] .account-login-description {
    animation: account-login-copy-forward var(--johnbot-duration-overlay) var(--johnbot-ease-out) both;
  }

  .account-login[data-transition="back"] .account-login-title,
  .account-login[data-transition="back"] .account-login-description {
    animation: account-login-copy-back var(--johnbot-duration-overlay) var(--johnbot-ease-out) both;
  }

  .account-login[data-transition] .account-login-description {
    animation-delay: 18ms;
  }

  .account-login[data-transition="forward"] .account-login-form[data-auth-panel="code"] {
    animation: account-login-panel-forward var(--johnbot-duration-overlay) 32ms var(--johnbot-ease-out) both;
  }

  .account-login[data-transition="back"] .account-login-form[data-auth-panel="email"] {
    animation: account-login-panel-back var(--johnbot-duration-overlay) 32ms var(--johnbot-ease-out) both;
  }

  @keyframes setup-enter {
    from {
      opacity: 0;
      transform: translateY(6px);
    }
  }

  @keyframes account-login-copy-forward {
    from {
      filter: blur(4px);
      opacity: 0;
      transform: translateX(10px);
    }
  }

  @keyframes account-login-copy-back {
    from {
      filter: blur(4px);
      opacity: 0;
      transform: translateX(-10px);
    }
  }

  @keyframes account-login-panel-forward {
    from {
      filter: blur(6px);
      opacity: 0;
      transform: translateX(16px) scale(0.985);
    }
  }

  @keyframes account-login-panel-back {
    from {
      filter: blur(6px);
      opacity: 0;
      transform: translateX(-16px) scale(0.985);
    }
  }
}

@media (prefers-reduced-motion: reduce) {
  .account-login-spinner,
  .approval-card {
    animation: none;
  }

  .account-login[data-transition] .account-login-title,
  .account-login[data-transition] .account-login-description,
  .account-login[data-transition] .account-login-form[data-auth-panel] {
    animation: none;
  }
}

button {
  cursor: pointer;
}

button:not(.ui-button):focus-visible,
input:not(.ui-input):focus-visible,
textarea:not(.ui-textarea):focus-visible {
  outline: 2px solid var(--johnbot-border-focus);
  outline-offset: 2px;
}

::selection {
  background: var(--johnbot-accent-strong);
}

/* No vertical scroll bar: the wheel, the trackpad and the keyboard still scroll. Horizontal bars
 * stay, because a mouse wheel cannot scroll a code block or a table sideways. */
::-webkit-scrollbar {
  width: 0;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  border: 2px solid transparent;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-border-strong);
  background-clip: padding-box;
}

.scroll-fade-top:not(.scroll-fade-bottom) {
  -webkit-mask-image: linear-gradient(
    to bottom,
    transparent 0,
    var(--johnbot-text-primary) 18px,
    var(--johnbot-text-primary) 100%
  );
  mask-image: linear-gradient(
    to bottom,
    transparent 0,
    var(--johnbot-text-primary) 18px,
    var(--johnbot-text-primary) 100%
  );
}

.scroll-fade-bottom:not(.scroll-fade-top) {
  -webkit-mask-image: linear-gradient(
    to bottom,
    var(--johnbot-text-primary) 0,
    var(--johnbot-text-primary) calc(100% - 18px),
    transparent 100%
  );
  mask-image: linear-gradient(
    to bottom,
    var(--johnbot-text-primary) 0,
    var(--johnbot-text-primary) calc(100% - 18px),
    transparent 100%
  );
}

.scroll-fade-top.scroll-fade-bottom {
  -webkit-mask-image: linear-gradient(
    to bottom,
    transparent 0,
    var(--johnbot-text-primary) 18px,
    var(--johnbot-text-primary) calc(100% - 18px),
    transparent 100%
  );
  mask-image: linear-gradient(
    to bottom,
    transparent 0,
    var(--johnbot-text-primary) 18px,
    var(--johnbot-text-primary) calc(100% - 18px),
    transparent 100%
  );
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

