/* The OpenCode note sits outside the list, so the list lets it through and its first and last rows
   round their own corners instead of relying on the clip. The first run and the setup dialog both
   show the note; without the row as its containing block, it points at a different row. */
:is(.onboarding-provider, .setup-local-content) .provider-picker-list {
  overflow: visible;
}

:is(.onboarding-provider, .setup-local-content) .provider-picker-list > :first-child,
:is(.onboarding-provider, .setup-local-content)
  .provider-picker-list
  > :first-child
  > .provider-picker-option:first-child {
  border-top-left-radius: calc(var(--johnbot-radius-md) - 1px);
  border-top-right-radius: calc(var(--johnbot-radius-md) - 1px);
}

:is(.onboarding-provider, .setup-local-content) .provider-picker-list > :last-child,
:is(.onboarding-provider, .setup-local-content)
  .provider-picker-list
  > :last-child
  > .provider-picker-option:last-child {
  border-bottom-left-radius: calc(var(--johnbot-radius-md) - 1px);
  border-bottom-right-radius: calc(var(--johnbot-radius-md) - 1px);
}

:is(.onboarding-provider, .setup-local-content) .provider-picker-option-with-callout {
  position: relative;
}

/* Drawn like the drag hint of the macOS installer: a note, then a thin arrow into the row. */
.provider-picker-callout {
  position: absolute;
  right: calc(100% + 10px);
  bottom: 50%;
  width: 150px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  color: var(--johnbot-onboarding-desktop-indigo);
  pointer-events: none;
  animation: provider-picker-callout-in 420ms cubic-bezier(0.23, 1, 0.32, 1) both;
}

.provider-picker-callout-title {
  font-size: var(--johnbot-text-md);
  font-weight: 620;
  line-height: 18px;
}

.provider-picker-callout-detail {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: 16px;
}

.provider-picker-callout-arrow {
  width: 92px;
  height: 40px;
  align-self: flex-end;
  margin-top: 2px;
  /* The note ends at the middle of its target; this puts the arrowhead (y 30 of 40) there too. */
  margin-bottom: -10px;
}

@keyframes provider-picker-callout-in {
  from {
    opacity: 0;
  }
}

/* The same note on the right of the list, for "More providers": the text aligns right and the
   arrow is mirrored to point left. */
.provider-picker-callout-end {
  right: auto;
  left: calc(100% + 10px);
  align-items: flex-end;
  text-align: right;
}

.provider-picker-callout-end .provider-picker-callout-arrow {
  align-self: flex-start;
  transform: scaleX(-1);
}

@media (prefers-reduced-motion: reduce) {
  .provider-picker-callout {
    animation: none;
  }
}

/* No room beside the list: the row's own description says the same. */
@media (max-width: 860px) {
  .provider-picker-callout {
    display: none;
  }
}

/* The setup dialog is 620px wide, and a note needs 160px on each side of it. */
@media (max-width: 960px) {
  .setup-local-content .provider-picker-callout {
    display: none;
  }
}

/* The provider step of a joined server covers the window, over the rail and the sidebar. */
.server-onboarding-screen {
  position: fixed;
}

.server-onboarding-close {
  position: absolute;
  top: 12px;
  right: 12px;
  -webkit-app-region: no-drag;
}

/* The first question of first run. The team rises in from the sides to the large agent in the
   middle; the two answers are rows of one grouped list. */

.first-run-screen[data-step="choose"] .onboarding-shell {
  width: min(100%, 960px);
}

/* First run changes steps in a view transition (`first-run-transition.ts`). The old step blurs and
   fades out while the next one comes into focus in the same place; the progress and the actions
   move to their new place. Opening the app blurs the setup screen away into
   the app. The motion stays small: blur and fade carry the change, not travel. */
.first-run-screen .onboarding-shell > .onboarding-step {
  view-transition-name: first-run-step;
}

.first-run-screen .onboarding-shell > .onboarding-progress {
  view-transition-name: first-run-progress;
}

.first-run-screen .onboarding-shell > .onboarding-actions {
  view-transition-name: first-run-actions;
}

::view-transition-group(first-run-step),
::view-transition-group(first-run-progress),
::view-transition-group(first-run-actions) {
  animation-duration: 440ms;
  animation-timing-function: var(--johnbot-ease-out);
}

/* The steps are not the same width. Each image keeps its own size in the middle, so none stretches. */
::view-transition-old(first-run-step),
::view-transition-new(first-run-step) {
  inset-inline-start: 50%;
  inline-size: auto;
  translate: -50% 0;
}

html:active-view-transition-type(step)::view-transition-old(first-run-step) {
  animation: first-run-step-out 220ms var(--johnbot-ease-out) both;
}

html:active-view-transition-type(step)::view-transition-new(first-run-step) {
  animation: first-run-step-in 440ms var(--johnbot-ease-out) 40ms both;
}

/* The live dots animate their own width, so the old picture of them is not needed. */
::view-transition-old(first-run-progress):not(:only-child) {
  animation: none;
  opacity: 0;
}

::view-transition-new(first-run-progress):not(:only-child) {
  animation: none;
}

::view-transition-new(first-run-progress):only-child,
::view-transition-new(first-run-actions):only-child {
  animation: first-run-step-rise 440ms var(--johnbot-ease-out) 40ms both;
}

/* The buttons change their labels in place, so the old ones blur away under the new ones. */
::view-transition-old(first-run-actions),
::view-transition-old(first-run-progress):only-child {
  animation: first-run-blur-out 220ms var(--johnbot-ease-out) both;
}

::view-transition-new(first-run-actions):not(:only-child) {
  animation: first-run-blur-in 440ms var(--johnbot-ease-out) 40ms both;
}

html:active-view-transition-type(open)::view-transition-old(*) {
  animation: first-run-open-out 320ms var(--johnbot-ease-out) both;
}

html:active-view-transition-type(open)::view-transition-new(*) {
  animation: first-run-open-in 520ms var(--johnbot-ease-out) 60ms both;
}

@keyframes first-run-step-out {
  to {
    opacity: 0;
    filter: blur(6px);
  }
}

@keyframes first-run-step-in {
  from {
    opacity: 0;
    filter: blur(6px);
  }
}

@keyframes first-run-step-rise {
  from {
    opacity: 0;
    filter: blur(4px);
  }
}

@keyframes first-run-blur-out {
  to {
    opacity: 0;
    filter: blur(8px);
  }
}

@keyframes first-run-blur-in {
  from {
    opacity: 0;
    filter: blur(8px);
  }
}

@keyframes first-run-open-out {
  to {
    opacity: 0;
    filter: blur(8px);
  }
}

@keyframes first-run-open-in {
  from {
    opacity: 0;
    filter: blur(6px);
  }
}

.first-run-choice {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
