/*
 * The agents of the first screen and of the splash watch the pointer with their eyes (see
 * `followPointer`). A hovered agent grows a little and a pressed one squeezes, then both spring back.
 * The `scale` property leaves `transform` and `translate` to the arc and to the jumps. On the splash
 * the hover is on the member, which stays still: a jump under a still pointer must not start it.
 */
@media (prefers-reduced-motion: no-preference) {
  .first-run-choice-avatar,
  .first-run-launch-avatar {
    --first-run-spring: linear(
      0,
      0.035 2.1%,
      0.281 6.7%,
      0.723 12.9%,
      0.938 16.7%,
      1.077 21%,
      1.149 24.3%,
      1.163 27%,
      1.154 29.9%,
      1.129 32.8%,
      1.051 39.6%,
      1.017 43.1%,
      0.977 51%,
      0.974 53.8%,
      0.975 57.1%,
      0.997 69.8%,
      1.003 76.9%,
      1
    );

    transition: scale 560ms var(--first-run-spring);
  }

  .first-run-choice-avatar:hover,
  .first-run-launch-member:hover .first-run-launch-avatar {
    scale: 1.12;
  }

  .first-run-choice-avatar:active,
  .first-run-launch-member:active .first-run-launch-avatar {
    scale: 0.9;
    transition-duration: var(--johnbot-duration-fast);
    transition-timing-function: var(--johnbot-ease-out);
  }
}

/*
 * While first run waits to open the app, a splash covers it. The team from the first screen stands
 * in the same arc and jumps in a slow wave, one agent after the other. The scribble under the team
 * fills with the download; a wait with no percent draws and erases it.
 */
.first-run-launch {
  --first-run-launch-accent: var(--johnbot-logo-production);
  position: absolute;
  z-index: var(--johnbot-layer-dialog);
  inset: 0;
  display: grid;
  place-items: center;
  overflow: hidden;
  background: var(--johnbot-bg-canvas);
  -webkit-app-region: drag;
}

.first-run-launch[data-variant="dev"] {
  --first-run-launch-accent: var(--johnbot-logo-dev);
}

.first-run-launch[data-variant="preview"] {
  --first-run-launch-accent: var(--johnbot-logo-preview);
}

.first-run-launch-stage {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 40px;
}

.first-run-launch-team {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--johnbot-space-3);
}

.first-run-launch-member {
  display: grid;
  flex: none;
}

.first-run-launch-avatar {
  width: 52px;
  height: 52px;
}

/* The same arc as the team on the first screen. */
.first-run-launch-member:nth-child(1),
.first-run-launch-member:nth-child(7) {
  translate: 0 24px;
}

.first-run-launch-member:nth-child(1) .first-run-launch-avatar,
.first-run-launch-member:nth-child(7) .first-run-launch-avatar {
  width: 40px;
  height: 40px;
}

.first-run-launch-member:nth-child(2),
.first-run-launch-member:nth-child(6) {
  translate: 0 8px;
}

.first-run-launch-member:nth-child(3) .first-run-launch-avatar,
.first-run-launch-member:nth-child(5) .first-run-launch-avatar {
  width: 68px;
  height: 68px;
}

.first-run-launch-member:nth-child(4) {
  translate: 0 -12px;
}

.first-run-launch-member:nth-child(4) .first-run-launch-avatar {
  width: 104px;
  height: 104px;
}

.first-run-launch-loader {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}

.first-run-launch-scribble {
  display: block;
  width: 112px;
  height: 14px;
  overflow: visible;
}

.first-run-launch-scribble polyline {
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 2.4px;
}

.first-run-launch-track {
  stroke: color-mix(in srgb, var(--first-run-launch-accent) 18%, transparent);
}

.first-run-launch-fill {
  stroke: var(--first-run-launch-accent);
  stroke-dasharray: 1 1;
  stroke-dashoffset: calc(1 - var(--first-run-launch-percent));
  transition: stroke-dashoffset var(--johnbot-duration-overlay) var(--johnbot-ease-out);
}

.first-run-launch-label {
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
}

@media (max-width: 760px) {
  .first-run-launch-team {
    gap: var(--johnbot-space-1-5);
  }

  .first-run-launch-member:nth-child(1),
  .first-run-launch-member:nth-child(7) {
    display: none;
  }
}

@media (prefers-reduced-motion: no-preference) {
  .first-run-launch-avatar {
    animation: first-run-launch-hop 1.8s var(--johnbot-ease-in-out) infinite;
  }

  .first-run-launch-member:nth-child(2) .first-run-launch-avatar {
    animation-delay: 120ms;
  }

  .first-run-launch-member:nth-child(3) .first-run-launch-avatar {
    animation-delay: 240ms;
  }

  .first-run-launch-member:nth-child(4) .first-run-launch-avatar {
    animation-delay: 360ms;
  }

  .first-run-launch-member:nth-child(5) .first-run-launch-avatar {
    animation-delay: 480ms;
  }

  .first-run-launch-member:nth-child(6) .first-run-launch-avatar {
    animation-delay: 600ms;
  }

  .first-run-launch-member:nth-child(7) .first-run-launch-avatar {
    animation-delay: 720ms;
  }

  .first-run-launch-progress[data-known="false"] .first-run-launch-fill {
    stroke-dasharray: 0.35 1.2;
    transition: none;
    animation: first-run-launch-scribble 1.8s var(--johnbot-ease-in-out) infinite;
  }
}

/* A short jump, then a rest, so the wave reads as one team and not as noise. */
@keyframes first-run-launch-hop {
  0%,
  36%,
  100% {
    transform: translateY(0);
  }
  16% {
    transform: translateY(-12px);
  }
}

@keyframes first-run-launch-scribble {
  from {
