/* === from: ./features/startup/startup-splash.css === *//*
 * The desktop startup splash. The logo fades in and each eye is drawn as one pen stroke. The logo then
 * blinks until the app is ready, and the splash fades out.
 */

.startup-splash {
  position: absolute;
  z-index: var(--johnbot-layer-dialog);
  inset: 0;
  display: grid;
  place-items: center;
  background: var(--johnbot-bg-canvas);
  -webkit-app-region: drag;
}

.startup-splash-logo {
  display: block;
  width: 96px;
  height: 96px;
  animation: startup-splash-in var(--johnbot-duration-overlay) var(--johnbot-ease-out) backwards;
}

/* The fade also runs with reduced motion: its animationend removes the splash. */
.startup-splash[data-phase="exit"] {
  pointer-events: none;
  -webkit-app-region: no-drag;
  animation: startup-splash-exit var(--johnbot-duration-overlay) var(--johnbot-ease-in-out) forwards;
}

@media (prefers-reduced-motion: no-preference) {
  /* Both eyes use the longer stroke's length, so they draw at the same time. */
  .startup-splash-logo .app-logo-eye {
    stroke-dasharray: var(--splash-eye-length) calc(var(--splash-eye-length) + 24px);
    animation:
      startup-splash-eye-draw 480ms var(--johnbot-ease-in-out) 160ms backwards,
      app-logo-blink 4.8s var(--johnbot-ease-in-out) 1s infinite;
  }
}

@keyframes startup-splash-in {
  from {
    opacity: 0;
  }
}

@keyframes startup-splash-eye-draw {
  from {
    stroke-dashoffset: calc(var(--splash-eye-length) + 12px);
  }
  to {
    stroke-dashoffset: 0px;
  }
}

@keyframes startup-splash-exit {
  to {
    opacity: 0;
  }
}

