  z-index: calc(var(--johnbot-layer-dialog) + 1);
  /* A fixed top keeps the input and filters still when the result list changes height, and clears toasts. */
  top: 112px;
  left: 50%;
  display: flex;
  width: min(640px, calc(100vw - 48px));
  max-height: calc(100dvh - 136px);
  flex-direction: column;
  overflow: hidden;
  outline: 0;
  background: var(--johnbot-bg-control);
  box-shadow:
    0 0 0 1px var(--johnbot-dialog-ring),
    var(--johnbot-shadow-dialog);
  color: var(--johnbot-text-primary);
  transform: translateX(-50%);
