  pointer-events: none;
  width: 1px;
  background: linear-gradient(to bottom, transparent, var(--johnbot-text-dim) 50%, transparent);
  content: "";
  opacity: 0;
  transform: translateX(-50%);
}

.panel-resizer:hover::after,
.panel-resizer:focus-visible::after,
.panel-resizer-active::after {
  opacity: 1;
}

.panel-resizer:focus-visible {
  outline: 0;
  box-shadow: inset 0 0 0 1px var(--johnbot-border-strong);
}

html.panel-resizing {
  --panel-resize-duration: 0ms;

  cursor: col-resize;
  user-select: none;
}

.right-panel-resizer {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  height: auto;
}

.app-frame > * {
  min-height: 0;
}

.panel-edge {
  border-right: clamp(0.5px, 0.05123cqw, 1px) solid var(--johnbot-border);
}

.window-drag {
  -webkit-app-region: drag;
}

.no-drag,
button,
input,
textarea {
  -webkit-app-region: no-drag;
}

.sidebar {
  display: flex;
  min-width: 0;
  overflow: hidden;
  flex-direction: column;
  background: var(--johnbot-bg-sidebar);
  color: var(--johnbot-text-primary);
  container-type: inline-size;
}

.sidebar-topbar {
  display: flex;
  height: var(--left-header-height);
  flex: 0 0 auto;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-2);
  border-bottom: 1px solid var(--johnbot-border);
  /* The logo of the page rail (`page-rail.css`) has the same top padding, to stay on this center line. */
  padding: 2px 3px 0 10px;
}

/* The frame edge. The top row of the sidebar, the chat and the side panel has no line of its own: the
 * window card in `window.css` draws the lines, the surfaces and the rounded corners. The theme layer at
 * the end of this file also sets the server rail background, so the selector carries the frame class
 * to win. */
@media (min-width: 721px) {
  .app-frame-edge > .server-rail {
    background: var(--johnbot-bg-native-sidebar);
  }

  .app-frame-edge > .server-rail::before,
  .app-frame-edge > .server-rail::after {
    content: none;
  }

  .app-frame-edge > .sidebar {
    position: relative;
    isolation: isolate;
    border-right: 0;
  }

  .app-frame-edge > .sidebar::before {
    position: absolute;
    z-index: -1;
    content: "";
    pointer-events: none;
  }

  .app-frame-edge .sidebar-topbar {
    border-bottom: 0;
  }

  /* The search sits as far below the panel's top line as it sits in from the side line, which
   * keeps its corner clear of the panel's rounded one. */
  .app-frame-edge .sidebar-search-wrap {
    padding-top: 11px;
  }

  .app-frame-edge .sidebar-compact-search {
    top: 11px;
  }

  .app-frame-edge .conversation-panel,
  .app-frame-edge .direct-conversation {
    isolation: isolate;
  }

  /* The window card draws the top line. */
  .app-frame-edge .conversation-header,
  .app-frame-edge .first-agent-setup-header {
    border-bottom: 0;
    background: transparent;
  }

  /* The routine canvas is in the same card under the same top row. Its board paints its own background. */
  .app-frame-edge .diagram-view-header {
    border-bottom: 0;
    background: transparent;
  }

  .app-frame-edge .diagram-view-body {
    overflow: hidden;
    background: var(--johnbot-bg-canvas);
  }

  /* An open panel's toggle. The faint fill it has elsewhere disappears on the edge, so it takes the
   * ghost button's open fill. An agent at the controls keeps its accent. The side panel toggle has no
   * fill: the panel shows next to it. */
  .app-frame-edge .header-panel-toggle[aria-expanded="true"]:not(.computer-button-agent-active, .side-panel-toggle) {
    border-color: var(--johnbot-border-strong);
    background: var(--johnbot-bg-control-hover);
    color: var(--johnbot-text-primary);
  }

  /* A direct conversation's header is taller on its own, so its line would miss the panel's. */
  .app-frame-edge .direct-conversation-header {
    height: var(--left-header-height);
    border-bottom: 0;
    background: transparent;
  }

  .app-frame-edge .direct-conversation-person .person-avatar {
    width: 26px;
    height: 26px;
  }

  /* The compatibility screen has no header, so it paints the top row and its line itself. */
  .app-frame-edge .remote-compatibility-screen {
    background:
      linear-gradient(var(--johnbot-border-strong), var(--johnbot-border-strong)) 0
      calc(var(--left-header-height) - 1px) / 100% 1px no-repeat,
      linear-gradient(var(--johnbot-bg-native-sidebar), var(--johnbot-bg-native-sidebar)) 0 0 / 100%
      var(--left-header-height) no-repeat;
  }

  /* A side panel is the right part of the window card. Its pseudo-element is the line to the chat. */
  .app-frame-edge .settings-panel,
  .app-frame-edge .browser-panel {
    isolation: isolate;
  }

  .app-frame-edge .settings-panel::before,
  .app-frame-edge .browser-panel::before {
    position: absolute;
    z-index: -1;
    content: "";
    pointer-events: none;
  }

  /* A side panel's header continues the top row at the chat header's height, so the lines meet. The
   * window card draws the line. */
  .app-frame-edge .settings-panel-header,
  .app-frame-edge .file-preview-header,
  .app-frame-edge .browser-preview-header {
    height: var(--left-header-height);
    border-bottom: 0;
    background: transparent;
  }
}

.sidebar-server-name {
  min-width: 0;
  max-width: 100%;
  height: var(--johnbot-control-sm);
  overflow: hidden;
  flex: 0 1 auto;
  justify-content: flex-start;
  gap: var(--johnbot-space-1-5);
  margin-right: auto;
  border-radius: var(--johnbot-radius-pill);
  padding: 0 var(--johnbot-space-2) 0 var(--johnbot-space-1);
  color: var(--johnbot-text-primary);
  cursor: pointer;
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-md);
  opacity: 1;
  text-align: left;
  transition:
    background-color var(--johnbot-duration-hover) ease,
    border-color var(--johnbot-duration-hover) ease,
    color var(--johnbot-duration-hover) ease,
    box-shadow var(--johnbot-duration-hover) ease,
    opacity var(--johnbot-duration-fast) ease;
}

.sidebar-server-name[aria-expanded="true"] {
  background: var(--ui-menu-item-hover);
}

.sidebar-server-name > .sidebar-server-name-mark {
  width: var(--johnbot-icon-lg);
  height: var(--johnbot-icon-lg);
}

/* The logo of a newly selected server springs in. */
.sidebar-server-name-mark[data-entering] {
  animation: sidebar-server-mark-in 420ms cubic-bezier(0.34, 1.36, 0.64, 1) both;
}

/* No overflow clip here: the old name blurs out past the box. The name itself ends in an ellipsis. */
.sidebar-server-name-label {
  min-width: 0;
  flex: 0 1 auto;
  white-space: nowrap;
}

.sidebar-server-name-label > span:not(.ui-swap-leaving) {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sidebar-server-name > .sidebar-server-name-chevron {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: 0 0 auto;
  color: var(--johnbot-text-muted);
}

/* A hosted server that sleeps because nobody used it, or that wakes. The view stays usable. */
.sidebar-server-name > .sidebar-server-name-sleep {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: 0 0 auto;
  color: var(--johnbot-text-muted);
}

.sidebar-server-name > .sidebar-server-name-sleep[data-state="waking"] {
  color: var(--johnbot-accent);
  animation: server-sleep-waking 1200ms ease-in-out infinite;
}

@keyframes sidebar-server-mark-in {
  from {
    opacity: 0;
    scale: 0.6;
    filter: blur(2px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .sidebar-server-name-mark[data-entering] {
    animation: none;
  }
}

/* The server menu view has no rail, so the server name moves right of the macOS traffic lights. The web
 * frame uses the macOS geometry but has no traffic lights, so these rules skip it. */
.app-frame-platform-darwin:not(.app-frame-with-server-rail, .web-app-frame) .sidebar-topbar {
  padding-left: 78px;
}

/* A compact sidebar is too narrow for the traffic lights and the expand button in one row, and the
 * menu view has no rail to hold the traffic lights. The button moves to its own row under them, over
 * the search button. */
.app-frame-platform-darwin:not(.app-frame-with-server-rail, .web-app-frame) .sidebar-compact .sidebar-topbar {
  height: calc(var(--left-header-height) + 36px);
  align-items: flex-end;
  justify-content: center;
  padding: 0 0 2px;
}

.app-frame-platform-darwin:not(.app-frame-with-server-rail, .web-app-frame) .sidebar-compact .sidebar-server-name,
.app-frame-platform-darwin:not(.app-frame-with-server-rail, .web-app-frame) .sidebar-compact .sidebar-new-button {
  display: none;
}

.app-frame-platform-darwin:not(.app-frame-with-server-rail, .web-app-frame) .sidebar-compact .sidebar-toggle-button {
  transform: none;
}

.app-frame-platform-darwin:not(.app-frame-with-server-rail, .web-app-frame)
  .sidebar-compact
  .sidebar-toggle-button:active {
  transform: scale(0.96);
}

.server-menu {
  min-width: 240px;
  max-width: 300px;
  max-height: min(520px, calc(100dvh - 16px), var(--kb-popper-content-available-height, 520px));
  overflow-y: auto;
}

.server-menu-row {
  gap: var(--johnbot-space-2);
}

.server-menu-mark {
  position: relative;
  display: grid;
  width: 20px;
  height: 20px;
  flex: 0 0 auto;
  overflow: hidden;
  place-items: center;
  border-radius: var(--johnbot-radius-pill);
}

.server-menu-mark::after {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--johnbot-text-primary) 12%, transparent);
  content: "";
}

.server-menu-mark > * {
  width: 100%;
  height: 100%;
}

.server-menu-name {
  min-width: 0;
  flex: 1 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.server-menu-muted {
  flex: 0 0 auto;
  color: var(--johnbot-text-secondary);
}

.server-menu-sleep {
  width: 7px;
  height: 7px;
  flex: 0 0 auto;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-text-muted);
}

.server-menu-sleep[data-state="waking"] {
  background: var(--johnbot-accent);
  animation: server-sleep-waking 1200ms ease-in-out infinite;
}

.server-menu .server-menu-layout-chevron {
  margin-left: 0;
}

/* The add item: a dashed circle that fills in on the highlighted row, with the plus cut out of it. */
.ui-action-menu .server-menu-add {
  color: var(--johnbot-text-secondary);
}

.ui-action-menu .server-menu-add:is(:hover, [data-highlighted]) {
  color: var(--johnbot-text-primary);
}

.server-menu-add-circle {
  display: grid;
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  flex: 0 0 auto;
  place-items: center;
  border: 1px dashed color-mix(in srgb, var(--johnbot-text-primary) 30%, transparent);
  border-radius: var(--johnbot-radius-pill);
}

.ui-action-menu .server-menu-add-circle > svg {
  width: var(--ui-menu-inset);
  height: var(--ui-menu-inset);
  stroke-width: 2.5;
}

.ui-action-menu .server-menu-add:is(:hover, [data-highlighted]) .server-menu-add-circle {
  border-color: transparent;
  background: var(--johnbot-text-primary);
}

.ui-action-menu .server-menu-add:is(:hover, [data-highlighted]) .server-menu-add-circle > svg {
  color: var(--ui-menu-bg);
}

.sidebar-topbar-actions {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 3px;
}

.sidebar-icon-button {
  position: relative;
  z-index: 2;
  display: grid;
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  place-items: center;
  border: 0;
  border-radius: var(--johnbot-radius-sm);
  background: transparent;
  color: var(--johnbot-text-muted);
  pointer-events: auto;
  cursor: pointer;
  -webkit-app-region: no-drag;
  transition:
    background-color var(--johnbot-duration-hover) ease,
    color var(--johnbot-duration-hover) ease,
    opacity var(--johnbot-duration-normal) ease,
    transform var(--johnbot-duration-normal) cubic-bezier(0.23, 1, 0.32, 1);
}

.sidebar-icon-button:hover {
  background: var(--johnbot-border);
  color: var(--johnbot-text-primary);
}

.sidebar-icon-button:active {
  transform: scale(0.96);
}

.sidebar-icon-button:focus-visible {
  outline: 1px solid var(--johnbot-text-muted);
  outline-offset: 1px;
}

.header-panel-toggle {
  position: relative;
  z-index: 2;
  display: grid;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  place-items: center;
  border: 1px solid transparent;
  border-radius: var(--johnbot-radius-sm);
  background: transparent;
  color: var(--johnbot-text-muted);
  pointer-events: auto;
  cursor: pointer;
  -webkit-app-region: no-drag;
  transition:
    border-color var(--johnbot-duration-hover) ease,
    background-color var(--johnbot-duration-hover) ease,
    box-shadow var(--johnbot-duration-hover) ease,
    color var(--johnbot-duration-hover) ease,
    transform var(--johnbot-duration-fast) cubic-bezier(0.23, 1, 0.32, 1);
}

.header-panel-toggle:hover {
  border-color: var(--johnbot-border-strong);
  background: var(--johnbot-hover);
  color: var(--johnbot-text-primary);
}

.header-panel-toggle:active {
  transform: scale(0.92);
  transition-duration: var(--johnbot-duration-fast);
}

.header-panel-toggle:focus-visible {
  outline: 1px solid var(--johnbot-text-muted);
  outline-offset: 1px;
}

.sidebar-toggle-icon {
  width: 17px;
  height: 17px;
  fill: none;
  stroke: currentcolor;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.sidebar-marketplace-button > svg {
  width: 18px;
  height: 18px;
  stroke-width: var(--johnbot-icon-stroke);
}

.sidebar-history-button > svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  stroke-width: var(--johnbot-icon-stroke);
}

/* No chat to open in that direction. The arrow stays in its place, so the bar does not move. */
.sidebar-history-button:disabled,
.sidebar-history-button:disabled:hover {
  background: transparent;
  color: var(--johnbot-text-muted);
  cursor: default;
  opacity: 0.4;
}

.sidebar-update-button,
.sidebar-update-button:hover {
  color: var(--johnbot-accent-text);
}

.sidebar-update-button > svg {
  width: 18px;
  height: 18px;
  stroke-width: var(--johnbot-icon-stroke);
}

.sidebar-search-wrap {
  position: relative;
  padding: 8px 12px 6px;
}

/* The field opens the global search, so it is a button drawn as the search field. */
.sidebar-search-trigger {
  width: 100%;
  justify-content: flex-start;
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-regular);
  line-height: 18px;
  cursor: pointer;
}

.sidebar-search-trigger:hover:not(:disabled) {
  border-color: var(--johnbot-text-dim);
  background: var(--johnbot-bg-surface);
  color: var(--johnbot-text-dim);
}

.sidebar-search-placeholder {
  color: var(--johnbot-text-muted);
}

.sidebar-compact-search {
  position: absolute;
  inset: 8px 12px 6px;
  display: grid;
  height: 32px;
  place-items: center;
  border: 0;
  border-radius: var(--johnbot-radius-sm);
  background: transparent;
  color: var(--johnbot-text-muted);
  opacity: 0;
  pointer-events: none;
  transform: translateX(6px) scale(0.96);
  cursor: pointer;
  transition:
    background-color var(--johnbot-duration-hover) ease,
    color var(--johnbot-duration-hover) ease,
    opacity var(--johnbot-duration-fast) ease,
    transform var(--johnbot-duration-slow) cubic-bezier(0.32, 0.72, 0, 1);
}

.sidebar-compact-search:hover {
  background: var(--johnbot-hover);
  color: var(--johnbot-text-primary);
}

.sidebar-compact-search:active {
  transform: scale(0.96);
}

.search-field {
  display: flex;
  height: 32px;
  align-items: center;
  gap: 8px;
  border: 0.5px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-sm);
  background: var(--johnbot-hover);
  padding: 0 9px;
  color: var(--johnbot-text-dim);
  opacity: 1;
  transform: translateX(0);
  transition:
    border-color var(--johnbot-duration-hover) ease,
    background-color var(--johnbot-duration-hover) ease,
    box-shadow var(--johnbot-duration-hover) ease,
    opacity var(--johnbot-duration-fast) ease,
    transform var(--johnbot-duration-slow) cubic-bezier(0.32, 0.72, 0, 1);
}

.search-field:focus-within {
  border-color: var(--johnbot-text-dim);
  background: var(--johnbot-bg-surface);
}

.search-field:has(input:focus-visible) {
  box-shadow: var(--johnbot-focus-ring);
}

.search-field input {
  min-width: 0;
  flex: 1;
  border: 0;
  outline: 0;
  background: transparent;
  box-shadow: none;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  line-height: 18px;
}

.search-field input::placeholder {
  color: var(--johnbot-text-muted);
}

.agent-list {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  overflow-x: hidden;
  overflow-y: auto;
  padding: 4px 12px 0;
  scrollbar-width: none;
}

.agent-list::-webkit-scrollbar {
  display: none;
}

.agent-list-content {
  position: relative;
}

.sidebar-list-context-trigger {
  min-height: 76px;
  flex: 1 0 76px;
}

.sidebar-chat-group + .sidebar-chat-group {
  margin-top: 6px;
  transition: margin-top var(--panel-resize-duration, var(--johnbot-duration-overlay)) cubic-bezier(0.32, 0.72, 0, 1);
}

/**
 * The one drag offset transport. Every row that a drag pushes out of the way - a section, an agent,
 * a person, a pinned tile - writes this pair inline and translates by it, so there is one name to
 * grep and one computation behind it.
 *
 * The reset below is not cosmetic. Custom properties inherit, and agent and person rows sit inside
 * a section that can be shifting itself; without a declaration of their own they would inherit its
 * offset and move twice. Each row's inline style still wins over this reset.
 */
.sidebar-section,
.sidebar-agent-item,
.sidebar-person-item,
.sidebar-pinned-item {
  --sidebar-drag-x: 0px;
  --sidebar-drag-y: 0px;
}

/** Only the rows actually in motion get a layer; the shifting class is toggled per offset. */
.sidebar-drag-shifting {
  will-change: transform;
}

.sidebar-section {
  position: relative;
  border-radius: var(--johnbot-radius-md);
  opacity: 1;
  transform: translate3d(var(--sidebar-drag-x), var(--sidebar-drag-y), 0);
  transition-property: background-color, box-shadow, opacity, transform;
  transition-duration: var(--johnbot-duration-fast);
  transition-timing-function: ease-out;
}

.sidebar-section-agent-drop-target {
  background: var(--johnbot-accent-soft);
  box-shadow: inset 0 0 0 1px var(--johnbot-accent-strong);
}

/* The tint is clear, so the outline takes the colour the tint makes over the surface under it. A
   color-mix blends a clear colour and does not lay it over the other, but for a tint of alpha a, a share
   of 1 / (2 - a) made opaque gives the same colour. 54% is within two steps of that for the 12% and
   16% tints. A row with its own fill sets the outline again. */
:is(.sidebar-section-agent-drop-target, .sidebar-pinned-group-agent-drop-target) {
  --agent-avatar-outline-tinted: color-mix(
    in srgb,
    var(--johnbot-accent-soft) 54%,
    var(--agent-avatar-outline, transparent)
  );
}

:is(.sidebar-section-agent-drop-target, .sidebar-pinned-group-agent-drop-target) > * {
  --agent-avatar-outline: color(from var(--agent-avatar-outline-tinted) srgb r g b / 1);
}

.sidebar-section-drop-before::before,
.sidebar-section-drop-after::after {
  position: absolute;
  z-index: 3;
  right: 7px;
  left: 7px;
  height: 2px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-accent-text);
  box-shadow: 0 0 0 1px var(--johnbot-bg-sidebar);
  content: "";
  pointer-events: none;
}

.sidebar-section-drop-before::before {
  top: -4px;
}

.sidebar-section-drop-after::after {
  bottom: -4px;
}

/* The dragged header keeps pointer events: Chromium ends a native drag at once when its source
 * stops taking them. */
.sidebar-section-dragging {
  opacity: 0;
  transition: none;
}

.sidebar-section-dragging {
  will-change: transform;
}

.sidebar-section-dragging * {
  animation-play-state: paused;
}

.sidebar-chat-group > header {
  display: flex;
  height: 32px;
  overflow: hidden;
  align-items: center;
  justify-content: space-between;
  padding: 0;
  opacity: 1;
  transform: translateY(0);
  transition:
    height var(--panel-resize-duration, var(--johnbot-duration-overlay)) cubic-bezier(0.32, 0.72, 0, 1),
    opacity var(--johnbot-duration-fast) ease,
    transform var(--johnbot-duration-slow) cubic-bezier(0.32, 0.72, 0, 1);
}

.sidebar-section-drag-handle,
.sidebar-agent-item .agent-row,
.sidebar-person-item .person-row {
  cursor: grab;
  touch-action: pan-y;
}

.agent-list[data-sidebar-dragging],
.agent-list[data-sidebar-dragging] .sidebar-section-drag-handle,
.agent-list[data-sidebar-dragging] .sidebar-section-toggle,
.agent-list[data-sidebar-dragging] .agent-row,
.agent-list[data-sidebar-dragging] .person-row {
  cursor: grabbing;
}

.agent-list[data-sidebar-dragging="chat"] .sidebar-section-toggle,
.agent-list[data-sidebar-dragging="person"] .sidebar-section-toggle {
  pointer-events: none;
}

.agent-list[data-sidebar-dragging] .sidebar-section-toggle:hover,
.agent-list[data-sidebar-dragging] .sidebar-section-toggle:focus-visible {
  background: transparent;
  color: var(--johnbot-text-readable);
}

.agent-list[data-sidebar-dragging] .sidebar-section-toggle:hover .sidebar-section-chevron,
.agent-list[data-sidebar-dragging] .sidebar-section-toggle:focus-visible .sidebar-section-chevron {
  opacity: 0;
}

.sidebar-section-toggle {
  display: flex;
  width: 100%;
  min-width: 0;
  height: 32px;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  border-radius: var(--johnbot-radius-md);
  padding: 0 7px;
  background: transparent;
  color: var(--johnbot-text-readable);
  transition-property: color;
  transition-duration: var(--johnbot-duration-hover);
  transition-timing-function: ease-out;
}

.sidebar-section-toggle:hover,
.sidebar-section-toggle:focus-visible {
  background: transparent;
  color: var(--johnbot-text-secondary);
}

.sidebar-section-toggle[aria-expanded="true"] {
  background: transparent;
}

.sidebar-section-toggle:active {
  scale: 0.96;
}

.sidebar-section-name {
  min-width: 0;
  overflow: hidden;
  font-size: var(--johnbot-text-sm);
  font-weight: 400;
  line-height: 16px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sidebar-section-chevron {
  flex: 0 0 auto;
  opacity: 0;
  transform: rotate(0deg);
  transition:
    opacity var(--johnbot-duration-hover) ease-out,
    transform var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.sidebar-section-toggle:hover .sidebar-section-chevron,
.sidebar-section-toggle:focus-visible .sidebar-section-chevron {
  opacity: 1;
}

.sidebar-section-chevron-collapsed {
  transform: rotate(-90deg);
}

.sidebar-section-collapse {
  display: grid;
  opacity: 1;
  grid-template-rows: 1fr;
  transition-property: grid-template-rows, opacity;
  transition-duration: var(--johnbot-duration-normal), var(--johnbot-duration-fast);
  transition-timing-function: var(--johnbot-ease-out), ease-out;
}

.sidebar-section-collapse[data-collapsed] {
  opacity: 0;
  grid-template-rows: 0fr;
}

.sidebar-section-body {
  min-height: 0;
  overflow: hidden;
}

.sidebar-section-editor-wrap {
  position: relative;
  width: 100%;
}

/* "Needs you" is not a section, so its heading is plain text with a count, and a rule ends it. */
.sidebar-waiting-group {
  border-bottom: 1px solid var(--johnbot-border);
  padding-bottom: var(--johnbot-space-2);
}

.sidebar-waiting-group-name {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-2);
  margin: 0;
  padding: 0 7px;
  color: var(--johnbot-text-readable);
  font-size: var(--johnbot-text-sm);
  font-weight: 400;
  line-height: 16px;
  white-space: nowrap;
}

.sidebar-waiting-group-count {
  display: inline-grid;
  min-width: 16px;
  height: 16px;
  place-items: center;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-warning);
  padding: 0 4px;
  color: var(--johnbot-bg-sidebar);
  font-size: var(--johnbot-text-sm);
  font-weight: 650;
}

.sidebar-hidden-group-count {
  margin-inline-start: var(--johnbot-space-1);
  font-variant-numeric: tabular-nums;
}

.sidebar-chat-group > .sidebar-section-editor-wrap {
  height: 36px;
}

.sidebar-section-editor {
  width: 100%;
  height: 36px;
  border-color: var(--johnbot-border-focus);
  border-radius: var(--johnbot-radius-md);
  padding: 0 32px 0 8px;
  background: var(--johnbot-bg-control);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
}

.sidebar-section-editor[aria-invalid="true"] {
  border-color: var(--johnbot-danger);
}

.sidebar-section-editor-chevron {
  position: absolute;
  top: 50%;
  right: 9px;
  color: var(--johnbot-text-muted);
  pointer-events: none;
  transform: translateY(-50%);
}

.sidebar-section-draft {
  min-height: 36px;
}

.sidebar-agent-drag-preview,
.sidebar-person-drag-preview,
.sidebar-section-drag-preview {
  position: fixed;
  z-index: var(--johnbot-layer-dropdown);
  box-sizing: border-box;
  margin: 0;
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-surface-raised);
  box-shadow: var(--johnbot-shadow-raised);
  opacity: 0.96;
  pointer-events: none;
  transform: none;
  transition: none;
}

.sidebar-agent-drag-preview *,
.sidebar-person-drag-preview *,
.sidebar-section-drag-preview * {
  animation: none;
  transition: none;
}

.sidebar-section-drag-preview.sidebar-section-toggle {
  background: var(--johnbot-bg-surface-raised);
  color: var(--johnbot-text-secondary);
}

.agent-row.sidebar-agent-drag-preview {
  --agent-avatar-outline: var(--johnbot-bg-surface-raised);

  background: var(--johnbot-bg-surface-raised);
  transition: none;
}

.agent-row.sidebar-person-drag-preview {
  --agent-avatar-outline: var(--johnbot-bg-surface-raised);

  background: var(--johnbot-bg-surface-raised);
  transition: none;
}

.agent-row.sidebar-agent-drag-preview *,
.agent-row.sidebar-person-drag-preview * {
  animation: none;
  transition: none;
}

.sidebar-agent-item {
  position: relative;
  transform: translate3d(var(--sidebar-drag-x), var(--sidebar-drag-y), 0);
  transition: transform var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.sidebar-agent-item + .sidebar-agent-item {
  margin-top: 4px;
}

.sidebar-agent-item-dragging {
  will-change: transform;
}

.agent-list[data-sidebar-dragging="chat"] .sidebar-agent-item {
  transition: none;
  will-change: transform;
}

.agent-list[data-sidebar-dragging="person"] .sidebar-person-item {
  will-change: transform;
}

.sidebar-agent-item-dragging {
  z-index: 1;
  opacity: 0;
  transition: none;
}

.sidebar-person-item-dragging {
  pointer-events: none;
}

.sidebar-agent-row-dragging * {
  animation-play-state: paused;
}

.sidebar-agent-row-dragging {
  opacity: 0;
  transition: none;
}

.sidebar-person-item {
  position: relative;
  transform: translate3d(var(--sidebar-drag-x), var(--sidebar-drag-y), 0);
  transition: transform var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.sidebar-person-item + .sidebar-person-item {
