}

.agent-row-avatar {
  position: relative;
  display: grid;
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  place-items: center;
  transform: translateX(0);
  transition: transform var(--panel-resize-duration, var(--johnbot-duration-overlay)) cubic-bezier(0.32, 0.72, 0, 1);
}

/* A hidden agent sleeps, so its face is faded and has no colour. */
.sidebar-agent-item-user-hidden .agent-row-avatar {
  opacity: 0.5;
  filter: grayscale(1);
}

.agent-row-agent-status {
  position: absolute;
  z-index: 1;
  right: -5px;
  bottom: -3px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--johnbot-bg-sidebar);
  box-shadow: 0 1px 3px var(--johnbot-shadow-popover-ambient);
  pointer-events: none;
}

.agent-row-active .agent-row-agent-status {
  border-color: var(--johnbot-bg-control);
}

.agent-row-agent-status-working {
  width: 24px;
  height: 16px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-surface);
  color: var(--johnbot-text-secondary);
}

.agent-row-thinking-dots {
  display: inline-flex;
  align-items: center;
  gap: 2px;
}

.agent-row-thinking-dots i {
  width: 3px;
  height: 3px;
  border-radius: var(--johnbot-radius-pill);
  background: currentColor;
  --typing-dot-travel: -1px;
  animation: typing-dot-pulse 900ms ease-in-out infinite;
}

.agent-row-thinking-dots i:nth-child(2) {
  animation-delay: var(--johnbot-duration-fast);
}

.agent-row-thinking-dots i:nth-child(3) {
  animation-delay: var(--johnbot-duration-overlay);
}

.agent-row-agent-status-responded {
  width: 16px;
  height: 16px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-success);
  color: var(--johnbot-success);
}

.agent-row-agent-status-responded svg {
  width: 10px;
  height: 10px;
  fill: none;
  stroke: currentColor;
  stroke-width: var(--johnbot-icon-stroke);
  stroke-linecap: round;
  stroke-linejoin: round;
}

.agent-row-agent-status-unread {
  min-width: 16px;
  height: 16px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-text-primary);
  padding: 0 3px;
  color: var(--johnbot-bg-sidebar);
  font-size: var(--johnbot-text-sm);
  font-weight: 650;
  line-height: 12px;
}

.agent-row-agent-status-routine,
.agent-row-agent-status-limited {
  width: 16px;
  height: 16px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-surface);
  color: var(--johnbot-text-secondary);
}

.agent-row-agent-status-routine svg,
.agent-row-agent-status-limited svg {
  width: 10px;
  height: 10px;
}

.agent-row-agent-status-routine-failed {
  color: var(--johnbot-danger);
}

/* An agent that waits for the user: amber, and a little larger than the routine marks, so it is
   the first badge the eye finds in a busy list. */
.agent-row-agent-status-waiting {
  width: 18px;
  height: 18px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-warning);
  color: var(--johnbot-bg-sidebar);
}

.agent-row-agent-status-waiting svg {
  width: 11px;
  height: 11px;
}

/* The action chip takes the time slot: the time does not matter while the agent waits. */
.agent-row-wait-chip {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 3px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-warning-soft);
  padding: 1px 7px 1px 5px;
  color: var(--johnbot-warning-text);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-semibold);
  line-height: 16px;
  white-space: nowrap;
}

.agent-row-wait-chip svg {
  width: 11px;
  height: 11px;
}

/* The tooltip anchors to this wrapper, so it needs a box of its own. */
.sidebar-agent-tooltip-trigger {
  display: block;
}

.sidebar-wait-tooltip {
  z-index: var(--johnbot-layer-tooltip);
  display: grid;
  max-width: min(260px, calc(100vw - 16px));
  gap: 2px;
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-sm);
  background: var(--johnbot-bg-surface-raised);
  box-shadow: var(--johnbot-shadow-raised);
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
  pointer-events: none;
}

.sidebar-wait-tooltip-title {
  display: inline-flex;
  align-items: center;
  gap: var(--johnbot-space-1);
  color: var(--johnbot-warning-text);
  font-weight: var(--johnbot-weight-semibold);
}

.sidebar-wait-tooltip-title svg {
  width: 14px;
  height: 14px;
}

.sidebar-wait-tooltip-detail {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4;
  overflow-wrap: anywhere;
}

.sidebar-wait-tooltip-hint {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

.agent-row-agent-status-entering {
  animation: sidebar-reply-in var(--johnbot-duration-overlay) cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes typing-dot-pulse {
  0%,
  60%,
  100% {
    opacity: 0.34;
    transform: translateY(0);
  }

  30% {
    opacity: 1;
    transform: translateY(var(--typing-dot-travel, -2px));
  }
}

@keyframes sidebar-reply-in {
  from {
    opacity: 0;
    transform: scale(0.55);
  }
}

.agent-context-submenu-chevron {
  margin-left: auto;
  color: var(--johnbot-text-muted);
}

.agent-context-submenu {
  max-height: min(520px, calc(100vh - 16px));
  overflow-y: auto;
}

@keyframes agent-context-in {
  from {
    opacity: 0;
    transform: scale(0.96) translateY(-3px);
  }
}

.agent-avatar {
  display: grid;
  width: 32px;
  height: 32px;
  flex: 0 0 auto;
  place-items: center;
  border: 0;
  border-radius: var(--johnbot-radius-pill);
  color: currentColor;
  overflow: visible;
}

.agent-avatar > svg {
  display: block;
  width: 128%;
  height: 128%;
  overflow: visible;
  translate: var(--agent-avatar-optical-offset-x, 0) var(--agent-avatar-optical-offset, 0);
}

/* The outline: a ring in the colour of the surface under the avatar, so a face that overlaps another
   face, a badge or a row edge reads as cut out of it. The surface sets `--agent-avatar-outline` where
   it sets its background; under any other the ring stays transparent, because a ring that misses the
   colour behind it shows as a halo. The ring is a stroke on the silhouette the Bloub paints first, the
   paper under its eyes. It is drawn behind that fill, so only the outer half shows, and it does not
   scale with the drawing, so the width is in pixels at every avatar size. */
.bloub-avatar-svg > g:nth-of-type(2) > path:first-child {
  stroke: var(--agent-avatar-outline, transparent);
  stroke-width: calc(var(--agent-avatar-outline-width, 1.5px) * 2);
  stroke-linejoin: round;
  paint-order: stroke fill;
  vector-effect: non-scaling-stroke;
}

/* A photo has no silhouette to stroke, so the same ring is an outline on its circle. */
.agent-avatar-custom {
  overflow: hidden;
  outline: var(--agent-avatar-outline-width, 1.5px) solid var(--agent-avatar-outline, transparent);
  background: var(--johnbot-hover);
  box-shadow: inset 0 0 0 1px var(--johnbot-border);
}

.agent-avatar-custom > img,
.composer-mention-avatar > img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* A mood that flies rings. They sit outside the circle, so the parent stops
   clipping and the image rounds itself instead. */
.agent-avatar[data-avatar="image"]:is([data-mood="working"], [data-mood="connecting"]) {
  position: relative;
  overflow: visible;
}

.agent-avatar[data-avatar="image"]:is([data-mood="working"], [data-mood="connecting"]) > img {
  border-radius: var(--johnbot-radius-pill);
}

/* Breathing, as a scale on the whole avatar. It is deliberately not a silhouette
   edit: the shape an agent is recognised by has to survive every mood, so the
   only thing allowed to move here is the box the shape is drawn in. The amplitude
   comes from the mood table, and 0 - every mood but `working` - holds still. */
.agent-avatar[data-breathe] {
  animation: agent-avatar-breathe 2.6s ease-in-out infinite;
}

@keyframes agent-avatar-breathe {
  0%,
  100% {
    scale: calc(1 - var(--agent-avatar-breathe, 0));
  }

  50% {
    scale: calc(1 + var(--agent-avatar-breathe, 0));
  }
}

/* The mood glow. It reads before the face does at sidebar sizes, and it never
   touches the Bloub's own colour, which is identity and comes from the seed. */
.agent-avatar[data-mood="waiting"] {
  filter: drop-shadow(0 0 3px var(--johnbot-accent));
}

.agent-avatar[data-mood="failed"] {
  filter: drop-shadow(0 0 3px var(--johnbot-danger));
}

/* The glow would start outside the outline and leave a dark line round the face. A glowing face is
   never in a group, so it has nothing to be cut out of. */
.agent-avatar:is([data-mood="waiting"], [data-mood="failed"]) {
  --agent-avatar-outline: transparent;
}

.agent-avatar[data-mood="asleep"] {
  opacity: 0.6;
}

@media (prefers-reduced-motion: reduce) {
  .agent-avatar[data-breathe] {
    animation: none;
  }
}

/* The rings reach 1.4 ball radii, which is the margin the Bloub viewBox carries
   past its body: 316 units drawn over the 200 the image fills, so the layer is
   158% of the avatar box and sits (158% - 100%) / 2 outside it on each side. */
.agent-avatar > .agent-avatar-arcs {
  position: absolute;
  inset: -29%;
  width: auto;
  height: auto;
  overflow: visible;
  translate: none;
}

.agent-row .agent-avatar {
  --agent-avatar-optical-offset: -4px;

  width: 36px;
  height: 36px;
}

.person-row .person-avatar {
  width: 36px;
  height: 36px;
}

.avatar-editor {
  position: relative;
  z-index: var(--johnbot-layer-popover);
  width: min(284px, calc(var(--settings-panel-width, 360px) - 30px));
  max-width: calc(100vw - 24px);
  margin: 0;
  overflow: hidden;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-overlay);
  box-shadow:
    0 22px 60px var(--johnbot-bg-overlay),
    0 3px 12px var(--johnbot-shadow-popover-ambient),
    inset 0 1px var(--johnbot-hover);
  backdrop-filter: blur(18px);
  transform-origin: var(--kb-popover-content-transform-origin);
  animation: avatar-editor-in var(--johnbot-duration-normal) cubic-bezier(0.23, 1, 0.32, 1) both;
}

@keyframes avatar-editor-in {
  from {
    opacity: 0;
    transform: translateY(-5px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.avatar-editor-divider {
  height: 1px;
  background: var(--johnbot-border);
}

.avatar-editor-heading {
  display: flex;
  min-height: 40px;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 7px 10px 3px 13px;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  font-weight: 590;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.avatar-editor-heading > span {
  white-space: nowrap;
}

.avatar-editor-actions {
  display: flex;
  align-items: center;
  gap: 2px;
}

.avatar-editor-actions button {
  min-height: 40px;
  border: 0;
  border-radius: var(--johnbot-radius-md);
  background: transparent;
  padding: 0 9px;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  font-weight: 540;
  transition-property: scale, background-color, color;
  transition-duration: var(--johnbot-duration-normal), var(--johnbot-duration-hover), var(--johnbot-duration-hover);
  transition-timing-function: ease-out;
}

.avatar-editor-actions .ui-icon-button {
  width: var(--johnbot-control-xl);
  padding: 0;
}

.avatar-editor-actions button:hover {
  background: var(--johnbot-hover);
  color: var(--johnbot-text-primary);
}

.avatar-editor-actions button:disabled,
.avatar-image-upload:disabled {
  cursor: wait;
  opacity: 0.58;
}

.avatar-image-upload {
  display: grid;
  width: calc(100% - 20px);
  min-height: 64px;
  align-items: center;
  margin: 4px 10px 12px;
  border: 1px dashed var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-hover);
  padding: 9px;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 11px;
  color: var(--johnbot-text-primary);
  text-align: left;
  transition:
    border-color var(--johnbot-duration-hover) ease,
    background-color var(--johnbot-duration-hover) ease,
    transform var(--johnbot-duration-normal) ease;
}

.avatar-image-upload:hover:not(:disabled) {
  border-color: var(--johnbot-success);
  background: var(--johnbot-success-soft);
}

.avatar-image-upload:active:not(:disabled) {
  transform: scale(0.985);
}

.avatar-image-upload-active {
  border-style: solid;
  border-color: var(--johnbot-border-strong);
}

.avatar-image-upload-preview {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  overflow: hidden;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-hover);
  color: var(--johnbot-text-muted);
}

.avatar-image-upload-preview > svg {
  width: 19px;
  height: 19px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-width: var(--johnbot-icon-stroke);
}

.avatar-image-upload-preview .agent-avatar {
  width: 42px;
  height: 42px;
}

.avatar-image-upload strong,
.avatar-image-upload small {
  display: block;
  white-space: normal;
  text-wrap: pretty;
}

.avatar-image-upload strong {
  margin-bottom: 3px;
  font-size: var(--johnbot-text-sm);
  font-weight: 580;
}

.avatar-image-upload small {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: 14px;
}

.avatar-editor-actions button:active,
.avatar-face-choice:active,
.avatar-color-choice:active {
  scale: 0.96;
}

.avatar-face-grid {
  display: grid;
  min-width: 0;
  margin: 0;
  border: 0;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  padding: 7px 10px 12px;
}

.avatar-face-choice,
.avatar-color-choice {
  display: grid;
  place-items: center;
  border: 1px solid transparent;
  border-radius: var(--johnbot-radius-md);
  background: transparent;
  color: var(--johnbot-text-secondary);
  transition-property: scale, background-color, box-shadow;
  transition-duration: var(--johnbot-duration-normal), var(--johnbot-duration-hover), var(--johnbot-duration-hover);
  transition-timing-function: ease-out;
}

.avatar-face-choice {
  width: 100%;
  height: 48px;
}

.avatar-face-choice:hover,
.avatar-color-choice:hover {
  background: var(--johnbot-hover);
}

.avatar-choice-selected {
  background: var(--johnbot-border);
  box-shadow:
    inset 0 0 0 1px var(--johnbot-text-muted),
    0 1px 3px var(--johnbot-shadow-popover-ambient);
}

.avatar-face-choice .agent-avatar {
  width: 34px;
  height: 34px;
}

.avatar-color-grid {
  display: grid;
  min-width: 0;
  margin: 0;
  border: 0;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 5px;
  padding: 4px 10px 12px;
}

.avatar-color-choice {
  width: 100%;
  height: 40px;
}

.avatar-color-swatch {
  display: block;
  width: 18px;
  height: 18px;
  border-radius: var(--johnbot-radius-pill);
  box-shadow: inset 0 0 0 1px var(--johnbot-border-strong);
}

.avatar-color-swatch-auto {
  display: grid;
  place-items: center;
  border: 1px dashed var(--johnbot-text-muted);
  background: transparent;
  box-shadow: none;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  font-weight: 650;
}

.conversation-title .agent-avatar {
  --agent-avatar-optical-offset: -2px;

  width: 18px;
  height: 18px;
}

.agent-row-copy {
  min-width: 0;
  flex: 1;
  opacity: 1;
  transform: translateX(0);
  transition:
    opacity var(--johnbot-duration-fast) ease,
    transform var(--johnbot-duration-slow) cubic-bezier(0.32, 0.72, 0, 1);
}

.agent-row-heading {
  display: flex;
  min-width: 0;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.agent-row-title {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 5px;
  overflow: hidden;
}

.agent-row-title:has(.agent-role-badge) {
  --agent-role-badge-collapsed-width: calc(2ch + 9px);

  display: grid;
  grid-template-columns:
    fit-content(calc(100% - var(--agent-role-badge-collapsed-width) - 5px))
    minmax(var(--agent-role-badge-collapsed-width), 1fr);
}

.agent-row-name {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 3px;
  overflow: hidden;
}

.agent-row-access {
  display: inline-flex;
  flex: none;
  color: var(--johnbot-text-muted);
}

.agent-row-access svg {
  width: 12px;
  height: 12px;
}

.agent-row-title strong,
.person-row .agent-row-heading strong,
.channel-row .agent-row-heading strong {
  min-width: 0;
  overflow: hidden;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
  line-height: 20px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-role-badge {
  min-width: 0;
  max-width: 100%;
  height: 18px;
  min-height: 18px;
  overflow: hidden;
  flex: 0 1 auto;
  justify-self: start;
  border: 0.5px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-xs);
  background: var(--johnbot-hover);
  padding: 2px 4px;
  color: var(--johnbot-text-readable);
  font-size: var(--johnbot-text-sm);
  font-weight: 400;
  line-height: 16px;
  white-space: nowrap;
}

.agent-role-badge > span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-row-time,
.person-row .agent-row-heading > span,
.channel-row .agent-row-time {
  min-width: 0;
  flex: 0 0 auto;
  color: var(--johnbot-text-readable);
  font-size: var(--johnbot-text-sm);
  line-height: 16px;
  white-space: nowrap;
}

/* At the default width and below, the wait chip keeps only its icon so that a long name keeps its
   space. The row's label and tooltip still name the action. */
@container (max-width: 300px) {
  .agent-row-wait-chip:has(.agent-row-wait-chip-label) {
    padding: 1px 5px;
  }

  .agent-row-wait-chip-label {
    display: none;
  }
}

/* Narrow panel: name and badge win over time and date. The time element keeps
   no reserved width, so long names get the space instead of truncating to a
   few characters beside a date. */
@container (max-width: 210px) {
  .agent-row-time,
  .person-row .agent-row-heading > span,
  .channel-row .agent-row-time {
    display: none;
  }
}

.agent-row-preview {
  display: block;
  margin-top: 0;
  overflow: hidden;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  line-height: 18px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The reference list extends agent tiles beyond the chat-list inset while the
   shared row anatomy supplies its 54px row and 36px avatar proportions. */
.sidebar:not(.sidebar-compact) .agent-row {
  width: calc(100% + var(--johnbot-space-2));
  margin-inline: calc(var(--johnbot-space-1) * -1);
}

.sidebar:not(.sidebar-compact) .sidebar-section-body .agent-row {
  width: 100%;
  margin-inline: 0;
}

.sidebar:not(.sidebar-compact) .sidebar-waiting-group .agent-row {
  width: 100%;
  margin-inline: 0;
}

/* A waiting row does not drag, so it does not show the grab cursor. */
.sidebar-waiting-group .sidebar-agent-item .agent-row {
  cursor: default;
}

.sidebar:not(.sidebar-compact) .sidebar-pinned-row.agent-row {
  width: 72px;
  margin-inline: 0;
}

.empty-search {
  margin: 32px 0;
  color: var(--johnbot-text-readable);
  font-size: var(--johnbot-text-md);
  text-align: center;
}

.sidebar-first-agent-state {
  display: flex;
  min-height: 100%;
  flex-direction: column;
}

.ui-button.sidebar-first-agent-action {
  flex: 0 0 auto;
}

.account-usage-popover {
  position: relative;
  z-index: var(--johnbot-layer-tooltip);
  display: grid;
  width: min(300px, calc(100vw - var(--johnbot-space-4)));
  max-height: min(60vh, 420px);
  overflow: auto;
  padding: var(--johnbot-space-2);
  gap: var(--johnbot-space-2);
  opacity: 1;
  transform: translateY(0) scale(1);
  transform-origin: var(--kb-popover-content-transform-origin);
  transition:
    opacity var(--johnbot-duration-fast) ease,
    transform var(--johnbot-duration-fast) var(--johnbot-ease-out);

  @starting-style {
    opacity: 0;
    transform: translateY(4px) scale(0.98);
  }
}

.account-usage-popover-header,
.account-usage-popover-heading {
  display: flex;
  align-items: center;
}

.account-usage-popover-header {
  justify-content: space-between;
}

.account-usage-popover-heading {
  min-width: 0;
  /* Match the horizontal padding of a provider row, so the gauge icon lines up
     with the provider logos below it. */
  padding-inline-start: var(--johnbot-space-1);
  gap: var(--johnbot-space-2);
}

.account-usage-popover-heading > svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  flex: 0 0 auto;
  color: var(--johnbot-text-primary);
  stroke-width: var(--johnbot-icon-stroke);
}

.account-usage-popover-title {
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-md);
}

/* Columns: logo, window label, bar, percent left, reset countdown. Each provider row and each
   window row is a subgrid, so the bars line up across providers. */
.account-usage-providers {
  display: grid;
  margin: 0;
  padding: 0;
  grid-template-columns: auto max-content minmax(0, 1fr) max-content max-content;
  column-gap: var(--johnbot-space-2);
  row-gap: var(--johnbot-space-1);
  list-style: none;
}

.account-usage-provider {
  display: grid;
  min-width: 0;
  align-items: center;
  border-radius: var(--johnbot-radius-md);
  padding: var(--johnbot-space-1);
  grid-column: 1 / -1;
  grid-template-columns: subgrid;
  row-gap: var(--johnbot-space-1);
}

.account-usage-provider > .account-usage-provider-name {
  grid-column: 2 / -1;
}

.account-usage-provider-logo {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  flex: 0 0 auto;
  overflow: visible;
  fill: var(--johnbot-provider-current);
}

.account-usage-provider-copy {
  display: grid;
  min-width: 0;
  grid-column: 2 / 4;
}

.account-usage-provider-name {
  overflow: hidden;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.account-usage-provider-meta {
  overflow: hidden;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.account-usage-provider-remaining {
  grid-column: 4 / -1;
  justify-self: end;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-semibold);
  font-variant-numeric: tabular-nums;
  line-height: var(--johnbot-leading-sm);
  white-space: nowrap;
}

.account-usage-windows,
.account-usage-window {
  display: grid;
  min-width: 0;
  grid-template-columns: subgrid;
}

.account-usage-windows {
  grid-column: 2 / -1;
  row-gap: var(--johnbot-space-1);
}

.account-usage-window {
  --account-usage-window-tone: var(--johnbot-text-secondary);

  align-items: center;
  grid-column: 1 / -1;
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.account-usage-window[data-usage-tone="warning"] {
  --account-usage-window-tone: var(--johnbot-warning);
}

.account-usage-window[data-usage-tone="critical"] {
  --account-usage-window-tone: var(--johnbot-danger);
}

.account-usage-window-label,
.account-usage-window-reset {
  color: var(--johnbot-text-muted);
  white-space: nowrap;
}

.account-usage-window-reset {
  text-align: right;
}

.account-usage-window-bar {
  display: block;
  height: 4px;
  overflow: hidden;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-border);
}

.account-usage-window-fill {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--account-usage-window-tone);
}

.account-usage-window-remaining {
  color: var(--johnbot-text-primary);
  font-variant-numeric: tabular-nums;
  font-weight: var(--johnbot-weight-semibold);
  text-align: right;
}

.account-usage-window:not([data-usage-tone="neutral"]) .account-usage-window-remaining {
  color: var(--account-usage-window-tone);
}

.account-usage-empty {
  margin: 0;
  padding: var(--johnbot-space-2) var(--johnbot-space-1);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.account-usage-refresh.ui-button {
  position: relative;
  width: var(--johnbot-control-md);
  height: var(--johnbot-control-md);
  flex: 0 0 auto;
  border-radius: var(--johnbot-radius-md);
  color: var(--johnbot-text-muted);
}

.account-usage-refresh.ui-button::before {
  position: absolute;
  inset: calc(0px - var(--johnbot-space-1));
  content: "";
}

.account-usage-refresh > svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  stroke-width: var(--johnbot-icon-stroke);
  transition: transform var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

.account-usage-refresh > svg.icon-spinning {
  animation-duration: 600ms;
}

.account-usage-popover-error {
  margin: 0;
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-danger-soft);
  padding: var(--johnbot-space-2);
  color: var(--johnbot-danger);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.sidebar-compact .sidebar-topbar {
  padding-inline: 12px;
}

.sidebar-compact .sidebar-server-name {
  opacity: 0;
  pointer-events: none;
}

.sidebar-compact .sidebar-new-button {
  opacity: 0;
  pointer-events: none;
  transform: translateX(6px) scale(0.92);
}

.sidebar-compact .sidebar-toggle-button {
  transform: translateX(13px);
}

.sidebar-compact .sidebar-toggle-button:active {
  transform: translateX(13px) scale(0.96);
}

.sidebar-compact .sidebar-search-wrap {
  padding-inline: 12px;
}

.sidebar-compact .search-field {
  opacity: 0;
  pointer-events: none;
  transform: translateX(-8px);
}

.sidebar-compact .sidebar-compact-search {
  opacity: 1;
  pointer-events: auto;
  transform: translateX(0) scale(1);
  transition-delay: 55ms;
}

.sidebar-compact .agent-list {
  padding-inline: 12px;
}

.sidebar-compact .sidebar-chat-group {
  position: relative;
}

.sidebar-compact .sidebar-chat-group + .sidebar-chat-group {
  margin-top: 4px;
}

.sidebar-compact .sidebar-chat-group > header {
  height: 0;
  overflow: hidden;
  opacity: 0;
  transform: translateY(-4px);
  white-space: nowrap;
}

.sidebar-compact .agent-row {
  padding-inline: 8px;
}

.sidebar-compact .agent-row-avatar {
  transform: translateX(6px);
}

.sidebar-compact .agent-row.sidebar-pinned-row {
  width: 60px;
  height: 60px;
  min-height: 60px;
  padding: 6px;
}

.sidebar-compact .sidebar-pinned-item {
  width: 60px;
  flex-basis: 60px;
}

.sidebar-compact .agent-row.sidebar-pinned-row .sidebar-pinned-avatar {
  transform: none;
}

.sidebar-compact .sidebar-pinned-copy {
  display: none;
}

.sidebar-compact .agent-row-copy {
  opacity: 0;
  pointer-events: none;
  transform: translateX(-8px);
}

.icon-spinning {
  animation: account-update-spin 800ms linear infinite;
}

@keyframes account-update-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .server-rail-mark,
  .server-rail-server-item,
  .sidebar-section,
  .sidebar-pinned-item {
    transition: none;
  }

  .sidebar-section-chevron,
  .sidebar-section-collapse,
  .sidebar-section-toggle,
  .sidebar-pinned-group-empty-target,
  .sidebar-pinned-empty-drop {
    transition: none;
  }

  .account-usage-popover {
    transform: none;
    transition: opacity var(--johnbot-duration-fast) ease;

    @starting-style {
      opacity: 0;
      transform: none;
    }
  }

  .account-usage-refresh > svg {
    transition: none;
  }

  .account-usage-refresh:hover:not(:disabled) > svg {
    transform: none;
  }

  .icon-spinning {
    animation-duration: 1.6s;
  }
}

.server-rail,
.sidebar {
  background: var(--johnbot-bg-sidebar);
}

.sidebar {
  --agent-avatar-outline: var(--johnbot-bg-sidebar);
}

.server-rail-monogram,
.server-rail-action .server-rail-monogram {
  border-color: var(--johnbot-border);
  background: var(--johnbot-bg-surface);
  color: var(--johnbot-text-secondary);
}

.sidebar-icon-button:hover,
.header-panel-toggle:hover,
.browser-toolbar-button:hover:not(:disabled),
.message-action-button:hover,
.message-action-button:focus-visible,
.message-action-button[aria-expanded="true"],
.reaction-picker-row button:hover,
.reaction-picker-row button:focus-visible,
.reaction-picker-row button[aria-checked="true"],
.composer-button:hover,
.composer-attachment > button:hover,
.agent-context-menu button:hover,
.agent-context-menu button:focus-visible {
  background: var(--johnbot-bg-control-hover);
  color: var(--johnbot-text-primary);
}

.sidebar-icon-button:active,
.header-panel-toggle:active,
.agent-row:active,
.composer-button:active,
.voice-button:active,
.settings-panel-nav-button:active {
  transform: scale(0.97);
}

.agent-row:hover {
  --agent-avatar-outline: var(--johnbot-bg-control);

  background: var(--johnbot-bg-control);
}

.agent-list[data-sidebar-dragging] .agent-row:hover {
  --agent-avatar-outline: inherit;

  background: transparent;
}

.agent-list[data-sidebar-dragging] .agent-row.agent-row-active,
.agent-list[data-sidebar-dragging] .agent-row.agent-row-active:hover {
  --agent-avatar-outline: var(--johnbot-bg-surface);

  background: var(--johnbot-bg-surface);
}

.settings-panel-content {
  color: var(--johnbot-text-primary);
}

.agent-settings-notifications,
.provider-model-panel,
.provider-model-rail,
.avatar-editor {
  border-color: var(--johnbot-border);
  background: var(--johnbot-bg-surface);
  color: var(--johnbot-text-primary);
}

.choice-key,
.composer-mention-token,
.remote-desktop-empty-mark {
  background: var(--johnbot-bg-control-hover);
  color: var(--johnbot-text-secondary);
}
.server-rail-muted {
  position: absolute;
  right: 0;
  bottom: 0;
  color: var(--johnbot-text-secondary);
  background: var(--johnbot-bg-sidebar);
  border-radius: var(--johnbot-radius-sm);
}

/* A hosted server that sleeps for no use: muted. One that wakes after the user's input: a pulsing accent. */
@keyframes server-sleep-waking {
  0%,
  100% {
    opacity: 1;
  }

  50% {
    opacity: 0.35;
  }
}

@media (prefers-reduced-motion: reduce) {
  .server-menu-sleep[data-state="waking"],
  .sidebar-server-name > .sidebar-server-name-sleep[data-state="waking"] {
    animation: none;
  }
}

/* A server menu item with a second line, such as "Muted until 14:30", like Discord's. */
.ui-action-menu:not([data-menu-layout="grid"]) .server-rail-menu-detail-item {
  height: auto;
}

.server-rail-menu-label {
  display: flex;
  flex-direction: column;
}

.server-rail-menu-detail {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

/* === from: @johnbot/ui/features/sidebar/sidebar-views.css === */
/* The switch over the sidebar list, and the rows of the diagrams view. */

.sidebar-view-switch {
  padding: 2px 12px 6px;
}

.sidebar-view-tabs.ui-sliding-tabs {
  display: grid;
  width: 100%;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.sidebar-view-tab.ui-sliding-tabs-trigger {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  justify-content: center;
  gap: var(--johnbot-space-1);
  overflow: hidden;
  padding-inline: var(--johnbot-space-1);
  font-size: var(--johnbot-text-sm);
  white-space: nowrap;
}

.sidebar-view-tab svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: none;
}

/* === from: ./features/account/account-update-island.css === */
.account-update-island {
  --panel-open-dur: calc(var(--johnbot-duration-slow) + var(--johnbot-duration-slow));
  --panel-close-dur: calc(var(--johnbot-duration-slow) + var(--johnbot-duration-normal));
  --panel-translate-y: calc(100% - var(--johnbot-space-3));
  --panel-blur: var(--johnbot-space-0-5);
  --panel-ease: var(--johnbot-ease-out);
  --text-swap-dur: var(--johnbot-duration-normal);
  --text-swap-translate-y: var(--johnbot-space-1);
  --text-swap-blur: var(--johnbot-space-0-5);
  --text-swap-ease: var(--johnbot-ease-in-out);
  --digit-dur: var(--johnbot-duration-slow);
  --digit-distance: var(--johnbot-space-1);
  --digit-stagger: calc(var(--johnbot-duration-fast) - var(--johnbot-duration-dialog));
  --digit-blur: var(--johnbot-space-0-5);
  --digit-ease: var(--johnbot-ease-out);
  --digit-dir-x: 0;
  --digit-dir-y: 1;

  position: absolute;
  z-index: 0;
  right: var(--johnbot-space-4);
  bottom: var(--johnbot-control-xl);
  left: var(--johnbot-space-4);
  display: grid;
  min-height: calc(var(--johnbot-control-xl) + var(--johnbot-radius-card));
  align-items: center;
  border: 0;
  border-radius: var(--johnbot-radius-lg) var(--johnbot-radius-lg) var(--johnbot-radius-md) var(--johnbot-radius-md);
  background: var(--johnbot-accent-strong);
  box-shadow: 0 0 0 1px var(--johnbot-accent-soft);
  -webkit-backdrop-filter: blur(var(--johnbot-space-3));
  backdrop-filter: blur(var(--johnbot-space-3));
  padding: calc(var(--johnbot-space-1) + 1px) var(--johnbot-space-1-5)
    calc(var(--johnbot-space-4) + var(--johnbot-space-1) - 1px);
  grid-template-columns: minmax(0, 1fr) auto;
  gap: var(--johnbot-space-2);
  color: var(--johnbot-accent-text);
  -webkit-font-smoothing: antialiased;
}

.account-update-island.t-panel-slide {
  transform: translateY(var(--panel-translate-y));
  opacity: 0;
  filter: blur(var(--panel-blur));
  pointer-events: none;
  transition:
    transform var(--panel-close-dur) var(--panel-ease),
    opacity var(--panel-close-dur) var(--panel-ease),
    filter var(--panel-close-dur) var(--panel-ease);
  will-change: transform, opacity, filter;
}

.account-update-island.t-panel-slide[data-open="true"] {
  transform: translateY(0);
  opacity: 1;
  filter: blur(0);
  pointer-events: auto;
  transition:
    transform var(--panel-open-dur) var(--panel-ease),
    opacity var(--panel-open-dur) var(--panel-ease),
    filter var(--panel-open-dur) var(--panel-ease);
}

/* The island only enters the DOM once there is an update to announce, so it is
   already `data-open="true"` on its first frame and the closed rule above never
   applies. This gives that first frame something to slide in from. */
@starting-style {
  .account-update-island.t-panel-slide[data-open="true"] {
    transform: translateY(var(--panel-translate-y));
    opacity: 0;
    filter: blur(var(--panel-blur));
  }
}

.account-update-island__copy {
  min-width: 0;
}

.account-update-island__copy strong {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--johnbot-accent-text);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-sm);
  white-space: nowrap;
}

.account-update-island .t-update-text-swap {
  display: inline-grid;
}

.account-update-island .t-update-text-swap > [data-text] {
  grid-area: 1 / 1;
  transform: translateY(0);
  opacity: 1;
  filter: blur(0);
  transition:
    transform var(--text-swap-dur) var(--text-swap-ease),
    filter var(--text-swap-dur) var(--text-swap-ease),
    opacity var(--text-swap-dur) var(--text-swap-ease);
  will-change: transform, filter, opacity;
}

.account-update-island
  .t-update-text-swap:is([data-state="available"], [data-state="action"])
  > [data-text]:is([data-text="ready"], [data-text="progress"], [data-text="error"]) {
  transform: translateY(var(--text-swap-translate-y));
  opacity: 0;
  filter: blur(var(--text-swap-blur));
}

.account-update-island
  .t-update-text-swap:is([data-state="ready"], [data-state="progress"])
  > [data-text]:is([data-text="available"], [data-text="action"], [data-text="error"]) {
  transform: translateY(calc(var(--text-swap-translate-y) * -1));
  opacity: 0;
  filter: blur(var(--text-swap-blur));
}

.account-update-island .t-update-text-swap[data-state="error"] > [data-text]:not([data-text="error"]) {
  transform: translateY(calc(var(--text-swap-translate-y) * -1));
  opacity: 0;
  filter: blur(var(--text-swap-blur));
}

.account-update-island__action-shell {
  position: relative;
  display: grid;
  /* A floor, not a fixed width: translated labels such as "Uruchom ponownie" are wider than the
     English ones, and the button grows to hold them while the status text gives way. */
  min-width: calc(
    var(--johnbot-control-xl) +
    var(--johnbot-control-xl) +
    var(--johnbot-space-6) +
    var(--johnbot-space-1)
  );
  flex-shrink: 0;
}

.account-update-island__action.ui-button {
  width: 100%;
  height: var(--johnbot-control-sm);
  min-height: var(--johnbot-control-sm);
  border-radius: var(--johnbot-radius-sm);
  background: var(--johnbot-surface-light);
  box-shadow: 0 1px 2px var(--johnbot-shadow-popover-ambient);
  padding: 0 var(--johnbot-space-3) 0 var(--johnbot-space-2);
  color: var(--johnbot-text-on-light);
  transition:
    box-shadow var(--johnbot-duration-normal) var(--johnbot-ease-out),
    transform var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.account-update-island__action.ui-button::after {
  position: absolute;
  top: 50%;
  left: 50%;
  width: calc(100% + var(--johnbot-space-4));
  min-width: var(--johnbot-control-xl);
  height: var(--johnbot-control-xl);
  transform: translate(-50%, -50%);
  content: "";
}

.account-update-island__action.ui-button:disabled {
  cursor: progress;
  opacity: 1;
}

.account-update-island__action-content {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--johnbot-space-1-5);
}

.account-update-island__action-label {
  min-width: calc(var(--johnbot-control-xl) + var(--johnbot-space-3));
  color: var(--johnbot-text-on-light);
  font-weight: var(--johnbot-weight-semibold);
  text-align: left;
}

.account-update-island__progress-value {
  display: inline-grid;
  align-items: baseline;
  grid-template-columns: 3ch max-content;
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-semibold);
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.account-update-island__progress-digits {
  display: inline-flex;
  justify-content: flex-end;
}

.account-update-island__progress-suffix,
.account-update-island__busy-label {
  display: inline-block;
}

@keyframes account-update-digit-pop-in {
  0% {
    transform: translate(
      calc(var(--digit-distance) * var(--digit-dir-x)),
      calc(var(--digit-distance) * var(--digit-dir-y))
    );
    opacity: 0.4;
    filter: blur(var(--digit-blur));
  }

  100% {
    transform: translate(0, 0);
    opacity: 1;
    filter: blur(0);
  }
}

.account-update-island__progress-value .t-digit {
  display: inline-block;
  will-change: transform, opacity, filter;
}

.account-update-island__progress-digits.is-animating .t-digit {
  animation: account-update-digit-pop-in var(--digit-dur) var(--digit-ease) both;
}

.account-update-island__progress-digits.is-animating .t-digit[data-stagger="1"] {
  animation-delay: var(--digit-stagger);
}

.account-update-island__progress-digits.is-animating .t-digit[data-stagger="2"] {
  animation-delay: calc(var(--digit-stagger) * 2);
}

.account-update-island__action-shell[data-downloading="true"] .account-update-island__action-label {
  min-width: var(--johnbot-control-md);
  text-align: center;
}

.account-update-island__action-shell[data-downloading="true"] .account-update-island__action.ui-button {
  padding-inline: var(--johnbot-space-2);
}

.account-update-island__icon.t-icon-swap {
  --icon-swap-dur: var(--johnbot-duration-overlay);
  --icon-swap-blur: var(--johnbot-space-0-5);
  --icon-swap-start-scale: 0.25;
  --icon-swap-ease: var(--johnbot-ease-in-out);

  position: relative;
  display: inline-grid;
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: 0 0 auto;
  place-items: center;
}

.account-update-island__icon.t-icon-swap .t-icon {
  position: relative;
  top: 1px;
  display: grid;
  grid-area: 1 / 1;
  place-items: center;
  transition:
    opacity var(--icon-swap-dur) var(--icon-swap-ease),
    filter var(--icon-swap-dur) var(--icon-swap-ease),
    transform var(--icon-swap-dur) var(--icon-swap-ease);
  will-change: opacity, filter, transform;
}

.account-update-island__icon.t-icon-swap svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  stroke-width: var(--johnbot-icon-stroke);
}

.account-update-island__icon.t-icon-swap .ui-spinner {
  border-color: var(--johnbot-text-dim-on-light);
  border-top-color: currentColor;
}

.account-update-island__icon.t-icon-swap[data-state="a"] .t-icon[data-icon="a"],
.account-update-island__icon.t-icon-swap[data-state="b"] .t-icon[data-icon="b"] {
  transform: scale(1);
  opacity: 1;
  filter: blur(0);
}

.account-update-island__icon.t-icon-swap[data-state="a"] .t-icon[data-icon="b"],
.account-update-island__icon.t-icon-swap[data-state="b"] .t-icon[data-icon="a"] {
  transform: scale(var(--icon-swap-start-scale));
  opacity: 0;
  filter: blur(var(--icon-swap-blur));
}

.account-update-island__action.ui-button:active:not(:disabled):not([data-disabled]) {
  transform: scale(0.96);
}

@media (hover: hover) and (pointer: fine) {
  .account-update-island__action.ui-button:hover:not(:disabled):not([data-disabled]) {
    background: var(--johnbot-surface-light);
    box-shadow:
      0 0 0 1px var(--johnbot-text-dim-on-light),
      0 1px 2px var(--johnbot-shadow-popover-ambient);
    color: var(--johnbot-text-on-light);
  }
}

@media (prefers-reduced-motion: reduce) {
  .account-update-island.t-panel-slide,
  .account-update-island__action.ui-button,
  .account-update-island__icon.t-icon-swap .t-icon,
  .account-update-island .t-update-text-swap > [data-text] {
    transition: none;
  }

  .account-update-island__progress-value .t-digit {
    animation: none;
  }
}

/* In the sidebar there is no account box to come out of: the island is in the flow at the end of
 * the sidebar, with four round corners and the same space above and below its button. */
.sidebar-update-island > .account-update-island {
  position: relative;
  inset: auto;
  min-height: 0;
  margin: var(--johnbot-space-2) var(--johnbot-space-3) var(--johnbot-space-3);
  border-radius: var(--johnbot-radius-lg);
  padding: var(--johnbot-space-1-5) var(--johnbot-space-1-5) var(--johnbot-space-1-5) var(--johnbot-space-3);
}

/* === from: @johnbot/ui/features/servers/join-server-dialog.css === */
.join-server-backdrop {
  animation: join-server-backdrop-in var(--modal-open-dur) var(--modal-ease) both;
  will-change: opacity;
}

.join-server-backdrop[data-motion="closing"] {
  animation: join-server-backdrop-out var(--modal-close-dur) var(--modal-ease) both;
}

.join-server-dialog {
  position: relative;
  width: min(420px, 100%);
  max-height: calc(100dvh - 48px);
  overflow: hidden;
  outline: 0;
  border-radius: var(--johnbot-radius-xl);
  background: var(--johnbot-bg-sidebar);
  color: var(--johnbot-text-primary);
  box-shadow: 0 0 0 1px var(--johnbot-border-strong);
}

.join-server-close {
  position: absolute;
  top: var(--johnbot-space-6);
  right: var(--johnbot-space-6);
  z-index: 2;
  color: var(--johnbot-text-muted);
}

.join-server-content {
  width: 100%;
  max-height: inherit;
  overflow-y: auto;
  padding: 32px;
}

.join-server-pages {
  /* The pages have fixed heights for the slide, so an error code adds its row here. */
  --join-server-reference: 0px;
  width: 100%;
  height: 336px;
  overflow: hidden;
  transition: height var(--page-slide-dur) var(--page-slide-ease);
}

.join-server-pages[data-reference] {
  --join-server-reference: calc(var(--johnbot-control-xs) + var(--johnbot-space-0-5));
}

.join-server-pages[data-page="1"][data-preview-error] {
  height: calc(356px + var(--join-server-reference));
}

.join-server-pages[data-page="2"] {
  height: 292px;
}

.join-server-pages[data-page="2"][data-error] {
  height: calc(364px + var(--join-server-reference));
}

.join-server-page {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--johnbot-space-4) + var(--johnbot-space-1));
  margin: 0;
}

.join-server-header {
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.join-server-header-entry {
  gap: var(--johnbot-space-2);
  padding-inline: calc(var(--johnbot-space-4) + var(--johnbot-space-1));
}

.join-server-header-entry .ui-heading {
  font-size: var(--johnbot-text-3xl);
  font-weight: var(--johnbot-weight-bold);
  line-height: var(--johnbot-leading-3xl);
}

.join-server-header-entry .ui-text {
  font-size: var(--johnbot-text-lg);
}

.join-server-header-verified {
  gap: var(--johnbot-space-2);
  padding-inline: var(--johnbot-space-2);
}

.join-server-header .ui-text {
  max-width: 296px;
  line-height: var(--johnbot-leading-sm);
}

.join-server-entry-logo {
  --app-logo-background: var(--johnbot-surface-light);
  width: 64px;
  height: 64px;
  flex: 0 0 auto;
  margin-bottom: var(--johnbot-space-4);
  border-radius: var(--johnbot-radius-xl);
  box-shadow:
    0 12px 28px var(--johnbot-shadow-dialog),
    inset 0 1px 0 var(--johnbot-border-strong);
}

.join-server-field {
  gap: var(--johnbot-space-2);
}

.join-server-link-input.ui-input {
  height: var(--johnbot-control-xl);
  background: var(--johnbot-bg-control);
  font-family: var(--johnbot-font-mono);
  font-size: var(--johnbot-text-sm);
}

.join-server-link-input.ui-input:focus-visible {
