}

.join-server-field .ui-field-error {
  min-height: var(--johnbot-leading-sm);
}

.join-server-identity-logo {
  --app-logo-background: var(--johnbot-surface-light);
  width: 88px;
  height: 88px;
  flex: 0 0 auto;
  margin-bottom: var(--johnbot-space-6);
  border-radius: var(--johnbot-radius-modal);
  box-shadow:
    0 16px 36px var(--johnbot-shadow-dialog),
    inset 0 1px 0 var(--johnbot-border-strong);
}

.join-server-invite-eyebrow {
  margin-bottom: 2px;
  font-size: var(--johnbot-text-lg);
}

.join-server-header-verified .ui-heading {
  font-size: var(--johnbot-text-3xl);
  font-weight: var(--johnbot-weight-bold);
  line-height: var(--johnbot-leading-3xl);
}

.join-server-hostname.ui-text {
  max-width: 260px;
  color: var(--johnbot-text-muted);
  font-family: var(--johnbot-font-sans);
  font-size: var(--johnbot-text-lg);
}

.join-server-alert.ui-alert {
  align-self: start;
  padding-block: var(--johnbot-space-2);
}

.join-server-alert .ui-alert-description {
  white-space: normal;
}

.join-server-actions {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: var(--johnbot-space-2);
  margin-top: auto;
}

.join-server-actions .ui-button {
  width: 100%;
}

.join-server-actions-verified {
  gap: var(--johnbot-space-1);
}

.join-server-preview {
  display: grid;
  gap: var(--johnbot-space-3);
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-control);
