.join-server-preview-signal span {
  width: 42px;
  height: 1px;
  opacity: 0.52;
}

.join-server-preview-heading {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.join-server-verified {
  color: var(--johnbot-success);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
}

.join-server-preview-heading strong,
.join-server-preview-heading small,
.join-server-preview dd {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.join-server-preview-heading strong {
  font-size: var(--johnbot-text-lg);
}

.join-server-preview-heading small,
.join-server-preview dt,
.join-server-preview p {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

.join-server-preview dl {
  display: grid;
  gap: var(--johnbot-space-2);
  margin: 0;
}

.join-server-preview dl div {
  min-width: 0;
  display: grid;
  grid-template-columns: 58px minmax(0, 1fr);
  gap: var(--johnbot-space-2);
}

.join-server-preview dd {
  margin: 0;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
}

.join-server-preview p {
  margin: 0;
  line-height: var(--johnbot-leading-sm);
}

@keyframes join-server-backdrop-in {
  from {
    opacity: 0;
  }
}

@keyframes join-server-backdrop-out {
  to {
    opacity: 0;
  }
}

@media (max-width: 560px) {
  .join-server-backdrop {
    padding: var(--johnbot-space-3);
  }

  .join-server-dialog {
    width: 100%;
    max-height: calc(100dvh - 24px);
  }

  .join-server-close {
    top: var(--johnbot-space-3);
    right: var(--johnbot-space-3);
  }

  .join-server-content {
    padding: var(--johnbot-space-6);
  }

  .join-server-pages {
    height: 348px;
  }

  .join-server-pages[data-page="1"][data-preview-error] {
    height: calc(368px + var(--join-server-reference));
  }

  .join-server-pages[data-page="2"] {
    height: 304px;
  }

  .join-server-pages[data-page="2"][data-error] {
    height: calc(376px + var(--join-server-reference));
  }
}

@media (prefers-reduced-motion: reduce) {
  .join-server-backdrop {
    animation: none;
  }

  .join-server-pages {
    transition: none;
  }
}

/* === from: @johnbot/ui/features/servers/add-server-dialog.css === */
/* The add-server dialog reuses the join-server-dialog shell (backdrop, surface, close button and
 * content padding). The pricing step is wider. */
.add-server-dialog {
  width: min(460px, 100%);
  transition: width var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

/* Long prices (for example in PLN) need wider columns: 48px for each character over 10, that is
 * 16px in each of the 3 columns. The width transition above animates the change. */
.add-server-dialog[data-step="pricing"] {
  width: min(calc(760px + var(--add-server-extra-price-chars, 0) * 48px), 100%);
}

.add-server-step {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-6);
  margin: 0;
  animation: add-server-step-in var(--johnbot-duration-slow) var(--johnbot-ease-out) both;
}

.add-server-step .ui-heading:focus {
  outline: none;
}

/* Pricing */

.add-server-pricing {
  gap: var(--johnbot-space-4);
}

.add-server-dialog[data-step="pricing"] .join-server-content {
  padding: var(--johnbot-space-6);
}

/* Over the plans, so it is as wide as the plans. */
.add-server-limit.ui-alert {
  align-self: stretch;
}

/* What the plans buy, before the prices. */
.add-server-intro {
  gap: var(--johnbot-space-2);
  padding-block: var(--johnbot-space-2);
}

.add-server-intro .ui-heading,
.add-server-intro .ui-text {
  margin: 0;
  text-wrap: balance;
}

/* The inline padding keeps the title clear of the close button of the shell. */
.add-server-intro .ui-heading {
  padding-inline: calc(var(--johnbot-control-md) + var(--johnbot-space-2));
  font-size: var(--johnbot-text-3xl);
  font-weight: var(--johnbot-weight-bold);
  line-height: var(--johnbot-leading-3xl);
  letter-spacing: var(--johnbot-tracking-tight);
}

.add-server-intro .ui-text {
  max-width: 560px;
  font-size: var(--johnbot-text-lg);
  line-height: var(--johnbot-leading-lg);
}

/* The billing switch is in the centre. The same inline padding on the two sides keeps it clear of
 * the close button of the shell. */
.add-server-bar {
  position: relative;
  min-height: var(--johnbot-control-md);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--johnbot-space-2);
  padding-inline: calc(var(--johnbot-control-md) + var(--johnbot-space-2));
}

/* At the left, across from the close button, so that the billing switch stays in the centre. */
.add-server-bar .hosted-currency {
  position: absolute;
  top: 50%;
  left: 0;
  width: auto;
  flex: 0 0 auto;
  transform: translateY(-50%);
}

/* The account pays in one currency, so the code is text: the same height as the select, no chevron. */
.hosted-currency-locked {
  display: inline-flex;
  align-items: center;
  height: var(--johnbot-control-md);
  padding-inline: 10px;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
}

/* With a license offer: personal or work use at the left, the currency and billing at the right. */
.add-server-bar[data-license] {
  justify-content: flex-end;
  padding-inline: 0;
}

.add-server-bar[data-license] .hosted-use {
  margin-right: auto;
}

.add-server-bar[data-license] .hosted-currency {
  position: static;
  transform: none;
}

/* Two equal columns, so the pill moves by exactly its own width. */
.hosted-billing {
  --hosted-billing-ease: cubic-bezier(0.34, 1.36, 0.64, 1);
  position: relative;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  padding: 3px;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-canvas);
}

.hosted-billing::before {
  content: "";
  position: absolute;
  top: 3px;
  bottom: 3px;
  left: 3px;
  width: calc(50% - 3px);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-control-active);
  box-shadow: inset 0 0 0 1px var(--johnbot-border);
  transition: transform 300ms var(--hosted-billing-ease);
}

.hosted-billing[data-billing="yearly"]::before,
.hosted-billing[data-use="work"]::before {
  transform: translateX(100%);
}

.hosted-billing-option {
  position: relative;
  z-index: 1;
  display: flex;
}

.hosted-billing-control {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--johnbot-space-2);
  padding: var(--johnbot-space-1) var(--johnbot-space-4);
  border-radius: var(--johnbot-radius-pill);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-md);
  white-space: nowrap;
  cursor: pointer;
  transition: color var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

.hosted-billing-control[data-checked] {
  color: var(--johnbot-text-primary);
}

.hosted-billing-option:has(:focus-visible) .hosted-billing-control {
  box-shadow: var(--johnbot-focus-ring);
}

.hosted-billing-save {
  padding: 0 var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-control);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-md);
  transition:
    color var(--johnbot-duration-overlay) var(--johnbot-ease-out),
    background-color var(--johnbot-duration-overlay) var(--johnbot-ease-out);
}

.hosted-billing[data-billing="yearly"] .hosted-billing-save {
  background: var(--johnbot-success-soft);
  color: var(--johnbot-success-text);
  animation: hosted-billing-save-pop 300ms var(--hosted-billing-ease) 80ms both;
}

/* The saving changes between personal and work use; equal digit widths keep the switch in place. */
.add-server-bar[data-license] .hosted-billing-save {
  font-variant-numeric: tabular-nums;
}

/* One framed panel. Hairlines divide the plans. */
.hosted-plans {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  overflow: hidden;
  margin: 0;
  padding: 0;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-card);
  background: var(--johnbot-bg-canvas);
  list-style: none;
}

/* The columns come in one after the other. The fill mode is backwards only, so the dimmed state
 * can still transition after the entrance ends. */
.hosted-plan {
  position: relative;
  isolation: isolate;
  min-width: 0;
  display: flex;
  flex-direction: column;
  padding: var(--johnbot-space-6);
  transition:
    opacity var(--johnbot-duration-overlay) var(--johnbot-ease-out),
    background-color var(--johnbot-duration-normal) var(--johnbot-ease-out);
  animation: hosted-plan-in var(--johnbot-duration-overlay) var(--johnbot-ease-out)
    calc(var(--plan-index) * 40ms + 60ms) backwards;
}

.hosted-plan + .hosted-plan {
  border-left: 1px solid var(--johnbot-border);
}

.hosted-plan[data-recommended] {
  background: var(--johnbot-bg-surface);
}

.hosted-plan[data-dimmed] {
  opacity: 0.5;
}

/* A cool-to-warm line on the top edge and a soft glow at the bottom of the recommended plan. */
.hosted-plan[data-recommended]::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--johnbot-accent), var(--johnbot-warning), transparent);
  opacity: 0.8;
  pointer-events: none;
}

.hosted-plan[data-recommended]::after {
  content: "";
  position: absolute;
  inset: auto 0 0;
  z-index: -1;
  height: 50%;
  background: linear-gradient(90deg, var(--johnbot-accent), var(--johnbot-warning));
  opacity: 0.22;
  mask-image: radial-gradient(90% 100% at 50% 100%, var(--johnbot-text-primary), transparent);
  pointer-events: none;
  transition: opacity var(--johnbot-duration-overlay) var(--johnbot-ease-out);
}

/* A fixed height, so that the badge does not move this column's content down. */
.hosted-plan-head {
  height: var(--johnbot-control-sm);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-2);
}

.hosted-plan-name {
  margin: 0;
  color: var(--johnbot-accent-text);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-md);
}

/* Light, like the "Choose" button of the same plan. */
.hosted-plan-badge {
  border-color: transparent;
  background: var(--johnbot-surface-light);
  color: var(--johnbot-text-on-light);
}

/* One line: the dialog gets wider for long prices. Only when the window is too narrow for that
 * width does the old price go on its own line above the new price. */
.hosted-plan-price {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  margin: var(--johnbot-space-4) 0 0;
}

/* The monthly price on yearly billing. The column grows from zero, so the price slides right
 * instead of jumping. */
.hosted-plan-was {
  display: grid;
  grid-template-columns: 0fr;
  align-self: center;
  opacity: 0;
  transition:
    grid-template-columns var(--johnbot-duration-overlay) var(--johnbot-ease-out),
    opacity var(--johnbot-duration-overlay) var(--johnbot-ease-out);
}

.hosted-plan-was[data-shown] {
  grid-template-columns: 1fr;
  opacity: 1;
}

.hosted-plan-was-inner {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
}

.hosted-plan-was s {
  display: inline-block;
  margin-right: var(--johnbot-space-2);
  color: var(--johnbot-text-dim);
  font-size: var(--johnbot-text-xl);
  line-height: var(--johnbot-leading-xl);
  font-variant-numeric: tabular-nums;
  text-decoration-thickness: 1px;
}

.hosted-plan-now {
  display: flex;
  align-items: flex-start;
  white-space: nowrap;
}

.hosted-plan-amount {
  --digit-distance: 12px;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-display);
  font-weight: var(--johnbot-weight-regular);
  line-height: var(--johnbot-leading-display);
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

.hosted-plan-period {
  white-space: nowrap;
  margin-left: var(--johnbot-space-1);
  padding-top: var(--johnbot-space-1);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

/* Only when the column is too narrow does the saving go on a second line. */
.hosted-plan-billed {
  display: flex;
  flex-wrap: wrap;
  margin: var(--johnbot-space-1) 0 0;
  color: var(--johnbot-text-dim);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  animation: add-server-step-in var(--johnbot-duration-overlay) var(--johnbot-ease-out) both;
}

.hosted-plan-billed-total {
  white-space: nowrap;
}

.hosted-plan-saving {
  color: var(--johnbot-success-text);
  white-space: nowrap;
}

.hosted-plan-saving::before {
  content: "\00b7" / "";
  margin: 0 var(--johnbot-space-1);
  color: var(--johnbot-text-dim);
}

.hosted-plan-summary {
  margin: var(--johnbot-space-4) 0 var(--johnbot-space-6);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
}

/* The bundle discount of a server with its license, in place of the "Best value" badge. */
.hosted-plan-bundle {
  padding: 0 var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-success-soft);
  color: var(--johnbot-success-text);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-md);
  white-space: nowrap;
}

/* For work, the price includes the license: the line has the success color of the bundle and an icon. */
.hosted-plan-summary[data-license] {
  display: flex;
  align-items: baseline;
  gap: var(--johnbot-space-2);
  color: var(--johnbot-text-primary);
  font-weight: var(--johnbot-weight-medium);
}

/* The icon bottom is on the baseline of the first line. It moves down so that its middle is on the
 * middle of the capital letters. */
.hosted-plan-summary svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: 0 0 auto;
  translate: 0 calc((var(--johnbot-icon-sm) - 1cap) / 2);
  color: var(--johnbot-success-text);
}

/* The personal and work summaries differ in length; two lines for both, so the buttons stay in place. */
.hosted-plans[data-license] .hosted-plan-summary {
  min-height: 2lh;
}

/* The price line breaks for all counts or for none. LongestPrice measures the longest price. */
.hosted-plans[data-license] .hosted-plan-price {
  position: relative;
}

.hosted-plan-longest {
  position: absolute;
  inset: 0 0 auto;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  visibility: hidden;
  pointer-events: none;
}

/* Only the visible price: the copy must not change the width that it measures. */
.hosted-plans[data-stacked] .hosted-plan-price > .hosted-plan-was[data-shown] {
  flex-basis: 100%;
}

/* The people row closes the frame of the plans. It stays for personal use, disabled, so nothing moves. */
.hosted-plans[data-license] {
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}

.hosted-license-people {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-3) var(--johnbot-space-6);
  border: 1px solid var(--johnbot-border);
  border-top: 0;
  border-radius: 0 0 var(--johnbot-radius-card) var(--johnbot-radius-card);
  background: var(--johnbot-bg-canvas);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  transition: color var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

.hosted-license-people[data-disabled] {
  color: var(--johnbot-text-muted);
}

.hosted-license-people > span {
  white-space: nowrap;
}

.hosted-license-stepper {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  margin: 0;
  padding: 0;
  border: 0;
  font-variant-numeric: tabular-nums;
}

/* As wide as "10 members", so the buttons stay in place while the count changes. */
.hosted-license-stepper > span {
  min-width: 11ch;
  text-align: center;
  white-space: nowrap;
}

.hosted-license-stepper .ui-icon-button {
  border-radius: var(--johnbot-radius-pill);
}

/* The buttons line up when the summaries wrap to different lengths. */
.hosted-plan-choose.ui-button {
  margin-top: auto;
}

/* With the people row, the summaries have one height, and a work plan has one fact less: the
 * buttons follow the summary, so they stay on one line. */
.hosted-plans[data-license] .hosted-plan-choose.ui-button {
  margin-top: 0;
}

.hosted-plan-facts {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-2);
  margin: var(--johnbot-space-6) 0 0;
  padding: var(--johnbot-space-4) 0 0;
  border-top: 1px dashed var(--johnbot-border);
  list-style: none;
}

.hosted-plan-facts li {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
}

.hosted-plan-facts svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: 0 0 auto;
  color: var(--johnbot-text-muted);
  transition: color var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

/* Needs that the plans do not cover. */
.add-server-custom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-4);
  padding: 0 var(--johnbot-space-1);
}

.add-server-custom-text {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.add-server-custom-text .ui-text {
  margin: 0;
}

.add-server-custom .ui-button {
  flex: 0 0 auto;
}

.add-server-join {
  margin: 0;
  text-align: center;
}

/* Progress */

.add-server-progress {
  align-items: stretch;
  gap: var(--johnbot-space-6);
}

.add-server-progress .join-server-header {
  gap: var(--johnbot-space-2);
}

/* Three ring segments around the server logo, one for each step. The SVG turns by -90deg, so the
 * first segment starts at the top. With pathLength 100, each segment is 30.33 long with a gap of 3. */
.add-server-ring {
  position: relative;
  width: 96px;
  height: 96px;
  margin: var(--johnbot-space-2) auto 0;
  display: grid;
  place-items: center;
}

.add-server-ring-segments {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  fill: none;
  stroke-width: 4;
  transform: rotate(-90deg);
}

.add-server-ring-segment circle {
  stroke-dasharray: 30.33 100;
  transition:
    stroke-dasharray var(--johnbot-duration-normal) var(--johnbot-ease-out),
    stroke-dashoffset var(--johnbot-duration-slow) var(--johnbot-ease-out),
    stroke var(--johnbot-duration-slow) var(--johnbot-ease-out);
}

.add-server-ring-segment:nth-child(1) circle {
  stroke-dashoffset: -1.5;
}

.add-server-ring-segment:nth-child(2) circle {
  stroke-dashoffset: -34.83;
}

.add-server-ring-segment:nth-child(3) circle {
  stroke-dashoffset: -68.17;
}

.add-server-ring-track {
  stroke: var(--johnbot-border);
}

.add-server-ring-segment .add-server-ring-fill {
  stroke: var(--johnbot-accent);
}

.add-server-ring-segment[data-state="pending"] .add-server-ring-fill {
  stroke-dasharray: 0 100;
}

/* The running segment creeps to 90% and waits there for the step to end. */
.add-server-ring-segment[data-state="active"] .add-server-ring-fill {
  /* About how long a setup step takes. It is not a motion token: the step ends the creep. */
  --add-server-step-creep: 20s;
  stroke-dasharray: 27.3 100;
  transition: stroke-dasharray var(--add-server-step-creep) cubic-bezier(0.05, 0.7, 0.1, 1);
  animation: add-server-segment-breathe 1.6s var(--johnbot-ease-in-out) infinite alternate;

  @starting-style {
    stroke-dasharray: 0 100;
  }
}

.add-server-ring-segment[data-state="failed"] .add-server-ring-fill {
  stroke: var(--johnbot-danger);
}

/* Ready: the gaps close and the three segments become one success ring. */
.add-server-progress[data-status="ready"] .add-server-ring-segment circle {
  stroke-dasharray: 33.4 100;
  stroke: var(--johnbot-success);
}

.add-server-progress[data-status="ready"] .add-server-ring-segment:nth-child(1) circle {
  stroke-dashoffset: 0;
}

.add-server-progress[data-status="ready"] .add-server-ring-segment:nth-child(2) circle {
  stroke-dashoffset: -33.33;
}

.add-server-progress[data-status="ready"] .add-server-ring-segment:nth-child(3) circle {
  stroke-dashoffset: -66.67;
}

/* A small server in the centre: one unit for each step, each with a light at the right. */
.add-server-ring-core {
  position: relative;
  width: 72px;
  height: 72px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: var(--johnbot-space-1);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-surface);
  box-shadow: inset 0 0 0 1px var(--johnbot-border);
  transition:
    opacity var(--johnbot-duration-normal) var(--johnbot-ease-out),
    transform var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

.add-server-light {
  position: relative;
  width: 42px;
  height: 13px;
  border: 1px solid color-mix(in srgb, var(--johnbot-text-dim) 55%, transparent);
  border-radius: var(--johnbot-radius-sm);
  background: var(--johnbot-bg-sidebar);
}

/* The drive slot at the left. */
.add-server-light::before {
  content: "";
  position: absolute;
  top: 5px;
  left: 5px;
  width: 16px;
  height: 1px;
  background: var(--johnbot-text-dim);
}

/* The light at the right. */
.add-server-light::after {
  content: "";
  position: absolute;
  top: 3.5px;
  right: 4px;
  width: 4px;
  height: 4px;
  border-radius: var(--johnbot-radius-pill);
  background: color-mix(in srgb, var(--johnbot-text-dim) 55%, transparent);
  transition:
    background var(--johnbot-duration-normal) var(--johnbot-ease-out),
    box-shadow var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

.add-server-light[data-state="active"]::after {
  background: var(--johnbot-accent);
  box-shadow: 0 0 6px var(--johnbot-accent);
  animation: add-server-light-flicker 1.3s steps(1, end) infinite;
}

.add-server-light[data-state="done"]::after {
  background: var(--johnbot-success);
  box-shadow: 0 0 6px var(--johnbot-success);
}

.add-server-light[data-state="failed"]::after {
  background: var(--johnbot-danger);
  box-shadow: 0 0 6px var(--johnbot-danger);
}

.add-server-progress:is([data-status="ready"], [data-status="error"]) .add-server-ring-core {
  opacity: 0;
  transform: scale(0.7);
}

/* The result appears after the ring has closed, then its check mark draws itself. */
.add-server-ring-result {
  position: absolute;
  width: 72px;
  height: 72px;
  display: grid;
  place-items: center;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-success);
  color: var(--johnbot-text-on-accent);
  animation: add-server-pop var(--johnbot-duration-overlay) var(--johnbot-ease-out) var(--johnbot-duration-normal) both;
}

.add-server-ring-result[data-tone="danger"] {
  background: var(--johnbot-danger);
}

.add-server-ring-result svg {
  width: 32px;
  height: 32px;
}

.add-server-ring-result svg path {
  stroke-dasharray: 24;
  stroke-dashoffset: 24;
  animation: add-server-check-draw var(--johnbot-duration-slow) var(--johnbot-ease-out) var(--johnbot-duration-slow)
    forwards;
}

/* What happens now. Each new line rolls in from below. */
.add-server-ticker {
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
  animation: add-server-detail-in var(--johnbot-duration-slow) var(--johnbot-ease-out) both;
}

/* Confetti: pieces start at the logo, burst out, then fall. */

.add-server-confetti {
  position: absolute;
  inset: 0;
  z-index: 1;
  overflow: hidden;
  pointer-events: none;
}

.add-server-confetti i {
  position: absolute;
  top: var(--confetti-origin-y);
  left: var(--confetti-origin-x);
  width: 7px;
  height: 12px;
  border-radius: var(--johnbot-radius-xs);
  background: var(--johnbot-accent);
  opacity: 0;
  animation: add-server-confetti var(--confetti-duration) var(--johnbot-ease-out) var(--confetti-delay) both;
}

.add-server-confetti i:nth-child(5n + 1) {
  background: var(--johnbot-success);
}

.add-server-confetti i:nth-child(5n + 2) {
  background: var(--johnbot-warning);
}

.add-server-confetti i:nth-child(5n + 3) {
  background: var(--johnbot-danger);
}

.add-server-confetti i:nth-child(5n + 4) {
  background: var(--johnbot-accent-text);
}

.add-server-confetti i:nth-child(3n) {
  width: 8px;
  height: 8px;
  border-radius: var(--johnbot-radius-pill);
}

@keyframes add-server-confetti {
  0% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(0.3) rotate(0deg);
  }

  30% {
    opacity: 1;
    transform: translate(calc(-50% + var(--confetti-x)), calc(-50% + var(--confetti-y)))
      rotate(calc(var(--confetti-spin) / 2)) scale(1);
  }

  100% {
    opacity: 0;
    transform: translate(calc(-50% + var(--confetti-x) * 1.15), calc(-50% + var(--confetti-y) + 360px))
      rotate(var(--confetti-spin)) scale(0.9);
  }
}

@keyframes hosted-billing-save-pop {
  50% {
    transform: scale(1.1);
  }
}

@keyframes hosted-plan-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
}

@keyframes add-server-step-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
}

@keyframes add-server-pop {
  from {
    opacity: 0;
    transform: scale(0.6);
  }
}

@keyframes add-server-check-draw {
  to {
    stroke-dashoffset: 0;
  }
}

/* An uneven pattern, as disk activity is. */
@keyframes add-server-light-flicker {
  0%,
  22%,
  34%,
  58%,
  64%,
  88% {
    opacity: 1;
  }

  18%,
  30%,
  54%,
  61%,
  84% {
    opacity: 0.25;
  }
}

@keyframes add-server-segment-breathe {
  to {
    opacity: 0.55;
  }
}

@keyframes add-server-detail-in {
  from {
    opacity: 0;
    transform: translateY(8px);
    filter: blur(2px);
  }
}

/* After the other svg rules, because this selector is more specific. */
@media (hover: hover) {
  .hosted-plan:not([data-recommended]):hover {
    background: var(--johnbot-bg-surface);
  }

  .hosted-plan[data-recommended]:hover::after {
    opacity: 0.3;
  }

  .hosted-plan:hover .hosted-plan-facts svg {
    color: var(--johnbot-text-secondary);
  }
}

@media (max-width: 720px) {
  .hosted-plans {
    grid-template-columns: minmax(0, 1fr);
  }

  .hosted-plan + .hosted-plan {
    border-top: 1px solid var(--johnbot-border);
    border-left: 0;
  }
}

@media (max-width: 560px) {
  .add-server-intro .ui-heading {
    font-size: var(--johnbot-text-2xl);
    line-height: var(--johnbot-leading-2xl);
  }

  .add-server-intro .ui-text {
    font-size: var(--johnbot-text-md);
    line-height: var(--johnbot-leading-md);
  }

  /* The switch goes under the close button and fills the width. */
  .add-server-bar {
    padding: calc(var(--johnbot-control-md) + var(--johnbot-space-1)) 0 0;
  }

  .add-server-bar .hosted-billing {
    flex: 1;
  }

  /* In the row of the close button, so that the switch keeps the full width. */
  .add-server-bar .hosted-currency {
    top: 0;
    transform: none;
  }

  /* Personal or work use and the currency on one line, the billing under them. */
  .add-server-bar[data-license] {
    flex-wrap: wrap;
    padding-top: 0;
  }

  .add-server-bar[data-license] .hosted-billing:not(.hosted-use) {
    flex: 1 1 100%;
  }

  .add-server-custom {
    flex-direction: column;
    align-items: stretch;
  }

  /* The button goes under the text, so that the text keeps the width. */
  .add-server-limit.ui-alert {
    grid-template-columns: auto minmax(0, 1fr);
    align-items: start;
  }

  .add-server-limit .ui-alert-actions {
    grid-column: 2;
    justify-content: flex-start;
  }
}

@media (prefers-reduced-motion: reduce) {
  .add-server-dialog,
  .hosted-billing::before,
  .hosted-billing-control,
  .hosted-billing-save,
  .hosted-plan,
  .hosted-plan-was,
  .hosted-license-people,
  .add-server-progress[data-status] .add-server-ring-segment circle,
  .add-server-progress[data-status] .add-server-ring-core {
    transition: none;
  }

  .add-server-step,
  .hosted-billing[data-billing="yearly"] .hosted-billing-save,
  .hosted-plan,
  .hosted-plan-billed,
  .add-server-ring-result,
  .add-server-light[data-state]::after,
  .add-server-ring-segment[data-state] .add-server-ring-fill,
  .add-server-ticker {
    animation: none;
  }

  .add-server-ring-result svg path {
    stroke-dashoffset: 0;
    animation: none;
  }

  .add-server-confetti {
    display: none;
  }
}

/* === from: @johnbot/ui/features/servers/hosted-server-upsell.css === */
/*
 * The offer of a hosted server: a notice at the routine list, a modal after a new routine, and a
 * line in the offline notice. A border beam marks it as an offer, not a fault.
 */

/* The notice: the icon on the title line, and the actions under the text. */
.hosted-upsell-notice {
  flex: none;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: start;
  margin-top: var(--johnbot-space-3);
  padding: var(--johnbot-space-3);
}

.hosted-upsell-notice .ui-alert-icon {
  width: var(--johnbot-space-8);
  height: var(--johnbot-space-8);
  padding: var(--johnbot-space-1-5);
  border-radius: var(--johnbot-radius-md);
  background: linear-gradient(135deg, var(--johnbot-beam-blue), var(--johnbot-beam-pink));
  color: var(--johnbot-text-on-accent);
}

.hosted-upsell-notice .ui-alert-title {
  text-wrap: balance;
}

.hosted-upsell-notice .ui-alert-actions {
  justify-content: flex-start;
  margin-top: var(--johnbot-space-2);
}

/*
 * The border beam, after libraries.dev/beam: a conic gradient that turns around the border, and a
 * soft glow outside it.
 */
@property --hosted-upsell-beam-angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

.hosted-upsell-beam {
  position: relative;
  border-color: transparent;
  background:
    radial-gradient(120% 140% at 0% 0%, color-mix(in srgb, var(--johnbot-beam-blue) 12%, transparent), transparent 60%),
    var(--johnbot-bg-surface-raised);
}

/* The sharp line: the gradient, masked to a 1px ring. */
.hosted-upsell-beam::before,
.hosted-upsell-beam-glow > span {
  position: absolute;
  border-radius: inherit;
  content: "";
  pointer-events: none;
  mask:
    linear-gradient(currentColor 0 0) content-box exclude,
    linear-gradient(currentColor 0 0);
  animation: hosted-upsell-beam-turn 6s linear infinite;
}

.hosted-upsell-beam::before {
  inset: 0;
  padding: 1px;
  background: conic-gradient(
    from var(--hosted-upsell-beam-angle),
    color-mix(in srgb, var(--johnbot-beam-blue) 18%, transparent) 0deg,
    color-mix(in srgb, var(--johnbot-beam-blue) 18%, transparent) 180deg,
    var(--johnbot-beam-teal) 240deg,
    var(--johnbot-beam-blue) 290deg,
    var(--johnbot-beam-pink) 330deg,
    color-mix(in srgb, var(--johnbot-beam-blue) 18%, transparent) 360deg
  );
}

/* The glow: a wider ring of the beam colours, blurred by its parent, so the mask does not cut the blur. */
.hosted-upsell-beam-glow {
  position: absolute;
  inset: calc(-1 * var(--johnbot-space-3));
  border-radius: inherit;
  filter: blur(6px);
  opacity: 0.5;
  pointer-events: none;
}

.hosted-upsell-beam-glow > span {
  inset: var(--johnbot-space-3);
  padding: 2px;
  background: conic-gradient(
    from var(--hosted-upsell-beam-angle),
    transparent 0deg,
    transparent 210deg,
    var(--johnbot-beam-teal) 250deg,
    var(--johnbot-beam-blue) 290deg,
    var(--johnbot-beam-pink) 330deg,
    transparent 360deg
  );
}

@keyframes hosted-upsell-beam-turn {
  to {
    --hosted-upsell-beam-angle: 360deg;
  }
}

@media (prefers-reduced-motion: reduce) {
  .hosted-upsell-beam::before,
  .hosted-upsell-beam-glow > span {
    animation: none;
  }
}

/* The modal. It portals out of the workspace, so the rules match the content element itself. */
.hosted-upsell-modal {
  width: min(420px, 100%);
  display: grid;
  gap: var(--johnbot-space-2);
  padding: var(--johnbot-space-6);
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-modal);
  outline: 0;
  color: var(--johnbot-text-primary);
  background: var(--johnbot-bg-sidebar);
}

.hosted-upsell-modal .hosted-upsell-modal-title {
  margin: 0;
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-lg);
  text-wrap: balance;
}

.hosted-upsell-modal .hosted-upsell-modal-description {
  margin: 0;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  text-wrap: pretty;
}

.hosted-upsell-modal .hosted-upsell-modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: var(--johnbot-space-2);
  margin-top: var(--johnbot-space-3);
}

/* The picture: a laptop and a server, drawn with plain lines. */
.hosted-upsell-modal .hosted-upsell-scene {
  display: grid;
  grid-template-columns: 1fr 1fr;
  margin-bottom: var(--johnbot-space-4);
  padding: var(--johnbot-space-6) var(--johnbot-space-2) var(--johnbot-space-4);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-surface);
}

.hosted-upsell-modal .hosted-upsell-device {
  display: grid;
  justify-items: center;
  align-content: end;
  gap: var(--johnbot-space-3);
  margin: 0;
}

.hosted-upsell-modal .hosted-upsell-device figcaption {
  display: grid;
  justify-items: center;
  gap: var(--johnbot-space-1-5);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
}

.hosted-upsell-modal .hosted-upsell-laptop {
  display: grid;
  justify-items: center;
}

.hosted-upsell-modal .hosted-upsell-laptop-lid {
  width: 88px;
  height: 58px;
  padding: 4px;
  border: 2px solid var(--johnbot-border-strong);
  border-bottom: 0;
  border-radius: var(--johnbot-radius-sm) var(--johnbot-radius-sm) 0 0;
  transform-origin: bottom;
  animation: hosted-upsell-lid 5s ease-in-out infinite;
}

.hosted-upsell-modal .hosted-upsell-laptop-screen {
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  border-radius: var(--johnbot-radius-xs);
  color: var(--johnbot-text-secondary);
  background: var(--johnbot-bg-control);
}

.hosted-upsell-modal .hosted-upsell-laptop-screen svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  animation: hosted-upsell-shown-open 5s ease-in-out infinite;
}

.hosted-upsell-modal .hosted-upsell-laptop-base {
  width: 108px;
  height: 6px;
  border-radius: 0 0 var(--johnbot-radius-sm) var(--johnbot-radius-sm);
  background: var(--johnbot-border-strong);
}

.hosted-upsell-modal .hosted-upsell-rack {
  width: 64px;
  display: grid;
  gap: 4px;
}

.hosted-upsell-modal .hosted-upsell-rack span {
  position: relative;
  height: 18px;
  border: 2px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-sm);
}

/* One light on each unit; the lights stay on. */
.hosted-upsell-modal .hosted-upsell-rack span::after {
  position: absolute;
  top: 50%;
  right: 6px;
  width: 5px;
  height: 5px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-success);
  transform: translateY(-50%);
  animation: hosted-upsell-light 1.6s ease-in-out infinite;
  content: "";
}

.hosted-upsell-modal .hosted-upsell-rack span:nth-child(2)::after {
  animation-delay: 0.5s;
}

.hosted-upsell-modal .hosted-upsell-rack span:nth-child(3)::after {
  animation-delay: 1s;
}

/* Status: one chip. The laptop chip changes with the lid. */
.hosted-upsell-modal .hosted-upsell-status {
  display: grid;
  justify-items: center;
  font-weight: var(--johnbot-weight-medium);
}

.hosted-upsell-modal .hosted-upsell-status > span {
  grid-area: 1 / 1;
  padding: 2px var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-pill);
  white-space: nowrap;
}

.hosted-upsell-modal .hosted-upsell-status .hosted-upsell-status-on {
  color: var(--johnbot-success-text);
  background: color-mix(in srgb, var(--johnbot-success) 16%, transparent);
}

.hosted-upsell-modal .hosted-upsell-status .hosted-upsell-status-off {
  color: var(--johnbot-warning-text);
  background: color-mix(in srgb, var(--johnbot-warning-text) 14%, transparent);
}

.hosted-upsell-modal .hosted-upsell-status-flip .hosted-upsell-status-on {
  animation: hosted-upsell-shown-open 5s ease-in-out infinite;
}

.hosted-upsell-modal .hosted-upsell-status-flip .hosted-upsell-status-off {
  animation: hosted-upsell-shown-closed 5s ease-in-out infinite;
}

@keyframes hosted-upsell-lid {
  0%,
  25% {
    transform: scaleY(1);
  }
  40%,
  85% {
    transform: scaleY(0.08);
  }
  100% {
    transform: scaleY(1);
  }
}

@keyframes hosted-upsell-shown-open {
  0%,
  30% {
    opacity: 1;
  }
  38%,
  88% {
    opacity: 0;
  }
  96%,
  100% {
    opacity: 1;
  }
}

@keyframes hosted-upsell-shown-closed {
  0%,
  30% {
    opacity: 0;
  }
  38%,
  88% {
    opacity: 1;
  }
  96%,
  100% {
    opacity: 0;
  }
}

@keyframes hosted-upsell-light {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.35;
  }
}

/* With reduced motion, the picture shows the end state: lid closed, routine stopped, server on. */
@media (prefers-reduced-motion: reduce) {
  .hosted-upsell-modal .hosted-upsell-laptop-lid,
  .hosted-upsell-modal .hosted-upsell-laptop-screen svg,
  .hosted-upsell-modal .hosted-upsell-rack span::after,
  .hosted-upsell-modal .hosted-upsell-status-flip .hosted-upsell-status-on,
  .hosted-upsell-modal .hosted-upsell-status-flip .hosted-upsell-status-off {
    animation: none;
  }

  .hosted-upsell-modal .hosted-upsell-laptop-lid {
    transform: scaleY(0.08);
  }

  .hosted-upsell-modal .hosted-upsell-laptop-screen svg,
  .hosted-upsell-modal .hosted-upsell-status-flip .hosted-upsell-status-on {
    opacity: 0;
  }
}

/* The line in the offline notice. */
.hosted-upsell-offline {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--johnbot-space-2);
  margin: var(--johnbot-space-1) 0 0;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
}

.app-loading .hosted-upsell-offline {
  justify-content: center;
}

/* === from: @johnbot/ui/features/servers/restart-server-dialog.css === */.restart-server-steps {
  display: grid;
  gap: var(--johnbot-space-1);
  margin: 0;
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-control);
  list-style: none;
}

.restart-server-step {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
