}

.restart-server-step-icon svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
}

.restart-server-step[data-status="done"] .restart-server-step-icon {
  color: var(--johnbot-success-text);
}

.restart-server-step[data-status="failed"] .restart-server-step-icon {
