/* === from: @johnbot/ui/features/servers/server-roles.css === *//* Server Settings > Roles, and the role menu of a member row. */

.server-roles-icon {
  color: var(--johnbot-text-secondary);
}

.server-roles-member-count {
  min-width: 72px;
