/* === from: @johnbot/ui/styles/settings-panel.css === */
/*
 * The right-hand settings panel, shared by the agent chat and the channel chat.
 *
 * These rules were the agent panel's alone, under an `agent-` prefix. That prefix is why the
 * channel panel became a second copy of them instead of a second user of them, so the shared part
 * moved here under neutral names. What stays in `conversation.css` is what only an agent has: the
 * avatar picker, the runtime section and the notification row.
 */

.settings-panel {
  /*
   * The step between one block of settings and the next: the fields, the link group, the agent's
   * runtime card, the channel's member list. It is declared here, on the panel both surfaces open,
   * because a section that stands further from the link group in one panel than in the other is
   * exactly the drift this file exists to stop.
   */
  --settings-panel-section-gap: 25px;

  position: absolute;
  z-index: 15;
  top: 0;
  right: 0;
  bottom: 0;
  display: flex;
  width: var(--settings-panel-width, 360px);
  flex-direction: column;
  border-left: 1px solid var(--johnbot-border);
  background: var(--johnbot-bg-canvas);
  color: var(--johnbot-text-primary);
  animation: settings-panel-in var(--johnbot-duration-slow) cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.settings-panel-header {
  display: grid;
  height: 39px;
  flex: 0 0 auto;
  grid-template-columns: 32px 1fr 32px;
  align-items: center;
  border-bottom: 1px solid var(--johnbot-border);
  padding: 0 10px;
}

.settings-panel-header h2 {
  margin: 0;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: 600;
  line-height: 18px;
  text-align: center;
}

.settings-panel-nav-button {
  position: relative;
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border: 0;
  border-radius: var(--johnbot-radius-sm);
  padding: 0;
  background: transparent;
  color: var(--johnbot-text-secondary);
  transition:
    background-color var(--johnbot-duration-hover) ease,
    color var(--johnbot-duration-hover) ease,
    transform var(--johnbot-duration-fast) ease;
}

.settings-panel-nav-button::before {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 40px;
  height: 40px;
  content: "";
  transform: translate(-50%, -50%);
}

.settings-panel-nav-button > svg {
  width: 16px;
  height: 16px;
  /* The weight is left to .ui-glyph-20 on the icons themselves, as in .message-action-button. */
}

.settings-panel-nav-button:hover {
  background: var(--johnbot-hover);
  color: var(--johnbot-text-primary);
}

/* The chevron reads a hair right of centre in its box, so it is nudged back onto the axis. */
.settings-back-icon {
  transform: translateX(-0.5px);
}

.settings-panel-content {
  min-height: 0;
  overflow-y: auto;
  padding: 24px 15px 28px;
}

.settings-field {
  display: block;
  margin: 0 0 17px;
}

.settings-field > span {
  display: block;
  margin: 0 0 6px 8px;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-md);
  line-height: 18px;
}

/* The count and error under a field, after its control rather than above it like the label. */
.settings-field > .ui-field-limit {
  display: grid;
  margin: var(--johnbot-space-1-5) 0 0 var(--johnbot-space-2);
}

.settings-field input,
.settings-field textarea,
.settings-field select {
  display: block;
  width: 100%;
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-md);
  outline: 0;
  background: var(--johnbot-shadow-popover-ambient);
  padding: 10px 11px;
  color: var(--johnbot-text-primary);
  caret-color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
  line-height: 19px;
  transition:
    border-color var(--johnbot-duration-hover) ease,
    background var(--johnbot-duration-hover) ease;
}

.settings-field input,
.settings-field select {
  height: 38px;
}

.settings-field select {
  appearance: none;
  cursor: pointer;
  background-image:
    linear-gradient(45deg, transparent 50%, var(--johnbot-text-secondary) 50%),
    linear-gradient(135deg, var(--johnbot-text-secondary) 50%, transparent 50%);
  background-position:
    calc(100% - 16px) 16px,
    calc(100% - 11px) 16px;
  background-repeat: no-repeat;
  background-size:
    5px 5px,
    5px 5px;
  padding-right: 32px;
}

.settings-field select option {
  background: var(--johnbot-bg-control);
  color: var(--johnbot-text-primary);
}

.settings-field textarea {
  field-sizing: content;
  min-height: 88px;
  max-height: 240px;
  overflow-y: auto;
}

/* Instructions keep a fixed height and scroll inside, so the rows below do not move. */
.settings-field .settings-instructions-input {
  field-sizing: fixed;
  height: 120px;
  min-height: 120px;
  max-height: 120px;
  resize: none;
}

.settings-field input::placeholder,
.settings-field textarea::placeholder {
  color: var(--johnbot-text-muted);
}

.settings-field input:focus,
.settings-field textarea:focus,
.settings-field select:focus {
  border-color: var(--johnbot-text-muted);
  background: var(--johnbot-shadow-popover-ambient);
}

.settings-field input[aria-invalid="true"],
.settings-field textarea[aria-invalid="true"] {
  border-color: var(--johnbot-danger);
}

.settings-field input:focus-visible,
.settings-field textarea:focus-visible,
.settings-field select:focus-visible {
  outline: none;
}

.settings-link-group {
  display: grid;
  width: 100%;
  margin: 7px 0 22px;
  border-top: 1px solid var(--johnbot-border);
  border-bottom: 1px solid var(--johnbot-border);
}

.settings-link {
  width: 100%;
  min-height: 42px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--johnbot-space-3);
  border: 0;
  border-radius: 0;
  background: transparent;
  padding: 0 var(--johnbot-space-1);
  text-align: left;
  transition: none;
}

.settings-link + .settings-link {
  border-top: 1px solid var(--johnbot-border);
}

.settings-link-label {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-2);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
}

/* A fixed square, so every label in a group starts on one line whatever the glyph's shape. */
.settings-link-icon {
  display: grid;
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: 0 0 auto;
  place-items: center;
  color: var(--johnbot-text-secondary);
}

.settings-link-icon > svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  stroke-width: var(--johnbot-icon-stroke);
}

.settings-link-value {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
}

.settings-link-value svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  stroke-width: var(--johnbot-icon-stroke);
}

@media (hover: hover) and (pointer: fine) {
  .settings-link-group .settings-link:hover {
    background: var(--johnbot-hover);
    color: var(--johnbot-text-primary);
  }

  .settings-link:hover .settings-link-value {
    color: var(--johnbot-text-secondary);
  }
}

/* Named groups of rows, one card each. Used where one panel holds several groups. */
.settings-link-section {
  display: grid;
  gap: var(--johnbot-space-1-5);
}

.settings-link-section-title {
  margin: 0 0 0 var(--johnbot-space-1);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-sm);
}

.settings-link-group-inset {
  margin: 0;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-surface);
}

.settings-link-group-inset > * + * {
  border-top: 1px solid var(--johnbot-border);
}

/* The card does not clip its rows, because a row can hold an inline popover. The end rows round
   their own hover background instead. A wrapper row rounds the trigger button inside it. */
.settings-link-group-inset > :first-child,
.settings-link-group-inset > :first-child > button {
  border-top-left-radius: calc(var(--johnbot-radius-md) - 1px);
  border-top-right-radius: calc(var(--johnbot-radius-md) - 1px);
}

.settings-link-group-inset > :last-child,
.settings-link-group-inset > :last-child > button {
  border-bottom-left-radius: calc(var(--johnbot-radius-md) - 1px);
  border-bottom-right-radius: calc(var(--johnbot-radius-md) - 1px);
}

.settings-link-group-inset .settings-link {
  min-height: 40px;
  gap: var(--johnbot-space-2);
  padding: 0 var(--johnbot-space-3);
}

/* === from: @johnbot/ui/styles/provider-code-login.css === */
/*
 * The code sign-in dialog. It opens from the provider rows, which appear inside the settings modal
 * as well as on their own, so it sits one layer above the shared dialog layer for the same reason
 * `opencode-key-dialog.css` does: both portals are children of `body`, and insertion order alone
 * would decide it wrongly the first time a caller mounts it from elsewhere.
 *
 * The code itself is the largest thing on screen. It is about to be typed on another device from
 * this screen alone, so it is set in the mono face at display size with the characters spaced
 * apart: a code read wrong costs the whole round trip.
 */

.provider-code-login-backdrop {
  z-index: calc(var(--johnbot-layer-dialog) + 1);
}

.provider-code-login-dialog {
  position: relative;
  width: min(420px, 100%);
  max-height: calc(100dvh - var(--johnbot-space-6) * 2);
  overflow-y: auto;
  outline: 0;
  border-radius: var(--johnbot-radius-xl);
  background: var(--johnbot-bg-control);
  padding: var(--johnbot-space-6);
  color: var(--johnbot-text-primary);
  animation: provider-code-login-dialog-in var(--johnbot-duration-slow) var(--johnbot-ease-out) both;
}

/* The host's sign-in page needs the width of a browser window. */
.provider-code-login-dialog[data-page] {
  width: min(720px, 100%);
}

.provider-code-login-header {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-1);
  /* The close button sits in the corner the title would otherwise run into. */
  padding-right: var(--johnbot-space-8);
}

.provider-code-login-title {
  margin: 0;
  font-size: var(--johnbot-text-xl);
  line-height: var(--johnbot-leading-xl);
  font-weight: var(--johnbot-weight-semibold);
  letter-spacing: var(--johnbot-tracking-tight);
}

.provider-code-login-description {
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
}

.provider-code-login-body {
  display: flex;
  flex-direction: column;
  margin-top: var(--johnbot-space-6);
}

/* The two waits, which look the same because they are the same to the user: johnBot is busy and
   there is nothing to do. */
.provider-code-login-pending {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--johnbot-space-2);
  padding: var(--johnbot-space-8) 0;
  text-align: center;
}

.provider-code-login-code {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--johnbot-space-4);
}

.provider-code-login-steps {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-1);
  margin: 0;
  padding-left: var(--johnbot-space-4);
  list-style: decimal;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
  align-self: stretch;
}

/* The link is a button, so it needs the baseline of the sentence it sits in rather than a line of
   its own. */
.provider-code-login-url {
  display: inline-flex;
  height: auto;
  gap: var(--johnbot-space-1-5);
  padding: 0;
}

.provider-code-login-url > svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: 0 0 auto;
  stroke-width: var(--johnbot-icon-stroke);
}

.provider-code-login-value {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-3);
  align-self: stretch;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-surface);
  padding: var(--johnbot-space-3) var(--johnbot-space-4);
}

/* The copy icon belongs to the label beside it, not to the code: the default icon size would make
   it the second largest thing in the row. */
.provider-code-login-copy > svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: 0 0 auto;
  stroke-width: var(--johnbot-icon-stroke);
}

.provider-code-login-digits {
  font-family: var(--johnbot-font-mono);
  font-size: var(--johnbot-text-2xl);
  line-height: var(--johnbot-leading-2xl);
  font-weight: var(--johnbot-weight-semibold);
  letter-spacing: var(--johnbot-tracking-wide);
}

/* The pasted code and its button, full width under the steps. */
.provider-code-login-paste {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-3);
  align-self: stretch;
}

.provider-code-login-expiry {
  margin: 0;
  text-align: center;
}

/* The app hand-off has no phase to show: only its two actions, in the order of a dialog footer. */
.provider-use-app-actions {
  flex-direction: row;
  justify-content: flex-end;
  gap: var(--johnbot-space-2);
}

.provider-code-login-close {
  position: absolute;
  top: var(--johnbot-space-3);
  right: var(--johnbot-space-3);
}

@keyframes provider-code-login-dialog-in {
  from {
    opacity: 0;
    transform: scale(0.97);
  }
}

/* === from: @johnbot/ui/features/conversation/conversation.css === */
/* Import order preserves the conversation cascade. Keep later overrides after base rules. */
@import "katex/dist/katex.min.css";
/* layout.css */
.conversation-panel {
  position: relative;
  display: flex;
  grid-column: 3;
  grid-row: 1;
  min-width: 0;
  flex-direction: column;
  background: var(--johnbot-bg-canvas);
  transition: padding-right var(--panel-resize-duration, var(--johnbot-duration-overlay)) cubic-bezier(0.22, 1, 0.36, 1);
  --conversation-column-width: 1440px;
}

/*
 * On a very wide screen the chat stops at a column and centers in the pane, so a reply and the
 * user's message stay near each other. A laptop window is narrower than the column and shows the
 * chat at full width. The scroll area and the composer keep the pane width, so the scroll bar stays
 * at the pane edge. The live content under the messages, such as the working row and a pending
 * question, stays in the same column.
 */
.conversation-panel > .conversation-scroll > :is(.virtual-chat-list, .conversation-live) {
  max-width: var(--conversation-column-width);
  margin-inline: auto;
}

/*
 * The composer is 6px wider on each side than the messages, as at full width. The padding holds the
 * composer and the notices above it in the column, and keeps their own side margins. A percentage
 * padding is relative to the panel, so the settings panel width is subtracted where it shows.
 */
.conversation-panel > .composer-wrap {
  padding-inline: max(var(--johnbot-space-1-5), calc((100% - var(--conversation-column-width) - 12px) / 2));
}

.conversation-panel:has(.settings-panel) > .composer-wrap {
  padding-inline: max(
    var(--johnbot-space-1-5),
    calc((100% - var(--settings-panel-width, 360px) - var(--conversation-column-width) - 12px) / 2)
  );
}

/*
 * An open side thread covers the agent's own chat and its message box. They leave the layout but stay
 * at the pane width, so their rows, scroll position and draft are there again on the way back. Their
 * content is not rendered: a selected sliding tab, such as a code preview, sets its own visibility.
 * The content keeps the size that the browser remembers from its last render, so the scroll area keeps
 * its height and position. Without containment, the remembered size changes nothing.
 */
.conversation-panel > .conversation-covered {
  position: absolute;
  inset: 0;
  visibility: hidden;
}

.conversation-panel > :is(.conversation-scroll, .composer-wrap) > * {
  contain-intrinsic-size: auto none;
}

.conversation-panel > .conversation-covered > * {
  content-visibility: hidden;
}

.conversation-panel > .composer-wrap.conversation-covered {
  top: auto;
}

/*
 * The mention picker is positioned in the composer wrap and is 12px narrower on each side than the
 * composer. Here a percentage is relative to the composer wrap.
 */
.conversation-panel > .composer-wrap .mention-picker {
  --mention-picker-side-inset: max(
    calc(var(--johnbot-space-1-5) + 12px),
    calc((100% - var(--conversation-column-width) + 12px) / 2)
  );
}

