}

.chat-search .chat-search-input {
  min-width: 0;
  height: var(--johnbot-control-md);
  flex: 1;
  border: 0;
  background: transparent;
  padding: 0 8px;
  box-shadow: none;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
}

.chat-search .chat-search-input:focus {
  border: 0;
  box-shadow: none;
  outline: 0;
}

.chat-search-input::-webkit-search-cancel-button {
  display: none;
}

.chat-search-position {
  min-width: 38px;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  font-variant-numeric: tabular-nums;
  text-align: center;
}

.chat-search-separator {
  width: 1px;
  height: 20px;
  flex: 0 0 auto;
  background: var(--johnbot-border);
}

.chat-search .chat-search-button {
  width: 26px;
  height: var(--johnbot-control-md);
  flex: 0 0 auto;
  border: 0;
  border-radius: inherit;
  padding: 0;
}

.chat-search-button svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  stroke-width: var(--johnbot-icon-stroke);
}

.chat-search .chat-search-close {
  margin-right: 3px;
}

::highlight(johnbot-chat-search-results) {
  background: var(--johnbot-accent-soft);
}

::highlight(johnbot-chat-search-current) {
  background: var(--johnbot-warning);
  color: var(--johnbot-paper-text);
}

.conversation-title[aria-label="View agent settings"]:hover {
  color: var(--johnbot-text-primary);
}

.browser-panel {
  position: absolute;
  z-index: 14;
  top: 0;
  right: 0;
  bottom: 0;
  display: flex;
  width: var(--browser-panel-width, 380px);
  flex-direction: column;
  border-left: 1px solid var(--johnbot-border);
  background: var(--johnbot-bg-canvas);
  color: var(--johnbot-text-primary);
  transition:
    border-color var(--johnbot-duration-slow) ease,
    box-shadow var(--johnbot-duration-slow) ease;
}

/* file-preview.css */
/* transitions.dev panel reveal for the file preview. The panel enters from
   the right edge, so it travels on X. `.browser-panel` declares its own
   transition later in the cascade than the `.t-panel-slide` snippet, so both
   property lists are restated here at a higher specificity. */
.file-preview-panel.t-panel-slide {
  --panel-translate-x: 24px;
  --panel-translate-y: 0px;

  transition:
    transform var(--panel-close-dur) var(--panel-ease),
    opacity var(--panel-close-dur) var(--panel-ease),
    filter var(--panel-close-dur) var(--panel-ease),
    border-color var(--johnbot-duration-slow) ease,
    box-shadow var(--johnbot-duration-slow) ease;
}

.file-preview-panel.t-panel-slide[data-open="true"] {
  transition:
    transform var(--panel-open-dur) var(--panel-ease),
    opacity var(--panel-open-dur) var(--panel-ease),
    filter var(--panel-open-dur) var(--panel-ease),
    border-color var(--johnbot-duration-slow) ease,
    box-shadow var(--johnbot-duration-slow) ease;
}

.file-preview-header {
  display: flex;
  height: 39px;
  flex: 0 0 auto;
  align-items: center;
  gap: 8px;
  border-bottom: 1px solid var(--johnbot-border);
  padding: 0 7px 0 11px;
}

.file-preview-header h2 {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  margin: 0;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Copy is a shared icon button; its icon matches the other header icons. */
.file-preview-copy svg {
  width: 15px;
  height: 15px;
  stroke-width: 2;
}

.file-preview-file-icon {
  width: 15px;
  height: 15px;
  flex: 0 0 auto;
  color: var(--johnbot-text-muted);
  stroke-width: var(--johnbot-icon-stroke);
}

.file-preview-content {
  min-height: 0;
  flex: 1;
  overflow: auto;
  background: var(--johnbot-bg-canvas);
}

.markdown-file-preview {
  min-width: 0;
}

.file-preview-markdown {
  max-width: 760px;
  margin: 0 auto;
  padding: 24px 26px 48px;
  color: var(--johnbot-text-primary);
  overflow-wrap: anywhere;
}

.file-preview-markdown > .message-markdown {
  font-size: var(--johnbot-text-md);
  line-height: 1.6;
}

.file-preview-markdown-status {
  min-width: 0;
  margin: 0;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-surface);
  padding: 18px 20px;
  color: var(--johnbot-text-primary);
  font-family: var(--johnbot-font-mono);
  font-size: var(--johnbot-text-sm);
  line-height: 1.55;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

.file-preview-text {
  min-width: min-content;
  min-height: 100%;
  margin: 0;
  padding: 18px 20px 48px;
  color: var(--johnbot-text-primary);
  font-family: var(--johnbot-font-mono);
  font-size: var(--johnbot-text-sm);
  line-height: 1.55;
  tab-size: 2;
  white-space: pre;
}

.file-preview-text-wrap {
  min-width: 0;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

.file-preview-image-wrap {
  display: grid;
  min-height: 100%;
  padding: 20px;
  place-items: center;
}

.file-preview-image {
  display: block;
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
}

.file-preview-pdf {
  display: block;
  width: 100%;
  height: 100%;
  border: 0;
  background: var(--johnbot-bg-canvas);
}

.file-preview-audio {
  display: block;
  width: calc(100% - 40px);
  margin: 20px;
}

.file-preview-video {
  display: block;
  width: 100%;
  max-height: 100%;
  background: var(--johnbot-bg-canvas);
  object-fit: contain;
}

.file-preview-spreadsheet {
  min-width: 0;
  min-height: 100%;
  padding: 20px;
  color: var(--johnbot-text-primary);
}

.file-preview-spreadsheet-status {
  margin: 0;
  color: var(--johnbot-text-muted);
  font-family: var(--johnbot-font-mono);
  white-space: pre-wrap;
}

.file-preview-spreadsheet-tabs {
  display: flex;
  gap: 6px;
  margin-bottom: 12px;
  overflow-x: auto;
}

.file-preview-spreadsheet-tabs button {
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-sm);
  background: var(--johnbot-bg-control);
  padding: 6px 10px;
  color: var(--johnbot-text-muted);
  white-space: nowrap;
}

.file-preview-spreadsheet-tabs button[aria-pressed="true"] {
  border-color: var(--johnbot-border-strong);
  background: var(--johnbot-bg-surface);
  color: var(--johnbot-text-primary);
}

.file-preview-spreadsheet-table-wrap {
  min-height: 0;
  overflow: auto;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-surface);
}

.file-preview-spreadsheet-table {
  width: max-content;
  min-width: 100%;
  border-collapse: collapse;
  font-size: var(--johnbot-text-sm);
}

.file-preview-spreadsheet-table caption {
  padding: 10px 12px;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  text-align: left;
}

.file-preview-spreadsheet-table th,
.file-preview-spreadsheet-table td {
  border-top: 1px solid var(--johnbot-border);
  border-right: 1px solid var(--johnbot-border);
  padding: 8px 12px;
  text-align: left;
  white-space: pre;
}

.file-preview-spreadsheet-table th {
  background: var(--johnbot-bg-control);
  font-weight: 600;
}

.file-preview-spreadsheet-table td:last-child,
.file-preview-spreadsheet-table th:last-child {
  border-right: 0;
}

.file-preview-spreadsheet-note {
  margin: 10px 0 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}
.file-preview-unsupported {
  display: grid;
  min-height: 100%;
  place-content: center;
  justify-items: center;
  gap: 8px;
  padding: 24px;
  color: var(--johnbot-text-muted);
  text-align: center;
}

.file-preview-unsupported > svg {
  width: 28px;
  height: 28px;
  margin-bottom: 4px;
}

.file-preview-unsupported strong {
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
}

.file-preview-unsupported span {
  max-width: 260px;
  font-size: var(--johnbot-text-sm);
  line-height: 1.45;
}

.file-preview-unsupported button {
  margin-top: 6px;
}

.file-preview-truncated {
  position: sticky;
  bottom: 0;
  margin: 0;
  border-top: 1px solid var(--johnbot-border);
  background: var(--johnbot-bg-control);
  padding: 7px 12px;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  text-align: center;
}
.browser-pip-window {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--johnbot-bg-canvas);
  color: var(--johnbot-text-primary);
}

.browser-pip-surface {
  width: 100%;
  height: 100%;
}

.file-preview-folder {
  display: grid;
  margin: 0;
  padding: 8px;
  list-style: none;
}

.file-preview-folder-entry {
  display: grid;
  width: 100%;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 10px;
  justify-content: stretch;
  padding: 6px 10px;
  font-size: var(--johnbot-text-sm);
  text-align: left;
}

.file-preview-folder-name {
  overflow: hidden;
  color: var(--johnbot-text-primary);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.file-preview-folder-meta {
  color: var(--johnbot-text-muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.file-preview-folder-empty {
  margin: 0;
  padding: 24px;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  text-align: center;
}

/* remote-desktop.css */
.conversation-panel.browser-panel-active {
  padding-right: var(--browser-panel-width, 380px);
}

.remote-desktop-workspace {
  position: fixed;
  z-index: var(--johnbot-layer-toast);
  inset: 0;
  display: flex;
  min-width: 0;
  flex-direction: column;
  background: var(--johnbot-bg-canvas);
  color: var(--johnbot-text-primary);
  opacity: 0;
  pointer-events: none;
  visibility: hidden;
  transition:
    opacity var(--johnbot-duration-fast) cubic-bezier(0.2, 0, 0, 1),
    visibility 0s linear var(--johnbot-duration-fast);
}

.remote-desktop-workspace-visible {
  opacity: 1;
  pointer-events: auto;
  visibility: visible;
  transition-delay: 0s;
}

.remote-desktop-workspace:focus {
  outline: none;
}

.remote-desktop-header {
  display: flex;
  height: 38px;
  min-height: 38px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: flex-start;
  overflow: hidden;
  border-bottom: 1px solid var(--johnbot-border);
  padding: 0 8px 0 0;
  background: var(--johnbot-bg-sidebar);
}

.remote-desktop-workspace-darwin .remote-desktop-header {
  padding-left: 84px;
}

.remote-desktop-actions {
  display: flex;
  min-width: 0;
  align-items: center;
  flex: 0 1 auto;
  justify-content: flex-end;
  gap: 4px;
  margin-left: auto;
  white-space: nowrap;
}

.remote-desktop-display-controls {
  min-width: 0;
  display: flex;
  flex: 0 1 168px;
  align-items: center;
}

.remote-desktop-back-button,
.remote-desktop-disconnect-button {
  flex: 0 0 auto;
}

.remote-desktop-disconnect-button {
  color: var(--johnbot-text-muted);
}

.remote-desktop-disconnect-button:hover:not(:disabled, [aria-disabled="true"]),
.remote-desktop-disconnect-button:focus-visible:not(:disabled, [aria-disabled="true"]) {
  background: var(--johnbot-danger-soft);
  color: var(--johnbot-danger);
}

.remote-desktop-stage {
  position: relative;
  min-height: 0;
  flex: 1;
  overflow: hidden;
  background: var(--johnbot-accent);
}

.remote-desktop-viewer,
.remote-desktop-viewer > div {
  width: 100%;
  height: 100%;
}

.remote-desktop-viewer {
  overflow: hidden;
  display: block;
  object-fit: contain;
}

.remote-desktop-display-select {
  width: min(168px, 22vw);
  min-width: 112px;
  flex: 0 1 168px;
  font-size: var(--johnbot-text-sm);
}

.remote-desktop-display-select-content {
  z-index: calc(var(--johnbot-layer-toast) + 1);
}

.remote-desktop-overlay {
  position: absolute;
  inset: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 7px;
  background: var(--johnbot-bg-overlay);
  padding: 24px;
  text-align: center;
}

.remote-desktop-overlay strong {
  max-width: 330px;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: 600;
}

.remote-desktop-connecting-avatar {
  width: 56px;
  height: 56px;
  margin-bottom: 5px;
  filter: drop-shadow(0 8px 18px var(--johnbot-accent-soft));
  opacity: 1;
  transform: translateY(0) scale(1);
  transition:
    opacity var(--johnbot-duration-overlay) var(--johnbot-ease-out),
    transform var(--johnbot-duration-overlay) var(--johnbot-ease-out);
  will-change: opacity, transform;
}

@starting-style {
  .remote-desktop-connecting-avatar {
    opacity: 0;
    transform: translateY(4px) scale(0.96);
  }
}

.remote-desktop-overlay > span:not(.ui-spinner):not(.remote-desktop-empty-mark) {
  max-width: 330px;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: 16px;
}

.remote-desktop-empty-mark {
  display: grid;
  width: 38px;
  height: 38px;
  margin-bottom: 5px;
  place-items: center;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-hover);
  color: var(--johnbot-text-muted);
}

.remote-desktop-empty-mark svg {
  width: 19px;
  height: 19px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: var(--johnbot-icon-stroke);
}

.remote-desktop-overlay > button {
  height: 34px;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-border);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  font-weight: 600;
}

.remote-desktop-overlay > button:hover {
  background: var(--johnbot-border-strong);
}

.remote-desktop-overlay > button {
  min-width: 92px;
  margin-top: 5px;
  padding: 0 13px;
}

.remote-desktop-button-dot {
  position: absolute;
  right: 4px;
  bottom: 4px;
  width: 5px;
  height: 5px;
  border: 1px solid var(--johnbot-bg-sidebar);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-success);
}

/* browser-panel.css */
.browser-pip-controls-document,
.browser-pip-controls-document body,
.browser-pip-controls-document #root {
  background: transparent;
}

.browser-pip-hover-controls {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: flex-end;
  gap: 2px;
  padding: 4px;
  opacity: 0;
  transition: opacity var(--johnbot-duration-fast) ease;
  -webkit-app-region: drag;
}

.browser-pip-hover-controls:hover,
.browser-pip-hover-controls:focus-within,
.browser-pip-window-hover .browser-pip-hover-controls {
  opacity: 1;
}

.browser-pip-hover-button {
  display: grid;
  width: 20px;
  height: 22px;
  flex: 0 0 20px;
  place-items: center;
  border: 0;
  border-radius: var(--johnbot-radius-sm);
  padding: 0;
  background: var(--johnbot-bg-overlay);
  color: var(--johnbot-text-secondary);
  -webkit-app-region: no-drag;
}

.browser-pip-hover-button:hover {
  background: var(--johnbot-bg-control-hover);
  color: var(--johnbot-text-primary);
}

.browser-pip-hover-button .browser-toolbar-icon {
  width: 12px;
  height: 12px;
}

.browser-pip-hover-button:active {
  transform: scale(0.96);
  transition: transform var(--johnbot-duration-fast) cubic-bezier(0.23, 1, 0.32, 1);
}

.browser-tab-control-icon {
  width: 12px;
  height: 12px;
  overflow: visible;
  fill: currentColor;
}

.browser-toolbar-button {
  display: grid;
  place-items: center;
  border: 0;
  background: transparent;
  color: var(--johnbot-text-muted);
}

.browser-toolbar-button:hover:not(:disabled) {
  background: var(--johnbot-border);
  color: var(--johnbot-text-primary);
}

.browser-toolbar-button {
  width: 25px;
  height: 25px;
  flex: 0 0 25px;
  border-radius: var(--johnbot-radius-sm);
}

.browser-toolbar-button:disabled {
  color: var(--johnbot-text-dim);
  cursor: default;
}

.browser-toolbar-icon {
  width: 15px;
  height: 15px;
}

.browser-profile-status,
.browser-recording-status,
.browser-diagnostic-status {
  display: inline-flex;
  height: 24px;
  flex: 0 0 auto;
  align-items: center;
  gap: 4px;
  border-radius: var(--johnbot-radius-sm);
  padding: 0 5px;
  font-size: var(--johnbot-text-sm);
  line-height: 1;
}

.browser-recording-status {
  background: var(--johnbot-danger-soft);
  color: var(--johnbot-danger);
}

.browser-diagnostic-status {
  background: var(--johnbot-warning-soft);
  color: var(--johnbot-warning);
}

.browser-profile-status {
  min-width: 0;
  max-width: 160px;
  flex-shrink: 1;
  background: var(--johnbot-bg-control);
  color: var(--johnbot-text-secondary);
}

/* The color of a profile: in its toolbar label, the agent select and the server settings. */
.browser-profile-dot {
  display: block;
  width: 8px;
  height: 8px;
  flex: 0 0 auto;
  border-radius: var(--johnbot-radius-pill);
}

.browser-profile-dot-shared {
  background: var(--johnbot-text-muted);
}

.browser-profile-status-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.browser-profile-status svg,
.browser-recording-status svg,
.browser-diagnostic-status svg {
  width: 12px;
  height: 12px;
}

.browser-surface {
  position: relative;
  min-height: 0;
  flex: 1;
  overflow: hidden;
  background: var(--johnbot-bg-canvas);
}

/* The live view of a host's tab. It fills the surface the native view would have covered. */
.browser-live-view {
  position: absolute;
  inset: 0;
}

.browser-live-view canvas {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.browser-empty-state {
  display: grid;
  height: 100%;
  place-content: center;
  gap: 5px;
  color: var(--johnbot-text-muted);
  text-align: center;
}

.browser-empty-state strong {
  font-size: var(--johnbot-text-lg);
  font-weight: 600;
}

.browser-empty-state span {
  font-size: var(--johnbot-text-sm);
}

/* agent-settings.css */
.agent-settings-avatar-picker {
  position: relative;
  z-index: 30;
  display: grid;
  width: 62px;
  height: 62px;
  margin: var(--johnbot-space-2) auto var(--johnbot-space-4);
  place-items: center;
}

.agent-settings-avatar {
  position: relative;
  display: grid;
  width: 62px;
  height: 62px;
  margin: 0;
  place-items: center;
  border: 0;
  border-radius: var(--johnbot-radius-pill);
  background: transparent;
}

.agent-settings-avatar .agent-avatar {
  --agent-avatar-optical-offset: calc(62px * -0.14);
  width: 62px;
  height: 62px;
}

.agent-settings-avatar .agent-avatar > svg {
  width: 128%;
  height: 128%;
}

.agent-settings-avatar:hover {
  filter: brightness(1.08);
}

/* The pencil badge of the mobile edit screen: it shows that the face opens an editor. */
.agent-settings-avatar-badge {
  position: absolute;
  right: -4px;
  bottom: -4px;
  display: grid;
  width: 24px;
  height: 24px;
  place-items: center;
  border: 3px solid var(--johnbot-bg-canvas);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-control);
  color: var(--johnbot-text-primary);
}

.agent-settings-avatar-badge-icon {
  width: 11px;
  height: 11px;
}

.agent-routines-overlay {
  position: absolute;
  z-index: 2;
  top: 39px;
  right: 0;
  bottom: 0;
  left: 0;
  overflow-y: auto;
  background: var(--johnbot-bg-canvas);
}

.agent-routines-settings {
  min-height: 100%;
  padding: 12px 15px 28px;
}

.agent-routines-list,
.agent-routine-run-list {
  display: grid;
}

.agent-routines-list {
  gap: 0;
}

.agent-routine-list-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 4px;
  align-items: center;
}

.agent-routine-row {
  display: grid;
  width: 100%;
  min-height: 48px;
  grid-template-columns: 16px minmax(0, 1fr);
  gap: 9px;
  align-items: center;
  border: 1px solid transparent;
  border-radius: var(--johnbot-radius-md);
  background: transparent;
  padding: 5px 7px;
  text-align: left;
  transition:
    border-color var(--johnbot-duration-hover) ease,
    background-color var(--johnbot-duration-hover) ease;
}

.agent-routine-row:focus-visible {
  border-color: var(--johnbot-border-strong);
  background: var(--johnbot-hover);
}

.agent-routine-row > span:nth-child(2) {
  display: grid;
  min-width: 0;
  gap: 2px;
}

.agent-routine-row strong,
.agent-routine-row small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-routine-row strong {
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: 500;
}

.agent-routine-row small,
.agent-routines-empty {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

.agent-routine-action-buttons svg {
  width: 15px;
  height: 15px;
}

.agent-routine-status-icon-active,
.agent-routine-status-icon-paused {
  display: grid;
  place-items: center;
}

.agent-routine-status-icon-active {
  color: var(--johnbot-success);
}

.agent-routine-status-icon-paused {
  color: var(--johnbot-text-muted);
}

.agent-routine-status-icon-active > svg,
.agent-routine-status-icon-paused > svg {
  width: 14px;
  height: 14px;
  stroke-width: var(--johnbot-icon-stroke);
}

@media (hover: hover) and (pointer: fine) {
  .agent-routine-row:hover {
    border-color: var(--johnbot-border);
    background: var(--johnbot-hover);
  }
}

.agent-routine-editor-actions {
  display: grid;
  gap: 11px;
  margin-bottom: 20px;
  border-bottom: 1px solid var(--johnbot-border);
  padding-bottom: 16px;
}

.agent-routine-active-toggle,
.agent-routine-action-buttons,
.agent-routine-run-row {
  display: flex;
  align-items: center;
}

.agent-routine-active-toggle {
  justify-content: space-between;
}

.agent-routine-active-toggle > span {
  display: grid;
  gap: 2px;
}

.agent-routine-active-toggle strong {
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
}

.agent-routine-active-toggle small {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

.agent-routine-action-buttons {
  flex-wrap: wrap;
  gap: 7px;
}

.agent-routine-action-buttons button {
  display: flex;
  align-items: center;
  gap: 6px;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-control);
  padding: 7px 9px;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
}

.agent-routine-action-buttons button:hover:not(:disabled) {
  background: var(--johnbot-bg-control-hover);
  color: var(--johnbot-text-primary);
}

.agent-routine-when,
.agent-routine-history {
  margin-top: 24px;
}

.agent-routine-history {
  border-top: 1px solid var(--johnbot-border);
  padding-top: 20px;
}

.agent-routine-run-list {
  margin-top: 10px;
}

.agent-routine-run-row {
  display: grid;
  grid-template-columns: 8px minmax(0, 1fr) auto;
  gap: 9px;
  border-bottom: 1px solid var(--johnbot-border);
  padding: 9px 2px;
}

.agent-routines-overlay {
  top: 0;
  overflow: hidden;
}

.agent-routines-settings {
  min-height: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
  padding: 0;
}

.agent-routines-header {
  width: 100%;
}

.agent-routines-heading {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--johnbot-space-0-5);
}

.agent-routines-body {
  min-height: 0;
  flex: 1;
  overflow-y: auto;
  padding: 14px 15px 28px;
  scrollbar-width: none;
}

.agent-routines-body::-webkit-scrollbar {
  display: none;
}

.agent-routine-editor {
  display: grid;
  gap: 14px;
}

.agent-routine-editor > .settings-field {
  margin-bottom: 0;
}

.agent-routine-editor-actions {
  display: flex;
  min-height: 34px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 0;
  border: 0;
  padding: 0;
}

.agent-routine-active-toggle {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
}

/* The shared field puts the label first and fills the row. Here the switch comes first, beside its state word. */
.ui-switch-field.agent-routine-active-toggle {
  width: auto;
  flex-direction: row-reverse;
  justify-content: flex-end;
}

.agent-routine-active-toggle .ui-switch-label {
  font-size: var(--johnbot-text-sm);
  font-weight: inherit;
}

.agent-routine-action-buttons {
  display: flex;
  flex-wrap: nowrap;
  justify-content: flex-end;
  gap: 7px;
}

.agent-routine-action-buttons button {
  min-height: 32px;
  border-radius: var(--johnbot-radius-md);
  padding-inline: 11px;
  font-size: var(--johnbot-text-sm);
}

.agent-routine-action-buttons .ui-button-variant-destructive {
  border-color: transparent;
  background: var(--johnbot-danger-soft);
  color: var(--johnbot-danger);
}

.agent-routine-action-buttons .ui-button-variant-default {
  border-color: transparent;
  background: var(--johnbot-surface-light);
  color: var(--johnbot-text-on-light);
}

@media (hover: hover) and (pointer: fine) {
  .agent-routine-action-buttons .ui-button-variant-destructive:hover:not(:disabled):not([data-disabled]) {
    background: var(--johnbot-danger-soft-hover);
    color: var(--johnbot-danger);
  }

  .agent-routine-action-buttons .ui-button-variant-default:hover:not(:disabled):not([data-disabled]) {
    background: color-mix(in srgb, var(--johnbot-surface-light) 82%, transparent);
    color: var(--johnbot-text-on-light);
  }
}

.agent-routine-instruction-field textarea {
  height: 158px;
  min-height: 158px;
  max-height: 158px;
  overflow-y: auto;
  resize: none;
}

.agent-routine-history {
  margin-top: 2px;
}

.agent-routine-when {
  margin-top: 0;
}

/* What a field misses, under its control, where the field limit goes. */
.agent-routine-field-error {
  margin: var(--johnbot-space-1-5) 0 0 var(--johnbot-space-2);
}

/* Schedule or webhook: two equal choices above the trigger. */
.agent-routine-trigger-kind {
  display: grid;
  min-width: 0;
  grid-template-columns: 1fr 1fr;
  gap: var(--johnbot-space-1);
  margin: 0 0 var(--johnbot-space-2);
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-md);
  padding: var(--johnbot-space-0-5);
}

.agent-routine-trigger-kind-icon {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

/* The schedule and history are fields, so their headings match the field labels. */
.agent-routine-when h3,
.agent-routine-history h3 {
  margin: 0 0 var(--johnbot-space-1-5) var(--johnbot-space-2);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-md);
  font-weight: inherit;
  line-height: var(--johnbot-leading-md);
}

/* A pointer and value row in the webhook filters. A JSON Pointer is longer than its value. */
.agent-routine-event-filter {
  display: grid;
  grid-template-columns: minmax(0, 3fr) minmax(0, 2fr) auto;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.agent-routine-history {
  border: 0;
  padding-top: 0;
}

.agent-routine-run-list {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0;
  margin-top: 0;
}

.agent-routine-run-row {
  display: flex;
  width: 100%;
  min-height: 32px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border: 0;
  border-radius: var(--johnbot-radius-sm);
  padding: 5px var(--johnbot-space-2);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  text-align: left;
}

.ui-button.agent-routine-run-link {
  cursor: pointer;
}

/* The time, then a muted note: an ignored webhook request, skipped runs, a late start, or why a run failed. */
.agent-routine-run-text {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-wrap: wrap;
  gap: 0 var(--johnbot-space-2);
  white-space: nowrap;
}

.agent-routine-run-note {
  min-width: 0;
  overflow: hidden;
  color: var(--johnbot-text-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-routine-history-error {
  margin-bottom: var(--johnbot-space-2);
}

/* A run whose answer went to a messaging place: the run row, then where the answer went. */
.agent-routine-run-entry {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
}

.agent-routine-delivery-row {
  display: flex;
  min-height: 28px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0 var(--johnbot-space-2) 5px;
  font-size: var(--johnbot-text-sm);
}

/* The reason is why the answer is missing from the place, so it wraps rather than cuts off. */
.agent-routine-delivery-note {
  min-width: 0;
  color: var(--johnbot-text-muted);
  overflow-wrap: anywhere;
  white-space: normal;
}

.agent-routine-delivery-failed,
.agent-routine-delivery-uncertain {
  color: var(--johnbot-warning);
}

@media (hover: hover) and (pointer: fine) {
  .ui-button.agent-routine-run-link:hover:not(:disabled) {
    background: var(--johnbot-bg-control-hover);
  }
}

.agent-routine-run-icon {
  display: grid;
  width: 18px;
  height: 18px;
  flex: 0 0 18px;
  place-items: center;
  color: var(--johnbot-text-muted);
}

.agent-routine-run-icon > svg {
  width: 16px;
  height: 16px;
  stroke-width: var(--johnbot-icon-stroke);
}

.agent-routine-run-icon-succeeded {
  color: var(--johnbot-success);
}

.agent-routine-run-icon-failed {
  color: var(--johnbot-danger);
}

.agent-routine-run-icon-needs-attention {
  color: var(--johnbot-warning);
}

.agent-routine-run-icon-running,
.agent-routine-run-icon-queued,
.agent-routine-run-icon-interrupted,
.agent-routine-run-icon-cancelled {
  color: var(--johnbot-text-muted);
}

/* The overlay fades out with the modal, which is not one of its children. */
.agent-memories-overlay[data-closed] {
  animation: agent-dialog-overlay-out var(--johnbot-duration-dialog) ease;
}

.agent-memories-modal {
  position: fixed;
  z-index: calc(var(--johnbot-layer-dialog) + 1);
  top: 50%;
  left: 50%;
  width: min(560px, calc(100vw - 48px));
  height: min(456px, calc(100dvh - 48px));
  min-height: 320px;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  overflow: hidden;
  outline: 0;
  background: var(--johnbot-bg-control);
  color: var(--johnbot-text-primary);
  transform: translate(-50%, -50%);
  transform-origin: center;
}

.agent-memories-header {
  display: flex;
  min-height: 48px;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-3);
  border-bottom: 1px solid var(--johnbot-border);
  padding: var(--johnbot-space-2) var(--johnbot-space-2) var(--johnbot-space-2) var(--johnbot-space-3);
}

.agent-memories-heading {
  min-width: 0;
}

.agent-skills-heading {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-1);
}

.agent-skills-parent {
  min-width: 0;
  height: auto;
  overflow: hidden;
  border: 0;
  background: transparent;
  color: var(--johnbot-text-muted);
  padding: 0;
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-lg);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-skills-crumb {
  flex: 0 0 auto;
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  color: var(--johnbot-text-muted);
}

.agent-skills-heading h2 {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-memories-heading h2 {
  margin: 0;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-lg);
}

.agent-memories-header-actions {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: var(--johnbot-space-1);
}

.agent-memories-header-actions svg,
.agent-memory-delete-button svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.agent-memories-add-button {
  color: var(--johnbot-text-secondary);
}

.agent-memories-body {
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  padding: var(--johnbot-space-2);
}

.agent-memory-composer {
  display: grid;
  gap: var(--johnbot-space-2);
  margin: 0 0 var(--johnbot-space-3);
  padding: var(--johnbot-space-1) var(--johnbot-space-1) 0;
}

.agent-memory-input {
  min-height: 64px;
  resize: none;
  border-color: var(--johnbot-border);
  background: transparent;
}

.agent-memory-input:focus-visible {
  border-color: var(--johnbot-border-strong);
  outline: 0;
  box-shadow: none;
}

.agent-memory-composer-actions,
.agent-memory-editor-actions {
  display: flex;
  justify-content: flex-end;
  gap: var(--johnbot-space-1);
}

.agent-memory-inclusion-actions {
  margin: 0;
  padding: 0;
  border: 0;
  min-width: 0;
  display: flex;
  flex-wrap: wrap;
  gap: var(--johnbot-space-1);
}

.agent-memory-list {
  min-height: 0;
  display: grid;
  grid-auto-rows: max-content;
  flex: 1;
  align-content: start;
  gap: var(--johnbot-space-0-5);
  overflow-y: auto;
  margin: 0;
  padding: 0;
  list-style: none;
  scrollbar-width: none;
}

.agent-memory-row {
  min-height: 50px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) calc(var(--johnbot-control-md) + var(--johnbot-space-2));
  align-items: stretch;
  border-radius: var(--johnbot-radius-md);
  overflow: hidden;
  background: transparent;
}

@media (hover: hover) and (pointer: fine) {
  .agent-memory-row:hover {
    background: var(--johnbot-bg-control-hover);
  }
}

.agent-memory-row:has(.agent-memory-row-main:focus-visible) {
  background: var(--johnbot-bg-control-active);
}

.agent-memory-row-main {
  min-width: 0;
  width: 100%;
  height: 100%;
  display: grid;
  align-content: center;
  justify-content: stretch;
  justify-items: start;
  gap: var(--johnbot-space-1);
  border: 0;
  border-radius: 0;
  outline: 0;
  background: transparent;
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
  color: inherit;
  font: inherit;
  text-align: left;
}

.agent-memory-row-main:focus-visible {
  box-shadow: none;
}

.agent-memory-row .agent-memory-row-main:hover {
  background: transparent;
}

.agent-memory-text {
  display: block;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
  white-space: pre-wrap;
}

.agent-memory-meta {
  display: block;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.agent-memory-delete-button {
  align-self: center;
  align-items: center;
  justify-self: center;
  color: var(--johnbot-text-muted);
}

.agent-memory-editor {
  grid-column: 1 / -1;
  display: grid;
  gap: var(--johnbot-space-2);
  background: transparent;
  padding: var(--johnbot-space-1) var(--johnbot-space-1) var(--johnbot-space-2);
}

.agent-memory-row:has(.agent-memory-editor),
.agent-memory-row:has(.agent-memory-editor):hover {
  background: transparent;
}

.agent-memory-state,
.agent-memory-limit,
.agent-memory-error {
  margin: var(--johnbot-space-1);
  border-radius: var(--johnbot-radius-md);
  padding: var(--johnbot-space-3);
  font-size: var(--johnbot-text-sm);
}

.agent-memory-state {
  min-height: 160px;
  display: grid;
  place-items: center;
  color: var(--johnbot-text-muted);
  text-align: center;
}

.agent-memory-limit {
  background: var(--johnbot-bg-surface);
  color: var(--johnbot-text-secondary);
}

.agent-memory-error {
  background: var(--johnbot-danger-soft);
  color: var(--johnbot-danger);
}

/*
 * The dialog before its first memory: a faint copy of the list above the pitch. The newest sample
 * writes itself in handwriting; when the next one comes, it becomes a typed row and steps back.
 */
.agent-memories-empty {
  display: grid;
  flex: 1;
  min-height: 0;
  grid-template-rows: minmax(0, 1fr) auto;
}

.agent-memories-empty-list {
  min-width: 0;
  overflow: hidden;
  pointer-events: none;
  user-select: none;
  mask-image: linear-gradient(var(--johnbot-text-primary) 45%, var(--johnbot-transparent));
  transition:
    opacity 700ms var(--johnbot-ease-out),
    filter 700ms var(--johnbot-ease-out);
}

.agent-memories-empty-list[data-clearing] {
  opacity: 0;
  filter: blur(3px);
}

/* A new row opens from no height, so the rows under it move down. */
.agent-memories-empty-item {
  display: grid;
  grid-template-rows: 1fr;
  animation: agent-memories-empty-open 520ms var(--johnbot-ease-out) both;
  transition: opacity 640ms var(--johnbot-ease-out);
}

.agent-memories-empty-item > *,
.agent-memories-empty-fold > * {
  min-height: 0;
  overflow: hidden;
}

@keyframes agent-memories-empty-open {
  from {
    grid-template-rows: 0fr;
    opacity: 0;
  }
}

.agent-memories-empty-item[data-age="1"] {
  opacity: 0.6;
}

.agent-memories-empty-item[data-age="2"] {
  opacity: 0.4;
}

.agent-memories-empty-item[data-age="3"] {
  opacity: 0.25;
}

/* The sample rows keep the real row styles, with no fixed height. */
.agent-memories-empty-row {
  min-height: 0;
}

.agent-memories-empty-row .agent-memory-row-main {
  height: auto;
}

/* The two texts of a row: the handwriting folds away and the typed text opens when the ink is dry. */
.agent-memories-empty-fold {
  display: grid;
  transition:
    grid-template-rows 640ms var(--johnbot-ease-out),
    opacity 640ms var(--johnbot-ease-out);
}

.agent-memories-empty-fold-hand {
  grid-template-rows: 1fr;
}

.agent-memories-empty-fold-typed {
  grid-template-rows: 0fr;
  opacity: 0;
}

.agent-memories-empty-item[data-dry] .agent-memories-empty-fold-hand {
  grid-template-rows: 0fr;
  opacity: 0;
}

.agent-memories-empty-item[data-dry] .agent-memories-empty-fold-typed {
  grid-template-rows: 1fr;
  opacity: 1;
}

/* Handwriting. The app has no hand font, so it uses the one of the system. */
.agent-memories-hand {
  color: var(--johnbot-accent-text);
  font-family: "Bradley Hand", "Noteworthy", "Segoe Print", cursive;
  font-weight: var(--johnbot-weight-semibold);
}

.agent-memories-empty-hand {
  display: grid;
  padding-block: var(--johnbot-space-0-5);
  font-size: var(--johnbot-text-xl);
  line-height: 1.3;
  transform: rotate(-0.6deg);
  transform-origin: left top;
}

/* Each line writes itself from left to right, at the speed of its length. */
.agent-memories-empty-line {
  white-space: nowrap;
  clip-path: inset(-0.4em calc(100% + 0.2em) -0.4em -0.2em);
  animation: agent-memories-empty-write var(--agent-memories-empty-length) linear var(--agent-memories-empty-delay)
    forwards;
}

@keyframes agent-memories-empty-write {
  to {
    clip-path: inset(-0.4em -0.2em -0.4em -0.2em);
  }
}

.agent-memories-empty-meta {
  opacity: 0;
  animation: agent-memories-empty-show 360ms var(--johnbot-ease-out) var(--agent-memories-empty-delay) forwards;
}

@keyframes agent-memories-empty-show {
  to {
    opacity: 1;
  }
}

.agent-memories-empty-pitch {
  z-index: 1;
  display: grid;
  justify-items: center;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-3) var(--johnbot-space-4);
  text-align: center;
}

.agent-memories-empty-title {
  display: grid;
  margin: 0;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-3xl);
  font-weight: var(--johnbot-weight-semibold);
  letter-spacing: -0.01em;
  line-height: 1.2;
}

.agent-memories-empty-title > .agent-memories-empty-lead {
  color: var(--johnbot-text-muted);
}

/* The one handwritten word of the title. It writes itself once. */
/* Inline, not inline-block: a reader then hears "remember." with no space before the full stop. */
.agent-memories-empty-word {
  line-height: 1;
  clip-path: inset(-0.4em calc(100% + 0.2em) -0.4em -0.2em);
  animation: agent-memories-empty-write 640ms linear 400ms forwards;
}

.agent-memories-empty-lines {
  display: grid;
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-lg);
  line-height: var(--johnbot-leading-lg);
}

.agent-memories-empty-action {
  margin-top: var(--johnbot-space-1);
}

/* Less motion: one still frame with the full list. */
.agent-memories-empty[data-still]
:is(
  .agent-memories-empty-item,
  .agent-memories-empty-fold,
  .agent-memories-empty-line,
  .agent-memories-empty-meta,
  .agent-memories-empty-word
) {
  animation: none;
  transition: none;
  clip-path: none;
}

.agent-memories-empty[data-still]
  :is(.agent-memories-empty-line, .agent-memories-empty-meta, .agent-memories-empty-word) {
  opacity: 1;
}

.shared-table-list {
  min-height: 0;
  display: grid;
  flex: 1;
  align-content: start;
  gap: var(--johnbot-space-0-5);
  overflow-y: auto;
  margin: 0;
  padding: 0;
  list-style: none;
  scrollbar-width: none;
}

.shared-table-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-md);
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
}

.shared-table-main {
  min-width: 0;
  display: grid;
  gap: var(--johnbot-space-1);
}

.shared-table-name {
  display: block;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-md);
}

.shared-table-confirm {
  grid-column: 1 / -1;
  display: grid;
  gap: var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-surface);
  padding: var(--johnbot-space-3);
}

.shared-table-confirm p {
  margin: 0;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.shared-table-confirm-actions {
  display: flex;
  justify-content: flex-end;
  gap: var(--johnbot-space-1);
}

.agent-memories-footer {
  display: flex;
  min-height: 48px;
  align-items: center;
  padding: var(--johnbot-space-2) var(--johnbot-space-3) var(--johnbot-space-3);
}

.agent-skill-empty {
  min-height: 160px;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: var(--johnbot-space-3);
}

.agent-skill-empty .agent-memory-state {
  min-height: 0;
  padding: 0;
}

.agent-skill-rows {
  display: grid;
  align-content: start;
  gap: 2px;
}

.agent-skill-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: var(--johnbot-space-2);
  min-height: 56px;
  padding: var(--johnbot-space-1) var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-lg);
}

.agent-skill-open {
  min-width: 0;
  height: auto;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  justify-content: stretch;
  justify-items: stretch;
  align-items: center;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-1);
  color: inherit;
  text-align: left;
}

.agent-skill-open:hover {
  background: transparent;
}

@media (hover: hover) and (pointer: fine) {
  .agent-skill-row:hover {
    background: var(--johnbot-bg-control-hover);
  }
}

.agent-skill-icon {
  width: 40px;
  height: 40px;
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  overflow: hidden;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-control);
  color: var(--johnbot-accent-text);
}

.agent-skill-icon img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.agent-skill-icon svg {
  width: 20px;
  height: 20px;
}

.agent-skill-copy {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.agent-skill-title {
  display: flex;
  min-width: 0;
  align-items: baseline;
  gap: var(--johnbot-space-2);
}

.agent-skill-title strong {
  overflow: hidden;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-md);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-skill-row:has(.agent-skill-update) {
  grid-template-columns: minmax(0, 1fr) auto auto auto;
}

.ui-button.agent-skill-update {
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-accent-soft);
  color: var(--johnbot-accent-text);
  font-size: var(--johnbot-text-sm);
}

.ui-button.agent-skill-update:hover:not(:disabled):not([data-disabled]),
.ui-button.agent-skill-update:focus-visible {
  background: color-mix(in srgb, var(--johnbot-accent-soft), var(--johnbot-accent) 12%);
  color: var(--johnbot-accent-text);
}

.agent-skill-copy small {
  overflow: hidden;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-skill-row-disabled .agent-skill-title strong {
  color: var(--johnbot-text-muted);
}

.agent-skill-more {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border: 0;
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-control-active);
  color: var(--johnbot-text-secondary);
  opacity: 0;
  cursor: pointer;
}

.agent-skill-more svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.agent-skill-row:hover .agent-skill-more,
.agent-skill-row:focus-within .agent-skill-more,
.agent-skill-row:has([aria-expanded="true"]) .agent-skill-more {
  opacity: 1;
}

.agent-skill-menu {
  z-index: calc(var(--johnbot-layer-dialog) + var(--johnbot-layer-popover) + 1);
}

.agent-skills-modal .ui-switch[data-checked] {
  background: var(--johnbot-accent);
}

.agent-skills-modal .ui-switch-thumb[data-checked] {
  background: var(--johnbot-text-primary);
}

.agent-local-library,
.agent-skill-detail {
  min-height: 0;
  display: grid;
  align-content: start;
  gap: var(--johnbot-space-4);
  overflow: auto;
  padding: var(--johnbot-space-3);
  scrollbar-width: none;
}

.agent-local-library::-webkit-scrollbar,
.agent-skill-detail::-webkit-scrollbar {
  display: none;
}

.agent-memories-modal[data-expanded] {
  animation: agent-dialog-content-in var(--johnbot-duration-dialog) ease;
}

.agent-memories-modal[data-closed] {
  animation: agent-dialog-content-out var(--johnbot-duration-dialog) ease;
}

@keyframes agent-dialog-overlay-out {
  to {
    opacity: 0;
  }
}

@keyframes agent-dialog-content-in {
  from {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.95);
  }
}

@keyframes agent-dialog-content-out {
  to {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.95);
  }
}

@media (max-width: 520px) {
  .agent-memories-modal {
    width: calc(100vw - 24px);
    height: calc(100dvh - 24px);
  }

  .agent-memories-header {
    padding-left: var(--johnbot-space-3);
  }
}

@media (prefers-reduced-motion: reduce) {
  .agent-memories-overlay,
  .agent-memories-modal {
    animation: none;
  }
}

/* The root list and each page behind it: one column of cards with an even gap. */
.agent-settings-page {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-4);
}

.agent-settings-page > .settings-field {
  margin: 0;
}

/* A switch row inside an inset group: as tall as a link row, the switch on the right. */
.agent-settings-switch-row {
  display: flex;
  min-height: 40px;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-2);
  padding: 0 var(--johnbot-space-3);
}

.agent-settings-switch-row > .settings-link-label {
  flex: 1 1 auto;
}

/* A provider setting: its row, then the notes under it. The row rounds with the card at an end. */
.agent-session-setting > .ui-select,
.agent-session-setting .agent-settings-runtime-row {
  border-radius: inherit;
}

.agent-session-setting-notes {
  display: grid;
  justify-items: start;
  gap: var(--johnbot-space-1);
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
}

.agent-session-setting > .agent-session-setting-notes {
  padding-top: 0;
}

.agent-session-setting-notes:empty {
  display: none;
}

.agent-settings-runtime-rows .provider-model-trigger-field,
.agent-settings-runtime-rows .agent-settings-runtime-row {
  width: 100%;
  height: auto;
  min-height: 40px;
  gap: var(--johnbot-space-2);
  border: 0;
  border-radius: 0;
  background: transparent;
  padding: 0 var(--johnbot-space-3);
  box-shadow: none;
  font-size: var(--johnbot-text-md);
}

.agent-settings-runtime-rows .provider-model-trigger-field:hover:not(:disabled),
.agent-settings-runtime-rows .provider-model-trigger-field[aria-expanded="true"],
.agent-settings-runtime-rows .agent-settings-runtime-row[data-expanded] {
  background: var(--johnbot-hover);
}

.agent-settings-runtime-rows .provider-model-trigger-field:focus-visible,
.agent-settings-runtime-rows .ui-select .agent-settings-runtime-row:focus-visible {
  outline: 0;
  background: var(--johnbot-hover);
  box-shadow: inset 0 0 0 1px var(--johnbot-border-focus);
}

.agent-settings-runtime-rows .provider-model-trigger-field .provider-model-field-label,
.agent-settings-runtime-label {
  flex: 1 1 auto;
  min-width: 0;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  line-height: 18px;
  text-align: left;
}

.agent-settings-runtime-rows .provider-model-trigger-field .provider-model-trigger-name,
.agent-settings-runtime-row .ui-select-value {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-regular);
}

.agent-settings-runtime-row .ui-select-trigger-icon {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

@media (hover: hover) and (pointer: fine) {
  .agent-settings-runtime-rows .provider-model-trigger-field:hover .provider-model-trigger-name,
  .agent-settings-runtime-row:hover .ui-select-value {
    color: var(--johnbot-text-secondary);
  }
}

.agent-settings-runtime-rows .provider-model-popover {
  width: var(--kb-popper-anchor-width);
  min-width: 0;
}

.agent-settings-runtime-path {
  display: grid;
  gap: 2px;
  padding: 11px var(--johnbot-space-3);
}

.agent-settings-runtime-path > span:last-child {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: 17px;
  overflow-wrap: anywhere;
  user-select: text;
}

.agent-settings-runtime-note {
  margin: 0;
  padding-inline: var(--johnbot-space-1);
  text-wrap: pretty;
}

.agent-settings-save-error {
  margin: 0 var(--johnbot-space-1);
  color: var(--johnbot-danger);
  font-size: var(--johnbot-text-sm);
  line-height: 16px;
}

.agent-settings-notifications {
  display: flex;
  min-height: 70px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 0;
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-border);
  padding: 13px 12px;
}

.agent-settings-notifications > div {
  min-width: 0;
}

.agent-settings-notifications strong,
.agent-settings-notifications span {
  display: block;
}

.agent-settings-notifications strong {
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: 500;
  line-height: 18px;
}

.agent-settings-notifications div > span {
  max-width: 194px;
  margin-top: 2px;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  line-height: 15px;
}

/* agent-folders.css */
/* The Folders row sits in the Rules group after Permissions. The + opens the folder picker; the rest
   of the row opens the Folders page. */
.agent-folders-entry {
  position: relative;
}

/* The + sits over an empty slot in the row, between the count and the chevron; a button cannot hold a button. */
.agent-folders-entry-add-slot {
  flex: none;
  width: 24px;
}

.agent-folders-entry-add {
  position: absolute;
  top: 50%;
  right: calc(var(--johnbot-space-3) + 14px + var(--johnbot-space-2));
  color: var(--johnbot-text-muted);
  transform: translateY(-50%);
}

/* The + is 24px; the row is 40px tall, so it takes a 40px target. */
.agent-folders-entry-add::before {
  position: absolute;
  inset: -8px;
  content: "";
}

/* The count changes as folders come and go; its digits keep one width. */
.agent-folders-count,
.agent-folders-lost {
  font-variant-numeric: tabular-nums;
}

/* A folder that is no longer on the disk shows on the row, so the user does not have to open the page. */
.agent-folders-lost {
  color: var(--johnbot-warning-text);
}

/* The value holds the count, a dot, then the warning; the row's 8px gap is too wide around a dot. */
.agent-folders-dot {
  margin-inline: calc(var(--johnbot-space-1) * -1);
}

/* While a folder is dragged over the side panel, the Folders row and the Added group show where it goes. */
.agent-folders-entry,
.agent-folders-drop-target {
  outline: 1px dashed transparent;
  outline-offset: -1px;
  transition:
    outline-color var(--johnbot-duration-fast) var(--johnbot-ease-out),
    background-color var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.agent-folders-entry[data-dragging],
.agent-folders-drop-target[data-dragging] {
  outline-color: var(--johnbot-text-muted);
  background-color: var(--johnbot-hover);
}

.agent-folders-page {
  display: grid;
  gap: var(--johnbot-space-4);
}

/* Icon, text, then the actions the row has: Locate… for a missing folder, then X. */
.agent-folders-row {
  display: grid;
  grid-auto-columns: auto;
  grid-auto-flow: column;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: var(--johnbot-space-2);
  min-height: 48px;
  padding: var(--johnbot-space-1-5) var(--johnbot-space-1-5) var(--johnbot-space-1-5) var(--johnbot-space-3);
}

.agent-folders-text {
  display: grid;
  min-width: 0;
}

.agent-folders-name {
  overflow: hidden;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-folders-path {
  overflow: hidden;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-folders-row[data-missing] .settings-link-icon,
.agent-folders-row[data-missing] .agent-folders-path {
  color: var(--johnbot-warning-text);
}

/* The note on the Folders page when the agent can change all files. */
.agent-folders-access {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--johnbot-space-2);
  padding: var(--johnbot-space-2) var(--johnbot-space-2) var(--johnbot-space-2) var(--johnbot-space-3);
}

.agent-folders-access-text {
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  text-wrap: pretty;
}

.agent-folders-remove {
  position: relative;
  color: var(--johnbot-text-muted);
}

/* The button is 32px; the row is 48px tall, so it can take a 44px target. */
.agent-folders-remove::before {
  position: absolute;
  inset: -6px;
  content: "";
}

.agent-folders-add {
  color: var(--johnbot-text-secondary);
}

.agent-folders-drop-target[data-dragging] .agent-folders-add {
  color: var(--johnbot-text-primary);
}

/* A folder the user just added comes in under the others. */
@media (prefers-reduced-motion: no-preference) {
  .agent-folders-row[data-fresh] {
    animation: agent-folders-row-in var(--johnbot-duration-normal) var(--johnbot-ease-out) both;
  }

  .agent-folders-chat-drop {
    animation: agent-folders-fade-in var(--johnbot-duration-fast) var(--johnbot-ease-out) both;
  }

  /* The user tried to add a folder that this row already gives: the row shows itself once. */
  .agent-folders-row[data-flash],
  .agent-folders-entry[data-flash] {
    animation: agent-folders-row-flash 900ms var(--johnbot-ease-out);
  }
}

/* Without motion the row stays marked a moment and the mark goes at once. */
@media (prefers-reduced-motion: reduce) {
  .agent-folders-row[data-flash],
  .agent-folders-entry[data-flash] {
    animation: agent-folders-row-flash 900ms steps(1, end);
  }
}

@keyframes agent-folders-row-flash {
  from,
  40% {
    background-color: var(--johnbot-hover);
  }
}

@keyframes agent-folders-row-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
}

@keyframes agent-folders-fade-in {
  from {
    opacity: 0;
  }
}

/* The chat's drop overlay in two halves. It takes the place of the chat's own overlay for a local
   agent in Workspace only mode; with wider access a folder gives nothing new, so files only attach. */
.agent-folders-chat-drop {
  position: absolute;
  z-index: 60;
  inset: var(--johnbot-space-3);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--johnbot-space-3);
  border-radius: var(--johnbot-radius-lg);
  background: color-mix(in srgb, var(--background) 70%, transparent);
  pointer-events: none;
  backdrop-filter: blur(3px);
}

/* The settings panel takes its own drops, so the overlay stops at its edge. */
.conversation-panel:has(.settings-panel) .agent-folders-chat-drop {
  right: calc(var(--settings-panel-width, 360px) + var(--johnbot-space-3));
}

.agent-folders-chat-zone {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-6);
  border: 1px dashed var(--johnbot-text-muted);
  border-radius: var(--johnbot-radius-lg);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-semibold);
  text-align: center;
  text-wrap: balance;
  transition:
    border-color var(--johnbot-duration-fast) var(--johnbot-ease-out),
    background-color var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.agent-folders-chat-zone > span {
  max-width: 28ch;
}

.agent-folders-chat-zone-folder {
  pointer-events: auto;
}

.agent-folders-chat-zone[data-dragging] {
  border-color: color-mix(in srgb, var(--accent) 70%, var(--johnbot-text-primary));
  background: var(--johnbot-hover);
}

.agent-folders-chat-zone svg {
  flex: none;
  width: 24px;
  height: 24px;
  color: var(--johnbot-text-secondary);
  transition: color var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.agent-folders-chat-zone[data-dragging] svg {
  color: var(--johnbot-text-primary);
}

/* routine-schedule.css */
/* Routine schedule row: the frequency and its values as one sentence of chips. */
.routine-trigger-row,
.routine-weekday-strip,
.routine-calendar-days {
  min-width: 0;
  margin: 0;
  border: 0;
  padding: 0;
}

/* Keyboard focus uses the shared focus ring, as the other controls do. The ring is a box shadow, so
   the native outline goes. This rule has the same weight as the accent outline rule in auth.css,
   which loads earlier. */
:is(.routine-schedule-picker, .routine-popover, .routine-chip-select-content)
:is(button, input, textarea):focus-visible {
  outline: 0;
}

:is(.routine-schedule-picker, .routine-popover) .ui-button:focus-visible {
  box-shadow: var(--johnbot-focus-ring);
}

.routine-schedule-picker {
  display: grid;
  min-width: 0;
  gap: var(--johnbot-space-1-5);
}

/* One line at every width. A narrow row shrinks its flexible chip, not the line count. */
/* In a panel the row is a form field, so it has the box of the settings inputs around it. */
.routine-trigger-row {
  display: flex;
  min-width: 0;
  align-items: flex-start;
  gap: var(--johnbot-space-2);
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-shadow-popover-ambient);
  padding: var(--johnbot-space-1);
  transition: border-color var(--johnbot-duration-hover) ease;
}

.routine-trigger-row:focus-within {
  border-color: var(--johnbot-text-muted);
}

.routine-schedule-picker[data-density="card"] .routine-trigger-row {
  border: 0;
  background: none;
  padding: 0;
}

.routine-trigger-icon {
  display: inline-flex;
  width: var(--johnbot-control-md);
  height: var(--johnbot-control-md);
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-accent);
  color: var(--johnbot-text-on-accent);
}

.routine-trigger-icon svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  stroke-width: 2;
}

.routine-schedule-picker[data-density="panel"] .routine-trigger-icon {
  width: var(--johnbot-control-sm);
  height: var(--johnbot-control-sm);
}

.routine-schedule-picker[data-density="card"] .routine-trigger-icon {
  display: none;
}

.routine-trigger-chips {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: center;
  gap: var(--johnbot-space-2);
  /* Clips a row that is narrower than its fixed chips, and keeps the focus ring visible. */
  overflow: clip;
  overflow-clip-margin: var(--johnbot-space-1);
}

.routine-trigger-phrase {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.routine-trigger-phrase-flexible {
  min-width: 0;
  flex-shrink: 1;
}

.routine-connector {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-lg);
  line-height: var(--johnbot-leading-lg);
}

.routine-chip-select {
  width: auto;
  flex: 0 0 auto;
}

.routine-chip-select-flexible {
  min-width: 0;
  flex-shrink: 1;
}

.routine-chip {
  display: inline-flex;
  height: var(--johnbot-control-md);
  min-width: 0;
  max-width: 100%;
  align-items: center;
  gap: var(--johnbot-space-1-5);
  cursor: pointer;
  border: 0;
  border-radius: var(--johnbot-radius-md);
  outline: 0;
  background: var(--johnbot-bg-control-active);
  padding: 0 var(--johnbot-space-3);
  color: var(--johnbot-text-primary);
  font-family: var(--johnbot-font-sans);
  font-size: var(--johnbot-text-lg);
  line-height: var(--johnbot-leading-lg);
  white-space: nowrap;
  flex: 0 0 auto;
  transition: background-color var(--johnbot-duration-hover) ease;
}

.routine-chip-flexible {
  flex-shrink: 1;
}

.routine-chip-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* The chips sit one padding inside the box, so the row is as tall as an input at every width. */
.routine-schedule-picker[data-density="panel"] .routine-chip {
  height: var(--johnbot-control-sm);
  border-radius: var(--johnbot-radius-xs);
}

.routine-schedule-picker[data-density="card"] .routine-chip {
  height: var(--johnbot-control-sm);
  padding: 0 var(--johnbot-space-2);
  font-size: var(--johnbot-text-md);
}

.routine-chip:focus-visible {
  box-shadow: var(--johnbot-focus-ring);
}

.routine-chip:is([aria-expanded="true"], [data-expanded]) {
  background: var(--johnbot-bg-control-hover);
  box-shadow: 0 0 0 1px var(--johnbot-border-strong);
}

.routine-chip:disabled,
.routine-chip[data-disabled] {
  cursor: default;
  background: transparent;
  padding: 0;
  color: var(--johnbot-text-secondary);
}

@media (hover: hover) and (pointer: fine) {
  .routine-chip:hover:not(:disabled, [data-disabled]) {
    background: var(--johnbot-bg-control-hover);
    box-shadow: 0 0 0 1px var(--johnbot-border-strong);
  }
}

.routine-chip-select-content {
  min-width: 160px;
}

.routine-chip-select-content .ui-select-item {
  font-size: var(--johnbot-text-lg);
  line-height: var(--johnbot-leading-lg);
}

.routine-cron-input {
  min-width: 0;
  max-width: 220px;
  flex: 1 1 180px;
  font-family: var(--johnbot-font-mono);
}

.routine-schedule-hint {
  margin: 0;
  padding-left: var(--johnbot-space-2);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.routine-schedule-picker[data-density="card"] .routine-schedule-hint {
  padding-left: 0;
}

/* Popovers */
.routine-popover {
  z-index: var(--johnbot-layer-popover);
  border-radius: var(--johnbot-radius-lg);
  padding: var(--johnbot-space-2);
}

.routine-weekday-strip {
  display: flex;
  gap: var(--johnbot-space-1);
}

.routine-day-item {
  display: inline-flex;
}

.routine-day {
  display: inline-flex;
  width: var(--johnbot-control-md);
  height: var(--johnbot-control-md);
  min-width: 0;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  border-radius: var(--johnbot-radius-pill);
  padding: 0;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
}

.routine-day-item:has(:focus-visible) .routine-day {
  box-shadow: var(--johnbot-focus-ring);
}

/* The strip is short, so an unselected day can look like a button. A month grid stays plain. */
.routine-weekday-strip .routine-day {
  background: var(--johnbot-bg-control-active);
}

@media (hover: hover) and (pointer: fine) {
  .routine-day:hover:not(:disabled, .routine-day-selected) {
    background: var(--johnbot-hover);
    color: var(--johnbot-text-primary);
  }
}

.routine-day.routine-day-selected,
.routine-day.routine-day-selected:hover {
  background: var(--johnbot-text-primary);
  color: var(--johnbot-bg-canvas);
}

.routine-day.routine-day-selected:focus-visible {
  box-shadow: var(--johnbot-focus-ring);
}

/* Time */
.routine-clock-input {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-1-5);
}

.routine-clock-segment.ui-input {
  width: 48px;
  height: var(--johnbot-control-lg);
  border: 0;
  background: var(--johnbot-bg-control-active);
  padding: 0;
  font-size: var(--johnbot-text-lg);
  font-variant-numeric: tabular-nums;
  text-align: center;
}

.routine-clock-separator {
  color: var(--johnbot-text-muted);
}

.routine-segmented {
  display: flex;
  margin-left: var(--johnbot-space-1);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-control-active);
  padding: var(--johnbot-space-0-5);
}

.routine-segmented-control {
  display: inline-flex;
  height: calc(var(--johnbot-control-lg) - 2 * var(--johnbot-space-0-5));
  min-width: 44px;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  border-radius: var(--johnbot-radius-sm);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
}

.routine-segmented-control label {
  cursor: pointer;
}

.routine-segmented-control[data-checked] {
  background: var(--johnbot-text-primary);
  color: var(--johnbot-bg-canvas);
}

.routine-segmented-item:has(:focus-visible) .routine-segmented-control {
  box-shadow: var(--johnbot-focus-ring);
}

/* Hours window: a two-option list and, for "Between hours", the times beside it. */
.routine-window-menu {
  display: grid;
  width: 240px;
  gap: var(--johnbot-space-1);
  padding: var(--johnbot-space-1);
}

.routine-window-options {
  display: grid;
  gap: var(--johnbot-space-0-5);
}

.routine-window-repeat {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-2);
  border-top: 1px solid var(--johnbot-border);
  padding: var(--johnbot-space-2) var(--johnbot-space-1) var(--johnbot-space-1) var(--johnbot-space-3);
}

.routine-window-repeat-label {
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-lg);
  line-height: var(--johnbot-leading-lg);
}

.routine-window-option-control {
  display: flex;
  min-height: var(--johnbot-control-lg);
  align-items: center;
  gap: var(--johnbot-space-2);
  cursor: pointer;
  border-radius: var(--johnbot-radius-md);
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
}

.routine-window-option-control[data-checked] {
  background: var(--johnbot-hover);
}

.routine-window-option:has(:focus-visible) .routine-window-option-control {
  box-shadow: var(--johnbot-focus-ring);
}

@media (hover: hover) and (pointer: fine) {
  .routine-window-option-control:hover {
    background: var(--johnbot-hover);
  }
}

.routine-window-option-label {
  flex: 1;
  cursor: pointer;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
  line-height: var(--johnbot-leading-lg);
}

.routine-window-option-check {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  flex: 0 0 auto;
}

.routine-window-option-check svg {
  width: 100%;
  height: 100%;
}

.routine-window-range {
  display: grid;
  gap: var(--johnbot-space-1-5);
  padding: var(--johnbot-space-1) var(--johnbot-space-3) var(--johnbot-space-2);
}

.routine-window-range-times {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.routine-window-range-count {
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
}

/* Calendar */
.routine-calendar {
  display: grid;
  width: calc(7 * var(--johnbot-control-md) + 6 * var(--johnbot-space-0-5));
  gap: var(--johnbot-space-1);
}

.routine-calendar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: var(--johnbot-space-1);
}

.routine-calendar-title {
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
}

.routine-calendar-weekdays,
.routine-calendar-days {
  display: grid;
  grid-template-columns: repeat(7, var(--johnbot-control-md));
  gap: var(--johnbot-space-0-5);
}

.routine-calendar-weekdays span {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  text-align: center;
}

.routine-calendar-day:focus-visible {
  box-shadow: var(--johnbot-focus-ring);
}

.routine-calendar-day[aria-current="date"]:not(.routine-day-selected) {
  color: var(--johnbot-accent-text);
}

.routine-calendar-day:disabled {
  cursor: default;
  opacity: 0.32;
}

/* Chat card */
/*
 * As wide as its content, as a message is: the row sets the width, and a narrow chat shrinks it.
 * The minimum keeps the card still while most edits change the chips. It needs the second class
 * because interaction-cards.css loads later and resets `min-width`.
 */
/*
 * The row takes the most space that still shows every label whole. RoutineSchedulePicker sets
 * `data-fit` from the labels and the width, so a short row keeps its room in a narrow panel.
 * Each step keeps the rules of the steps before it.
 */
.routine-schedule-picker:not([data-fit="roomy"]) .routine-trigger-chips {
  gap: var(--johnbot-space-1-5);
}

.routine-schedule-picker:not([data-fit="roomy"]) .routine-trigger-phrase {
  gap: var(--johnbot-space-1);
}

.routine-schedule-picker:not([data-fit="roomy"]) .routine-connector {
  font-size: var(--johnbot-text-md);
}

.routine-schedule-picker[data-density="panel"]:not([data-fit="roomy"]) .routine-trigger-row {
  gap: var(--johnbot-space-1-5);
}

.routine-schedule-picker[data-density="panel"]:not([data-fit="roomy"]) .routine-trigger-icon svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.routine-schedule-picker[data-density="panel"]:not([data-fit="roomy"]) .routine-chip {
  gap: var(--johnbot-space-1);
  padding: 0 var(--johnbot-space-2);
  font-size: var(--johnbot-text-md);
}

.routine-schedule-picker[data-density="panel"]:is([data-fit="tight"], [data-fit="minimal"])
  .routine-connector-optional {
  display: none;
}

.routine-schedule-picker[data-density="panel"]:is([data-fit="tight"], [data-fit="minimal"])
  :is(.routine-trigger-row, .routine-trigger-chips) {
  gap: var(--johnbot-space-1);
}

.routine-schedule-picker[data-density="panel"]:is([data-fit="tight"], [data-fit="minimal"]) .routine-trigger-icon {
  width: var(--johnbot-control-xs);
  height: var(--johnbot-control-xs);
  align-self: center;
}

.routine-schedule-picker[data-density="panel"]:is([data-fit="tight"], [data-fit="minimal"]) .routine-chip {
  padding: 0 var(--johnbot-space-1-5);
}

/* The value chips then cut their labels short, and the frequency and time chips stay whole. */
.routine-schedule-picker[data-fit="minimal"] :is(.routine-trigger-icon, .routine-connector) {
  display: none;
}

.routine-schedule-picker[data-fit="minimal"] .routine-trigger-chips {
  gap: var(--johnbot-space-1);
}

/*
 * The end of a trigger row: the menu that changes the trigger. It sits one padding from the end,
 * as the icon does at the start. The menu button has the size of a chip, so the row stays as tall
 * as an input.
 */
.routine-trigger-action {
  display: inline-flex;
  flex: 0 0 auto;
  align-self: center;
  margin-inline-start: calc(var(--johnbot-space-1) * -1);
}

.routine-trigger-action:empty {
  display: none;
}

:is(.routine-trigger-row, .routine-trigger-card-header) .routine-trigger-action .ui-button {
  width: var(--johnbot-control-sm);
  height: var(--johnbot-control-sm);
  border-radius: var(--johnbot-radius-xs);
}

/*
 * The webhook trigger: a header, then one full-width row for each value. The header icon starts
 * where the row text starts, and the row actions share one column with the menu button.
 */
.routine-trigger-card {
  display: grid;
  min-width: 0;
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-shadow-popover-ambient);
}

.routine-trigger-card-header {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-2);
  padding: var(--johnbot-space-1) var(--johnbot-space-1) var(--johnbot-space-1) var(--johnbot-space-3);
}

:is(.routine-trigger-card-header, .routine-trigger-menu) .routine-trigger-icon {
  width: var(--johnbot-control-sm);
  height: var(--johnbot-control-sm);
}

.routine-trigger-card-title {
  min-width: 0;
  flex: 1;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
  /* Mostly lowercase text looks low when its line box is centered. Center the x-height on the icon. */
  text-box: trim-both ex alphabetic;
}

.routine-webhook-field {
  display: grid;
  /* An action, the row padding and the top border, so a row without an action has the same height. */
  min-height: calc(var(--johnbot-control-sm) + var(--johnbot-space-2) + 1px);
  grid-template-columns: minmax(84px, auto) minmax(0, 1fr) var(--johnbot-control-sm);
  align-items: center;
  gap: var(--johnbot-space-3);
  border: 0;
  border-top: 1px solid var(--johnbot-border);
  margin: 0;
  background: none;
  padding: var(--johnbot-space-1) var(--johnbot-space-1) var(--johnbot-space-1) var(--johnbot-space-3);
  color: inherit;
  font: inherit;
  text-align: left;
}

.routine-webhook-label {
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  white-space: nowrap;
}

.routine-webhook-value {
  min-width: 0;
  overflow: hidden;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

code.routine-webhook-value {
  font-family: inherit;
}

/* A new secret wraps in a fixed-width font, so the user can read each character before copying it. */
code.routine-webhook-secret {
  padding-block: var(--johnbot-space-1-5);
  font-family: var(--johnbot-font-mono);
  overflow-wrap: anywhere;
  white-space: normal;
}

.routine-webhook-field > :last-child {
  justify-self: center;
}

.routine-webhook-field > .ui-icon-button {
  width: var(--johnbot-control-sm);
  height: var(--johnbot-control-sm);
}

/* The Events row is a ghost Button; two classes keep the row layout over the button styles. */
.routine-webhook-field.routine-webhook-events-toggle {
  width: auto;
  min-width: 0;
  height: auto;
  justify-content: stretch;
  border-radius: 0 0 calc(var(--johnbot-radius-md) - 1px) calc(var(--johnbot-radius-md) - 1px);
  color: inherit;
  font: inherit;
  text-align: start;
  cursor: pointer;
}

.routine-webhook-field.routine-webhook-events-toggle[aria-expanded="true"] {
  background: none;
}

.routine-webhook-field.routine-webhook-events-toggle:hover {
  background: var(--johnbot-bg-control-hover);
}

.routine-webhook-events-toggle:focus-visible {
  outline: 0;
  box-shadow: var(--johnbot-focus-ring);
}

.routine-webhook-events-toggle > svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  stroke-width: var(--johnbot-icon-stroke);
  color: var(--johnbot-text-muted);
}

/* A status sentence wraps; a URL or a secret stays on one line. */
.ui-text.routine-webhook-value {
  white-space: normal;
}

.routine-webhook-note {
  padding: 0 var(--johnbot-space-3) var(--johnbot-space-2);
}

.routine-trigger-card-header + .routine-webhook-note {
  border-top: 1px solid var(--johnbot-border);
  padding-top: var(--johnbot-space-2);
}

.routine-webhook-secret-note {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-2);
}

/* In a chat card the rows are one block, so the card gap does not split them, and they line up
 * with the card title. */
.routine-webhook-card-endpoint {
  display: grid;
  border-bottom: 1px solid var(--johnbot-border);
}

.routine-webhook-card-endpoint > .routine-webhook-field,
.routine-webhook-card-endpoint > .routine-webhook-note {
  padding-left: 0;
}

/* The setup steps: a number, or a check when done, beside each step. */
.routine-webhook-steps {
  display: grid;
  margin: 0;
  padding: 0;
  list-style: none;
}

.routine-webhook-steps > li {
  display: grid;
  grid-template-columns: var(--johnbot-control-sm) minmax(0, 1fr);
  gap: var(--johnbot-space-2);
  border-top: 1px solid var(--johnbot-border);
  padding: var(--johnbot-space-3);
}

.routine-webhook-step-body {
  display: grid;
  min-width: 0;
  gap: var(--johnbot-space-1-5);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.routine-webhook-step-body > strong {
  font-weight: var(--johnbot-weight-medium);
}

.routine-webhook-steps > li[data-disabled] .routine-webhook-step-body > strong {
  color: var(--johnbot-text-muted);
}

.routine-webhook-step-marker {
  display: inline-grid;
  width: var(--johnbot-control-sm);
  height: var(--johnbot-control-sm);
  place-items: center;
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-pill);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
}

.routine-webhook-step-marker[data-done] {
  border-color: var(--johnbot-success);
  background: var(--johnbot-success-soft);
  color: var(--johnbot-success-text);
}

.routine-webhook-step-check {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

/* A value row inside a step has its own border. */
.routine-webhook-inset {
  min-width: 0;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-sm);
}

.routine-webhook-inset > .routine-webhook-field {
  border-top: 0;
}

.routine-webhook-step-button {
  justify-self: start;
}

.routine-webhook-disclosure {
  justify-self: start;
  margin-inline-start: calc(var(--johnbot-space-2) * -1);
  padding-inline: var(--johnbot-space-2);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  font-weight: inherit;
}

.routine-webhook-disclosure-icon {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  stroke-width: var(--johnbot-icon-stroke);
}

.routine-webhook-filter {
  display: grid;
  gap: var(--johnbot-space-1);
}

.routine-webhook-events {
  display: grid;
  gap: var(--johnbot-space-3);
  border-top: 1px solid var(--johnbot-border);
  padding: var(--johnbot-space-3);
}

.routine-webhook-events .settings-field {
  display: grid;
  margin: 0;
  gap: var(--johnbot-space-1-5);
}

.routine-webhook-events .settings-field > span {
  margin: 0;
}

/* Hints are captions, not field labels. */
.routine-webhook-events .settings-field > .ui-text {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.routine-webhook-add-filter {
  justify-self: start;
  margin-left: calc(var(--johnbot-space-2) * -1);
  padding-inline: var(--johnbot-space-2);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-md);
  font-weight: inherit;
}

/* A quiet link under the rows. Its text starts under the row labels. */
.routine-webhook-filter-link {
  justify-self: start;
  margin: 0 0 var(--johnbot-space-1) var(--johnbot-space-1);
  padding-inline: var(--johnbot-space-2);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  font-weight: inherit;
}

.routine-webhook-add-filter svg,
.routine-webhook-filter-link svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  stroke-width: var(--johnbot-icon-stroke);
}

/* The trigger menu: a name and one line that tells when the routine runs. It is taller than a short
 * window, so it fits the space left and scrolls; the webhook row stays reachable. */
.routine-trigger-menu {
  width: 300px;
  max-height: min(560px, calc(100dvh - 16px), var(--kb-popper-content-available-height, 560px));
  overflow-y: auto;
}

.routine-trigger-menu.ui-action-menu .routine-trigger-menu-item[role="menuitemradio"] {
  height: auto;
  padding-block: var(--johnbot-space-1-5);
  gap: var(--johnbot-space-3);
  white-space: normal;
}

.routine-trigger-menu-text {
  display: grid;
  min-width: 0;
  flex: 1;
}

.routine-trigger-menu-description {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.routine-trigger-menu.ui-action-menu .routine-trigger-menu-item > .routine-trigger-menu-check {
  color: var(--johnbot-text-primary);
}

/* routine-calendar.css */
/* Routine calendar: the runs of every routine, by day, with the next runs beside them. */
.routine-planner {
  container-type: inline-size;
  display: grid;
  min-width: 0;
  gap: var(--johnbot-space-4);
  color: var(--johnbot-text-primary);
}

.routine-planner-header {
  display: grid;
  gap: var(--johnbot-space-3);
}

.routine-planner-title {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-3);
}

.routine-planner-identity {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-2);
}

/* The arrow lines up with the content edge, not its hit area. */
.routine-planner-identity .ui-icon-button {
  margin-left: calc(-1 * var(--johnbot-space-2));
}

.routine-planner-title h2 {
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-semibold);
}

.routine-planner-title h2 span {
  color: var(--johnbot-text-muted);
  font-weight: var(--johnbot-weight-regular);
}

.routine-planner-title p,
.routine-planner-note {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

.routine-planner-toolbar {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-2);
}

.routine-planner-nav {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-1);
}

.routine-planner-range {
  margin-left: var(--johnbot-space-2);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.routine-planner-clock-change {
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-warning-soft);
  padding: var(--johnbot-space-1-5) var(--johnbot-space-3);
  color: var(--johnbot-warning-text);
  font-size: var(--johnbot-text-sm);
}

.routine-planner-body {
  display: grid;
  min-width: 0;
  grid-template-columns: minmax(0, 1fr) minmax(0, 17rem);
  align-items: start;
  gap: var(--johnbot-space-4);
}

.routine-planner-grid {
  display: grid;
  min-width: 0;
  gap: var(--johnbot-space-1);
}

.routine-planner-weekdays {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: var(--johnbot-space-1);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

/* The day cell's border and padding, so that each head starts where its day starts. */
.routine-planner-weekdays > * {
  padding-inline: calc(1px + var(--johnbot-space-1-5));
}

/* Each day is a list, not a time grid: runs at the same minute stack and stay readable. */
.routine-planner-week {
  display: grid;
  min-width: 0;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: var(--johnbot-space-1);
}

.routine-planner-day {
  display: grid;
  min-width: 0;
  min-height: 12rem;
  align-content: start;
  gap: var(--johnbot-space-1);
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-surface);
  padding: var(--johnbot-space-1-5);
}

.routine-planner-day[data-past] {
  background: var(--johnbot-transparent);
}

.routine-planner-day[aria-current="date"] {
  border-color: var(--johnbot-accent-strong);
}

.routine-planner-day-button.ui-button {
  width: 100%;
  justify-content: flex-start;
  gap: var(--johnbot-space-1-5);
  color: var(--johnbot-text-muted);
}

.routine-planner-day-button strong {
  color: var(--johnbot-text-primary);
  font-weight: var(--johnbot-weight-semibold);
  font-variant-numeric: tabular-nums;
}

.routine-planner-day[aria-current="date"] .routine-planner-day-button strong {
  color: var(--johnbot-accent-text);
}

.routine-planner-runs,
.routine-planner-entries {
  display: grid;
  min-width: 0;
  gap: var(--johnbot-space-0-5);
  margin: 0;
  padding: 0;
  list-style: none;
}

.routine-planner-status {
  display: grid;
  width: var(--johnbot-space-4);
  height: var(--johnbot-space-4);
  place-items: center;
}

.routine-planner-status > svg {
  width: var(--johnbot-space-3);
  height: var(--johnbot-space-3);
  stroke-width: 2;
}

.routine-planner-status-dot {
  width: var(--johnbot-space-2);
  height: var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-accent);
}

.routine-planner-status[data-status="paused"] {
  color: var(--johnbot-text-muted);
}

.routine-planner-status[data-status="failed"] {
  color: var(--johnbot-danger-text);
}

.routine-planner-status[data-status="completed"] {
  color: var(--johnbot-success-text);
}

.routine-planner-avatars {
  display: flex;
}

.routine-planner-avatar.agent-avatar {
  width: var(--johnbot-space-4);
  height: var(--johnbot-space-4);
}

.routine-planner-avatars .routine-planner-avatar + .routine-planner-avatar {
  margin-left: calc(var(--johnbot-space-1-5) * -1);
}

.routine-planner-run.ui-button {
  display: grid;
  width: 100%;
  height: auto;
  min-height: var(--johnbot-control-sm);
  grid-template-columns: auto minmax(0, 1fr) auto;
  grid-template-areas:
    "mark time avatars"
    "name name name";
  align-items: center;
  gap: var(--johnbot-space-0-5) var(--johnbot-space-1);
  border-radius: var(--johnbot-radius-sm);
  background: var(--johnbot-bg-control);
  padding: var(--johnbot-space-1) var(--johnbot-space-1-5);
  text-align: left;
  font-size: var(--johnbot-text-sm);
}

.routine-planner-run .routine-planner-status {
  grid-area: mark;
}

.routine-planner-run-time {
  grid-area: time;
  color: var(--johnbot-text-muted);
  font-variant-numeric: tabular-nums;
}

/* Two lines before an ellipsis: a day column is narrow, and the name is what tells runs apart. */
.routine-planner-run-name {
  display: -webkit-box;
  grid-area: name;
  min-width: 0;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-height: 1.3;
  overflow-wrap: break-word;
  white-space: normal;
}

.routine-planner-run .routine-planner-avatars {
  grid-area: avatars;
}

/* A paused run would happen if the routine resumed. It keeps its place but loses its weight. */
.routine-planner-run[data-status="paused"],
.routine-planner-entry[data-status="paused"] {
  opacity: 0.6;
}

.routine-planner-run[data-status="paused"] {
  outline: 1px dashed var(--johnbot-border-grouped);
  outline-offset: -1px;
  background: var(--johnbot-transparent);
}

.routine-planner-run[data-status="failed"] {
  background: var(--johnbot-danger-soft);
}

.routine-planner-run[data-status="completed"] .routine-planner-run-name {
  color: var(--johnbot-text-muted);
}

.routine-planner-more.ui-button {
  justify-self: start;
  color: var(--johnbot-text-muted);
}

/* A month has up to six rows of days: a run is one line, and the column heads name the weekdays. */
.routine-planner[data-view="month"] .routine-planner-day {
  min-height: 7rem;
}

.routine-planner[data-view="month"] .routine-planner-day-button > span {
  display: none;
}

.routine-planner[data-view="month"] .routine-planner-run.ui-button {
  grid-template-columns: auto auto minmax(0, 1fr);
  grid-template-areas: "mark time name";
}

.routine-planner[data-view="month"] .routine-planner-run-name {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.routine-planner[data-view="month"] .routine-planner-run .routine-planner-avatars {
  display: none;
}

/* Days of the months before and after only fill the rows. */
.routine-planner-day[data-outside] {
  border-color: var(--johnbot-border);
  background: var(--johnbot-transparent);
}

.routine-planner-day[data-outside] .routine-planner-day-button strong {
  color: var(--johnbot-text-muted);
  font-weight: var(--johnbot-weight-regular);
}

.routine-planner-upcoming,
.routine-planner-day-view {
  display: grid;
  min-width: 0;
  align-content: start;
  gap: var(--johnbot-space-2);
}

.routine-planner-upcoming {
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-lg);
  padding: var(--johnbot-space-3);
}

.routine-planner-upcoming h3,
.routine-planner-hour h3 {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
}

.routine-planner-hour {
  display: grid;
  grid-template-columns: 4rem minmax(0, 1fr);
  align-items: start;
  gap: var(--johnbot-space-2);
  border-top: 1px solid var(--johnbot-border-strong);
  padding-top: var(--johnbot-space-2);
}

.routine-planner-hour h3 {
  padding-top: var(--johnbot-space-2);
  font-variant-numeric: tabular-nums;
}

.routine-planner-entry {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-1);
}

.routine-planner-entry-main.ui-button {
  display: flex;
  min-width: 0;
  height: auto;
  flex: 1 1 auto;
  align-items: center;
  justify-content: flex-start;
  gap: var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-md);
  padding: var(--johnbot-space-1-5) var(--johnbot-space-2);
  text-align: left;
}

.routine-planner-entry-text {
  display: grid;
  min-width: 0;
}

.routine-planner-entry-name,
.routine-planner-entry-meta {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.routine-planner-entry-name {
  font-size: var(--johnbot-text-md);
}

.routine-planner-entry-meta {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-regular);
}

.routine-planner-entry[data-status="failed"] .routine-planner-entry-meta {
  color: var(--johnbot-danger-text);
}

.routine-planner-entry-agents {
  display: flex;
  flex: 0 0 auto;
}

.routine-planner-agent .routine-planner-avatar.agent-avatar {
  width: var(--johnbot-control-xs);
  height: var(--johnbot-control-xs);
}

/*
 * The calendar before its first routine: a faint month behind the pitch. The month and the pitch
 * share one grid cell. Sample runs land on the month one at a time and write a note.
 */
.routine-planner-empty,
.routine-planner-empty-board {
  display: grid;
  min-width: 0;
}

.routine-planner-empty > *,
.routine-planner-empty-board > * {
  grid-area: 1 / 1;
}

.routine-planner-empty-board {
  pointer-events: none;
  user-select: none;
}

.routine-planner-empty-cells,
.routine-planner-empty-runs {
  display: grid;
  min-width: 0;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  grid-auto-rows: 10rem;
}

/* Only hairlines. They clear behind the pitch and fade towards every edge. */
.routine-planner-empty-cells {
  mask-image:
    radial-gradient(ellipse 36% 36% at 50% 50%, var(--johnbot-transparent) 68%, var(--johnbot-text-primary) 100%),
    radial-gradient(ellipse 72% 78% at 50% 50%, var(--johnbot-text-primary) 50%, var(--johnbot-transparent) 100%);
  mask-composite: intersect;
}

.routine-planner-empty-cell {
  border-top: 1px solid var(--johnbot-border);
  border-left: 1px solid var(--johnbot-border);
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
  color: var(--johnbot-text-dim);
  font-size: var(--johnbot-text-md);
}

.routine-planner-empty-cell[data-outside] {
  opacity: 0.45;
}

.routine-planner-empty-cell[data-today] {
  color: var(--johnbot-text-primary);
  font-weight: var(--johnbot-weight-semibold);
}

/* A run lands, writes its note, holds, then fades. The animation is `LIFE` steps of `STEP_MS`. */
.routine-planner-empty-run {
  display: grid;
  min-width: 0;
  align-self: start;
  justify-items: start;
  gap: var(--johnbot-space-2);
  grid-row: var(--routine-planner-empty-row);
  grid-column: var(--routine-planner-empty-column);
  margin-top: calc(var(--johnbot-space-8) + var(--johnbot-space-1));
  padding-inline: var(--johnbot-space-2);
  animation: routine-planner-empty-life var(--routine-planner-empty-life) var(--johnbot-ease-out) both;
}

.routine-planner-empty-run > .routine-planner-run {
  width: 100%;
}

.routine-planner-empty-day {
  display: none;
}

.routine-planner-empty-check {
  stroke-dasharray: 24;
  stroke-dashoffset: 24;
  opacity: 0;
  animation: routine-planner-empty-draw 420ms var(--johnbot-ease-out) 380ms forwards;
}

@keyframes routine-planner-empty-life {
  0% {
    opacity: 0;
    filter: blur(4px);
    transform: translateY(10px) scale(0.96);
  }

  8%,
  88% {
    opacity: 1;
    filter: blur(0);
    transform: none;
  }

  100% {
    opacity: 0;
    filter: blur(3px);
    transform: translateY(-4px);
  }
}

@keyframes routine-planner-empty-draw {
  from {
    opacity: 1;
  }

  to {
    opacity: 1;
    stroke-dashoffset: 0;
  }
}

/* Handwriting. The app has no hand font, so it uses the one of the system. */
.routine-planner-hand {
  color: var(--johnbot-accent-text);
  font-family: "Bradley Hand", "Noteworthy", "Segoe Print", cursive;
  font-weight: var(--johnbot-weight-semibold);
}

.routine-planner-empty-note {
  display: grid;
  width: fit-content;
  padding-inline: var(--johnbot-space-1);
  font-size: var(--johnbot-text-xl);
  line-height: 1.3;
  transform: rotate(-1.5deg);
  transform-origin: left top;
}

/* Each line writes itself from left to right, at the speed of its length. */
.routine-planner-empty-line {
  clip-path: inset(-0.4em 100% -0.4em -0.2em);
  animation: routine-planner-empty-write var(--routine-planner-empty-length) linear var(--routine-planner-empty-delay)
    forwards;
}

@keyframes routine-planner-empty-write {
  to {
    clip-path: inset(-0.4em -0.2em -0.4em -0.2em);
  }
}

.routine-planner-empty-underline {
  width: 100%;
  height: var(--johnbot-space-2);
  overflow: visible;
}

.routine-planner-empty-underline path {
  fill: none;
  stroke: currentColor;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  stroke-linecap: round;
  opacity: 0;
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
  animation: routine-planner-empty-draw 520ms var(--johnbot-ease-out) var(--routine-planner-empty-delay) forwards;
}

.routine-planner-empty-pitch {
  z-index: 1;
  display: grid;
  max-width: 34rem;
  place-self: center;
  justify-items: center;
  gap: var(--johnbot-space-4);
  padding: var(--johnbot-space-6);
  text-align: center;
}

.routine-planner-empty-title {
  display: grid;
  font-size: var(--johnbot-text-display);
  font-weight: var(--johnbot-weight-semibold);
  letter-spacing: -0.01em;
  line-height: 1.2;
}

.routine-planner-empty-title > .routine-planner-empty-lead {
  color: var(--johnbot-text-muted);
}

/* The one handwritten word of the title. It writes itself once. */
/* Inline, not inline-block: a reader then hears "done." with no space before the full stop. */
.routine-planner-empty-done {
  clip-path: inset(-0.4em 100% -0.4em -0.2em);
  animation: routine-planner-empty-write 520ms linear 500ms forwards;
}

.routine-planner-empty-lines {
  display: grid;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-xl);
  line-height: 1.5;
}

.routine-planner-empty-action.ui-button {
  width: 100%;
  max-width: 22rem;
  height: var(--johnbot-control-lg);
  margin-top: var(--johnbot-space-2);
}

.routine-planner-empty-menu {
  min-width: 14rem;
  max-height: min(520px, calc(100dvh - 16px), var(--kb-popper-content-available-height, 520px));
  overflow-y: auto;
}

/* Less motion: one still frame with three runs and their notes. */
.routine-planner-empty[data-still]
:is(
  .routine-planner-empty-run,
  .routine-planner-empty-check,
  .routine-planner-empty-line,
  .routine-planner-empty-underline path,
  .routine-planner-empty-done
) {
  animation: none;
  clip-path: none;
  stroke-dashoffset: 0;
  opacity: 1;
}

.routine-planner-skeleton-heading {
  height: var(--johnbot-control-xs);
}

.routine-planner-skeleton-run {
  height: var(--johnbot-control-md);
}

/* Seven day columns need the full width: the next runs move below the week. */
@container (max-width: 1160px) {
  .routine-planner-body {
    grid-template-columns: minmax(0, 1fr);
  }
}

/* A narrow pane, such as a phone or a side panel: the week becomes a list of days. */
@container (max-width: 920px) {
  .routine-planner-week {
    grid-template-columns: minmax(0, 1fr);
  }

  .routine-planner-day {
    min-height: 0;
    grid-template-columns: 5rem minmax(0, 1fr);
    align-items: start;
  }

  .routine-planner-day > :not(.routine-planner-day-heading) {
    grid-column: 2;
  }

  .routine-planner-loading .routine-planner-day {
    grid-template-columns: minmax(0, 1fr);
  }

  .routine-planner-loading .routine-planner-day > * {
    grid-column: 1;
  }

  /* The month becomes a list of its own days: each day names its weekday again. */
  .routine-planner-weekdays,
  .routine-planner-day[data-outside] {
    display: none;
  }

  .routine-planner[data-view="month"] .routine-planner-day {
    min-height: 0;
  }

  .routine-planner[data-view="month"] .routine-planner-day-button > span {
    display: inline;
  }

  /* The pitch comes first, then one row for each run on screen. */
  .routine-planner-empty > .routine-planner-empty-board {
    grid-area: 2 / 1;
  }

  .routine-planner-empty-pitch {
    padding-inline: 0;
  }

  .routine-planner-empty-title {
    font-size: var(--johnbot-text-3xl);
  }

  .routine-planner-empty-lines {
    font-size: var(--johnbot-text-lg);
  }

  .routine-planner-empty-cells {
    display: none;
  }

  .routine-planner-empty-runs {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: repeat(3, 8rem);
    grid-auto-rows: 0;
  }

  .routine-planner-empty-run {
    width: 100%;
    grid-row: var(--routine-planner-empty-slot);
    grid-column: 1;
    margin-top: 0;
    padding-inline: 0;
  }

  .routine-planner-empty-day {
    display: block;
    color: var(--johnbot-text-dim);
    font-size: var(--johnbot-text-sm);
  }

  .routine-planner-empty-note {
    font-size: var(--johnbot-text-lg);
  }
}

/* chat-action-card.css */
/* Chat action card: the shell of a chat record the person can act on. Variants add a body. */

/* Keyboard focus is a muted ring: an accent ring looks like a selection here. The same weight as
 * the accent outline rule in auth.css, which loads earlier. */
.chat-action-card :is(button, input, textarea):focus-visible {
  outline: 0;
}

.chat-action-card .ui-button:focus-visible {
  box-shadow: 0 0 0 1px var(--johnbot-text-muted);
}

.chat-action-card.conversation-interaction-card {
  min-width: min(100%, 320px);
}

.chat-action-card {
  display: grid;
  width: fit-content;
  max-width: min(100%, 520px);
  gap: var(--johnbot-space-3);
}

.chat-action-card-header {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.chat-action-card-icon {
  display: inline-flex;
  width: var(--johnbot-control-md);
  height: var(--johnbot-control-md);
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-accent);
  color: var(--johnbot-text-on-accent);
}

.chat-action-card-icon svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
}

.chat-action-card-heading {
  display: grid;
  min-width: 0;
  flex: 1;
}

.chat-action-card-eyebrow {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.chat-action-card-title {
  overflow: hidden;
  margin: 0;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-lg);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chat-action-card-open svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.chat-action-card-footer {
  display: flex;
  min-height: var(--johnbot-leading-md);
  align-items: center;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
}

/* Without a status the footer holds only its empty live region, so it takes no space. */
.chat-action-card-footer-empty {
  min-height: 0;
  margin-top: calc(-1 * var(--johnbot-space-3));
}

.chat-action-card-status {
  display: inline-flex;
  align-items: center;
  gap: var(--johnbot-space-1-5);
}

.chat-action-card-status svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.chat-action-card-footer-action {
  margin-left: auto;
}

.chat-action-card-error {
  color: var(--johnbot-danger-text);
}

.chat-action-card-removed .chat-action-card-title {
  color: var(--johnbot-text-muted);
  text-decoration: line-through;
}

/* marketplace-suggestion.css */
/* Marketplace suggestion: an app or skill an agent suggests in the chat, with its connect action. */

.marketplace-suggestion.conversation-interaction-card {
  display: grid;
  container-type: inline-size;
  width: 100%;
  max-width: 520px;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-3);
}

.marketplace-suggestion-header {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-3);
}

/* The listing icon keeps its tile border here, as on a dark chat its own fill meets the card. */
.marketplace-suggestion .marketplace-suggestion-icon {
  width: var(--johnbot-control-lg);
  height: var(--johnbot-control-lg);
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-surface-raised);
  color: var(--johnbot-text-primary);
}

.marketplace-suggestion .marketplace-suggestion-icon img {
  border-radius: inherit;
}

.marketplace-suggestion-heading {
  display: grid;
  min-width: 0;
  flex: 1;
}

/* In a narrow chat the action takes its own row, so the name keeps the width. */
@container (max-width: 360px) {
  .marketplace-suggestion-header {
    flex-wrap: wrap;
  }

  .marketplace-suggestion-heading {
    flex-basis: calc(100% - var(--johnbot-control-lg) - var(--johnbot-control-md) - 2 * var(--johnbot-space-3));
  }

  .marketplace-suggestion-action {
    order: 1;
    width: 100%;
  }

  .marketplace-suggestion-action > .ui-button {
    width: 100%;
  }
}

.marketplace-suggestion-title {
  overflow: hidden;
  margin: 0;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-md);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.marketplace-suggestion .marketplace-suggestion-name {
  height: auto;
  padding: 0;
  color: inherit;
  font: inherit;
}

.marketplace-suggestion-description {
  overflow: hidden;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.marketplace-suggestion-action {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
}

/*
 * Connect, its busy step and Connected are one button. Both labels share one grid cell; the stage
 * takes the width of the label on screen, and the cell keeps that width, so the wider label
 * overflows on both sides instead of pushing the other one off-centre.
 */
.marketplace-suggestion .marketplace-suggestion-button {
  overflow: clip;
}

/* Connected is a status: the success fill holds under the pointer. On-light text keeps AA on the dark-theme fill. */
.marketplace-suggestion .marketplace-suggestion-button.ui-button[data-state="connected"],
.marketplace-suggestion .marketplace-suggestion-button.ui-button[data-state="connected"]:hover {
  border-color: transparent;
  background: var(--johnbot-success);
  color: var(--johnbot-text-on-light);
  cursor: default;
}

/* On-light text on the light-theme success fill is 3:1. The darker success-text fill keeps AA. */
:root[data-johnbot-color-scheme="light"]
  .marketplace-suggestion
  .marketplace-suggestion-button.ui-button[data-state="connected"] {
  background: var(--johnbot-success-text);
}

.marketplace-suggestion-stage {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: center;
  justify-items: center;
}

.marketplace-suggestion-layer {
  display: inline-flex;
  grid-area: 1 / 1;
  align-items: center;
  gap: var(--johnbot-space-1-5);
  white-space: nowrap;
}

.marketplace-suggestion-button[data-state="connected"] [data-layer="start"],
.marketplace-suggestion-button:not([data-state="connected"]) [data-layer="done"] {
  opacity: 0;
}

.marketplace-suggestion-layer > svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

/* The spinner takes no room until the step is busy. */
.marketplace-suggestion-spinner {
  display: inline-flex;
  width: 0;
  margin-inline-end: calc(-1 * var(--johnbot-space-1-5));
  opacity: 0;
}

.marketplace-suggestion-button[data-state="busy"] .marketplace-suggestion-spinner {
  width: auto;
  margin-inline-end: 0;
  opacity: 1;
}

.marketplace-suggestion[data-state="connected"] .marketplace-suggestion-dismiss {
  width: 0;
  min-width: 0;
  margin-inline-start: calc(-1 * var(--johnbot-space-3));
  overflow: hidden;
  border-width: 0;
  padding: 0;
  opacity: 0;
  visibility: hidden;
}

/*
 * The motion of a change the user started. With reduced motion, only the fill and the labels fade.
 * The busy step: the spinner grows in and the button widens. Connected: the success fill comes in, the
 * old label lifts away as the new one rises, the check draws from its short stroke, and Dismiss
 * folds so the button glides to the edge.
 */
.marketplace-suggestion[data-motion] .marketplace-suggestion-button.ui-button {
  transition:
    background-color var(--johnbot-duration-slow) var(--johnbot-ease-out),
    color var(--johnbot-duration-slow) var(--johnbot-ease-out),
    opacity var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

.marketplace-suggestion[data-motion] .marketplace-suggestion-layer {
  transition: opacity var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

@media (prefers-reduced-motion: no-preference) {
  .marketplace-suggestion[data-motion] .marketplace-suggestion-stage {
    transition: width var(--johnbot-duration-slow) var(--johnbot-ease-out);
  }

  .marketplace-suggestion[data-motion] .marketplace-suggestion-layer {
    transition:
      opacity var(--johnbot-duration-normal) var(--johnbot-ease-out),
      transform var(--johnbot-duration-slow) var(--johnbot-ease-out);
  }

  .marketplace-suggestion-button[data-state="connected"] [data-layer="start"] {
    transform: translateY(-40%);
  }

  .marketplace-suggestion-button:not([data-state="connected"]) [data-layer="done"] {
    transform: translateY(40%);
  }

  .marketplace-suggestion[data-motion] .marketplace-suggestion-layer > svg path {
    stroke-dasharray: 24 24;
    stroke-dashoffset: -24;
    transition: stroke-dashoffset var(--johnbot-duration-overlay) var(--johnbot-ease-out) var(--johnbot-duration-fast);
  }

  .marketplace-suggestion[data-motion] .marketplace-suggestion-button[data-state="connected"] svg path {
    stroke-dashoffset: 0;
  }

  .marketplace-suggestion[data-motion] .marketplace-suggestion-spinner {
    transform: scale(0.6);
    transition:
      opacity var(--johnbot-duration-normal) var(--johnbot-ease-out),
      transform var(--johnbot-duration-normal) var(--johnbot-ease-out);
  }

  .marketplace-suggestion[data-motion]
    .marketplace-suggestion-button[data-state="busy"]
    .marketplace-suggestion-spinner {
    transform: none;
  }

  .marketplace-suggestion[data-motion] .marketplace-suggestion-dismiss {
    transition:
      opacity var(--johnbot-duration-fast) var(--johnbot-ease-out),
      width var(--johnbot-duration-slow) var(--johnbot-ease-out),
      margin var(--johnbot-duration-slow) var(--johnbot-ease-out),
      visibility 0s linear var(--johnbot-duration-slow);
  }
}

.marketplace-suggestion-done[data-slot="badge"] {
  gap: var(--johnbot-space-1-5);
  border-radius: var(--johnbot-radius-pill);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
}

.marketplace-suggestion-done svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.marketplace-suggestion-unavailable {
  display: flex;
  margin: 0;
  gap: var(--johnbot-space-2);
  border-top: 1px solid var(--johnbot-border);
  padding-top: var(--johnbot-space-3);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.marketplace-suggestion-unavailable svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: 0 0 auto;
  margin-top: var(--johnbot-space-0-5);
  color: var(--johnbot-text-muted);
}

.marketplace-suggestion-dismissed {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

/* backup-models.css */
.backup-model-logo {
  display: inline-flex;
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  flex: none;
  align-items: center;
  justify-content: center;
}

.backup-model-logo svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  overflow: visible;
  fill: var(--johnbot-provider-current);
}

.backup-model-option {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.backup-models-page {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-4);
}

.backup-models-intro {
  margin: 0;
  padding-inline: var(--johnbot-space-1);
}

.backup-models-empty {
  margin: 0;
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
}

.backup-models-list {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
}

.backup-models-row {
  display: flex;
  min-height: 40px;
  align-items: center;
  gap: var(--johnbot-space-2);
  padding: var(--johnbot-space-1) var(--johnbot-space-2) var(--johnbot-space-1) var(--johnbot-space-3);
}

.backup-models-number {
  width: var(--johnbot-icon-sm);
  flex: none;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
  text-align: center;
}

.backup-models-text {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
}

.backup-models-name {
  overflow: hidden;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.backup-models-state {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

/* The same dimming the provider picker uses for an unavailable provider. */
.backup-models-row:not([data-state="ready"]) .backup-model-logo svg {
  opacity: 0.44;
}

.backup-models-row:not([data-state="ready"]) .backup-models-name {
  color: var(--johnbot-text-muted);
  text-decoration: line-through;
}

.backup-models-actions {
  display: inline-flex;
  flex: none;
}

.usage-limit-ask-card {
  display: flex;
  max-width: 560px;
  flex-direction: column;
  gap: var(--johnbot-space-3);
  margin: var(--johnbot-space-4) 0 0;
}

.usage-limit-ask-body {
  margin: 0;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-md);
}

.usage-limit-ask-select {
  max-width: 320px;
}

.usage-limit-ask-remember {
  display: inline-flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  cursor: pointer;
}

.usage-limit-ask-error {
  margin: 0;
  color: var(--johnbot-danger);
  font-size: var(--johnbot-text-sm);
}

.usage-limit-ask-actions {
  display: flex;
  justify-content: flex-end;
  gap: var(--johnbot-space-2);
}

/* task-list.css */
/* Task list: the chat block of a plan an agent works through. */

.task-list {
  --task-list-glyph: var(--johnbot-icon-sm);
  --task-list-ease: var(--johnbot-ease-out);
  /* The open is slower than the close: rows settle in one after another, and leave together. */
  --task-list-open: 320ms;
  --task-list-close: 200ms;
  --task-list-close-ease: cubic-bezier(0.32, 0.08, 0.24, 1);
  --task-list-blur: 4px;
  --task-list-stagger: 28ms;

  box-sizing: border-box;
  width: min(100%, 448px);
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-card);
  background: var(--johnbot-bg-canvas);
  color: var(--johnbot-text-primary);
}

/* The ghost button is the whole header row, so it takes the card corners and the row height.
 * An open list is not a pressed control: the transparent background overrides the expanded
 * ghost fill, and the ghost hover rule still wins. */
.task-list .task-list-header {
  display: flex;
  background: transparent;
  width: 100%;
  height: auto;
  align-items: center;
  justify-content: flex-start;
  gap: var(--johnbot-space-3);
  border-radius: var(--johnbot-radius-card);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-regular);
  padding: var(--johnbot-space-3);
  text-align: left;
}

.task-list .task-list-header:focus-visible {
  outline: 0;
  box-shadow: 0 0 0 1px var(--johnbot-text-muted);
}

.task-list-summary-glyph {
  display: inline-flex;
  width: var(--task-list-glyph);
  height: var(--task-list-glyph);
  flex: 0 0 auto;
}

.task-list-donut {
  width: 100%;
  height: 100%;
}

.task-list-donut circle {
  stroke-width: 1.5;
}

.task-list-donut-track {
  stroke: var(--johnbot-border-strong);
}

.task-list-donut-value {
  stroke: var(--johnbot-text-primary);
  stroke-linecap: round;
  transition: stroke-dashoffset var(--johnbot-duration-slow) var(--task-list-ease);
}

/* The title and the running task share one cell, and swap with a blur when the list closes. */
.task-list-title {
  display: grid;
  min-width: 0;
  flex: 1;
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
}

.task-list-title-layer {
  overflow: hidden;
  min-width: 0;
  grid-area: 1 / 1;
  text-overflow: ellipsis;
  white-space: nowrap;
  transition:
    opacity var(--task-list-open) var(--task-list-ease),
    filter var(--task-list-open) var(--task-list-ease),
    transform var(--task-list-open) var(--task-list-ease);
}

.task-list-title-name {
  font-weight: var(--johnbot-weight-semibold);
}

.task-list-title-task {
  font-weight: var(--johnbot-weight-regular);
}

.task-list-title[data-showing="task"] .task-list-title-name,
.task-list-title[data-showing="title"] .task-list-title-task {
  filter: blur(var(--task-list-blur));
  opacity: 0;
}

.task-list-title[data-showing="task"] .task-list-title-name {
  transform: translateY(calc(-1 * var(--johnbot-space-1)));
}

.task-list-title[data-showing="title"] .task-list-title-task {
  transform: translateY(var(--johnbot-space-1));
}

/* The next task enters from below while the list stays closed. */
.task-list-title-task-text {
  animation: task-list-title-in var(--task-list-open) var(--task-list-ease);
}

.task-list-count {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  font-variant-numeric: tabular-nums;
  line-height: var(--johnbot-leading-md);
}

.task-list-chevron {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: 0 0 auto;
  color: var(--johnbot-text-muted);
  transform: rotate(-90deg);
  transition: transform var(--johnbot-duration-normal) var(--task-list-ease);
}

.task-list[data-open] .task-list-chevron {
  transform: rotate(0deg);
}

/* The panel animates its row from 0fr to 1fr, so the chat below moves with it. */
.task-list-panel {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows var(--task-list-close) var(--task-list-close-ease);
}

.task-list[data-open] .task-list-panel {
  grid-template-rows: 1fr;
  transition: grid-template-rows var(--task-list-open) var(--task-list-ease);
}

.task-list-items {
  display: grid;
  overflow: hidden;
  min-height: 0;
  margin: 0;
  padding: 0 var(--johnbot-space-3);
  list-style: none;
  transition: padding var(--task-list-close) var(--task-list-close-ease);
}

.task-list[data-open] .task-list-items {
  padding-bottom: var(--johnbot-space-3);
  transition: padding var(--task-list-open) var(--task-list-ease);
}

/* A closing list blurs and lifts away as one; an opening list focuses in row by row. The delay
 * stops growing after the eighth row, so a long plan does not wait for its last rows. */
.task-list-item {
  display: flex;
  min-width: 0;
  align-items: flex-start;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-0-5) 0;
  filter: blur(var(--task-list-blur));
  opacity: 0;
  transform: translateY(calc(-1 * var(--johnbot-space-1))) scale(0.98);
  transform-origin: left top;
  transition:
    opacity var(--task-list-close) var(--task-list-close-ease),
    filter var(--task-list-close) var(--task-list-close-ease),
    transform var(--task-list-close) var(--task-list-close-ease);
}

.task-list[data-open] .task-list-item {
  filter: blur(0);
  opacity: 1;
  transform: none;
  transition:
    opacity var(--task-list-open) var(--task-list-ease),
    filter var(--task-list-open) var(--task-list-ease),
    transform var(--task-list-open) var(--task-list-ease);
  transition-delay: calc(min(var(--task-list-index, 0), 8) * var(--task-list-stagger));
}

.task-list-item-mark {
  display: inline-flex;
  width: var(--task-list-glyph);
  height: var(--johnbot-leading-md);
  flex: 0 0 auto;
  align-items: center;
}

.task-list-item-label {
  position: relative;
  min-width: 0;
  flex: 1;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
  transition: color var(--johnbot-duration-normal) var(--task-list-ease);
}

.task-list-item[data-state="pending"] .task-list-item-label {
  color: var(--johnbot-text-muted);
}

.task-list-item[data-state="done"] .task-list-item-label {
  color: var(--johnbot-text-dim);
}

/* The strike line draws from the start of the text when the task is done. */
.task-list-item-text {
  position: relative;
}

.task-list-item-text::after {
  position: absolute;
  top: 50%;
  right: 0;
  left: 0;
  height: 1px;
  background: currentColor;
  content: "";
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform var(--johnbot-duration-slow) var(--task-list-ease);
}

.task-list-item[data-state="done"] .task-list-item-text::after {
  transform: scaleX(1);
}

.task-list-item[data-state="active"] .task-list-item-text,
.task-list-title[data-showing="task"] .task-list-title-task-text {
  display: inline-block;
  color: var(--johnbot-text-primary);
  animation: task-list-pulse 1.6s ease-in-out infinite;
  animation-play-state: var(--task-list-play-state, running);
}

.task-list-title[data-showing="task"] .task-list-title-task-text {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  vertical-align: top;
  animation:
    task-list-title-in var(--task-list-open) var(--task-list-ease),
    task-list-pulse 1.6s ease-in-out infinite;
  animation-play-state: var(--task-list-play-state, running);
}

/* The same roll as the update island: each settled value lifts in from below and sharpens. */
.task-list-item-progress {
  --digit-dur: var(--johnbot-duration-overlay);
  --digit-distance: var(--johnbot-space-1);
  --digit-blur: var(--johnbot-space-0-5);
  --digit-stagger: 40ms;

  display: inline-flex;
  min-width: 4ch;
  flex: 0 0 auto;
  justify-content: flex-end;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-control);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
  line-height: var(--johnbot-leading-md);
  padding: 0 var(--johnbot-space-1-5);
}

/* One glyph for all states. Each layer shows for its own state, so a change animates in place. */
.task-list-mark {
  width: var(--task-list-glyph);
  height: var(--task-list-glyph);
  overflow: visible;
}

.task-list-mark circle,
.task-list-mark path {
  transition:
    opacity var(--johnbot-duration-normal) var(--task-list-ease),
    transform var(--johnbot-duration-normal) var(--task-list-ease),
    stroke-dashoffset var(--johnbot-duration-slow) var(--task-list-ease);
  transform-box: fill-box;
  transform-origin: center;
}

.task-list-mark-pending {
  opacity: 0;
  stroke: var(--johnbot-text-dim);
  stroke-dasharray: 1.2 2;
  stroke-width: 1.5;
}

.task-list-mark-track {
  opacity: 0;
  stroke: var(--johnbot-border-strong);
  stroke-width: 1.5;
}

.task-list-mark-arc {
  opacity: 0;
  stroke: var(--johnbot-text-primary);
  stroke-dasharray: 12 100;
  stroke-linecap: round;
  stroke-width: 1.5;
}

.task-list-mark-fill {
  fill: var(--johnbot-text-dim);
  opacity: 0;
  transform: scale(0.4);
}

.task-list-mark-check {
  stroke: var(--johnbot-bg-canvas);
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.75;
}

.task-list-mark-cross {
  stroke: var(--johnbot-bg-canvas);
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  stroke-linecap: round;
  stroke-width: 1.75;
}

.task-list-mark[data-state="pending"] .task-list-mark-pending,
.task-list-mark[data-state="active"] .task-list-mark-track,
.task-list-mark[data-state="active"] .task-list-mark-arc,
.task-list-mark[data-state="done"] .task-list-mark-fill,
.task-list-mark[data-state="failed"] .task-list-mark-fill {
  opacity: 1;
}

/* Rotate the outer SVG so Chromium can composite the animation. */
.task-list-mark[data-state="active"] {
  animation: task-list-turn 0.9s linear infinite;
  animation-play-state: var(--task-list-play-state, running);
}

.task-list-mark[data-state="done"] .task-list-mark-fill,
.task-list-mark[data-state="failed"] .task-list-mark-fill {
  transform: scale(1);
}

.task-list-mark[data-state="failed"] .task-list-mark-fill {
  fill: var(--johnbot-danger);
}

/* The check and the cross draw after the disc has filled. */
.task-list-mark[data-state="done"] .task-list-mark-check,
.task-list-mark[data-state="failed"] .task-list-mark-cross {
  stroke-dashoffset: 0;
  transition-delay: var(--johnbot-duration-fast);
}

@keyframes task-list-turn {
  to {
    transform: rotate(360deg);
  }
}

@keyframes task-list-title-in {
  from {
    filter: blur(var(--task-list-blur));
    opacity: 0;
    transform: translateY(var(--johnbot-space-1));
  }
}

/* Opacity avoids the per-frame text paint of an animated clipped gradient. */
@keyframes task-list-pulse {
  50% {
    opacity: 0.6;
  }
}

/* Closed rows remain mounted for the close transition, but need no idle animation. */
.task-list:not([data-open]) .task-list-panel {
  --task-list-play-state: paused;
}

@media (prefers-reduced-motion: reduce) {
  .task-list-donut-value,
  .task-list-chevron,
  .task-list-panel,
  .task-list-items,
  .task-list-item,
  .task-list[data-open] .task-list-panel,
  .task-list[data-open] .task-list-items,
  .task-list[data-open] .task-list-item,
  .task-list-item-label,
  .task-list-title-layer,
  .task-list-item-text::after,
  .task-list-mark circle,
  .task-list-mark path {
    transition: none;
  }

  .task-list-mark[data-state="active"],
  .task-list-item[data-state="active"] .task-list-item-text,
  .task-list-title-task-text,
  .task-list-title[data-showing="task"] .task-list-title-task-text {
    animation: none;
  }
}

/* subagents.css */
/* The subagents of one turn: the chat card and the side panel pane. */

.subagents-elapsed {
  flex: 0 0 auto;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
}

/* The live line: the icon of the current step and its text. */

.subagents-live {
  display: flex;
  min-width: 0;
  align-items: flex-start;
  gap: var(--johnbot-space-1-5);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.subagents-live-glyph {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  flex: 0 0 auto;
  margin-top: 2px;
}

.subagents-live-text {
  display: -webkit-box;
  min-width: 0;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
}

.subagents-live[data-state="failed"] {
  color: var(--johnbot-danger-text);
}

/* The group: the header with the progress, and the list. */

.subagents-group {
  display: flex;
  width: 100%;
  flex-direction: column;
  gap: var(--johnbot-space-1-5);
}

.subagents-group .subagents-group-header {
  display: flex;
  height: auto;
  align-self: flex-start;
  align-items: center;
  gap: var(--johnbot-space-2);
  margin-left: calc(-1 * var(--johnbot-space-1-5));
  border-radius: var(--johnbot-radius-sm);
  padding: var(--johnbot-space-0-5) var(--johnbot-space-1-5);
  color: inherit;
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-regular);
  line-height: var(--johnbot-leading-md);
  text-align: left;
}

/* The open list is not a lit toggle, so the header has no fill. */
.subagents-group .subagents-group-header[aria-expanded="true"]:not(:hover) {
  background: transparent;
  color: inherit;
}

.subagents-group-chevron {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  color: var(--johnbot-text-muted);
  transition: rotate var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.subagents-group-header[aria-expanded="true"] .subagents-group-chevron {
  rotate: 90deg;
}

@media (prefers-reduced-motion: reduce) {
  .subagents-group-chevron {
    transition: none;
  }
}

.subagents-group-title {
  font-weight: var(--johnbot-weight-medium);
}

.subagents-progress {
  gap: var(--johnbot-space-1-5);
  font-variant-numeric: tabular-nums;
}

.subagents-ring {
  width: var(--johnbot-icon-xs);
}

.subagents-ring .ui-radial-progress-track,
.subagents-ring .ui-radial-progress-indicator {
  stroke-width: 7;
}

.subagents-ring .ui-radial-progress-indicator {
  transition: stroke-dasharray var(--johnbot-duration-slow) var(--johnbot-ease-out);
}

.subagents-progress-failed {
  color: var(--johnbot-danger-text);
}

@media (prefers-reduced-motion: reduce) {
  .subagents-ring .ui-radial-progress-indicator {
    transition: none;
  }
}

/* The list: one quiet card, as wide as the agent's message bubble. */

.subagents-list {
  display: flex;
  width: min(100%, 720px);
  flex-direction: column;
  margin: 0;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-card);
  background: var(--johnbot-bg-canvas);
  padding: var(--johnbot-space-1);
  list-style: none;
}

/* Two lines on one grid: the status and step icons share the first column, so both texts start
   at the same x. */
.subagents-list .subagents-row {
  display: grid;
  width: 100%;
  height: auto;
  align-items: start;
  grid-template-columns: var(--johnbot-icon-sm) minmax(0, 1fr) auto auto;
  gap: 2px var(--johnbot-space-2);
  border: 0;
  border-radius: var(--johnbot-radius-sm);
  background: transparent;
  padding: var(--johnbot-space-2);
  color: inherit;
  font-weight: var(--johnbot-weight-regular);
  line-height: inherit;
  text-align: left;
  white-space: normal;
  cursor: pointer;
}

.subagents-list .subagents-row:hover {
  background: var(--johnbot-hover);
}

.subagents-list .subagents-row.subagents-row-selected {
  background: var(--johnbot-bg-surface);
}

.subagents-row:focus-visible {
  outline: 2px solid var(--johnbot-focus-ring);
  outline-offset: -2px;
}

.subagents-row-copy,
.subagents-row .subagents-live {
  display: contents;
}

.subagents-row-title {
  display: -webkit-box;
  overflow: hidden;
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-md);
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 1;
}

.subagents-row .subagents-elapsed {
  line-height: var(--johnbot-leading-md);
}

.subagents-row .subagents-live-glyph {
  grid-column: 1;
  grid-row: 2;
  align-self: center;
  justify-self: center;
  margin-top: 0;
}

.subagents-row .subagents-live-text {
  grid-column: 2;
  grid-row: 2;
}

.subagents-row-chevron {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  flex: 0 0 auto;
  margin-top: 4px;
  color: var(--johnbot-text-muted);
  opacity: 0;
  transition: opacity var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.subagents-row:hover .subagents-row-chevron,
.subagents-row:focus-visible .subagents-row-chevron,
.subagents-row.subagents-row-selected .subagents-row-chevron {
  opacity: 1;
}

@media (prefers-reduced-motion: reduce) {
  .subagents-row-chevron {
    transition: none;
  }
}

/* The side panel pane: the steps of one subagent. */

.subagents-panel {
  overflow: hidden;
}

.subagents-panel-detail {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  gap: var(--johnbot-space-3);
  overflow-y: auto;
  padding: var(--johnbot-space-4);
}

.subagents-panel-head {
  display: flex;
  align-items: flex-start;
  gap: var(--johnbot-space-2);
}

.subagents-panel-head h3 {
  margin: 0;
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-lg);
  overflow-wrap: anywhere;
}

.subagents-panel-meta {
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

.subagents-steps {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-2);
}

.subagents-prompt {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0;
  border-left: 2px solid var(--johnbot-border-strong);
  padding-left: var(--johnbot-space-2);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.subagents-prompt-label {
  color: var(--johnbot-text-muted);
  font-weight: var(--johnbot-weight-medium);
}

.subagents-step-list {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-1-5);
  margin: 0;
  padding: 0;
  list-style: none;
}

.subagents-step {
  display: flex;
  align-items: flex-start;
  gap: var(--johnbot-space-2);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  overflow-wrap: anywhere;
}

.subagents-step-glyph {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  flex: 0 0 auto;
  margin-top: 2px;
  color: var(--johnbot-text-muted);
}

.subagents-step[data-kind="thinking"] .subagents-step-text {
  color: var(--johnbot-text-muted);
  font-style: italic;
}

.subagents-step[data-kind="text"] .subagents-step-text {
  color: var(--johnbot-text-primary);
}

.subagents-step-text.agent-activity-label {
  -webkit-line-clamp: unset;
}

.subagents-error {
  display: flex;
  align-items: flex-start;
  gap: var(--johnbot-space-2);
  margin: 0;
  color: var(--johnbot-danger-text);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.subagents-error-icon {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  flex: 0 0 auto;
  margin-top: 2px;
}

/* Status icons: the same icons and colours as the chat action markers. */

.subagents-status {
  display: inline-flex;
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-leading-md);
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
}

.subagents-status-icon {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.subagents-status[data-state="running"] {
  color: var(--johnbot-accent);
}

.subagents-status[data-state="running"] .subagents-status-icon {
  animation: ui-spin 1s linear infinite;
}

.subagents-status[data-state="completed"] {
  color: var(--johnbot-success);
}

.subagents-status[data-state="failed"] {
  color: var(--johnbot-danger);
}

.subagents-status[data-state="stopped"] {
  color: var(--johnbot-text-muted);
}

@media (prefers-reduced-motion: reduce) {
  .subagents-status[data-state="running"] .subagents-status-icon {
    animation: none;
  }
}

/* awaiting-replies.css */
/*
 * Waiting for replies: the task list rows, in the queue panel's surface. It hangs off the top of the
 * next panel like the queue: its bottom goes under the composer, or under the queue when the queue
 * shows, and that panel paints over the overlap.
 */

.awaiting-replies {
  --awaiting-composer-overlap: 14px;

  position: relative;
  z-index: 9;
  width: auto;
  margin: 0 12px calc(-1 * var(--awaiting-composer-overlap));
  border-color: var(--johnbot-queue-border);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-queue-surface);
  padding-bottom: var(--awaiting-composer-overlap);
  animation: queue-panel-in var(--johnbot-duration-normal) cubic-bezier(0.23, 1, 0.32, 1) both;
}

.awaiting-replies.task-list .task-list-header {
  min-width: 0;
  flex: 1;
  border-radius: var(--johnbot-radius-lg);
}

/* The close button sits next to the header button, because a button cannot hold another. */
.awaiting-replies-bar {
  display: flex;
  align-items: center;
}

.awaiting-replies-dismiss {
  margin-right: var(--johnbot-space-2);
  color: var(--johnbot-text-muted);
}

.awaiting-replies-item {
  align-items: center;
}

.awaiting-replies-avatar {
  --agent-avatar-optical-offset: -1px;

  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  flex: 0 0 auto;
}

.awaiting-replies-text {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: baseline;
  gap: var(--johnbot-space-2);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
}

.awaiting-replies-name {
  flex: 0 0 auto;
  color: var(--johnbot-text-primary);
  font-weight: var(--johnbot-weight-medium);
}

.awaiting-replies-preview {
  overflow: hidden;
  min-width: 0;
  color: var(--johnbot-text-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.awaiting-replies-state {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: var(--johnbot-space-2);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-md);
}

.awaiting-replies-detail {
  color: var(--johnbot-text-dim);
}

.awaiting-replies-item[data-state="failed"] .awaiting-replies-state-label {
  color: var(--johnbot-danger-text);
}

/* An agent that was asked waits for the user or for its plan, so its work does not go on. */
.awaiting-replies-item[data-wait] .awaiting-replies-state-label {
  color: var(--johnbot-warning-text);
}

.awaiting-replies-open,
.awaiting-replies-steer {
  flex: 0 0 auto;
}

.awaiting-replies-item[data-state="active"] .awaiting-replies-state-label {
  animation: task-list-pulse 1.6s ease-in-out infinite;
  animation-play-state: var(--task-list-play-state, running);
}

@media (prefers-reduced-motion: reduce) {
  .awaiting-replies {
    animation: none;
  }

  .awaiting-replies-item[data-state="active"] .awaiting-replies-state-label {
    animation: none;
  }
}

/* open-waits.css */
/*
 * Open waits: the "Waiting for replies" card, with a two-line row for each wait and a menu at the
 * row end.
 */

.open-waits .task-list-title-name {
  font-weight: var(--johnbot-weight-medium);
}

.open-waits .task-list-count {
  color: var(--johnbot-warning-text);
  font-size: var(--johnbot-text-sm);
}

.open-waits-row {
  align-items: flex-start;
}

.open-waits-row-text {
  display: grid;
  min-width: 0;
  flex: 1;
  gap: var(--johnbot-space-0-5);
}

.open-waits-row-note {
  overflow: hidden;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.open-waits-row-meta {
  display: flex;
  min-width: 0;
  gap: var(--johnbot-space-1);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  white-space: nowrap;
}

.open-waits-row-request {
  overflow: hidden;
  min-width: 0;
  color: var(--johnbot-text-dim);
  text-overflow: ellipsis;
}

[data-wait-state="woken"] .open-waits-row-state {
  color: var(--johnbot-warning-text);
}

[data-wait-state="resuming"] .open-waits-row-state {
  color: var(--johnbot-text-primary);
  animation: task-list-pulse 1.6s ease-in-out infinite;
  animation-play-state: var(--task-list-play-state, running);
}

@media (prefers-reduced-motion: reduce) {
  [data-wait-state="resuming"] .open-waits-row-state {
    animation: none;
  }
}

.open-waits-menu {
  flex: 0 0 auto;
  align-self: flex-start;
  color: var(--johnbot-text-muted);
}

/* header-controls.css */
.conversation-title {
  display: flex;
  height: var(--johnbot-control-sm);
  align-items: center;
  gap: 6px;
  border-radius: var(--johnbot-radius-sm);
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  padding: 2px 4px;
  text-align: left;
  transition: background var(--johnbot-duration-hover) ease;
}

.conversation-title:hover {
  background: var(--johnbot-hover);
}

.conversation-title h1 {
  margin: 0;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: 400;
  line-height: 18px;
  letter-spacing: 0;
}

.conversation-access-lock {
  display: inline-flex;
  flex: none;
  color: var(--johnbot-text-muted);
}

.conversation-access-lock svg {
  width: 14px;
  height: 14px;
}

.conversation-header-actions {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 6px;
}

/* The model change that waits for the running turn to end. */
.conversation-model-pending {
  flex: none;
  gap: 4px;
}

.conversation-model-pending svg {
  width: 12px;
  height: 12px;
}

.provider-model-picker {
  position: relative;
  min-width: 0;
}

.provider-model-trigger {
  display: flex;
  width: max-content;
  /* Room for the effort after the model name. The model name shortens first. */
  max-width: 240px;
  height: 28px;
  align-items: center;
  gap: 6px;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-overlay);
  padding: 0 9px 0 8px;
  color: var(--johnbot-text-primary);
  cursor: pointer;
  box-shadow: inset 0 1px var(--johnbot-hover);
  transition:
    border-color var(--johnbot-duration-hover) ease,
    background-color var(--johnbot-duration-hover) ease,
    transform var(--johnbot-duration-fast) cubic-bezier(0.23, 1, 0.32, 1);
}

.provider-model-trigger:hover:not(:disabled),
.provider-model-trigger[aria-expanded="true"] {
  border-color: var(--johnbot-border-strong);
  background: var(--johnbot-bg-surface);
}

.provider-model-trigger:active:not(:disabled) {
  transform: scale(0.97);
}

.provider-model-trigger:focus-visible,
.provider-model-rail-button:focus-visible,
.provider-model-option:focus-visible {
  outline: 1px solid var(--johnbot-border-focus);
  outline-offset: 1px;
}

.provider-model-trigger:disabled {
  opacity: 0.48;
  cursor: default;
}

.provider-model-trigger-value {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 6px;
}

.provider-model-trigger-name {
  flex: 0 1 auto;
  min-width: 0;
  white-space: nowrap;
  font-size: var(--johnbot-text-md);
  font-weight: 470;
  line-height: 18px;
}

.provider-model-trigger-effort {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  line-height: 18px;
  white-space: nowrap;
}

.provider-model-trigger-effort::before {
  margin-right: var(--johnbot-space-1-5);
  content: "·";
}

/* The Fast chip gets its own room, so the model name keeps the width it has without it. */
.provider-model-trigger:has(.provider-model-trigger-fast) {
  max-width: 296px;
}

.provider-model-trigger-fast svg {
  width: 12px;
  height: 12px;
  margin-right: var(--johnbot-space-0-5);
  stroke-width: var(--johnbot-icon-stroke);
}

/* An email can be long: the account gives way before the model name does. */
.provider-model-trigger-account {
  min-width: 0;
  max-width: 160px;
  flex-shrink: 1;
  overflow: hidden;
}

/* SwapLabel: the old text sits on top of the new text while both animate. */
.ui-swap {
  position: relative;
  display: inline-block;
  overflow: hidden;
  white-space: nowrap;
}

.ui-swap > span,
.ui-swap-digits {
  display: inline-block;
}

.ui-swap > .ui-swap-leaving {
  position: absolute;
  top: 0;
  left: 0;
}

/* The trigger swap is mostly a blur. The box does not clip it: a clip cuts the blur and the old
 * text with a hard edge while the box eases to the new width. The name clips itself instead. */
.provider-model-trigger-value .ui-swap {
  overflow: visible;
}

/* A name without SwapLabel, such as a static copy of the trigger, clips itself. */
.provider-model-trigger-name:not(.ui-swap) {
  overflow: hidden;
  text-overflow: ellipsis;
}

.provider-model-trigger-name > span:not(.ui-swap-leaving) {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
}

.provider-model-trigger-name > .ui-swap-leaving {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* A newly chosen provider's mark springs in. */
.provider-model-trigger-mark {
  display: flex;
  flex: 0 0 auto;
}

.provider-model-trigger-mark[data-entering] {
  animation: provider-model-mark-in 420ms cubic-bezier(0.34, 1.36, 0.64, 1) both;
}

@keyframes provider-model-mark-in {
  from {
    opacity: 0;
    scale: 0.6;
    filter: blur(2px);
  }
}

.provider-model-picker-field {
  width: 100%;
}

.provider-model-trigger-field {
  width: 100%;
  max-width: none;
  height: 44px;
  gap: 8px;
  border: 0;
  border-radius: 0;
  background: var(--johnbot-hover);
  padding: 0 11px 0 12px;
  box-shadow: none;
}

.provider-model-trigger-field:hover:not(:disabled),
.provider-model-trigger-field[aria-expanded="true"] {
  border-color: transparent;
  background: var(--johnbot-border);
}

.provider-model-trigger-field .provider-model-field-label {
  flex: 0 0 auto;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  font-weight: 400;
  line-height: 17px;
}

.provider-model-trigger-field .provider-model-trigger-value {
  max-width: calc(100% - 84px);
  margin-left: auto;
  justify-content: flex-end;
}

.provider-model-mark {
  width: 15px;
  height: 15px;
  flex: 0 0 15px;
  overflow: visible;
  fill: var(--johnbot-provider-current);
}

.provider-model-mark-large {
  width: 19px;
  height: 19px;
  flex-basis: 19px;
}

.provider-model-chevron {
  width: 13px;
  height: 13px;
  flex: 0 0 13px;
  fill: none;
  stroke: var(--johnbot-text-muted);
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: transform var(--johnbot-duration-normal) ease;
}

.provider-model-trigger[aria-expanded="true"] .provider-model-chevron {
  transform: rotate(180deg);
}

.provider-model-popover {
  --provider-model-rail-bg: var(--johnbot-bg-sheet-inset);
  --provider-model-segment-radius: calc(var(--ui-menu-item-radius) - var(--johnbot-space-0-5));
  position: relative;
  z-index: var(--johnbot-layer-dropdown);
  width: min(360px, calc(100vw - 24px));
  min-height: 226px;
  overflow: hidden;
  border: 0;
  border-radius: var(--ui-menu-radius);
  background: var(--ui-menu-bg);
  color: var(--johnbot-text-primary);
  box-shadow: var(--ui-menu-panel-shadow);
  transform-origin: var(--kb-popover-content-transform-origin);
  animation: ui-menu-in var(--ui-menu-duration) var(--ui-menu-ease) both;
}

/* The copy that ContentExitMotion leaves in the place of the closed popover plays the exit. */
.provider-model-popover:not([data-expanded]) {
  animation: ui-menu-out var(--ui-menu-duration) var(--ui-menu-ease) both;
}

.provider-model-layout {
  max-height: min(520px, calc(100dvh - 100px), var(--kb-popper-content-available-height, 520px));
  display: flex;
  width: 100%;
  min-height: inherit;
}

.provider-model-rail {
  display: flex;
  width: 52px;
  flex: 0 0 52px;
  flex-direction: column;
  align-items: center;
  gap: var(--johnbot-space-1);
  border-right: 1px solid var(--johnbot-border);
  background: var(--provider-model-rail-bg);
  padding: 9px 7px;
}

.provider-model-rail-tabs {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--johnbot-space-1);
}

/* Opens the provider settings, to connect a provider that the rail leaves out. */
.provider-model-rail-add {
  color: var(--johnbot-text-muted);
}

.provider-model-rail-add:hover {
  color: var(--johnbot-text-primary);
}

.provider-model-rail-tooltip-trigger {
  display: flex;
}

.provider-model-rail-tooltip {
  z-index: var(--johnbot-layer-tooltip);
  display: flex;
  max-width: min(240px, calc(100vw - 16px));
  flex-direction: column;
  gap: var(--johnbot-space-0-5);
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-sm);
  background: var(--johnbot-bg-surface-raised);
  box-shadow: var(--johnbot-shadow-raised);
  padding: var(--johnbot-space-1-5) var(--johnbot-space-2);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-md);
  overflow-wrap: anywhere;
  pointer-events: none;
}

.provider-model-rail-tooltip small {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-regular);
}

.provider-model-rail-button {
  position: relative;
  display: grid;
  width: 36px;
  height: 36px;
  flex: 0 0 36px;
  place-items: center;
  border: 0;
  border-radius: var(--ui-menu-item-radius);
  background: transparent;
  padding: 0;
  cursor: pointer;
  transition:
    background-color var(--johnbot-duration-hover) ease,
    opacity var(--johnbot-duration-hover) ease;
}

.provider-model-rail-button:hover {
  background: var(--ui-menu-item-hover);
}

.provider-model-rail-button-selected {
  background: color-mix(in srgb, var(--johnbot-text-primary) 8%, transparent);
  box-shadow: inset 0 0 0 1px var(--ui-menu-edge);
}

.provider-model-rail-button .provider-model-mark {
  opacity: 0.48;
}

.provider-model-rail-button:not(.provider-model-rail-button-selected, .provider-model-rail-button-unavailable):hover
  .provider-model-mark {
  opacity: 0.8;
}

.provider-model-rail-button-selected .provider-model-mark {
  fill: var(--johnbot-text-primary);
  opacity: 1;
}

/* A provider that cannot run: a dim mark and a dot. The dot uses the warning color when the user can
 * fix it here (sign in, update), and the muted text color otherwise. The tooltip names the state. */
.provider-model-rail-button-unavailable .provider-model-mark {
  opacity: 0.28;
}

.provider-model-rail-button-unavailable:is(:hover, .provider-model-rail-button-selected) .provider-model-mark {
  opacity: 0.6;
}

.provider-model-rail-button:is(
  [data-state="not-installed"],
  [data-state="sign-in-required"],
  [data-state="outdated"],
  [data-state="error"]
)::after {
  position: absolute;
  top: var(--johnbot-space-1-5);
  right: var(--johnbot-space-1-5);
  width: 6px;
  height: 6px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-text-muted);
  box-shadow: 0 0 0 2px var(--provider-model-rail-bg);
  content: "";
}

.provider-model-rail-button:is([data-state="sign-in-required"], [data-state="outdated"])::after {
  background: var(--johnbot-warning);
}

/* The place of an account in its provider's list, when the provider has more than one. */
.provider-model-rail-account {
  position: absolute;
  right: 2px;
  bottom: 2px;
  min-width: 16px;
  height: 16px;
  padding: 0 3px;
  box-sizing: border-box;
  display: grid;
  place-items: center;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-control);
  box-shadow: 0 0 0 2px var(--provider-model-rail-bg);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.provider-model-panel {
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
  flex: 1;
  padding: var(--ui-menu-padding);
}

.provider-model-panel:not([data-selected]) {
  display: none;
}

.provider-model-heading {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: var(--johnbot-space-2);
  /* The right inset lives on the text, not the row, so the action button can line its right edge up
   * with the search field and the model rows below it. */
  padding: var(--johnbot-space-1-5) 0 var(--johnbot-space-2) var(--ui-menu-inset);
}

.provider-model-heading-text {
  flex: 1 1 auto;
  min-width: 0;
  padding-right: 4px;
}

/* The icons are raw lucide exports with no intrinsic size, and only the icon-only button sizes
 * carry a rule, so an icon beside a label needs one here to match every other button. */
.provider-model-heading .ui-button,
.provider-model-empty .ui-button-variant-outline {
  border-color: transparent;
  border-radius: var(--ui-menu-item-radius);
  background: var(--ui-menu-item-hover);
  box-shadow: none;
  color: var(--johnbot-text-primary);
}

.provider-model-heading .ui-button:hover,
.provider-model-empty .ui-button-variant-outline:hover {
  background: color-mix(in srgb, var(--johnbot-text-primary) 10%, transparent);
}

.provider-model-heading .ui-button svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  stroke-width: var(--johnbot-icon-stroke);
}

.provider-model-heading strong,
.provider-model-heading span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The runtime status: a filled block with no border, as the search field. */
.provider-model-empty {
  display: grid;
  justify-items: start;
  gap: var(--johnbot-space-2);
  margin-bottom: var(--ui-menu-padding);
  border: 0;
  border-radius: var(--ui-menu-item-radius);
  background: var(--ui-menu-item-hover);
  padding: var(--johnbot-space-2) var(--ui-menu-inset);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  line-height: 18px;
}

.provider-model-heading strong {
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
  font-weight: 620;
  line-height: 20px;
}

.provider-model-heading span {
  margin-top: 1px;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: 16px;
}

.provider-model-empty > .ui-progress {
  justify-self: stretch;
}

.provider-model-list {
  display: grid;
  gap: 0;
}

.provider-model-effort {
  flex-shrink: 0;
  display: flex;
  /* The effort segments go to a line of their own when they do not fit beside the label. */
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-1) 12px;
  /* The separator runs to both edges of the panel, as in the menus. */
  margin: var(--ui-menu-padding) calc(var(--ui-menu-padding) * -1) 0;
  border-top: 1px solid var(--johnbot-border);
  padding: var(--ui-menu-padding) var(--ui-menu-padding) 0 calc(var(--ui-menu-padding) + var(--ui-menu-inset));
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: 17px;
}

/* The effort and auto-approve rows are one group under one separator. */
.provider-model-effort + .provider-model-effort {
  margin-top: 0;
  border-top: 0;
  padding-top: var(--johnbot-space-1);
}

/* Each row is as high as the effort control, so the switch and the segments have room. */
.provider-model-effort > :first-child {
  display: flex;
  min-height: var(--johnbot-control-md);
  align-items: center;
}

.provider-model-effort-select {
  width: 128px;
}

/* Effort as segments, in the SlidingTabs look and timing. */
.provider-model-effort-segments {
  --provider-model-effort-duration: 250ms;
  --provider-model-effort-ease: cubic-bezier(0.22, 1, 0.36, 1);
  position: relative;
  display: flex;
  /* On a line of their own, the segments can shrink. A long label then ends in an ellipsis. */
  flex: 1 1 auto;
  min-width: 0;
  gap: var(--johnbot-space-0-5);
  border-radius: var(--ui-menu-item-radius);
  background: var(--ui-menu-item-hover);
  padding: var(--johnbot-space-0-5);
}

.provider-model-effort-segment {
  display: flex;
  flex: 1 1 auto;
  min-width: 0;
}

.provider-model-effort-segment-control {
  position: relative;
  z-index: 1;
  display: flex;
  flex: 1;
  min-width: 0;
  height: calc(var(--johnbot-control-md) - 2 * var(--johnbot-space-0-5));
  align-items: center;
  justify-content: center;
  border-radius: var(--provider-model-segment-radius);
  padding-inline: var(--johnbot-space-2);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
  white-space: nowrap;
  cursor: pointer;
  transition: color var(--provider-model-effort-duration) var(--provider-model-effort-ease);
}

.provider-model-effort-segment-control label {
  overflow: hidden;
  text-overflow: ellipsis;
  cursor: inherit;
}

.provider-model-effort-segment-control:hover:not([data-disabled]),
.provider-model-effort-segment-control[data-checked] {
  color: var(--johnbot-text-primary);
}

.provider-model-effort-segment:has(:focus-visible) .provider-model-effort-segment-control {
  box-shadow: 0 0 0 1px var(--johnbot-text-muted);
}

.provider-model-effort-segment-control[data-disabled] {
  opacity: 0.5;
  cursor: default;
}

/* The chosen segment's background. EffortSegments places it, and it slides to a new choice. */
.provider-model-effort-pill {
  position: absolute;
  top: var(--johnbot-space-0-5);
  left: 0;
  z-index: 0;
  width: 0;
  height: calc(var(--johnbot-control-md) - 2 * var(--johnbot-space-0-5));
  border-radius: var(--provider-model-segment-radius);
  background: color-mix(in srgb, var(--johnbot-text-primary) 12%, transparent);
  box-shadow: inset 0 1px 0 var(--ui-menu-highlight);
  pointer-events: none;
  transition:
    transform var(--provider-model-effort-duration) var(--provider-model-effort-ease),
    width var(--provider-model-effort-duration) var(--provider-model-effort-ease);
}

.provider-model-effort-pill[data-initializing] {
  transition: none;
}

.provider-model-effort-segments:has([data-disabled]) .provider-model-effort-pill {
  opacity: 0.5;
}

.provider-model-effort-select .ui-select-trigger {
  border-color: transparent;
  border-radius: var(--ui-menu-item-radius);
  background: var(--ui-menu-item-hover);
  box-shadow: none;
}

.provider-model-effort-select .ui-select-trigger:is(:hover, [data-expanded]) {
  background: color-mix(in srgb, var(--johnbot-text-primary) 10%, transparent);
}

.provider-model-effort-content {
  border-radius: var(--ui-menu-radius);
  background: var(--ui-menu-bg);
  box-shadow: var(--ui-menu-panel-shadow);
  animation: ui-menu-in var(--ui-menu-duration) var(--ui-menu-ease) both;
}

.provider-model-effort-content .ui-select-listbox {
  padding: var(--ui-menu-padding);
}

.provider-model-effort-content .ui-select-item {
  border-radius: var(--ui-menu-item-radius);
  padding-block: var(--johnbot-space-1-5);
  padding-left: var(--ui-menu-inset);
  font-size: var(--johnbot-text-md);
}

.provider-model-effort-content .ui-select-item[data-highlighted] {
  background: var(--ui-menu-item-hover);
}

/* The check of the selected model is a filled circle on the left, as in the menus. */
.provider-model-option {
  position: relative;
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  border: 0;
  border-radius: var(--ui-menu-item-radius);
  background: transparent;
  padding: var(--johnbot-space-1-5) var(--ui-menu-inset) var(--johnbot-space-1-5)
    calc(var(--ui-menu-inset) + var(--johnbot-icon-md) + var(--johnbot-space-2));
  color: var(--johnbot-text-primary);
  cursor: pointer;
  text-align: left;
  transition:
    background-color var(--johnbot-duration-hover) ease,
    color var(--johnbot-duration-hover) ease;
}

.provider-model-option::before {
  position: absolute;
  top: 50%;
  left: var(--ui-menu-inset);
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  box-sizing: border-box;
  border: 1px solid color-mix(in srgb, var(--johnbot-text-primary) 22%, transparent);
  border-radius: var(--johnbot-radius-pill);
  content: "";
  translate: 0 -50%;
  transition:
    background-color var(--ui-menu-duration) ease-out,
    border-color var(--ui-menu-duration) ease-out;
}

.provider-model-option-selected::before {
  border-color: transparent;
  background: var(--johnbot-text-primary);
}

.provider-model-option:hover:not(:disabled),
.provider-model-option:focus-visible {
  background: var(--ui-menu-item-hover);
}

.provider-model-option:disabled {
  color: var(--johnbot-text-dim);
  cursor: not-allowed;
}

.provider-model-option-name {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 7px;
}

.provider-model-option-name > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--johnbot-text-md);
  line-height: 18px;
}

.provider-model-option-name small {
  flex: 0 0 auto;
  border-radius: var(--johnbot-radius-pill);
  background: color-mix(in srgb, var(--johnbot-text-primary) 7%, transparent);
  padding: 1px var(--johnbot-space-1-5);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: 500;
  line-height: 15px;
}

/* The tick sits in the filled circle, cut out of it in the panel color. */
.provider-model-check {
  position: absolute;
  top: 50%;
  left: calc(var(--ui-menu-inset) + (var(--johnbot-icon-md) - var(--johnbot-icon-sm)) / 2);
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  fill: none;
  stroke: var(--ui-menu-bg);
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 2.5;
  translate: 0 -50%;
}

@media (max-width: 720px) {
  /* A form field keeps the width of its row. */
  .provider-model-trigger:not(.provider-model-trigger-field) {
    max-width: 148px;
  }

  /* A narrow header keeps the model name; the label and the title still name the effort. */
  .provider-model-trigger-effort {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .provider-model-chevron,
  .provider-model-trigger,
  .provider-model-rail-button,
  .provider-model-option,
  .provider-model-option::before,
  .provider-model-effort-segment-control,
  .provider-model-effort-pill {
    transition: none;
  }

  .provider-model-popover,
  .provider-model-popover:not([data-expanded]),
  .provider-model-effort-content {
    animation: none;
  }

  .provider-model-trigger-mark[data-entering] {
    animation: none;
  }
}

.computer-button-agent-active {
  border-color: var(--johnbot-accent);
  background: var(--johnbot-accent-soft);
  box-shadow: 0 0 10px var(--johnbot-accent-strong);
  color: var(--johnbot-accent);
}

.computer-control-dot {
  position: absolute;
  top: 1px;
  right: 1px;
  width: 5px;
  height: 5px;
  border: 1px solid var(--johnbot-bg-canvas);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-accent);
  animation: browser-control-pulse 1.25s ease-in-out infinite;
}

.browser-toolbar-button:active:not(:disabled) {
  transform: scale(0.92);
  transition-duration: var(--johnbot-duration-fast);
}

/* timeline.css */
.conversation-scroll {
  min-height: 0;
  flex: 1;
  overflow-anchor: none;
  overflow-x: hidden;
  overflow-y: auto;
  padding: 8px 12px var(--johnbot-space-6);
}

.virtual-chat-list {
  position: relative;
  width: 100%;
}

.virtual-chat-row {
  position: absolute;
  inset: 0 0 auto;
  width: 100%;
  padding-top: var(--johnbot-chat-entry-gap);
}

/* Rows the timeline marks as grouped (marker runs, same-sender messages) sit tighter. */
.virtual-chat-row[data-grouped] {
  padding-top: var(--johnbot-chat-marker-gap);
}

.virtual-chat-row > .chat-action-marker + .message-entry {
  margin-top: var(--johnbot-chat-marker-gap);
}

.virtual-chat-list-static .virtual-chat-row {
  position: relative;
  inset: auto;
}

/*
 * The mark on a message that a quote opened. The band reaches 12px past the chat column, which is
 * the edge of the scroll area below the column width, and leaves out the gap above the row; it
 * holds, then fades out.
 */
.virtual-chat-row[data-reply-flash] {
  isolation: isolate;
}

.virtual-chat-row[data-reply-flash]::before {
  position: absolute;
  z-index: -1;
  inset: var(--johnbot-chat-entry-gap) -12px 0;
  background: var(--johnbot-accent-soft);
  content: "";
  opacity: 0;
  pointer-events: none;
  animation: reply-flash 1.6s var(--johnbot-ease-out);
}

.virtual-chat-row[data-grouped][data-reply-flash]::before {
  top: var(--johnbot-chat-marker-gap);
}

@keyframes reply-flash {
  0%,
  45% {
    opacity: 1;
  }

  100% {
    opacity: 0;
  }
}

.conversation-history-status {
  display: flex;
  min-height: 32px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

/*
 * The way back to the newest message. The wrapper carries the pill, because the count turns one
 * round button into two buttons the reader reads as one control, and only the wrapper knows how
 * wide that is. The circle becomes a pill in one step: `44px` to `auto` cannot be animated, and a
 * scale would fight the centring transform.
 */
.scroll-to-latest {
  position: sticky;
  z-index: 3;
  top: calc(100% - 58px);
  left: 50%;
  display: flex;
  width: max-content;
  height: 44px;
  align-items: center;
  margin-bottom: -44px;
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-surface-raised);
  box-shadow:
    0 8px 24px var(--johnbot-shadow-popover-ambient),
    inset 0 0 0 1px var(--johnbot-shadow-ring);
  color: var(--johnbot-text-primary);
  transform: translateX(-50%);
  transition: background-color var(--johnbot-duration-hover) ease;
}

/*
 * With a count the pill wears the colours of the unread banner: it is the same news. It is also
 * lower than the round arrow, and the label makes it wider, so the bottom edge is held where the
 * circle had it: `100% - 58px` plus `44px` is the same line as `100% - 50px` plus `36px`.
 */
.scroll-to-latest:is([data-new-messages], [data-reply-return]) {
  top: calc(100% - 50px);
  height: 36px;
  margin-bottom: -36px;
}

.scroll-to-latest[data-new-messages] {
  border-color: transparent;
  background: var(--johnbot-unread-surface);
  color: var(--johnbot-unread-text);
}

.scroll-to-latest-button {
  display: grid;
  width: 44px;
  height: 100%;
  place-items: center;
  border: 0;
  border-radius: inherit;
  background: none;
  color: inherit;
  transition:
    background-color var(--johnbot-duration-hover) ease,
    transform var(--johnbot-duration-fast) cubic-bezier(0.23, 1, 0.32, 1);
}

/*
 * One padding on all four sides: `space-1-5` from the pill edge to the arrow, to the round dismiss
 * mark, and above and below both, because each is `22px` tall inside a `36px` pill with a `1px`
 * border. `space-2` divides arrow from label and label from mark.
 */
.scroll-to-latest:is([data-new-messages], [data-reply-return]) .scroll-to-latest-button {
  width: auto;
  grid-auto-flow: column;
  gap: var(--johnbot-space-2);
  padding-inline: var(--johnbot-space-1-5) var(--johnbot-space-2);
}

.scroll-to-latest-count {
  font-size: var(--johnbot-text-sm);
  font-weight: 620;
  white-space: nowrap;
}

/*
 * The whole height stays clickable, but nothing here is painted: a highlight on this button would
 * fill the end of the pill. The hover and focus marks sit on the icon below, which is round, and
 * that round mark is what separates the two halves. No rule divides them.
 */
.scroll-to-latest-dismiss {
  display: grid;
  height: 100%;
  place-items: center;
  border: 0;
  background: none;
  padding-inline: 0 var(--johnbot-space-1-5);
  color: inherit;
  transition: transform var(--johnbot-duration-fast) cubic-bezier(0.23, 1, 0.32, 1);
}

.scroll-to-latest-button svg {
  width: 22px;
  height: 22px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: var(--johnbot-icon-stroke);
}

/* The mark is as tall as the arrow, so one padding can hold both away from every edge. */
.scroll-to-latest-dismiss svg {
  box-sizing: content-box;
  width: 14px;
  height: 14px;
  border-radius: var(--johnbot-radius-pill);
  padding: var(--johnbot-space-1);
  transition: background-color var(--johnbot-duration-hover) ease;
}

/* The ring follows the pill: an offset ring would draw a circle around one half of it. */
.scroll-to-latest-button:focus-visible {
  outline: 2px solid var(--johnbot-border-focus);
  outline-offset: -2px;
}

/* The dismiss ring follows its round icon mark, for the same reason its hover does. */
.scroll-to-latest-dismiss:focus-visible {
  outline: none;
}

.scroll-to-latest-dismiss:focus-visible svg {
  outline: 2px solid var(--johnbot-border-focus);
}

.scroll-to-latest[data-new-messages] .scroll-to-latest-button:focus-visible {
  outline-color: var(--johnbot-unread-text);
}

.scroll-to-latest[data-new-messages] .scroll-to-latest-dismiss:focus-visible svg {
  outline-color: var(--johnbot-unread-text);
}

/* The way back to a reply has a smaller arrow, so the label reads first. */
.scroll-to-latest-button .scroll-to-latest-reply-icon {
  width: 18px;
  height: 18px;
}

.scroll-to-latest-button:active,
.scroll-to-latest-dismiss:active {
  transform: scale(0.96);
}

@media (hover: hover) and (pointer: fine) {
  /* These are shared ghost buttons, whose own hover is written with two `:not()`s and so outweighs
     a plain class. Each rule that has to replace it is matched at the same strength, or its own
     hover paints over the pill and repaints the text for a light background. */
  .scroll-to-latest-button:hover:not(:disabled):not([data-disabled]) {
    background: var(--johnbot-bg-control-active);
    color: inherit;
  }

  /* The dismiss box itself stays unpainted: its mark is the round one on the icon. */
  .scroll-to-latest-dismiss:hover:not(:disabled):not([data-disabled]) {
    background: none;
    color: inherit;
  }

  .scroll-to-latest-dismiss:hover svg {
    background: var(--johnbot-bg-control-active);
  }

  /* The pill has one hover, on the dismiss icon. Its body is a wide target and needs no mark. */
  .scroll-to-latest:is([data-new-messages], [data-reply-return])
  .scroll-to-latest-button:hover:not(:disabled):not([data-disabled]) {
    background: none;
  }

  .scroll-to-latest[data-new-messages] .scroll-to-latest-dismiss:hover svg {
    background: color-mix(in srgb, var(--johnbot-unread-text) 18%, transparent);
  }
}

@media (prefers-reduced-motion: reduce) {
  .scroll-to-latest,
  .scroll-to-latest-button,
  .scroll-to-latest-dismiss,
  .scroll-to-latest-dismiss svg {
    transition: none;
  }

  .scroll-to-latest-button:active,
  .scroll-to-latest-dismiss:active {
    transform: none;
  }
}

.unread-messages-banner {
