  background: var(--johnbot-unread-surface);
  padding: 0 12px;
  color: var(--johnbot-unread-text);
  font-size: var(--johnbot-text-sm);
  font-weight: 620;
  line-height: 16px;
  transition: background-color var(--johnbot-duration-hover) var(--johnbot-ease-out);
}

.unread-messages-banner button {
  border: 0;
  border-radius: var(--johnbot-radius-sm);
  background: transparent;
  color: inherit;
}

.unread-messages-jump {
  position: absolute;
  inset: 0;
  width: 100%;
  padding: 0 12px;
  font-size: var(--johnbot-text-sm);
  font-weight: 620;
  line-height: 16px;
