}

.unread-messages-mark-read {
  position: relative;
  z-index: 1;
  margin-left: auto;
  padding: 0;
  font-size: var(--johnbot-text-sm);
  font-weight: 680;
  line-height: 14px;
  text-decoration: underline;
  text-underline-offset: 2px;
  transition: transform var(--johnbot-duration-fast) cubic-bezier(0.23, 1, 0.32, 1);
}

.unread-messages-mark-read-label {
  display: inline-flex;
  align-items: center;
  border-radius: var(--johnbot-radius-sm);
  padding: 3px 5px;
  transition: background-color var(--johnbot-duration-hover) var(--johnbot-ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .unread-messages-banner:hover {
    background-color: color-mix(in srgb, var(--johnbot-unread-surface) 88%, var(--johnbot-unread-text));
  }

  .unread-messages-banner .ui-button:hover:not(:disabled):not([data-disabled]) {
    background: transparent;
    color: var(--johnbot-unread-text);
  }

  .unread-messages-banner
    .unread-messages-mark-read:hover:not(:disabled):not([data-disabled])
    .unread-messages-mark-read-label {
