.unread-messages-divider {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 8px;
  margin: var(--johnbot-space-1) 0 var(--johnbot-space-2);
  color: var(--johnbot-unread-surface);
  font-size: var(--johnbot-text-sm);
  font-weight: 720;
  letter-spacing: 0.08em;
  line-height: 12px;
}

.unread-messages-divider hr {
  width: 100%;
  height: 1px;
  flex: 1;
  border: 0;
  background: var(--johnbot-unread-surface);
}

.unread-messages-divider span {
  flex: 0 0 auto;
}

.time-marker {
  display: flex;
  align-items: center;
  justify-content: center;
  max-width: 656px;
  height: 24px;
  margin: 0 auto;
  padding: 4px 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
