}

.message-action-button {
  display: grid;
  width: 24px;
  height: 24px;
  place-items: center;
  border: 0;
  border-radius: var(--johnbot-radius-sm);
  background: transparent;
  padding: 0;
  color: var(--johnbot-text-muted);
  transition:
    background var(--johnbot-duration-hover) ease,
    color var(--johnbot-duration-hover) ease;
}

.message-action-button:hover,
.message-action-button:focus-visible,
.message-action-button[aria-expanded="true"] {
