  color: var(--johnbot-text-secondary);
  outline: none;
}

.message-action-button svg {
  width: 17px;
  height: 17px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  /* No stroke-width: every icon in this row is hand-drawn on a 20-unit grid and carries
   * its own scaled weight from .ui-glyph-20. Setting it here outranks that class and
   * paints them a fifth heavier than the grid they were drawn for. */
}

.message-action-button svg circle:not(:first-child),
.message-action-button svg:has(circle:nth-child(3)) circle {
  fill: currentColor;
  stroke: none;
}

.message-action-popover-anchor {
  position: relative;
  display: grid;
  place-items: center;
}

.reaction-picker-row {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: 1px;
}

.reaction-picker-options {
  display: flex;
  flex: 0 0 auto;
  flex-wrap: nowrap;
  align-items: center;
  gap: 1px;
}

.reaction-picker-more {
  margin-top: 3px;
  border-top: 1px solid var(--johnbot-border);
