}

.reaction-picker-more .reaction-picker-options {
  display: grid;
  width: 100%;
  min-width: 0;
  flex: 1 1 auto;
  grid-template-columns: repeat(8, minmax(0, 1fr));
}

.reaction-picker-more .reaction-picker-options [role="menuitemradio"] {
  width: 100%;
  min-width: 0;
}

.reaction-picker-row :is([role="menuitem"], [role="menuitemradio"]) {
  display: grid;
  width: 31px;
  height: 31px;
  flex: 0 0 auto;
  place-items: center;
  border: 0;
  border-radius: var(--johnbot-radius-sm);
  background: transparent;
  padding: 0;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-xl);
  line-height: 1;
  transition:
    background var(--johnbot-duration-hover) ease,
    transform var(--johnbot-duration-hover) ease;
}

.reaction-picker-row :is([role="menuitem"], [role="menuitemradio"]):hover,
.reaction-picker-row :is([role="menuitem"], [role="menuitemradio"]):focus-visible,
.reaction-picker-row :is([role="menuitem"], [role="menuitemradio"])[data-highlighted],
.reaction-picker-row [role="menuitemradio"][aria-checked="true"] {
  background: var(--johnbot-border);
  outline: none;
  transform: scale(1.08);
}

.reaction-picker-row .reaction-more-button {
  color: var(--johnbot-text-muted);
}

.reaction-more-button svg {
  width: 15px;
  height: 15px;
}

.message-reaction-pill {
  display: flex;
  min-width: 0;
  height: var(--johnbot-icon-lg);
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: var(--johnbot-radius-sm);
  background: transparent;
  padding: 0;
  color: inherit;
  font-size: var(--johnbot-text-lg);
  line-height: 1;
  transition: background var(--johnbot-duration-hover) ease;
}

.message-entry:has(.message-reaction-anchor) > .ui-message-content {
  padding-bottom: var(--johnbot-space-3);
}

.message-reaction-anchor .message-reaction-pill {
  gap: 2px;
  margin: 0;
  border-radius: inherit;
}

.ui-bubble-reactions.message-reaction-anchor {
  padding: 2px 6px;
}

.ui-bubble-reactions.message-reaction-anchor:has(> .message-reaction-pill:only-child) {
  width: var(--johnbot-control-xs);
  padding-inline: 2px;
}

.ui-bubble-reactions.message-reaction-anchor:has(> .message-reaction-pill:only-child) > .message-reaction-pill {
  width: var(--johnbot-icon-lg);
  border-radius: var(--johnbot-radius-pill);
}

.message-reaction-anchor .ui-bubble-reaction-overflow {
  padding-right: 6px;
}

.message-reaction-pill:hover {
  background: var(--johnbot-hover);
}

.message-reaction-pill-readonly:hover {
  background: transparent;
}

.message-reaction-anchor:has(.message-reaction-pill:focus-visible) {
  box-shadow:
    0 0 0 3px var(--johnbot-bg-canvas),
    0 0 0 5px var(--johnbot-border-focus);
}

.message-reaction-pill:focus-visible {
  outline: none;
}

.chat-action-entry-animated {
  width: 100%;
  animation: message-in var(--johnbot-duration-normal) cubic-bezier(0.23, 1, 0.32, 1) both;
}

.agent-activity-slot[data-reserved="true"] {
  min-height: 44px;
}

.agent-activity-entry {
  width: 100%;
  display: grid;
  grid-template-rows: 1fr;
  pointer-events: none;
  transition: grid-template-rows var(--johnbot-duration-overlay) var(--johnbot-ease-out);
}

@starting-style {
  .agent-activity-entry {
    grid-template-rows: 0fr;
  }
}

.agent-activity-entry[data-state="exiting"] {
  grid-template-rows: 0fr;
}

.agent-activity-content {
  min-height: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  overflow: clip;
  overflow-clip-margin: var(--johnbot-space-3);
  padding: 4px 0 8px 8px;
  opacity: 1;
  filter: blur(0);
  transform: translateY(0);
  transition:
    opacity var(--johnbot-duration-overlay) var(--johnbot-ease-out),
    filter var(--johnbot-duration-overlay) var(--johnbot-ease-out),
    transform var(--johnbot-duration-overlay) var(--johnbot-ease-out);
  will-change: opacity, filter, transform;
}

@starting-style {
  .agent-activity-content {
    opacity: 0;
    filter: blur(2px);
    transform: translateY(4px);
  }
}

.agent-activity-entry[data-state="exiting"] .agent-activity-content {
  opacity: 0;
  filter: blur(2px);
  transform: translateY(2px);
}

.agent-activity-avatar {
  --agent-avatar-optical-offset: -2px;

  width: 32px;
  height: 32px;
  flex: 0 0 auto;
  align-self: center;
  transform: translateY(0) scale(1);
  transition: transform var(--johnbot-duration-overlay) var(--johnbot-ease-out);
  will-change: transform;
}

@starting-style {
  .agent-activity-avatar {
    transform: translateY(3px) scale(0.96);
  }
}

.agent-activity-entry[data-state="exiting"] .agent-activity-avatar {
  transform: translateY(0) scale(0.98);
}

.agent-activity-label {
  display: -webkit-box;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  background: linear-gradient(
    90deg,
    var(--johnbot-text-primary) 0%,
    var(--johnbot-text-primary) 30%,
    var(--johnbot-text-muted) 45%,
    var(--johnbot-text-muted) 55%,
    var(--johnbot-text-primary) 70%,
    var(--johnbot-text-primary) 100%
  );
  background-size: 300% 100%;
  background-clip: text;
  color: transparent;
  font-size: var(--johnbot-text-sm);
  line-height: 20px;
  overflow-wrap: anywhere;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: image-generation-shine 2.25s cubic-bezier(0.25, 0.1, 0.25, 1) infinite;
}

/* A wait for the provider is not work, so its label does not shine. */
.agent-activity-entry[data-waiting="true"] .agent-activity-label {
  animation: none;
  background: none;
  color: var(--johnbot-text-secondary);
  -webkit-text-fill-color: currentColor;
}

.agent-activity-elapsed {
  flex: 0 0 auto;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
  line-height: 20px;
}

.chat-action-marker {
  width: min(var(--johnbot-chat-marker-width), calc(100% - var(--johnbot-space-6)));
  min-height: var(--johnbot-chat-marker-height);
  justify-content: center;
  margin: 0 auto;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  letter-spacing: var(--johnbot-tracking-normal);
  text-align: center;
}

.chat-action-marker-content {
  max-width: 100%;
  gap: var(--johnbot-space-1);
}

.chat-action-marker-summary {
  /* The reveal's own timings. They sit above the `--johnbot-duration-*` scale,
     which tops out at an overlay fade: this is a panel of rows that has to read
     as unrolling, and the palette has no token for that. */
  --chat-action-history-open: 340ms;
  /* The shared eases are quint curves: `--johnbot-ease-in-out` holds the panel
     almost still for 50ms and then moves 25px in two frames, which reads as a
     lurch in everything below it. This one spreads the distance evenly and
     settles, so the messages under the marker travel at one speed. */
  --chat-action-history-ease: cubic-bezier(0.4, 0, 0.2, 1);
  /* The close is shorter than the open: leaving needs no reading time, and a
     long collapse holds the messages below in motion for no reason. */
  --chat-action-history-close: 200ms;
  /* The close curve decelerates from the first frame. The open's ease holds the
     panel almost still for the first 20ms, which reads as a click the panel did
     not answer, and then drops the box fast. */
  --chat-action-history-close-ease: cubic-bezier(0.32, 0.08, 0.24, 1);
  /* The rows have to stay faintly visible until the box is nearly shut. A
     shorter fade empties the panel at the halfway point and leaves blank space
     closing on its own. */
  --chat-action-history-lift: 170ms;
  /* How much of the box's bottom edge dissolves while it closes. One row's
     worth, so the edge takes a row out at a time. */
  --chat-action-history-fade: 22px;
  --chat-action-history-entry: 260ms;
  /* Each state waits this much longer than the one above it. */
  --chat-action-history-stagger: 60ms;
  display: flex;
  min-width: 0;
  max-width: 100%;
  flex-direction: column;
  align-items: center;
}

.ui-button.chat-action-history-toggle {
  flex: 0 0 auto;
  color: var(--johnbot-text-muted);
}

.chat-action-history-toggle svg {
  transition: transform var(--chat-action-history-close) var(--johnbot-ease-out);
}

.chat-action-history-toggle[aria-expanded="true"] svg {
  transform: rotate(180deg);
}

/* The panel is a single grid track, so `0fr` to `1fr` animates the list's real
   height with no measured pixel value - the same technique as `.t-acc` in
   transitions.css. The height has to move for the row below to follow it; a
   paint-only reveal leaves the space behind and drops it in one step at the end.
   A `from` or `to` alone leaves the other end on the element's own style, so
   these rules stay the single source of the resting state. */
.chat-action-history-panel {
  display: grid;
  width: 100%;
  grid-template-rows: 1fr;
}

.chat-action-history-panel[data-state="open"] {
  animation: chat-action-history-open var(--chat-action-history-open) var(--chat-action-history-ease);
}

/* The close runs the same track backwards and holds `0fr` until the panel leaves
   the tree, so the messages below travel the whole distance under one curve
   instead of standing still and then closing the gap in a single step. */
.chat-action-history-panel[data-state="closed"] {
  animation: chat-action-history-close var(--chat-action-history-close) var(--chat-action-history-close-ease) forwards;
}

@keyframes chat-action-history-open {
  from {
    grid-template-rows: 0fr;
  }
}

@keyframes chat-action-history-close {
  to {
    grid-template-rows: 0fr;
  }
}

/* On the way in the box grows under rows that are still fading up, so its edge
   never cuts anything solid. */
.chat-action-history-panel[data-state="open"] .chat-action-history {
  animation: chat-action-history-settle var(--chat-action-history-open) var(--johnbot-ease-out);
}

/* The rows fade out just before the box finishes closing, so the clip edge never
   cuts through anything solid and the panel is never an empty box shrinking on
   its own. The panel leaves the tree on the collapse's end, not on this one's. */
.chat-action-history-panel[data-state="closed"] .chat-action-history {
  animation: chat-action-history-lift var(--chat-action-history-lift) var(--johnbot-ease-out) forwards;
}

/* No fade on the way in: the rows already carry their own, and stacking a second
   one over them washes the whole panel out. */
@keyframes chat-action-history-settle {
  from {
    transform: translateY(-25%);
  }
}

/* The lift stays small on the way out: the collapsing box already carries the
   rows upward, and a longer travel makes them outrun it and arrive early. */
@keyframes chat-action-history-lift {
  to {
    transform: translateY(-8%);
    opacity: 0;
  }
}

/* `min-height: 0` lets the track win over the list's content height, and the
   clip keeps the rows inside the shrinking box. */
.chat-action-history-clip {
  min-height: 0;
  overflow: hidden;
}

/* The closing box passes its edge over rows that are still readable and cuts
   them through the middle of the glyphs. The mask softens that edge, so a row
   dissolves as the edge reaches it instead of being sliced. Below the fade
   distance the whole list is inside the gradient and leaves on its own. The way
   in needs none of this: there the box grows ahead of rows that are still
   arriving. */
.chat-action-history-panel[data-state="closed"] .chat-action-history-clip {
  -webkit-mask-image: linear-gradient(
    to bottom,
    var(--johnbot-text-primary) calc(100% - var(--chat-action-history-fade)),
    transparent
  );
  mask-image: linear-gradient(
    to bottom,
    var(--johnbot-text-primary) calc(100% - var(--chat-action-history-fade)),
    transparent
  );
}

.chat-action-history {
  box-sizing: border-box;
  display: grid;
  width: 100%;
  gap: var(--johnbot-space-1);
  margin: var(--johnbot-space-1) 0 0;
  padding: var(--johnbot-space-1-5) var(--johnbot-space-2);
  border-inline-start: 1px solid var(--johnbot-border-grouped);
  list-style: none;
  text-align: left;
}

.chat-action-history-entry {
  display: grid;
  grid-template-columns: var(--johnbot-icon-xs) minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--johnbot-space-1-5);
  color: var(--johnbot-text-secondary);
}

/* `backwards` holds the entry hidden through its delay, so a late state never
   shows at full strength before its turn. The exit leaves the rows alone: the
   list fades as one piece. */
.chat-action-history-panel[data-state="open"] .chat-action-history-entry {
  animation: chat-action-history-entry-in var(--chat-action-history-entry) var(--johnbot-ease-out) backwards;
}

.chat-action-history-panel[data-state="open"] .chat-action-history-entry:nth-child(2) {
  animation-delay: var(--chat-action-history-stagger);
}

.chat-action-history-panel[data-state="open"] .chat-action-history-entry:nth-child(3) {
  animation-delay: calc(var(--chat-action-history-stagger) * 2);
}

/* The stagger stops growing here: a long run should not open in slow motion. */
.chat-action-history-panel[data-state="open"] .chat-action-history-entry:nth-child(n + 4) {
  animation-delay: calc(var(--chat-action-history-stagger) * 3);
}

@keyframes chat-action-history-entry-in {
  from {
    transform: translateX(calc(var(--johnbot-space-1) * -1));
    opacity: 0;
    filter: blur(2px);
  }
}

.chat-action-history-entry time {
  color: var(--johnbot-text-muted);
  white-space: nowrap;
}

.chat-action-history-icon,
.chat-action-history-icon svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
}

.chat-action-history-status-completed .chat-action-history-icon {
  color: var(--johnbot-success);
}

.chat-action-history-status-failed .chat-action-history-icon,
.chat-action-history-status-interrupted .chat-action-history-icon,
.chat-action-history-status-cancelled .chat-action-history-icon {
  color: var(--johnbot-danger);
}

.chat-action-history-status-needs-attention .chat-action-history-icon {
  color: var(--johnbot-warning);
}

.chat-action-history-status-in-progress .chat-action-history-icon {
  color: var(--johnbot-accent);
}

@media (prefers-reduced-motion: reduce) {
  .chat-action-history-panel,
  .chat-action-history,
  .chat-action-history-entry {
    animation: none;
  }

  .chat-action-history-toggle svg {
    transition: none;
  }
}

.chat-action-marker-label,
.chat-action-marker-time {
  flex: 0 0 auto;
  white-space: nowrap;
}

.chat-action-marker-time {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

.chat-action-target {
  box-sizing: border-box;
  display: inline-flex;
  min-width: 0;
  max-width: min(280px, 100%);
  height: auto;
  min-height: var(--johnbot-chat-marker-height);
  flex: 0 1 auto;
  align-items: center;
  gap: var(--johnbot-space-1);
  border: 0;
  border-radius: var(--johnbot-radius-pill);
  background: transparent;
  padding: 0 var(--johnbot-space-1-5);
  color: var(--johnbot-text-secondary);
  font: inherit;
  line-height: inherit;
  outline: none;
  text-align: left;
  white-space: nowrap;
  transition:
    background-color var(--johnbot-duration-hover) var(--johnbot-ease-out),
    box-shadow var(--johnbot-duration-hover) var(--johnbot-ease-out),
    color var(--johnbot-duration-hover) var(--johnbot-ease-out),
    scale var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

button.chat-action-target:hover,
.chat-action-agent-menu-trigger:hover,
.chat-action-agent-menu-trigger[aria-expanded="true"] {
  background: var(--johnbot-bg-control-hover);
  box-shadow: 0 0 0 1px var(--johnbot-border-strong);
  color: var(--johnbot-text-primary);
}

button.chat-action-target:focus-visible,
.chat-action-agent-menu-trigger:focus-visible {
  background: var(--johnbot-bg-control-hover);
  box-shadow: var(--johnbot-focus-ring);
  color: var(--johnbot-text-primary);
}

button.chat-action-target:active,
.chat-action-agent-menu-trigger:active {
  background: var(--johnbot-bg-control-active);
  scale: 0.96;
}

.chat-action-target-unavailable {
  color: var(--johnbot-text-muted);
}

/* Markers without a target pill keep the same optical label-to-time rhythm. */
.chat-action-marker-unavailable .chat-action-marker-label,
.chat-action-marker-context-reset .chat-action-marker-label,
.chat-action-marker-model-switch .chat-action-marker-label,
.chat-action-marker-channel-change .chat-action-marker-label {
  padding-inline-end: var(--johnbot-space-1-5);
}

.chat-action-target-name,
.chat-action-target > span:last-child {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.chat-action-target .ui-marker-icon,
.chat-action-target .ui-marker-icon svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  flex: 0 0 var(--johnbot-icon-xs);
}

.chat-action-target .ui-marker-icon {
  translate: 0 -0.5px;
}

.chat-action-agent-avatar {
  --agent-avatar-optical-offset: -2px;

  position: relative;
  width: var(--johnbot-chat-marker-avatar);
  height: var(--johnbot-chat-marker-avatar);
  flex: 0 0 var(--johnbot-chat-marker-avatar);
  border: 0;
  background: transparent;
  translate: 0 -0.5px;
}

.chat-action-marker-agent-message .chat-action-target {
  --chat-action-agent-color: var(--johnbot-accent);
}

.chat-action-marker-agent-message button.chat-action-target:hover,
.chat-action-marker-agent-message .chat-action-agent-menu-trigger:hover,
.chat-action-marker-agent-message .chat-action-agent-menu-trigger[aria-expanded="true"] {
  background: color-mix(in srgb, var(--chat-action-agent-color) 16%, transparent);
  box-shadow: none;
  color: var(--chat-action-agent-color);
}

.chat-action-marker-agent-message button.chat-action-target:focus-visible,
.chat-action-marker-agent-message .chat-action-agent-menu-trigger:focus-visible {
  background: color-mix(in srgb, var(--chat-action-agent-color) 16%, transparent);
  box-shadow: var(--johnbot-focus-ring);
  color: var(--chat-action-agent-color);
}

.chat-action-marker-agent-message button.chat-action-target:active,
.chat-action-marker-agent-message .chat-action-agent-menu-trigger:active {
  background: color-mix(in srgb, var(--chat-action-agent-color) 34%, transparent);
  color: var(--johnbot-text-primary);
}

/* The open text of an agent message reads as a chat message under its centred marker. */
.chat-action-message-text {
  align-self: stretch;
  margin-block: var(--johnbot-space-2);
  text-align: start;
}

.chat-action-target-status-in-progress .ui-marker-icon {
  color: var(--johnbot-accent);
}

.chat-action-target-status-completed .ui-marker-icon {
  color: var(--johnbot-success);
}

.chat-action-target-status-failed .ui-marker-icon,
.chat-action-target-status-cancelled .ui-marker-icon,
.chat-action-target-status-interrupted .ui-marker-icon {
  color: var(--johnbot-danger);
}

.chat-action-target-status-needs-attention .ui-marker-icon {
  color: var(--johnbot-warning);
}

.chat-action-target-status-in-progress .ui-marker-icon svg {
  animation: ui-spin 1s linear infinite;
}

.chat-action-avatar-stack {
  display: inline-flex;
  min-width: 0;
  height: var(--johnbot-chat-marker-avatar);
  align-items: center;
}

.chat-action-avatar-stack .chat-action-agent-avatar + .chat-action-agent-avatar {
  margin-left: -6px;
}

/* An open group lists each message as its own marker, centred like the row that holds them. */
.chat-action-group-list {
  padding-inline: 0;
  border-inline-start: 0;
  text-align: center;
}

/* Only the group's own rows: a routine run in an open group keeps the layout of its own history. */
.chat-action-group-list > .chat-action-history-entry {
  display: block;
}

.chat-action-group-list .chat-action-marker {
  width: 100%;
}

/* A group of routine runs reads "routine · 3 runs · 17:15–18:45". In a narrow chat the count, the
   time and the toggle move together to a second line, so the routine keeps its whole name. The dots
   are decoration only. */
.chat-action-marker-routine-run-group > .chat-action-marker-summary > .chat-action-marker-content {
  flex-wrap: wrap;
  justify-content: center;
}

.chat-action-run-group-details {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: var(--johnbot-space-1);
}

.chat-action-run-group-count::before,
.chat-action-run-group-time::before {
  content: "·" / "";
  margin-inline-end: var(--johnbot-space-1);
}

/* The shared .ui-action-menu item rule outranks a single class, so the grid template and the
 * truncation below have to be compounded to reach the row. */
.ui-action-menu.chat-action-agent-menu {
  min-width: 220px;
  max-width: min(320px, calc(100vw - var(--johnbot-space-4)));
}

.ui-action-menu.chat-action-agent-menu .chat-action-agent-menu-item[role="menuitem"] {
  display: grid;
  align-items: center;
  grid-template-columns: 18px minmax(0, 1fr) auto;
  gap: var(--johnbot-space-2);
}

.chat-action-agent-menu-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.chat-action-agent-menu-item .chat-action-agent-avatar {
  width: 18px;
  height: 18px;
  flex-basis: 18px;
}

.chat-action-agent-menu-status {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  white-space: nowrap;
}

/* The files of an update sit at the start edge, where an agent's own files sit. */
.chat-action-attachments {
  margin-top: var(--johnbot-space-2);
}

.chat-row-unavailable {
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  text-align: center;
}

@media (prefers-reduced-motion: reduce) {
  .chat-action-target-status-in-progress .ui-marker-icon svg {
    animation: none;
  }
}

.message-entry .ui-bubble {
  letter-spacing: -0.15px;
}

.message-entry-agent .ui-bubble {
  max-width: min(720px, 100%);
}

.message-entry-agent .ui-bubble:has(.choice-card) {
  width: min(500px, 100%);
  max-width: min(500px, 100%);
}

.message-entry-agent .ui-bubble:has(.image-generation) {
  width: min(420px, 100%);
  max-width: min(420px, 100%);
}

.message-entry-agent .ui-bubble:has(.image-gallery) {
  width: min(520px, 100%);
  max-width: min(520px, 100%);
}

.message-entry-agent
  .ui-bubble-variant-ghost:has(
    :is(.choice-card, .image-generation, .image-gallery, .message-code-block, .message-data-table-scroll)
  )
  > .ui-bubble-content {
  width: 100%;
}

.image-generation {
  display: grid;
  min-width: 0;
  justify-items: start;
  gap: 14px;
}

.message-image-attachments {
  display: grid;
  min-width: 0;
  gap: 10px;
}

.image-generation-stage {
  position: relative;
  width: min(100%, 420px);
  overflow: hidden;
  aspect-ratio: var(--image-generation-ratio);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-control);
  isolation: isolate;
}

.image-generation-canvas,
.image-generation-preview {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.image-generation-canvas {
  overflow: hidden;
  background: var(--johnbot-bg-control);
  opacity: 1;
  transition: opacity var(--johnbot-duration-overlay) ease;
}

.image-generation-canvas-failed {
  display: grid;
  place-items: center;
}

.image-generation-ready .image-generation-canvas {
  opacity: 0;
}

/* The canvas above rests at `opacity: 0` once the image arrives, but the glow
 * inside it keeps two infinite keyframes on `mask-size` and `mask-position`,
 * and the compositor can take neither. One finished image in the history
 * therefore costs a style recalculation and a repaint every frame for as long
 * as the conversation is open. A profile of an idle window measured 60 style
 * recalculations a second with no script running at all. The reduced-motion
 * block at the end of this file already stops these keyframes for the same
 * element, so this only makes the finished state agree with it. */
.image-generation-ready .image-generation-glow {
  animation: none;
}

.image-generation-dots {
  position: absolute;
  inset: 2px;
  background-image: radial-gradient(circle, var(--johnbot-text-muted) 0.7px, transparent 1.3px);
  background-repeat: space;
  background-size: 11px 11px;
  opacity: 0.22;
}

.image-generation-failure-mark {
  display: grid;
  width: 54px;
  height: 54px;
  place-items: center;
  border: 2px solid var(--johnbot-danger);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-danger-soft);
  box-shadow: 0 0 0 5px var(--johnbot-danger-soft);
  color: var(--johnbot-danger);
}

/* Was a 40px U+00D7 sized off a type token, which is why the scale carried a step no
 * copy in the app used. */
.image-generation-failure-mark > svg {
  width: var(--johnbot-control-xl);
  height: var(--johnbot-control-xl);
  stroke-width: var(--johnbot-icon-stroke);
}

.image-generation-glow {
  position: absolute;
  inset: 2px;
  background-image: radial-gradient(circle, var(--johnbot-text-primary) 1.1px, transparent 1.6px);
  background-repeat: space;
  background-size: 11px 11px;
  -webkit-mask-image:
    radial-gradient(ellipse at center, var(--johnbot-text-primary) 0%, transparent 60%),
    radial-gradient(ellipse at center, var(--johnbot-text-primary) 0%, transparent 62%);
  mask-image:
    radial-gradient(ellipse at center, var(--johnbot-text-primary) 0%, transparent 60%),
    radial-gradient(ellipse at center, var(--johnbot-text-primary) 0%, transparent 62%);
  -webkit-mask-repeat: no-repeat, no-repeat;
  mask-repeat: no-repeat, no-repeat;
  -webkit-mask-size:
    72% 62%,
    52% 52%;
  mask-size:
    72% 62%,
    52% 52%;
  -webkit-mask-position:
    16% 20%,
    30% 32%;
  mask-position:
    16% 20%,
    30% 32%;
  animation:
    image-generation-morph 4.2s cubic-bezier(0.35, 1.55, 0.65, 1) infinite,
    image-generation-breathe 1.9s cubic-bezier(0.66, 0, 0.34, 1) infinite;
}

.image-generation-resolution {
  position: absolute;
  z-index: 1;
  top: 8px;
  right: 8px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-surface);
  padding: 2px 7px;
  color: var(--johnbot-text-muted);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: var(--johnbot-text-sm);
  white-space: nowrap;
}

.image-generation-meta {
  display: flex;
  width: min(100%, 420px);
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  text-align: left;
}

.image-generation-label {
  background: linear-gradient(
    90deg,
    var(--johnbot-text-primary) 0%,
    var(--johnbot-text-primary) 30%,
    var(--johnbot-text-muted) 45%,
    var(--johnbot-text-muted) 55%,
    var(--johnbot-text-primary) 70%,
    var(--johnbot-text-primary) 100%
  );
  background-size: 300% 100%;
  background-clip: text;
  color: transparent;
  font-size: var(--johnbot-text-lg);
  font-weight: 550;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

/* The shimmer says "still working", so it stops once the image has arrived or
   failed. Left unscoped it also ran on "Image generation failed" and on plain
   attached images, and it animates `background-position` under
   `background-clip: text` - a main-thread text repaint per frame that no
   compositor can take - once per image message, for the life of the thread. */
.image-generation:not(.image-generation-ready, .image-generation-failed) .image-generation-label {
  animation: image-generation-shine 2.25s cubic-bezier(0.25, 0.1, 0.25, 1) infinite;
}

.image-generation-prompt {
  overflow: hidden;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  line-height: 18px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.image-generation-error {
  max-width: 100%;
  color: var(--johnbot-danger);
  font-size: var(--johnbot-text-sm);
  line-height: 17px;
}

.image-generation-preview {
  display: block;
  border: 0;
  background: var(--johnbot-bg-control);
  cursor: pointer;
  opacity: 0;
  padding: 0;
  transition: opacity var(--johnbot-duration-overlay) ease;
}

.image-generation-preview-visible {
  opacity: 1;
}

.image-generation-preview img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.image-generation-preview:focus-visible,
.image-generation-hover-download:focus-visible {
  outline: 2px solid var(--johnbot-border-focus);
  outline-offset: 2px;
}

.image-generation-hover-download {
  position: absolute;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  right: 10px;
  bottom: 10px;
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-glass);
  padding: 5px 10px;
  color: var(--johnbot-text-primary);
  cursor: pointer;
  backdrop-filter: blur(12px) saturate(1.15);
  -webkit-backdrop-filter: blur(12px) saturate(1.15);
  font-size: var(--johnbot-text-sm);
  font-weight: 650;
  opacity: 0;
  pointer-events: none;
  transform: translateY(4px);
  transition:
    background-color var(--johnbot-duration-hover) ease,
    color var(--johnbot-duration-hover) ease,
    border-color var(--johnbot-duration-hover) ease,
    opacity var(--johnbot-duration-hover) ease,
    transform var(--johnbot-duration-hover) ease;
}

.image-generation-download-icon {
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
}

.image-generation-stage:hover .image-generation-hover-download,
.image-generation-stage:focus-within .image-generation-hover-download {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}

.image-generation-hover-download:hover {
  border-color: var(--johnbot-border-focus);
  background: var(--johnbot-bg-glass);
  color: var(--johnbot-text-primary);
}

@keyframes image-generation-morph {
  0% {
    -webkit-mask-size:
      52% 46%,
      40% 40%;
    mask-size:
      52% 46%,
      40% 40%;
    -webkit-mask-position:
      16% 20%,
      30% 32%;
    mask-position:
      16% 20%,
      30% 32%;
  }
  25% {
    -webkit-mask-size:
      46% 58%,
      44% 38%;
    mask-size:
      46% 58%,
      44% 38%;
    -webkit-mask-position:
      84% 16%,
      66% 30%;
    mask-position:
      84% 16%,
      66% 30%;
  }
  50% {
    -webkit-mask-size:
      60% 44%,
      38% 46%;
    mask-size:
      60% 44%,
      38% 46%;
    -webkit-mask-position:
      82% 84%,
      62% 68%;
    mask-position:
      82% 84%,
      62% 68%;
  }
  75% {
    -webkit-mask-size:
      48% 54%,
      46% 40%;
    mask-size:
      48% 54%,
      46% 40%;
    -webkit-mask-position:
      14% 82%,
      34% 66%;
    mask-position:
      14% 82%,
      34% 66%;
  }
  100% {
    -webkit-mask-size:
      52% 46%,
      40% 40%;
    mask-size:
      52% 46%,
      40% 40%;
    -webkit-mask-position:
      16% 20%,
      30% 32%;
    mask-position:
      16% 20%,
      30% 32%;
  }
}

@keyframes image-generation-breathe {
  0%,
  100% {
    opacity: 0.55;
  }
  50% {
    opacity: 1;
  }
}

@keyframes image-generation-shine {
  0%,
  18% {
    background-position: 100% 0;
  }
  82%,
  100% {
    background-position: 0% 0;
  }
}

/* A failed send, beside the time under the bubble. A send in flight leaves it empty. */
.pending-send-status {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 2px;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.pending-send-label {
  display: inline-flex;
  align-items: center;
  gap: var(--johnbot-space-1);
  color: var(--johnbot-danger-text);
}

.pending-send-label:not(:empty) {
  margin-inline-end: var(--johnbot-space-1);
}

.pending-send-label > svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: none;
}

.pending-send-error {
  color: var(--johnbot-text-muted);
  overflow-wrap: anywhere;
}

.pending-send-error::before {
  content: "·";
  margin-inline-end: var(--johnbot-space-1);
}

/* agent-steps.css */
/* The steps of an agent's turn: under the activity line while it runs, above the answer after. */

/* The working rings reach about 10px past a face, and the channel's faces sit 2px from the edge.
   The clip margin keeps the rings whole. It goes when the line leaves, so open steps do not show
   below the closing row. */
.agent-activity-body {
  min-height: 0;
  overflow: clip;
  overflow-clip-margin: var(--johnbot-space-3);
}

.agent-activity-entry[data-state="exiting"] .agent-activity-body {
  overflow-clip-margin: 0;
}

/* The entry ignores the pointer so the chat scrolls under it; its controls take it back. */
.agent-activity-content .agent-steps-toggle,
.agent-activity-steps {
  pointer-events: auto;
}

.agent-activity-content .agent-steps-toggle {
  flex: 0 0 auto;
  color: var(--johnbot-text-muted);
}

/* The open list is not a lit toggle, so the chevron has no fill. */
.agent-activity-content .agent-steps-toggle[aria-expanded="true"]:not(:hover) {
  background: transparent;
}

.agent-activity-steps {
  padding: 0 0 var(--johnbot-space-2) var(--johnbot-space-6);
}

.agent-steps-chevron {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  flex: 0 0 auto;
  color: var(--johnbot-text-muted);
  transition: rotate var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.agent-steps-toggle[aria-expanded="true"] .agent-steps-chevron {
  rotate: 180deg;
}

/* The row's chevron points right, as the subagents header's does, and down when its list is open. */
.agent-steps-header[aria-expanded="true"] .agent-steps-chevron {
  rotate: 90deg;
}

.agent-steps {
  display: grid;
  justify-items: start;
  margin-bottom: var(--johnbot-space-1);
}

/* The row looks like the header of the subagents above it. */
.agent-steps .agent-steps-header {
  display: flex;
  height: auto;
  min-width: 0;
  max-width: 100%;
  align-items: center;
  gap: var(--johnbot-space-2);
  margin-left: calc(-1 * var(--johnbot-space-1-5));
  border-radius: var(--johnbot-radius-sm);
  padding: var(--johnbot-space-0-5) var(--johnbot-space-1-5);
  color: inherit;
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-regular);
  line-height: var(--johnbot-leading-md);
  text-align: left;
}

/* The open list is not a lit toggle, so the header has no fill. */
.agent-steps .agent-steps-header[aria-expanded="true"]:not(:hover) {
  background: transparent;
  color: inherit;
}

.agent-step-icon {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  flex: 0 0 auto;
  color: var(--johnbot-text-muted);
}

.agent-steps-summary {
  overflow: hidden;
  font-weight: var(--johnbot-weight-medium);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-steps-failed {
  flex: 0 0 auto;
  color: var(--johnbot-danger-text);
  font-variant-numeric: tabular-nums;
}

.agent-steps-duration {
  flex: 0 0 auto;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
}

.agent-steps-panel {
  display: grid;
  width: 100%;
  grid-template-rows: 1fr;
  opacity: 1;
  transition:
    grid-template-rows var(--johnbot-duration-overlay) var(--johnbot-ease-out),
    opacity var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

/* The panel exists only while the row is open, so it opens from its first frame. */
@starting-style {
  .agent-steps-panel {
    grid-template-rows: 0fr;
    opacity: 0;
  }
}

.agent-steps-viewport {
  max-height: 220px;
  overflow: hidden;
  padding-left: var(--johnbot-space-3);
  border-left: 1px solid var(--johnbot-border);
}

.agent-steps-viewport[data-scrolls] {
  overflow-y: auto;
}

.agent-steps-panel > .agent-steps-viewport {
  min-height: 0;
  margin-left: var(--johnbot-space-3);
}

.agent-steps-list {
  display: grid;
  gap: var(--johnbot-space-1);
  margin: 0;
  padding: var(--johnbot-space-1-5) 0;
  list-style: none;
  transition: transform var(--johnbot-duration-overlay) var(--johnbot-ease-out);
}

.agent-step {
  display: flex;
  align-items: flex-start;
  gap: var(--johnbot-space-2);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  overflow-wrap: anywhere;
  animation: message-in var(--johnbot-duration-normal) var(--johnbot-ease-out) both;
}

/* The step that the user picked in the trace lights up, then fades back. A colour change is not
 * motion, so it stays with reduced motion. */
.agent-step[data-focused] {
  border-radius: var(--johnbot-radius-xs);
  animation: agent-step-picked calc(var(--johnbot-duration-overlay) * 6) var(--johnbot-ease-out) both;
}

@keyframes agent-step-picked {
  from {
    background: var(--johnbot-hover);
  }

  to {
    background: transparent;
  }
}

.agent-step .agent-step-icon {
  margin-top: 2px;
}

.agent-step[data-kind="thinking"] .agent-step-text {
  color: var(--johnbot-text-muted);
  font-style: italic;
}

.agent-step-text.agent-activity-label {
  display: inline;
  -webkit-line-clamp: unset;
}

.agent-step-memory {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 0 var(--johnbot-space-2);
  color: var(--johnbot-text-primary);
}

.agent-step-memory-action,
.agent-step-memory-previous,
.agent-step-memory[data-action="forgotten"] s {
  color: var(--johnbot-text-muted);
}

@media (prefers-reduced-motion: reduce) {
  .agent-steps-chevron,
  .agent-steps-panel,
  .agent-steps-list {
    transition: none;
  }

  .agent-step {
    animation: none;
  }
}

/* trace-waterfall.css */
/* The trace of an agent run: the totals, then one timeline row for each span. */

.trace {
  --trace-surface: var(--johnbot-bg-surface);
  /* `cqw` resolves where these are used, inside the scroll body, so a narrow trace keeps its timeline. */
  --trace-name-width: min(260px, 45cqw);
  /* Room on the right of the timeline for the label after the last bar. */
  --trace-label-room: min(150px, 25cqw);
  --trace-lane-pad: var(--johnbot-space-3);
  --trace-row-height: 36px;
  --trace-bar-height: 16px;
  /* The colour of the agent that did a span. The top agent and its own calls stay neutral. */
  --trace-hue: var(--johnbot-text-muted);
  display: flex;
  min-width: 0;
  min-height: 0;
  max-height: 100%;
  flex: 1 1 auto;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-card);
  background: var(--trace-surface);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.trace-header {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  padding: var(--johnbot-space-2) var(--johnbot-space-2) var(--johnbot-space-2) var(--johnbot-space-4);
  border-bottom: 1px solid var(--johnbot-border);
}

.trace-title {
  flex: 1 1 auto;
  margin: 0;
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-md);
}

/* The speed menu is compact: it holds one short value. */
.ui-select.trace-select {
  width: auto;
  flex: 0 0 auto;
}

.trace-select .trace-select-trigger {
  width: auto;
  gap: var(--johnbot-space-1);
  padding-inline: var(--johnbot-space-2) var(--johnbot-space-1-5);
  font-variant-numeric: tabular-nums;
}

.trace-search {
  position: relative;
  width: min(240px, 100%);
}

.trace-search-icon {
  position: absolute;
  top: 50%;
  left: var(--johnbot-space-2);
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  color: var(--johnbot-text-muted);
  translate: 0 -50%;
  pointer-events: none;
}

.trace-search .trace-search-input {
  width: 100%;
  padding-inline: calc(var(--johnbot-space-2) * 2 + var(--johnbot-icon-xs)) var(--johnbot-space-8);
}

/* A focused field gets a neutral border only, as the other fields of the app. */
.trace-search .trace-search-input:focus-visible {
  border-color: var(--johnbot-text-muted);
  box-shadow: none;
  outline: none;
}

/* The browser's own clear button would sit under the shortcut hint. */
.trace-search-input::-webkit-search-cancel-button {
  display: none;
}

.trace-search-kbd {
  position: absolute;
  top: 50%;
  right: var(--johnbot-space-1-5);
  translate: 0 -50%;
  pointer-events: none;
}

.trace-totals {
  display: flex;
  flex: 0 0 auto;
  flex-wrap: wrap;
  /* The last total in each line puts its right border outside the trace, where it is clipped. */
  margin: 0 -1px 0 0;
}

.trace-total {
  display: grid;
  flex: 1 1 96px;
  gap: var(--johnbot-space-0-5);
  min-width: 0;
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
  border-right: 1px solid var(--johnbot-border);
  border-bottom: 1px solid var(--johnbot-border);
}

.trace-total-label {
  overflow: hidden;
  color: var(--johnbot-text-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The same roll as the task list: the digits that change lift in and sharpen. */
.trace-total-value {
  --digit-dur: var(--johnbot-duration-overlay);
  --digit-distance: var(--johnbot-space-1);
  --digit-blur: var(--johnbot-space-0-5);
  --digit-ease: var(--johnbot-ease-out);

  margin: 0;
  font-size: var(--johnbot-text-lg);
  font-variant-numeric: tabular-nums;
  line-height: var(--johnbot-leading-lg);
}

.trace-body {
  --trace-fade: var(--johnbot-space-6);
  /* No edge is faded until the list scrolls: one opaque layer for each edge. */
  --trace-mask-top: linear-gradient(var(--johnbot-text-primary), var(--johnbot-text-primary));
  --trace-mask-bottom: linear-gradient(var(--johnbot-text-primary), var(--johnbot-text-primary));
  min-height: 0;
  flex: 1 1 auto;
  overflow: auto;
  container-type: inline-size;
  scrollbar-width: none;
}

.trace-body::-webkit-scrollbar {
  display: none;
}

.trace-body.scroll-fade-top,
.trace-body.scroll-fade-bottom {
  mask-image: var(--trace-mask-top), var(--trace-mask-bottom);
  mask-composite: intersect;
}

/* The rows fade in under the rows that stay at the top. */
.trace-body.scroll-fade-top {
  --trace-mask-top: linear-gradient(
    to bottom,
    var(--johnbot-text-primary) var(--trace-stack),
    transparent var(--trace-stack),
    var(--johnbot-text-primary) calc(var(--trace-stack) + var(--trace-fade))
  );
}

.trace-body.scroll-fade-bottom {
  --trace-mask-bottom: linear-gradient(
    to bottom,
    var(--johnbot-text-primary) calc(100% - var(--trace-fade)),
    transparent
  );
}

.trace-grid {
  position: relative;
  z-index: 0;
}

.trace-rows {
  margin: 0;
  padding: 0;
  list-style: none;
}

.trace-row {
  display: grid;
  height: var(--trace-row-height);
  box-sizing: border-box;
  grid-template-columns: var(--trace-name-width) minmax(0, 1fr);
  border-bottom: 1px solid var(--johnbot-border);
}

/* The rows under a parent slide closed when it folds and open when it unfolds. `clip`, not `hidden`:
 * a scroll container here would stop the parent rows inside from staying at the top. */
.trace-branch-children {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows var(--johnbot-duration-slow) var(--johnbot-ease-out);
}

.trace-branch-children[data-open] {
  grid-template-rows: 1fr;
}

.trace-branch-clip {
  min-height: 0;
  overflow: clip;
  opacity: 0;
  transition: opacity var(--johnbot-duration-slow) var(--johnbot-ease-out);
}

.trace-branch-children[data-open] > .trace-branch-clip {
  opacity: 1;
}

/* A row that a search or a replay adds fades in. */
.trace-row {
  transition: opacity var(--johnbot-duration-slow) var(--johnbot-ease-out);
}

@starting-style {
  .trace-row {
    opacity: 0;
  }
}

/* A parent row stays under the rows above it while its own rows scroll. Its item ends with its last
 * row, so the next parent row takes its place. */
.trace-row[data-parent] {
  position: sticky;
  top: calc((var(--trace-depth) + 1) * var(--trace-row-height));
  z-index: 4;
  background: var(--trace-surface);
}

/* Five agent colours. The calls of an agent take its colour through `--trace-hue`. */
.trace-row[data-hue="1"],
.trace-handoff[data-hue="1"] {
  --trace-hue: var(--johnbot-chart-storage-downloads);
}

.trace-row[data-hue="2"],
.trace-handoff[data-hue="2"] {
  --trace-hue: var(--johnbot-chart-storage-files);
}

.trace-row[data-hue="3"],
.trace-handoff[data-hue="3"] {
  --trace-hue: var(--johnbot-chart-storage-chats);
}

.trace-row[data-hue="4"],
.trace-handoff[data-hue="4"] {
  --trace-hue: var(--johnbot-chart-storage-workspaces);
}

.trace-row[data-hue="5"],
.trace-handoff[data-hue="5"] {
  --trace-hue: var(--johnbot-chart-storage-runtimes);
}

.trace-name {
  position: sticky;
  left: 0;
  z-index: 3;
  display: flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-1-5);
  --trace-indent: var(--johnbot-space-4);
  --trace-guide-at: calc(var(--johnbot-control-xs) / 2);
  padding-inline: calc(var(--johnbot-space-2) + var(--trace-depth, 0) * var(--trace-indent)) var(--johnbot-space-2);
  border-right: 1px solid var(--johnbot-border);
  /* The tint of a row under the pointer, then one guide line for each tree level above the row,
   * under the chevron of that level. */
  background:
    linear-gradient(var(--trace-row-tint), var(--trace-row-tint)),
    repeating-linear-gradient(
      to right,
      transparent 0 var(--trace-guide-at),
      var(--johnbot-border) var(--trace-guide-at) calc(var(--trace-guide-at) + 1px),
      transparent calc(var(--trace-guide-at) + 1px) var(--trace-indent)
    )
    var(--johnbot-space-2) 0 / calc(var(--trace-depth, 0) * var(--trace-indent)) 100% no-repeat,
    var(--trace-surface);
}

/* The row under the pointer or the keyboard lights up, and so does the piece of its parent's lane
 * that stands for it. A piece under the pointer lights up its row. */
.trace-row {
  --trace-row-tint: transparent;
}

.trace-row[data-hovered],
.trace-row:has(.trace-name-button:focus-visible) {
  --trace-row-tint: var(--johnbot-hover);
}

.trace-row[data-hovered] .trace-bar:not(.trace-segment),
.trace-segment[data-hovered] {
  outline: 1px solid var(--johnbot-text-secondary);
  outline-offset: 1px;
}

/* The name of a row is its keyboard stop, and a click on it shows the step in the chat. */
.trace-name .trace-name-button.ui-button {
  height: auto;
  min-width: 0;
  flex: 1 1 auto;
  justify-content: flex-start;
  gap: var(--johnbot-space-1-5);
  padding: 0;
  border-radius: var(--johnbot-radius-xs);
  background: transparent;
  color: inherit;
  font-size: inherit;
  font-weight: inherit;
  text-align: start;
  cursor: default;
}

.trace-row[data-selectable] .trace-name-button.ui-button {
  cursor: pointer;
}

/* The row's tint shows the keyboard stop, so the name gets a thin neutral ring and no halo. */
.trace-name .trace-name-button.ui-button:focus-visible {
  box-shadow: none;
  outline: 1px solid var(--johnbot-text-muted);
  outline-offset: 1px;
}

.trace-axis-row {
  position: sticky;
  top: 0;
  z-index: 4;
  background: var(--trace-surface);
}

.trace-axis-name {
  color: var(--johnbot-text-muted);
}

/* An open row is not a lit toggle, so the chevron has no fill. */
.trace-name .trace-toggle[aria-expanded="true"]:not(:hover) {
  background: transparent;
}

.trace-toggle-icon {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  transition: rotate var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.trace-toggle[aria-expanded="false"] .trace-toggle-icon {
  rotate: -90deg;
}

.trace-toggle-space {
  width: var(--johnbot-control-xs);
  flex: 0 0 auto;
}

.trace-icon {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  flex: 0 0 auto;
  color: var(--johnbot-text-muted);
}

/* The icon of a row sits on a quiet tile. An agent's icon has the agent's colour. */
.trace-glyph {
  display: grid;
  width: 22px;
  height: 22px;
  box-sizing: border-box;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-sm);
  background: color-mix(in srgb, var(--johnbot-text-primary) 4%, var(--trace-surface));
  color: var(--johnbot-text-secondary);
}

.trace-glyph[data-agent] {
  color: var(--trace-hue);
}

.trace-row:not([data-hue]) .trace-glyph[data-agent] {
  color: var(--johnbot-text-primary);
}

.trace-glyph[data-failed] {
  color: var(--johnbot-danger-text);
}

.trace-glyph-icon {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
}

.trace-spinner {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  flex: 0 0 auto;
  color: var(--johnbot-text-muted);
  animation: ui-spin 1s linear infinite;
}

.trace-span-name {
  min-width: 0;
  flex: 0 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.trace-row[data-parent] .trace-span-name {
  font-weight: var(--johnbot-weight-semibold);
}

.trace-row[data-failed] .trace-span-name {
  color: var(--johnbot-danger-text);
}

/* A light moves along the name of a running step. It repaints the text on each frame, so only the
 * few running rows have it. */
.trace-row[data-running] .trace-span-name {
  background:
    linear-gradient(
      90deg,
      var(--johnbot-text-muted) 0%,
      var(--johnbot-text-muted) 35%,
      var(--johnbot-text-primary) 50%,
      var(--johnbot-text-muted) 65%,
      var(--johnbot-text-muted) 100%
    )
    0 0 / 300% 100%;
  background-clip: text;
  color: transparent;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: trace-shine 2s linear infinite;
}

@keyframes trace-shine {
  from {
    background-position: 100% 0;
  }

  to {
    background-position: 0 0;
  }
}

.trace-span-detail {
  /* The detail takes only the room after the name, so the name stays readable. */
  flex: 1 1 0;
  min-width: 0;
  overflow: hidden;
  color: var(--johnbot-text-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The timeline of a row. Each time sits at `--trace-at`, from 0 to 1, between the left pad and the
 * label room. The overlay of grid lines uses the same scale. */
.trace-lane {
  --trace-scale: calc(100% - var(--trace-lane-pad) - var(--trace-label-room));
  position: relative;
  z-index: 1;
  min-width: 0;
}

.trace-row[data-hovered] .trace-lane {
  background: var(--trace-row-tint);
}

.trace-overlay {
  --trace-scale: calc(100% - var(--trace-lane-pad) - var(--trace-label-room));
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: var(--trace-name-width);
  pointer-events: none;
}

.trace-tick,
.trace-gridline,
.trace-now,
.trace-now-dot,
.trace-bar,
.trace-handoff,
.trace-bar-label {
  position: absolute;
  left: calc(var(--trace-lane-pad) + var(--trace-scale) * var(--trace-at));
}

.trace-tick {
  top: 50%;
  padding-left: var(--johnbot-space-1);
  color: var(--johnbot-text-muted);
  font-variant-numeric: tabular-nums;
  translate: 0 -50%;
  white-space: nowrap;
}

.trace-gridline,
.trace-now {
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--johnbot-border);
}

.trace-now {
  z-index: 2;
  background: var(--johnbot-text-dim);
}

.trace-now-dot {
  bottom: 0;
  width: 7px;
  height: 7px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-text-primary);
  translate: -3px 50%;
}

/* A new bar grows from its start. A replay moves bars on each frame, so their position has no
 * transition. */
.trace-bar {
  transform-origin: left center;
  transition: scale var(--johnbot-duration-overlay) var(--johnbot-ease-out);
}

@starting-style {
  .trace-bar {
    scale: 0 1;
  }
}

.trace-bar {
  top: 50%;
  display: grid;
  width: max(3px, calc(var(--trace-scale) * var(--trace-width)));
  height: var(--trace-bar-height);
  box-sizing: border-box;
  place-items: center;
  overflow: hidden;
  border-radius: var(--johnbot-radius-xs);
  translate: 0 -50%;
}

/* A model call has the full agent colour and a tool call a dim one. */
.trace-bar[data-kind="model"],
.trace-swatch[data-kind="model"] {
  background-color: var(--trace-hue);
}

.trace-bar[data-kind="tool"],
.trace-swatch[data-kind="tool"] {
  background-color: color-mix(in srgb, var(--trace-hue) 45%, var(--trace-surface));
}

.trace-bar[data-kind="waiting"],
.trace-swatch[data-kind="waiting"] {
  border: 1px solid color-mix(in srgb, var(--trace-hue) 60%, transparent);
  background: repeating-linear-gradient(
    -45deg,
    color-mix(in srgb, var(--trace-hue) 60%, transparent) 0 1px,
    transparent 1px 5px
  );
}

.trace-bar[data-kind="handoff"] {
  border: 1px solid var(--trace-hue);
  background-color: transparent;
}

.trace-bar[data-failed],
.trace-swatch[data-failed] {
  border: 0;
  background: var(--johnbot-danger);
}

.trace-bar.trace-track {
  border: 0;
  background: color-mix(in srgb, var(--trace-hue) 16%, transparent);
}

/* A light moves along a bar that still runs. */
.trace-bar[data-running]:not([data-kind="waiting"]) {
  background-image: linear-gradient(
    90deg,
    transparent 0%,
    color-mix(in srgb, var(--johnbot-text-primary) 35%, transparent) 50%,
    transparent 100%
  );
  background-repeat: no-repeat;
  background-size: 50% 100%;
  animation: trace-bar-shine 1.6s linear infinite;
}

@keyframes trace-bar-shine {
  from {
    background-position: -100% 0;
  }

  to {
    background-position: 200% 0;
  }
}

.trace-bar-icon {
  width: 12px;
  height: 12px;
  color: var(--johnbot-text-on-accent);
}

/* The line from a parent row down to its subagents' bars. It starts under the parent's lane and ends
 * at the top of the last subagent's row. A line has the colour of the agent that hands off, so the
 * rows that draw parts of it do not give it their own colour. */
.trace-handoff {
  --trace-elbow: var(--johnbot-space-2);
  top: calc((var(--trace-from) + 1.5) * var(--trace-row-height) + var(--trace-bar-height) / 2);
  width: var(--trace-elbow);
  height: calc((var(--trace-to) - var(--trace-from) - 0.5) * var(--trace-row-height) - var(--trace-bar-height) / 2);
  box-sizing: border-box;
  border-left: 2px dotted var(--trace-hue);
  translate: calc(-1 * var(--trace-elbow)) 0;
  /* The rows slide when a parent folds, so the line follows them at the same pace. */
  transition:
    top var(--johnbot-duration-slow) var(--johnbot-ease-out),
    height var(--johnbot-duration-slow) var(--johnbot-ease-out);
}

.trace-handoff:not([data-hue]) {
  --trace-hue: var(--johnbot-text-muted);
}

/* The branch into a subagent's bar. The line goes on past it to the next subagent, and turns into the
 * bar of the last one. */
.trace-handoff.trace-handoff-end {
  top: 0;
  height: 50%;
  border-bottom: 2px dotted var(--trace-hue);
  border-left: 0;
}

.trace-handoff.trace-handoff-end[data-last] {
  border-left: 2px dotted var(--trace-hue);
  border-bottom-left-radius: var(--johnbot-radius-xs);
}

/* A parent row is opaque while it stays at the top, so it draws the part of a line that passes it. */
.trace-handoff.trace-handoff-pass {
  top: 0;
  height: 100%;
}

.trace-bar-label {
  top: 50%;
  display: inline-flex;
  align-items: center;
  gap: var(--johnbot-space-1-5);
  padding-left: var(--johnbot-space-1-5);
  color: var(--johnbot-text-muted);
  font-variant-numeric: tabular-nums;
  translate: 0 -50%;
  white-space: nowrap;
}

.trace-empty {
  display: grid;
  gap: var(--johnbot-space-1);
  padding: var(--johnbot-space-8) var(--johnbot-space-4);
  text-align: center;
}

.trace-empty-title,
.trace-empty-description {
  margin: 0;
}

.trace-empty-title {
  font-weight: var(--johnbot-weight-medium);
}

.trace-empty-description {
  color: var(--johnbot-text-muted);
}

.trace-footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-2) var(--johnbot-space-4);
  padding: var(--johnbot-space-2) var(--johnbot-space-2) var(--johnbot-space-2) var(--johnbot-space-4);
  border-top: 1px solid var(--johnbot-border);
}

/* Each key is a small bar in the shape of the bars above it. The top agent's neutral colour is too dim here,
 * so the keys use the secondary text colour. */
.trace-legend {
  --trace-hue: var(--johnbot-text-secondary);
  display: flex;
  flex-wrap: wrap;
  gap: var(--johnbot-space-1) var(--johnbot-space-4);
  margin: 0;
  padding: 0;
  color: var(--johnbot-text-muted);
  list-style: none;
}

.trace-legend-item {
  display: inline-flex;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.trace-swatch {
  width: 16px;
  height: 8px;
  flex: none;
  box-sizing: border-box;
  border-radius: var(--johnbot-radius-xs);
}

/* The handoff key is a piece of the dotted line that goes down to a subagent. */
.trace-swatch[data-kind="handoff"] {
  height: 2px;
  border-top: 2px dotted var(--trace-hue);
  border-radius: 0;
}

.trace-replay {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-1);
}

.trace-replay .trace-play {
  border-radius: var(--johnbot-radius-pill);
}

.trace-replay .trace-select {
  margin-left: var(--johnbot-space-1);
}

.ui-dialog-content.trace-dialog {
  width: min(1040px, 100%);
  max-height: min(680px, calc(100dvh - 2 * var(--johnbot-space-6)));
  display: flex;
  overflow: hidden;
  outline: 0;
  background: var(--johnbot-bg-surface);
}

.trace.trace-in-dialog {
  border: 0;
  border-radius: 0;
}

@media (prefers-reduced-motion: reduce) {
  .trace-branch-children,
  .trace-branch-clip,
  .trace-row,
  .trace-bar,
  .trace-handoff {
    transition: none;
  }

  .trace-spinner,
  .trace-row[data-running] .trace-span-name,
  .trace-bar[data-running] {
    animation: none;
  }

  .trace-toggle-icon {
    transition: none;
  }
}

/* agent-chat-empty.css */
/* A direct chat before its first message: the agent, its line, and a faint sample turn below.
   It fills the scroll area and no more, so the chat cannot open scrolled past the title: on a
   short window, the turn row gets only the height that is left. */
.agent-chat-empty {
  box-sizing: border-box;
  height: 100%;
  display: grid;
  grid-auto-rows: auto minmax(0, 21rem);
  align-content: center;
  justify-items: center;
  gap: var(--johnbot-space-6);
  padding: var(--johnbot-space-6) 0;
  container-type: inline-size;
}

.agent-chat-empty-pitch {
  --agent-chat-empty-title-size: var(--johnbot-text-display);
  --agent-chat-empty-hand-size: calc(var(--agent-chat-empty-title-size) * 1.2);
  display: grid;
  justify-items: center;
  gap: var(--johnbot-space-2);
  text-align: center;
}

.agent-chat-empty-avatar.agent-avatar {
  width: calc(var(--johnbot-control-xl) * 1.6);
  height: calc(var(--johnbot-control-xl) * 1.6);
  margin-bottom: var(--johnbot-space-2);
}

.agent-chat-empty-title {
  margin: 0;
  font-size: var(--agent-chat-empty-title-size);
  font-weight: var(--johnbot-weight-semibold);
  letter-spacing: -0.01em;
  line-height: 1.2;
}

.agent-chat-empty-title > span {
  display: block;
}

.agent-chat-empty-ready,
.agent-chat-empty-description {
  color: var(--johnbot-text-muted);
}

.agent-chat-empty-description {
  max-width: 30rem;
  margin: 0;
  font-size: var(--johnbot-text-xl);
  line-height: 1.5;
  text-wrap: balance;
}

/* The one handwritten word. It writes itself once, from left to right. The brand has no hand
   font, so the system ones stand in. */
.agent-chat-empty-hand {
  display: inline-block;
  color: var(--johnbot-accent-text);
  font-family: "Bradley Hand", "Noteworthy", "Segoe Print", cursive;
  font-size: var(--agent-chat-empty-hand-size);
  line-height: 1;
  transform: rotate(-2deg);
  clip-path: inset(-0.4em 100% -0.4em -0.2em);
  animation: agent-chat-empty-write calc(var(--johnbot-duration-slow) * 2.8) linear
    calc(var(--johnbot-duration-slow) * 2.5) forwards;
}

@keyframes agent-chat-empty-write {
  to {
    clip-path: inset(-0.4em -0.2em -0.4em -0.2em);
  }
}

/* The faint turn, in a column of chat width. Its rows are the chat's own. */
.agent-chat-empty-turn {
  width: min(100%, 40rem);
  min-height: 0;
  overflow: hidden;
  opacity: 0.5;
  pointer-events: none;
  user-select: none;
  mask-image: radial-gradient(ellipse 70% 90% at 50% 20%, var(--johnbot-text-primary) 45%, var(--johnbot-transparent));
}

.agent-chat-empty-row {
  padding-top: var(--johnbot-chat-entry-gap);
}

.agent-chat-empty-showing {
  transition:
    opacity calc(var(--johnbot-duration-slow) * 3.5) var(--johnbot-ease-out),
    filter calc(var(--johnbot-duration-slow) * 3.5) var(--johnbot-ease-out),
    transform calc(var(--johnbot-duration-slow) * 3.5) var(--johnbot-ease-out);
}

.agent-chat-empty-showing[data-leaving] {
  opacity: 0;
  filter: blur(3px);
  transform: translateY(-6px);
}

@container (max-width: 520px) {
  .agent-chat-empty-pitch {
    --agent-chat-empty-title-size: var(--johnbot-text-3xl);
  }

  .agent-chat-empty-description {
    font-size: var(--johnbot-text-lg);
  }
}

.agent-chat-empty[data-still] .agent-chat-empty-hand {
  animation: none;
  clip-path: none;
}

/* message-content.css */
.message-entry-user .ui-bubble {
  max-width: min(420px, 100%);
}

/* A table needs the width of an agent table. The bubble still fits a short table. */
.message-entry-user .ui-bubble:has(.message-markdown-table-scroll) {
  max-width: min(720px, 100%);
}

.message-copy {
  margin: 0;
  font-size: var(--johnbot-text-lg);
  line-height: 20px;
  overflow-wrap: anywhere;
  white-space: pre-line;
  user-select: text;
}

.message-markdown {
  white-space: normal;
}

.message-markdown > *,
.message-markdown :is(p, ul, ol, blockquote) {
  margin: 0;
}

.message-markdown > :not(:first-child) {
  margin-top: var(--johnbot-space-3);
}

.message-markdown-heading {
  margin: 0;
  color: inherit;
  font-weight: var(--johnbot-weight-semibold);
  letter-spacing: var(--johnbot-tracking-tight);
}

.message-markdown-heading[data-level="1"] {
  font-size: var(--johnbot-text-2xl);
  line-height: var(--johnbot-leading-2xl);
}

.message-markdown-heading[data-level="2"] {
  font-size: var(--johnbot-text-xl);
  line-height: var(--johnbot-leading-xl);
}

.message-markdown-heading:is([data-level="3"], [data-level="4"], [data-level="5"], [data-level="6"]) {
  font-size: var(--johnbot-text-lg);
  line-height: var(--johnbot-leading-lg);
}

.message-markdown strong {
  font-weight: var(--johnbot-weight-semibold);
}

.message-markdown del {
  color: var(--johnbot-text-secondary);
}

.message-markdown :is(ul, ol) {
  padding-left: var(--johnbot-space-6);
}

.message-markdown ul {
  list-style: disc;
}

.message-markdown ul ul {
  list-style: circle;
}

.message-markdown ol {
  list-style: decimal;
}

.message-markdown li + li,
.message-markdown li > :is(ul, ol) {
  margin-top: var(--johnbot-space-1);
}

.message-markdown-task {
  display: flex;
  align-items: flex-start;
  gap: var(--johnbot-space-1-5);
  list-style: none;
}

.message-markdown-checkbox {
  margin-top: var(--johnbot-space-1);
  opacity: 1;
}

.message-markdown blockquote {
  border-left: var(--johnbot-space-0-5) solid var(--johnbot-border-strong);
  padding-left: var(--johnbot-space-3);
  color: var(--johnbot-text-secondary);
}

.message-markdown blockquote > :not(:first-child) {
  margin-top: var(--johnbot-space-2);
}

.message-markdown :not(pre) > code {
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-xs);
  background: var(--johnbot-bg-control);
  padding: var(--johnbot-space-0-5) var(--johnbot-space-1);
  color: var(--johnbot-text-primary);
  font-family: var(--johnbot-font-mono);
  font-size: var(--johnbot-text-md);
  white-space: break-spaces;
}

.message-markdown hr {
  height: 1px;
  border: 0;
  background: var(--johnbot-border-strong);
}

.message-markdown-raw-html {
  display: block;
  color: var(--johnbot-text-secondary);
  font-family: var(--johnbot-font-mono);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-md);
  white-space: pre-wrap;
}

.message-markdown-image {
  display: block;
  width: auto;
  max-width: 100%;
  max-height: 360px;
  border-radius: var(--johnbot-radius-md);
  object-fit: contain;
}

/* The image opens in the image viewer. The button keeps the image's own size. */
.message-markdown-image-button {
  display: block;
  width: auto;
  max-width: 100%;
  height: auto;
  padding: 0;
  border-radius: var(--johnbot-radius-md);
  cursor: zoom-in;
}

.message-markdown-image-button:focus-visible {
  outline: 2px solid var(--johnbot-border-focus);
  outline-offset: 2px;
}

.message-markdown-table-scroll {
  width: 100%;
  min-width: 0;
  overflow-x: auto;
  border-radius: var(--johnbot-radius-md);
  box-shadow: 0 0 0 1px var(--johnbot-data-table-ring);
}

/* Each column keeps the data table minimum, so a narrow message scrolls sideways and does not
   break words. */
.message-markdown-table {
  width: 100%;
  min-width: calc(var(--message-markdown-table-columns) * 112px);
  border-collapse: collapse;
  background: var(--johnbot-bg-canvas);
  color: var(--johnbot-data-table-text);
}

.message-markdown-table :is(th, td) {
  border-right: 1px solid var(--johnbot-data-table-border);
  border-bottom: 1px solid var(--johnbot-data-table-border);
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
  overflow-wrap: break-word;
  text-align: left;
  vertical-align: top;
}

.message-markdown-table th {
  background: var(--johnbot-bg-surface-raised);
  color: var(--johnbot-data-table-header-text);
  font-weight: var(--johnbot-weight-medium);
}

.message-markdown-table :is(th, td):last-child {
  border-right: 0;
}

.message-markdown-table tbody tr:last-child td {
  border-bottom: 0;
}

.message-markdown-table [data-align="center"] {
  text-align: center;
}

.message-markdown-table [data-align="right"] {
  text-align: right;
}

::highlight(johnbot-message-selection) {
  background: var(--johnbot-accent-strong);
  color: inherit;
}

/* The passage that a quote points to, after a click on the quote. */
::highlight(johnbot-quote-target) {
  background: var(--johnbot-warning);
  color: var(--johnbot-paper-text);
}

.selection-highlight-layer {
  position: fixed;
  z-index: 18;
  inset: 0;
  pointer-events: none;
}

.selection-highlight-layer span {
  position: fixed;
  border-radius: var(--johnbot-radius-xs);
  background: var(--johnbot-accent-strong);
}

.selection-actions-layer {
  position: fixed;
  z-index: 25;
  opacity: 0;
  pointer-events: none;
  transform: translateY(4px) scale(0.97);
  transform-origin: 50% 0;
  transition:
    opacity var(--johnbot-duration-slow) ease-out,
    transform var(--johnbot-duration-overlay) cubic-bezier(0.23, 1, 0.32, 1);
  will-change: top, left, transform;
}

.selection-actions-layer[data-placement="top"] {
  transform-origin: 50% 100%;
}

.selection-actions-layer[data-ready="true"] {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0) scale(1);
}

.selection-actions-bar {
  display: flex;
  max-width: calc(100vw - 24px);
  height: 36px;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-surface-raised);
  padding: 4px;
  box-shadow:
    0 14px 34px var(--johnbot-shadow-popover-ambient),
    0 3px 10px var(--johnbot-shadow-popover-ambient),
    inset 0 0 0 1px var(--johnbot-shadow-ring);
  color: var(--johnbot-text-primary);
  transition: width var(--johnbot-duration-overlay) cubic-bezier(0.23, 1, 0.32, 1);
}

.selection-actions-content,
.selection-actions-presets,
.selection-actions-more-presets {
  display: flex;
  width: max-content;
  min-width: 0;
  align-items: center;
}

.selection-actions-content {
  height: 28px;
  flex: 0 0 auto;
  gap: 2px;
}

.selection-actions-form-shell {
  display: flex;
  min-width: 0;
  align-items: center;
  overflow: hidden;
  opacity: 1;
  transform: translateX(0);
  transition:
    max-width var(--johnbot-duration-overlay) cubic-bezier(0.23, 1, 0.32, 1),
    opacity var(--johnbot-duration-overlay) cubic-bezier(0.23, 1, 0.32, 1),
    transform var(--johnbot-duration-overlay) cubic-bezier(0.23, 1, 0.32, 1);
}

.selection-actions-form-shell-hidden {
  opacity: 0;
  pointer-events: none;
  transform: translateX(-8px);
}

.selection-actions-form {
  display: flex;
  height: 28px;
  flex: 0 0 auto;
  align-items: center;
  overflow: hidden;
  transition: width var(--johnbot-duration-overlay) cubic-bezier(0.23, 1, 0.32, 1);
}

.selection-actions-form input {
  width: 100%;
  height: 28px;
  border: 0;
  background: transparent;
  padding: 0 10px 0 11px;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  font-weight: 400;
  line-height: 28px;
  outline: 0;
}

.selection-actions-form input::placeholder {
  color: var(--johnbot-text-muted);
}

.selection-actions-form input:focus-visible {
  outline: 0;
}

.selection-actions-presets {
  max-width: 224px;
  gap: 2px;
  overflow: hidden;
  opacity: 1;
  transform: translateX(0);
  transition:
    max-width var(--johnbot-duration-overlay) cubic-bezier(0.23, 1, 0.32, 1),
    opacity var(--johnbot-duration-overlay) cubic-bezier(0.23, 1, 0.32, 1),
    transform var(--johnbot-duration-overlay) cubic-bezier(0.23, 1, 0.32, 1);
}

.selection-actions-presets-hidden {
  max-width: 0;
  opacity: 0;
  pointer-events: none;
  transform: translateX(-8px);
}

.selection-actions-more-presets {
  max-width: 0;
  gap: 2px;
  margin-left: 0;
  overflow: hidden;
  opacity: 0;
  transition:
    max-width var(--johnbot-duration-overlay) cubic-bezier(0.23, 1, 0.32, 1),
    opacity var(--johnbot-duration-overlay) cubic-bezier(0.23, 1, 0.32, 1),
    margin-left var(--johnbot-duration-overlay) cubic-bezier(0.23, 1, 0.32, 1);
}

.selection-actions-presets-expanded .selection-actions-more-presets {
  max-width: 262px;
  margin-left: 2px;
  opacity: 1;
}

.selection-actions-send-shell {
  display: flex;
  min-width: 0;
  max-width: 0;
  align-items: center;
  overflow: hidden;
  opacity: 0;
  transform: scale(0.88);
  transition:
    max-width var(--johnbot-duration-overlay) cubic-bezier(0.23, 1, 0.32, 1),
    opacity var(--johnbot-duration-overlay) cubic-bezier(0.23, 1, 0.32, 1),
    transform var(--johnbot-duration-overlay) cubic-bezier(0.23, 1, 0.32, 1);
}

.selection-actions-send-shell-visible {
  max-width: 30px;
  opacity: 1;
  transform: scale(1);
}

.selection-actions-control,
.selection-actions-icon-button,
.selection-actions-send {
  display: inline-flex;
  height: 28px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: var(--johnbot-radius-pill);
  padding: 0;
  transition:
    background-color var(--johnbot-duration-hover) ease,
    border-color var(--johnbot-duration-hover) ease,
    box-shadow var(--johnbot-duration-hover) ease,
    color var(--johnbot-duration-hover) ease,
    opacity var(--johnbot-duration-hover) ease,
    transform var(--johnbot-duration-normal) ease;
}

.selection-actions-control {
  gap: 4px;
  border: 1px solid transparent;
  background: transparent;
  padding: 0 9px;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  font-weight: 430;
  white-space: nowrap;
}

.selection-actions-icon-button,
.selection-actions-send {
  width: 28px;
}

.selection-actions-icon-button {
  background: transparent;
  color: var(--johnbot-text-secondary);
}

.selection-actions-send {
  background: var(--johnbot-text-primary);
  color: var(--johnbot-bg-canvas);
}

.selection-actions-control:active,
.selection-actions-icon-button:active,
.selection-actions-send:active {
  transform: scale(0.94);
}

.selection-actions-divider {
  width: 1px;
  height: 16px;
  flex: 0 0 auto;
  margin: 0 3px;
  background: var(--johnbot-border-strong);
}

.selection-actions-more-divider {
  margin-left: 1px;
}

.selection-actions-expand svg {
  transition: transform var(--johnbot-duration-overlay) cubic-bezier(0.23, 1, 0.32, 1);
}

.selection-actions-expand[aria-expanded="true"] svg {
  transform: rotate(180deg);
}

.selection-actions-icon {
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.selection-actions-status,
.selection-actions-error {
  display: inline-flex;
  height: 28px;
  align-items: center;
  gap: 7px;
  padding: 0 10px;
  font-size: var(--johnbot-text-sm);
  white-space: nowrap;
}

.selection-actions-status {
  color: var(--johnbot-text-secondary);
}

.selection-actions-error {
  color: var(--johnbot-danger);
}

.selection-actions-spinner {
  width: 12px;
  height: 12px;
  border: 1.5px solid var(--johnbot-border-strong);
  border-top-color: var(--johnbot-text-secondary);
  border-radius: var(--johnbot-radius-pill);
  animation: selection-actions-spin 700ms linear infinite;
}

.message-selection-quote {
  max-width: 100%;
  max-height: 124px;
  overflow: auto;
  margin: 0;
  border-left: 2px solid var(--johnbot-accent);
  border-radius: 0 var(--johnbot-radius-sm) var(--johnbot-radius-sm) 0;
  background: var(--johnbot-bg-control);
  padding: 6px 8px;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  line-height: 17px;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

@media (hover: hover) and (pointer: fine) {
  .selection-actions-control:hover {
    border-color: var(--johnbot-border-focus);
    background: var(--johnbot-accent-strong);
    box-shadow: 0 0 0 1px var(--johnbot-accent-soft);
    color: var(--johnbot-text-primary);
  }

  .selection-actions-icon-button:hover {
    background: var(--johnbot-bg-control-hover);
    color: var(--johnbot-text-primary);
  }

  .selection-actions-send:hover {
    opacity: 0.9;
  }
}

@media (max-width: 480px) {
  .selection-actions-control {
    width: 28px;
    padding: 0;
  }

  .selection-actions-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    white-space: nowrap;
  }

  .selection-actions-presets-expanded .selection-actions-more-presets {
    max-width: 88px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .selection-actions-layer,
  .selection-actions-bar,
  .selection-actions-form,
  .selection-actions-form-shell,
  .selection-actions-presets,
  .selection-actions-more-presets,
  .selection-actions-send-shell,
  .selection-actions-expand svg {
    transition: none;
  }

  .selection-actions-spinner {
    animation-duration: 1.4s;
  }
}

@keyframes selection-actions-spin {
  to {
    transform: rotate(360deg);
  }
}

/* One column as wide as the bubble. The implicit `auto` column grew to the content's min-content
   width, and a file chip's percentage cap does not count there, so a long path made the text run
   past the bubble and the chat ask for a column wider than the window. */
.message-content-blocks {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  min-width: 0;
  gap: 10px;
}

.message-content-resize {
  min-width: 0;
}

.message-content-resize[data-resizing="true"],
.agent-queue-panel-resize[data-resizing="true"] {
  overflow: hidden;
  will-change: height;
}

/* Opacity only: a blur filter on text repaints every fading word on each frame. */
.t-stream-w {
  animation: t-stream-in var(--stream-fade) var(--stream-ease) both;
}

@keyframes t-stream-in {
  from {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .t-stream-w {
    animation: none;
  }
}

.message-entry-agent .ui-bubble:has(:is(.message-data-table-scroll, .message-code-block)) {
  width: min(720px, 100%);
  max-width: min(720px, 100%);
}

.message-entry-agent .ui-bubble:has(.message-data-table-scroll) > .ui-bubble-content {
  width: 100%;
}

.message-entry-agent .message-shell:has(.message-data-table-scroll) {
  align-items: flex-end;
}

.message-code-block {
  width: 100%;
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-control);
}

.message-code-header {
  min-height: 34px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-2);
  border-bottom: 1px solid var(--johnbot-border);
  background: var(--johnbot-bg-control);
  padding: 4px 6px 4px 10px;
}

.message-code-heading {
  min-width: 0;
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.message-code-filename {
  overflow: hidden;
  color: var(--johnbot-text-primary);
  font-family: var(--johnbot-font-mono);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.message-code-language {
  flex: none;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-border);
  padding: 1px 6px;
  color: var(--johnbot-text-readable);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
  line-height: 16px;
}

.message-code-language:only-child {
  font-family: var(--johnbot-font-mono);
}

:where(.ui-button).message-code-copy {
  position: relative;
  height: 26px;
  flex: none;
  gap: var(--johnbot-space-1);
  border-radius: var(--johnbot-radius-sm);
  padding-inline: 7px;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: 16px;
}

@media (hover: hover) and (pointer: fine) {
  :where(.ui-button).message-code-copy:hover:not(:disabled) {
    background: var(--johnbot-bg-control-active);
    box-shadow: 0 0 0 1px var(--johnbot-border-strong);
    color: var(--johnbot-text-primary);
  }
}

:where(.ui-button).message-code-copy:active:not(:disabled) {
  transform: scale(0.96);
}

:where(.ui-button).message-code-copy::after {
  position: absolute;
  width: 40px;
  height: 40px;
  content: "";
}

.message-code-copy-icons {
  position: relative;
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  display: grid;
  place-items: center;
}

.message-code-copy-icons > span {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  opacity: 0;
  filter: blur(4px);
  scale: 0.25;
  transition:
    opacity var(--johnbot-duration-slow) var(--johnbot-ease-out),
    filter var(--johnbot-duration-slow) var(--johnbot-ease-out),
    scale var(--johnbot-duration-slow) var(--johnbot-ease-out);
}

.message-code-copy-icons > span[data-visible="true"] {
  opacity: 1;
  filter: blur(0);
  scale: 1;
}

.message-code-copy-icons svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  display: block;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: var(--johnbot-icon-stroke);
}

.message-code-scroll {
  width: 100%;
  max-height: 420px;
  overflow: auto;
  margin: 0;
  background: var(--johnbot-bg-sidebar);
  padding-block: 8px 10px;
  color: var(--johnbot-text-secondary);
  font-family: var(--johnbot-font-mono);
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
  line-height: 19px;
  /* Only the inline axis: Chromium stops a vertical wheel at a contained block even when the block
     cannot scroll, so the chat would not scroll under the pointer. */
  overscroll-behavior-x: contain;
  tab-size: 2;
}

.message-code-scroll:focus-visible {
  outline: 2px solid var(--johnbot-border-focus);
  outline-offset: -2px;
}

.message-code-scroll > code {
  min-width: 100%;
  width: max-content;
  display: block;
  font: inherit;
}

.message-code-line {
  min-height: 19px;
  display: flex;
}

.message-code-line-number {
  width: 40px;
  flex: none;
  padding-right: 8px;
  color: var(--johnbot-text-dim);
  font-size: var(--johnbot-text-sm);
  text-align: right;
  user-select: none;
}

.message-code-line-source {
  min-width: 0;
  padding-right: 12px;
  white-space: pre;
}

.message-code-caret {
  width: 2px;
  height: 13px;
  display: inline-block;
  margin-left: 2px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-accent);
  transform: translateY(2px);
}

[data-code-token="cmnt"] {
