    opacity var(--johnbot-duration-hover) ease,
    transform var(--johnbot-duration-hover) ease;
}

.message-citation-arrow svg {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
