}

[data-slot="bubble"][data-author="user"] .message-citation-mark:hover,
[data-slot="bubble"][data-author="user"] .message-citation-mark:focus-visible {
  background: var(--johnbot-accent-soft);
  color: var(--johnbot-accent);
}

[data-slot="bubble"][data-author="user"] .message-citation-footer {
  border-top-color: var(--johnbot-border-on-light);
}

[data-slot="bubble"][data-author="user"] .message-citation-ref-label {
  color: var(--johnbot-text-on-light);
}

[data-slot="bubble"][data-author="user"] .message-citation-ref-host {
  color: var(--johnbot-text-muted-on-light);
}

[data-slot="bubble"][data-author="user"] .message-citation-separator {
  color: var(--johnbot-text-dim-on-light);
}

.message-reply-context {
  max-width: 360px;
