}

.message-reply-quote .message-markdown-excerpt-code {
  font-family: var(--johnbot-font-mono);
  white-space: pre-wrap;
}

[data-slot="bubble"][data-author="user"] .message-reply-context {
  border-left-color: var(--johnbot-border-strong);
  color: var(--johnbot-text-readable);
