}
.channel-paused-task + .channel-paused-task {
  border-top: 1px solid var(--johnbot-accent-soft);
}
.channel-paused-task-reason {
  min-width: 0;
  flex: 1 1 24ch;
  margin: 0;
  overflow-wrap: anywhere;
  font-size: var(--johnbot-text-sm);
}
.channel-paused-task-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--johnbot-space-2);
  align-items: center;
}
.channel-paused-task-actions .ui-button {
  background: var(--johnbot-surface-light);
  color: var(--johnbot-text-on-light);
}
.channel-paused-task-actions .ui-button:hover {
  background: var(--johnbot-surface-light);
  box-shadow: 0 0 0 1px var(--johnbot-text-dim-on-light);
}

/* === from: @johnbot/ui/features/diagrams/diagrams.css === */
/* The diagram view: header, canvas, cards, edges, the assistant over the canvas and the run panel. */

.diagram-view {
  display: flex;
  height: 100%;
  min-width: 0;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  background: var(--johnbot-bg-canvas);
}

/* What the Routines view says instead of a canvas: it is loading, it failed, or the server is remote. */
.diagram-flows-notice {
  align-items: center;
  justify-content: center;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
}

/* The Bloub overflows its box. An auto grid track grows to the Bloub and starts at the box's top,
   and its percentage height then resolves against that track, so the Bloub grows taller than wide
   and sits low. One track the size of the box keeps every avatar here centred on its line. */
.diagram-view .agent-avatar {
  grid-template: 100% / 100%;
}

/* The same height, avatar and name as the agent chat header, so switching views keeps the bar. */
.diagram-view-header {
  display: flex;
  height: 38px;
  flex: none;
  align-items: center;
  gap: var(--johnbot-space-1-5);
  border-bottom: 1px solid var(--johnbot-border);
  padding: 0 var(--johnbot-space-3);
}

/* The chevron that closes routine details has no open fill: it is a close action, not a lit toggle. */
.diagram-view .diagram-view-header .header-panel-toggle[aria-expanded="true"]:not(:hover) {
  border-color: transparent;
  background: transparent;
  color: var(--johnbot-text-muted);
}

.diagram-view-icon {
  display: grid;
  width: 18px;
  height: 18px;
  flex: none;
  place-items: center;
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-accent-soft);
  color: var(--johnbot-accent-text);
}

.diagram-view-avatar.agent-avatar {
  width: 18px;
  height: 18px;
}

.diagram-view-icon svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
}

/* The name keeps its room; the routine picker beside it is the part that narrows. */
.diagram-view-title {
  max-width: 32ch;
  flex: none;
  overflow: hidden;
  margin: 0;
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-regular);
  line-height: 18px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.diagram-view-actions {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-1);
  margin-left: auto;
}

/* As with the chat's browser sidebar: the routine details panel appears at once at the right edge, and
   the canvas eases its padding to make room. */
.diagram-view-body {
  --diagram-inspector-width: 340px;

  position: relative;
  display: flex;
  min-height: 0;
  flex: 1;
  transition: padding-right var(--panel-resize-duration, var(--johnbot-duration-overlay)) cubic-bezier(0.22, 1, 0.36, 1);
}

.diagram-view-body[data-inspector="open"] {
  padding-right: var(--diagram-inspector-width);
}

/* The board, or the empty canvas, and the chat panel over it. The panel keeps to this box. */
.diagram-view-canvas {
  position: relative;
  display: flex;
  min-width: 0;
  flex: 1;
}

.diagram-view-chat {
  position: absolute;
  bottom: var(--johnbot-space-4);
  left: var(--johnbot-space-4);
  z-index: 2;
  width: min(360px, calc(100% - var(--johnbot-space-8)));
  /* The folded panel keeps its box, so the canvas under it still takes the pointer. */
  pointer-events: none;
}

/* Canvas */

.diagram-board {
  position: relative;
  min-width: 0;
  flex: 1;
  overflow: hidden;
}

.diagram-board-viewport {
  position: absolute;
  inset: 0;
  overflow: hidden;
  outline: 0;
  background-color: var(--johnbot-bg-canvas);
  background-image: radial-gradient(circle at 1px 1px, var(--johnbot-border-strong) 1px, transparent 0);
  background-position: var(--diagram-grid-x) var(--diagram-grid-y);
  background-size: var(--diagram-grid-size) var(--diagram-grid-size);
  cursor: grab;
  touch-action: none;
}

.diagram-board-viewport:focus-visible {
  box-shadow: inset var(--johnbot-focus-ring);
}

.diagram-board-viewport:is([data-panning], [data-dragging]) {
  cursor: grabbing;
}

.diagram-board-world {
  position: absolute;
  top: 0;
  left: 0;
  transform-origin: 0 0;
}

.diagram-board-world[data-settling] {
  transition: transform var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

/* The right-click menu's trigger wraps the viewport without a box of its own. */
.diagram-board-menu-area {
  display: contents;
}

.diagram-canvas-menu-avatar.agent-avatar {
  width: 20px;
  height: 20px;
  grid-template: 100% / 100%;
}

/* An agent row has a name and a title, so it gets more room than a one-line menu row. */
.ui-action-menu.diagram-canvas-agents:not([data-menu-layout="grid"]) [role="menuitem"] {
  height: auto;
  gap: var(--johnbot-space-3);
  padding-block: var(--johnbot-space-2);
}

.diagram-canvas-menu-agent {
  display: grid;
  min-width: 0;
  gap: var(--johnbot-space-0-5);
  line-height: var(--johnbot-leading-md);
}

.diagram-canvas-menu-agent small {
  overflow: hidden;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* A new agent, asked for at the spot the user right-clicked and kept inside the canvas. */
.diagram-new-agent {
  position: absolute;
  top: clamp(
    var(--johnbot-space-2),
    var(--diagram-new-agent-y),
    calc(100% - var(--diagram-new-agent-height, 188px) - var(--johnbot-space-2))
  );
  left: clamp(var(--johnbot-space-2), var(--diagram-new-agent-x), calc(100% - 288px));
  z-index: 3;
  display: grid;
  width: 280px;
  gap: var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-overlay);
  box-shadow:
    0 0 0 1px var(--johnbot-border),
    var(--johnbot-shadow-overlay);
  backdrop-filter: blur(16px);
  padding: var(--johnbot-space-3);
  font-size: var(--johnbot-text-sm);
}

.diagram-new-agent-header {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  font-weight: var(--johnbot-weight-medium);
  user-select: none;
}

.diagram-new-agent-avatar.agent-avatar {
  width: 24px;
  height: 24px;
  grid-template: 100% / 100%;
}

/* The model field, drawn as the inputs above it are: their height, edge and fill. */
.diagram-new-agent .provider-model-trigger-field {
  height: var(--johnbot-control-sm);
  min-height: var(--johnbot-control-sm);
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-control);
  box-shadow: none;
  padding-inline: var(--johnbot-space-2);
  font-size: var(--johnbot-text-sm);
}

.diagram-new-agent .provider-model-trigger-field:hover:not(:disabled),
.diagram-new-agent .provider-model-trigger-field[aria-expanded="true"] {
  border-color: var(--johnbot-border-strong);
  background: var(--johnbot-bg-control);
}

.diagram-new-agent .provider-model-trigger-field:focus-visible {
  border-color: var(--johnbot-border-focus);
  outline: none;
}

.diagram-new-agent-actions {
  display: flex;
  justify-content: flex-end;
  gap: var(--johnbot-space-1);
}

/* Zoom in, zoom out and fit, as a column of separate square buttons. */
.diagram-board-zoom {
  position: absolute;
  right: var(--johnbot-space-4);
  bottom: var(--johnbot-space-4);
  z-index: 2;
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-1-5);
}

.diagram-board-zoom .ui-button {
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-overlay);
  box-shadow: var(--johnbot-shadow-raised);
}

.diagram-board-zoom .ui-button svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  color: var(--johnbot-text-muted);
}

.diagram-board-zoom .ui-button:hover svg {
  color: var(--johnbot-text-primary);
}

/* Below the routine picker, which holds the top centre of the canvas. */
.diagram-board-status {
  position: absolute;
  top: calc(var(--johnbot-space-4) + var(--johnbot-control-sm) + var(--johnbot-space-2));
  left: 50%;
  z-index: 2;
  max-width: min(420px, calc(100% - 320px));
  margin: 0;
  translate: -50% 0;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-overlay);
  box-shadow: 0 0 0 1px var(--johnbot-border);
  padding: var(--johnbot-space-1-5) var(--johnbot-space-3);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-md);
  pointer-events: none;
  text-align: center;
}

.diagram-board-status:empty {
  display: none;
}

.diagram-board-status[data-tone="danger"] {
  box-shadow: 0 0 0 1px var(--johnbot-danger-border);
  color: var(--johnbot-danger-text);
}

/* Edges. The SVG has no size of its own: it draws outside its box, in canvas coordinates. */

.diagram-edges {
  position: absolute;
  top: 0;
  left: 0;
  width: 1px;
  height: 1px;
  overflow: visible;
  pointer-events: none;
}

.diagram-edge path,
.diagram-edge-draft {
  fill: none;
}

.diagram-edge-hit {
  stroke: transparent;
  stroke-width: 16px;
  pointer-events: stroke;
  cursor: pointer;
}

.diagram-edge-line {
  stroke: var(--johnbot-border-strong);
  stroke-width: 2px;
  stroke-linecap: round;
}

.diagram-edge[data-state="delivered"] .diagram-edge-line {
  stroke: var(--diagram-routine-color, var(--johnbot-accent));
}

.diagram-edge[data-state="running"] .diagram-edge-line {
  stroke: var(--diagram-routine-color, var(--johnbot-accent));
  stroke-dasharray: 6 6;
  animation: diagram-edge-flow 0.6s linear infinite;
}

/* A connection that belongs to one routine wears its colour, so its path reads as that routine's. */
.diagram-edge[data-routine-color][data-state="idle"] .diagram-edge-line {
  stroke: var(--diagram-routine-color);
  opacity: 0.6;
}

.diagram-edge:hover .diagram-edge-line,
.diagram-edge[data-selected] .diagram-edge-line {
  stroke: var(--johnbot-text-primary);
  stroke-width: 3px;
}

/* One arrow where a connection enters a card. Before a run it stays readable on the quiet line. */
.diagram-edge .diagram-edge-arrow {
  fill: var(--johnbot-text-muted);
}

.diagram-edge:is([data-state="delivered"], [data-state="running"]) .diagram-edge-arrow {
  fill: var(--diagram-routine-color, var(--johnbot-accent));
}

.diagram-edge:hover .diagram-edge-arrow,
.diagram-edge[data-selected] .diagram-edge-arrow {
  fill: var(--johnbot-text-primary);
}

.diagram-edge[data-state="dimmed"] .diagram-edge-arrow {
  opacity: 0.3;
}

.diagram-edge[data-routine-color][data-state="idle"] .diagram-edge-arrow {
  fill: var(--diagram-routine-color);
  opacity: 0.6;
}

.diagram-edge-draft {
  stroke: var(--johnbot-accent);
  stroke-width: 2px;
  stroke-dasharray: 6 6;
}

.diagram-edge-draft[data-target="invalid"] {
  stroke: var(--johnbot-danger);
}

.diagram-edge-remove.ui-button {
  position: absolute;
  top: var(--diagram-edge-y);
  left: var(--diagram-edge-x);
  z-index: 1;
  translate: -50% -50%;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-surface-raised);
  box-shadow: 0 0 0 1px var(--johnbot-border-strong);
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.diagram-edge-remove.ui-button:is([data-selected], :focus-visible) {
  opacity: 1;
  pointer-events: auto;
}

@keyframes diagram-edge-flow {
  to {
    stroke-dashoffset: -12;
  }
}

/* Cards */

.diagram-node {
  position: absolute;
  top: var(--diagram-node-y);
  left: var(--diagram-node-x);
  display: flex;
  width: var(--diagram-node-width);
  flex-direction: column;
  border-radius: var(--johnbot-radius-card);
  background: var(--johnbot-bg-surface-raised);
  box-shadow:
    0 0 0 1px var(--johnbot-border),
    var(--johnbot-shadow-raised);
  cursor: grab;
  transition:
    box-shadow var(--johnbot-duration-fast) var(--johnbot-ease-out),
    opacity var(--johnbot-duration-normal) var(--johnbot-ease-out);
  user-select: none;
}

.diagram-node[data-status="running"] {
  box-shadow:
    0 0 0 1px var(--johnbot-accent),
    0 0 0 5px var(--johnbot-accent-soft);
}

.diagram-node[data-status="failed"] {
  box-shadow:
    0 0 0 1px var(--johnbot-danger-border),
    var(--johnbot-shadow-raised);
}

.diagram-node[data-unreachable] {
  box-shadow: 0 0 0 1px var(--johnbot-warning);
}

.diagram-node[data-selected] {
  box-shadow:
    0 0 0 2px var(--johnbot-accent),
    var(--johnbot-shadow-raised);
}

.diagram-node-header {
  display: flex;
  height: 52px;
  align-items: center;
  gap: var(--johnbot-space-1);
  border-bottom: 1px solid var(--johnbot-border);
  padding: 0 var(--johnbot-space-2) 0 var(--johnbot-space-1);
}

.diagram-node-select.ui-button {
  height: 44px;
  min-width: 0;
  flex: 1;
  justify-content: flex-start;
  gap: var(--johnbot-space-2);
  padding: 0 var(--johnbot-space-1-5);
  background: transparent;
  cursor: inherit;
  text-align: left;
}

.diagram-node-avatar.agent-avatar {
  width: 28px;
  height: 28px;
}

.diagram-node-icon {
  display: grid;
  width: 28px;
  height: 28px;
  flex: none;
  place-items: center;
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-accent-soft);
  color: var(--johnbot-accent-text);
}

.diagram-node-icon svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.diagram-node-heading {
  display: grid;
  min-width: 0;
}

.diagram-node-kicker {
  overflow: hidden;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-regular);
  line-height: var(--johnbot-leading-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.diagram-node-name {
  overflow: hidden;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-semibold);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.diagram-node-body {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-2);
  padding: var(--johnbot-space-2) var(--johnbot-space-3) var(--johnbot-space-3);
}

.diagram-node-task,
.diagram-node-schedule {
  display: -webkit-box;
  overflow: hidden;
  margin: 0;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.diagram-node-schedule {
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
}

/* The output of the last run, inside the card, the way a generation shows its result. */
.diagram-node-preview {
  display: flex;
  min-height: 64px;
  align-items: flex-start;
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-control);
  padding: var(--johnbot-space-2);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.diagram-node-preview[data-empty] {
  align-items: center;
  justify-content: center;
}

.diagram-node-preview p {
  display: -webkit-box;
  overflow: hidden;
  margin: 0;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4;
  white-space: pre-line;
}

.diagram-node[data-status="failed"] .diagram-node-preview {
  background: var(--johnbot-danger-soft);
  color: var(--johnbot-danger-text);
}

.diagram-node-preview-empty {
  color: var(--johnbot-text-placeholder);
}

.diagram-node-footer {
  display: flex;
  min-height: 24px;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-2);
}

.diagram-node-status {
  display: inline-flex;
  align-items: center;
  gap: var(--johnbot-space-1);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

.diagram-node-status svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
}

:is(.diagram-node-status, .diagram-inspector-step-status)[data-status="succeeded"] {
  color: var(--johnbot-success-text);
}

:is(.diagram-node-status, .diagram-inspector-step-status)[data-status="failed"] {
  color: var(--johnbot-danger-text);
}

:is(.diagram-node-status, .diagram-inspector-step-status)[data-status="running"] {
  color: var(--johnbot-accent-text);
}

.diagram-node-status[data-status="unreachable"] {
  color: var(--johnbot-warning-text);
}

.diagram-node-duration {
  color: var(--johnbot-text-muted);
}

.diagram-node-duration::before {
  content: "·";
  margin-right: var(--johnbot-space-1);
}

.diagram-node-remove.ui-button,
/* Stays at the right edge also when the routine has no runs to show. */
.diagram-node-run.ui-button {
  flex: none;
  margin-inline-start: auto;
}

.diagram-node-run.ui-button svg,
.diagram-view-actions .ui-button-size-xs svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
}

/* Ports sit on the card's edge, level with the header. */
.diagram-port.ui-button {
  position: absolute;
  top: 19px;
  z-index: 1;
  width: 14px;
  min-width: 14px;
  height: 14px;
  border: 2px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-surface-raised);
  padding: 0;
  cursor: crosshair;
  transition:
    scale var(--johnbot-duration-fast) var(--johnbot-ease-out),
    border-color var(--johnbot-duration-fast) var(--johnbot-ease-out),
    background-color var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

/* A larger target than the dot it shows. */
.diagram-port.ui-button::before {
  position: absolute;
  inset: -8px;
  content: "";
}

.diagram-port-in.ui-button {
  left: -7px;
}

.diagram-port-out.ui-button {
  right: -7px;
}

.diagram-port.ui-button:hover,
.diagram-port-out.ui-button[data-connecting],
.diagram-port-in.ui-button[data-target="valid"] {
  scale: 1.25;
  border-color: var(--johnbot-accent);
  background: var(--johnbot-accent-soft);
}

.diagram-port-out.ui-button[data-connecting] {
  background: var(--johnbot-accent);
}

.diagram-port-in.ui-button[data-target="invalid"] {
  border-color: var(--johnbot-danger);
  opacity: 0.5;
}

.diagram-port.ui-button:disabled {
  opacity: 1;
  cursor: default;
}

/* Routine colours. A routine, the chips that name it on agent cards, and its path while it is in
   focus share one colour, so a run can be followed across the canvas. */
[data-routine-color="0"] {
  --diagram-routine-color: var(--johnbot-file-blue);
  --diagram-routine-soft: var(--johnbot-file-blue-soft);
}

[data-routine-color="1"] {
  --diagram-routine-color: var(--johnbot-file-green);
  --diagram-routine-soft: var(--johnbot-file-green-soft);
}

[data-routine-color="2"] {
  --diagram-routine-color: var(--johnbot-file-orange);
  --diagram-routine-soft: var(--johnbot-file-orange-soft);
}

[data-routine-color="3"] {
  --diagram-routine-color: var(--johnbot-file-pink);
  --diagram-routine-soft: var(--johnbot-file-pink-soft);
}

[data-routine-color="4"] {
  --diagram-routine-color: var(--johnbot-file-teal);
  --diagram-routine-soft: var(--johnbot-file-teal-soft);
}

[data-routine-color="5"] {
  --diagram-routine-color: var(--johnbot-file-yellow);
  --diagram-routine-soft: var(--johnbot-file-yellow-soft);
}

/* Outside the focused routine's path the canvas recedes, but stays readable and editable. */
.diagram-node[data-dimmed] {
  opacity: 0.4;
}

.diagram-node[data-dimmed]:is(:hover, :focus-within) {
  opacity: 0.8;
}

.diagram-edge[data-state="dimmed"] .diagram-edge-line {
  opacity: 0.3;
}

.diagram-node-routines {
  display: flex;
  flex-wrap: wrap;
  gap: var(--johnbot-space-1);
  margin: 0;
  padding: 0;
  list-style: none;
}

.diagram-routine-chip.ui-button {
  height: 22px;
  gap: var(--johnbot-space-1);
  border-radius: var(--johnbot-radius-pill);
  background: var(--diagram-routine-soft);
  padding: 0 var(--johnbot-space-2);
  color: var(--diagram-routine-color);
  font-size: var(--johnbot-text-sm);
}

.diagram-routine-chip.ui-button[aria-pressed="true"] {
  box-shadow: inset 0 0 0 1px var(--diagram-routine-color);
}

.diagram-routine-chip.ui-button svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
}

.diagram-routine-chip-name {
  max-width: 120px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The webhook of a routine in the details panel: the routine settings' card, and Save under it. */
.diagram-routine-webhook {
  display: grid;
  gap: var(--johnbot-space-2);
}

.diagram-routine-webhook-actions {
  display: flex;
  justify-content: flex-end;
}

/* The routine picker, at the top centre of the canvas. */
.diagram-view-lens-bar {
  position: absolute;
  top: var(--johnbot-space-4);
  left: 50%;
  z-index: 2;
  translate: -50% 0;
}

.diagram-view-lens-bar .ui-select-trigger {
  background: var(--johnbot-bg-overlay);
  box-shadow: var(--johnbot-shadow-raised);
}

.diagram-view-lens-trigger.ui-select-trigger {
  min-width: 120px;
  max-width: 280px;
}

.diagram-view-lens-option {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.diagram-view-lens-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.diagram-view-lens-option svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  flex: none;
}

/* "All routines" has no colour of its own: its dot is an outline. */
.diagram-view-lens-dot[data-all] {
  background: transparent;
  box-shadow: inset 0 0 0 1.5px var(--johnbot-text-muted);
}

.diagram-view-lens-dot,
.diagram-inspector-routine-dot {
  width: 8px;
  height: 8px;
  flex: none;
  border-radius: var(--johnbot-radius-pill);
  background: var(--diagram-routine-color);
}

.diagram-inspector-routine.ui-button[aria-pressed="true"] {
  background: var(--diagram-routine-soft);
}

/* Routine: what it asks, when it fires, how it went */

/* The routine glows while the run it started is in progress. */
.diagram-node[data-kind="routine"][data-firing] {
  box-shadow:
    0 0 0 1px var(--diagram-routine-color),
    0 0 0 5px var(--diagram-routine-soft);
}

.diagram-node[data-kind="routine"] .diagram-node-icon {
  background: var(--diagram-routine-soft);
  color: var(--diagram-routine-color);
}

.diagram-node[data-kind="routine"][data-firing] .diagram-node-icon {
  animation: diagram-routine-fire 1.2s var(--johnbot-ease-in-out) infinite;
}

.diagram-routine-instruction {
  display: -webkit-box;
  overflow: hidden;
  margin: 0;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  border-left: 2px solid var(--diagram-routine-color, var(--johnbot-accent));
  padding-left: var(--johnbot-space-2);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.diagram-routine-week {
  --diagram-week-height: 40px;
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: var(--johnbot-space-1);
}

.diagram-routine-week[data-size="panel"] {
  --diagram-week-height: 72px;
}

.diagram-routine-day {
  display: grid;
  justify-items: center;
  gap: var(--johnbot-space-1);
}

/* One day, midnight at the top: a tick sits at the time the routine fires. */
.diagram-routine-day-track {
  position: relative;
  width: 100%;
  height: var(--diagram-week-height);
  border-radius: var(--johnbot-radius-sm);
  background: var(--johnbot-bg-control);
}

.diagram-routine-day[data-weekend] .diagram-routine-day-track {
  background: var(--johnbot-bg-control-hover);
}

.diagram-routine-day[data-today] .diagram-routine-day-track {
  box-shadow: inset 0 0 0 1px var(--johnbot-accent);
}

/* Noon, so a morning run reads as morning. */
.diagram-routine-day-track::after {
  position: absolute;
  top: 50%;
  right: 3px;
  left: 3px;
  height: 1px;
  background: var(--johnbot-border);
  content: "";
}

.diagram-routine-tick {
  position: absolute;
  top: var(--diagram-tick-at);
  right: 3px;
  left: 3px;
  z-index: 1;
  height: 3px;
  translate: 0 -50%;
  border-radius: var(--johnbot-radius-pill);
  background: var(--diagram-routine-color, var(--johnbot-accent));
}

.diagram-routine-day-name {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: 1;
}

.diagram-routine-day[data-today] .diagram-routine-day-name {
  color: var(--johnbot-accent-text);
  font-weight: var(--johnbot-weight-semibold);
}

.diagram-routine-dots {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-1);
  margin: 0;
  padding: 0;
  list-style: none;
}

.diagram-routine-dot {
  width: 8px;
  height: 8px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-border-strong);
}

.diagram-routine-dot[data-status="succeeded"] {
  background: var(--johnbot-success);
}

.diagram-routine-dot[data-status="failed"] {
  background: var(--johnbot-danger);
}

.diagram-routine-dot[data-status="running"] {
  background: var(--johnbot-accent);
}

@keyframes diagram-routine-fire {
  50% {
    scale: 1.15;
  }
}

/* Run panel */

.diagram-inspector {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  display: flex;
  width: var(--diagram-inspector-width);
  min-height: 0;
  flex-direction: column;
  border-left: 1px solid var(--johnbot-border);
  background: var(--johnbot-bg-surface);
}

.diagram-inspector-header {
  display: flex;
  min-height: 52px;
  align-items: center;
  gap: var(--johnbot-space-2);
  border-bottom: 1px solid var(--johnbot-border);
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
}

.diagram-inspector-title {
  overflow: hidden;
  margin: 0;
  flex: 1;
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-semibold);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.diagram-inspector-avatar.agent-avatar {
  width: 24px;
  height: 24px;
}

.diagram-inspector-body {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  gap: var(--johnbot-space-4);
  overflow-y: auto;
  padding: var(--johnbot-space-4);
}

.diagram-inspector-run {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--johnbot-space-1-5) var(--johnbot-space-2);
  font-size: var(--johnbot-text-md);
}

.diagram-inspector-muted,
.diagram-inspector-empty {
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
}

.diagram-inspector-section {
  display: grid;
  gap: var(--johnbot-space-1-5);
}

.diagram-inspector-section p {
  margin: 0;
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
}

/* The task reads as text until the user points at it or types in it. */
.diagram-inspector-task.ui-textarea {
  min-height: 0;
  margin: calc(-1 * var(--johnbot-space-1-5));
  border-color: transparent;
  background: transparent;
  padding: var(--johnbot-space-1) var(--johnbot-space-1-5);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
  resize: none;
  field-sizing: content;
}

.diagram-inspector-task.ui-textarea:is(:hover, :focus-visible, :focus) {
  border-color: var(--johnbot-border);
  background: var(--johnbot-bg-control);
}

.diagram-inspector-section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.diagram-inspector-section-title {
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-semibold);
  letter-spacing: var(--johnbot-tracking-wide);
}

.diagram-inspector-text {
  max-height: 320px;
  overflow: auto;
  margin: 0;
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-control);
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
  color: var(--johnbot-text-primary);
  font-family: var(--johnbot-font-sans);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

.diagram-inspector-text[data-tone="danger"] {
  background: var(--johnbot-danger-soft);
  color: var(--johnbot-danger-text);
}

.diagram-inspector-steps {
  display: grid;
  gap: var(--johnbot-space-0-5);
  margin: 0;
  padding: 0;
  list-style: none;
}

.diagram-inspector-step.ui-button {
  width: 100%;
  height: auto;
  justify-content: flex-start;
  gap: var(--johnbot-space-2);
  padding: var(--johnbot-space-2);
  text-align: left;
}

.diagram-inspector-step-number {
  display: grid;
  width: 20px;
  height: 20px;
  flex: none;
  place-items: center;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-control);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
  font-weight: var(--johnbot-weight-semibold);
}

.diagram-inspector-step-name {
  overflow: hidden;
  flex: 1;
  font-size: var(--johnbot-text-md);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.diagram-inspector-step-status {
  display: inline-flex;
  align-items: center;
  gap: var(--johnbot-space-1);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
}

.diagram-inspector-times,
.diagram-inspector-history {
  display: grid;
  gap: var(--johnbot-space-1);
  margin: 0;
  padding: 0;
  font-size: var(--johnbot-text-md);
  list-style: none;
}

.diagram-inspector-times li {
  color: var(--johnbot-text-secondary);
}

.diagram-inspector-history li {
  display: grid;
  grid-template-columns: 96px minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.diagram-inspector-history-time {
  overflow: hidden;
  color: var(--johnbot-text-secondary);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.diagram-inspector-history-kind {
  color: var(--johnbot-text-muted);
}

.diagram-inspector-history-kind::before {
  content: " · ";
}

.diagram-inspector-step-status svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
}

/* Assistant */

.diagram-chat,
.diagram-chat-launcher.ui-button {
  background: var(--johnbot-bg-glass);
  box-shadow:
    0 0 0 1px var(--johnbot-glass-border),
    var(--johnbot-shadow-overlay);
  backdrop-filter: blur(16px);
}

/* The launcher and the panel share one grid cell. Opening grows the panel out of the launcher's pill
   with a clip that relaxes into the panel's own corners, with a little overshoot; closing folds it
   back faster and without one. The panel's shadow sits outside its box, so the open clip leaves room. */
.diagram-chat-morph {
  --diagram-chat-open-duration: var(--johnbot-duration-island-content);
  --diagram-chat-close-duration: var(--johnbot-duration-island-content-exit);
  --diagram-chat-open-ease: cubic-bezier(0.34, 1.25, 0.64, 1);
  --diagram-chat-launcher-height: 36px;
  --diagram-chat-blur: 2px;
  display: grid;
  align-items: end;
}

.diagram-chat-morph > * {
  grid-area: 1 / 1;
}

.diagram-chat-launcher.ui-button {
  height: var(--diagram-chat-launcher-height);
  touch-action: none;
  justify-self: start;
  gap: var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-pill);
  padding-left: var(--johnbot-space-1-5);
  pointer-events: auto;
  transition:
    opacity var(--diagram-chat-open-duration) var(--johnbot-ease-out),
    filter var(--diagram-chat-open-duration) var(--johnbot-ease-out),
    scale var(--diagram-chat-open-duration) var(--johnbot-ease-out);
}

.diagram-chat-morph[data-open="true"] .diagram-chat-launcher.ui-button {
  scale: 0.97;
  filter: blur(var(--diagram-chat-blur));
  opacity: 0;
  pointer-events: none;
  transition:
    opacity var(--johnbot-duration-fast) var(--johnbot-ease-out),
    filter var(--johnbot-duration-fast) var(--johnbot-ease-out),
    scale var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.diagram-chat {
  display: flex;
  max-height: 340px;
  flex-direction: column;
  border-radius: var(--johnbot-radius-xl);
  overflow: hidden;
  clip-path: inset(calc(100% - var(--diagram-chat-launcher-height)) 24% 0 0 round var(--johnbot-radius-pill));
  opacity: 0;
  pointer-events: none;
  transition:
    clip-path var(--diagram-chat-close-duration) var(--johnbot-ease-out),
    opacity var(--diagram-chat-close-duration) var(--johnbot-ease-out);
}

.diagram-chat-morph[data-open="true"] .diagram-chat {
  clip-path: inset(-32px round 0);
  opacity: 1;
  pointer-events: auto;
  transition:
    clip-path var(--diagram-chat-open-duration) var(--diagram-chat-open-ease),
    opacity var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

/* The content settles a beat after the shape, so the panel reads as opening, not appearing. */
.diagram-chat > * {
  filter: blur(var(--diagram-chat-blur));
  opacity: 0;
  translate: 0 var(--johnbot-space-2);
  transition:
    opacity var(--johnbot-duration-fast) var(--johnbot-ease-out),
    filter var(--johnbot-duration-fast) var(--johnbot-ease-out),
    translate var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.diagram-chat-morph[data-open="true"] .diagram-chat > * {
  filter: blur(0);
  opacity: 1;
  translate: 0 0;
  transition:
    opacity var(--diagram-chat-open-duration) var(--johnbot-ease-out) var(--johnbot-duration-fast),
    filter var(--diagram-chat-open-duration) var(--johnbot-ease-out) var(--johnbot-duration-fast),
    translate var(--diagram-chat-open-duration) var(--johnbot-ease-out) var(--johnbot-duration-fast);
}

.diagram-chat-avatar.agent-avatar {
  width: 24px;
  height: 24px;
}

.diagram-chat-header {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  cursor: grab;
  touch-action: none;
  border-bottom: 1px solid var(--johnbot-border);
  padding: var(--johnbot-space-2) var(--johnbot-space-2) var(--johnbot-space-2) var(--johnbot-space-3);
}

.diagram-chat-title {
  overflow: hidden;
  margin: 0;
  flex: 1;
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-semibold);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.diagram-chat-messages {
  display: flex;
  min-height: 96px;
  flex: 1;
  flex-direction: column;
  gap: var(--johnbot-space-2);
  overflow-y: auto;
  padding: var(--johnbot-space-3);
}

.diagram-chat-empty {
  margin: auto 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  text-align: center;
}

.diagram-chat-bubble {
  max-width: 88%;
  font-size: var(--johnbot-text-md);
}

.diagram-chat-text {
  margin: 0;
  white-space: pre-wrap;
}

/* The chat's Markdown, a size down to fit the panel. */
.diagram-chat-markdown {
  min-width: 0;
  font-size: var(--johnbot-text-md);
}

.diagram-chat-changes {
  display: grid;
  gap: var(--johnbot-space-1);
  margin: var(--johnbot-space-2) 0 0;
  padding: 0;
  font-size: var(--johnbot-text-sm);
  list-style: none;
}

.diagram-chat-changes li {
  display: flex;
  align-items: flex-start;
  gap: var(--johnbot-space-1-5);
}

.diagram-chat-changes svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  flex: none;
  margin-top: 2px;
  color: var(--johnbot-success-text);
}

.diagram-chat-working {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

/* The chat composer's compact row, without its attach button: the editor and the send button. */
.diagram-chat-composer.composer[data-compact] {
  grid-template-columns: minmax(0, 1fr) auto;
  margin: var(--johnbot-space-2);
}

.diagram-chat-composer.composer[data-compact] > .composer-input-label {
  grid-column: 1;
}

@media (prefers-reduced-motion: reduce) {
  .diagram-edge[data-state="running"] .diagram-edge-line {
    animation: none;
  }

  .diagram-node[data-kind="routine"][data-firing] .diagram-node-icon {
    animation: none;
  }

  .diagram-chat-launcher.ui-button,
  .diagram-chat,
  .diagram-chat > *,
  .diagram-board-world[data-settling],
  .diagram-node,
  .diagram-port.ui-button,
  .diagram-edge-remove.ui-button {
    transition: none;
  }
}

/*
 * The canvas before its first routine: a faint sample diagram builds itself behind the pitch, one
 * run passes through it, and it fades and starts again. The dots move into the backdrop, so they
 * clear behind the pitch with the cards.
 */
.diagram-empty {
  container-type: inline-size;
}

.diagram-empty-viewport {
  display: grid;
  background-image: none;
  cursor: default;
}

.diagram-empty-backdrop {
  position: relative;
  grid-area: 1 / 1;
  overflow: hidden;
  pointer-events: none;
  user-select: none;
  opacity: 0.62;
  mask-image:
    radial-gradient(ellipse 30% 30% at 50% 50%, var(--johnbot-transparent) 55%, var(--johnbot-text-primary) 100%),
    radial-gradient(ellipse 80% 85% at 50% 50%, var(--johnbot-text-primary) 55%, var(--johnbot-transparent) 100%);
  mask-composite: intersect;
}

.diagram-empty-grid {
  position: absolute;
  inset: 0;
  background-image: radial-gradient(circle at 1px 1px, var(--johnbot-border-strong) 1px, var(--johnbot-transparent) 0);
  background-size: 24px 24px;
}

.diagram-empty-world {
  top: 50%;
  left: 50%;
  translate: -50% -50%;
  transform-origin: center;
  scale: var(--diagram-empty-scale);
  transition:
    opacity 900ms var(--johnbot-ease-out),
    filter 900ms var(--johnbot-ease-out);
}

.diagram-empty-backdrop[data-leaving] .diagram-empty-world {
  opacity: 0;
  filter: blur(4px);
}

/* A card lands: it rises out of a blur. */
.diagram-empty-node {
  opacity: 0;
  filter: blur(6px);
  transform: translateY(12px) scale(0.96);
  transition:
    opacity 700ms var(--johnbot-ease-out),
    filter 700ms var(--johnbot-ease-out),
    transform 700ms var(--johnbot-ease-out);
}

.diagram-empty-node[data-shown] {
  opacity: 1;
  filter: blur(0);
  transform: none;
}

.diagram-empty-node .diagram-node {
  cursor: default;
}

/* A connection draws from its output to its input, after the card it enters has landed. */
.diagram-empty .diagram-empty-edge[data-state="idle"] .diagram-edge-line {
  stroke-dasharray: 1600;
  stroke-dashoffset: 1600;
  transition: stroke-dashoffset 900ms var(--johnbot-ease-in-out) 350ms;
}

.diagram-empty .diagram-empty-edge[data-drawn] .diagram-edge-line {
  stroke-dashoffset: 0;
}

.diagram-empty .diagram-empty-edge[data-state] .diagram-edge-arrow {
  opacity: 0;
  transition: opacity 300ms var(--johnbot-ease-out) 1100ms;
}

.diagram-empty .diagram-empty-edge[data-drawn] .diagram-edge-arrow {
  opacity: 1;
}

/* The run pulse rides one connection, once, in the colour of the routine that fired. */
.diagram-empty-pulse {
  position: absolute;
  top: 0;
  left: 0;
  width: 10px;
  height: 10px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--diagram-routine-color, var(--johnbot-accent));
  outline: 4px solid var(--diagram-routine-soft, var(--johnbot-accent-soft));
  offset-rotate: 0deg;
  animation: diagram-empty-pulse 900ms var(--johnbot-ease-in-out) both;
}

@keyframes diagram-empty-pulse {
  0% {
    offset-distance: 0%;
    opacity: 0;
  }

  15% {
    opacity: 1;
  }

  85% {
    opacity: 1;
  }

  100% {
    offset-distance: 100%;
    opacity: 0;
  }
}

.diagram-empty-pitch {
  z-index: 1;
  display: grid;
  grid-area: 1 / 1;
  max-width: 34rem;
  place-self: center;
  justify-items: center;
  gap: var(--johnbot-space-4);
  padding: var(--johnbot-space-6);
  text-align: center;
}

.diagram-empty-title {
  margin: 0;
  font-size: var(--johnbot-text-display);
  font-weight: var(--johnbot-weight-semibold);
  letter-spacing: -0.01em;
  line-height: 1.2;
}

.diagram-empty-title > span {
  display: block;
}

.diagram-empty-lead {
  color: var(--johnbot-text-muted);
}

/* The one handwritten word of the title. It writes itself once. The app has no hand font, so it
   uses the system ones; their small x-height is brought up to the title's. */
.diagram-empty-title .diagram-empty-hand {
  display: inline;
  color: var(--johnbot-accent-text);
  font-family: "Bradley Hand", "Noteworthy", "Segoe Print", cursive;
  font-size-adjust: 0.62;
  font-weight: var(--johnbot-weight-semibold);
  line-height: 1;
  clip-path: inset(-0.4em 100% -0.4em -0.2em);
  animation: diagram-empty-write 520ms linear 500ms forwards;
}

@keyframes diagram-empty-write {
  to {
    clip-path: inset(-0.4em -0.2em -0.4em -0.2em);
  }
}

.diagram-empty-lines {
  display: grid;
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-xl);
  line-height: 1.5;
}

.diagram-empty-action.ui-button {
  width: 100%;
  max-width: 22rem;
  height: var(--johnbot-control-lg);
  margin-top: var(--johnbot-space-2);
}

/* A narrow pane: a smaller title, and a stronger fade so the cards stay behind the words. */
@container (max-width: 720px) {
  .diagram-empty-title {
    font-size: var(--johnbot-text-3xl);
  }

  .diagram-empty-lines {
    font-size: var(--johnbot-text-lg);
  }

  .diagram-empty-backdrop {
    opacity: 0.45;
  }
}

/* Less motion: a still frame with the finished run. */
.diagram-empty[data-still] :is(.diagram-empty-world, .diagram-empty-node, .diagram-empty-hand),
.diagram-empty[data-still] .diagram-empty-edge[data-state] path {
  animation: none;
  transition: none;
  clip-path: none;
}

.diagram-empty[data-still] .diagram-empty-pulse {
  display: none;
}

/* === from: @johnbot/ui/features/workflows/workflow-nodes.css === */
/*
 * Workflow node components: the node chrome, the step and control nodes, ports, connections, the
 * result strip, the picker menus and the asset library. The values follow the Higgsfield canvas
 * measurements: the card is one step lighter than the canvas, an inner field is one step lighter
 * than the card, and every edge is a 1px ring, not a shadow. The canvas, its HUD and the story frame
 * keep their own styles.
 */

:where(.wfn-stage, .wfn-menu, .wfn-popover) {
  --wfn-card: var(--johnbot-bg-canvas);
  --wfn-field: var(--johnbot-bg-surface-raised);
  --wfn-ring: color-mix(in srgb, var(--johnbot-text-primary) 6%, transparent);
  --wfn-ring-strong: color-mix(in srgb, var(--johnbot-text-primary) 10%, transparent);
  --wfn-hover: color-mix(in srgb, var(--johnbot-text-primary) 6%, transparent);
  --wfn-port: color-mix(in srgb, var(--johnbot-text-primary) 10%, var(--johnbot-bg-canvas));
  --wfn-glass: color-mix(in srgb, var(--johnbot-bg-surface-raised) 75%, transparent);
  --wfn-glass-blur: blur(40px) saturate(1.4);
  --wfn-radius-card: calc(var(--johnbot-radius-lg) + var(--johnbot-space-1));
  --wfn-small: calc(var(--johnbot-text-sm) - 1px);
  /* Ten pixels: one step over the control radius, so a row sits concentric in its menu. */
  --wfn-radius-row: calc(var(--johnbot-radius-sm) + var(--johnbot-space-1));
  --wfn-radius-run: calc(var(--johnbot-radius-md) + 2px);
  /* The Title size: 40px, one step over the display size. */
  --wfn-text-title: calc(var(--johnbot-text-display) * 1.25);
  /* Focus is a neutral 1px ring, not the accent halo of the shared token. */
  --johnbot-focus-ring: 0 0 0 1px var(--johnbot-text-muted);
}

/*
 * The light palette puts a raised surface only a little above the canvas, so a field on a card
 * almost disappears. There the card is the light surface, and a field is one step darker.
 */
:root[data-johnbot-color-scheme="light"] :where(.wfn-stage, .wfn-menu, .wfn-popover) {
  --wfn-card: var(--johnbot-bg-surface);
  --wfn-field: var(--johnbot-bg-control-hover);
}

/* ---------------------------------------------------------------- Node */

.wfn-node {
  position: relative;
  display: grid;
  gap: var(--johnbot-space-1-5);
  width: var(--wfn-width);
  transition: width var(--johnbot-duration-slow) var(--johnbot-ease-out);
}

.wfn-node[data-kind="prompt"] {
  --wfn-width: 296px;
  --wfn-height: 151px;
}

.wfn-node[data-kind="agent"],
.wfn-node[data-kind="llm"] {
  --wfn-width: 350px;
}

.wfn-node[data-kind="image"] {
  --wfn-width: 300px;
}

.wfn-node[data-kind="asset"] {
  --wfn-width: 240px;
}

.wfn-label {
  display: flex;
  gap: var(--johnbot-space-1);
  align-items: center;
  color: var(--johnbot-text-muted);
  font-size: var(--wfn-small);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-sm);
  user-select: none;
}

.wfn-label svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
}

.wfn-card {
  position: relative;
  display: grid;
  gap: var(--johnbot-space-2);
  align-content: start;
  min-height: var(--wfn-height, auto);
  padding: var(--johnbot-space-2);
  border-radius: var(--wfn-radius-card);
  background: var(--wfn-card);
  box-shadow: 0 0 0 1px var(--wfn-ring);
  transition: box-shadow var(--johnbot-duration-hover) var(--johnbot-ease-out);
}

.wfn-card[data-media] {
  aspect-ratio: var(--wfn-aspect, auto);
  padding: 0;
  overflow: hidden;
}

/* --------------------------------------------------------------- Field */

.wfn-field {
  display: grid;
  gap: var(--johnbot-space-2);
  padding: var(--johnbot-space-3);
  border-radius: var(--johnbot-radius-md);
  background: var(--wfn-field);
  transition: box-shadow var(--johnbot-duration-hover) var(--johnbot-ease-out);
}

.wfn-field:focus-within {
  box-shadow: inset 0 0 0 1px var(--wfn-ring-strong);
}

.wfn-field-fill {
  min-height: calc(var(--wfn-height) - var(--johnbot-space-4));
}

.wfn-field-task {
  grid-template-rows: 1fr auto;
  min-height: 150px;
}

.wfn-stage .wfn-input {
  min-height: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  resize: none;
  field-sizing: content;
}

.wfn-stage .wfn-input::placeholder,
.wfn-stage .wfn-text-input::placeholder {
  color: var(--johnbot-text-muted);
}

/* The field box shows the focus, so the shared accent outline goes. */
.wfn-stage .wfn-input:focus-visible {
  outline: none;
  box-shadow: none;
}

.wfn-field-fill .wfn-input {
  height: 100%;
}

.wfn-field-foot {
  display: flex;
  gap: var(--johnbot-space-2);
  align-items: center;
  justify-content: space-between;
  min-width: 0;
}

.wfn-field-result p {
  max-height: 120px;
  margin: 0;
  overflow-y: auto;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

/* Why a failed run stopped, in place of its result. The Failed mark and the results carry the colour. */
.wfn-field-result p[data-failed] {
  color: var(--johnbot-text-muted);
}

.wfn-field-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: calc(var(--johnbot-space-1) * -1) 0;
  color: var(--johnbot-text-muted);
  font-size: var(--wfn-small);
  font-weight: var(--johnbot-weight-semibold);
}

/* A pill in a field: an agent, a model. Flat until hover, as the Higgsfield model button. */
.wfn-stage .wfn-pill {
  gap: var(--johnbot-space-1-5);
  min-width: 0;
  height: 20px;
  padding: 0 var(--johnbot-space-1);
  border: 0;
  border-radius: var(--johnbot-radius-pill);
  background: transparent;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
}

/* A long model name gives up its room first and ends with "…", so it stays in the field. */
.wfn-stage .wfn-model-pill {
  flex-shrink: 1;
}

/* An agent next to a model keeps its full name, but leaves 96px: the model logo, a few letters and the arrow. */
.wfn-stage .wfn-agent-pill:has(+ .wfn-model-pill) {
  max-width: calc(100% - 96px - var(--johnbot-space-2));
}

.wfn-stage .wfn-field-foot .provider-model-trigger {
  gap: var(--johnbot-space-1);
  height: 20px;
  padding: 0 var(--johnbot-space-1);
  border: 0;
  background: transparent;
  box-shadow: none;
}

.wfn-stage .wfn-field-foot .provider-model-trigger-name {
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-sm);
}

.wfn-stage .wfn-field-foot .provider-model-trigger:is(:hover, [aria-expanded="true"]),
.wfn-stage .wfn-pill:hover {
  background: var(--wfn-hover);
}

.wfn-pill > svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  color: var(--johnbot-text-muted);
}

/* A provider logo is a filled mark, so it overrides the outline paint of the menu icons. */
.wfn-pill > svg.wfn-model-logo,
.wfn-menu.ui-action-menu [role="menuitem"] > svg.wfn-model-logo {
  flex: none;
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  color: var(--johnbot-text-primary);
  fill: currentcolor;
  stroke: none;
}

.wfn-avatar.agent-avatar {
  --agent-avatar-optical-offset: -2px;

  flex: none;
  width: 16px;
  height: 16px;
}

.wfn-stage .wfn-run {
  height: var(--johnbot-control-lg);
  border-radius: var(--wfn-radius-run);
  font-weight: var(--johnbot-weight-semibold);
}

/* --------------------------------------------------------------- Ports */

.wfn-ports {
  position: absolute;
  top: 50%;
  display: grid;
  gap: 10px;
  translate: 0 calc(-50% + 11px);
}

.wfn-ports[data-side="in"] {
  right: calc(100% + var(--johnbot-space-3));
}

.wfn-ports[data-side="out"] {
  left: calc(100% + var(--johnbot-space-3));
}

.wfn-port-slot {
  position: relative;
  display: grid;
}

.wfn-stage .wfn-port {
  width: var(--johnbot-control-sm);
  height: var(--johnbot-control-sm);
  border-radius: var(--johnbot-radius-pill);
  background: var(--wfn-port);
  box-shadow: 0 0 0 1px var(--wfn-ring);
  color: var(--johnbot-text-secondary);
  opacity: 0;
  transition:
    opacity var(--johnbot-duration-fast) var(--johnbot-ease-out),
    scale var(--johnbot-duration-fast) var(--johnbot-ease-out),
    background-color var(--johnbot-duration-hover) var(--johnbot-ease-out);
}

.wfn-port svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.wfn-node:is(:hover, :focus-within, [data-selected]) .wfn-port {
  opacity: 1;
}

.wfn-stage .wfn-port:hover {
  background: var(--johnbot-text-primary);
  color: var(--johnbot-bg-canvas);
}

/*
 * The port name shows next to the port on hover, as the Higgsfield "Text" chip. The text box is
 * trimmed to the capitals, so a name with no descender is at the vertical centre. The chip keeps
 * its height of one line and 2px above and below.
 */
.wfn-port-chip {
  position: absolute;
  top: 50%;
  padding: calc((1lh - 1cap) / 2 + 2px) var(--johnbot-space-2);
  text-box: trim-both cap alphabetic;
  border-radius: var(--johnbot-radius-sm);
  background: var(--wfn-card);
  box-shadow: 0 0 0 1px var(--wfn-ring-strong);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-sm);
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  translate: 0 -50%;
  transition: opacity var(--johnbot-duration-hover) var(--johnbot-ease-out);
}

.wfn-port-slot[data-side="out"] .wfn-port-chip {
  left: calc(100% + var(--johnbot-space-2));
}

.wfn-port-slot[data-side="in"] .wfn-port-chip {
  right: calc(100% + var(--johnbot-space-2));
}

.wfn-port-slot:has(.wfn-port:is(:hover, :focus-visible)) .wfn-port-chip {
  opacity: 1;
}

/* ------------------------------------------------------------- Toolbar */

/*
 * The toolbar keeps its screen size at every zoom, as the results strip does. Its shape follows the
 * Infeld IconActionList: a round bar of round icon buttons, muted until the pointer or the focus is
 * on them. Each name shows in a tooltip. A ring, not a shadow, sets it off the canvas.
 */
.wfn-toolbar {
  position: absolute;
  bottom: calc(100% + var(--johnbot-space-3) / var(--wfn-scale, 1));
  left: round(50%, 1px);
  z-index: 2;
  display: flex;
  gap: var(--johnbot-space-0-5);
  align-items: center;
  padding: var(--johnbot-space-1);
  border-radius: var(--johnbot-radius-pill);
  white-space: nowrap;
  background: var(--wfn-glass);
  box-shadow: 0 0 0 1px var(--wfn-ring-strong);
  translate: calc(round(-50%, 1px) + var(--wfn-snap-x, 0px) / var(--wfn-scale, 1))
    calc(var(--wfn-snap-y, 0px) / var(--wfn-scale, 1));
  transform-origin: bottom center;
  scale: calc(1 / var(--wfn-scale, 1));
  backdrop-filter: var(--wfn-glass-blur);
}

/*
 * Above the node, the toolbar can cover a node that is near. Then it goes under the node, and under the
 * results strip when the node shows one: 8px gap, 52px strip, 8px gap, as the canvas measures it.
 */
.wfn-toolbar[data-side="below"] {
  top: calc(100% + var(--johnbot-space-3) / var(--wfn-scale, 1));
  bottom: auto;
  transform-origin: top center;
}

.wfn-toolbar[data-side="below"][data-strip] {
  top: calc(100% + (8px + 52px + var(--johnbot-space-2)) / var(--wfn-scale, 1));
}

/* The fill shows the focus, as the hover does, so the toolbar has no focus ring. */
.wfn-stage .wfn-toolbar :is(.ui-button, .wfn-toolbar-select) {
  border-radius: var(--johnbot-radius-pill);
  box-shadow: none;
  color: var(--johnbot-text-secondary);
}

.wfn-stage .wfn-toolbar :is(.ui-button, .wfn-toolbar-select):is(:hover, :focus-visible, [aria-pressed="true"]) {
  background: var(--wfn-hover);
  color: var(--johnbot-text-primary);
}

.wfn-stage .wfn-toolbar .wfn-tool-action {
  width: var(--johnbot-control-md);
  height: var(--johnbot-control-md);
  padding: 0;
}

.wfn-stage .wfn-toolbar .wfn-tool-action svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
}

/* Delete takes the danger colour under the pointer or the focus, as are the nodes and the lines that it removes. */
.wfn-stage .wfn-toolbar .wfn-tool-action[data-tone="danger"]:is(:hover, :focus-visible) {
  background: color-mix(in srgb, var(--johnbot-danger) 16%, transparent);
  color: var(--johnbot-danger-text);
}

.wfn-toolbar-separator {
  width: 1px;
  height: 16px;
  margin: 0 var(--johnbot-space-1);
  background: var(--wfn-ring-strong);
}

/* A node with no actions of its own and no Duplicate starts its toolbar with Lock. */
.wfn-toolbar-separator:first-child {
  display: none;
}

.wfn-stage .wfn-toolbar-select {
  gap: var(--johnbot-space-1);
  height: var(--johnbot-control-md);
  padding-inline: var(--johnbot-space-2);
  font-size: var(--johnbot-text-sm);
}

.wfn-toolbar-select svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  color: var(--johnbot-text-muted);
}

/* ---------------------------------------------------------------- Text */

.wfn-text {
  width: auto;
  min-width: 120px;
}

.wfn-stage .wfn-text-input {
  min-height: 0;
  padding: var(--johnbot-space-1) var(--johnbot-space-1-5);
  border: 0;
  border-radius: var(--johnbot-radius-sm);
  background: transparent;
  box-shadow: none;
  color: var(--wfn-text-ink, var(--johnbot-text-primary));
  font-size: var(--johnbot-text-lg);
  line-height: 1.4;
  resize: none;
  field-sizing: content;
}

.wfn-stage .wfn-text-input[data-font="mono"] {
  font-family: var(--johnbot-font-mono);
}

.wfn-stage .wfn-text-input[data-text-size="lg"] {
  font-size: var(--johnbot-text-3xl);
  letter-spacing: var(--johnbot-tracking-tight);
}

.wfn-stage .wfn-text-input[data-text-size="xl"] {
  font-size: var(--wfn-text-title);
  letter-spacing: var(--johnbot-tracking-tight);
}

.wfn-stage .wfn-text-input[data-bold] {
  font-weight: var(--johnbot-weight-bold);
}

.wfn-stage .wfn-text-input:focus-visible {
  outline: none;
  box-shadow: none;
}

/* --------------------------------------------------------------- Media */

.wfn-media {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.wfn-card[data-media] > .wfn-media {
  position: absolute;
  inset: 0;
}

.wfn-media-empty {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  height: 100%;
  color: color-mix(in srgb, var(--johnbot-text-primary) 14%, transparent);
}

.wfn-media-empty svg {
  width: 40px;
  height: 40px;
  stroke-width: 1.25;
}

/*
 * The glass layer on an image: hidden at rest, shown on hover, focus or selection. It never grows
 * past the card, as on Higgsfield: the prompt stops at three lines and scrolls, and on a short card
 * it gives up more of its height.
 */
.wfn-overlay {
  position: absolute;
  inset: auto 0 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: var(--johnbot-space-1);
  max-height: 100%;
  padding: var(--johnbot-space-2);
  opacity: 0;
  translate: 0 4px;
  transition:
    opacity var(--johnbot-duration-normal) var(--johnbot-ease-out),
    translate var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

.wfn-node:is(:hover, :focus-within, [data-selected]) .wfn-overlay {
  opacity: 1;
  translate: 0 0;
}

.wfn-overlay-bar {
  display: flex;
  gap: var(--johnbot-space-1);
  align-items: center;
}

.wfn-stage .wfn-chip {
  display: inline-flex;
  gap: var(--johnbot-space-1);
  align-items: center;
  height: var(--johnbot-control-xs);
  padding: 0 var(--johnbot-space-1-5);
  border: 0;
  border-radius: var(--johnbot-radius-sm);
  background: var(--wfn-glass);
  box-shadow: inset 0 0 0 1px var(--wfn-ring-strong);
  color: var(--johnbot-text-primary);
  font-size: var(--wfn-small);
  font-weight: var(--johnbot-weight-medium);
  backdrop-filter: var(--wfn-glass-blur);
  cursor: pointer;
}

.wfn-chip svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
}

.wfn-stage .wfn-collapse {
  margin-left: auto;
  border-radius: var(--johnbot-radius-sm);
  color: var(--johnbot-text-primary);
}

.wfn-panel {
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  gap: var(--johnbot-space-2);
  min-height: 0;
  padding: 10px;
  border-radius: var(--johnbot-radius-md);
  background: var(--wfn-glass);
  box-shadow: inset 0 0 0 1px var(--wfn-ring);
  backdrop-filter: var(--wfn-glass-blur);
}

.wfn-panel .wfn-input {
  max-height: calc(var(--johnbot-leading-sm) * 3);
  overflow-y: auto;
  font-weight: var(--johnbot-weight-medium);
  scrollbar-width: none;
}

.wfn-stage .wfn-run-pill {
  gap: var(--johnbot-space-1);
  height: var(--johnbot-control-xs);
  padding: 0 10px 0 var(--johnbot-space-1-5);
  border-radius: var(--johnbot-radius-pill);
  font-size: var(--johnbot-text-sm);
}

.wfn-run-pill svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
}

/* The spinner takes the place of the play icon, so the pill keeps its width. */
.wfn-stage .wfn-run-pill[aria-busy="true"] svg {
  display: none;
}

/* --------------------------------------------------------------- Asset */

.wfn-stage .wfn-asset-trigger {
  display: grid;
  width: 100%;
  min-height: 120px;
  padding: 0;
  border: 0;
  border-radius: var(--johnbot-radius-md);
  background: var(--wfn-field);
  color: inherit;
  font: inherit;
  cursor: pointer;
}

/* A taller asset card stretches its file button, and the file row stays in the middle. */
.wfn-node[data-kind="asset"] .wfn-card {
  align-content: stretch;
}

/* An image asset with a height the user set fills the card and crops the image. */
.wfn-node[data-height] .wfn-card[data-media] {
  aspect-ratio: auto;
  height: var(--wfn-height);
}

.wfn-node[data-height] .wfn-card[data-media] .wfn-asset-trigger > .wfn-media {
  position: absolute;
  inset: 0;
}

.wfn-card[data-media] .wfn-asset-trigger {
  position: absolute;
  inset: 0;
  border-radius: 0;
}

.wfn-asset-trigger:focus-visible {
  outline: 0;
  box-shadow: 0 0 0 1px var(--johnbot-text-muted);
}

/* A file from the computer over the card: the card takes the hover fill. */
.wfn-stage .wfn-asset-trigger[data-dropping] {
  background: var(--wfn-hover);
}

.wfn-asset-empty {
  display: grid;
  gap: var(--johnbot-space-2);
  place-content: center;
  justify-items: center;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
}

.wfn-asset-icon {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--wfn-hover);
  box-shadow: inset 0 0 0 1px var(--wfn-ring-strong);
  transition: background-color var(--johnbot-duration-hover) var(--johnbot-ease-out);
}

.wfn-asset-icon svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
}

.wfn-asset-trigger:is(:hover, [data-dropping]) .wfn-asset-icon {
  background: var(--wfn-ring-strong);
}

.wfn-asset-caption {
  position: absolute;
  bottom: var(--johnbot-space-2);
  left: var(--johnbot-space-2);
  max-width: calc(100% - var(--johnbot-space-4));
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wfn-asset-file {
  display: flex;
  gap: var(--johnbot-space-3);
  align-items: center;
  min-width: 0;
  padding: var(--johnbot-space-3);
  text-align: left;
}

.wfn-asset-glyph {
  position: relative;
  display: grid;
  flex: none;
  place-items: center;
  width: 40px;
  height: 48px;
  border-radius: var(--johnbot-radius-sm);
  background: var(--wfn-hover);
  box-shadow: inset 0 0 0 1px var(--wfn-ring-strong);
  color: var(--johnbot-text-muted);
}

.wfn-asset-glyph svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  translate: 0 -4px;
}

.wfn-asset-glyph span {
  position: absolute;
  bottom: var(--johnbot-space-1);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-glyph-sm);
  font-weight: var(--johnbot-weight-bold);
  letter-spacing: var(--johnbot-tracking-wide);
}

.wfn-asset-text {
  display: grid;
  min-width: 0;
}

.wfn-asset-name {
  overflow: hidden;
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wfn-asset-meta {
  color: var(--johnbot-text-muted);
  font-size: var(--wfn-small);
  line-height: var(--johnbot-leading-sm);
}

/* ------------------------------------------------------ Menus, library */

.wfn-menu {
  --ui-menu-bg: var(--wfn-glass);
  --ui-menu-panel-shadow: 0 0 0 1px var(--wfn-ring-strong);
  --ui-menu-item-hover: var(--wfn-hover);
  --ui-menu-radius: var(--johnbot-radius-lg);

  backdrop-filter: var(--wfn-glass-blur);
}

/* ------------------------------------------------------------- Picker */

/*
 * Every choice list on the canvas has this one style: a search field over a divider, group
 * headings, and rows with an icon tile, the name and small chips. The panel, the row and the tile
 * radii are concentric.
 */
.wfn-picker.ui-action-menu {
  --ui-menu-radius: var(--wfn-radius-card);

  display: flex;
  flex-direction: column;
  min-width: 232px;
  max-width: min(320px, calc(100vw - var(--johnbot-space-4)));
  max-height: min(440px, var(--kb-popper-content-available-height, 440px));
  padding: 0;
}

.wfn-picker-search {
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--johnbot-space-2);
  padding: 0 var(--johnbot-space-3);
  border-bottom: 1px solid var(--wfn-ring-strong);
}

.wfn-picker.ui-action-menu .wfn-picker-search > svg {
  flex: none;
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  color: var(--johnbot-text-muted);
}

.wfn-picker .wfn-picker-field {
  flex: 1;
  min-width: 0;
  height: var(--johnbot-control-lg);
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
}

.wfn-picker .wfn-picker-field::placeholder {
  color: var(--johnbot-text-muted);
}

/* The divider under the field shows where typing goes, so the shared outline goes. */
.wfn-picker .wfn-picker-field:focus-visible {
  outline: none;
  box-shadow: none;
}

.wfn-picker-search:has(.wfn-picker-field:focus-visible) {
  border-bottom-color: var(--johnbot-border-focus);
}

.wfn-picker-list {
  flex: 1 1 auto;
  min-height: 0;
  padding: var(--johnbot-space-1-5);
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
}

/* An action list groups its rows in a fieldset, which has the group role. */
fieldset.wfn-picker-group {
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}

.wfn-picker-group + .wfn-picker-group {
  margin-top: var(--johnbot-space-1-5);
}

.wfn-picker-heading {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-1-5);
  padding: var(--johnbot-space-1-5) var(--johnbot-space-2) var(--johnbot-space-1);
  color: var(--johnbot-text-muted);
  font-size: var(--wfn-small);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-sm);
}

.wfn-picker.ui-action-menu .wfn-picker-heading > svg {
  flex: none;
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  fill: currentcolor;
}

.wfn-picker.ui-action-menu .wfn-picker-row:is([role^="menuitem"]) {
  height: auto;
  min-height: calc(var(--johnbot-control-md) + var(--johnbot-space-2));
  gap: calc(var(--johnbot-space-2) + var(--johnbot-space-0-5));
  padding: var(--johnbot-space-1) var(--johnbot-space-2) var(--johnbot-space-1) var(--johnbot-space-1);
  border-radius: var(--wfn-radius-row);
  white-space: normal;
}

.wfn-picker.ui-action-menu .wfn-picker-row:is([role^="menuitem"])[data-checked] {
  background: var(--wfn-hover);
}

.wfn-picker.ui-action-menu
  .wfn-picker-row:is([role^="menuitem"])[data-checked]:is(:hover, :focus-visible, [data-highlighted]) {
  background: var(--wfn-ring-strong);
}

/* The tile holds the mark of a choice: a logo, an avatar, a swatch or a sample. */
.wfn-picker-tile {
  display: grid;
  flex: none;
  place-items: center;
  width: var(--johnbot-control-md);
  height: var(--johnbot-control-md);
  overflow: hidden;
  border-radius: var(--johnbot-radius-sm);
  background: var(--wfn-field);
  box-shadow: inset 0 0 0 1px var(--wfn-ring);
  color: var(--johnbot-text-secondary);
  transition: color var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

/*
 * A node kind in an add menu is only its icon in the colour of the kind, with no tile, so the
 * twelve kinds fit in short rows. A kind with no colour of its own has a neutral icon.
 */
.wfn-picker-tile[data-kind] {
  --wfn-kind: var(--johnbot-text-secondary);

  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  background: none;
  box-shadow: none;
  color: var(--wfn-kind);
}

/* The add menu is a little taller than the other lists, so all its kinds show with no scroll. */
.wfn-picker.ui-action-menu:has(.wfn-picker-tile[data-kind]) {
  max-height: min(560px, var(--kb-popper-content-available-height, 560px));
}

.wfn-picker.ui-action-menu .wfn-picker-row:has(> .wfn-picker-tile[data-kind]) {
  min-height: var(--johnbot-control-md);
  gap: var(--johnbot-space-2);
  padding: var(--johnbot-space-1) var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-md);
}

.wfn-picker-row[data-checked] .wfn-picker-tile {
  box-shadow: inset 0 0 0 1px var(--wfn-ring-strong);
  color: var(--johnbot-text-primary);
}

:is(.wfn-picker.ui-action-menu, .wfn-drop-menu) .wfn-picker-tile > svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  stroke-width: var(--johnbot-icon-stroke);
}

/* A provider logo is a filled mark. */
.wfn-picker.ui-action-menu .wfn-picker-tile > svg.wfn-model-logo,
.wfn-picker.ui-action-menu .wfn-picker-chip > svg.wfn-model-logo {
  fill: currentcolor;
  stroke: none;
}

.wfn-picker-tile > .wfn-swatch {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
}

/* An avatar has its own shape, so it has no tile box. The offset centres the face, as elsewhere. */
.wfn-picker-tile:has(> .agent-avatar),
.wfn-picker-row[data-checked] .wfn-picker-tile:has(> .agent-avatar) {
  overflow: visible;
  background: none;
  box-shadow: none;
}

.wfn-picker-tile > .agent-avatar {
  --agent-avatar-optical-offset: calc(var(--johnbot-control-sm) * -0.14);

  width: var(--johnbot-control-sm);
  height: var(--johnbot-control-sm);
}

.wfn-picker-tile > .wfn-font-sample {
  font-size: var(--johnbot-text-lg);
}

/* A text size shows "Aa" at a size that grows with the choice. */
.wfn-picker-tile > .wfn-font-sample[data-step="1"] {
  font-size: var(--johnbot-text-sm);
}

.wfn-picker-tile > .wfn-font-sample[data-step="3"] {
  font-size: var(--johnbot-text-2xl);
}

.wfn-picker-tile > .wfn-font-sample[data-step="4"] {
  font-size: var(--johnbot-text-3xl);
}

/* An aspect ratio shows its frame. The longer side is one icon long. */
.wfn-picker-aspect {
  width: calc(var(--johnbot-icon-md) * var(--wfn-aspect-w));
  height: calc(var(--johnbot-icon-md) * var(--wfn-aspect-h));
  border: 1.5px solid currentcolor;
  border-radius: var(--johnbot-radius-xs);
}

/* An effort shows five bars. The bars up to the level are lit. */
.wfn-picker-meter {
  display: flex;
  align-items: flex-end;
  gap: var(--johnbot-space-0-5);
  height: var(--johnbot-icon-md);
}

.wfn-picker-meter > i {
  width: 3px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--wfn-ring-strong);
}

.wfn-picker-meter > i[data-on] {
  background: currentcolor;
}

.wfn-picker-meter > i:nth-child(1) {
  height: 20%;
}

.wfn-picker-meter > i:nth-child(2) {
  height: 40%;
}

.wfn-picker-meter > i:nth-child(3) {
  height: 60%;
}

.wfn-picker-meter > i:nth-child(4) {
  height: 80%;
}

.wfn-picker-meter > i:nth-child(5) {
  height: 100%;
}

.wfn-picker-body {
  display: grid;
  flex: 1;
  gap: var(--johnbot-space-1);
  min-width: 0;
}

.wfn-picker-name {
  overflow: hidden;
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wfn-picker-chips {
  display: flex;
  flex-wrap: wrap;
  gap: var(--johnbot-space-1);
}

.wfn-picker-chip {
  display: inline-flex;
  align-items: center;
  gap: var(--johnbot-space-1);
  height: 18px;
  padding: 0 var(--johnbot-space-1-5);
  border-radius: var(--johnbot-radius-xs);
  background: var(--wfn-hover);
  /* Muted text on the chip's own fill is under 4.5:1 in the light theme. */
  color: var(--johnbot-text-secondary);
  font-size: var(--wfn-small);
  font-variant-numeric: tabular-nums;
  line-height: 1;
  white-space: nowrap;
}

.wfn-picker.ui-action-menu .wfn-picker-chip > svg {
  flex: none;
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
}

.wfn-picker.ui-action-menu .wfn-picker-row > svg.wfn-picker-check {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  margin-left: auto;
  color: var(--johnbot-text-primary);
}

.wfn-picker-empty {
  margin: 0;
  padding: var(--johnbot-space-4) var(--johnbot-space-3);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  text-align: center;
}

/*
 * The model picker keeps the layout of the one in the conversation header: a rail of provider logos
 * on the left, and the panel of the chosen provider. The panel has the picker style.
 */
.wfn-model-picker.wfn-picker.ui-action-menu {
  width: min(360px, calc(100vw - var(--johnbot-space-4)));
  max-width: none;
}

.wfn-model-layout {
  display: flex;
  min-height: 0;
  max-height: inherit;
}

.wfn-model-rail {
  display: flex;
  flex: none;
  flex-direction: column;
  align-items: center;
  gap: var(--johnbot-space-1);
  padding: var(--johnbot-space-2);
  border-right: 1px solid var(--wfn-ring-strong);
}

.wfn-model-tab-hint {
  display: flex;
}

/* The panel radius less the rail padding, so the tab and the panel corners are concentric. */
.wfn-model-tab {
  display: grid;
  place-items: center;
  width: var(--johnbot-control-lg);
  height: var(--johnbot-control-lg);
  padding: 0;
  border: 0;
  border-radius: var(--johnbot-radius-md);
  outline: 0;
  background: transparent;
  color: var(--johnbot-text-primary);
  cursor: pointer;
  transition: background-color var(--johnbot-duration-hover) var(--johnbot-ease-out);
}

.wfn-model-tab:hover {
  background: var(--wfn-hover);
}

.wfn-model-tab[data-selected] {
  background: var(--wfn-hover);
  box-shadow: inset 0 0 0 1px var(--wfn-ring-strong);
}

/* The shared accent focus outline goes; a neutral ring inside the tab shows the focus. */
.wfn-model-picker .wfn-model-tab:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 1px var(--johnbot-text-muted);
}

.wfn-model-tab > .wfn-model-mark {
  width: var(--johnbot-icon-lg);
  height: var(--johnbot-icon-lg);
  fill: currentcolor;
  opacity: 0.48;
  transition: opacity var(--johnbot-duration-hover) var(--johnbot-ease-out);
}

.wfn-model-tab:hover > .wfn-model-mark {
  opacity: 0.8;
}

.wfn-model-tab[data-selected] > .wfn-model-mark {
  opacity: 1;
}

.wfn-model-panel {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}

.wfn-model-heading {
  overflow: hidden;
  padding: var(--johnbot-space-3) var(--johnbot-space-3) var(--johnbot-space-1);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-md);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wfn-model-list {
  margin: 0;
  list-style: none;
}

.wfn-model-list .wfn-picker-row[role="option"] {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  min-height: calc(var(--johnbot-control-md) + var(--johnbot-space-2));
  /* With the list padding, the name starts on the line of the heading and the search icon. */
  padding: var(--johnbot-space-1) var(--johnbot-space-2) var(--johnbot-space-1) var(--johnbot-space-1-5);
  border-radius: var(--wfn-radius-row);
  outline: 0;
  color: var(--johnbot-text-primary);
  cursor: pointer;
  transition: background-color var(--johnbot-duration-hover) var(--johnbot-ease-out);
}

.wfn-model-list .wfn-picker-row[role="option"]:is(:hover, [data-highlighted], [data-selected]) {
  background: var(--wfn-hover);
}

.wfn-model-list .wfn-picker-row[role="option"][data-selected]:is(:hover, [data-highlighted]) {
  background: var(--wfn-ring-strong);
}

.ui-popover-menu-surface.wfn-popover {
  display: grid;
  gap: var(--johnbot-space-3);
  width: 344px;
  padding: var(--johnbot-space-3);
  border-radius: var(--wfn-radius-card);
  background: var(--wfn-glass);
  box-shadow: 0 0 0 1px var(--wfn-ring-strong);
  backdrop-filter: var(--wfn-glass-blur);
}

/* The title of a popover, with one action at the end, such as Upload. */
.wfn-popover-head {
  display: flex;
  gap: var(--johnbot-space-2);
  align-items: center;
  justify-content: space-between;
  margin-block: calc(var(--johnbot-space-1) * -1);
}

/* The action has the size of the title text. */
.wfn-popover-head .ui-button {
  font-size: var(--johnbot-text-sm);
}

.wfn-popover-title {
  margin: 0;
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-semibold);
}

.wfn-library {
  display: grid;
  gap: var(--johnbot-space-3);
}

/* Filter pills, as the Higgsfield library: a full pill, light text at half strength until active. */
.wfn-popover .wfn-library-tabs {
  padding: 0;
  background: transparent;
}

.wfn-popover .wfn-library-tabs .ui-sliding-tabs-trigger {
  border-radius: var(--johnbot-radius-pill);
  font-size: var(--johnbot-text-sm);
}

.wfn-popover .wfn-library-tabs .ui-sliding-tabs-pill {
  top: 0;
  border-radius: var(--johnbot-radius-pill);
  background: var(--wfn-ring-strong);
}

/* The search field: the quiet fill of the node fields, and the same 1px ring on focus. */
.wfn-library-search {
  display: flex;
  gap: var(--johnbot-space-1-5);
  align-items: center;
  height: var(--johnbot-control-md);
  padding: 0 var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-md);
  background: var(--wfn-field);
  transition: box-shadow var(--johnbot-duration-hover) var(--johnbot-ease-out);
}

.wfn-library-search:focus-within {
  box-shadow: inset 0 0 0 1px var(--wfn-ring-strong);
}

.wfn-library-search > svg {
  flex: none;
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  color: var(--johnbot-text-muted);
}

.wfn-popover .wfn-library-search .ui-input {
  flex: 1 1 auto;
  height: 100%;
  min-height: 0;
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
  font-size: var(--johnbot-text-sm);
}

.wfn-popover .wfn-library-search .ui-input:focus-visible {
  outline: none;
  box-shadow: none;
}

/* The scroll area: the shared fades mask its edges, and the native bar gives way to the thumb. */
.wfn-scroll {
  position: relative;
}

.wfn-library-scroll {
  max-height: 280px;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: none;
}

.wfn-library-scroll::-webkit-scrollbar {
  display: none;
}

.wfn-library-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--johnbot-space-2);
}

.wfn-library-empty {
  margin: 0;
  padding: var(--johnbot-space-6) var(--johnbot-space-2);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  text-align: center;
  text-wrap: pretty;
}

/* The thumb sits in the popover padding, so it never covers a tile. The track is 12px for the pointer. */
.wfn-scroll-track {
  position: absolute;
  top: 0;
  right: calc(-1 * var(--johnbot-space-3));
  bottom: 0;
  width: var(--johnbot-space-3);
}

.wfn-scroll-thumb {
  position: absolute;
  top: 0;
  left: 50%;
  width: var(--johnbot-space-1);
  border-radius: var(--johnbot-radius-pill);
  background: color-mix(in srgb, var(--johnbot-text-primary) 24%, transparent);
  opacity: 0;
  transition-property: opacity, width, background-color;
  transition-duration: var(--johnbot-duration-fast);
  transition-timing-function: var(--johnbot-ease-out);
}

.wfn-scroll:is(:hover, :focus-within) .wfn-scroll-thumb,
.wfn-scroll-track[data-dragging] .wfn-scroll-thumb {
  opacity: 1;
}

.wfn-scroll-track:hover .wfn-scroll-thumb,
.wfn-scroll-track[data-dragging] .wfn-scroll-thumb {
  width: var(--johnbot-space-1-5);
  background: color-mix(in srgb, var(--johnbot-text-primary) 40%, transparent);
}

/* One full column: a short name must not shrink the thumb. */
.wfn-popover .wfn-library-tile {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-content: start;
  gap: var(--johnbot-space-1);
  height: auto;
  padding: var(--johnbot-space-1);
  border-radius: var(--johnbot-radius-md);
  text-align: left;
}

.wfn-popover .wfn-library-tile[aria-pressed="true"] {
  box-shadow: inset 0 0 0 1px var(--johnbot-text-primary);
}

/* An inset ring, so the scroll area does not clip it, in the text colour and not the accent. */
.wfn-popover .wfn-library-tile:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--johnbot-text-primary) 40%, transparent);
}

.wfn-popover .wfn-library-tile[aria-pressed="true"]:focus-visible {
  box-shadow: inset 0 0 0 2px var(--johnbot-text-primary);
}

.wfn-library-thumb {
  display: grid;
  place-items: center;
  aspect-ratio: 1;
  overflow: hidden;
  border-radius: var(--johnbot-radius-sm);
  background: var(--wfn-hover);
}

.wfn-library-name {
  overflow: hidden;
  color: var(--johnbot-text-secondary);
  font-size: var(--wfn-small);
  font-weight: var(--johnbot-weight-regular);
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (prefers-reduced-motion: reduce) {
  .wfn-overlay {
    translate: 0 0;
  }
}

/* ---------------------------------------------------------- Connections */

.wfn-stage :is(.wfn-node, .wfn-text) {
  z-index: 1;
}

.wfn-edges {
  position: absolute;
  top: 0;
  left: 0;
  width: 1px;
  height: 1px;
  overflow: visible;
  pointer-events: none;
}

.wfn-edge {
  --wfn-edge: color-mix(in srgb, var(--johnbot-text-primary) 32%, transparent);

  color: var(--wfn-edge);
}

.wfn-edge[data-tone="done"] {
  --wfn-edge: color-mix(in srgb, var(--johnbot-text-primary) 60%, transparent);
}

.wfn-edge[data-tone="run"] {
  --wfn-edge: color-mix(in srgb, var(--johnbot-text-primary) 72%, transparent);
}

/* A selected edge is solid and bright, like the selected node ring. */
.wfn-edge[data-selected] {
  --wfn-edge: var(--johnbot-text-primary);
}

.wfn-edge[data-removing] {
  --wfn-edge: var(--johnbot-danger);
}

.wfn-edge-line,
.wfn-edge-comet,
.wfn-edge-draft {
  fill: none;
  stroke: currentcolor;
  stroke-linecap: round;
}

/* A connected edge is a thin dashed line, as on the Higgsfield canvas. */
.wfn-edge-line {
  stroke-width: 1.5;
  stroke-dasharray: 5 5;
  transition: color var(--johnbot-duration-hover) var(--johnbot-ease-out);
}

.wfn-edge:is([data-tone="done"], [data-selected]) .wfn-edge-line {
  stroke-dasharray: none;
}

.wfn-edge[data-motion] .wfn-edge-line {
  animation: wfn-march 1.2s linear infinite;
}

.wfn-edge:is([data-tone="done"], [data-selected]) .wfn-edge-line {
  animation: none;
}

@keyframes wfn-march {
  to {
    stroke-dashoffset: -10;
  }
}

/* The comet carries the answer of a done step into the step that runs now. */
.wfn-edge-comet {
  stroke: var(--johnbot-text-primary);
  stroke-width: 3;
  stroke-dasharray: 0.12 1;
  animation: wfn-comet 1.1s var(--johnbot-ease-out) infinite;
}

@keyframes wfn-comet {
  from {
    stroke-dashoffset: 0.12;
  }

  to {
    stroke-dashoffset: -1;
  }
}

.wfn-edge-hit {
  fill: none;
  stroke: transparent;
  stroke-width: 14;
  pointer-events: stroke;
  cursor: pointer;
}

.wfn-edge-draft {
  color: var(--johnbot-text-muted);
  stroke-width: 2;
  stroke-dasharray: 5 5;
  transition: color var(--johnbot-duration-hover) var(--johnbot-ease-out);
}

/* On a port that can take it, the line snaps to the port and turns solid. */
.wfn-edge-draft[data-state="ok"] {
  color: var(--johnbot-text-primary);
  stroke-dasharray: none;
}

.wfn-edge-draft[data-state="refused"] {
  color: var(--johnbot-danger);
}

/* A line back to an earlier node can end here too: it makes a loop. */
.wfn-edge-draft[data-state="loop"] {
  color: var(--johnbot-warning);
  stroke-dasharray: none;
}

/*
 * Why the line cannot end here, or that it makes a loop, next to the pointer. It keeps its screen
 * size at every zoom.
 */
.wfn-draft-reason {
  position: absolute;
  z-index: 3;
  padding: 2px var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-sm);
  background: var(--wfn-card);
  box-shadow: 0 0 0 1px var(--johnbot-danger-border);
  color: var(--johnbot-danger-text);
  font-size: var(--johnbot-text-sm);
  white-space: nowrap;
  pointer-events: none;
  transform-origin: 0 0;
  translate: calc(14px / var(--wfn-scale, 1)) calc(14px / var(--wfn-scale, 1));
  scale: calc(1 / var(--wfn-scale, 1));
}

.wfn-draft-reason[data-tone="loop"] {
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--johnbot-warning) 45%, transparent);
  color: var(--johnbot-warning-text);
}

/*
 * The remove button of a connection sits on the line at the point nearest to the pointer, and keeps
 * its screen size at every zoom. It takes the danger colour, and so does the line while the pointer is on it.
 */
.wfn-edge-actions {
  position: absolute;
  z-index: 2;
  display: flex;
  transform-origin: 0 0;
  translate: calc(-50% / var(--wfn-scale, 1)) calc(-50% / var(--wfn-scale, 1));
  scale: calc(1 / var(--wfn-scale, 1));
}

.wfn-stage .wfn-edge-actions .wfn-edge-remove {
  border-radius: var(--johnbot-radius-pill);
  background: color-mix(in srgb, var(--johnbot-danger) 14%, var(--wfn-card));
  box-shadow: 0 0 0 1px var(--johnbot-danger-border);
  color: var(--johnbot-danger-text);
  opacity: 1;
  scale: 1;
  transition-property: opacity, scale, background-color;
  transition-duration: var(--johnbot-duration-fast);
  transition-timing-function: var(--johnbot-ease-out);
}

.wfn-stage .wfn-edge-actions .wfn-edge-remove:hover {
  background: color-mix(in srgb, var(--johnbot-danger) 28%, var(--wfn-card));
  color: var(--johnbot-danger-text);
}

@starting-style {
  .wfn-stage .wfn-edge-actions .wfn-edge-remove {
    opacity: 0;
    scale: 0.6;
  }
}

@media (prefers-reduced-motion: reduce) {
  .wfn-stage .wfn-edge-actions .wfn-edge-remove {
    transition: none;
  }
}

/* A connected port stays visible; while you connect, the ports that cannot take the line dim. */
.wfn-stage .wfn-port[data-connected] {
  opacity: 1;
}

.wfn-stage .wfn-port:is([data-armed], [data-target]) {
  background: var(--johnbot-text-primary);
  color: var(--johnbot-bg-canvas);
  opacity: 1;
}

.wfn-stage .wfn-port[data-dim] {
  opacity: 0.25;
}

.wfn-stage .wfn-port[data-refused] {
  background: var(--johnbot-danger);
  color: var(--johnbot-text-primary);
  opacity: 1;
}

/* A hidden port waits at half size, so it grows in when it shows, as on Higgsfield. */
.wfn-stage
  .wfn-node:not(:hover, :focus-within, [data-selected])
  .wfn-port:not([data-connected], [data-armed], [data-target], [data-dim], [data-refused], [data-missing]) {
  scale: 0.5;
}

/*
 * A step that runs: a faint ring, and a bright arc that goes round the edge of the card, as a comet
 * goes along an edge. The arc is a conic gradient in a 1px frame over the ring; it has no glow.
 */
.wfn-node[data-status="running"] .wfn-card {
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--johnbot-text-primary) 16%, transparent);
}

.wfn-node[data-status="running"] .wfn-card-frame::before {
  content: "";
  position: absolute;
  z-index: 1;
  inset: -1.5px;
  padding: 1.5px;
  /* Resolved here, so the ring follows the card radius of each node size. */
  --wfn-radius-ring: calc(var(--wfn-radius-card) + 1.5px);
  border-radius: var(--wfn-radius-ring);
  background: conic-gradient(
    from var(--wfn-sweep),
    transparent 0turn 0.45turn,
    color-mix(in srgb, var(--johnbot-text-primary) 24%, transparent) 0.72turn,
    color-mix(in srgb, var(--johnbot-text-primary) 72%, transparent) 0.9turn,
    var(--johnbot-text-primary) 0.985turn,
    transparent 1turn
  );
  mask:
    linear-gradient(var(--johnbot-text-primary) 0 0) content-box,
    linear-gradient(var(--johnbot-text-primary) 0 0);
  mask-composite: exclude;
  pointer-events: none;
  animation: wfn-sweep 1.6s linear infinite;
}

@property --wfn-sweep {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0turn;
}

@keyframes wfn-sweep {
  to {
    --wfn-sweep: 1turn;
  }
}

/* The time of the run, at the end of the label row. When the run ends, it fades out after a moment. */
.wfn-run-time {
  display: inline-flex;
  gap: var(--johnbot-space-1);
  align-items: center;
  margin-inline-start: auto;
  color: var(--johnbot-text-secondary);
  font-weight: var(--johnbot-weight-medium);
  font-variant-numeric: tabular-nums;
  transition: opacity var(--johnbot-duration-hover) var(--johnbot-ease-out);

  @starting-style {
    opacity: 0;
  }
}

.wfn-run-time[data-done] {
  color: var(--johnbot-success-text);
  animation: wfn-run-time-out 1.8s var(--johnbot-ease-out) forwards;
}

/* A failed step keeps its mark until it runs again. */
.wfn-run-time[data-failed] {
  color: var(--johnbot-danger-text);
}

@keyframes wfn-run-time-out {
  0%,
  70% {
    opacity: 1;
  }

  to {
    opacity: 0;
  }
}

/* Lines that pulse in the result field stand for the result that the run makes. Each line takes the
   height of one line of text (8 + 8 = 16 px), so a result of three lines does not change the size of
   the card. */
.wfn-result-pending {
  display: grid;
  gap: var(--johnbot-space-2);
  padding-block: var(--johnbot-space-1);
}

.wfn-result-pending .ui-skeleton {
  min-height: var(--johnbot-space-2);
  background: color-mix(in srgb, var(--johnbot-text-primary) 9%, transparent);
}

.wfn-result-pending .ui-skeleton:nth-child(2) {
  width: 88%;
  animation-delay: 120ms;
}

.wfn-result-pending .ui-skeleton:nth-child(3) {
  width: 56%;
  animation-delay: 240ms;
}

/* When there is a last result, the lines cover it and it keeps its space. */
.wfn-result-body {
  position: relative;
}

.wfn-result-body[data-running] p {
  visibility: hidden;
}

.wfn-result-body p + .wfn-result-pending {
  position: absolute;
  inset: 0;
  align-content: start;
  overflow: hidden;
}

/* An image step that runs: a soft light goes across the picture, or across the empty frame. */
.wfn-node[data-status="running"] .wfn-card[data-media]::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    100deg,
    transparent 30%,
    color-mix(in srgb, var(--johnbot-text-primary) 12%, transparent) 50%,
    transparent 70%
  );
  background-size: 250% 100%;
  pointer-events: none;
  animation: wfn-sheen 1.4s var(--johnbot-ease-in-out) infinite;
}

@keyframes wfn-sheen {
  from {
    background-position: 100% 0;
  }

  to {
    background-position: 0% 0;
  }
}

/* --------------------------------------------------------------- Canvas */

/* The spring goes a little past its end and comes back. The palette has no spring ease. */
.wfn-art-layer {
  --wfn-art-spring: cubic-bezier(0.34, 1.35, 0.64, 1);
  transform-box: fill-box;
  transform-origin: 50% 50%;
  transition-property: rotate, translate, scale, opacity;
  transition-duration: var(--johnbot-duration-slow);
  transition-timing-function: var(--wfn-art-spring);
}

.wfn-art-color {
  fill: var(--wfn-art-color);
}

.wfn-art-face-light {
  fill: var(--wfn-art-light);
}

.wfn-art-face-dark {
  fill: var(--wfn-art-dark);
}

.wfn-art-gloss {
  fill: color-mix(in srgb, var(--johnbot-paper) 55%, transparent);
}

.wfn-art-wood {
  fill: var(--wfn-art-wood-color);
}

.wfn-art-wood-shade {
  fill: color-mix(in srgb, var(--wfn-art-wood-color) 84%, var(--johnbot-paper-text));
}

.wfn-art-rubber {
  fill: var(--johnbot-file-pink);
}

.wfn-art-rubber-shade {
  fill: color-mix(in srgb, var(--johnbot-file-pink) 80%, var(--johnbot-paper-text));
}

.wfn-art-metal {
  fill: var(--wfn-art-metal-color);
}

.wfn-art-metal-groove {
  fill: color-mix(in srgb, var(--wfn-art-metal-color) 70%, var(--johnbot-paper-text));
}

.wfn-art-tint-back {
  fill: color-mix(in srgb, var(--wfn-art-base) 36%, var(--wfn-card));
}

.wfn-art-tint-middle {
  fill: color-mix(in srgb, var(--wfn-art-base) 62%, var(--wfn-card));
}

.wfn-art-curl {
  fill: var(--wfn-art-light);
}

.wfn-art-stop-light {
  stop-color: var(--wfn-art-light);
}

.wfn-art-stop-color {
  stop-color: var(--wfn-art-base);
}

.wfn-art-stop-edge {
  stop-color: color-mix(in srgb, var(--johnbot-paper) 70%, transparent);
}

.wfn-art-stop-clear {
  stop-color: transparent;
}

/* A cut in the bar colour around each layer keeps the layers apart without a shadow. */
.wfn-art-cut {
  stroke: color-mix(in srgb, var(--johnbot-bg-surface-raised) 75%, var(--wfn-card));
  stroke-width: 2;
  stroke-linejoin: round;
  paint-order: stroke;
}

.wfn-art-edge {
  fill: none;
  stroke-width: 0.8;
  stroke-linejoin: round;
}

/* The pen and the eraser change places with a small zoom, as the icon of the other mode. */
.wfn-tool-art [data-layer="eraser"],
.wfn-tool-art[data-eraser] [data-layer="pen"] {
  opacity: 0;
  scale: 0.25;
}

.wfn-tool-art[data-eraser] [data-layer="eraser"] {
  opacity: 1;
  scale: 1;
}

/* At rest the layers at the back turn a little, so the stack reads as a stack. */
.wfn-tool-art [data-layer="back"] {
  rotate: -10deg;
}

.wfn-tool-art [data-layer="middle"] {
  rotate: 6deg;
}

.wfn-menu :is([role="menuitem"], [role="menuitemcheckbox"]) .wfn-keys {
  margin-left: auto;
  padding-left: var(--johnbot-space-4);
}

/* ------------------------------------------------------------ Minimap */

/* Shortcut keys, in tooltips and in menus. */
.wfn-keys {
  display: inline-flex;
  gap: 2px;
  align-items: center;
}

.wfn-keys .ui-kbd {
  min-width: 18px;
  height: 18px;
  border: 0;
  background: var(--wfn-hover);
  color: var(--johnbot-text-muted);
  font-family: inherit;
  font-size: var(--wfn-small);
}

.wfn-hint {
  display: inline-flex;
  gap: var(--johnbot-space-2);
  align-items: center;
}

/* The canvas tooltips have the 1px ring of the HUD and no shadow. */
.ui-tooltip.wfn-tooltip {
  border-radius: var(--johnbot-radius-md);
  box-shadow: 0 0 0 1px var(--johnbot-border-strong);
  font-weight: var(--johnbot-weight-medium);
}

.ui-tooltip.wfn-tooltip:has(.wfn-keys) {
  padding-right: var(--johnbot-space-1-5);
}

/* The results of the selected step, oldest first, under its card, as on the Higgsfield canvas. The
 * result on view is larger and has a full ring in the colour of its kind. The strip keeps its screen
 * size at every zoom, as the selection frame does. */
.wfn-strip {
  position: absolute;
  top: calc(100% + 8px / var(--wfn-scale, 1));
  left: round(50%, 1px);
  transform-origin: top center;
  scale: calc(1 / var(--wfn-scale, 1));
  z-index: 2;
  display: flex;
  gap: var(--johnbot-space-1);
  align-items: center;
  min-inline-size: 0;
  margin: 0;
  padding: 0;
  border: 0;
  color: var(--johnbot-text-secondary);
  translate: calc(round(-50%, 1px) + var(--wfn-snap-x, 0px) / var(--wfn-scale, 1))
    calc(var(--wfn-snap-y, 0px) / var(--wfn-scale, 1));
}

/* Seven results fit. More scroll, and the arrows move through all of them. */
.wfn-strip-list {
  display: flex;
  gap: var(--johnbot-space-1-5);
  align-items: center;
  max-width: calc(7 * 36px + 6 * var(--johnbot-space-1-5) + 16px);
  height: 52px;
  overflow-x: auto;
  padding: 0 var(--johnbot-space-1);
  scrollbar-width: none;
}

.wfn-strip-item {
  --wfn-strip-size: 36px;

  display: grid;
  flex: none;
  place-items: center;
  width: var(--wfn-strip-size);
  height: var(--wfn-strip-size);
  overflow: hidden;
  padding: 2px;
  border: 2px solid color-mix(in srgb, var(--wfn-kind) 40%, transparent);
  border-radius: var(--johnbot-radius-pill);
  background: var(--wfn-glass);
  color: var(--johnbot-text-secondary);
  font-size: var(--wfn-small);
  font-variant-numeric: tabular-nums;
  font-weight: var(--johnbot-weight-semibold);
  cursor: pointer;
  backdrop-filter: var(--wfn-glass-blur);
  transition-property: width, height, border-color, color, scale;
  transition-duration: var(--johnbot-duration-fast);
  transition-timing-function: var(--johnbot-ease-out);
}

.wfn-strip-item:hover {
  border-color: color-mix(in srgb, var(--wfn-kind) 72%, transparent);
  color: var(--johnbot-text-primary);
}

.wfn-strip-item[aria-pressed="true"] {
  --wfn-strip-size: 44px;

  border-color: var(--wfn-kind);
  color: var(--johnbot-text-primary);
}

.wfn-strip-item:active {
  scale: 0.96;
}

.wfn-strip-item:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--johnbot-text-primary) 40%, transparent);
  outline-offset: 1px;
}

.wfn-strip-item img {
  width: 100%;
  height: 100%;
  border-radius: var(--johnbot-radius-pill);
  object-fit: cover;
}

/* A failed run has no result, so its item shows a cross in place of an image or a number. */
.wfn-strip-item[data-failed] {
  color: var(--johnbot-danger-text);
}

.wfn-strip-failed {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

:is(.wfn-menu-icon, .wfn-picker-tile, .wfn-node, .wfn-minimap-node)[data-kind="text"] {
  --wfn-kind: var(--johnbot-file-teal);
}

:is(.wfn-menu-icon, .wfn-picker-tile, .wfn-node, .wfn-minimap-node)[data-kind="prompt"] {
  --wfn-kind: var(--johnbot-file-blue);
}

:is(.wfn-menu-icon, .wfn-picker-tile, .wfn-node, .wfn-minimap-node)[data-kind="asset"] {
  --wfn-kind: var(--johnbot-file-orange);
}

:is(.wfn-menu-icon, .wfn-picker-tile, .wfn-node, .wfn-minimap-node)[data-kind="llm"] {
  --wfn-kind: var(--johnbot-chart-storage-downloads);
}

:is(.wfn-menu-icon, .wfn-picker-tile, .wfn-node, .wfn-minimap-node)[data-kind="agent"] {
  --wfn-kind: var(--johnbot-file-green);
}

:is(.wfn-menu-icon, .wfn-picker-tile, .wfn-node, .wfn-minimap-node)[data-kind="image"] {
  --wfn-kind: var(--johnbot-file-pink);
}

@media (prefers-reduced-motion: reduce) {
  /* The arc stops and becomes a full ring; the light on an image stays at the centre. */
  .wfn-node[data-status="running"] .wfn-card-frame::before {
    background: color-mix(in srgb, var(--johnbot-text-primary) 56%, transparent);
    animation: none;
  }

  .wfn-node[data-status="running"] .wfn-card[data-media]::after {
    background-position: 50% 0;
    animation: none;
  }

  .wfn-run-time[data-done] {
    animation: none;
  }
}

/* ------------------------------------------------------------ Selection */

.wfn-card-frame {
  position: relative;
  display: grid;
}

/*
 * Selection is a neutral ring 3px outside the card, not a colour: the kind colours and the run ring
 * keep their meaning. An outline follows the card radius, so the ring stays concentric. The canvas
 * sets --wfn-scale, so the ring and the grip keep their size at every zoom.
 */
.wfn-node {
  --wfn-select-line: calc(1.5px / var(--wfn-scale, 1));
  --wfn-select-gap: calc(3px / var(--wfn-scale, 1));
}

/* A height that changes at once, as a reset or an undo, eases to its place, as the width does. */
.wfn-node .wfn-card {
  outline: var(--wfn-select-line) solid transparent;
  outline-offset: var(--wfn-select-gap);
  transition-property: box-shadow, outline-color, min-height, height;
  transition-duration:
    var(--johnbot-duration-hover), var(--johnbot-duration-hover), var(--johnbot-duration-slow),
    var(--johnbot-duration-slow);
  transition-timing-function: var(--johnbot-ease-out);
}

.wfn-node:not([data-selected]) .wfn-card-frame:hover .wfn-card {
  box-shadow: 0 0 0 1px var(--wfn-ring-strong);
}

.wfn-node[data-selected] .wfn-card {
  outline-color: color-mix(in srgb, var(--johnbot-text-primary) 40%, transparent);
}

.wfn-text {
  --wfn-select-line: calc(1px / var(--wfn-scale, 1));
  --wfn-select-gap: calc(4px / var(--wfn-scale, 1));
}

.wfn-text[data-selected] .wfn-text-input {
  outline: var(--wfn-select-line) solid color-mix(in srgb, var(--johnbot-text-primary) 32%, transparent);
  outline-offset: var(--wfn-select-gap);
}

/*
 * The resize grips: every corner and side resizes, but only the bottom-right corner shows a mark, a
 * short arc on the ring, concentric with the card (card radius + gap). So the card edge stays calm.
 */
.wfn-grip {
  --wfn-grip-size: calc(18px / var(--wfn-scale, 1));
  --wfn-grip-line: calc(3px / var(--wfn-scale, 1));
  --wfn-grip-out: calc(var(--wfn-select-gap) + var(--wfn-select-line) / 2 + var(--wfn-grip-line) / 2);
  --wfn-grip-radius: calc(var(--wfn-radius-card) + var(--wfn-grip-out));
  --wfn-grip-arc: var(--wfn-grip-line) solid var(--wfn-grip-color, transparent);
  /* The band of a side, centred on the selection ring. */
  --wfn-grip-band: calc(12px / var(--wfn-scale, 1));
  --wfn-grip-band-out: calc(var(--wfn-grip-out) * -1 - var(--wfn-grip-band) / 2);

  position: absolute;
  z-index: 2;
  box-sizing: border-box;
  width: var(--wfn-grip-size);
  height: var(--wfn-grip-size);
  transition: border-color var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

/* A larger target than the arc. */
.wfn-grip::after {
  position: absolute;
  inset: calc(-6px / var(--wfn-scale, 1));
  content: "";
}

/* The top corners and the bottom-left corner have no mark: the cursor shows the resize. */
.wfn-grip[data-corner="nw"] {
  top: calc(var(--wfn-grip-out) * -1);
  left: calc(var(--wfn-grip-out) * -1);
}

.wfn-grip[data-corner="ne"] {
  top: calc(var(--wfn-grip-out) * -1);
  right: calc(var(--wfn-grip-out) * -1);
}

.wfn-grip[data-corner="se"] {
  right: calc(var(--wfn-grip-out) * -1);
  bottom: calc(var(--wfn-grip-out) * -1);
  border-right: var(--wfn-grip-arc);
  border-bottom: var(--wfn-grip-arc);
  border-bottom-right-radius: var(--wfn-grip-radius);
}

.wfn-grip[data-corner="sw"] {
  bottom: calc(var(--wfn-grip-out) * -1);
  left: calc(var(--wfn-grip-out) * -1);
}

/* A side has no mark: the selection ring is the edge, and the cursor shows the resize. */
.wfn-grip[data-side] {
  z-index: 1;
  width: auto;
  height: auto;
}

.wfn-grip[data-side]::after {
  display: none;
}

.wfn-grip:is([data-corner="n"], [data-corner="s"]) {
  right: var(--wfn-grip-size);
  left: var(--wfn-grip-size);
  height: var(--wfn-grip-band);
}

.wfn-grip:is([data-corner="e"], [data-corner="w"]) {
  top: var(--wfn-grip-size);
  bottom: var(--wfn-grip-size);
  width: var(--wfn-grip-band);
}

.wfn-grip[data-corner="n"] {
  top: var(--wfn-grip-band-out);
}

.wfn-grip[data-corner="s"] {
  bottom: var(--wfn-grip-band-out);
}

.wfn-grip[data-corner="e"] {
  right: var(--wfn-grip-band-out);
}

.wfn-grip[data-corner="w"] {
  left: var(--wfn-grip-band-out);
}

/* The ports sit over the side bands, so a press on a port connects and does not resize. */
.wfn-ports {
  z-index: 1;
}

/* A text node is small and has no card, so its ring and grip are lighter and shorter. */
.wfn-text .wfn-grip {
  --wfn-grip-size: calc(12px / var(--wfn-scale, 1));
  --wfn-grip-line: calc(2px / var(--wfn-scale, 1));
  --wfn-grip-radius: calc(var(--johnbot-radius-sm) + var(--wfn-grip-out));
}

.wfn-node:is(:hover, [data-selected]) .wfn-grip {
  --wfn-grip-color: color-mix(in srgb, var(--johnbot-text-primary) 32%, transparent);
}

.wfn-node[data-selected] .wfn-grip,
.wfn-node[data-resizing] .wfn-grip,
.wfn-grip:hover {
  --wfn-grip-color: var(--johnbot-text-primary);
}

/*
 * While a Delete control points at nodes, or the confirmation is open, the nodes that go have a danger
 * ring, and their connections take it too.
 */
.wfn-node[data-doomed] .wfn-card {
  outline-color: var(--johnbot-danger);
}

.wfn-text[data-doomed] .wfn-text-input {
  outline: var(--wfn-select-line) solid var(--johnbot-danger);
  outline-offset: var(--wfn-select-gap);
}

.wfn-node[data-doomed] .wfn-grip {
  --wfn-grip-color: var(--johnbot-danger);
}

.wfn-grip[data-cursor="ew"] {
  cursor: ew-resize;
}

.wfn-grip[data-cursor="ns"] {
  cursor: ns-resize;
}

.wfn-grip[data-cursor="nwse"] {
  cursor: nwse-resize;
}

.wfn-grip[data-cursor="nesw"] {
  cursor: nesw-resize;
}

/* A step with a height that the user set gives the extra room to its task. */
.wfn-node[data-height] .wfn-card:has(> .wfn-field-task) {
  grid-template-rows: 1fr;
}

/* A locked node shows a lock after its label and takes no drag. */
.wfn-node[data-locked] :is(.wfn-label, .wfn-card) {
  cursor: default;
}

.wfn-lock-badge {
  display: inline-flex;
  color: var(--johnbot-text-muted);
}

.wfn-lock-badge svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
}

.wfn-text[data-sized] .wfn-text-input {
  width: 100%;
}

/* The ring of a selected node shows the focus from the keyboard too. */
.wfn-node:focus-visible {
  outline: none;
}

.wfn-node:not(.wfn-text):focus-visible:not([data-selected]) .wfn-card {
  outline-color: color-mix(in srgb, var(--johnbot-text-primary) 40%, transparent);
}

/* ------------------------------------------------------------ Run status */

.wfn-hud-spin {
  animation: wfn-spin 1s linear infinite;
}

@keyframes wfn-spin {
  to {
    rotate: 360deg;
  }
}

@media (prefers-reduced-motion: reduce) {
  .wfn-hud-spin {
    animation: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .wfn-art-layer {
    transition: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .wfn-node,
  .wfn-node .wfn-card,
  .wfn-stage .wfn-port,
  .wfn-grip {
    transition: none;
  }
}

/* ---------------------------------------------------------- Scroll fades */

/*
 * Content that scrolls fades out at an edge where more of it is. Each fade grows over the first or the
 * last fade size of the scroll, so an edge at the start or the end stays sharp. The ranges are lengths,
 * not parts of the scroll range: content that fits gets no fade, also where the engine puts a timeline
 * with no scroll range at its end.
 */
@property --wfn-fade-start {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@property --wfn-fade-end {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

.wfn-node :is(textarea, .wfn-field-result p),
.wfn-strip-list {
  --wfn-fade-size: var(--johnbot-space-4);
  --wfn-fade-side: to bottom;

  mask-image: linear-gradient(
    var(--wfn-fade-side),
    transparent,
    var(--johnbot-text-primary) var(--wfn-fade-start),
    var(--johnbot-text-primary) calc(100% - var(--wfn-fade-end)),
    transparent
  );
  animation:
    wfn-fade-start linear both,
    wfn-fade-end linear both;
  animation-timeline: scroll(self block), scroll(self block);
  animation-range:
    0 var(--wfn-fade-size),
    calc(100% - var(--wfn-fade-size)) 100%;
}

.wfn-strip-list {
  --wfn-fade-size: var(--johnbot-space-6);
  --wfn-fade-side: to right;

  animation-timeline: scroll(self inline), scroll(self inline);
}

@keyframes wfn-fade-start {
  from {
    --wfn-fade-start: 0px;
  }

  to {
    --wfn-fade-start: var(--wfn-fade-size);
  }
}

@keyframes wfn-fade-end {
  from {
    --wfn-fade-end: var(--wfn-fade-size);
  }

  to {
    --wfn-fade-end: 0px;
  }
}

/* ---------------------------------------------------------------- Size */

.wfn-node[data-kind="trigger"],
.wfn-node[data-kind="output"] {
  --wfn-width: 280px;
}

.wfn-node[data-kind="condition"],
.wfn-node[data-kind="approval"] {
  --wfn-width: 300px;
}

.wfn-node[data-kind="note"] {
  --wfn-width: 240px;
  --wfn-height: 240px;
}

/* The edge of a rectangle, the selection ring and the resize arc share one radius, so they stay
 * concentric. */
.wfn-node[data-kind="shape"] {
  --wfn-width: 208px;
  --wfn-height: 128px;
  --wfn-radius-card: var(--johnbot-radius-md);
}

/* --------------------------------------------------------------- Kinds */

:is(.wfn-menu-icon, .wfn-picker-tile, .wfn-node, .wfn-minimap-node)[data-kind="trigger"] {
  --wfn-kind: var(--johnbot-file-yellow);
}

:is(.wfn-menu-icon, .wfn-picker-tile, .wfn-node, .wfn-minimap-node)[data-kind="condition"] {
  --wfn-kind: var(--johnbot-chart-series-codex);
}

:is(.wfn-menu-icon, .wfn-picker-tile, .wfn-node, .wfn-minimap-node)[data-kind="output"] {
  --wfn-kind: var(--johnbot-chart-storage-workspaces);
}

:is(.wfn-menu-icon, .wfn-picker-tile, .wfn-node, .wfn-minimap-node)[data-kind="approval"] {
  --wfn-kind: var(--johnbot-chart-storage-files);
}

:is(.wfn-menu-icon, .wfn-picker-tile, .wfn-node, .wfn-minimap-node)[data-kind="note"] {
  --wfn-kind: var(--johnbot-file-yellow);
}

:is(.wfn-menu-icon, .wfn-picker-tile, .wfn-node, .wfn-minimap-node)[data-kind="shape"] {
  --wfn-kind: var(--johnbot-text-secondary);
}

/* -------------------------------------------------------------- Fields */

.wfn-block-meta {
  display: inline-flex;
  gap: var(--johnbot-space-1);
  align-items: center;
  min-width: 0;
  overflow: hidden;
  color: var(--johnbot-text-muted);
  font-size: var(--wfn-small);
  line-height: var(--johnbot-leading-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wfn-block-copy {
  display: flex;
  gap: var(--johnbot-space-1);
  align-items: center;
  min-width: 0;
}

.wfn-block-url {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  color: var(--johnbot-text-secondary);
  font-family: var(--johnbot-font-mono);
  font-size: var(--wfn-small);
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* A pill alone on its row keeps its own width. */
.wfn-stage .wfn-block-field > .wfn-pill {
  justify-self: start;
}

.wfn-block-field > .wfn-field-foot {
  justify-content: flex-start;
}

.wfn-block-field > .wfn-field-foot > .wfn-block-meta {
  margin-left: auto;
}

.wfn-block-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--johnbot-space-2);
}

/* ------------------------------------------------------------ Branches */

/* Each branch row holds its output port on the right edge of the card, as a node holds its output. */
.wfn-branch {
  position: relative;
  display: flex;
  gap: var(--johnbot-space-2);
  align-items: center;
  min-height: var(--johnbot-control-sm);
  padding: 0 var(--johnbot-space-3);
  border-radius: var(--johnbot-radius-md);
  background: var(--wfn-field);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
  transition: opacity var(--johnbot-duration-hover) var(--johnbot-ease-out);
}

.wfn-branch[data-skipped] {
  opacity: 0.5;
}

.wfn-branch-check {
  display: inline-grid;
  margin-left: auto;
  color: var(--johnbot-success);
}

.wfn-branch-check svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.wfn-branch-port {
  position: absolute;
  top: 50%;
  left: calc(100% + var(--johnbot-space-2) + 6px);
  translate: 0 -50%;
}

/* The name of a branch rides on its line, at the middle. */
.wfn-edge-label {
  position: absolute;
  z-index: 1;
  padding: 0 var(--johnbot-space-1-5);
  border-radius: var(--johnbot-radius-pill);
  background: var(--wfn-card);
  box-shadow: 0 0 0 1px var(--wfn-ring-strong);
  color: var(--johnbot-text-secondary);
  font-size: var(--wfn-small);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-sm);
  text-transform: capitalize;
  pointer-events: none;
  translate: -50% -50%;
}

/*
 * A loop shows where it goes back under its nodes. With no condition to end it, it takes the warning
 * colour: the run repeats it until the user stops the run.
 */
.wfn-edge-loop {
  position: absolute;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  gap: var(--johnbot-space-1);
  padding: 0 var(--johnbot-space-2) 0 var(--johnbot-space-1-5);
  border-radius: var(--johnbot-radius-pill);
  background: var(--wfn-card);
  box-shadow: 0 0 0 1px var(--wfn-ring-strong);
  color: var(--johnbot-text-secondary);
  font-size: var(--wfn-small);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-sm);
  white-space: nowrap;
  pointer-events: none;
  translate: -50% -50%;
}

.wfn-edge-loop svg {
  width: 0.875em;
  height: 0.875em;
}

.wfn-edge-loop[data-endless] {
  /* The soft warning is translucent, so the card under it hides the line. */
  background: linear-gradient(var(--johnbot-warning-soft) 0 0), var(--wfn-card);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--johnbot-warning) 45%, transparent);
  color: var(--johnbot-warning-text);
}

/* ---------------------------------------------------------------- Note */

/*
 * A note is coloured paper, as on Higgsfield. The paper keeps the hue of the note colour at a fixed
 * lightness, so a note is the same pastel in the dark and the light theme, where the palette
 * darkens each colour for text. A 1px edge in a deeper tint frames it.
 */
:is(.wfn-node, .wfn-ghost)[data-kind="note"] {
  --wfn-note-paper: oklch(from var(--wfn-note) 0.88 calc(c * 0.5) h);
  --wfn-note-edge: oklch(from var(--wfn-note) 0.76 calc(c * 0.6) h);
}

.wfn-node[data-kind="note"] .wfn-card {
  grid-template-rows: minmax(0, 1fr) auto;
  align-content: stretch;
  height: var(--wfn-height);
  padding: var(--johnbot-space-4) var(--johnbot-space-4) var(--johnbot-space-3);
  background: var(--wfn-note-paper);
  box-shadow: 0 0 0 1px var(--wfn-note-edge);
}

.wfn-stage .wfn-note-input {
  height: 100%;
  overflow-y: auto;
  color: var(--wfn-note-ink);
  font-size: var(--johnbot-text-2xl);
  font-weight: var(--johnbot-weight-medium);
  line-height: 1.35;
  text-wrap: pretty;
  field-sizing: fixed;
  scrollbar-width: none;
}

.wfn-stage .wfn-note-input::placeholder {
  color: var(--johnbot-paper-text-dim);
}

.wfn-stage .wfn-note-input[data-font="mono"] {
  font-family: var(--johnbot-font-mono);
}

.wfn-stage .wfn-note-input[data-text-size="lg"] {
  font-size: var(--johnbot-text-lg);
}

.wfn-stage .wfn-note-input[data-text-size="3xl"] {
  font-size: var(--johnbot-text-3xl);
  letter-spacing: var(--johnbot-tracking-tight);
}

.wfn-stage .wfn-note-input[data-text-size="display"] {
  font-size: var(--johnbot-text-display);
  line-height: 1.2;
  letter-spacing: var(--johnbot-tracking-tight);
}

.wfn-stage .wfn-note-input[data-bold] {
  font-weight: var(--johnbot-weight-bold);
}

.wfn-note-author {
  overflow: hidden;
  color: var(--johnbot-paper-text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-sm);
  white-space: nowrap;
  text-overflow: ellipsis;
  user-select: none;
}

/* The font menu shows each font in itself. */
.wfn-font-sample {
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-semibold);
  line-height: 1;
}

.wfn-font-sample[data-font="mono"] {
  font-family: var(--johnbot-font-mono);
}

.wfn-swatch {
  flex: none;
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  border-radius: var(--johnbot-radius-pill);
  background: var(--wfn-swatch);
  box-shadow: inset 0 0 0 1px var(--wfn-ring-strong);
}

/* -------------------------------------------------------------- States */

.wfn-alert {
  display: flex;
  gap: var(--johnbot-space-2);
  align-items: center;
  min-width: 0;
  margin: 0;
  padding: var(--johnbot-space-1-5) var(--johnbot-space-2) var(--johnbot-space-1-5) var(--johnbot-space-3);
  border-radius: var(--johnbot-radius-md);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  transition: opacity var(--johnbot-duration-hover) var(--johnbot-ease-out);
}

.wfn-alert > svg {
  flex: none;
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.wfn-alert-text {
  display: -webkit-box;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  overflow-wrap: anywhere;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}

.wfn-alert[data-tone="danger"] {
  background: var(--johnbot-danger-soft);
  color: var(--johnbot-danger-text);
}

.wfn-alert[data-tone="warning"] {
  background: var(--johnbot-warning-soft);
  color: var(--johnbot-warning-text);
}

.wfn-alert[data-tone="success"] {
  background: var(--johnbot-success-soft);
  color: var(--johnbot-success-text);
}

/* The last answer stays in its place while the step runs again, so the card does not change size. */
.wfn-alert[data-stale] {
  opacity: 0.5;
}

/* Before the first answer, a line that pulses holds the place of the answer at the same height. */
.wfn-alert[data-pending] {
  background: var(--wfn-field);
}

.wfn-alert[data-pending] .ui-skeleton {
  width: 64%;
  min-height: var(--johnbot-space-2);
  margin-block: var(--johnbot-space-1);
  background: color-mix(in srgb, var(--johnbot-text-primary) 9%, transparent);
}

.wfn-stage .wfn-alert .ui-button {
  flex: none;
  color: inherit;
}

.wfn-node[data-status="approval"] .wfn-card {
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--johnbot-warning) 64%, transparent);
}

/* A required input with no line stays visible in the warning colour. */
.wfn-stage .wfn-port[data-missing]:not([data-target], [data-armed]) {
  background: var(--johnbot-warning-soft);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--johnbot-warning) 64%, transparent);
  color: var(--johnbot-warning-text);
  opacity: 1;
}

/* An agent that the user deleted. */
.wfn-stage .wfn-pill[data-missing] {
  color: var(--johnbot-warning-text);
}

.wfn-stage .wfn-pill[data-missing] > svg:first-child {
  color: inherit;
}

.wfn-pill-action {
  color: var(--johnbot-text-muted);
}

/* ----------------------------------------------------------- Long text */

/* Long text scrolls inside its field, so the node keeps its layout. */
.wfn-stage :is(.wfn-field-task, .wfn-field-fill, .wfn-field-system, .wfn-block-field) .wfn-input {
  max-height: 200px;
  overflow-y: auto;
}

/* A card with a height that the user set gives all its room to the main field. */
.wfn-stage .wfn-node[data-height] :is(.wfn-field-task, .wfn-field-fill) .wfn-input {
  max-height: none;
}

.wfn-stage .wfn-pill > span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wfn-stage .wfn-pill > :is(svg, .wfn-avatar) {
  flex: none;
}

/* --------------------------------------------------------------- Shape */

/* A shape has no label. The lock badge of a locked shape sits above its top-left corner. */
.wfn-label[data-bare] {
  position: absolute;
  bottom: 100%;
  left: 0;
  margin-bottom: var(--johnbot-space-1-5);
}

.wfn-stage .wfn-node[data-kind="shape"] .wfn-card {
  grid-template-rows: none;
  align-content: center;
  place-items: center;
  height: var(--wfn-height);
  padding: var(--johnbot-space-3);
  background: transparent;
  box-shadow: none;
}

/* The outline of the shape shows the hover, not the ring of the card. */
.wfn-stage .wfn-node[data-kind="shape"]:not([data-selected]) .wfn-card-frame:hover .wfn-card {
  box-shadow: none;
}

.wfn-shape-surface {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
}

span.wfn-shape-surface {
  border-radius: var(--wfn-radius-card);
  background: color-mix(in srgb, var(--wfn-shape) 16%, transparent);
  box-shadow: inset 0 0 0 2px var(--wfn-shape);
}

span.wfn-shape-surface:is([data-shape="circle"], [data-shape="oval"]) {
  border-radius: var(--johnbot-radius-pill);
}

svg.wfn-shape-surface {
  fill: color-mix(in srgb, var(--wfn-shape) 16%, transparent);
  stroke: var(--wfn-shape);
  stroke-width: 2;
  stroke-linejoin: round;
}

/* In the light theme, ink is near the darkest tone. A Default shape takes a soft fill and a thinner edge there. */
:root[data-johnbot-color-scheme="light"] span.wfn-shape-surface[data-color="ink"] {
  background: color-mix(in srgb, var(--wfn-shape) 5%, transparent);
  box-shadow: inset 0 0 0 1.5px var(--wfn-shape);
}

:root[data-johnbot-color-scheme="light"] svg.wfn-shape-surface[data-color="ink"] {
  fill: color-mix(in srgb, var(--wfn-shape) 5%, transparent);
  stroke-width: 1.5;
}

/* The words sit at the centre of the shape, and the field grows with them. */
.wfn-stage .wfn-shape-input {
  position: relative;
  width: 100%;
  max-height: 100%;
  overflow: hidden;
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-md);
  text-align: center;
  field-sizing: content;
}

.wfn-shape-icon {
  flex: none;
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.wfn-stage .wfn-toolbar-select :is(.wfn-shape-icon, .wfn-swatch) {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  color: var(--johnbot-text-primary);
}

@media (prefers-reduced-motion: reduce) {
  .wfn-branch {
    transition: none;
  }
}

/* === from: @johnbot/ui/features/workflows/workflows.css === */
/*
 * The workflow canvas: the stage, the HUD, the tool bar, the search, the minimap, the zoom, the version
 * bar, the Undo toast of a delete and the in-app frame. The nodes use workflow-nodes.css.
 */

:where(.wfn-stage) {
  /* A control in the tool bar: the bar radius less the bar padding. */
  --wfn-tool-radius: calc(var(--johnbot-radius-grouped) - var(--johnbot-space-1-5));
  /* The canvas inside the window card: the card radius less its 1px border. */
  --wfn-card-inner-radius: calc(var(--johnbot-radius-card) - 1px);
}

.wfn-stage {
  display: flex;
  flex-wrap: wrap;
  gap: 120px;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 120px var(--johnbot-space-8);
  background-color: var(--johnbot-bg-frame);
  background-image: radial-gradient(
    color-mix(in srgb, var(--johnbot-text-primary) 9%, transparent) 1px,
    transparent 1px
  );
  background-size: 20px 20px;
  color: var(--johnbot-text-primary);
  font-family: var(--johnbot-font-sans);
}

/* ------------------------------------------------------ Menus, library */

.wfn-menu-text {
  font-size: var(--johnbot-text-sm);
}

.wfn-menu-meta {
  color: var(--johnbot-text-muted);
  font-size: var(--wfn-small);
}

.wfn-menu-check {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  margin-left: auto;
  color: var(--johnbot-text-primary);
}

/* ---------------------------------------------------------- Connections */

.wfn-stage {
  position: relative;
}

/* On a screen with one device pixel for each CSS pixel, a line of 1.5 in a 24px icon that shows at 14px or 16px is
 * thinner than a pixel, so it shows faint and soft. A line of 2 fills whole pixels. */
@media (max-resolution: 1.5dppx) {
  .wfn-stage {
    --johnbot-icon-stroke: 2;
  }
}

/* --------------------------------------------------------------- Canvas */

.wfn-stage.wfn-canvas {
  display: block;
  height: 100vh;
  min-height: 0;
  padding: 0;
  overflow: hidden;
  background-image: none;
}

.wfn-viewport {
  position: absolute;
  inset: 0;
  overflow: hidden;
  cursor: default;
  touch-action: none;
}

/*
 * The canvas fades out at the edges of the view, so a node that the view cuts does not end on a hard
 * line. The fade is over the world and under the bars, the cursors and the selection box.
 */
.wfn-viewport::after {
  --wfn-edge-fade: var(--johnbot-space-8);

  position: absolute;
  inset: 0;
  z-index: 1;
  content: "";
  background:
    linear-gradient(to right, var(--johnbot-bg-frame), transparent) left / var(--wfn-edge-fade) 100% no-repeat,
    linear-gradient(to left, var(--johnbot-bg-frame), transparent) right / var(--wfn-edge-fade) 100% no-repeat,
    linear-gradient(to bottom, var(--johnbot-bg-frame), transparent) top / 100% var(--wfn-edge-fade) no-repeat,
    linear-gradient(to top, var(--johnbot-bg-frame), transparent) bottom / 100% var(--wfn-edge-fade) no-repeat;
  pointer-events: none;
}

/* The dot grid fades out toward the edges of the view, as on the Higgsfield canvas. A mask reads only
 * the alpha, so any opaque colour serves. */
.wfn-dots {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  mask-image: radial-gradient(ellipse 85% 75% at 50% 50%, var(--johnbot-text-primary) 45%, transparent 100%);
  pointer-events: none;
}

.wfn-dots circle {
  fill: color-mix(in srgb, var(--johnbot-text-primary) 15%, transparent);
}

/* A drag on the empty canvas draws a selection box; Space held turns it into a pan. */
.wfn-viewport[data-space] {
  cursor: grab;
}

.wfn-viewport:is([data-panning], [data-dragging]) {
  cursor: grabbing;
  user-select: none;
}

/* A size that goes back to its default eases there too. */
.wfn-world {
  position: absolute;
  top: 0;
  left: 0;
  transform-origin: 0 0;
  interpolate-size: allow-keywords;
}

/* While the camera glides, the nodes that pass under a still pointer show no hover. */
.wfn-viewport[data-camera-moving] .wfn-world {
  pointer-events: none;
}

/* The world has no width, so a slot sizes to its content and free text does not wrap. */
.wfn-slot {
  position: absolute;
  width: max-content;
  cursor: default;
}

.wfn-slot :is(.wfn-label, .wfn-card) {
  cursor: grab;
}

.wfn-viewport[data-dragging] .wfn-slot :is(.wfn-label, .wfn-card) {
  cursor: grabbing;
}

/*
 * The HUD: every bar over the canvas is one glass bar, 40px high, with a 4px inset. Controls inside
 * are 32px with an 8px radius, so the bar radius is 8 + 4 = 12. The bars come in one after another.
 */
.wfn-canvas {
  /* The space between the bottom bars and the edges of the canvas. */
  --wfn-hud-inset: var(--johnbot-space-4);

  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.wfn-hud {
  position: absolute;
  z-index: 3;
  display: flex;
  gap: 2px;
  align-items: center;
  height: calc(var(--johnbot-control-md) + var(--johnbot-space-2));
  padding: var(--johnbot-space-1);
  border-radius: var(--johnbot-radius-lg);
  background: var(--wfn-glass);
  box-shadow: 0 0 0 1px var(--wfn-ring-strong);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  backdrop-filter: var(--wfn-glass-blur);
}

.wfn-hud-top {
  position: absolute;
  top: var(--johnbot-space-4);
  right: var(--johnbot-space-4);
  left: var(--johnbot-space-4);
  z-index: 3;
  display: flex;
  gap: var(--johnbot-space-2);
  align-items: flex-start;
  justify-content: space-between;
  pointer-events: none;
}

.wfn-hud-top .wfn-hud {
  position: relative;
  pointer-events: auto;
}

.wfn-hud-group {
  display: flex;
  gap: var(--johnbot-space-2);
  align-items: center;
}

/* The tool bar: tools, then Search, then Add node as the one primary action. */
.wfn-hud-tools {
  bottom: var(--wfn-hud-inset);
  left: round(50%, 1px);
  translate: round(-50%, 1px) 0;
}

.wfn-stage .wfn-hud-add-button {
  margin-left: var(--johnbot-space-1);
}

/* A pressed tool, such as Select or an open minimap: a quiet fill, not a colour. */
.wfn-stage .wfn-hud .wfn-hud-tool[aria-pressed="true"] {
  background: var(--wfn-hover);
  color: var(--johnbot-text-primary);
}

/* The icon of a pressed tool is full. Most icons have lines inside, which a full fill hides, so they take a part fill.
 * The Select arrow is one closed shape, so it fills whole. */
.wfn-stage .wfn-hud .wfn-hud-tool[aria-pressed="true"] svg.lucide {
  fill: currentcolor;
  fill-opacity: 0.35;
}

.wfn-stage .wfn-hud .wfn-hud-tool[aria-pressed="true"] svg.wfn-hud-arrow {
  fill-opacity: 1;
}

.wfn-stage .wfn-hud .wfn-hud-tool svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
}

/* The workflow switcher: the name and a small chevron in one button. The name has the type of the other page titles. */
.wfn-stage .wfn-hud-title .wfn-hud-switcher {
  gap: var(--johnbot-space-1-5);
  min-width: 0;
  padding-inline: var(--johnbot-space-3) calc(var(--johnbot-space-2) + var(--johnbot-space-0-5));
}

.wfn-stage .wfn-hud-switcher-name {
  overflow: hidden;
  max-width: 40ch;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wfn-stage .wfn-hud-switcher .wfn-hud-chevron {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  color: var(--johnbot-text-muted);
}

/* In the desktop window, the page lets clicks through to the server menu in the top row. The parts of the canvas take
 * them back; the top row of the canvas starts after the server menu. */
.wfn-canvas[data-frame="window"] > * {
  pointer-events: auto;
}

/* The Draw tool draws over the nodes, and Sticky note and Shapes place over them, so the nodes do not take a press. */
.wfn-canvas:is([data-tool="draw"], [data-tool="note"], [data-tool="shape"]) .wfn-world * {
  pointer-events: none;
}

/* The pan tool takes every press on the canvas, nodes too. */
.wfn-canvas[data-tool="pan"] .wfn-viewport,
.wfn-canvas[data-tool="pan"] .wfn-slot :is(.wfn-label, .wfn-card, .wfn-card *) {
  cursor: grab;
}

.wfn-canvas[data-tool="pan"] .wfn-viewport[data-panning],
.wfn-canvas[data-tool="pan"] .wfn-viewport[data-panning] * {
  cursor: grabbing;
}

.wfn-canvas[data-tool="draw"] .wfn-viewport {
  cursor: crosshair;
}

.wfn-canvas[data-draw="eraser"] .wfn-viewport {
  cursor: none;
}

/* The options of the Draw, Sticky note and Shapes tools sit above the tool bar, at its centre. */
.wfn-hud.wfn-hud-sub {
  right: 0;
  bottom: calc(var(--wfn-hud-inset) + var(--johnbot-control-lg) + var(--johnbot-space-3) + var(--johnbot-space-2));
  left: 0;
  gap: var(--johnbot-space-1);
  width: fit-content;
  margin-inline: auto;
}

.wfn-stage .wfn-hud-sub .wfn-hud-tool {
  width: var(--johnbot-control-md);
}

.wfn-stage .wfn-hud-sub .wfn-shape-icon {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
}

/* The shape colour: the picked colour and a chevron, as the colour button of Higgsfield. */
.wfn-stage .wfn-hud .wfn-hud-fill {
  gap: var(--johnbot-space-1);
  padding-inline: var(--johnbot-space-2) var(--johnbot-space-1-5);
}

.wfn-stage .wfn-hud-fill .wfn-hud-chevron {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  color: var(--johnbot-text-muted);
}

/*
 * The item that Sticky note or Shapes puts down shows at half strength under the pointer, at its
 * size on the canvas, with its centre on the pointer.
 */
.wfn-ghost {
  position: absolute;
  z-index: 3;
  opacity: 0.5;
  translate: -50% -50%;
  pointer-events: none;
  animation: wfn-fade-in var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

/* A shape that a drag draws grows from the corner where the drag started. */
.wfn-ghost[data-drawn] {
  translate: none;
  animation: none;
}

.wfn-ghost[data-kind="note"] {
  border-radius: var(--wfn-radius-card);
  background: var(--wfn-note-paper);
  box-shadow: 0 0 0 1px var(--wfn-note-edge);
}

.wfn-ghost span.wfn-shape-surface {
  background: color-mix(in srgb, var(--wfn-shape) 16%, transparent);
  box-shadow: none;
  outline: 1px dashed var(--wfn-shape);
  outline-offset: -1px;
}

.wfn-ghost svg.wfn-shape-surface {
  stroke-dasharray: 4 3;
  stroke-width: 1;
}

.wfn-ink-dot {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  border-radius: var(--johnbot-radius-pill);
  background: var(--wfn-ink);
  box-shadow: inset 0 0 0 1px var(--wfn-ring-strong);
  transition-property: box-shadow;
  transition-duration: var(--johnbot-duration-fast);
  transition-timing-function: var(--johnbot-ease-out);
}

/* The picked colour has a ring in the text colour, with a gap of the bar colour. */
.wfn-stage .wfn-hud .wfn-ink-swatch[aria-pressed="true"] {
  background: transparent;
}

.wfn-ink-swatch[aria-pressed="true"] .wfn-ink-dot {
  box-shadow:
    0 0 0 2px var(--wfn-glass),
    0 0 0 3.5px var(--johnbot-text-primary);
}

/* The lines: in canvas units, so a zoom scales them with the nodes. */
.wfn-ink {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 2;
  width: 1px;
  height: 1px;
  overflow: visible;
  pointer-events: none;
}

.wfn-ink-line {
  fill: none;
  stroke: var(--wfn-ink);
  stroke-linecap: round;
  stroke-linejoin: round;
  transition-property: opacity;
  transition-duration: var(--johnbot-duration-fast);
  transition-timing-function: var(--johnbot-ease-out);
}

.wfn-ink-line[data-brush="marker"] {
  stroke-opacity: 0.45;
}

/* A line that the eraser touched shows faint until the release removes it. */
.wfn-ink-line[data-erasing] {
  opacity: 0.25;
}

.wfn-eraser {
  position: absolute;
  z-index: 3;
  width: var(--johnbot-space-4);
  height: var(--johnbot-space-4);
  border-radius: var(--johnbot-radius-pill);
  background: color-mix(in srgb, var(--johnbot-text-primary) 8%, transparent);
  box-shadow: inset 0 0 0 1px var(--johnbot-text-primary);
  translate: -50% -50%;
  pointer-events: none;
}

/* Hide interface keeps only the canvas and one way back. */
.wfn-canvas[data-hud-hidden] :is(.wfn-hud, .wfn-hud-top) {
  visibility: hidden;
  opacity: 0;
}

.wfn-stage .wfn-hud-show {
  position: absolute;
  right: var(--wfn-hud-inset);
  bottom: var(--wfn-hud-inset);
  z-index: 3;
  gap: var(--johnbot-space-1-5);
  animation: wfn-fade-in var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

.wfn-hud-zoom {
  bottom: var(--wfn-hud-inset);
  left: var(--wfn-hud-inset);
}

.wfn-hud-separator {
  width: 1px;
  height: var(--johnbot-space-4);
  margin: 0 var(--johnbot-space-1);
  background: var(--wfn-ring-strong);
}

/* Every control in a bar, and in a node toolbar: 32px and a press scale. Bar controls have radius 8. */
.wfn-stage .wfn-hud .ui-button {
  border-radius: var(--johnbot-radius-md);
}

.wfn-stage :is(.wfn-hud, .wfn-toolbar) .ui-button {
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
  transition-property: background-color, color, opacity, scale;
  transition-duration: var(--johnbot-duration-fast);
  transition-timing-function: var(--johnbot-ease-out);
}

.wfn-stage :is(.wfn-hud, .wfn-toolbar) .ui-button:active:not(:disabled) {
  scale: 0.96;
}

.wfn-stage .wfn-hud .ui-button-variant-ghost {
  color: var(--johnbot-text-secondary);
}

.wfn-stage .wfn-hud .ui-button-variant-ghost:hover:not(:disabled),
.wfn-stage .wfn-hud .ui-button-variant-ghost[data-expanded] {
  background: var(--wfn-hover);
  color: var(--johnbot-text-primary);
}

.wfn-stage .wfn-hud-button {
  gap: var(--johnbot-space-1-5);
  height: var(--johnbot-control-md);
  padding-inline: var(--johnbot-space-3);
}

/* An icon has space of its own at its edge, so the side with the icon gets less padding. Then the two sides look equal. */
.wfn-stage .wfn-hud-button:has(> svg:first-child) {
  padding-inline-start: calc(var(--johnbot-space-2) + var(--johnbot-space-0-5));
}

.wfn-stage .wfn-hud-button svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

/*
 * The tool bar is one size up from the other bars, as on Higgsfield: 48px high, 36px controls with
 * 20px icons. The control radius is 16 - 6 = 10, so the corners stay concentric.
 */
.wfn-stage .wfn-hud-tools {
  gap: var(--johnbot-space-1-5);
  height: calc(var(--johnbot-control-lg) + var(--johnbot-space-3));
  padding: var(--johnbot-space-1-5);
  border-radius: var(--johnbot-radius-grouped);
}

.wfn-stage .wfn-hud-tools .ui-button {
  height: var(--johnbot-control-lg);
  border-radius: var(--wfn-tool-radius);
}

.wfn-stage .wfn-hud-tools .wfn-hud-tool {
  width: var(--johnbot-control-lg);
}

.wfn-stage .wfn-hud-tools .wfn-hud-tool svg {
  width: var(--johnbot-icon-lg);
  height: var(--johnbot-icon-lg);
}

.wfn-stage .wfn-hud-tools .wfn-hud-add-button svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
}

/*
 * The Draw, Sticky note and Shapes tools show a picture in the bar. The pen stands on the bar and
 * the bar cuts its foot; the notes and the shapes sit in the centre of the button. On hover and when
 * the tool is on, each layer moves on its own with a small spring, as on Higgsfield.
 */
.wfn-stage .wfn-hud-tools {
  overflow: clip;
}

.wfn-stage .wfn-hud-tools .wfn-hud-tool[data-art] {
  position: relative;
  width: calc(var(--johnbot-control-lg) + var(--johnbot-space-2));
  padding: 0;
  overflow: visible;
}

.wfn-stage .wfn-hud-tools .wfn-hud-tool:is([data-art="note"], [data-art="shape"]) {
  width: calc(var(--johnbot-control-lg) + var(--johnbot-space-4));
}

.wfn-stage .wfn-hud .wfn-hud-tool[data-art]:is(:hover, [aria-pressed="true"]) {
  background: transparent;
}

/*
 * The art colours. Each picture mixes its colour with paper for a lit face and with paper text for
 * a face in shade, so a picture reads the same in the dark and the light theme. The front of a note
 * or a shape goes from the lit face to the base colour.
 */
.wfn-stage .wfn-hud-tools .wfn-hud-tool[data-art] .wfn-tool-art {
  --wfn-art-base: var(--wfn-art-color);
  --wfn-art-light: color-mix(in srgb, var(--wfn-art-color) 58%, var(--johnbot-paper));
  --wfn-art-dark: color-mix(in srgb, var(--wfn-art-color) 72%, var(--johnbot-paper-text));
  --wfn-art-wood-color: color-mix(in srgb, var(--johnbot-file-orange) 38%, var(--johnbot-paper));
  --wfn-art-metal-color: color-mix(in srgb, var(--johnbot-paper) 78%, var(--johnbot-paper-text));
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: auto;
  overflow: visible;
}

/*
 * The light palette darkens each colour for text. A note or a shape keeps the hue at a fixed light
 * tone there, as the note paper does, so it is bright and clean. The ink colour becomes a light neutral tone.
 */
:root[data-johnbot-color-scheme="light"] .wfn-stage .wfn-hud-tools .wfn-hud-tool[data-art] .wfn-tool-art {
  --wfn-art-base: oklch(from var(--wfn-art-color) 0.82 calc(c * 0.75) h);
  --wfn-art-light: oklch(from var(--wfn-art-color) 0.93 calc(c * 0.35) h);
}

/* The pen comes up out of the bar. */
.wfn-hud-tool[data-art="draw"]:is(:hover, [aria-pressed="true"]) .wfn-art-layer {
  translate: 0 calc(var(--johnbot-space-1-5) * -1);
}

/* The notes fan out: the back note goes to the left, the front note goes up and to the right. */
.wfn-hud-tool[data-art="note"]:is(:hover, [aria-pressed="true"]) [data-layer="back"] {
  rotate: -15deg;
  translate: calc(var(--johnbot-space-1) * -1) calc(var(--johnbot-space-0-5) * -1);
}

.wfn-hud-tool[data-art="note"]:is(:hover, [aria-pressed="true"]) [data-layer="middle"] {
  rotate: 4deg;
  translate: 0 calc(var(--johnbot-space-1) * -1);
}

.wfn-hud-tool[data-art="note"]:is(:hover, [aria-pressed="true"]) [data-layer="front"] {
  rotate: 4deg;
  translate: var(--johnbot-space-1) calc(var(--johnbot-space-1-5) * -1);
}

/* The square grows and turns to the left, the circle rolls to the right, the next shape lifts. */
.wfn-hud-tool[data-art="shape"]:is(:hover, [aria-pressed="true"]) [data-layer="back"] {
  rotate: -17deg;
  translate: calc(var(--johnbot-space-1) * -1) calc(var(--johnbot-space-0-5) * -1);
  scale: 1.06;
}

.wfn-hud-tool[data-art="shape"]:is(:hover, [aria-pressed="true"]) [data-layer="middle"] {
  rotate: 12deg;
  translate: var(--johnbot-space-1) var(--johnbot-space-0-5);
}

.wfn-hud-tool[data-art="shape"]:is(:hover, [aria-pressed="true"]) [data-layer="front"] {
  rotate: 6deg;
  translate: var(--johnbot-space-0-5) calc(var(--johnbot-space-1-5) * -1);
}

.wfn-hud-tools .wfn-hud-separator {
  height: calc(var(--johnbot-space-4) + var(--johnbot-space-1));
  margin: 0 var(--johnbot-space-0-5);
}

/* The icon of a HUD bar, such as the version bar. */
.wfn-hud-icon {
  display: inline-grid;
  flex: 0 0 auto;
  place-items: center;
  width: var(--johnbot-control-md);
  height: var(--johnbot-control-md);
  border-radius: var(--johnbot-radius-md);
  background: var(--wfn-hover);
  color: var(--johnbot-text-secondary);
}

.wfn-stage .wfn-hud-icon svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.wfn-stage .wfn-hud-name {
  field-sizing: content;
  min-width: 8ch;
  max-width: 40ch;
  height: var(--johnbot-control-md);
  padding: 0 var(--johnbot-space-2);
  border: 0;
  border-radius: var(--johnbot-radius-md);
  background: transparent;
  box-shadow: none;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  text-overflow: ellipsis;
  transition-property: background-color, box-shadow;
  transition-duration: var(--johnbot-duration-fast);
}

.wfn-stage .wfn-hud-name:hover {
  background: var(--wfn-hover);
}

.wfn-stage .wfn-hud-name:focus-visible {
  outline: none;
  background: var(--wfn-hover);
  box-shadow: inset 0 0 0 1px var(--wfn-ring-strong);
}

/* A past run on view. */
.wfn-hud-viewing {
  gap: var(--johnbot-space-1-5);
  padding-left: var(--johnbot-space-3);
  font-variant-numeric: tabular-nums;
}

.wfn-stage .wfn-hud-viewing > svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  color: var(--johnbot-text-muted);
}

/* The tools bar gives its place to the version bar while a version shows. */
.wfn-hud[hidden] {
  display: none;
}

/* A version that shows, read-only, in place of the tools: its time, Back, and Make current. */
.wfn-hud-version {
  bottom: var(--wfn-hud-inset);
  left: round(50%, 1px);
  gap: var(--johnbot-space-1-5);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  translate: round(-50%, 1px) 0;
}

.wfn-hud-lock {
  display: inline-flex;
  gap: var(--johnbot-space-1);
  align-items: center;
  margin-right: var(--johnbot-space-1);
  color: var(--johnbot-text-muted);
}

.wfn-hud-lock-icon {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
}

/* Any drag on a version pans. */
.wfn-canvas[data-preview] .wfn-viewport {
  cursor: grab;
}

.wfn-canvas[data-preview] .wfn-viewport[data-panning] {
  cursor: grabbing;
}

.wfn-hud-label {
  font-weight: var(--johnbot-weight-medium);
}

.wfn-hud-meta {
  margin-right: var(--johnbot-space-1);
  color: var(--johnbot-text-muted);
}

.wfn-hud-count {
  min-width: var(--johnbot-space-4);
  padding: 0 var(--johnbot-space-1);
  border-radius: var(--johnbot-radius-xs);
  background: var(--wfn-hover);
  color: var(--johnbot-text-muted);
  font-size: var(--wfn-small);
  font-variant-numeric: tabular-nums;
  line-height: var(--johnbot-leading-sm);
  text-align: center;
}

/* The run: a primary button, or progress and Stop while it runs. */
.wfn-hud-progress {
  display: inline-flex;
  gap: var(--johnbot-space-1-5);
  align-items: center;
  padding: 0 var(--johnbot-space-2);
  color: var(--johnbot-text-secondary);
  font-variant-numeric: tabular-nums;
  animation: wfn-fade-in var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.wfn-hud-progress .wfn-hud-ring {
  --ui-radial-progress-color: var(--johnbot-text-primary);

  width: var(--johnbot-icon-md);
}

.wfn-stage .wfn-hud-stop {
  animation: wfn-fade-in var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.wfn-stage .wfn-hud-stop svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  fill: currentColor;
}

@keyframes wfn-fade-in {
  from {
    opacity: 0;
  }
}

/* Zoom: the value opens the zoom menu. */
.wfn-stage .wfn-zoom-value {
  justify-content: center;
  min-width: 6ch;
  padding-inline: var(--johnbot-space-1);
  font-variant-numeric: tabular-nums;
}

.wfn-zoom-menu {
  min-width: 200px;
}

.wfn-zoom-menu .wfn-menu-text {
  margin-right: auto;
}

/* The zoom levels: a 3 by 2 grid above the zoom commands, as on the Higgsfield canvas. */
.wfn-zoom-presets {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2px;
}

.wfn-zoom-menu.ui-action-menu .wfn-zoom-presets .wfn-zoom-preset {
  justify-content: center;
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
}

.wfn-zoom-menu.ui-action-menu .wfn-zoom-presets .wfn-zoom-preset[data-current] {
  background: var(--wfn-hover);
  color: var(--johnbot-text-primary);
}

/* Context menu icons sit in one column, so the labels align. */
.wfn-menu-glyph {
  display: inline-grid;
  flex: 0 0 auto;
  place-items: center;
  color: var(--johnbot-text-secondary);
}

.wfn-menu-glyph svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

/* The shared danger colour reaches only a direct icon, so the column icon takes it here. */
.wfn-menu .ui-action-menu-danger .wfn-menu-glyph {
  color: var(--johnbot-danger);
}

/* ------------------------------------------------------------- Search */

/*
 * Search opens above the tool bar, as on the Higgsfield canvas. It is one glass panel: the field,
 * then the empty line or the results. The panel radius is the field radius + its 4px inset.
 */
.wfn-hud.wfn-search {
  bottom: calc(var(--wfn-hud-inset) + var(--johnbot-control-md) + var(--johnbot-space-2) + var(--johnbot-space-2));
  left: round(50%, 1px);
  display: grid;
  gap: var(--johnbot-space-1);
  align-items: stretch;
  width: min(480px, calc(100% - var(--johnbot-space-8)));
  height: auto;
  translate: round(-50%, 1px) 0;
}

.wfn-search-field {
  display: flex;
  gap: var(--johnbot-space-1);
  align-items: center;
  padding-left: var(--johnbot-space-2);
  border-radius: var(--wfn-tool-radius);
}

/* The field has no border, so a 1px ring in the focus colour shows where typing goes. */
.wfn-search-field:has(.wfn-search-input:focus-visible) {
  box-shadow: inset 0 0 0 1px var(--johnbot-border-focus);
}

.wfn-stage .wfn-search-icon {
  flex: 0 0 auto;
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  color: var(--johnbot-text-muted);
}

.wfn-stage .wfn-search-input {
  flex: 1 1 auto;
  height: var(--johnbot-control-md);
  padding: 0 var(--johnbot-space-1);
  border: 0;
  background: transparent;
  box-shadow: none;
  font-size: var(--johnbot-text-sm);
}

.wfn-stage .wfn-search-input:focus-visible {
  outline: none;
  box-shadow: none;
}

.wfn-search-empty {
  margin: 0;
  padding: var(--johnbot-space-2) var(--johnbot-space-2) var(--johnbot-space-3);
  border-top: 1px solid var(--wfn-ring);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  text-wrap: pretty;
}

.wfn-search-results {
  display: grid;
  gap: 2px;
  max-height: 320px;
  margin: 0;
  padding: var(--johnbot-space-1) 0 0;
  overflow-y: auto;
  border-top: 1px solid var(--wfn-ring);
  list-style: none;
}

.wfn-stage .wfn-hud .wfn-search-result {
  justify-content: flex-start;
  gap: var(--johnbot-space-2);
  width: 100%;
  height: auto;
  min-height: var(--johnbot-control-md);
  padding: var(--johnbot-space-1) var(--johnbot-space-2);
  color: var(--johnbot-text-primary);
  text-align: left;
}

.wfn-search-result .wfn-menu-text {
  flex: 0 0 auto;
}

/*
 * A connection dropped on the empty canvas opens the same panel at the end of the line, with only the
 * kinds that can take it. The first kind is what Enter adds, so it shows the hover fill while the
 * field has focus.
 */
/* The popover places the menu, so it does not take the place of the search bar. */
.wfn-hud.wfn-search.wfn-drop-menu {
  position: relative;
  bottom: auto;
  left: auto;
  width: 240px;
  translate: none;
}

/* Its groups and rows are those of the add menu: the icon of the kind and its name. */
.wfn-hud.wfn-drop-menu .wfn-search-results {
  display: block;
  max-height: min(560px, calc(100vh - var(--johnbot-space-8)));
  padding: var(--johnbot-space-1) 0 0;
}

.wfn-drop-list {
  display: grid;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.wfn-drop-menu:has(.wfn-search-input:focus) .wfn-search-result[data-first] {
  background: var(--wfn-hover);
}

.wfn-search-snippet {
  min-width: 0;
  overflow: hidden;
  color: var(--johnbot-text-muted);
  font-size: var(--wfn-small);
  font-weight: var(--johnbot-weight-regular);
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ------------------------------------------------------------ Minimap */

/* The minimap sits over the zoom bar. Nodes are kind-tinted blocks; the view is a bright frame. */
.wfn-hud.wfn-minimap {
  bottom: calc(var(--wfn-hud-inset) + var(--johnbot-control-md) + var(--johnbot-space-2) + var(--johnbot-space-2));
  left: var(--wfn-hud-inset);
  height: auto;
  padding: 0;
  overflow: hidden;
}

.wfn-minimap svg {
  display: block;
  cursor: pointer;
  touch-action: none;
}

.wfn-minimap-node {
  fill: color-mix(in srgb, var(--wfn-kind, var(--johnbot-text-primary)) 40%, transparent);
}

.wfn-minimap-node[data-selected] {
  fill: var(--johnbot-text-primary);
}

/* A drawn line, thin at every size, so it does not cover the nodes. */
.wfn-minimap-line {
  fill: none;
  stroke: var(--wfn-ink);
  stroke-width: 1;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.wfn-minimap-line[data-brush="marker"] {
  stroke-opacity: 0.45;
}

.wfn-minimap-view {
  fill: color-mix(in srgb, var(--johnbot-text-primary) 4%, transparent);
  stroke: color-mix(in srgb, var(--johnbot-text-primary) 64%, transparent);
  stroke-width: 1.5;
}

.wfn-results-menu {
  min-width: 220px;
}

.wfn-results-menu .wfn-menu-text {
  margin-right: auto;
}

.wfn-results-menu .wfn-menu-meta {
  font-variant-numeric: tabular-nums;
}

.wfn-results-menu .wfn-menu-check {
  margin-left: 0;
}

.wfn-menu-check[data-off] {
  visibility: hidden;
}

/* Each node kind has one colour, for its menu tile and its results strip. The tile is a soft wash of
 * that colour behind the icon. */
.wfn-menu-icon {
  --wfn-kind: var(--johnbot-text-secondary);

  display: inline-grid;
  flex: none;
  place-items: center;
  width: var(--johnbot-icon-lg);
  height: var(--johnbot-icon-lg);
  margin-left: calc(var(--johnbot-space-1) * -1);
  border-radius: var(--johnbot-radius-sm);
  background: color-mix(in srgb, var(--wfn-kind) 16%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--wfn-kind) 14%, transparent);
  color: var(--wfn-kind);
}

:is(.wfn-menu, .wfn-search) .wfn-menu-icon svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  color: inherit;
  stroke-width: var(--johnbot-icon-stroke);
}

@media (prefers-reduced-motion: reduce) {
  .wfn-edge-line,
  .wfn-edge-comet,
  .wfn-hud-progress,
  .wfn-stage .wfn-hud-stop {
    animation: none;
  }

  .wfn-stage :is(.wfn-hud, .wfn-toolbar) .ui-button:active:not(:disabled) {
    scale: 1;
  }
}

/* ------------------------------------------------------------ Selection */

/* In a group, each node keeps its ring, and only one node at a time resizes. */
.wfn-world[data-group] .wfn-grip {
  display: none;
}

/* While a node moves or resizes, the nodes under the pointer show no handles. */
.wfn-viewport:is([data-resizing], [data-dragging]) .wfn-node:not([data-resizing], [data-selected]) .wfn-grip {
  --wfn-grip-color: transparent;
}

/* The cursor of the handle stays while the pointer moves over other nodes. */
.wfn-viewport[data-resizing],
.wfn-viewport[data-resizing] .wfn-slot :is(.wfn-label, .wfn-card, .wfn-grip) {
  cursor: ew-resize;
  user-select: none;
}

.wfn-viewport[data-resizing="ns"],
.wfn-viewport[data-resizing="ns"] .wfn-slot :is(.wfn-label, .wfn-card, .wfn-grip) {
  cursor: ns-resize;
}

.wfn-viewport[data-resizing="nwse"],
.wfn-viewport[data-resizing="nwse"] .wfn-slot :is(.wfn-label, .wfn-card, .wfn-grip) {
  cursor: nwse-resize;
}

.wfn-viewport[data-resizing="nesw"],
.wfn-viewport[data-resizing="nesw"] .wfn-slot :is(.wfn-label, .wfn-card, .wfn-grip) {
  cursor: nesw-resize;
}

/* A live resize follows the pointer with no delay. */
.wfn-viewport[data-resizing] .wfn-slot :is(.wfn-node, .wfn-card) {
  transition: none;
}

/* ------------------------------------------------------- Empty canvas */

/* An empty workflow asks for its trigger in the middle of the canvas. The canvas stays usable. */
.wfn-empty {
  position: absolute;
  inset: 0;
  display: grid;
  gap: var(--johnbot-space-3);
  place-content: center;
  justify-items: center;
  pointer-events: none;
  animation: wfn-fade-in var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

.wfn-empty > * {
  pointer-events: auto;
}

.wfn-stage .wfn-empty-icon {
  width: var(--johnbot-control-lg);
  height: var(--johnbot-control-lg);
  border-radius: var(--johnbot-radius-lg);
}

.wfn-stage .wfn-empty-icon svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
}

.wfn-empty-title {
  margin: 0;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  text-wrap: balance;
}

/* ------------------------------------------------------------ Selection */

/* The selection box: a quiet fill and a 1px ring, not a colour. */
.wfn-marquee {
  position: absolute;
  z-index: 3;
  border-radius: var(--johnbot-radius-xs);
  background: color-mix(in srgb, var(--johnbot-text-primary) 4%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--johnbot-text-primary) 32%, transparent);
  pointer-events: none;
}

/* A selection of more than one node: one frame around all of it and one toolbar. */
.wfn-group {
  position: absolute;
  z-index: 2;
  border-radius: var(--wfn-radius-card);
  outline: calc(1px / var(--wfn-scale, 1)) dashed color-mix(in srgb, var(--johnbot-text-primary) 24%, transparent);
  outline-offset: calc(12px / var(--wfn-scale, 1));
  pointer-events: none;
}

.wfn-group .wfn-group-bar {
  bottom: calc(100% + (12px + var(--johnbot-space-3)) / var(--wfn-scale, 1));
  pointer-events: auto;
}

.wfn-group-count {
  padding: 0 var(--johnbot-space-1) 0 var(--johnbot-space-3);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.wfn-viewport[data-dragging] .wfn-group-bar {
  opacity: 0;
}

/* Alignment guides: 1px at every zoom, a faint tint of the text colour that fades in. */
.wfn-guide {
  position: absolute;
  z-index: 3;
  background: color-mix(in srgb, var(--johnbot-text-primary) 22%, transparent);
  pointer-events: none;
  opacity: 1;
  transition: opacity var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

@starting-style {
  .wfn-guide {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .wfn-guide {
    transition: none;
  }
}

.wfn-guide[data-axis="x"] {
  width: calc(1px / var(--wfn-scale, 1));
  translate: calc(-0.5px / var(--wfn-scale, 1)) 0;
}

.wfn-guide[data-axis="y"] {
  height: calc(1px / var(--wfn-scale, 1));
  translate: 0 calc(-0.5px / var(--wfn-scale, 1));
}

/* ------------------------------------------------------------ Run status */

.wfn-hud-live {
  display: contents;
}

.wfn-stage .wfn-hud-step {
  gap: var(--johnbot-space-1-5);
  max-width: 360px;
  font-variant-numeric: tabular-nums;
}

.wfn-stage .wfn-hud .wfn-hud-step > svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: none;
  color: var(--johnbot-text-muted);
}

.wfn-stage .wfn-hud-status[data-status="failed"] .wfn-hud-step > svg {
  color: var(--johnbot-danger-text);
}

.wfn-hud-step .wfn-hud-meta {
  margin-right: 0;
}

.wfn-hud-step-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (prefers-reduced-motion: reduce) {
  .wfn-ghost {
    animation: none;
  }
}

/* A deleted workflow hides until its Undo toast closes. */
.wfn-stage[data-deleted] {
  visibility: hidden;
}

/* The Undo toast of a workflow delete has the 1px ring and no shadow, as the other canvas surfaces. */
.wfn-undo-toast-host .agent-delete-undo-toast {
  box-shadow: 0 0 0 1px var(--johnbot-border);
}

.wfn-undo-toast-tile {
  display: grid;
  place-items: center;
  width: var(--johnbot-control-md);
  height: var(--johnbot-control-md);
  border-radius: var(--johnbot-radius-sm);
  background: var(--johnbot-bg-control);
  box-shadow: inset 0 0 0 1px var(--johnbot-border);
  color: var(--johnbot-text-secondary);
}

.wfn-undo-toast-icon {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

/* --------------------------------------------------------------- In app */

/* The story has no root that sizes the window, so the window takes the screen. */
.app-window.wfn-app {
  height: 100vh;
}

/*
 * In the desktop window, the canvas fills the pane. The window frame shows through the top row, which
 * holds the canvas bar, and the canvas paints only the card below it, inside the card's border and corners.
 */
.wfn-stage.wfn-canvas[data-frame="window"] {
  --wfn-hud-inset: var(--johnbot-space-2);

  height: 100%;
  background: transparent;
}

.wfn-canvas[data-frame="window"] :is(.wfn-viewport, .wfn-empty) {
  top: var(--left-header-height);
}

.wfn-canvas[data-frame="window"] .wfn-viewport {
  border-radius: var(--wfn-card-inner-radius);
  background: var(--johnbot-bg-frame);
}

/* The workflow page does not need the Marketplace button that the sidebar keeps in the top row. */
.wfn-app .sidebar-marketplace-button {
  display: none;
}

/* The server menu keeps the start of the top row, so the bar starts after it. */
.wfn-canvas[data-frame="window"] .wfn-hud-top {
  top: 0;
  right: var(--johnbot-space-3);
  left: calc(var(--left-panel-width) + var(--johnbot-space-3));
  height: var(--left-header-height);
  align-items: center;
}

/* In the top row, the bars are plain groups of controls, as in the other pages' top rows. */
.wfn-canvas[data-frame="window"] .wfn-hud-top .wfn-hud {
  height: auto;
  padding: 0;
  background: transparent;
  box-shadow: none;
  backdrop-filter: none;
}

/* The buttons of the top row have the size of the buttons in the other pages' top rows, such as Run now in Routines. */
.wfn-canvas[data-frame="window"] .wfn-hud-top .wfn-hud-button {
  height: var(--johnbot-control-xs);
  padding-inline: var(--johnbot-space-2);
  font-size: var(--johnbot-text-lg);
}

.wfn-canvas[data-frame="window"] .wfn-hud-top .wfn-hud-button svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
}

/* The window's top row stays when the interface is hidden: only the bars on the canvas go. */
.wfn-canvas[data-frame="window"][data-hud-hidden] .wfn-hud-top,
.wfn-canvas[data-frame="window"][data-hud-hidden] .wfn-hud-top .wfn-hud {
  visibility: visible;
  opacity: 1;
}

/* ------------------------------------------------------------ Switcher */

/*
 * The workflow switcher in the menu of the app. The panel keeps the sheet colour, the edge and the top
 * highlight of the shared menu, but not its drop shadow.
 */

.wfs-menu.ui-action-menu {
  --ui-menu-panel-shadow: inset 0 1px 0 var(--ui-menu-highlight), 0 0 0 1px var(--ui-menu-edge);

  min-width: 260px;
  max-width: min(320px, calc(100vw - var(--johnbot-space-4)));
  max-height: min(520px, var(--kb-popper-content-available-height, 520px));
  overflow-y: auto;
}

.wfs-menu .wfs-name {
  flex: 1 1 auto;
}

/* The step count at the end of a row keeps its numbers in line from row to row. */
.wfs-menu .ui-menu-trailing {
  flex: none;
  font-variant-numeric: tabular-nums;
}

/* The history clock has no closed shape, so it stays an outline on the highlighted row. */
.wfs-menu.ui-action-menu [class~="lucide-rotate-ccw-clock"] > * {
  fill: none;
}

/* === from: @johnbot/ui/features/usage/agent-usage-report.css === */
.agent-usage-secondary,
.agent-usage-footer {
  font-size: var(--johnbot-text-sm);
  color: var(--johnbot-text-muted);
}
.agent-usage-overview {
  display: grid;
  gap: var(--johnbot-space-8);
}
.agent-usage-summary {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-8);
}
.agent-usage-hero {
  font-size: var(--johnbot-text-usage-total);
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.04em;
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
  margin-bottom: var(--johnbot-space-3);
}
.agent-usage-providers {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-6);
}
.agent-usage-provider-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-4);
  font-size: var(--johnbot-text-lg);
}
.agent-usage-provider-heading > span {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
}
/* The legend mark for the row's series. Its colour is an inline style, because it is the
   provider that decides it rather than the stylesheet. */
.agent-usage-series-dot {
  width: var(--johnbot-space-2);
  height: var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-pill);
  flex-shrink: 0;
}
.agent-usage-provider-heading strong {
  font-weight: 550;
  font-variant-numeric: tabular-nums;
}
.agent-usage-provider p {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  margin-top: var(--johnbot-space-2);
}
.agent-usage-provider-icon {
  fill: var(--johnbot-provider-current);
  width: var(--johnbot-space-4);
  height: var(--johnbot-space-4);
  flex-shrink: 0;
}
.agent-usage-trend {
  min-width: 0;
}
.agent-usage-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-4);
  margin-bottom: var(--johnbot-space-4);
}

/* One line, never two. A wrapped second row put two entries under five and read as a
   second, more important group; the entries are a tail of decreasing interest instead, so
   a panel too narrow to hold them all drops the last ones rather than rewrapping. */
.agent-usage-totals {
  display: flex;
  flex-wrap: nowrap;
  gap: calc(var(--johnbot-space-6) * 2);
  margin-top: var(--johnbot-space-4);
  overflow: hidden;
}
.agent-usage-totals dt {
  font-size: var(--johnbot-text-sm);
  color: var(--johnbot-text-muted);
  margin-bottom: var(--johnbot-space-1);
  white-space: nowrap;
}
.agent-usage-totals dd {
  margin: 0;
  font-size: var(--johnbot-text-xl);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.agent-usage-table {
  overflow-x: auto;
}
.agent-usage-table table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--johnbot-text-lg);
  font-variant-numeric: tabular-nums;
}
.agent-usage-table th,
.agent-usage-table td {
  text-align: right;
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
  border-bottom: 1px solid var(--johnbot-border-strong);
  white-space: nowrap;
  font-weight: 400;
}
.agent-usage-table th:first-child {
  text-align: left;
  padding-left: 0;
  white-space: normal;
}
.agent-usage-table td:last-child {
  padding-right: 0;
}
.agent-usage-table thead th {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}
.agent-usage-table td {
  color: var(--johnbot-text-secondary);
}
.agent-usage-model-name {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-3);
  overflow-wrap: anywhere;
  min-width: 10rem;
}
.agent-usage-footer {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-3);
  padding-bottom: var(--johnbot-space-6);
}
.agent-usage-footer summary {
  cursor: pointer;
  width: fit-content;
}
.agent-usage-footer details p {
  margin-top: var(--johnbot-space-3);
  max-width: 72ch;
  line-height: 1.6;
}

/* === from: ./features/usage/usage.css === */
/*
 * The workspace keeps its place in the app frame grid while Usage is open, so the wrapper draws no
 * box of its own. Its children are still grid items of the frame, but they are no longer its DOM
 * children, so `.app-frame > *` no longer reaches them: without this, a conversation panel grows to
 * its content height and pushes the composer under the window edge.
 */
.app-frame-panes {
  display: contents;
}
.app-frame-panes > * {
  min-height: 0;
}
.app-frame-page-open .app-frame-panes {
  visibility: hidden;
  pointer-events: none;
}

/* A selected tab in the chat sets itself visible, so every part of the chat hides, not only its root. */
.app-frame.app-frame-page-open .app-frame-panes * {
  visibility: hidden;
}
.window-page {
  z-index: 1;
  min-height: 0;
  overflow: hidden;
}
.agent-usage {
  container-type: inline-size;
  display: flex;
  flex: 1;
  min-width: 0;
  min-height: 0;
  height: 100%;
  flex-direction: column;
  color: var(--johnbot-text-primary);
  background: var(--johnbot-bg-canvas);
}
.agent-usage-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-4) var(--johnbot-space-6);
  border-bottom: 1px solid var(--johnbot-border);
}
.agent-usage-identity,
.agent-usage-controls {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-3);
  min-width: 0;
}
.agent-usage-identity {
  flex-wrap: wrap;
}
/* What lines up with the header's inset is the arrow, not the 32px hit area around it, so
   the button hangs its padding back into the header rather than pushing the glyph right. */
.agent-usage-identity .ui-icon-button {
  margin-left: calc(-1 * var(--johnbot-space-2));
}
.agent-usage-identity h2 {
  display: flex;
  gap: var(--johnbot-space-3);
  font-size: var(--johnbot-text-lg);
  color: var(--johnbot-text-muted);
}
.agent-usage-identity h2 span:last-child {
  color: var(--johnbot-text-primary);
  overflow-wrap: anywhere;
}

/* The three filters and the refresh button need more width than the header can always
   give, so the row wraps from the right rather than clipping its last controls. */
.agent-usage-controls {
  margin-left: auto;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: var(--johnbot-space-3);
}
.agent-usage-body {
  width: 100%;
  max-width: 1200px;
  margin-inline: auto;
  padding: var(--johnbot-space-6);
  overflow: auto;
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-8);
}
.agent-usage h3 {
  font-size: var(--johnbot-text-xl);
  font-weight: 550;
}
.agent-usage-notice {
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-md);
  padding: var(--johnbot-space-4);
  background: var(--johnbot-bg-surface);
  border-radius: var(--johnbot-radius-md);
}
.agent-usage-notice .ui-button {
  margin-top: var(--johnbot-space-3);
}
.agent-usage-loading {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
}
.agent-usage-placeholder {
  height: 280px;
  margin-top: var(--johnbot-space-6);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-surface);
}
@container (min-width: 850px) {
  .agent-usage-overview {
    grid-template-columns: minmax(260px, 0.8fr) minmax(0, 1.5fr);
    gap: calc(var(--johnbot-space-6) * 2);
  }
  .agent-usage-body {
    padding: var(--johnbot-space-8) calc(var(--johnbot-space-6) * 2);
    gap: calc(var(--johnbot-space-6) * 2);
  }
}
/* The drop order is the reading order reversed: message counts go before token
   categories, and the processed total is the one entry that always stays. */
@container (max-width: 1000px) {
  .agent-usage-totals > div:nth-child(n + 7) {
    display: none;
  }
}
@container (max-width: 820px) {
  .agent-usage-totals > div:nth-child(n + 6) {
    display: none;
  }
}
@container (max-width: 660px) {
  .agent-usage-totals > div:nth-child(n + 5) {
    display: none;
  }
}
@container (max-width: 540px) {
  .agent-usage-totals > div:nth-child(n + 4) {
    display: none;
  }
}
@container (max-width: 400px) {
  .agent-usage-totals > div:nth-child(n + 3) {
    display: none;
  }
}
@container (max-width: 480px) {
  .agent-usage-hero {
    font-size: var(--johnbot-text-display);
  }
  .agent-usage-body {
    padding: var(--johnbot-space-4);
  }
  .agent-usage-header {
    padding: var(--johnbot-space-3);
  }
  .agent-usage-controls {
    margin-left: 0;
    justify-content: flex-start;
  }
  .agent-usage-section-header {
    flex-wrap: wrap;
  }
}

/* The header holds one row of filters, so every dropdown and the refresh button share
   a body colour and a 32px height rather than each wearing its own form-field or
   toolbar look. */
.agent-usage-controls .ui-select {
  width: auto;
  flex-shrink: 0;
}
.agent-usage-controls .ui-select-trigger {
  width: max-content;
  border-color: var(--johnbot-border);
  background: var(--johnbot-bg-control);
  box-shadow: none;
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
}

.app-frame-panes.server-connection-workspace {
  position: relative;
  grid-column: -2 / -1;
  grid-row: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
  overflow: hidden;
}
/* The pane makes no stacking context, so the dialog layer of the loading screen would paint over the
 * menus that open from the sidebar. The screen covers only the pane, so one layer is sufficient. */
.server-connection-workspace > .app-loading {
  z-index: 1;
}
/* The panes were grid items of the frame and stretched to its height. In this column they grow to
 * fill it, so a short chat keeps its composer at the bottom. */
.server-connection-content > * {
  min-height: 0;
  flex: 1;
}

/* === from: ./features/schedule/schedule.css === *//* The schedule fills the pane the usage report uses, and scrolls inside it. */
.schedule-pane {
  height: 100%;
  min-height: 0;
  overflow-y: auto;
  background: var(--johnbot-bg-canvas);
  padding: var(--johnbot-space-4) var(--johnbot-space-6) var(--johnbot-space-6);
}

/* === from: @johnbot/ui/styles/chart.css === */
.ui-chart {
  width: 100%;
  height: 300px;
  min-width: 0;
  font-size: var(--johnbot-text-sm);
}
.ui-chart-tooltip {
  background: var(--johnbot-bg-surface);
  color: var(--johnbot-text-primary);
  padding: var(--johnbot-space-3);
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-md);
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
}
/* One row per series: mark, name, value. The value column takes the remaining width so
   the numbers line up under each other however long the names are. */
.ui-chart-tooltip-row {
  display: grid;
  grid-template-columns: var(--johnbot-space-4) auto 1fr;
  align-items: center;
  gap: var(--johnbot-space-2);
  margin-top: var(--johnbot-space-2);
}
.ui-chart-tooltip-value {
  text-align: right;
}
.ui-chart-tooltip-mark {
  display: flex;
  align-items: center;
}
.ui-chart-tooltip-total {
  border-top: 1px solid var(--johnbot-border-strong);
  padding-top: var(--johnbot-space-2);
  color: var(--johnbot-text-muted);
}

/* === from: @johnbot/ui/features/files/files.css === */
/*
 * Files and storage (issue 496). The storage bar takes its hues from the
 * `--johnbot-chart-storage-*` tokens in a fixed order; everything else uses the
 * shared text, surface and space tokens.
 */

/* Storage bar ------------------------------------------------------------- */

.storage-usage {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-4);
}

.storage-usage [data-group="workspaces"] {
  --storage-color: var(--johnbot-chart-storage-workspaces);
}
.storage-usage [data-group="files"] {
  --storage-color: var(--johnbot-chart-storage-files);
}
.storage-usage [data-group="chats"] {
  --storage-color: var(--johnbot-chart-storage-chats);
}
.storage-usage [data-group="downloads"] {
  --storage-color: var(--johnbot-chart-storage-downloads);
}
.storage-usage [data-group="runtimes"] {
  --storage-color: var(--johnbot-chart-storage-runtimes);
}
.storage-usage [data-group="app"] {
  --storage-color: var(--johnbot-chart-storage-app);
}

/* A 2px surface gap between segments; each segment keeps a minimum width so a
   small share stays a visible mark next to its legend row. */
.storage-usage-bar {
  display: flex;
  height: 10px;
  gap: var(--johnbot-space-0-5);
}

.storage-usage-segment {
  min-width: 4px;
  flex-basis: 0;
  border-radius: var(--johnbot-radius-xs);
  background: var(--storage-color);
  transition: opacity var(--johnbot-duration-fast) ease;
}

.storage-usage[data-hovering="true"] :is(.storage-usage-segment, .storage-usage-legend-row):not([data-active]) {
  opacity: 0.35;
}

.storage-usage-legend {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--johnbot-space-1) var(--johnbot-space-6);
  margin: 0;
  padding: 0;
  list-style: none;
}

.storage-usage-legend-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  align-items: baseline;
  gap: var(--johnbot-space-2);
  padding: var(--johnbot-space-1) 0;
  font-size: var(--johnbot-text-md);
  transition: opacity var(--johnbot-duration-fast) ease;
}

.storage-usage-swatch {
  width: var(--johnbot-space-2);
  height: var(--johnbot-space-2);
  align-self: center;
  border-radius: var(--johnbot-radius-pill);
  background: var(--storage-color);
}

.storage-usage-legend-label {
  overflow: hidden;
  color: var(--johnbot-text-secondary);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.storage-usage-legend-value {
  color: var(--johnbot-text-primary);
  font-variant-numeric: tabular-nums;
}

.storage-usage-legend-percent {
  min-width: 4ch;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
  text-align: right;
}

/* Storage page ------------------------------------------------------------ */

.storage-overview {
  container-type: inline-size;
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: var(--johnbot-space-8);
  color: var(--johnbot-text-primary);
}

.storage-summary {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-4);
}

.storage-summary-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--johnbot-space-3);
}

.storage-summary-label {
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
}

.storage-summary-total {
  margin: var(--johnbot-space-1) 0;
  font-size: var(--johnbot-text-display);
  font-weight: var(--johnbot-weight-semibold);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.03em;
  line-height: 1.1;
}

.storage-summary-total-skeleton {
  width: 140px;
  height: 36px;
  margin: var(--johnbot-space-1) 0;
}

.storage-summary-caption {
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

.storage-message {
  display: flex;
  align-items: flex-start;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-3) var(--johnbot-space-4);
  border: 1px solid var(--johnbot-border-grouped);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-grouped);
}

.storage-message-icon {
  width: 18px;
  height: 18px;
  flex: 0 0 auto;
  margin-top: 1px;
  color: var(--johnbot-text-muted);
  stroke-width: var(--johnbot-icon-stroke);
}

.storage-message[role="alert"] .storage-message-icon {
  color: var(--johnbot-danger-text);
}

.storage-message-title {
  margin: 0;
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
}

.storage-message-description {
  margin: var(--johnbot-space-0-5) 0 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

.storage-section {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-2);
}

.storage-section-heading-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--johnbot-space-3);
}

.storage-section-heading {
  margin: 0;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-semibold);
}

.storage-section-aside {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

.storage-rows {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: 1px solid var(--johnbot-border-grouped);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-grouped);
  list-style: none;
}

.storage-rows > li + li {
  border-top: 1px solid var(--johnbot-border-grouped);
}

.storage-row.ui-button {
  display: flex;
  width: 100%;
  height: auto;
  min-height: 52px;
  align-items: center;
  justify-content: flex-start;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-2) var(--johnbot-space-4);
  border-radius: 0;
  text-align: left;
  font-weight: var(--johnbot-weight-regular);
}

.storage-row-avatar {
  width: 28px;
  height: 28px;
  flex: 0 0 auto;
}

.storage-row-copy {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  gap: var(--johnbot-space-0-5);
}

.storage-row-title {
  overflow: hidden;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.storage-row-meta {
  overflow: hidden;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* One series, so the share bar is one neutral hue; the size beside it is the
   readable value. Scaled to the largest agent, so the top agent fills it. */
.storage-row-share {
  width: 96px;
  height: 6px;
  flex: 0 0 auto;
  overflow: hidden;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-hover);
}

.storage-row-share-fill {
  display: block;
  height: 100%;
  min-width: 4px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-text-muted);
}

.storage-row-size {
  display: flex;
  min-width: 72px;
  flex: 0 0 auto;
  flex-direction: column;
  align-items: flex-end;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-variant-numeric: tabular-nums;
}

.storage-row-percent {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

.storage-row-chevron {
  width: 16px;
  height: 16px;
  flex: 0 0 auto;
  color: var(--johnbot-text-dim);
  stroke-width: var(--johnbot-icon-stroke);
}

.storage-cleanup-row {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-2) var(--johnbot-space-4);
}

.storage-cleanup-row .storage-row-meta {
  white-space: normal;
}

.storage-subview-header {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
}

/* The same size as the back icon in the settings panel header. */
.storage-subview-back > svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
}

.storage-subview-header h3 {
  margin: 0;
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-semibold);
}

@container (max-width: 520px) {
  .storage-row-share {
    display: none;
  }
}

/* File list ---------------------------------------------------------------- */

.file-list {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: var(--johnbot-space-3);
}

.file-list-toolbar {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.file-list-search {
  position: relative;
  min-width: 0;
  flex: 1;
}

.file-list-search-icon {
  position: absolute;
  top: 50%;
  left: var(--johnbot-space-2);
  width: 14px;
  height: 14px;
  color: var(--johnbot-text-muted);
  pointer-events: none;
  stroke-width: var(--johnbot-icon-stroke);
  transform: translateY(-50%);
}

.file-list-search .file-list-search-input {
  width: 100%;
  padding-left: calc(var(--johnbot-space-2) + 14px + var(--johnbot-space-1-5));
}

.file-list-toolbar > .ui-select {
  width: auto;
  flex: 0 0 auto;
}

.file-list-sort {
  width: 120px;
}

.file-list[data-compact="true"] .file-list-sort {
  width: auto;
}

.file-list-filters {
  display: flex;
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
  flex-wrap: wrap;
  gap: var(--johnbot-space-1);
}

.file-list[data-compact="true"] .file-list-filters {
  flex-wrap: nowrap;
  overflow-x: auto;
  scrollbar-width: none;
}

.file-list-filter.ui-button {
  flex: 0 0 auto;
  gap: var(--johnbot-space-1-5);
  border-radius: var(--johnbot-radius-pill);
  color: var(--johnbot-text-muted);
}

.file-list-filter.ui-button[aria-pressed="true"] {
  background: var(--johnbot-bg-control-active);
  color: var(--johnbot-text-primary);
}

.file-list-filter-count {
  color: var(--johnbot-text-muted);
  font-variant-numeric: tabular-nums;
}

.file-list-filter[aria-pressed="true"] .file-list-filter-count {
  color: var(--johnbot-text-secondary);
}

.file-list-summary {
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

.file-list-group {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-1);
}

.file-list-group + .file-list-group {
  margin-top: var(--johnbot-space-2);
}

.file-list-group-heading {
  margin: 0;
  padding: 0 var(--johnbot-space-1);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
}

.file-list-rows {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-0-5);
  margin: 0;
  padding: 0;
  list-style: none;
}

.file-list-skeleton {
  height: 48px;
  border-radius: var(--johnbot-radius-md);
}

.file-list-message {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--johnbot-space-2);
  padding: var(--johnbot-space-8) var(--johnbot-space-4);
  text-align: center;
}

.file-list-message-icon {
  width: 20px;
  height: 20px;
  color: var(--johnbot-danger-text);
  stroke-width: var(--johnbot-icon-stroke);
}

.file-list-message-title {
  margin: 0;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
}

.file-list-message-description {
  max-width: 320px;
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

.file-row {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-1);
  padding-right: var(--johnbot-space-1);
  border-radius: var(--johnbot-radius-md);
}

.file-row:hover,
.file-row:focus-within {
  background: var(--johnbot-hover);
}

.file-row-main.ui-button {
  display: flex;
  min-width: 0;
  height: auto;
  flex: 1;
  align-items: center;
  justify-content: flex-start;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-1-5) var(--johnbot-space-2);
  text-align: left;
  font-weight: var(--johnbot-weight-regular);
}

.file-row-main.ui-button:hover {
  background: transparent;
}

/* A missing or remote file cannot preview, but its row still reads as a row
   rather than a disabled control. */
.file-row-main.ui-button:disabled {
  opacity: 1;
}

.files-file-visual {
  --file-reference-color: var(--johnbot-file-default);
  --file-reference-soft: var(--johnbot-file-default-soft);

  display: grid;
  width: 36px;
  height: 36px;
  flex: 0 0 auto;
  place-items: center;
  overflow: hidden;
  border-radius: var(--johnbot-radius-md);
  background: var(--file-reference-soft);
  color: var(--file-reference-color);
  font-family: var(--johnbot-font-mono);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-semibold);
  letter-spacing: 0.02em;
}

/* The shared danger colour is too dark for 12px text on its soft fill. */
.files-file-visual[data-file-tone="document"] {
  color: var(--johnbot-danger-text);
}

.files-file-visual[data-status="missing"],
.files-file-visual[data-status="failed"] {
  opacity: 0.5;
}

.files-file-thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.file-row-copy {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  gap: var(--johnbot-space-0-5);
}

.file-row-name {
  overflow: hidden;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.file-row[data-status="missing"] .file-row-name {
  color: var(--johnbot-text-muted);
  text-decoration: line-through;
  text-decoration-color: var(--johnbot-text-dim);
}

.file-row-meta {
  display: flex;
  min-width: 0;
  overflow: hidden;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  white-space: pre;
}

.file-row-meta-part {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.file-row-meta-part:first-child {
  flex: 0 0 auto;
  font-variant-numeric: tabular-nums;
}

.file-row-status {
  flex: 0 0 auto;
}

/* The chat panel surface is lighter than the page; the shared danger colour is too dark on it at 12px. */
.file-row-status.z-badge-variant-destructive-light {
  color: var(--johnbot-danger-text);
}

.file-row-menu-trigger {
  flex: 0 0 auto;
  color: var(--johnbot-text-muted);
}

.file-row-menu-trigger > svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  stroke-width: var(--johnbot-icon-stroke);
}

/* Icons next to button text: the ui-button leaves lucide at its 24px default. */
.files-button-icon {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: 0 0 auto;
  stroke-width: var(--johnbot-icon-stroke);
}

/* Agent settings > Files ------------------------------------------------- */

.agent-files-view {
  position: absolute;
  z-index: 2;
  inset: 0;
  display: flex;
  flex-direction: column;
  background: var(--johnbot-bg-canvas);
}

.agent-files-body {
  container-type: inline-size;
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  gap: var(--johnbot-space-6);
  overflow-y: auto;
  padding: var(--johnbot-space-4);
}

.agent-files-summary {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-3);
}

.agent-files-total-label {
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
}

.agent-files-total {
  margin: var(--johnbot-space-0-5) 0 0;
  font-size: var(--johnbot-text-3xl);
  font-weight: var(--johnbot-weight-semibold);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
}

.agent-files-total-skeleton {
  width: 96px;
  height: 28px;
  margin-top: var(--johnbot-space-0-5);
}

/* One grouped card with a label and a value per row: the settings panel is too narrow for
   tiles, and a row keeps a long label such as "Files from agents" on one line. */
.agent-files-tiles {
  display: flex;
  flex-direction: column;
  margin: 0;
  overflow: hidden;
  border: 1px solid var(--johnbot-border-grouped);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-grouped);
}

.agent-files-tile {
  display: flex;
  min-height: 36px;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
}

.agent-files-tile + .agent-files-tile {
  border-top: 1px solid var(--johnbot-border-grouped);
}

.agent-files-tile dt {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-1);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-md);
}

.agent-files-tile-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-files-tile dd {
  margin: 0;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-variant-numeric: tabular-nums;
}

/* The row keeps its height: the button overlaps the row padding, not the text. */
.agent-files-tile-action {
  flex: 0 0 auto;
  margin-block: calc(var(--johnbot-space-1) * -1);
  color: var(--johnbot-text-muted);
}

.agent-files-tile-skeleton {
  width: 64px;
  height: 18px;
}

.agent-files-section {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-2);
}

/* Chat > Files panel ------------------------------------------------------ */

.conversation-files-summary {
  flex: 0 0 auto;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
}

.conversation-files-content {
  min-height: 0;
  flex: 1;
  overflow-y: auto;
  padding: var(--johnbot-space-3);
}

/* Machine use, at the top of Storage -------------------------------------- */

.machine-resources-metrics,
.machine-resources-settings {
  margin: 0;
  padding: 0;
  border: 1px solid var(--johnbot-border-grouped);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-grouped);
  list-style: none;
}

.machine-resources-metric {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) 96px 44px;
  align-items: center;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-3) var(--johnbot-space-4);
}

.machine-resources-metric + .machine-resources-metric {
  border-top: 1px solid var(--johnbot-border-grouped);
}

.machine-resources-icon {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  color: var(--johnbot-text-secondary);
}

.machine-resources-metric[data-tone="warning"] .machine-resources-icon {
  color: var(--johnbot-warning);
}

.machine-resources-metric[data-tone="danger"] .machine-resources-icon {
  color: var(--johnbot-danger);
}

.machine-resources-copy {
  display: grid;
  min-width: 0;
  gap: var(--johnbot-space-0-5);
}

.machine-resources-title {
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
}

.machine-resources-meta {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

.machine-resources-bar {
  position: relative;
  display: flex;
  align-items: center;
}

.machine-resources-bar .ui-progress-track {
  height: 6px;
}

.machine-resources-metric[data-tone="warning"] .ui-progress-fill {
  background: var(--johnbot-warning);
}

.machine-resources-metric[data-tone="danger"] .ui-progress-fill {
  background: var(--johnbot-danger);
}

/* The alert level of the metric, on its bar. */
.machine-resources-threshold {
  position: absolute;
  top: -3px;
  bottom: -3px;
  width: 2px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-text-secondary);
}

.machine-resources-value {
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
  text-align: end;
}

.storage-message.machine-resources-alert .storage-message-icon {
  color: var(--johnbot-warning);
}

.machine-resources-settings {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-4);
  padding: var(--johnbot-space-4);
}

.machine-resources-setting {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-4);
}

.machine-resources-select {
  flex: 0 0 220px;
}

@container (max-width: 520px) {
  .machine-resources-metric {
    grid-template-columns: auto minmax(0, 1fr) 44px;
  }

  .machine-resources-bar {
    display: none;
  }

  .machine-resources-setting {
    flex-direction: column;
    align-items: stretch;
  }

  .machine-resources-select {
    flex-basis: auto;
  }
}

/* === from: @johnbot/ui/features/import/agent-import.css === */
/* Server settings > Import. The review and result use the Storage page's summary, section and
   row styles (features/files/files.css), so the two tabs read as one set. The guide is a single
   sequence: three connected steps, and the file button as the one strong control. */

.agent-import-guide {
  display: flex;
  max-width: 560px;
  flex-direction: column;
  gap: var(--johnbot-space-6);
}

.agent-import-intro {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-1-5);
}

.agent-import-heading {
  margin: 0;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-xl);
  font-weight: var(--johnbot-weight-semibold);
  letter-spacing: -0.01em;
}

.agent-import-lede {
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  line-height: 1.5;
}

/* The steps are a real sequence, so they keep their numbers. A rule between the markers joins them. */
.agent-import-steps {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
}

.agent-import-step {
  position: relative;
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr);
  column-gap: var(--johnbot-space-4);
  padding-bottom: var(--johnbot-space-6);
}

.agent-import-step:last-child {
  padding-bottom: 0;
}

.agent-import-step:not(:last-child)::before {
  position: absolute;
  top: 28px;
  bottom: 4px;
  left: 11.5px;
  width: 1px;
  background: var(--johnbot-border-grouped);
  content: "";
}

.agent-import-marker {
  display: inline-flex;
  width: 24px;
  height: 24px;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-pill);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
  font-weight: var(--johnbot-weight-medium);
}

.agent-import-step-body {
  display: flex;
  min-width: 0;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--johnbot-space-2);
  padding-top: 2px;
}

.agent-import-step-title {
  margin: 0;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
}

.agent-import-step-note {
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: 1.45;
}

/* Two ways into Grok Bot share step 1: the ready agent from its link, or the skill added by hand. */
.agent-import-setup {
  display: flex;
  width: 100%;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--johnbot-space-3);
}

.agent-import-setup .ui-sliding-tabs-content-slot {
  width: 100%;
}

/* The folder panel is the tallest and has no steps after it, so when it is hidden it takes no space.
   The panels that do have steps after them share one height, so steps 2 and 3 never move. */
.agent-import-setup-folder:not([data-selected]) {
  display: none;
}

.agent-import-setup-panel {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--johnbot-space-2);
}

/* One card per way in, the same shape in both panels, so step 2 stays where it is: the ready agent
   with its link, or the skill file with both ways to take it. */
.agent-import-card {
  display: flex;
  width: 100%;
  align-items: center;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-2) var(--johnbot-space-2) var(--johnbot-space-2) var(--johnbot-space-3);
  border: 1px solid var(--johnbot-border-grouped);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-grouped);
}

.agent-import-card-icon {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  flex: none;
  color: var(--johnbot-text-secondary);
  stroke-width: var(--johnbot-icon-stroke);
}

.agent-import-card-copy {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
}

.agent-import-card-name {
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
}

.agent-import-card-meta {
  overflow: hidden;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The exact words to send, shown as the text itself rather than described. */
.agent-import-prompt {
  display: flex;
  width: 100%;
  align-items: center;
  gap: var(--johnbot-space-2);
  padding: var(--johnbot-space-1) var(--johnbot-space-1) var(--johnbot-space-1) var(--johnbot-space-3);
  border: 1px solid var(--johnbot-border-grouped);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-grouped);
}

.agent-import-prompt-text {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-import-prompt svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  stroke-width: var(--johnbot-icon-stroke);
}

.agent-import-card .ui-button svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  stroke-width: var(--johnbot-icon-stroke);
}

.agent-import-picker.ui-button {
  display: flex;
  width: 100%;
  height: auto;
  min-height: 64px;
  align-items: center;
  justify-content: flex-start;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-3) var(--johnbot-space-4);
  border: 1px solid var(--johnbot-border-grouped);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-grouped);
  text-align: left;
  font-weight: var(--johnbot-weight-regular);
}

.agent-import-picker.ui-button:hover:not(:disabled, [aria-disabled="true"]) {
  border-color: var(--johnbot-border-strong);
  background: var(--johnbot-bg-control-hover);
}

.agent-import-picker-icon {
  width: var(--johnbot-icon-lg);
  height: var(--johnbot-icon-lg);
  flex: 0 0 auto;
  color: var(--johnbot-text-secondary);
  stroke-width: var(--johnbot-icon-stroke);
}

.agent-import-picker-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: var(--johnbot-space-0-5);
}

.agent-import-picker-title {
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
}

.agent-import-picker-meta {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

/* Review and result rows. */

.agent-import-row {
  display: flex;
  min-height: 52px;
  align-items: center;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-3) var(--johnbot-space-4);
}

label.agent-import-row {
  cursor: pointer;
}

label.agent-import-row:hover {
  background: var(--johnbot-hover);
}

label.agent-import-row:has(input:disabled) {
  cursor: default;
}

.agent-import-row-note {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: 1.4;
}

.agent-import-notes {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-1);
  margin: var(--johnbot-space-1) 0 0;
  padding: 0;
  list-style: none;
}

.agent-import-done {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.agent-import-done-icon {
  width: 32px;
  height: 32px;
  flex: 0 0 auto;
  color: var(--johnbot-success-text);
  stroke-width: var(--johnbot-icon-stroke);
}

.agent-import-skipped-icon {
  color: var(--johnbot-warning-text);
}

.agent-import-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: var(--johnbot-space-2);
}

/* The name and, for a name already on this server, the hint that the import adds another one. */
.agent-import-row-title {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-1);
}

.agent-import-name-hint {
  display: inline-flex;
  flex: none;
  color: var(--johnbot-text-muted);
  border-radius: var(--johnbot-radius-sm);
}

.agent-import-name-hint:hover,
.agent-import-name-hint:focus-visible {
  color: var(--johnbot-text-secondary);
}

.agent-import-name-hint svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  stroke-width: var(--johnbot-icon-stroke);
}

/* A channel row shows up to three of its members, overlapped, where an agent row has one avatar. */
.agent-import-members {
  display: flex;
  flex: none;
  width: 44px;
}

.agent-import-member-avatar {
  width: 22px;
  height: 22px;
  flex: none;
  border-radius: var(--johnbot-radius-pill);
  box-shadow: 0 0 0 2px var(--johnbot-bg-grouped);
}

.agent-import-member-avatar + .agent-import-member-avatar {
  margin-left: -11px;
}

.agent-import-channel-icon {
  width: 28px;
  height: var(--johnbot-icon-md);
  flex: none;
  color: var(--johnbot-text-secondary);
  stroke-width: var(--johnbot-icon-stroke);
}

/* The first screen: one large button for each place the agents can be now. */
.agent-import-sources {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-2);
  margin: 0;
  padding: 0;
  list-style: none;
}

.agent-import-source .agent-import-picker-copy {
  flex: 1;
}

.agent-import-source-logo {
  width: var(--johnbot-icon-lg);
  height: var(--johnbot-icon-lg);
  flex: 0 0 auto;
  color: var(--johnbot-text-primary);
  fill: currentColor;
}

.agent-import-back.ui-button {
  align-self: flex-start;
}

.agent-import-back.ui-button svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

/* The Hermes app icon: a light tile on a dark theme and a dark one on a light theme, as Hermes ships both. */
.hermes-logo-tile {
  fill: var(--johnbot-text-primary);
}

.hermes-logo-mark {
  fill: var(--johnbot-bg-canvas);
}

.agent-import-source-label {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-1-5);
}

.agent-import-source-label-logo {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: 0 0 auto;
}

/* A Hermes profile: its head row, then every item it holds. */
.agent-import-profile {
  gap: var(--johnbot-space-2);
}

.agent-import-profile-head {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-3);
}

.agent-import-profile-name {
  margin: 0;
}

.agent-import-chevron {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.agent-import-chevron-open {
  transform: rotate(180deg);
}

.agent-import-rerun {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-2);
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-grouped);
}

.agent-import-items[data-muted="true"] {
  opacity: 0.5;
}

.agent-import-item {
  align-items: flex-start;
}

.agent-import-allow {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: var(--johnbot-space-1-5);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  cursor: pointer;
}

/* A command is the exact text to type, so it reads as code and wraps rather than hides its end. */
.agent-import-command {
  font-family: var(--johnbot-font-mono);
  font-size: var(--johnbot-text-sm);
  overflow-wrap: anywhere;
  white-space: normal;
}

/* === from: @johnbot/ui/features/transfer/instance-transfer.css === */
/* Settings > Transfer. Rows, messages and steps reuse the Storage page and the agent import
   (features/files/files.css, features/import/agent-import.css), so the screens read as one set. */

.instance-transfer {
  display: flex;
  max-width: 720px;
  flex-direction: column;
  gap: var(--johnbot-space-4);
}

.instance-transfer-start {
  justify-content: flex-start;
}

.instance-transfer-back {
  align-self: flex-start;
  padding-inline: 0;
}

.instance-transfer-link {
  align-self: flex-start;
  padding-inline: 0;
}

.instance-transfer-chip {
  padding: 0 var(--johnbot-space-1-5);
  border: 1px solid var(--johnbot-border-grouped);
  border-radius: var(--johnbot-radius-pill);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  white-space: nowrap;
}

/* Old computer → file → new computer, as one line. */
.instance-transfer-flow {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-3);
  margin: 0;
  padding: var(--johnbot-space-3) var(--johnbot-space-4);
  border: 1px solid var(--johnbot-border-grouped);
  border-radius: var(--johnbot-radius-lg);
  list-style: none;
}

.instance-transfer-flow-item {
  display: flex;
  flex: 1 1 0;
  flex-direction: column;
  align-items: center;
  gap: var(--johnbot-space-1-5);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  text-align: center;
}

.instance-transfer-flow-icon {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  color: var(--johnbot-text-primary);
}

.instance-transfer-flow-arrow {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: none;
  color: var(--johnbot-text-muted);
}

.instance-transfer-tiles {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--johnbot-space-3);
}

.instance-transfer-tile {
  display: flex;
  height: auto;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--johnbot-space-1);
  padding: var(--johnbot-space-4);
  text-align: left;
  white-space: normal;
}

.instance-transfer-tile-icon {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  margin-bottom: var(--johnbot-space-2);
}

.instance-transfer-tile-title {
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
}

.instance-transfer-tile-text {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-regular);
}

/* What moves, as counts with icons. */
.instance-transfer-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--johnbot-space-3);
  margin: 0;
  padding: 0;
  list-style: none;
}

.instance-transfer-summary-item {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
}

.instance-transfer-summary-icon {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: none;
  color: var(--johnbot-text-muted);
}

.instance-transfer-not-moved {
  display: flex;
  align-items: flex-start;
  gap: var(--johnbot-space-2);
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: 1.45;
}

.instance-transfer-not-moved-icon {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  flex: none;
  margin-top: 2px;
}

@media (max-width: 640px) {
  .instance-transfer-tiles,
  .instance-transfer-summary {
    grid-template-columns: minmax(0, 1fr);
  }
}

/* === from: @johnbot/ui/features/settings/settings-modal.css === */
.settings-modal-tabs-root {
  display: contents;
}

.settings-modal {
  --johnbot-bg-surface: var(--johnbot-bg-control);
  --johnbot-text-muted: var(--johnbot-settings-text-muted);
  width: min(880px, calc(100vw - 48px));
  height: min(600px, calc(100dvh - 48px));
  min-width: 0;
  min-height: 0;
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  overflow: hidden;
  outline: none;
  background: var(--johnbot-bg-canvas);
  color: var(--johnbot-text-primary);
  transform-origin: center;
  animation: settings-modal-in var(--johnbot-duration-overlay) var(--johnbot-ease-out) both;
  will-change: transform, opacity;
}

.settings-modal-nav {
  display: grid;
  gap: var(--johnbot-space-1);
}

.settings-modal-nav-item {
  position: relative;
  width: 100%;
  height: auto;
  min-height: var(--johnbot-control-md);
  display: grid;
  grid-template-columns: var(--johnbot-icon-md) minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--johnbot-space-2);
  border: 0;
  border-radius: var(--johnbot-radius-md);
  background: transparent;
  padding: 0 var(--johnbot-space-2);
  color: var(--johnbot-text-secondary);
  font: inherit;
  font-size: var(--johnbot-text-md);
  text-align: left;
  transition:
    background-color var(--johnbot-duration-hover) ease,
    color var(--johnbot-duration-hover) ease;
}

.settings-modal-nav-item svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  stroke-width: var(--johnbot-icon-stroke);
}

.settings-modal-nav-item[aria-current="page"] {
  background: var(--johnbot-bg-control-hover);
  color: var(--johnbot-text-primary);
  font-weight: var(--johnbot-weight-medium);
}

.settings-modal-nav-item {
  cursor: pointer;
}

.settings-modal-nav-item:focus-visible {
  outline: 0;
  box-shadow: var(--johnbot-focus-ring);
}

@media (hover: hover) and (pointer: fine) {
  .settings-modal-nav-item:not([aria-current]):hover {
    background: var(--johnbot-hover);
    color: var(--johnbot-text-primary);
  }
}

.settings-modal-main {
  position: relative;
  min-width: 0;
  min-height: 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  background: var(--johnbot-bg-canvas);
}

.settings-modal-footer {
  display: contents;
}

.settings-modal-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--johnbot-space-4);
  padding: var(--johnbot-space-6) var(--johnbot-space-6) var(--johnbot-space-4);
}

.settings-modal-title {
  margin: 0;
  font-size: var(--johnbot-text-2xl);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-2xl);
  letter-spacing: var(--johnbot-tracking-tight);
}

.settings-modal-description {
  margin: var(--johnbot-space-1) 0 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
}

.settings-modal-scroll-frame {
  position: relative;
  min-height: 0;
  overflow: hidden;
}

.settings-modal-scroll-frame::before,
.settings-modal-scroll-frame::after {
  position: absolute;
  right: var(--johnbot-space-2);
  left: 0;
  z-index: 1;
  height: var(--johnbot-space-8);
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--johnbot-duration-normal) ease;
  content: "";
}

.settings-modal-scroll-frame::before {
  top: 0;
  background: linear-gradient(
    to bottom,
    var(--johnbot-bg-canvas) 0%,
    var(--johnbot-bg-canvas) 28%,
    var(--johnbot-bg-canvas-clear) 100%
  );
}

.settings-modal-scroll-frame::after {
  bottom: 0;
  background: linear-gradient(
    to top,
    var(--johnbot-bg-canvas) 0%,
    var(--johnbot-bg-canvas) 28%,
    var(--johnbot-bg-canvas-clear) 100%
  );
}

.settings-modal-scroll-frame[data-scroll-up]::before,
.settings-modal-scroll-frame[data-scroll-down]::after {
  opacity: 1;
}

/*
 * `--settings-modal-floating-space` is the height of whatever `floatingContent` the caller floats
 * over the end of the panel, such as the server settings error toast. The panel spends it as extra
 * end padding, so its last control scrolls clear of the floating element instead of under it.
 */
.settings-modal-content {
  height: 100%;
  min-height: 0;
  display: grid;
  align-content: start;
  gap: var(--johnbot-space-6);
  overflow-y: auto;
  /*
   * The inline padding stays a plain token so the panel text keeps the same left edge as the header
   * title. A gutter subtracted from the padding only lines up when the platform draws a classic
   * scrollbar; with overlay scrollbars it moved the whole panel inward.
   */
  padding: 0 var(--johnbot-space-6) calc(var(--johnbot-space-6) + var(--settings-modal-floating-space, 0px));
  scrollbar-gutter: stable;
}

.settings-modal-tab-panel {
  display: grid;
  align-content: start;
  gap: var(--johnbot-space-6);
  animation: settings-modal-tab-in var(--johnbot-duration-fast) var(--johnbot-ease-out) both;
  will-change: transform, opacity;
}

.settings-modal-tab-panel:not([data-selected]) {
  display: none;
}

.settings-modal-card:is(.ui-card, .ui-item-group) {
  width: 100%;
  display: grid;
  overflow: hidden;
  border: 0;
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-surface);
  box-shadow: none;
}

.settings-modal-card.ui-card {
  padding: 0 var(--johnbot-space-4);
}

.settings-modal-card > .ui-switch-field,
.settings-modal-card > .ui-item {
  padding: var(--johnbot-space-3) var(--johnbot-space-4);
}

.settings-modal-row {
  min-height: 64px;
}

.settings-modal-card > .ui-switch-field {
  width: 100%;
  justify-content: space-between;
  padding: var(--johnbot-space-3) var(--johnbot-space-4);
}

.settings-modal-card > :not(:first-child) {
  position: relative;
  border-top: 0;
}

.settings-modal-card > :not(:first-child)::before {
  position: absolute;
  top: 0;
  right: var(--johnbot-space-4);
  left: var(--johnbot-space-4);
  height: 1px;
  background: var(--johnbot-border);
  pointer-events: none;
  content: "";
}

.settings-modal-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-4);
}

.settings-modal-row-title {
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-lg);
}

.settings-modal :where(.ui-item-title, .ui-switch-label) {
  font-size: var(--johnbot-text-lg);
  line-height: var(--johnbot-leading-lg);
}

.settings-modal :where(.ui-item-description, .ui-switch-description),
.settings-modal :where(.ui-text)[data-variant="caption"] {
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
}

.settings-modal .ui-item-description {
  overflow: visible;
  text-overflow: clip;
  white-space: normal;
}

.settings-modal :where(.ui-item-content, .ui-switch-copy) {
  gap: var(--johnbot-space-0-5);
}

.settings-modal :where(.ui-button, .ui-input, .ui-textarea, .ui-native-select) {
  font-size: var(--johnbot-text-lg);
  line-height: var(--johnbot-leading-lg);
}

.settings-modal :where(.ui-button-variant-default) {
  background: var(--johnbot-accent);
  color: var(--johnbot-text-primary);
}

.settings-modal :where(.ui-button-variant-outline, .ui-button-variant-secondary) {
  background: var(--johnbot-bg-surface-raised);
}

.settings-modal :where(.ui-button-variant-destructive) {
  background: var(--johnbot-danger);
  color: var(--johnbot-text-primary);
}

.settings-modal .ui-switch[data-checked] {
  background: var(--johnbot-accent);
}

.settings-modal .ui-switch-thumb[data-checked] {
  background: var(--johnbot-text-primary);
}

@media (hover: hover) and (pointer: fine) {
  .settings-modal :where(.ui-button-variant-default):hover:not(:disabled):not([data-disabled]) {
    background: var(--johnbot-accent-hover);
  }

  .settings-modal :where(.ui-button-variant-destructive):hover:not(:disabled):not([data-disabled]) {
    background: var(--johnbot-danger-hover);
    color: var(--johnbot-text-primary);
  }
}

:is(.app-settings-modal-shell, .server-settings-modal-shell).settings-modal {
  width: min(920px, calc(100vw - 48px));
  height: min(640px, calc(100dvh - 48px));
  grid-template-columns: 196px minmax(0, 1fr);
  border-radius: var(--johnbot-radius-card);
  box-shadow:
    var(--johnbot-shadow-raised),
    0 0 0 1px var(--johnbot-dialog-ring);
}

:is(.app-settings-modal-shell, .server-settings-modal-shell) .settings-modal-nav {
  gap: var(--johnbot-space-1);
}

:is(.app-settings-modal-shell, .server-settings-modal-shell) .settings-modal-nav-item {
  min-height: var(--johnbot-control-md);
  padding-inline: var(--johnbot-space-3);
  font-size: var(--johnbot-text-lg);
}

:is(.app-settings-modal-shell, .server-settings-modal-shell) .settings-modal-nav-item[data-selected] {
  background: var(--johnbot-bg-control-hover);
  color: var(--johnbot-text-primary);
  font-weight: var(--johnbot-weight-medium);
}

:is(.app-settings-modal-shell, .server-settings-modal-shell) .settings-modal-header {
  align-items: center;
  padding: var(--johnbot-space-4) var(--johnbot-space-4) var(--johnbot-space-6) var(--johnbot-space-8);
}

:is(.app-settings-modal-shell, .server-settings-modal-shell) .settings-modal-description {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  clip-path: inset(50%);
  white-space: nowrap;
}

:is(.app-settings-modal-shell, .server-settings-modal-shell) .settings-modal-content {
  gap: var(--johnbot-space-6);
  padding: 0 var(--johnbot-space-8) calc(var(--johnbot-space-8) + var(--settings-modal-floating-space, 0px));
}

:is(.app-settings-modal-shell, .server-settings-modal-shell) .settings-modal-tab-panel {
  gap: var(--johnbot-space-6);
  animation: none;
  will-change: auto;
}

:is(.app-settings-modal-shell, .server-settings-modal-shell) .ui-settings-section {
  gap: var(--johnbot-space-2);
}

:is(.app-settings-modal-shell, .server-settings-modal-shell) .ui-settings-section-header {
  padding-inline: 0;
}

:is(.app-settings-modal-shell, .server-settings-modal-shell) .ui-settings-section-heading {
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
}

.provider-picker-embedded {
  border: 0;
}

.provider-picker-embedded .provider-picker-list {
  overflow: hidden;
  border: 0;
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-surface);
}

.provider-picker-embedded .provider-picker-option {
  position: relative;
  min-height: 64px;
  border: 0;
  background: transparent;
  padding: 0 var(--johnbot-space-4);
}

.provider-picker-embedded .provider-picker-option-selection {
  min-height: 64px;
  padding: var(--johnbot-space-3) 0;
}

/* The row has no inline padding of its own here, so the message moves left to stay under the name. */
.provider-picker-embedded .provider-picker-check-error.provider-picker-used-by {
  margin-top: calc(-1 * var(--johnbot-space-4));
  padding: 0 0 var(--johnbot-space-3) 54px;
}

.provider-picker-embedded .provider-picker-accounts {
  margin-top: calc(-1 * var(--johnbot-space-2));
  padding: 0 0 var(--johnbot-space-2) 54px;
}

.provider-picker-embedded .provider-picker-option + .provider-picker-option,
.provider-picker-embedded .provider-picker-option-custom {
  border-top: 0;
}

.provider-picker-embedded .provider-picker-option + .provider-picker-option::before,
.provider-picker-embedded .provider-picker-option-custom::before {
  position: absolute;
  top: 0;
  right: var(--johnbot-space-4);
  left: var(--johnbot-space-4);
  height: 1px;
  background: var(--johnbot-border);
  pointer-events: none;
  content: "";
}

/* The row pads its own inline edges here, so the button margin goes and the gap between two
   actions has to come from the wrapper instead. */
.provider-picker-embedded .provider-picker-actions {
  gap: var(--johnbot-space-2);
}

.provider-picker-embedded .provider-picker-install,
.provider-picker-embedded .provider-picker-custom-count {
  margin-right: 0;
}

/* Row actions keep the onboarding colours: Download and Update stay light and only Connect takes
   the accent, so the modal's accent primary button does not repaint them. */
.settings-modal .ui-button-variant-default.provider-picker-install:not(.provider-picker-connect) {
  background: var(--johnbot-surface-light);
  color: var(--johnbot-text-on-light);
}

@media (hover: hover) and (pointer: fine) {
  .settings-modal
    .ui-button-variant-default.provider-picker-install:not(.provider-picker-connect):hover:not(:disabled):not(
      [data-disabled]
    ) {
    background: color-mix(in srgb, var(--johnbot-surface-light) 82%, transparent);
  }
}

.provider-picker-embedded .provider-picker-option:hover:not(.provider-picker-option-unavailable),
.provider-picker-embedded .provider-picker-option:focus-within,
.provider-picker-embedded .provider-picker-option-selected {
  background: var(--johnbot-bg-control-hover);
}

.settings-modal .provider-picker-name {
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-lg);
}

.settings-modal :where(.provider-picker-email, .provider-picker-check-error) {
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
}

/* An account line is one size below its provider. */
.settings-modal .provider-picker-account .provider-picker-name {
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
}

.settings-modal .provider-picker-account .provider-picker-email {
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.settings-modal .provider-picker-status {
  font-variant-numeric: tabular-nums;
}

.app-settings-modal-shell .settings-modal-select {
  width: 168px;
}

/* "Open external links in": browser names are longer than the other choices. */
.app-settings-modal-shell .settings-modal-link-select {
  width: 220px;
}

/* A line between the two fixed places and the browsers. */
.ui-select-item.settings-modal-select-group-end {
  margin-bottom: var(--johnbot-space-1);
  border-bottom: 1px solid var(--johnbot-border);
}

/* The command field under the link list on Linux and Windows. */
.settings-modal-link-command {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.app-settings-modal-shell .settings-modal-select .ui-select-trigger {
  background: var(--johnbot-bg-surface-raised);
  color: var(--johnbot-text-secondary);
}

.app-settings-modal-shell .settings-modal-update-track-select {
  width: 112px;
}

.app-settings-modal-shell .settings-modal-update-actions {
  flex-wrap: wrap;
}

.app-settings-modal-shell .settings-modal-update-status {
  text-wrap: pretty;
}

.app-settings-modal-shell .settings-modal-update-status-active {
  color: var(--johnbot-accent);
}

.app-settings-modal-shell .settings-modal-error {
  color: var(--johnbot-danger);
}

.settings-identity-name-row.ui-item,
.settings-identity-image-row.ui-item {
  min-height: 72px;
}

.settings-identity-name-control {
  --settings-identity-error-duration: 280ms;
  position: relative;
  width: 220px;
  height: var(--johnbot-control-md);
}

.settings-identity-name-input.ui-input {
  width: 100%;
  transition: border-color var(--johnbot-duration-normal) ease-out;
  will-change: transform;
}

.settings-identity-name-input.is-shaking {
  animation: settings-identity-name-shake 280ms linear;
}

.settings-identity-name-error {
  position: absolute;
  top: calc(100% + var(--johnbot-space-0-5));
  right: 0;
  left: 0;
  opacity: 0;
  visibility: hidden;
  transition:
    opacity var(--settings-identity-error-duration) ease-out,
    visibility 0s linear var(--settings-identity-error-duration);
}

.settings-identity-name-control[data-invalid] .settings-identity-name-error {
  opacity: 1;
  visibility: visible;
  transition:
    opacity var(--settings-identity-error-duration) ease-out,
    visibility 0s linear;
}

.settings-identity-image-control {
  gap: var(--johnbot-space-2);
}

.settings-identity-image-picker {
  position: relative;
  display: flex;
}

.settings-identity-image-trigger {
  position: relative;
  width: calc(var(--johnbot-control-xl) + var(--johnbot-space-2));
  height: calc(var(--johnbot-control-xl) + var(--johnbot-space-2));
  overflow: hidden;
}

.settings-modal-save-bar {
  min-height: 60px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-4);
  border-top: 1px solid var(--johnbot-border);
  background: var(--johnbot-bg-surface);
  padding: var(--johnbot-space-3) var(--johnbot-space-6);
}

.settings-modal-save-actions {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-1);
}

.settings-modal-readonly-value {
  min-width: 180px;
  max-width: 300px;
  overflow-wrap: anywhere;
  color: var(--johnbot-text-primary);
  font-weight: var(--johnbot-weight-medium);
  text-align: right;
  user-select: text;
}

.settings-modal-profile-photo-trigger {
  border-radius: var(--johnbot-radius-pill);
}

.settings-modal-avatar {
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  border: 0;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-accent-soft);
  color: var(--johnbot-accent-hover);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-semibold);
}

.settings-modal-avatar > img {
  width: 100%;
  height: 100%;
  border-radius: inherit;
  object-fit: cover;
  outline: 1px solid var(--johnbot-image-outline);
  outline-offset: -1px;
}

@keyframes settings-identity-name-shake {
  0%,
  100% {
    transform: translateX(0);
  }

  28.57% {
    transform: translateX(6px);
  }

  57.14% {
    transform: translateX(-6px);
  }

  78.57% {
    transform: translateX(4px);
  }
}

@keyframes settings-modal-tab-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }

