/* === from: ./features/settings/settings-modal.css === */
/*
 * Settings modal rules for markup that only the renderer draws: the server settings detail crumbs,
 * the provider section, the Dynamic Island tab, the voice key row and the sound theme row. The
 * shared modal frame and its panels are in `@johnbot/ui/features/settings/settings-modal.css`,
 * which `styles.css` imports immediately before this file.
 */

/*
 * A detail view inside a section keeps the header as the way back, as the agent skills modal does,
 * rather than a back row above the panel.
 */
.settings-modal-crumbs {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
}

/*
 * The parent crumb is a ghost button, so `.ui-button` would otherwise win the type properties and
 * draw it smaller than the title it sits in. The selector carries the modal class to take those
 * back. Hover changes only the text colour. The padding gives the keyboard focus ring room, and negative
 * margins cancel it and the border on every side, so the header keeps the same height, the crumb text
 * keeps the title's left edge, and the separator has the same space on both sides.
 */
.settings-modal .settings-modal-crumb-parent {
  min-width: 0;
  height: auto;
  overflow: hidden;
  border: 1px solid transparent;
  border-radius: var(--johnbot-radius-md);
  background: transparent;
  color: var(--johnbot-text-muted);
  margin-block: calc(-1 * var(--johnbot-space-1) - 1px);
  margin-inline: calc(-1 * var(--johnbot-space-2) - 1px);
  padding: var(--johnbot-space-1) var(--johnbot-space-2);
  font-size: inherit;
  font-weight: inherit;
  line-height: inherit;
  letter-spacing: inherit;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (hover: hover) and (pointer: fine) {
  /* The shared ghost hover outweighs the base rule above, so this rule clears its fill. */
  .settings-modal .settings-modal-crumb-parent:hover:not(:disabled) {
    background: transparent;
    color: var(--johnbot-text-primary);
  }
}

.settings-modal-crumb-separator {
  flex: 0 0 auto;
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  color: var(--johnbot-text-muted);
}

.settings-modal-crumb-current {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.settings-provider-section {
  display: grid;
  gap: var(--johnbot-space-2);
}

.settings-dynamic-island-size > .ui-slider-field,
.settings-dynamic-island-preview {
  padding: var(--johnbot-space-3) var(--johnbot-space-4);
}

/* A server logo in the island server list, at the size of the billing server rows. */
.settings-dynamic-island-server-mark {
  --server-gradient-logo-size: 32px;
  --server-gradient-logo-radius: var(--johnbot-radius-md);
}

.settings-dynamic-island-server-mark > img {
  width: 32px;
  height: 32px;
  border-radius: var(--johnbot-radius-md);
}

.settings-dynamic-island-preview {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--johnbot-space-3);
}

.settings-dynamic-island-preview-display {
  min-width: 0;
  display: grid;
  gap: var(--johnbot-space-1-5);
  margin: 0;
}

/* The top edge of a screen: the island hangs from it as it does from the real menu bar. The strip
   clips the island, so a width past the strip shows as cut off rather than as a wider card. */
.settings-dynamic-island-preview-bar {
  height: 64px;
  display: flex;
  justify-content: center;
  overflow: hidden;
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-canvas);
  box-shadow: inset 0 0 0 1px var(--johnbot-border);
}

.settings-dynamic-island-preview-fit {
  /* The island hangs below the 1px frame edge, so the edge runs over it and the notch shoulders
     curve out of it, as they do out of the top edge of a display. */
  margin-top: 1px;
  display: flex;
  justify-content: center;
  transform-origin: top center;
  scale: var(--settings-dynamic-island-preview-scale, 1);
  transition: scale var(--johnbot-duration-slow) var(--johnbot-ease-out);
}

.settings-dynamic-island-preview-caption {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  text-align: center;
}

.settings-voice-key {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  margin-top: var(--johnbot-space-2);
}

.settings-voice-key > .ui-input {
  flex: 1;
  min-width: 0;
}

/* The sound theme cards are too wide to sit beside the text, so they wrap below it. */
.settings-sound-theme-row {
  flex-wrap: wrap;
}

.settings-sound-theme-row > .sound-theme-picker {
  flex-basis: 100%;
}

/* === from: @johnbot/ui/features/window/page-rail.css === */
/* The page rail at the left of the window, on desktop and on the web. The window styles place it in
 * the window grid. The window buttons of macOS sit at the top of the rail, in the top row. Other
 * windows can show the johnBot logo there. */
.window-rail {
  position: relative;
  display: flex;
  width: 52px;
  min-height: 0;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  padding: calc(var(--left-header-height, 38px) + var(--johnbot-space-1)) 0 var(--johnbot-space-3);
  -webkit-app-region: drag;
}

/* The logo has the size of a rail icon, in the column of the icons. Its top padding is the same as
 * the top padding of `.sidebar-topbar`, so it is on the center line of the server logo. */
.window-rail-logo {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  display: flex;
  height: var(--left-header-height, 38px);
  align-items: center;
  justify-content: center;
  padding-top: 2px;
}

.window-rail-logo .app-logo {
  display: block;
  width: var(--johnbot-icon-lg);
  height: var(--johnbot-icon-lg);
}

.window-rail-logo-link {
  display: flex;
  border-radius: var(--johnbot-radius-logo);
  -webkit-app-region: no-drag;
}

.window-rail-logo-link:focus-visible {
  outline: 0;
  box-shadow: var(--johnbot-focus-ring);
}

.window-rail-group {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--johnbot-space-1-5);
  /* The window swallows mouse events over a drag area. With the gaps between the buttons in the
   * drag area, the pointer left the group between two buttons, and the tooltip closed instead of
   * moving to the next button. */
  -webkit-app-region: no-drag;
}

.window-rail-button {
  position: relative;
  display: flex;
  width: var(--johnbot-control-lg);
  height: var(--johnbot-control-lg);
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: var(--johnbot-radius-lg);
  background: transparent;
  padding: 0;
  color: var(--johnbot-text-muted);
  font: inherit;
  cursor: pointer;
  -webkit-app-region: no-drag;
}

@media (hover: hover) and (pointer: fine) {
  .window-rail-button:hover {
    background: var(--johnbot-bg-control-hover);
    color: var(--johnbot-text-primary);
  }
}

.window-rail-button[aria-current="page"],
.window-rail-button[aria-current="page"]:hover:not(:disabled):not([data-disabled]) {
  background: var(--johnbot-bg-control-active);
  color: var(--johnbot-text-primary);
}

.window-rail-button:focus-visible {
  outline: 0;
  box-shadow: var(--johnbot-focus-ring);
}

.window-rail-button svg {
  width: var(--johnbot-icon-lg);
  height: var(--johnbot-icon-lg);
}

/* The dot of a rail button that has a notice, such as an update. */
.window-rail-notice {
  position: absolute;
  top: var(--johnbot-space-1-5);
  right: var(--johnbot-space-1-5);
  width: var(--johnbot-space-2);
  height: var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-badge-new);
}

/* The hover card of a usage ring shows the limits only. The usage page has the refresh. */
.window-rail-usage-card .account-usage-refresh {
  display: none;
}

/* The card opens, closes and moves with the tooltip motion, not with the transition of the usage
 * popover. A transition would cover the motion. */
.account-usage-popover.window-rail-usage-card {
  transition: none;
  transform-origin: var(--kb-tooltip-content-transform-origin);
}

/* Usage rings: the provider logo inside one ring per limit window. The hover fill is a circle around
 * the rings. */
.window-rail-button.window-rail-usage {
  border-radius: var(--johnbot-radius-pill);
}

.window-rail-button .window-rail-usage-ring {
  position: absolute;
  inset: 1px;
  width: 34px;
  height: 34px;
  transform: rotate(-90deg);
}

.window-rail-button .window-rail-usage-logo {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  overflow: visible;
  fill: var(--johnbot-provider-current);
}

.window-rail-usage-track {
  stroke: currentcolor;
  opacity: 0.15;
}

.window-rail-usage-arc {
  stroke: var(--johnbot-success);
}

.window-rail-usage-arc[data-usage-tone="warning"] {
  stroke: var(--johnbot-warning);
}

.window-rail-usage-arc[data-usage-tone="critical"] {
  stroke: var(--johnbot-danger);
}

/* The usage of a custom agent: its logo with no ring, at the size of a rail icon. The hover card
 * shows the answer of the agent as it wrote it. */
.window-rail-button .window-rail-agent-usage-logo {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
}

.window-rail-agent-usage {
  display: grid;
  padding-inline: var(--johnbot-space-1);
  gap: var(--johnbot-space-1);
}

.window-rail-agent-usage-text {
  margin: 0;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

/* A row of the More menu: the page, then its pin. */
.window-rail-more-menu .window-rail-more-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) var(--johnbot-control-md);
  align-items: center;
  border-radius: var(--ui-menu-item-radius);
  transition: background-color var(--johnbot-duration-hover) var(--johnbot-ease-out);
}

/* The whole line highlights, for the page and for its pin. The items have no background of their own. */
.ui-action-menu.window-rail-more-menu .window-rail-more-row:is(:hover, :has([data-highlighted])) {
  background: var(--ui-menu-item-hover);
}

.ui-action-menu.window-rail-more-menu
  .window-rail-more-row
  :is([role="menuitem"], [role="menuitemcheckbox"]):is(:hover, :focus-visible, [data-highlighted]) {
  background: transparent;
}

/* The pin shows on a pinned page, and on the row under the pointer or the keyboard. The shared
 * .ui-action-menu item rule outranks a single class, so this rule names the role to center the pin. */
.ui-action-menu.window-rail-more-menu .window-rail-more-pin[role="menuitemcheckbox"] {
  justify-content: center;
  padding: 0;
  opacity: 0;
}

.ui-action-menu.window-rail-more-menu
  .window-rail-more-row:is([data-pinned], :hover, :focus-within)
  .window-rail-more-pin {
  opacity: 1;
}

/* A touch screen has no hover, so each pin shows. */
@media (hover: none) {
  .ui-action-menu.window-rail-more-menu .window-rail-more-pin[role="menuitemcheckbox"] {
    opacity: 1;
  }
}

/* Only a pinned page has a filled pin. A highlighted pin stays an outline. */
.ui-action-menu.window-rail-more-menu .window-rail-more-pin > .agent-context-icon > * {
  fill-opacity: 0;
}

.window-rail-more-menu .window-rail-more-row[data-pinned] .window-rail-more-pin > .agent-context-icon > * {
  fill-opacity: 1;
}

/* The page icon follows the line, also when the pin is highlighted. */
.ui-action-menu.window-rail-more-menu
  .window-rail-more-row:is(:hover, :has([data-highlighted]))
  > [role="menuitem"]
  > .agent-context-icon {
  color: var(--johnbot-text-primary);
}

.ui-action-menu.window-rail-more-menu
  .window-rail-more-row:is(:hover, :has([data-highlighted]))
  > [role="menuitem"]
  > .agent-context-icon
  > * {
  fill-opacity: 1;
}

/* === from: ./features/window/window.css === */
/* The desktop window: the page rail at the left, and the frame as the card of the page that the rail
 * selects. The rail shares the darker surface of the frame edge, so the rail and the top row show as
 * one L around the card. */
.app-window {
  /* The frame is darker than the card, so the card comes forward. */
  --window-frame: var(--johnbot-bg-frame);
  /* The thin frame at the right and the bottom of the card */
  --window-edge: var(--johnbot-space-1);
  --window-hairline-height: var(--johnbot-icon-lg);
  display: grid;
  width: 100%;
  height: 100%;
  min-height: 0;
  grid-template-columns: auto minmax(0, 1fr);
  background: var(--window-frame);
}

/* A hidden rail stays out of the grid. The frame keeps the last column, which then takes the whole
 * window. */
.app-window > .window-rail[hidden] {
  display: none;
}

.app-window > .app-frame {
  grid-column: -2;
}

/* The frame below the edge layout keeps its own shape, so the rail would only take width. */
@media (max-width: 720px) {
  .app-window > .window-rail {
    display: none;
  }
}

/* A window with no macOS window buttons starts the server menu at the left edge of the search field
 * and the rows below it, at all widths. The web frame has the macOS class but no buttons. The
 * selector must out-rank the macOS rule below, which also matches the web frame. */
.app-window
  > :is(.web-app-frame, .app-frame:not(.app-frame-platform-darwin)):not(.app-frame-with-server-rail)
  > .sidebar:not(.sidebar-compact)
  .sidebar-topbar {
  padding-left: var(--johnbot-space-3);
}

@media (min-width: 721px) {
  /* The top row holds a short line at the end of the sidebar. */
  .app-window > .app-frame-edge > .sidebar:not(.sidebar-compact) .sidebar-topbar {
    position: relative;
  }

  /* The rail holds the window buttons, so the server menu needs only the part of them that is past
   * the rail. */
  .app-window
    > .app-frame-platform-darwin:not(.app-frame-with-server-rail)
    > .sidebar:not(.sidebar-compact)
    .sidebar-topbar {
    padding-left: var(--johnbot-space-6);
  }

  /* One card holds the sidebar, the chat and the side panel, below the top row. The frame draws the
   * card, and the panes have no background of their own, so the card's line and its four rounded
   * corners show. The padding keeps the panes inside the card's line. */
  .app-window > .app-frame-edge {
    position: relative;
    isolation: isolate;
    padding: 0 calc(var(--window-edge) + 1px) calc(var(--window-edge) + 1px) 0;
    background: var(--window-frame);
  }

  .app-window > .app-frame-edge::before {
    position: absolute;
    z-index: -1;
    inset: calc(var(--left-header-height) - 1px) var(--window-edge) var(--window-edge) 0;
    border: 1px solid var(--johnbot-border);
    border-radius: var(--johnbot-radius-card);
    background: var(--johnbot-bg-canvas);
    content: "";
    pointer-events: none;
  }

  .app-window > .app-frame-edge.app-frame-with-server-rail::before {
    left: var(--server-rail-width);
  }

  .app-window > .app-frame-edge > .server-rail {
    background: var(--window-frame);
  }

  .app-window > .app-frame-edge > .sidebar,
  .app-window > .app-frame-edge :is(.conversation-panel, .direct-conversation, .diagram-view),
  .app-window > .app-frame-edge :is(.settings-panel, .browser-panel) {
    background: transparent;
  }

  /* The sidebar shows the card, and the channel title sits on the top row, so an avatar outline takes
   * the colour of the one it is on. */
  .app-window > .app-frame-edge > .sidebar {
    --agent-avatar-outline: var(--johnbot-bg-canvas);
  }

  .app-window > .app-frame-edge .channel-title {
    --agent-avatar-outline: var(--window-frame);
  }

  .app-window > .app-frame-edge :is(.conversation-panel, .direct-conversation)::before {
    content: none;
  }

  /* The line between the agent list and the chat starts at the card's top line. In the top row, a short
   * line sits above it. */
  .app-window > .app-frame-edge > .sidebar::before {
    inset: var(--left-header-height) 0 0 auto;
    width: 1px;
    border: 0;
    border-radius: 0;
    background: var(--johnbot-border);
  }

  .app-window > .app-frame-edge > .sidebar:not(.sidebar-compact) .sidebar-topbar::after,
  .app-window
    > .app-frame-edge
    :is(.settings-panel, .browser-panel)
    > :is(.settings-panel-header, .file-preview-header, .browser-preview-header)::before {
    position: absolute;
    top: 50%;
    width: 1px;
    height: var(--window-hairline-height);
    translate: 0 -50%;
    background: var(--johnbot-border-strong);
    content: "";
    pointer-events: none;
  }

  .app-window > .app-frame-edge > .sidebar:not(.sidebar-compact) .sidebar-topbar::after {
    right: 0;
  }

  /* A side panel is the right part of the card. Its line to the chat starts at the card's top line. */
  .app-window > .app-frame-edge :is(.settings-panel, .browser-panel) {
    border-left: 0;
  }

  .app-window > .app-frame-edge :is(.settings-panel, .browser-panel)::before {
    inset: calc(var(--left-header-height) - 1px) auto 0 0;
    width: 1px;
    border: 0;
    border-radius: 0;
    background: var(--johnbot-border);
  }

  .app-window
    > .app-frame-edge
    :is(.settings-panel, .browser-panel)
    > :is(.settings-panel-header, .file-preview-header, .browser-preview-header) {
    position: relative;
  }

  .app-window
    > .app-frame-edge
    :is(.settings-panel, .browser-panel)
    > :is(.settings-panel-header, .file-preview-header, .browser-preview-header)::before {
    left: 0;
  }

  /* In the side panel, the tab row is in the top row and a pane starts under it, so the pane's line to
   * the chat starts at the pane's top, and its own header has no short line. */
  .app-window > .app-frame-edge .side-panel-docked > :is(.settings-panel, .browser-panel)::before {
    top: 0;
  }

  .app-window
    > .app-frame-edge
    .side-panel-docked
    > :is(.settings-panel, .browser-panel)
    > :is(.settings-panel-header, .file-preview-header, .browser-preview-header)::before {
    content: none;
  }

  /* A maximized pane covers the hidden chat. A chat preview frame keeps its own visibility, so the
   * pane paints the card under it. */
  .app-window > .app-frame-edge .side-panel-maximized > :is(.settings-panel, .browser-panel) {
    border-bottom-right-radius: calc(var(--johnbot-radius-card) - 1px);
    background: var(--johnbot-bg-canvas);
  }

  /* The routine canvas fills the card, so its board follows the card's rounded corner. */
  .app-window > .app-frame-edge .diagram-view-body {
    border-top: 0;
    border-right: 0;
    border-radius: 0 0 calc(var(--johnbot-radius-card) - 1px) 0;
  }

  /* The top row controls are flat: one height and one radius, with no line. A control fills on hover,
   * and an open control keeps a stronger fill. */
  .app-window > .app-frame-edge .conversation-header-actions {
    gap: var(--johnbot-space-2);
  }

  .app-window > .app-frame-edge .conversation-header :is(.provider-model-trigger, .header-panel-toggle) {
    height: var(--johnbot-control-sm);
    border-color: transparent;
    border-radius: var(--johnbot-radius-md);
    background: transparent;
    box-shadow: none;
    color: var(--johnbot-text-secondary);
  }

  .app-window > .app-frame-edge .conversation-header .header-panel-toggle {
    width: var(--johnbot-control-sm);
    min-width: var(--johnbot-control-sm);
    padding: 0;
    color: var(--johnbot-text-muted);
  }

  @media (hover: hover) and (pointer: fine) {
    .app-window > .app-frame-edge .conversation-header :is(.provider-model-trigger, .header-panel-toggle):hover {
      border-color: transparent;
      background: var(--johnbot-bg-control-hover);
      color: var(--johnbot-text-primary);
    }
  }

  .app-window
    > .app-frame-edge
    .conversation-header
    :is(.provider-model-trigger, .header-panel-toggle):is([aria-expanded="true"], [data-expanded]):not(
      .computer-button-agent-active,
      .side-panel-toggle
    ) {
    border-color: transparent;
    background: var(--johnbot-bg-control-active);
    color: var(--johnbot-text-primary);
  }

  /* A short line between the model and the side panel button */
  .app-window > .app-frame-edge .conversation-header-actions > .side-panel-toggle {
    position: relative;
    margin-left: calc(var(--johnbot-space-2) + 1px);
    overflow: visible;
  }

  .app-window > .app-frame-edge .conversation-header-actions > .side-panel-toggle::before {
    position: absolute;
    top: 50%;
    left: calc(-1 * var(--johnbot-space-2) - 1px);
    width: 1px;
    height: var(--window-hairline-height);
    translate: 0 -50%;
    background: var(--johnbot-border-strong);
    content: "";
    pointer-events: none;
  }

  /* The usage and schedule pages sit in the card, as the chat does. Their title and controls go in the
   * top row, as the chat header does, and the rest of the page goes in the card below it. The card
   * draws the surface, the line and the rounded corner, so the page has no background of its own. */
  .app-frame-edge > .window-page > :is(.agent-usage, .schedule-pane) {
    background: transparent;
  }

  .app-window > .app-frame-edge > .window-page .agent-usage-header,
  .app-window > .app-frame-edge > .window-page .routine-planner-title {
    flex: none;
    height: var(--left-header-height);
    flex-wrap: nowrap;
    padding: 0 var(--johnbot-space-3);
    border-bottom: 0;
    -webkit-app-region: drag;
  }

  .app-window
    > .app-frame-edge
    > .window-page
    :is(.agent-usage-header, .routine-planner-title)
    > :is(.agent-usage-identity, .agent-usage-controls, .routine-planner-identity, p) {
    flex-wrap: nowrap;
    gap: var(--johnbot-space-2);
    -webkit-app-region: no-drag;
  }

  .app-window > .app-frame-edge > .window-page :is(.agent-usage-identity, .routine-planner-identity) .ui-icon-button {
    margin-left: 0;
  }

  .app-window > .app-frame-edge > .window-page :is(.agent-usage-identity, .routine-planner-title) h2 {
    gap: var(--johnbot-space-2);
    font-size: var(--johnbot-text-md);
    font-weight: var(--johnbot-weight-medium);
    white-space: nowrap;
    color: var(--johnbot-text-primary);
  }

  /* In a narrow window, the title gets shorter and the controls keep their size. */
  .app-window > .app-frame-edge > .window-page :is(.agent-usage-identity, .routine-planner-identity) {
    overflow: hidden;
  }

  .app-window > .app-frame-edge > .window-page :is(.agent-usage-controls, .routine-planner-title > p) {
    flex: none;
  }

  /* Flat controls, as in the chat header. */
  .app-window
    > .app-frame-edge
    > .window-page
    :is(.agent-usage-header, .routine-planner-title)
    :is(.ui-select-trigger, .ui-icon-button) {
    height: var(--johnbot-control-sm);
    border-color: transparent;
    border-radius: var(--johnbot-radius-md);
    background: transparent;
    box-shadow: none;
    color: var(--johnbot-text-secondary);
  }

  .app-window > .app-frame-edge > .window-page :is(.agent-usage-header, .routine-planner-title) .ui-icon-button {
    width: var(--johnbot-control-sm);
  }

  @media (hover: hover) {
    .app-window
      > .app-frame-edge
      > .window-page
      :is(.agent-usage-header, .routine-planner-title)
      :is(.ui-select-trigger, .ui-icon-button):hover {
      background: var(--johnbot-bg-control-hover);
      color: var(--johnbot-text-primary);
    }
  }

  /* The schedule header holds the title in the top row; the week below it scrolls in the card. */
  .app-window > .app-frame-edge > .window-page > .schedule-pane {
    padding: 0;
    overflow: hidden;
  }

  .app-window > .app-frame-edge > .window-page .routine-planner {
    height: 100%;
    grid-template-rows: auto minmax(0, 1fr);
    gap: 0;
  }

  .app-window > .app-frame-edge > .window-page .routine-planner-header {
    gap: 0;
  }

  .app-window > .app-frame-edge > .window-page .routine-planner-toolbar {
    padding: var(--johnbot-space-4) var(--johnbot-space-6) 0;
  }

  .app-window > .app-frame-edge > .window-page .routine-planner-body {
    min-height: 0;
    overflow-y: auto;
    padding: var(--johnbot-space-4) var(--johnbot-space-6) var(--johnbot-space-6);
  }

  /* The empty month fills the card and clips at its bottom edge, so the pitch stays in the middle of
   * what the user sees. A pitch taller than the card scrolls. */
  .app-window > .app-frame-edge > .window-page .routine-planner-empty {
    min-height: 0;
    overflow-y: auto;
    grid-template-rows: minmax(0, 1fr);
  }

  .app-window > .app-frame-edge > .window-page :is(.routine-planner-empty-board, .routine-planner-empty-board > *) {
    min-height: 0;
    overflow: hidden;
  }

  .app-window > .app-frame-edge > .window-page .routine-planner-empty-board {
    grid-template-rows: minmax(0, 1fr);
  }

  /* A narrow card puts the runs below the pitch, so both rows keep their height and scroll. */
  @container (max-width: 920px) {
    .app-window > .app-frame-edge > .window-page .routine-planner-empty {
      grid-template-rows: none;
    }
  }

  /* The settings, schedule, usage and Marketplace pages cover the sidebar, so the week has room for
   * seven days. The server menu stays in the top row, so the user can select the server that the page
   * shows. The "settings" kind is both settings pages; the "titled" kind is schedule, usage and Marketplace. */
  /* Out of the grid flow: a grid cell would push the sidebar to a second row. The grid area of an
   * absolute item is its containing block, so the item spans the whole grid. */
  .app-frame-edge:not([data-window-page-kind="agents"]) > .window-page {
    position: absolute;
    grid-row: 1 / -1;
    grid-column: 1 / -1;
    inset: 0 0 0 1px;
  }

  /* The settings page starts below the top row. The schedule, usage and Marketplace titles go in the
   * top row, after the server menu, and the rest of the top row lets clicks through to that menu. The
   * rail is the way back, so these titles have no Back button and no server name. */
  .app-frame-edge[data-window-page-kind="settings"] > .window-page {
    top: var(--left-header-height);
  }

  .app-frame-edge[data-window-page-kind="titled"] > .window-page {
    pointer-events: none;
  }

  .app-frame-edge.app-frame-with-server-rail:not([data-window-page-kind="agents"]) > .window-page {
    left: calc(var(--server-rail-width) + 1px);
  }

  .app-frame-edge:not([data-window-page-kind="agents"]) > .sidebar > :not(.sidebar-topbar),
  .app-frame-edge:not([data-window-page-kind="agents"]) > .left-panel-resizer {
    visibility: hidden;
  }

  /* New agent and New section add to the agent list, so the button shows only on the agents page. */
  .app-frame-edge:not([data-window-page-kind="agents"]) > .sidebar .sidebar-new-button {
    display: none;
  }

  /* The John Twin renders the agent sidebar itself, with the twin's entities in the place of the
   * agents: the frame's sidebar stays out of the way while the page is open. */
  .app-frame-edge[data-window-page-kind="twin"] > .sidebar {
    visibility: hidden;
  }

  /* The page spans the sidebar, so the line at the end of the sidebar does not show. */
  .app-frame-edge[data-window-page-kind="titled"] > .sidebar::before {
    display: none;
  }

  .app-window
    > .app-frame-edge[data-window-page-kind="titled"]
    > .window-page
    :is(.agent-usage-header, .routine-planner-title, .skills-marketplace-topbar) {
    margin-left: var(--left-panel-width);
  }

  .app-frame-edge[data-window-page-kind="titled"]
    > .window-page
    :is(
      .agent-usage-header,
      .routine-planner-title,
      .agent-usage-body,
      .routine-planner-toolbar,
      .routine-planner-body,
      .routine-planner-empty,
      .routine-planner-error,
      .marketplace-heading,
      .marketplace-nav,
      .skills-marketplace-body
    ) {
    pointer-events: auto;
  }

  .app-frame-edge[data-window-page-kind="titled"] > .window-page .john-twin-pane {
    pointer-events: auto;
  }

  /* The Marketplace page: the path of a page goes in the top row, as the usage title does. The side panel and the
   * list are below it. */
  .app-window > .app-frame-edge > .window-page > .skills-marketplace-page {
    grid-template-rows: var(--left-header-height) minmax(0, 1fr);
  }

  .app-window > .app-frame-edge > .window-page .skills-marketplace-topbar {
    min-height: 0;
    padding: 0 var(--johnbot-space-3);
    border-bottom: 0;
    -webkit-app-region: drag;
  }

  .app-window > .app-frame-edge > .window-page .marketplace-heading {
    flex: 0 1 auto;
    -webkit-app-region: no-drag;
  }

  .app-window > .app-frame-edge > .window-page .skills-marketplace-topbar .marketplace-title {
    font-size: var(--johnbot-text-md);
    font-weight: var(--johnbot-weight-medium);
    white-space: nowrap;
  }

  .app-window > .app-frame-edge > .window-page :is(.agent-usage-identity, .routine-planner-identity) > .ui-icon-button,
  .app-window > .app-frame-edge > .window-page :is(.agent-usage-identity, .routine-planner-identity) > h2 > span {
    display: none;
  }

  .app-frame-edge > .window-page :is(.agent-usage-identity, .routine-planner-identity) h2:focus {
    outline: none;
  }
}

/* The settings page: the nav at the width of the sidebar. */
.settings-page {
  display: grid;
  width: 100%;
  height: 100%;
  min-height: 0;
  grid-template-columns: max(var(--left-panel-width, 280px), 220px) minmax(0, 1fr);
}

.settings-page-nav {
  display: flex;
  min-width: 0;
  min-height: 0;
  flex-direction: column;
  gap: var(--johnbot-space-1);
  overflow: hidden;
  border-right: 1px solid var(--johnbot-border);
  padding: var(--johnbot-space-4) var(--johnbot-space-3) 0;
}

/* The title and the search stay at the top. The list below them scrolls. */
.settings-page-sections,
.settings-page-results {
  min-height: 0;
  flex: 1 1 auto;
  overflow-y: auto;
  padding-bottom: var(--johnbot-space-3);
}

.settings-page-title {
  margin: 0 0 var(--johnbot-space-3);
  padding: 0 var(--johnbot-space-2);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-lg);
}

/* The heading takes the focus when the page opens, only so a screen reader reads it. */
.settings-page-title:focus {
  outline: none;
}

/* A capsule search field */
.settings-page-search {
  flex: none;
  border-radius: var(--johnbot-radius-pill);
  padding: 0 var(--johnbot-space-3);
}

.settings-page-search > svg {
  flex: none;
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.settings-page-search input {
  height: 100%;
  padding: 0;
}

.settings-page-sections[hidden] {
  display: none;
}

/* The text that shows when no setting matches the search */
.settings-page-empty {
  margin: var(--johnbot-space-4) 0 var(--johnbot-space-1);
  padding: 0 var(--johnbot-space-2);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

/* The server mark and name, as the server menu shows them */
.settings-page-server {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.settings-page-server .server-menu-mark {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
}

.settings-page-nav-group .settings-modal-nav-item {
  padding-inline: var(--johnbot-space-3);
}

.settings-page-nav-group .settings-modal-nav-item[data-selected] {
  background: var(--johnbot-bg-control-hover);
  color: var(--johnbot-text-primary);
  font-weight: var(--johnbot-weight-medium);
}

/* A search result: the section with its icon, and below it the matching row title */
.settings-page-results {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-0-5);
  margin: var(--johnbot-space-2) 0 0;
  padding-inline: 0;
  list-style: none;
}

.settings-page-result {
  display: flex;
  width: 100%;
  height: auto;
  flex-direction: column;
  align-items: stretch;
  gap: var(--johnbot-space-0-5);
  border: 0;
  border-radius: var(--johnbot-radius-md);
  background: transparent;
  padding: var(--johnbot-space-1-5) var(--johnbot-space-2);
  color: var(--johnbot-text-primary);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

@media (hover: hover) and (pointer: fine) {
  .settings-page-result:hover {
    background: var(--johnbot-bg-control-hover);
  }
}

.settings-page-result:focus-visible {
  outline: 0;
  box-shadow: var(--johnbot-focus-ring);
}

.settings-page-result-section {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

.settings-page-result-section svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.settings-page-result-title {
  overflow: hidden;
  padding-left: calc(var(--johnbot-icon-sm) + var(--johnbot-space-2));
  font-size: var(--johnbot-text-md);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.settings-page-content {
  position: relative;
  min-width: 0;
  min-height: 0;
}

/* The panel of the settings window, as a page: it fills the content column and has no dialog frame. */
.settings-page-content > .settings-modal.settings-modal-page {
  width: 100%;
  height: 100%;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: minmax(0, 1fr);
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  animation: none;
  will-change: auto;
}

.settings-page-content > .settings-modal-page > .settings-modal-main {
  background: transparent;
}

.settings-page-content > .settings-modal-page :is(.settings-modal-header, .settings-modal-content) {
  width: 100%;
  max-width: 784px;
  margin-inline: auto;
}

/* The row that a search result opened */
.settings-page-content [data-search-match] {
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-control-active);
}

/* A narrow window stacks the page: the heading and the sections above the panel. */
@media (max-width: 720px) {
  .settings-page {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
  }

  .settings-page-nav {
    border-right: 0;
    border-bottom: 1px solid var(--johnbot-border);
    padding: var(--johnbot-space-3) var(--johnbot-space-3) 0;
  }

  .settings-page-title {
    margin-bottom: var(--johnbot-space-2);
  }

  .settings-page-sections,
  .settings-page-results {
    max-height: 40dvh;
    padding-bottom: var(--johnbot-space-2);
  }
}

/* A window that shows one chat has no sidebar and no resizer, so the chat takes the whole
 * frame. Its header starts after the macOS window buttons. */
.app-window > .app-frame.app-frame-chat-window {
  grid-template-columns: 0 0 minmax(0, 1fr);
}

.app-frame-chat-window > .left-panel-resizer {
  display: none;
}

.app-frame-chat-window.app-frame-platform-darwin .conversation-header {
  padding-left: 76px;
}

/* A pagina John Twin: a sidebar da tela de agentes inteira (o mesmo componente:
 * barra superior com o menu de novo item, pastas por setor com as entidades do
 * twin, busca e redimensionamento), o DiagramView das Rotinas e o painel de
 * configuracoes da entidade em dock. A sidebar do frame sai de cena enquanto a
 * pagina esta aberta. */
.window-page > .john-twin-pane {
  position: relative;
  display: flex;
  width: 100%;
  height: 100%;
  min-height: 0;
}
.window-page > .john-twin-pane > .sidebar {
  width: var(--left-panel-width, 280px);
  flex: none;
  min-height: 0;
  background: transparent !important;
  position: relative;
  isolation: isolate;
  border-right: 0 !important;
  --agent-avatar-outline: var(--johnbot-bg-canvas);
}
.window-page > .john-twin-pane > .sidebar::before {
  position: absolute;
  z-index: -1;
  content: "";
  pointer-events: none;
  inset: var(--left-header-height) 0 0 auto;
  width: 1px;
  border: 0;
  border-radius: 0;
  background: var(--johnbot-border);
}
.window-page > .john-twin-pane > .sidebar:not(.sidebar-compact) .sidebar-topbar {
  position: relative;
  border-bottom: 0 !important;
}
.app-window
  > :is(.web-app-frame, .app-frame:not(.app-frame-platform-darwin)):not(.app-frame-with-server-rail)
  .john-twin-pane
  > .sidebar:not(.sidebar-compact)
  .sidebar-topbar {
  padding-left: var(--johnbot-space-3);
}
.app-window
  > .app-frame-platform-darwin:not(.app-frame-with-server-rail)
  .john-twin-pane
  > .sidebar:not(.sidebar-compact)
  .sidebar-topbar {
  padding-left: var(--johnbot-space-6);
}
.window-page > .john-twin-pane > .sidebar:not(.sidebar-compact) .sidebar-topbar::after {
  position: absolute;
  top: 50%;
  right: 0;
  width: 1px;
  height: var(--window-hairline-height);
  translate: 0 -50%;
  background: var(--johnbot-border-strong);
  content: "";
  pointer-events: none;
}
.window-page > .john-twin-pane > .sidebar .sidebar-search-wrap {
  padding-top: 11px;
}
.window-page > .john-twin-pane > .sidebar .sidebar-compact-search {
  top: 11px;
}
.window-page > .john-twin-pane > .left-panel-resizer {
  flex: none;
  margin-left: -8px;
  margin-right: -8px;
}
.window-page > .john-twin-pane > .diagram-view {
  flex: 1;
  min-width: 0;
  background: transparent;
}
.window-page > .john-twin-pane > .diagram-view .diagram-view-header {
  border-bottom: 0;
  background: transparent;
}
.window-page > .john-twin-pane > .diagram-view .diagram-view-body {
  border-top: 0;
  border-right: 0;
  border-radius: 0 0 calc(var(--johnbot-radius-card) - 1px) 0;
}
/* Com o painel de configuracoes aberto, o canvas encolhe para nao ficar por baixo dele. */
.window-page > .john-twin-pane:has(> .settings-panel) > .diagram-view {
  margin-right: var(--side-panel-width, 360px);
}
.window-page > .john-twin-pane > .settings-panel {
  /* Como na tela de agentes: o painel abre em dock (a regra side-panel-docked o
     posiciona abaixo da barra superior e a aba o nomeia no topo). */
  background: var(--johnbot-bg-canvas);
  border-left: 1px solid var(--johnbot-border);
}

/* === from: @johnbot/ui/features/settings/opencode-key-dialog.css === */
/*
 * The OpenCode Go key dialog. It opens on top of the settings modal, so its layer is one above
 * the shared dialog layer rather than the same one -- both portals are children of `body`, and
 * relying on insertion order alone would break the first time a caller mounts it from elsewhere.
 *
 * Minimal on purpose: left-aligned title with one dynamic description line instead of stacked
 * notice cards, matching the small confirm dialogs.
 */

.opencode-key-backdrop {
  z-index: calc(var(--johnbot-layer-dialog) + 1);
}

.opencode-key-dialog {
  width: min(400px, 100%);
  max-height: calc(100dvh - var(--johnbot-space-6) * 2);
  overflow-y: auto;
  outline: 0;
  border-radius: var(--johnbot-radius-xl);
  background: var(--johnbot-bg-control);
  padding: var(--johnbot-space-6);
  color: var(--johnbot-text-primary);
  animation: opencode-key-dialog-in var(--johnbot-duration-slow) var(--johnbot-ease-out) both;
}

.opencode-key-header {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: var(--johnbot-space-1);
}

.opencode-key-title {
  margin: 0;
  font-size: var(--johnbot-text-xl);
  line-height: var(--johnbot-leading-xl);
  font-weight: var(--johnbot-weight-semibold);
  letter-spacing: var(--johnbot-tracking-tight);
}

.opencode-key-description {
  margin: 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
}

.opencode-key-status-dot {
  display: inline-block;
  width: 6px;
  height: 6px;
  margin-right: var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-success);
}

.opencode-key-form {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-4);
  margin: var(--johnbot-space-4) 0 0;
}

.opencode-key-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: var(--johnbot-space-2);
}

@keyframes opencode-key-dialog-in {
  from {
    opacity: 0;
    transform: scale(0.97);
  }
}

/* === from: ./features/settings/settings-mobile-connect.css === */
/* Mobile Connect: the phones as cards, with the permanent link as one more card. "Add phone" and
 * the permanent link open a dialog that shows one code at a time, so a phone camera cannot catch
 * the wrong code. */
.settings-mobile-app-tab {
  display: inline-flex;
  align-items: center;
  gap: var(--johnbot-space-1-5);
}

.settings-mobile-app-tab > svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: 0 0 auto;
}

.settings-mobile-app-qr-platform {
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
}

.settings-mobile-app-qr-logo {
  width: 20px;
  height: 20px;
  flex: 0 0 auto;
}

/* A code and the tag that says what it does. */
.settings-mobile-qr {
  display: grid;
  justify-items: center;
  gap: var(--johnbot-space-2);
}

.settings-mobile-qr .ui-qr-code {
  overflow: hidden;
  border-radius: var(--johnbot-radius-md);
}

/* A new code settles in, so a change of code reads as a new code. */
.settings-mobile-qr-code {
  animation: settings-mobile-qr-in var(--johnbot-duration-overlay) var(--johnbot-ease-out);
}

.settings-mobile-qr-slot {
  display: grid;
  place-items: center;
  align-content: center;
  gap: var(--johnbot-space-2);
  border: 1px dashed var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-md);
}

.settings-mobile-qr-tag {
  display: inline-flex;
  align-items: center;
  gap: var(--johnbot-space-1-5);
  min-height: 24px;
  padding: 0 var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-control);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
  white-space: nowrap;
}

.settings-mobile-qr-tag > svg {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  flex: 0 0 auto;
}

.settings-mobile-qr-tag[data-kind="signin"] {
  background: var(--johnbot-accent-soft);
  color: var(--johnbot-accent-text);
}

.settings-mobile-qr-tag[data-kind="permanent"] {
  background: var(--johnbot-warning-soft);
  color: var(--johnbot-warning-text);
}

.settings-mobile-qr-tag[data-kind="success"] {
  background: var(--johnbot-success-soft);
  color: var(--johnbot-success-text);
}

.settings-mobile-qr-tag-time {
  font-variant-numeric: tabular-nums;
  opacity: 0.8;
}

.settings-mobile-link-warning {
  display: inline-flex;
  align-items: center;
  gap: var(--johnbot-space-1-5);
  color: var(--johnbot-warning-text);
}

.settings-mobile-link-warning > svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.settings-mobile-connect-qr-stage {
  position: relative;
  flex: 0 0 auto;
}

.settings-mobile-connect-qr-stage .ui-qr-code {
  transition:
    opacity var(--johnbot-duration-normal) ease-out,
    filter var(--johnbot-duration-overlay) ease-out,
    transform var(--johnbot-duration-overlay) var(--johnbot-ease-out);
}

.settings-mobile-connect-qr-stage[data-success] .ui-qr-code {
  opacity: 0.18;
  filter: blur(2px);
  transform: scale(0.97);
}

.settings-mobile-connect-success-mark {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: var(--johnbot-success);
  animation: settings-mobile-connect-success-enter var(--johnbot-duration-overlay) var(--johnbot-ease-out) both;
}

.settings-mobile-connect-success-mark::before {
  position: absolute;
  width: 84px;
  height: 84px;
  border: 1px solid var(--johnbot-success);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-success-soft);
  content: "";
  animation: settings-mobile-connect-success-ring 600ms var(--johnbot-ease-out) both;
}

.settings-mobile-connect-success-mark > svg {
  position: relative;
  width: 58px;
  height: 58px;
  padding: var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-surface-raised);
  filter: drop-shadow(0 6px 16px var(--johnbot-shadow-popover-ambient));
