  animation: settings-mobile-connect-success-pop 420ms var(--johnbot-ease-out) both;
}

.settings-mobile-connect-success-mark > svg path {
  stroke-dasharray: 24;
  stroke-dashoffset: 24;
  animation: settings-mobile-connect-check-draw 360ms var(--johnbot-duration-fast) var(--johnbot-ease-out) forwards;
}

.settings-mobile-phones {
