}

.settings-mobile-route-option {
  display: flex;
  min-width: 0;
}

.settings-mobile-route-card {
  display: flex;
  flex: 1;
  align-items: flex-start;
  gap: var(--johnbot-space-3);
  min-width: 0;
  padding: var(--johnbot-space-3) var(--johnbot-space-4);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-control);
  box-shadow: inset 0 0 0 1px var(--johnbot-border);
  cursor: pointer;
  transition-property: background-color, box-shadow;
  transition-duration: var(--johnbot-duration-hover), var(--johnbot-duration-normal);
  transition-timing-function: var(--johnbot-ease-out);
}

.settings-mobile-route-card:hover {
  background: var(--johnbot-bg-control-hover);
}

.settings-mobile-route-card[data-disabled] {
  cursor: default;
}

.settings-mobile-route-card[data-checked] {
  box-shadow:
    inset 0 0 0 1.5px var(--johnbot-accent),
    0 1px 3px var(--johnbot-shadow-popover-ambient);
}

/* A ring, filled when the route is selected. */
.settings-mobile-route-dot {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  margin-top: 1px;
  border-radius: var(--johnbot-radius-pill);
  box-shadow: inset 0 0 0 1.5px var(--johnbot-text-muted);
  transition: box-shadow var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

.settings-mobile-route-dot::after {
  width: 8px;
  height: 8px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-accent);
  content: "";
  transform: scale(0);
  transition: transform var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

.settings-mobile-route-card[data-checked] .settings-mobile-route-dot {
  box-shadow: inset 0 0 0 1.5px var(--johnbot-accent);
}

.settings-mobile-route-card[data-checked] .settings-mobile-route-dot::after {
  transform: scale(1);
}

.settings-mobile-route-option:has(:focus-visible) .settings-mobile-route-card {
  box-shadow: var(--johnbot-focus-ring);
}

.settings-mobile-route-text {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-1);
  min-width: 0;
}

.settings-mobile-route-name {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--johnbot-space-2);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
}

.settings-mobile-route-hint {
