/* === from: @johnbot/ui/features/settings/integration-layout.css === */
/* The shared integration layout: see IntegrationLayout.tsx. */

.integration-logo-tile {
  --integration-tile: 36px;
  display: inline-grid;
  flex: none;
  width: var(--integration-tile);
  height: var(--integration-tile);
  place-items: center;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-surface-raised);
  color: var(--johnbot-text-primary);
}

.integration-logo-tile[data-size="lg"] {
  --integration-tile: 48px;
  border-radius: var(--johnbot-radius-lg);
}

.integration-logo-tile > svg {
  width: 55%;
  height: 55%;
}

/* An app icon fills its tile. */
.integration-logo-tile > img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: inherit;
}

.integration-status {
  gap: var(--johnbot-space-1);
}

.integration-status-dot {
  width: 6px;
  height: 6px;
  border-radius: var(--johnbot-radius-pill);
  background: currentColor;
}

.integration-status[data-status="unavailable"] .integration-status-dot {
  background: var(--johnbot-transparent);
  box-shadow: inset 0 0 0 1px currentColor;
}

/* ------------------------------------------------ page header */

/* One gap between every part of an integration page. */
.integration-page {
  display: grid;
  gap: var(--johnbot-space-6);
}

.integration-detail-header {
  display: flex;
  gap: var(--johnbot-space-3);
  align-items: center;
}

.integration-detail-copy {
  display: grid;
  flex: 1;
  gap: var(--johnbot-space-1);
  min-width: 0;
}

.integration-detail-title {
  display: flex;
  gap: var(--johnbot-space-2);
  align-items: center;
}

.integration-detail-actions {
  display: flex;
  flex: none;
  gap: var(--johnbot-space-2);
}

/* ------------------------------------------------ connect dialog */

.integration-wizard {
  display: grid;
  gap: var(--johnbot-space-4);
  padding: var(--johnbot-space-6);
  border-radius: var(--johnbot-radius-xl);
  background: var(--johnbot-bg-sheet);
  box-shadow: var(--johnbot-shadow-dialog);
}

.integration-wizard-head {
  display: grid;
  gap: var(--johnbot-space-2);
  justify-items: center;
  text-align: center;
}

.integration-wizard-logos {
  display: flex;
  gap: var(--johnbot-space-2);
  align-items: center;
  margin-bottom: var(--johnbot-space-2);
}

.integration-wizard-app {
  width: 36px;
  height: 36px;
}

/* Dots flow from johnBot to the other app while the flow runs. */
.integration-wizard-link {
  width: 40px;
  height: 2px;
  border-radius: var(--johnbot-radius-pill);
  background:
    radial-gradient(circle, var(--johnbot-accent) 0 1px, var(--johnbot-transparent) 1.5px) 0 50% / 8px 2px repeat-x;
  animation: integration-wizard-flow 0.6s linear infinite;
}

@keyframes integration-wizard-flow {
  to {
    background-position-x: 8px;
  }
}

.integration-wizard-logos[data-link="connected"] .integration-wizard-link {
  background: var(--johnbot-success);
  animation: none;
}

.integration-wizard-logos[data-link="broken"] .integration-wizard-link {
  background:
    radial-gradient(circle, var(--johnbot-border-strong) 0 1px, var(--johnbot-transparent) 1.5px) 0 50% / 8px 2px
    repeat-x;
  animation: none;
}

/* The other app breathes while johnBot waits for it. */
.integration-wizard-target {
  display: inline-grid;
  border-radius: var(--johnbot-radius-md);
}

.integration-wizard-logos[data-link="connecting"] .integration-wizard-target {
  animation: integration-wizard-pulse 1.8s var(--johnbot-ease-out) infinite;
}

.integration-wizard-logos[data-link="connected"] .integration-wizard-target {
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--johnbot-success) 30%, var(--johnbot-transparent));
}

@keyframes integration-wizard-pulse {
  0% {
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--johnbot-accent) 45%, var(--johnbot-transparent));
  }
  100% {
    box-shadow: 0 0 0 8px var(--johnbot-transparent);
  }
}

@media (prefers-reduced-motion: reduce) {
  .integration-wizard-link,
  .integration-wizard-logos[data-link="connecting"] .integration-wizard-target {
    animation: none;
  }
}

.integration-wizard-body {
  display: grid;
  gap: var(--johnbot-space-3);
}

/* A body whose parts are all hidden, such as a plugin dialog before a failure, takes no gap. */
.integration-wizard-body:empty {
  display: none;
}

.integration-wizard-form {
  display: grid;
  gap: var(--johnbot-space-4);
}

.integration-wizard-foot {
  display: flex;
  gap: var(--johnbot-space-2);
  justify-content: flex-end;
}

/* CopyButton draws its icon at full size; match the 14px icons of the other footer buttons. */
.integration-wizard-foot .ui-button > svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

/* Above the settings window the flow opens from. */
.integration-dialog-backdrop {
  z-index: calc(var(--johnbot-layer-dialog) + 1);
}

.integration-wizard-dialog {
  position: fixed;
  top: 50%;
  left: 50%;
  z-index: calc(var(--johnbot-layer-dialog) + 1);
  width: min(440px, calc(100vw - var(--johnbot-space-6) * 2));
  max-height: calc(100dvh - var(--johnbot-space-6) * 2);
  overflow-y: auto;
  outline: 0;
  transform: translate(-50%, -50%);
}

/* A page drawn in the dialog, such as a joined server's sign-in page, needs room to type in. */
.integration-wizard-dialog[data-wide] {
  width: min(720px, calc(100vw - var(--johnbot-space-6) * 2));
}

/* Over the Marketplace window and the menus it opens. Both portals are children of `body`, so the
   order of insertion alone cannot put this one on top. */
:is(.integration-dialog-backdrop, .integration-wizard-dialog)[data-nested] {
  z-index: calc(var(--johnbot-layer-dialog-host) + 2);
}

.integration-wizard-dialog h2 {
  margin: 0;
}

.integration-dialog-close {
  position: absolute;
  top: var(--johnbot-space-3);
  right: var(--johnbot-space-3);
}

/* ------------------------------------------------ stepper */

.integration-stepper {
  display: flex;
  align-items: center;
  margin: 0 0 var(--johnbot-space-2);
  padding: 0;
  list-style: none;
}

.integration-step {
  display: flex;
  align-items: center;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

/* The line to a step: quiet until the flow reaches that step, then it fills from the left. */
.integration-step + .integration-step::before {
  display: block;
  width: 24px;
  height: 2px;
  margin-inline: var(--johnbot-space-1);
  border-radius: var(--johnbot-radius-pill);
  background:
    linear-gradient(to right, var(--johnbot-success), var(--johnbot-accent)) no-repeat,
    var(--johnbot-border-strong);
  background-size:
    0% 100%,
    auto;
  content: "";
}

.integration-step + .integration-step[data-state="current"]::before {
  background-size:
    100% 100%,
    auto;
  animation: integration-step-fill 0.4s var(--johnbot-ease-out);
}

.integration-step + .integration-step[data-state="done"]::before {
  background:
    linear-gradient(var(--johnbot-success), var(--johnbot-success)) no-repeat,
    var(--johnbot-border-strong);
  background-size:
    100% 100%,
    auto;
  animation: integration-step-fill 0.4s var(--johnbot-ease-out);
}

@keyframes integration-step-fill {
  from {
    background-size:
      0% 100%,
      auto;
  }
}

@media (prefers-reduced-motion: reduce) {
  .integration-step + .integration-step[data-state="current"]::before,
  .integration-step + .integration-step[data-state="done"]::before {
    animation: none;
  }
}

.integration-step-index {
  display: inline-grid;
  box-sizing: border-box;
  width: 20px;
  height: 20px;
  place-items: center;
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-pill);
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
  font-weight: var(--johnbot-weight-medium);
  line-height: 1;
}

.integration-step[data-state="current"] {
  color: var(--johnbot-text-primary);
}

.integration-step[data-state="current"] .integration-step-index {
  border-color: var(--johnbot-accent);
  background: var(--johnbot-accent);
  color: var(--johnbot-text-on-accent);
}

.integration-step[data-state="done"] .integration-step-index {
  border-color: var(--johnbot-success);
  color: var(--johnbot-success);
}

/* ------------------------------------------------ card content */

/* Content of a card that is not rows: a form, a list, information. One body, so no row divider cuts it. */
.integration-card-body {
  display: grid;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-3) var(--johnbot-space-4);
}

/* A field in a card has the size of the buttons beside it, as in Server settings. */
.integration-card-body :where(.ui-input) {
  font-size: var(--johnbot-text-lg);
  line-height: var(--johnbot-leading-lg);
}

/* The last line of a card: what the rows above it mean. */
.integration-card-note {
  padding: var(--johnbot-space-3) var(--johnbot-space-4);
}

/* On the card fill, the danger tone needs its text step for contrast. */
.integration-card-note[data-tone="danger"] {
  color: var(--johnbot-danger-text);
}

/* ------------------------------------------------ disconnect dialog */

/* What a disconnect removes and what it keeps, one line each. */
.integration-effects {
  display: grid;
  margin: 0;
  padding: var(--johnbot-space-1);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-surface);
  list-style: none;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
}

.integration-effects li {
  display: flex;
  gap: var(--johnbot-space-3);
  align-items: center;
  padding: var(--johnbot-space-2);
}

.integration-effects li + li {
  border-top: 1px solid var(--johnbot-border);
}

.integration-effect-icon {
  display: inline-grid;
  flex: none;
  width: 28px;
  height: 28px;
  place-items: center;
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-surface-raised);
  color: var(--johnbot-text-muted);
}

.integration-effects .integration-effect-icon > svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.integration-effects li[data-tone="danger"] .integration-effect-icon {
  background: var(--johnbot-danger-soft);
  color: var(--johnbot-danger-text);
}

.integration-effects li[data-tone="success"] .integration-effect-icon {
  background: var(--johnbot-success-soft);
  color: var(--johnbot-success);
}

/* The label on the soft danger fill reads the text step, as the shared confirmation does for contrast. */
.integration-confirm.ui-button-variant-destructive {
  color: var(--johnbot-danger-text);
}

/* ------------------------------------------------ linked rows */

/* The whole row opens the integration, as on Marketplace cards. Buttons in the row stay on top. */
.integrations-hub-row {
  position: relative;
  border-radius: var(--johnbot-radius-md);
  transition: background-color var(--johnbot-duration-hover) var(--johnbot-ease-out);
}

.integrations-hub-row:has(> .integrations-hub-hitarea:hover) {
  background: var(--johnbot-hover);
}

.integrations-hub-hitarea {
  position: absolute;
  z-index: 1;
  inset: 0;
  width: auto;
  height: auto;
  padding: 0;
  border: 0;
  border-radius: inherit;
  background: var(--johnbot-transparent);
  cursor: pointer;
  transition: none;
}

.integrations-hub-hitarea:hover:not(:disabled):not([data-disabled]) {
  background: var(--johnbot-transparent);
}

.integrations-hub-hitarea:focus-visible {
  outline: 2px solid var(--johnbot-border-focus);
  outline-offset: -2px;
}

.integrations-hub-actions {
  gap: var(--johnbot-space-3);
}

.integrations-hub-actions .ui-button {
  position: relative;
  z-index: 2;
}

.integrations-hub-chevron {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  margin: 0 var(--johnbot-space-1-5);
  color: var(--johnbot-text-muted);
}

.integrations-face-stack {
  display: inline-flex;
  gap: var(--johnbot-space-0-5);
  align-items: center;
}

.integrations-face-more {
  display: inline-grid;
  min-width: 24px;
  height: 24px;
  padding: 0 var(--johnbot-space-1);
  place-items: center;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-control);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
}

.integrations-agent-face {
  --integrations-agent-face-size: 32px;
  display: inline-block;
  flex: none;
  width: var(--integrations-agent-face-size);
  height: var(--integrations-agent-face-size);
}

.integrations-agent-face[data-size="sm"] {
  --integrations-agent-face-size: 24px;
}

/* An agent avatar stands low in its box. Lift it to the middle, as the marketplace avatar does. */
.integrations-agent-face > * {
  --agent-avatar-optical-offset: calc(var(--integrations-agent-face-size) * -0.14);
  width: 100%;
  height: 100%;
}

/* === from: @johnbot/ui/features/settings/provider-settings-page.css === */
/* Settings > Providers. The settings card and row classes do the layout; these rules add only what
   they do not have. */

.provider-settings-stack {
  display: grid;
  gap: var(--johnbot-space-6);
}

/* The select value is a block; the logo and the name center in it. */
.provider-settings-select {
  width: 168px;
}

.provider-settings-select .ui-select-value,
.provider-settings-select-option {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.provider-settings-logo-off {
  opacity: 0.44;
}

.provider-settings-stack .ui-item-description.provider-settings-warning {
  color: var(--johnbot-warning-text);
}

.provider-settings-stack .ui-item-description.provider-settings-error {
  color: var(--johnbot-danger-text);
}

/* An account with two lines of text keeps its buttons on the title line. */
.provider-settings-account.ui-item {
  align-items: flex-start;
}

.provider-settings-account .ui-item-content {
  gap: var(--johnbot-space-1);
}

.provider-settings-account .provider-picker-account-rename {
  max-width: 280px;
}

/* The usage badge is a shared badge that opens the usage popover of the app. */
.provider-settings-usage-badge {
  cursor: pointer;
  font: inherit;
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-sm);
}

.provider-settings-usage-badge:focus-visible {
  outline: 2px solid var(--johnbot-focus-ring);
  outline-offset: 2px;
}

.provider-settings-progress {
  max-width: 320px;
}

/* === from: @johnbot/ui/features/settings/github-connector.css === */
/* UserAvatar has no style of its own: the initials, or GitHub's picture when the account has one. */
.github-connector-avatar {
  display: inline-grid;
  flex: none;
  width: 32px;
  height: 32px;
  place-items: center;
  overflow: hidden;
  border-radius: var(--johnbot-radius-pill);
  background: linear-gradient(135deg, var(--johnbot-accent-strong), var(--johnbot-onboarding-desktop-indigo));
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-semibold);
}

.github-connector-avatar > img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.github-connector-search {
  position: relative;
  display: flex;
  align-items: center;
}

.github-connector-search > svg {
  position: absolute;
  left: var(--johnbot-space-3);
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  color: var(--johnbot-text-muted);
  pointer-events: none;
}

.github-connector-search input {
  width: 100%;
  padding-left: calc(var(--johnbot-space-3) * 2 + var(--johnbot-icon-sm));
}

/* A long list scrolls inside the card, so Disconnect stays near the top of the tab. The rows' hover fill goes past
   the text, so the names line up with the search field. */
.github-connector-repository-list {
  display: grid;
  max-height: 260px;
  margin: 0 calc(var(--johnbot-space-2) * -1);
  padding: 0;
  overflow-y: auto;
  list-style: none;
}

.github-connector-repository {
  display: flex;
  gap: var(--johnbot-space-2);
  align-items: center;
  justify-content: space-between;
  /* The same height with and without the Private badge. */
  min-height: 36px;
  padding: 0 var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-md);
  transition: background-color var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.github-connector-repository:hover {
  background: var(--johnbot-hover);
}

.github-connector-repository-name {
  min-width: 0;
}

.github-connector-repository-owner {
  color: var(--johnbot-text-muted);
}

.github-connector-private {
  flex: none;
  gap: var(--johnbot-space-1);
}

/* ------------------------------------------------ connect dialog */

.github-connector-center {
  display: grid;
  min-height: 96px;
  place-items: center;
}

/* The code is about to be typed on another screen, so each character has its own tile. */
.github-connector-code {
  display: flex;
  gap: var(--johnbot-space-1-5);
  justify-content: center;
}

.github-connector-code-char {
  display: inline-grid;
  width: 36px;
  height: 48px;
  place-items: center;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-surface);
  font-family: var(--johnbot-font-mono);
  font-size: var(--johnbot-text-xl);
  font-weight: var(--johnbot-weight-semibold);
}

.github-connector-code-char[data-separator="true"] {
  width: 12px;
  border-color: var(--johnbot-transparent);
  background: var(--johnbot-transparent);
  color: var(--johnbot-text-muted);
}

.github-connector-waiting {
  display: flex;
  gap: var(--johnbot-space-2);
  align-items: center;
  justify-content: center;
}

.github-connector-done {
  display: flex;
  gap: var(--johnbot-space-3);
  align-items: center;
  padding: var(--johnbot-space-3) var(--johnbot-space-4);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-success-wash);
}

.github-connector-done > div {
  display: grid;
  flex: 1;
}

/* === from: @johnbot/ui/features/settings/onepassword-connector.css === */
/* A vault secret: the labelled field, and its buttons in line with the field, not with the label. */
.vault-secret-form {
  display: flex;
  align-items: flex-end;
  gap: var(--johnbot-space-3);
}

.vault-secret-form > .ui-field {
  flex: 1;
  min-width: 0;
}

.vault-secret-actions {
  display: flex;
  gap: var(--johnbot-space-2);
  align-items: center;
}

/* A joined server's Bitwarden form: one field per row, the buttons under them. */
.bitwarden-connector-host-form {
  display: grid;
  gap: var(--johnbot-space-3);
}

.bitwarden-connector-actions {
  display: flex;
  gap: var(--johnbot-space-2);
  align-items: center;
}

/* A step's text is its instruction, so it wraps instead of ending in an ellipsis. */
.onepassword-connector-step .ui-item-description {
  white-space: normal;
}

.onepassword-connector-step .ui-item-media {
  color: var(--johnbot-text-muted);
}

.onepassword-connector-step[data-step="done"] .ui-item-media {
  color: var(--johnbot-success);
}

/* A step whose earlier step is not done is quieter, so the eye goes to the one to do now. */
.onepassword-connector-step[data-step="waiting"] .ui-item-title {
  color: var(--johnbot-text-muted);
}

/* === from: @johnbot/ui/features/settings/slack-integration.css === */
/* Marketplace > Apps > Slack, Discord and Telegram: the channel pages (ChannelParts.tsx). */

.channel-stack {
  display: grid;
  gap: var(--johnbot-space-0-5);
  justify-items: start;
}

/* ------------------------------------------------ connect dialog */

.channel-checklist {
  display: grid;
  gap: var(--johnbot-space-2);
  margin: 0;
  padding: var(--johnbot-space-3) var(--johnbot-space-4);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-surface);
  list-style: none;
  font-size: var(--johnbot-text-sm);
}

.channel-checklist li {
  display: flex;
  gap: var(--johnbot-space-2);
  align-items: center;
}

.channel-checklist li[data-state="done"] {
  color: var(--johnbot-text-secondary);
}

.channel-checklist li[data-state="done"] svg {
  color: var(--johnbot-success);
}

.channel-checklist-dot {
  width: 14px;
  height: 14px;
  border: 1px solid var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-pill);
}

.channel-waiting {
  display: flex;
  gap: var(--johnbot-space-2);
  align-items: center;
  justify-content: center;
}

.channel-orchestrator-card {
  display: flex;
  gap: var(--johnbot-space-3);
  align-items: center;
  padding: var(--johnbot-space-3);
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-surface);
}

.channel-orchestrator-model {
  display: grid;
  gap: var(--johnbot-space-1);
}

/* ------------------------------------------------ Discord roles dialog */

.discord-roles {
  display: grid;
  max-height: 40vh;
  margin: 0;
  padding: var(--johnbot-space-1);
  overflow-y: auto;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-surface);
  list-style: none;
}

.discord-role-row {
  display: flex;
  gap: var(--johnbot-space-2);
  align-items: center;
  padding: var(--johnbot-space-1) var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-sm);
  cursor: pointer;
}

.discord-role-row:hover {
  background: var(--johnbot-bg-control-hover);
}

.discord-role-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* === from: @johnbot/ui/features/settings/hosted-servers.css === */
.hosted-servers-add {
  display: flex;
}

/* The list area before the first list answers. It fades in after a delay, so a fast answer does not flash it. */
.hosted-servers-loading {
  display: grid;
  place-items: center;
  padding: var(--johnbot-space-8);
  animation: hosted-servers-loading-in var(--johnbot-duration-normal) var(--johnbot-ease-out)
    var(--johnbot-loading-indicator-delay) both;
}

@keyframes hosted-servers-loading-in {
  from {
    opacity: 0;
  }
}

.hosted-servers-list .hosted-servers-row {
  min-height: 64px;
  align-items: center;
}

.hosted-servers-list .ui-item-content {
  min-width: 0;
}

.hosted-servers-list .ui-item-title {
  gap: var(--johnbot-space-2);
}

.hosted-servers-actions {
  flex-wrap: nowrap;
  justify-content: flex-end;
}

@media (max-width: 700px) {
  .hosted-servers-list .hosted-servers-row {
    align-items: flex-start;
    flex-direction: column;
  }

  .hosted-servers-actions {
    width: 100%;
    justify-content: flex-start;
  }
}

/* === from: @johnbot/ui/features/settings/profile.css === */
/* The Profile tab of Settings: the header, the year of activity, and its two dialogs. */

.profile-panel {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-6);
}

/* ─── Header ─── */

.profile-hero {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-3);
}

.profile-hero-avatar {
  display: grid;
  place-items: center;
  flex: none;
  width: calc(var(--johnbot-space-8) * 1.75);
  aspect-ratio: 1;
  border-radius: var(--johnbot-radius-pill);
  overflow: hidden;
  background: var(--johnbot-accent-soft);
  color: var(--johnbot-accent-hover);
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-semibold);
}

.profile-hero-avatar > img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  outline: 1px solid var(--johnbot-image-outline);
  outline-offset: -1px;
  border-radius: inherit;
}

.profile-hero-text {
  min-width: 0;
}

.profile-hero-text h3 {
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--johnbot-text-xl);
  font-weight: var(--johnbot-weight-semibold);
  color: var(--johnbot-text-primary);
}

.profile-hero-text p {
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--johnbot-text-sm);
  color: var(--johnbot-text-secondary);
}

.profile-hero-actions {
  display: flex;
  flex: none;
  gap: var(--johnbot-space-2);
  margin-inline-start: auto;
}

/* ─── Cards ─── */

/* The surface of a settings card (`.settings-modal-card`), for content that is not a row list. */
.profile-card {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-3);
  margin: 0;
  padding: var(--johnbot-space-4);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-surface);
}

/* Lists of rows: the rows give the rhythm, as the rows of a settings card do. */
.profile-card.profile-facts,
.profile-card.profile-ranking,
.profile-card.profile-bars {
  row-gap: 0;
  padding: var(--johnbot-space-1) var(--johnbot-space-4);
}

.profile-activity-placeholder {
  align-items: flex-start;
}

.profile-columns {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--johnbot-space-4);
  align-items: start;
}

.profile-columns > .ui-settings-section {
  height: 100%;
  grid-template-rows: auto 1fr;
}

.profile-facts {
  display: flex;
  flex-direction: column;
  margin: 0;
}

.profile-facts > div,
.profile-ranking li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-3);
  min-height: calc(var(--johnbot-space-8) + var(--johnbot-space-3));
  border-top: 1px solid var(--johnbot-border);
  font-size: var(--johnbot-text-sm);
}

.profile-facts > div:first-child,
.profile-ranking li:first-child {
  border-top: 0;
}

.profile-facts dt {
  flex: none;
  color: var(--johnbot-text-secondary);
  transition: color var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

.profile-facts dd {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-1-5);
  min-width: 0;
  margin: 0;
  overflow: hidden;
  white-space: nowrap;
  color: var(--johnbot-text-primary);
  font-weight: var(--johnbot-weight-medium);
}

.profile-ranking {
  list-style: none;
}

.profile-ranking li {
  justify-content: flex-start;
  color: var(--johnbot-text-primary);
  transition: opacity var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

.profile-ranking-avatar {
  width: var(--johnbot-space-6);
  height: var(--johnbot-space-6);
  flex: none;
}

.profile-ranking-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.profile-ranking strong,
.profile-bar-value {
  font-variant-numeric: tabular-nums;
  font-weight: var(--johnbot-weight-medium);
}

/* ─── Bars ─── */

/*
 * The label column is as wide as the longest model name, up to a limit, so every bar starts at the
 * same place. A longer name ends with an ellipsis.
 */
.profile-bars {
  display: grid;
  grid-template-columns: fit-content(45%) 1fr auto;
  column-gap: var(--johnbot-space-4);
  margin: 0;
  list-style: none;
}

.profile-bars li {
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: subgrid;
  align-items: center;
  min-height: calc(var(--johnbot-space-8) + var(--johnbot-space-1));
  font-size: var(--johnbot-text-sm);
  color: var(--johnbot-text-primary);
  transition: opacity var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

.profile-bar-label {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-1-5);
  min-width: 0;
  white-space: nowrap;
}

.profile-bar-name {
  overflow: hidden;
  text-overflow: ellipsis;
}

.profile-bar-track {
  height: var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-pill);
  background: color-mix(in srgb, var(--johnbot-text-primary) 7%, var(--johnbot-transparent));
  overflow: hidden;
}

.profile-bar-fill {
  display: block;
  height: 100%;
  border-radius: inherit;
}

.profile-bar-value {
  text-align: end;
  color: var(--johnbot-text-secondary);
}

/* ─── Heatmap ─── */

.profile-heatmap {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-1-5);
  min-width: 0;
}

.profile-heatmap-months,
.profile-heatmap-grid {
  display: grid;
  grid-template-columns: repeat(var(--profile-columns), minmax(0, 1fr));
  column-gap: var(--johnbot-space-0-5);
}

.profile-heatmap-months {
  font-size: var(--johnbot-text-sm);
  color: var(--johnbot-text-muted);
}

.profile-heatmap-months span {
  white-space: nowrap;
}

.profile-heatmap-grid {
  grid-template-rows: repeat(7, auto);
  grid-auto-flow: column;
  row-gap: var(--johnbot-space-0-5);
}

.profile-heat-cell {
  display: block;
  aspect-ratio: 1;
  border-radius: var(--johnbot-radius-xs);
  background: color-mix(in srgb, var(--johnbot-text-primary) 7%, var(--johnbot-transparent));
}

.profile-heat-cell[data-empty] {
  background: var(--johnbot-transparent);
}

.profile-heat-cell[data-level="1"] {
  background: color-mix(in srgb, var(--johnbot-accent) 32%, var(--johnbot-transparent));
}

.profile-heat-cell[data-level="2"] {
  background: color-mix(in srgb, var(--johnbot-accent) 55%, var(--johnbot-transparent));
}

.profile-heat-cell[data-level="3"] {
  background: color-mix(in srgb, var(--johnbot-accent) 78%, var(--johnbot-transparent));
}

.profile-heat-cell[data-level="4"] {
  background: var(--johnbot-accent);
}

.profile-heatmap-grid .profile-heat-cell[data-active] {
  outline: 1px solid var(--johnbot-text-primary);
  outline-offset: 1px;
}

/* One label for the whole year. It is fixed to the viewport, so a card that clips its content
   does not cut it. In a dialog it mounts in the dialog, above the overlay. */
.profile-heat-tooltip {
  position: fixed;
  z-index: var(--johnbot-layer-toast);
  transform: translate(-50%, calc(-100% - var(--johnbot-space-2)));
  pointer-events: none;
  white-space: nowrap;
  box-shadow: var(--johnbot-shadow-raised);
}

.profile-heatmap-legend {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: var(--johnbot-space-1);
  font-size: var(--johnbot-text-sm);
  color: var(--johnbot-text-muted);
}

.profile-heatmap-legend .profile-heat-cell {
  width: var(--johnbot-space-3);
}

/* ─── Dialogs ─── */

.profile-dialog {
  width: min(880px, 100%);
  max-height: calc(100dvh - 2 * var(--johnbot-space-6));
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-4);
  overflow: auto;
  padding: var(--johnbot-space-6);
  outline: 0;
  border-radius: var(--johnbot-radius-xl);
  border: 1px solid var(--johnbot-dialog-ring);
  background: var(--johnbot-bg-sidebar);
  color: var(--johnbot-text-primary);
}

.profile-dialog-header,
.profile-dialog-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-2);
}

.profile-dialog-footer {
  justify-content: flex-end;
}

.profile-dialog-title {
  margin: 0;
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-semibold);
}

.profile-share-image {
  display: block;
  width: 100%;
  height: auto;
  border-radius: var(--johnbot-radius-card);
  box-shadow: var(--johnbot-shadow-card);
}

.profile-share-placeholder {
  display: grid;
  place-items: center;
  aspect-ratio: 1200 / 690;
  border-radius: var(--johnbot-radius-card);
  background: var(--johnbot-bg-surface);
}

.profile-edit {
  width: min(440px, 100%);
}

.profile-edit-form {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-4);
}

.profile-edit-photo {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.profile-edit-photo .profile-edit-photo-trigger {
  width: calc(var(--johnbot-space-8) * 2.5);
  height: calc(var(--johnbot-space-8) * 2.5);
  overflow: visible;
}

.profile-edit-photo .profile-edit-avatar {
  font-size: var(--johnbot-text-xl);
}

.profile-edit-photo-badge {
  position: absolute;
  inset-block-end: 0;
  inset-inline-end: 0;
  display: grid;
  place-items: center;
  width: var(--johnbot-space-6);
  height: var(--johnbot-space-6);
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-bg-surface);
  color: var(--johnbot-text-secondary);
}

.profile-edit-photo-badge > svg {
  width: var(--johnbot-space-3);
  height: var(--johnbot-space-3);
}

/* ─── Tiles (last, so that their descendant rules do not override the ones above) ─── */

.profile-tiles {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(128px, 1fr));
  gap: var(--johnbot-space-2);
  margin: 0;
}

.profile-tile {
  --profile-step: calc(var(--johnbot-duration-fast) / 3);
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-1);
  padding: var(--johnbot-space-3);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-surface);
  transition: background-color var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

.profile-tile dt {
  font-size: var(--johnbot-text-sm);
  color: var(--johnbot-text-secondary);
}

.profile-tile dd {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-0-5);
  margin: 0;
}

.profile-tile strong {
  font-size: var(--johnbot-text-2xl);
  font-weight: var(--johnbot-weight-semibold);
  font-variant-numeric: tabular-nums;
  color: var(--johnbot-text-primary);
}

.profile-tile dd > span {
  font-size: var(--johnbot-text-sm);
  color: var(--johnbot-text-muted);
}

/* ─── Motion ─── */

/* Colour-only hovers stay for every user. Movement is only for users who allow it. */

.profile-tile:hover {
  background: linear-gradient(var(--johnbot-hover), var(--johnbot-hover)), var(--johnbot-bg-surface);
}

.profile-tile-value {
  white-space: pre;
}

.profile-tile .profile-tile-value.is-animating .t-digit {
  animation-delay: calc(
    var(--profile-i, 0) *
    var(--profile-step) *
    1.5 +
    var(--profile-c, 0) *
    var(--profile-step) /
    2
  );
}

.profile-facts > div:hover dt {
  color: var(--johnbot-text-primary);
}

/* The row under the pointer stays bright; the other rows step back. */
.profile-ranking:hover li:not(:hover),
.profile-bars:hover li:not(:hover) {
  opacity: 0.45;
}

.profile-bars li:hover .profile-bar-value {
  color: var(--johnbot-text-primary);
}

@media (prefers-reduced-motion: no-preference) {
  .profile-panel {
    --profile-step: calc(var(--johnbot-duration-fast) / 3);
  }

  /* The page builds from the top: each block rises one step after the block above it. */
  .profile-panel > * {
    animation: profile-rise var(--johnbot-duration-toast-enter) var(--johnbot-ease-out) backwards;
  }

  .profile-panel > :nth-child(2) {
    animation-delay: var(--profile-step);
  }

  .profile-panel > :nth-child(3) {
    animation-delay: calc(var(--profile-step) * 2);
  }

  .profile-panel > :nth-child(4) {
    animation-delay: calc(var(--profile-step) * 3);
  }

  .profile-panel > :nth-child(n + 5) {
    animation-delay: calc(var(--profile-step) * 4);
  }

  .profile-hero-avatar {
    animation: profile-pop var(--johnbot-duration-toast-enter) var(--johnbot-ease-out) backwards;
  }

  .profile-tile {
    transition:
      background-color var(--johnbot-duration-normal) var(--johnbot-ease-out),
      transform var(--johnbot-duration-normal) var(--johnbot-ease-out);
  }

  .profile-tile:hover {
    transform: translateY(calc(var(--johnbot-space-0-5) * -1));
  }

  /* The year fills in as a wave from the oldest week to this week. */
  .profile-heatmap-grid .profile-heat-cell {
    animation: profile-cell-in var(--johnbot-duration-overlay) var(--johnbot-ease-out) backwards;
    animation-delay: calc(var(--profile-col, 0) * var(--johnbot-duration-fast) / 15);
    transition: transform var(--johnbot-duration-fast) var(--johnbot-ease-out);
  }

  .profile-heatmap-grid .profile-heat-cell[data-active] {
    position: relative;
    z-index: 1;
    transform: scale(1.35);
  }

  /* The label fades in once, then glides from day to day. */
  .profile-heat-tooltip {
    animation: profile-tip-in var(--johnbot-duration-normal) var(--johnbot-ease-out) backwards;
    transition:
      left var(--johnbot-duration-fast) var(--johnbot-ease-out),
      top var(--johnbot-duration-fast) var(--johnbot-ease-out);
  }

  .profile-ranking li {
    animation: profile-slide-in var(--johnbot-duration-toast-enter) var(--johnbot-ease-out) backwards;
    animation-delay: calc(var(--johnbot-duration-slow) + var(--profile-i, 0) * var(--profile-step));
  }

  .profile-ranking-avatar {
    transition: transform var(--johnbot-duration-normal) var(--johnbot-ease-out);
  }

  .profile-ranking li:hover .profile-ranking-avatar {
    transform: scale(1.12) rotate(-6deg);
  }

  .profile-bar-fill {
    transform-origin: left center;
    animation: profile-grow calc(var(--johnbot-duration-overlay) * 2.5) var(--johnbot-ease-out) backwards;
    animation-delay: calc(var(--johnbot-duration-overlay) + var(--profile-i, 0) * var(--profile-step) * 2);
  }

  .profile-hero-actions svg {
    transition: transform var(--johnbot-duration-normal) var(--johnbot-ease-out);
  }

  .profile-hero-actions button:hover .profile-icon-share {
    transform: translateY(calc(var(--johnbot-space-0-5) * -1));
  }

  .profile-hero-actions button:hover .profile-icon-edit {
    transform: rotate(-14deg);
  }
}

@keyframes profile-rise {
  from {
    opacity: 0;
    transform: translateY(var(--johnbot-space-2));
  }
}

@keyframes profile-pop {
  from {
    opacity: 0;
    transform: scale(0.85);
  }
}

@keyframes profile-cell-in {
  from {
    opacity: 0;
    transform: scale(0.4);
  }
}

@keyframes profile-tip-in {
  from {
    opacity: 0;
    transform: translate(-50%, calc(-100% - var(--johnbot-space-1)));
  }
}

@keyframes profile-slide-in {
  from {
    opacity: 0;
    transform: translateX(calc(var(--johnbot-space-2) * -1));
  }
}

@keyframes profile-grow {
  from {
    transform: scaleX(0);
  }
}

/* === from: ./features/computer-use/computer-use.css === */
.computer-use-settings {
  display: grid;
  gap: var(--johnbot-space-6);
}

.computer-use-card:is(.ui-item-group) {
  overflow: hidden;
}

.computer-use-permission-icon {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-accent-soft);
}

.computer-use-permission-icon svg {
  width: 16px;
  height: 16px;
  color: var(--johnbot-accent-text);
}

.computer-use-alert {
  margin-top: var(--johnbot-space-3);
}

.computer-use-settings > .computer-use-alert:first-child,
.computer-use-compact > .computer-use-alert:first-child {
  margin-top: 0;
}

.computer-use-loading .computer-use-row {
  min-height: 60px;
}

.computer-use-skeleton-icon {
  width: 30px;
  height: 30px;
  border-radius: var(--johnbot-radius-md);
}

.computer-use-skeleton-title {
  width: 128px;
  height: 12px;
}

.computer-use-skeleton-description {
  width: min(220px, 70%);
  height: 10px;
  margin-top: var(--johnbot-space-2);
}

/*
 * Wide enough that nothing here wraps or is cut: the header sentence beside "Check again", and each
 * permission description beside its badge and button. `.ui-item-description` ends in an ellipsis
 * rather than a second line, so a card too narrow loses the words instead of folding them.
 */
.computer-use-compact {
  width: min(100%, 520px);
  margin-top: var(--johnbot-space-4);
  text-align: left;
}

.computer-use-compact-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--johnbot-space-3);
  margin: 0 var(--johnbot-space-1) var(--johnbot-space-2);
}

.computer-use-compact-header h2 {
  margin: 0;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-md);
}

.computer-use-compact-header p {
  margin: var(--johnbot-space-0-5) 0 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

/*
 * "Check again" sits on the same line as the heading, not under the rows: the grant it asks about is
 * given outside this window, so the button belongs to the card and not to any one permission.
 */
.computer-use-compact-header > .ui-button {
  flex: 0 0 auto;
}

.computer-use-compact .computer-use-card {
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-control);
}

.computer-use-compact .computer-use-row {
  min-height: 58px;
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
}

.computer-use-compact .computer-use-row + .computer-use-row {
  border-top: 1px solid var(--johnbot-border);
}

.computer-use-compact .ui-item-title {
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
}

.computer-use-compact .ui-item-description {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
}

@media (max-width: 640px) {
  .computer-use-row.ui-item {
    align-items: flex-start;
  }

  .computer-use-row .ui-item-actions {
    width: auto;
    padding-top: var(--johnbot-space-1);
  }
}

.computer-use-recheck {
  display: flex;
  justify-content: flex-end;
  margin-top: var(--johnbot-space-2);
}

/* A label-and-icon button carries no size of its own for the mark beside the word, and a 24px icon
   dwarfs a two-word label. */
.computer-use-recheck .ui-button > svg,
.computer-use-compact-header .ui-button > svg,
.computer-use-alert .ui-button > svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: 0 0 auto;
  stroke-width: var(--johnbot-icon-stroke);
}

/*
 * The hue over the window an agent works in: one even rim of the accent around the whole border,
 * with a short fall inward. The middle of the window keeps no paint at all, because the agent may
 * hold the window for minutes and what it types has to stay as readable as before.
 *
 * Nothing here moves. A turning or breathing edge is movement at the side of the eye for the whole
 * length of the task, which costs more attention than it returns.
 */
.computer-use-window-highlight {
  position: absolute;
  inset: 0;
  border-radius: var(--computer-use-window-radius);
  /*
   * The rim, then two falls inward from every edge: a near one that carries most of the hue and a
   * far one that takes it out slowly, so the window reads as tinted rather than outlined. All three
   * are even the whole way round.
   */
  box-shadow:
    inset 0 0 0 2px var(--johnbot-accent),
    inset 0 0 44px -4px var(--johnbot-accent-strong),
    inset 0 0 120px -8px var(--johnbot-accent-soft);
  /* The surface itself is click-through; this keeps a stray pointer rule from undoing that. */
  pointer-events: none;
}

/*
 * The overlay window that carries the rim. It covers the whole desktop and paints nothing of its
 * own: every pixel outside the rim stays transparent, so the applications below are seen and
 * clicked exactly as before. The frame inside it is what main places over one window.
 */
html:has(.computer-use-highlight-surface),
body:has(.computer-use-highlight-surface),
#root:has(.computer-use-highlight-surface) {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
}

.computer-use-highlight-surface {
  position: relative;
  width: 100%;
  height: 100%;
  background: transparent;
  pointer-events: none;
}

.computer-use-highlight-surface-frame {
  position: absolute;
  pointer-events: none;
}

/*
 * The agent cursor johnBot draws when the driver draws none, which is every desktop of more than
 * one display. The same dart as the driver theme, at about the size the driver renders it.
 *
 * The tip sits on the origin of the drawing, so the point main sends is the point the cursor holds
 * without any offset. `overflow: visible` keeps the outline, which is half outside the path, from
 * being cut at the edge of the box.
 */
.computer-use-agent-cursor {
  position: absolute;
  left: 0;
  top: 0;
  width: 22px;
  height: 24px;
  overflow: visible;
  fill: var(--johnbot-accent);
  /* The colour the accent carries text in, so the outline holds over any wallpaper. */
  stroke: var(--johnbot-text-on-accent);
  stroke-width: 5;
  /* Under the fill, so the outline reads as an edge rather than as a second, thicker dart. */
  paint-order: stroke fill;
  filter: drop-shadow(0 0 6px var(--johnbot-accent-strong));
  /* No transition: `ComputerUseAgentCursor` plays each move, and a transition would fight it. */
  pointer-events: none;
}

/*
 * The accent on the one row that still needs the user. `--johnbot-accent` is the colour of an
 * action here, and a panel of two rows says at a glance which one is left when only the ungranted
 * one carries it.
 */
.computer-use-grant:is(.ui-button) {
  border-color: transparent;
  background: var(--johnbot-accent);
  color: var(--johnbot-text-on-accent);
}

@media (hover: hover) and (pointer: fine) and (min-width: 601px) {
  .computer-use-grant:is(.ui-button):hover:not(:disabled):not([data-disabled]) {
    background: var(--johnbot-accent-hover);
  }
}

/*
 * The window that stands beside the System Settings pane. It is small, it is the only thing in its
 * own window, and the user reads it while looking at another application - so it carries the steps
 * and nothing else.
 */
.computer-use-help {
  height: 100vh;
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-4);
  /* Clear of the traffic lights, which sit over this surface on macOS. */
  padding: 44px var(--johnbot-space-4) var(--johnbot-space-4);
  background: var(--johnbot-bg-canvas);
  text-align: left;
}

.computer-use-help-header {
  display: flex;
  align-items: flex-start;
  gap: var(--johnbot-space-3);
}

.computer-use-help-icon {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-accent-soft);
}

.computer-use-help-icon svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  color: var(--johnbot-accent-text);
  stroke-width: var(--johnbot-icon-stroke);
}

.computer-use-help h1 {
  margin: 0;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-md);
}

.computer-use-help-header p {
  margin: var(--johnbot-space-0-5) 0 0;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.computer-use-help-steps {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-2);
  margin: 0;
  padding-left: var(--johnbot-space-4);
  /* The order of the two steps is the whole of the instruction, so the numbers have to be drawn. */
  list-style: decimal;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
