/* === from: ./features/servers/server-mcp.css === */
/*
 * The MCP section of the server settings modal. The list rows and the form both sit inside the
 * shared settings shell, so this file only carries what the primitives do not: the row line that
 * pairs a name with its status badge, the repeatable-row grids, and the panel-level save bar.
 */

/*
 * The list and the form are the two pages of a page-slide, so they share one grid cell. Each page
 * keeps the column layout the panel used to hold, which is what keeps the form's save bar at the
 * bottom of the panel.
 */
.server-mcp-panel {
  display: grid;
  grid-template: minmax(0, 1fr) / minmax(0, 1fr);
  min-height: 100%;
}

.server-mcp-panel.t-page-slide .t-page {
  position: static;
  grid-area: 1 / 1;
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-6);
  min-width: 0;
}

/*
 * Only the entering page is mounted, so its starting style is where the entry comes from. The
 * selector has to out-rank `.t-page-slide[data-page][data-page-id]` in transitions.css, which also
 * describes the page that is on screen: a starting style only wins a tie, not a lower specificity.
 */
@starting-style {
  .settings-modal .server-mcp-panel.t-page-slide .t-page[data-page-id] {
    opacity: 0;
    transform: translateX(var(--t-page-from-x));
    filter: blur(var(--page-blur));
  }
}

.server-mcp-section {
  min-width: 0;
}

.server-mcp-error {
  display: block;
  margin-bottom: var(--johnbot-space-2);
}

/* The managed runtime under a STDIO server, while it is downloading or after it failed. It sits
   above the list because it describes every row there, not one of them. */
.server-mcp-runtime-note {
  display: block;
  margin-bottom: var(--johnbot-space-2);
}

/* A test result is one sentence under the Test section's own button, not a field. */
.server-mcp-test-result {
  display: block;
  overflow-wrap: anywhere;
}

.server-mcp-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--johnbot-space-3);
  border: 1px dashed var(--johnbot-border);
  border-radius: var(--johnbot-radius-card);
  padding: var(--johnbot-space-8) var(--johnbot-space-6);
  text-align: center;
}

/*
 * `.ui-button` leaves an icon at the lucide default of 24px, which towers over the label beside it.
 * The panel's buttons take the shared icon size and stroke, the way the other labelled icon buttons
 * in the app do.
 */
.server-mcp-panel .ui-button > svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  flex: 0 0 auto;
  stroke-width: var(--johnbot-icon-stroke);
}

.server-mcp-list {
  min-width: 0;
}

.server-mcp-row-icon {
  color: var(--johnbot-text-muted);
}

.server-mcp-row[data-disabled] .server-mcp-row-icon,
.server-mcp-row[data-disabled] .ui-item-content {
  opacity: 0.55;
}

.server-mcp-row-title {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  min-width: 0;
  flex-wrap: wrap;
}

/* The one action a row's sentence asks for: Sign in after a challenge, Cancel during the wait. */
.server-mcp-row-next {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  margin-top: var(--johnbot-space-1);
}

.server-mcp-row-menu {
  min-width: 180px;
}

/* Form */

.server-mcp-form {
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: var(--johnbot-space-6);
  min-width: 0;
}

.server-mcp-transport-panel {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-6);
  min-width: 0;
}

/* A fieldset so the legend names the group; the browser default frame is not wanted here. */
.server-mcp-repeat {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-2);
  min-width: 0;
  border: 0;
  margin: 0;
  padding: 0;
}

.server-mcp-repeat-legend {
  padding: 0;
}

.server-mcp-repeat-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.server-mcp-repeat-row-pair {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) auto;
}

.server-mcp-repeat-add {
  justify-content: center;
  width: 100%;
}

/* The exact address an OAuth app must allow, with its copy button. */
.server-mcp-callback {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  min-width: 0;
}

.server-mcp-callback-url {
  min-width: 0;
  overflow-wrap: anywhere;
  font-family: var(--johnbot-font-mono);
}

/* The modal footer belongs to the General tab, so the form carries its own bar at its foot. */
@media (max-width: 520px) {
  .server-mcp-repeat-row-pair {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .server-mcp-repeat-row-pair > .ui-input:first-child {
    grid-column: 1 / -1;
  }
}

/* === from: @johnbot/ui/features/marketplace/marketplace.css === */
/* The Marketplace window: agents, apps and skills, and a page for each. Tokens only. */

/* ---------------------------------------------------------------- window */

/* A page of the window: the window card draws the surface, the line and the corner. */
.skills-marketplace {
  /* One inset for the whole window: the top bar title and the body start on it. */
  --marketplace-inset: var(--johnbot-space-6);
  display: grid;
  /* The side panel has the width of the settings page nav. The top row is above both columns. */
  grid-template-columns: max(var(--left-panel-width, 280px), 220px) minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  width: 100%;
  height: 100%;
  overflow: hidden;
  color: var(--johnbot-text-primary);
}

/* Menus and the connect and confirm dialogs open over the window. */
.marketplace-menu {
  z-index: calc(var(--johnbot-layer-dialog-host) + 1);
}

body:has(.skills-marketplace) :is(.integration-dialog-backdrop, .integration-wizard-dialog):not([data-nested]) {
  z-index: calc(var(--johnbot-layer-dialog-host) + 1);
}

.skills-marketplace-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-3);
  grid-column: 1 / -1;
  min-height: 48px;
  padding: var(--johnbot-space-2) var(--johnbot-space-2) var(--johnbot-space-2) var(--marketplace-inset);
  border-bottom: 1px solid var(--johnbot-border);
}

/* ---------------------------------------------------------------- side panel */

/* As the settings page nav: the title and the kinds, then the apps that the user connected. */
.marketplace-nav {
  display: flex;
  grid-row: 2;
  grid-column: 1;
  min-width: 0;
  min-height: 0;
  flex-direction: column;
  gap: var(--johnbot-space-1);
  overflow-y: auto;
  padding: var(--johnbot-space-4) var(--johnbot-space-3) var(--johnbot-space-3);
  border-right: 1px solid var(--johnbot-border);
}

.marketplace-nav-title {
  margin: 0 0 var(--johnbot-space-3);
  padding: 0 var(--johnbot-space-2);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-lg);
}

/* The title takes the focus when the page opens, only so a screen reader reads it. */
.marketplace-nav-title:focus {
  outline: none;
}

.marketplace-nav-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

/* The icon column holds an app logo, which has its own margin, so it is one step bigger than a line icon. The kind
   icons stay at their size in its center, so all names start at the same place. */
.marketplace-nav-item {
  grid-template-columns: var(--johnbot-icon-lg) minmax(0, 1fr) auto;
}

/* A row is a shared Button: it keeps the text of a settings row, not the larger text of a button. */
.ui-button.marketplace-nav-item {
  font: inherit;
  font-size: var(--johnbot-text-md);
  white-space: normal;
}

.ui-button.marketplace-nav-item[aria-current] {
  font-weight: var(--johnbot-weight-medium);
}

/* The kind that holds the open page is selected, as the page itself is. */
.marketplace-nav-item[aria-current="location"] {
  background: var(--johnbot-bg-control-hover);
  color: var(--johnbot-text-primary);
  font-weight: var(--johnbot-weight-medium);
}

.marketplace-nav-item > svg:first-child {
  justify-self: center;
}

.marketplace-nav-count {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-regular);
  font-variant-numeric: tabular-nums;
}

.marketplace-nav-heading {
  margin: var(--johnbot-space-4) 0 var(--johnbot-space-1);
  padding: 0 var(--johnbot-space-2);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-sm);
}

.marketplace-nav-mark {
  display: grid;
  width: var(--johnbot-icon-lg);
  height: var(--johnbot-icon-lg);
  place-items: center;
  overflow: hidden;
  border-radius: var(--johnbot-radius-xs);
}

.marketplace-nav-mark > :is(svg, img) {
  width: 100%;
  height: 100%;
}

.marketplace-nav-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.marketplace-nav-item > .marketplace-nav-warning {
  color: var(--johnbot-warning-text);
}

.skills-marketplace-body {
  position: relative;
  grid-row: 2;
  grid-column: 2;
  overflow: auto;
  scrollbar-gutter: stable;
}

/* Each list and page has one width, so the content does not move when a page opens. */
.marketplace-frame {
  padding: var(--johnbot-space-6) var(--marketplace-inset) var(--johnbot-space-8);
}

.marketplace-frame > * {
  width: min(100%, 880px);
  margin-inline: auto;
}

.skills-marketplace-error {
  position: sticky;
  bottom: var(--johnbot-space-4);
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  width: fit-content;
  max-width: calc(100% - 32px);
  margin: 0 auto var(--johnbot-space-4);
  padding: var(--johnbot-space-1) var(--johnbot-space-1) var(--johnbot-space-1) var(--johnbot-space-3);
  border: 1px solid var(--johnbot-danger);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-control);
  color: var(--johnbot-danger);
  box-shadow: 0 12px 32px var(--johnbot-shadow-dialog);
}

.marketplace-visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* ---------------------------------------------------------------- heading */

.marketplace-heading {
  display: flex;
  flex: 1;
  align-items: center;
  gap: var(--johnbot-space-1-5);
  min-width: 0;
}

.marketplace-title {
  min-width: 0;
  margin: 0;
  overflow: hidden;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-lg);
  text-overflow: ellipsis;
  white-space: nowrap;
}

/*
 * A parent in the path is plain text until the pointer is on it: then it shows the outline button chip, as the parent
 * in the path did before. The start margin cancels the chip's padding and border, so the text stays on the inset. The
 * end margin cancels less, so the chip does not touch the separator.
 */
.skills-marketplace .marketplace-crumb-parent {
  flex: 0 1 auto;
  min-width: 0;
  margin-inline: calc(-1 * var(--johnbot-space-2) - 1px) calc(-1 * var(--johnbot-space-1));
  overflow: hidden;
  border-color: transparent;
  background: transparent;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.skills-marketplace .marketplace-crumb-parent:focus-visible {
  border-color: var(--johnbot-border);
  background: var(--johnbot-bg-control);
  color: var(--johnbot-text-primary);
}

@media (hover: hover) and (pointer: fine) {
  .skills-marketplace .marketplace-crumb-parent:hover:not(:disabled) {
    border-color: var(--johnbot-border);
    background: var(--johnbot-bg-control);
    color: var(--johnbot-text-primary);
  }
}

.marketplace-crumb-separator {
  flex: 0 0 auto;
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  color: var(--johnbot-text-muted);
}

/* A title takes focus when its view opens. The focus is for screen readers, not a control. */
.marketplace-title:focus,
.skills-marketplace-body h3[tabindex="-1"]:focus {
  outline: none;
}

/* ---------------------------------------------------------------- views */

.marketplace-view,
.marketplace-stack {
  display: grid;
  align-content: start;
  gap: var(--johnbot-space-6);
  min-width: 0;
}

.marketplace-head {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-4);
}

.marketplace-head-actions {
  display: flex;
  flex: 0 1 auto;
  align-items: center;
  min-width: 0;
  max-width: 50%;
  gap: var(--johnbot-space-1);
}

.marketplace-head-copy {
  display: grid;
  flex: 1;
  gap: var(--johnbot-space-1);
  min-width: 0;
}

.marketplace-page-title {
  margin: 0;
  overflow-wrap: anywhere;
}

.marketplace-command {
  overflow-wrap: anywhere;
  color: var(--johnbot-text-primary);
  font-family: var(--johnbot-font-mono);
  font-size: var(--johnbot-text-sm);
}

/* The head of a list: its title and one line, then the search and the filter on one row. */
.marketplace-browse {
  gap: var(--johnbot-space-8);
}

.marketplace-browse-head {
  display: grid;
  gap: var(--johnbot-space-6);
}

.marketplace-browse-copy {
  display: grid;
  gap: var(--johnbot-space-1);
}

.marketplace-browse-copy > p {
  margin: 0;
}

.marketplace-browse-title {
  margin: 0;
  font-size: var(--johnbot-text-3xl);
}

.marketplace-toolbar {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.marketplace-search {
  position: relative;
  flex: 1;
  min-width: 0;
}

.marketplace-install-menu {
  min-width: 220px;
}

/* The button can show an agent's name. A long name is cut, and the skill name keeps its space. */
.marketplace-install-trigger {
  min-width: 0;
  max-width: 100%;
}

.marketplace-install-trigger svg {
  flex: none;
}

.marketplace-install-label {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.marketplace-block {
  display: grid;
  gap: var(--johnbot-space-2);
}

.marketplace-block-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--johnbot-space-2);
}

.marketplace-block-copy {
  display: grid;
  gap: var(--johnbot-space-0-5);
  min-width: 0;
}

.marketplace-load-more {
  justify-self: center;
}

/* ---------------------------------------------------------------- avatars and marks */

.marketplace-avatar {
  --marketplace-avatar-size: 20px;
  display: inline-grid;
  flex: none;
  width: var(--marketplace-avatar-size);
  height: var(--marketplace-avatar-size);
}

.marketplace-avatar[data-size="xs"] {
  --marketplace-avatar-size: 16px;
}

.marketplace-avatar[data-size="md"] {
  --marketplace-avatar-size: 40px;
}

.marketplace-avatar[data-size="lg"] {
  --marketplace-avatar-size: 48px;
}

/* An agent avatar stands low in its box. Lift it to the middle, as the channel avatar does. */
.marketplace-avatar > .agent-avatar {
  --agent-avatar-optical-offset: calc(var(--marketplace-avatar-size) * -0.14);
  width: 100%;
  height: 100%;
}

/* A skill's icon, or a spark, on a quiet tile. */
.marketplace-skill-mark {
  display: inline-grid;
  flex: none;
  place-items: center;
  width: 20px;
  height: 20px;
  overflow: hidden;
  border-radius: var(--johnbot-radius-xs);
  background: var(--johnbot-bg-control);
  color: var(--johnbot-text-muted);
}

.marketplace-skill-mark[data-size="row"] {
  width: 36px;
  height: 36px;
  border-radius: var(--johnbot-radius-md);
}

.marketplace-skill-mark[data-size="md"] {
  width: 40px;
  height: 40px;
  border-radius: var(--johnbot-radius-md);
}

/* A plugin icon in a row. `PluginIcon` also draws the icon of the MCP connect dialog. */
.skills-marketplace-icon {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 42px;
  height: 42px;
  overflow: hidden;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-control);
  color: var(--johnbot-accent-text);
}

.skills-marketplace-icon:has(img) {
  border: 0;
  background: transparent;
}

.skills-marketplace-icon img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.skills-marketplace-icon svg {
  width: 20px;
  height: 20px;
}

.marketplace-skill-mark[data-kind="icon"] > img {
  width: 100%;
  height: 100%;
}

.marketplace-skill-mark[data-kind="none"] > * {
  width: 60%;
  height: 60%;
}

/* ---------------------------------------------------------------- cards */

.marketplace-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: var(--johnbot-space-3);
}

.marketplace-card {
  position: relative;
  display: grid;
  min-width: 0;
  grid-template-rows: auto 1fr auto;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-4);
  border: 1px solid var(--johnbot-border-grouped);
  border-radius: var(--johnbot-radius-card);
  background: var(--johnbot-bg-grouped);
  transition: background var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.marketplace-card:hover:not(.marketplace-card-skeleton) {
  background: var(--johnbot-bg-control-hover);
}

.marketplace-card-head {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-3);
  min-width: 0;
}

.marketplace-card-name {
  flex: 1;
  min-width: 0;
  margin: 0;
  overflow-wrap: anywhere;
}

/* The action sits above the hit area, so "Add" adds and the rest of the card opens the page. */
.marketplace-card-action {
  position: relative;
  z-index: 2;
  display: inline-flex;
  flex: 0 1 auto;
  align-items: center;
  gap: var(--johnbot-space-2);
  min-width: 0;
  max-width: 60%;
}

.marketplace-card-body {
  display: -webkit-box;
  margin: 0;
  overflow: hidden;
  color: var(--johnbot-text-secondary);
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
}

.marketplace-card-foot {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  min-height: 16px;
  font-variant-numeric: tabular-nums;
}

.marketplace-hitarea {
  position: absolute;
  inset: 0;
  z-index: 1;
  width: 100%;
  height: 100%;
  border-radius: inherit;
  background: transparent;
}

/* The card draws the hover. The shared ghost hover would cover the text above the hit area. */
.marketplace-hitarea:hover:not(:disabled) {
  background: transparent;
}

.marketplace-card-skeleton {
  grid-template-rows: auto auto auto;
}

.marketplace-skeleton-mark {
  width: 40px;
  height: 40px;
  border-radius: var(--johnbot-radius-md);
}

.marketplace-skeleton-line {
  width: 100%;
  height: 12px;
}

.marketplace-skeleton-line:last-child {
  width: 60%;
}

.marketplace-done {
  display: inline-flex;
  align-items: center;
  gap: var(--johnbot-space-1);
  color: var(--johnbot-success-text);
  font-size: var(--johnbot-text-sm);
  white-space: nowrap;
}

.marketplace-done > svg {
  width: var(--marketplace-done-icon, 14px);
  height: var(--marketplace-done-icon, 14px);
  color: var(--marketplace-done-mark, currentColor);
}

/* ---------------------------------------------------------------- rows */

.marketplace-rows {
  display: grid;
  margin: 0;
  padding: 0;
  list-style: none;
}

.marketplace-row {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-3);
  min-height: 52px;
  padding: var(--johnbot-space-1-5) var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-md);
}

.marketplace-row-copy {
  display: grid;
  flex: 1;
  gap: var(--johnbot-space-0-5);
  min-width: 0;
  overflow-wrap: anywhere;
}

/* ---------------------------------------------------------------- app list */

.marketplace-app-group {
  display: grid;
  gap: var(--johnbot-space-3);
  padding-top: var(--johnbot-space-4);
  border-top: 1px solid var(--johnbot-border);
}

.marketplace-app-group-title {
  display: flex;
  align-items: baseline;
  gap: var(--johnbot-space-2);
  margin: 0;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-semibold);
}

.marketplace-app-group-count {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-regular);
  font-variant-numeric: tabular-nums;
}

.marketplace-app-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  column-gap: var(--johnbot-space-6);
  row-gap: var(--johnbot-space-1);
  margin: 0;
  padding: 0;
  list-style: none;
}

/* The row opens the app page; the status control sits above the hit area. */
.marketplace-app-row {
  position: relative;
  display: flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-lg);
}

@media (hover: hover) and (pointer: fine) {
  .marketplace-app-row:hover {
    background: var(--johnbot-bg-control-hover);
  }

  /* The row hover has the color of the Connect button, so on a hovered row the button is one step lighter. */
  .marketplace-app-row:hover .marketplace-app-action[data-variant="secondary"]:not([data-disabled]) {
    background: var(--johnbot-bg-control-active);
  }
}

.skills-marketplace .marketplace-app-row-hit {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  padding: 0;
  border-radius: inherit;
  background: transparent;
}

/* The row draws the hover. The shared ghost hover would cover the text above the hit area. */
.skills-marketplace .marketplace-app-row-hit:hover:not(:disabled) {
  background: transparent;
}

/* A little bigger than the settings tile, so that a logo with its own margin still reads. */
.marketplace-app-row > .integration-logo-tile {
  --integration-tile: 40px;
  pointer-events: none;
}

.marketplace-app-row-copy {
  display: grid;
  flex: 1;
  min-width: 0;
  gap: var(--johnbot-space-0-5);
  pointer-events: none;
}

.marketplace-app-row-name {
  overflow: hidden;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-medium);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.marketplace-app-row-tagline {
  overflow: hidden;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.marketplace-app-row-status {
  position: relative;
  display: inline-flex;
  flex: none;
}

/* As tall as a button, so the rows keep one height. The check has the success color; the word stays quiet. */
.marketplace-app-row-status > .marketplace-done {
  height: var(--johnbot-control-md);
  gap: var(--johnbot-space-1-5);
  padding-inline: var(--johnbot-space-2);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  --marketplace-done-icon: var(--johnbot-icon-md);
  --marketplace-done-mark: var(--johnbot-success);
}

/* ---------------------------------------------------------------- pages */

.marketplace-page {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 220px;
  gap: var(--johnbot-space-8);
  align-items: start;
}

.marketplace-side {
  position: sticky;
  top: var(--johnbot-space-6);
  padding-left: var(--johnbot-space-6);
  border-left: 1px solid var(--johnbot-border);
}

/* `dt` and `dd` are direct children of the list, so each fact is one pair of grid rows. */
.marketplace-props {
  display: grid;
  gap: var(--johnbot-space-0-5);
  margin: 0;
}

.marketplace-props > dd {
  margin: 0 0 var(--johnbot-space-3);
}

.marketplace-props > dd:last-child {
  margin-bottom: 0;
}

/* The Information list of an app page: the label and the value side by side. */
.marketplace-info {
  grid-template-columns: minmax(120px, max-content) minmax(0, 1fr);
  column-gap: var(--johnbot-space-6);
  row-gap: var(--johnbot-space-2);
}

.marketplace-info > dd {
  margin: 0;
}

.skills-marketplace .marketplace-link {
  height: auto;
  padding: 0;
  /* The size of the other values in the list. */
  font-size: var(--johnbot-text-md);
}

/* The skill-preview card, with room for more than one request. */
.marketplace-try {
  display: grid;
  gap: var(--johnbot-space-2);
}

.skill-preview-card.marketplace-try-card {
  gap: var(--johnbot-space-2);
}

/* Every text line is as tall as the chip, so the chip and the text share one line. */
.marketplace-try-card .skill-preview-request {
  width: min(100%, 560px);
  line-height: var(--johnbot-space-6);
}

.marketplace-try-card .skill-preview-chip {
  margin-inline-end: var(--johnbot-space-0-5);
  vertical-align: top;
}

.marketplace-try-card .reference-chip-icon > :is(img, svg) {
  width: 100%;
  height: 100%;
}

/* The skill's SKILL.md, as the agent reads it. */
.marketplace-doc {
  min-width: 0;
  padding: var(--johnbot-space-4) var(--johnbot-space-6);
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-card);
  font-size: var(--johnbot-text-sm);
  overflow-wrap: anywhere;
}

.marketplace-doc > :first-child {
  margin-top: 0;
}

.marketplace-doc > :last-child {
  margin-bottom: 0;
}

/* ---------------------------------------------------------------- no results */

.marketplace-empty {
  display: grid;
  justify-items: center;
  gap: var(--johnbot-space-2);
  padding: var(--johnbot-space-8) var(--johnbot-space-6);
  border: 1px dashed var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-card);
  text-align: center;
}

.marketplace-empty > p {
  max-width: 440px;
  margin: 0;
}

.marketplace-empty > .ui-button {
  margin-top: var(--johnbot-space-2);
}

.marketplace-empty-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--johnbot-space-2);
}

/* ---------------------------------------------------------------- narrow */

/* A narrow window puts the kinds in a row above the list. The connected apps are in the list. */
@media (max-width: 720px) {
  .skills-marketplace {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto auto minmax(0, 1fr);
  }

  .marketplace-nav {
    grid-row: 2;
    overflow-x: auto;
    padding: var(--johnbot-space-2) var(--johnbot-space-3);
    border-right: 0;
    border-bottom: 1px solid var(--johnbot-border);
  }

  .marketplace-nav-title,
  .marketplace-nav-group {
    display: none;
  }

  .marketplace-nav-list {
    grid-auto-columns: max-content;
    grid-auto-flow: column;
  }

  .skills-marketplace-body {
    grid-row: 3;
    grid-column: 1;
  }
}

@media (max-width: 860px) {
  .skills-marketplace {
    --marketplace-inset: var(--johnbot-space-4);
  }

  .marketplace-page {
    grid-template-columns: minmax(0, 1fr);
  }

  .marketplace-side {
    position: static;
    padding: var(--johnbot-space-4) 0 0;
    border-top: 1px solid var(--johnbot-border);
    border-left: 0;
  }

  .marketplace-head {
    flex-wrap: wrap;
  }
}

/* Last, because it is the most specific icon rule: every button icon in the window is 16px. */
.skills-marketplace .ui-button > svg,
.marketplace-search > svg {
  width: 16px;
  height: 16px;
}

/* After the icon size rule, so that the warning color wins. */
.marketplace-app-action[data-status="attention"] > svg {
  color: var(--johnbot-warning-text);
}

/* === from: @johnbot/ui/features/settings/logo-color-picker.css === */
/* The logo color swatches, in the same shape as the agent avatar color grid. */
.logo-color-grid {
  display: grid;
  grid-template-columns: repeat(5, 32px);
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
  gap: 4px;
}

.logo-color-choice {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  padding: 0;
  border: 1px solid transparent;
  border-radius: var(--johnbot-radius-md);
  background: transparent;
  transition-property: scale, background-color, box-shadow;
  transition-duration: var(--johnbot-duration-normal), var(--johnbot-duration-hover), var(--johnbot-duration-hover);
  transition-timing-function: ease-out;
}

.logo-color-choice:hover {
  background: var(--johnbot-hover);
}

.logo-color-choice:active {
  scale: 0.96;
}

.logo-color-choice-selected {
  background: var(--johnbot-border);
  box-shadow:
    inset 0 0 0 1px var(--johnbot-text-muted),
    0 1px 3px var(--johnbot-shadow-popover-ambient);
}

.logo-color-swatch {
  display: block;
  width: 18px;
  height: 18px;
  border-radius: var(--johnbot-radius-pill);
  box-shadow: inset 0 0 0 1px var(--johnbot-border-strong);
}

/* === from: @johnbot/ui/features/settings/sound-theme-picker.css === */
/* Sound feedback off, or on in one sound theme. Each card shows a moving dither tile. */
.sound-theme-picker {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(104px, 1fr));
  width: 100%;
  min-width: 0;
  gap: var(--johnbot-space-2);
}

.sound-theme-option {
  display: flex;
  min-width: 0;
}

.sound-theme-card {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  padding: var(--johnbot-space-1);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-control);
  box-shadow: inset 0 0 0 1px var(--johnbot-border);
  text-align: left;
  cursor: pointer;
  transition-property: scale, background-color, box-shadow;
  transition-duration: var(--johnbot-duration-normal), var(--johnbot-duration-hover), var(--johnbot-duration-normal);
  transition-timing-function: var(--johnbot-ease-out);
}

.sound-theme-card:hover {
  background: var(--johnbot-bg-control-hover);
}

.sound-theme-card:active {
  scale: 0.96;
}

.sound-theme-card[data-checked] {
  box-shadow:
    inset 0 0 0 1.5px var(--johnbot-text-primary),
    0 1px 3px var(--johnbot-shadow-popover-ambient);
}

.sound-theme-card[data-popped][data-checked] {
  animation: sound-theme-pop var(--johnbot-duration-toast-enter) var(--johnbot-ease-out);
}

.sound-theme-option:has(:focus-visible) .sound-theme-card {
  box-shadow: var(--johnbot-focus-ring);
}

/* The shader reads the ink from `color` and the back from `background-color`. Before it starts, or
   without WebGL, the same colors show as a dot screen. */
.sound-theme-dither {
  --sound-theme-ink: var(--johnbot-sound-off-ink);
  --sound-theme-back: var(--johnbot-sound-off-back);
  position: relative;
  height: 56px;
  overflow: hidden;
  clip-path: inset(0 round var(--johnbot-radius-md));
  border-radius: var(--johnbot-radius-md);
  color: var(--sound-theme-ink);
  background-color: var(--sound-theme-back);
  background-image:
    radial-gradient(var(--sound-theme-ink) 1px, transparent 1.5px),
    linear-gradient(135deg, transparent, var(--sound-theme-ink));
  background-size:
    4px 4px,
    100% 100%;
  opacity: 0.72;
  filter: saturate(0.7);
  transition-property: opacity, filter;
  transition-duration: var(--johnbot-duration-overlay);
  transition-timing-function: var(--johnbot-ease-out);
}

.sound-theme-dither canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.sound-theme-card:hover .sound-theme-dither,
.sound-theme-card[data-checked] .sound-theme-dither {
  opacity: 1;
  filter: none;
}

.sound-theme-dither[data-choice="default"] {
  --sound-theme-ink: var(--johnbot-sound-warm-ink);
  --sound-theme-back: var(--johnbot-sound-warm-back);
}

.sound-theme-dither[data-choice="mech"] {
  --sound-theme-ink: var(--johnbot-sound-mech-ink);
  --sound-theme-back: var(--johnbot-sound-mech-back);
}

.sound-theme-dither[data-choice="bubble"] {
  --sound-theme-ink: var(--johnbot-sound-bubble-ink);
  --sound-theme-back: var(--johnbot-sound-bubble-back);
}

.sound-theme-dither[data-choice="press"] {
  --sound-theme-ink: var(--johnbot-sound-press-ink);
  --sound-theme-back: var(--johnbot-sound-press-back);
}

.sound-theme-text {
  display: grid;
  min-width: 0;
  padding: var(--johnbot-space-1-5) var(--johnbot-space-1) var(--johnbot-space-0-5);
}

.sound-theme-name {
  overflow: hidden;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-md);
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: inherit;
}

.sound-theme-hint {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

@keyframes sound-theme-pop {
  0% {
    scale: 1;
  }

  35% {
    scale: 1.06;
    rotate: -1.5deg;
  }

  70% {
    scale: 0.98;
    rotate: 0.8deg;
  }

  100% {
    scale: 1;
    rotate: 0deg;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sound-theme-card[data-popped][data-checked] {
    animation: none;
  }

  .sound-theme-card:active {
    scale: 1;
  }
}

/* === from: @johnbot/ui/features/settings/mcp-connect-dialog.css === */
/*
 * The content of the plugin connect dialogs. The frame is the shared connect dialog,
 * `WizardDialog` in `integration-layout.css`: the two logos, the title, and the buttons.
 */

/* One card of facts, its rows divided rather than spaced: a connection is one thing to read. */
.mcp-connect-card {
  display: flex;
  flex-direction: column;
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-grouped);
}

.mcp-connect-row {
  position: relative;
  margin: 0;
  padding: var(--johnbot-space-3);
}

.mcp-connect-row + .mcp-connect-row {
  border-top: 1px solid var(--johnbot-border-grouped);
}

/* The steps that turn on a server another app runs. The heading leaves room for the setup link
   that sits in the row's corner. */
.mcp-local-heading {
  margin: 0;
  padding-right: var(--johnbot-space-6);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-sm);
}

.mcp-local-steps {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-2);
  margin: var(--johnbot-space-2) 0 0;
  padding-left: var(--johnbot-space-4);
  list-style: decimal;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.mcp-local-steps > li::marker {
  color: var(--johnbot-text-muted);
}

.mcp-local-address {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--johnbot-space-3);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.mcp-local-address > code {
  overflow-wrap: anywhere;
  color: var(--johnbot-text-primary);
  font-family: var(--johnbot-font-mono);
}

/* On the label's line, at the far end of it: the way out to the key page is a quiet aside, and it
   is the size of the other links in the marketplace rather than the size of the field. */
.mcp-connect-docs {
  position: absolute;
  top: var(--johnbot-space-3);
  right: var(--johnbot-space-3);
  gap: var(--johnbot-space-1-5);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

/* The mark that says the link leaves the app. It reads beside the words rather than over them,
   so it is the size of every other external-link mark in the marketplace. */
.mcp-connect-docs > svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: 0 0 auto;
  stroke-width: var(--johnbot-icon-stroke);
}

.mcp-connect-privacy {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.mcp-connect-privacy svg {
  flex: none;
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  color: var(--johnbot-text-muted);
}

/* A joined server's sign-in page, drawn from the host's browser. The page keeps the shape of the host's frame. */
.mcp-sign-in-page {
  position: relative;
  width: 100%;
  overflow: hidden;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-surface);
}

.mcp-sign-in-page-note {
  min-width: 0;
  margin: 0;
}

/* A relayed sign-in: the page is in the user's own browser, so the dialog holds only the address field. */
.mcp-sign-in-relay-open {
  margin-top: var(--johnbot-space-4);
}

.mcp-sign-in-relay-form {
  margin-top: var(--johnbot-space-4);
}

/* In the connect dialog, the body's gap spaces them. The open button keeps the width of its words. */
.integration-wizard-body > :is(.mcp-sign-in-relay-open, .mcp-sign-in-relay-form) {
  margin-top: 0;
}

.integration-wizard-body > .mcp-sign-in-relay-open {
  justify-self: start;
}

.mcp-sign-in-relay-row {
  display: flex;
  gap: var(--johnbot-space-2);
}

.mcp-sign-in-relay-row > .ui-input {
  flex: 1;
  min-width: 0;
}

/* === from: ./features/provider-updates/provider-updates.css === */
/* The provider mark in the update notification's icon slot. The sizes match the slot the Toaster
   reserves for a status glyph, and the fill is the brand colour the provider row already uses, so
   the notification and the row that offers the same update read as one thing. */
.provider-update-toast-logo {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  overflow: visible;
  fill: var(--johnbot-provider-current);
}

/* The action sits beside the words it acts on, centred on the title and the version line, rather than
   in a row of its own under them. The words stop at the button while it is there; a state with no
   button gives them the full width, so the running update's bar reaches the right edge. */
.provider-update-toast[data-sonner-toast][data-styled="true"] [data-action] {
  grid-row: 1;
  align-self: center;
}

.provider-update-toast[data-sonner-toast][data-styled="true"]:has(.provider-update-toast-action:not([data-idle="true"]))
  [data-content] {
  grid-column: 2;
}

/* In the first row the button is under the close control, which floats over the top right corner,
   so it keeps the same room clear that the words keep. */
.ui-toaster.ui-toaster-closeable .provider-update-toast[data-sonner-toast][data-styled="true"] [data-action],
.ui-toaster .provider-update-toast[data-sonner-toast][data-styled="true"]:has([data-close-button]) [data-action] {
  margin-right: var(--johnbot-space-6);
}

/* A state with nothing to offer marks its label instead of losing it, and the button goes out of the
   layout. Sonner renders its action button for as long as an action exists on the toast, and taking
   the action away means replacing the notification, which is the one thing this flow will not do.
   Hiding the button also keeps a control with no accessible name out of the tree. */
.ui-toaster [data-sonner-toast] [data-action]:has(.provider-update-toast-action[data-idle="true"]) {
  display: none;
}

/* The running update puts its bar under the version line. Sonner builds the toast's children itself,
   so the bar cannot be one of them - it goes in the description, as a line of its own. */
.provider-update-toast[data-sonner-toast][data-styled="true"] [data-description]:has(.provider-update-toast-progress) {
  display: flex;
  flex-direction: column;
}

/* A block, so the ellipsis applies in a state with no bar too, where the description is not a flex
   column. */
.provider-update-toast-line {
  display: block;
  min-width: 0;
  overflow: hidden;
  font-variant-numeric: tabular-nums;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* A failure is a sentence, not a version. It wraps, also inside a long path or address, and stops
   after three lines until the user opens it. */
.provider-update-toast-line[data-failed="true"] {
  display: -webkit-box;
  overflow-wrap: anywhere;
  text-overflow: clip;
  white-space: normal;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  line-clamp: 3;
}

.provider-update-toast-line[data-failed="true"][data-expanded="true"] {
  display: block;
  -webkit-line-clamp: none;
  line-clamp: none;
}

/* The control that opens the rest of the failure sits under it, at the start of the line, in the
   description's colour. */
.provider-update-toast .provider-update-toast-details {
  margin-top: var(--johnbot-space-1);
  color: inherit;
  font-size: inherit;
  text-decoration: underline;
}

/* The bar and the percentage, on one line under the version. */
.provider-update-toast-progress {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-3);
  margin-top: var(--johnbot-space-2);
}

/* The content column keeps its words clear of the close control, which floats over the top right
   corner. The progress row is below that corner, so it takes the room back and ends at the card's
   right padding. */
.ui-toaster.ui-toaster-closeable .provider-update-toast .provider-update-toast-progress,
.ui-toaster .provider-update-toast:has([data-close-button]) .provider-update-toast-progress {
  margin-right: calc(-1 * var(--johnbot-space-6));
}

.provider-update-toast-bar {
  flex: 1;
  min-width: 0;
}

/* The bar carries the provider's colour, the same one the mark above it carries, so the running
   update is legible as this provider's at a glance rather than as generic progress. */
.provider-update-toast-bar[data-provider] .ui-progress-fill {
  background: var(--johnbot-provider-current);
}

/* A short movement leaves most of each 400 ms display interval still and readable.
   Move the whole value together; staggered digits make fast changes hard to read. */
.provider-update-toast-percent {
  --digit-dur: var(--johnbot-duration-fast);
  --digit-distance: var(--johnbot-space-1);
  --digit-blur: 0px;
  --digit-ease: ease-out;
  display: inline-flex;
  justify-content: flex-end;
  width: 4ch;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  font-variant-numeric: tabular-nums;
}

/* === from: @johnbot/ui/features/custom-providers/custom-providers.css === */
/* The dialog that describes an OpenAI-compatible endpoint. It sits on the same modal geometry as
 * join-server-dialog.css, but scrolls instead of paging: the repeatable model and header lists have
 * no fixed height. */

.custom-provider-dialog {
  display: flex;
  width: min(460px, 100%);
  max-height: calc(100dvh - 48px);
  flex-direction: column;
  overflow: hidden;
  outline: 0;
  /* The same radius the settings modal uses, so the two surfaces read as one family. It also nests
   * the close button: an 8px glyph target held 8px in from the corner asks for about 16px around it,
   * which 20px overshot. */
  border-radius: var(--johnbot-radius-card);
  background: var(--johnbot-bg-sidebar);
  color: var(--johnbot-text-primary);
}

.custom-provider-header {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: var(--johnbot-space-3);
  border-bottom: 1px solid var(--johnbot-border);
  padding: var(--johnbot-space-4);
}

.custom-provider-mark {
  display: grid;
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  place-items: center;
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-accent-soft);
  color: var(--johnbot-accent-text);
}

.custom-provider-title {
  min-width: 0;
  flex: 1;
}

/* The close button is a 32px target around a 16px glyph, so it overhangs its own glyph by 8px on
 * every side. It is held at the top of the header and pulled out by that 8px, so the glyph keeps the
 * header's own 16px inset from the top and from the inline end and reads as square in the corner.
 * Centring it instead would leave it 26px down while staying 16px in, because the title is two lines
 * tall and the header centres its children. */
.custom-provider-close {
  flex: 0 0 auto;
  align-self: flex-start;
  margin-block-start: calc(var(--johnbot-space-2) * -1);
  margin-inline-end: calc(var(--johnbot-space-2) * -1);
  color: var(--johnbot-text-muted);
}

/* The form is the layout box; the fields inside it are what scrolls, so the footer stays put and
 * outside the scroll fade. */
.custom-provider-body {
  display: flex;
  min-height: 0;
  flex-direction: column;
}

.custom-provider-form {
  display: flex;
  min-height: 0;
  flex-direction: column;
  gap: var(--johnbot-space-4);
  overflow-y: auto;
  padding: var(--johnbot-space-4);
}

/* The saved endpoints scroll on the same terms the form's fields do, so both dialogs keep their
 * footer outside the fade. */
.custom-provider-list {
  display: flex;
  min-height: 0;
  flex-direction: column;
  gap: var(--johnbot-space-4);
  overflow-y: auto;
  padding: var(--johnbot-space-4);
}

.custom-provider-list-empty {
  padding: var(--johnbot-space-4) 0;
  text-align: center;
}

.custom-provider-rows {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-2);
}

.custom-provider-rows-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--johnbot-space-3);
}

.custom-provider-row {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-1);
}

/* Two equal columns and a trash button: the model ID and its display name carry the same weight,
 * and neither should reflow when the other holds a long value. */
.custom-provider-row-inputs {
  display: grid;
  align-items: center;
  gap: var(--johnbot-space-2);
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) auto;
}

.custom-provider-row-inputs.custom-provider-row-single {
  grid-template-columns: minmax(0, 1fr) auto;
}

/* A token count is short, so the context window column is narrower than the ID and the name. */
.custom-provider-row-inputs.custom-provider-row-triple {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) minmax(0, 0.6fr) auto;
}

.custom-provider-rows-error,
.custom-provider-row-error,
.custom-provider-submit-error {
  display: block;
}

.custom-provider-actions {
  display: flex;
  flex-shrink: 0;
  flex-direction: column;
  align-items: center;
  gap: var(--johnbot-space-2);
  border-top: 1px solid var(--johnbot-border);
  padding: var(--johnbot-space-4);
}

.custom-provider-actions .ui-button-variant-default {
  width: 100%;
}

/* Same reason as the picker heading: only the direct children here are the label-and-icon buttons.
 * The nested remove buttons are icon-only and already sized by .ui-icon-button. */
.custom-provider-rows > .ui-button svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  stroke-width: var(--johnbot-icon-stroke);
}

/* The label sits first and a find control follows it; a section error keeps the far end. */
.custom-provider-rows-heading > .custom-provider-discover {
  margin-inline-start: auto;
}

.custom-provider-rows-heading > .custom-provider-discover + .custom-provider-rows-error {
  display: none;
}

.custom-provider-rows-heading > .custom-provider-discover svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  stroke-width: var(--johnbot-icon-stroke);
}

.custom-provider-discovery-status {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.custom-provider-discovered {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: var(--johnbot-space-1);
  list-style: none;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-md);
}

.custom-provider-discovered-row {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  padding: var(--johnbot-space-1) var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-sm);
  cursor: pointer;
}

.custom-provider-discovered-row:hover {
  background: var(--johnbot-bg-control-hover);
}

.custom-provider-discovered-id {
  min-width: 0;
  overflow: hidden;
  font-family: var(--johnbot-font-mono);
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The preset chooser: two short groups of full-width rows. */
.custom-provider-preset-group {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-2);
}

.custom-provider-presets {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-1);
  margin: 0;
  padding: 0;
  list-style: none;
}

.custom-provider-preset.ui-button {
  display: flex;
  width: 100%;
  height: auto;
  align-items: center;
  justify-content: flex-start;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
  text-align: start;
  white-space: normal;
}

.custom-provider-preset-icon {
  display: grid;
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  place-items: center;
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-control-hover);
  color: var(--johnbot-text-secondary);
}

.custom-provider-preset > .custom-provider-preset-icon svg,
.custom-provider-preset-chevron {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  stroke-width: var(--johnbot-icon-stroke);
}

.custom-provider-preset-copy {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  gap: 2px;
}

.custom-provider-preset-title {
  color: var(--johnbot-text-primary);
  font-weight: var(--johnbot-weight-medium);
}

.custom-provider-preset-description {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-regular);
}

.custom-provider-preset-chevron {
  flex-shrink: 0;
  color: var(--johnbot-text-muted);
}

/* The custom ACP agent form. */
.custom-acp-presets {
  display: flex;
  flex-wrap: wrap;
  gap: var(--johnbot-space-2);
}

.custom-acp-code {
  overflow-wrap: anywhere;
}

.custom-acp-code input,
input.custom-acp-code {
  font-family: var(--johnbot-font-mono);
}

/* Local model servers and ACP agents that the host found, below the provider list. */
.detected-providers {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-2);
  margin-top: var(--johnbot-space-4);
}

.detected-providers-heading {
  display: flex;
  min-height: 24px;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.detected-providers-scanning {
  display: inline-flex;
  align-items: center;
  gap: var(--johnbot-space-1-5);
}

.ui-button.detected-providers-scan {
  gap: var(--johnbot-space-1-5);
  margin-inline-start: auto;
  margin-inline-end: calc(var(--johnbot-space-2) * -1);
}

.detected-providers-heading > .detected-providers-scan svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

.detected-providers-icon {
  color: var(--johnbot-text-secondary);
}

.detected-providers .detected-providers-icon > svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  stroke-width: var(--johnbot-icon-stroke);
}

.ui-button.detected-providers-show-hidden {
  align-self: flex-start;
  margin-inline-start: calc(var(--johnbot-space-2) * -1);
}

/* Under the last error it belongs to, at the start of the line like that text. */
.ui-button.custom-agents-copy-diagnostics {
  justify-self: start;
  margin-inline-start: calc(var(--johnbot-space-2) * -1);
}

/* The lists in the detection settings, below the switch card. */
.detected-providers-settings {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-4);
  margin-top: var(--johnbot-space-3);
}

/* The ACP registry search and agent-ID forms. The field takes its own line; the actions sit under it
 * and wrap apart, with the same gap the settings section keeps between its children. */
.acp-registry-form {
  display: flex;
  flex-wrap: wrap;
  gap: var(--johnbot-space-2);
}

.acp-registry-form > .ui-field {
  flex-basis: 100%;
}

/* A registry entry in a narrow column. Translated action labels can be wider than the row, so the
 * actions move under the entry and then wrap among themselves. The entry keeps a readable width and
 * no action is clipped. */
.acp-registry-entry.ui-item {
  flex-wrap: wrap;
}

.acp-registry-entry .ui-item-content {
  flex-basis: 180px;
}

.acp-registry-entry .ui-item-actions {
  min-width: 0;
  flex-shrink: 1;
  flex-wrap: wrap;
  margin-inline-start: auto;
}

/* === from: @johnbot/ui/features/browser/browser-profiles.css === */
/* The browser profiles section of the server settings: the list, then the new profile form. */
.browser-profiles-panel {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-3);
}

/* The name field row of the new profile form and of an inline rename. */
.browser-profiles-row {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.browser-profiles-name {
  min-width: 0;
  flex: 1;
}

/* "New profile" closes the list of the agent settings select, under a line. */
.ui-select-item.browser-profile-select-new {
  margin-top: calc(var(--johnbot-space-1) * 2 + 1px);
}

.ui-select-item.browser-profile-select-new::before {
  position: absolute;
  top: calc(-1 * var(--johnbot-space-1) - 1px);
  right: calc(-1 * var(--johnbot-space-1));
  left: calc(-1 * var(--johnbot-space-1));
  border-top: 1px solid var(--johnbot-border);
  content: "";
}

.ui-select-item.browser-profile-select-new[hidden] {
  display: none;
}

.browser-profile-select-option .ui-select-item-label,
.browser-profile-select-value {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-2);
}

/* The column of the profile colors and the "New profile" plus. */
.browser-profile-select-mark {
  display: inline-flex;
  width: var(--johnbot-icon-sm);
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
}

.browser-profile-select-mark svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

/* In the settings the dot is the button that opens the colors. */
/* The shared profile has no color menu. Its dot takes the place of the menu button. */
.browser-profile-shared-mark {
  display: inline-flex;
  width: var(--johnbot-control-md);
  height: var(--johnbot-control-md);
  align-items: center;
  justify-content: center;
}

.browser-profile-color-trigger .browser-profile-dot {
  width: 12px;
  height: 12px;
}

.browser-profile-color-option {
  gap: var(--johnbot-space-2);
}

.browser-profile-color-option > span:not(.browser-profile-dot) {
  flex: 1 1 auto;
}

/* The name field takes the place of "New profile". Its text lines up with the option labels. */
.browser-profile-select-form {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-1);
}

.browser-profile-select-form .browser-profiles-name {
  font-size: var(--johnbot-text-sm);
}

.browser-profile-select-form .ui-text {
  padding-inline: var(--johnbot-space-2);
}

/* === from: @johnbot/ui/features/vault/vault.css === */
/* The Vault page of the server settings. */

.vault-panel {
  display: grid;
  gap: var(--johnbot-space-6);
  min-width: 0;
}

.vault-truncate,
.ui-item-content > .vault-truncate {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.vault-icon {
  display: inline-grid;
  flex: none;
  place-items: center;
}

.vault-icon svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
}

/* Item logos. A site gets a letter tile: no icon is fetched from it. */
.vault-letter {
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-semibold);
}

/* Card brands sit on light paper, as their artwork expects. */
.vault-card-logo {
  display: inline-grid;
  flex: none;
  width: var(--integration-tile, 36px);
  height: calc(var(--integration-tile, 36px) * 2 / 3);
  place-items: center;
  border: 1px solid var(--johnbot-paper-border);
  border-radius: var(--johnbot-radius-xs);
  background: var(--johnbot-paper);
  color: var(--johnbot-paper-text);
}

.vault-card-logo > svg {
  width: 70%;
  height: 70%;
}

.vault-avatar {
  display: inline-grid;
  flex: none;
  width: var(--integration-tile, 36px);
  height: var(--integration-tile, 36px);
  place-items: center;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-accent-soft);
  color: var(--johnbot-accent-hover);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-semibold);
}

.vault-avatar > svg {
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
}

.vault-toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: var(--johnbot-space-3);
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--johnbot-space-1);
}

.vault-count {
  margin-inline-start: var(--johnbot-space-1-5);
  color: var(--johnbot-text-muted);
  font-variant-numeric: tabular-nums;
}

.vault-fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--johnbot-space-3) var(--johnbot-space-4);
}

.vault-wide {
  grid-column: 1 / -1;
}

.vault-fill-sites {
  min-width: 0;
  margin: 0;
  border: 0;
  padding: 0;
}

.vault-fill-sites > .ui-label {
  margin-block-end: var(--johnbot-space-1-5);
  padding: 0;
}

.vault-sites {
  display: grid;
  margin: 0;
  padding: 0;
  list-style: none;
}

.vault-site {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-2);
  min-width: 0;
}

.vault-secret {
  position: relative;
  display: flex;
  align-items: center;
}

.vault-secret .ui-input {
  flex: 1;
  padding-inline-end: var(--johnbot-space-8);
}

.vault-secret .ui-icon-button {
  position: absolute;
  inset-inline-end: var(--johnbot-space-1);
}

/* The search matches the tab bar beside it: same height, fill and text size, no border until focus. */
.vault-toolbar .server-settings-search {
  align-self: stretch;
}

.vault-toolbar .server-settings-search .ui-input {
  height: 100%;
  border-color: var(--johnbot-transparent);
  font-size: var(--johnbot-text-md);
}

.vault-toolbar .server-settings-search .ui-input:focus-visible {
  border-color: var(--johnbot-border-focus);
}

.vault-dialog.ui-confirm-dialog {
  width: min(520px, 100%);
}

.vault-dialog-form {
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.vault-dialog-header {
  display: flex;
  gap: var(--johnbot-space-3);
  align-items: center;
  padding: var(--johnbot-space-4) var(--johnbot-space-4) 0 var(--johnbot-space-6);
}

.vault-dialog-title {
  flex: 1;
  min-width: 0;
  margin: 0;
  overflow: hidden;
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.vault-dialog-body {
  display: grid;
  gap: var(--johnbot-space-3);
  min-height: 0;
  overflow-y: auto;
  padding: var(--johnbot-space-4) var(--johnbot-space-6) var(--johnbot-space-6);
}

/* === from: @johnbot/ui/features/agents/agent-template.css === */
/* The publish dialog and the install dialog of an agent template. Both are one centred card: the
 * agent's identity on top, its content below, and the actions in a footer on the right. */

.agent-template-dialog {
  position: relative;
  display: flex;
  width: min(420px, 100%);
  max-height: calc(100dvh - 48px);
  flex-direction: column;
  overflow: hidden;
  outline: 0;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-card);
  background: var(--johnbot-bg-sidebar);
  color: var(--johnbot-text-primary);
}

.agent-template-status {
  position: absolute;
  z-index: 1;
  inset-block-start: var(--johnbot-space-3);
  inset-inline-start: var(--johnbot-space-3);
}

.agent-template-corner-actions {
  position: absolute;
  z-index: 1;
  display: flex;
  gap: var(--johnbot-space-1);
  inset-block-start: var(--johnbot-space-2);
  inset-inline-end: var(--johnbot-space-2);
  color: var(--johnbot-text-muted);
}

.agent-template-body {
  display: flex;
  min-height: 0;
  flex-direction: column;
  gap: var(--johnbot-space-4);
  padding: var(--johnbot-space-6) var(--johnbot-space-4) var(--johnbot-space-4);
}

.agent-template-scroll {
  overflow-y: auto;
}

.agent-template-identity {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--johnbot-space-1);
  text-align: center;
}

.agent-template-avatar {
  width: 72px;
  height: 72px;
  margin-block-end: var(--johnbot-space-3);
}

.agent-template-name {
  overflow-wrap: anywhere;
}

.agent-template-description {
  display: -webkit-box;
  margin-block-start: var(--johnbot-space-1);
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4;
  line-clamp: 4;
}

.agent-template-rows {
  display: grid;
  overflow: hidden;
  border-radius: var(--johnbot-radius-grouped);
}

.agent-template-row {
  display: grid;
  width: 100%;
  height: auto;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--johnbot-space-3);
  border-radius: 0;
  padding: var(--johnbot-space-3) var(--johnbot-space-4);
  text-align: start;
  color: var(--johnbot-text-muted);
}

.agent-template-row + .agent-template-row {
  border-top: 1px solid var(--johnbot-border-grouped);
}

.agent-template-row-copy {
  display: grid;
  min-width: 0;
  gap: var(--johnbot-space-0-5);
}

.agent-template-row-title {
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
}

.agent-template-row-detail {
  overflow: hidden;
  color: var(--johnbot-text-grouped-secondary);
  font-size: var(--johnbot-text-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-template-actions {
  display: flex;
  flex-shrink: 0;
  justify-content: flex-end;
  gap: var(--johnbot-space-2);
  border-top: 1px solid var(--johnbot-border);
  padding: var(--johnbot-space-3) var(--johnbot-space-4);
}

.agent-template-copy {
  margin-inline-end: auto;
}

.agent-template-detail-header {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  margin-block-start: calc(var(--johnbot-space-2) * -1);
}

.agent-template-detail {
  display: flex;
  min-height: 0;
  flex-direction: column;
  gap: var(--johnbot-space-4);
  overflow-y: auto;
}

.agent-template-section {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-1);
}

/* The instructions as Markdown, at the body size of the dialog. Headings stay below the agent's name. */
.agent-template-prose {
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
  overflow-wrap: anywhere;
}

.agent-template-prose .message-markdown-heading[data-level] {
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
  line-height: var(--johnbot-leading-lg);
}

.agent-template-prose .message-markdown-heading:not([data-level="1"], [data-level="2"]) {
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
}

.agent-template-list {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-3);
  margin: 0;
  padding: 0;
  list-style: none;
}

.agent-template-list > li {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-0-5);
}

.agent-template-skill-toggle {
  justify-content: flex-start;
  align-self: flex-start;
  gap: var(--johnbot-space-1);
  margin-inline-start: calc(var(--johnbot-space-2) * -1);
}

.agent-template-skill-text {
  max-height: 240px;
  margin: var(--johnbot-space-1) 0 0;
  overflow: auto;
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-control);
  padding: var(--johnbot-space-3);
  font-family: var(--johnbot-font-mono);
  font-size: var(--johnbot-text-sm);
  white-space: pre-wrap;
}

/* === from: @johnbot/ui/features/agents/agent-delete-undo-toast.css === */
/* Sonner gives an unstyled toast no width, so the host takes the toaster width. */
.agent-delete-undo-toast-host {
  width: var(--width);
}

/* The same raised surface, border, and shadow as the shared toast. The bottom padding keeps the bar
   clear of the text. */
.agent-delete-undo-toast {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--johnbot-space-3);
  overflow: hidden;
  padding: var(--johnbot-space-3);
  padding-bottom: calc(var(--johnbot-space-3) + var(--johnbot-space-1));
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-surface-raised);
  box-shadow:
    0 0 0 1px var(--johnbot-border),
    var(--johnbot-shadow-raised);
  color: var(--johnbot-text-primary);
  font-family: var(--johnbot-font-sans);
}

/* Without a fixed track, the grid row grows to the drawing's width, and the drawing's 128% height
   then resolves against that row. The drawing becomes taller than wide and the body sits low. */
.agent-delete-undo-toast-avatar {
  grid-template: minmax(0, 1fr) / minmax(0, 1fr);
  width: 32px;
  height: 32px;
}

.agent-delete-undo-toast-text {
  display: flex;
  min-width: 0;
  flex-direction: column;
}

.agent-delete-undo-toast-title {
  overflow: hidden;
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-md);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-delete-undo-toast-detail {
  overflow: hidden;
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The bar sits on the bottom edge, inside the rounded corners. */
.agent-delete-undo-toast-bar {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
}

.agent-delete-undo-toast-bar .ui-progress-track {
  border-radius: 0;
  background: transparent;
}

.agent-delete-undo-toast-bar .ui-progress-fill {
  background: var(--johnbot-accent);
  transition-duration: var(--johnbot-duration-fast);
  transition-timing-function: linear;
}

/* === from: @johnbot/ui/features/updates/whats-new.css === */
/* The "What's new" dialog after an app update. One centred card: the logo and version on top, the
 * notes in a scroll area, and the actions in a footer. The groups use the colours of the
 * changelog page on johnbot.run, so a reader sees the same notes in the same way. */

.whats-new-dialog {
  position: relative;
  display: flex;
  width: min(480px, 100%);
  max-height: min(640px, calc(100dvh - 2 * var(--johnbot-space-6)));
  flex-direction: column;
  overflow: hidden;
  outline: 0;
  border-radius: var(--johnbot-radius-xl);
  background: var(--johnbot-bg-sidebar);
  color: var(--johnbot-text-primary);
}

.whats-new-close {
  position: absolute;
  z-index: 1;
  inset-block-start: var(--johnbot-space-3);
  inset-inline-end: var(--johnbot-space-3);
  color: var(--johnbot-text-muted);
}

.whats-new-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--johnbot-space-1);
  padding: var(--johnbot-space-8) var(--johnbot-space-6) var(--johnbot-space-4);
  text-align: center;
}

.whats-new-logo {
  --app-logo-background: var(--johnbot-surface-light);
  width: 56px;
  height: 56px;
  margin-block-end: var(--johnbot-space-3);
  border-radius: var(--johnbot-radius-logo);
}

.whats-new-title {
  margin: 0;
  font-size: var(--johnbot-text-2xl);
  font-weight: var(--johnbot-weight-bold);
  line-height: var(--johnbot-leading-2xl);
}

.whats-new-body {
  display: flex;
  min-height: 0;
  flex: 1 1 auto;
  flex-direction: column;
  gap: var(--johnbot-space-6);
  overflow-y: auto;
  padding: var(--johnbot-space-2) var(--johnbot-space-6) var(--johnbot-space-6);
  border-block-start: 1px solid transparent;
}

.whats-new-body.scroll-fade-top {
  border-block-start-color: var(--johnbot-border);
}

.whats-new-body.scroll-fade-bottom {
  mask-image: linear-gradient(to bottom, var(--johnbot-text-primary) calc(100% - 32px), transparent);
}

.whats-new-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--johnbot-space-2);
  padding-block: var(--johnbot-space-6);
  text-align: center;
}

.whats-new-state .ui-button {
  margin-block-start: var(--johnbot-space-2);
}

.whats-new-state-icon {
  width: 24px;
  height: 24px;
  color: var(--johnbot-warning-text);
}

.whats-new-notice {
  padding: var(--johnbot-space-3) var(--johnbot-space-4) var(--johnbot-space-4);
  border-radius: var(--johnbot-radius-card);
  background-image: linear-gradient(
    180deg,
    var(--johnbot-warning-soft),
    color-mix(in srgb, var(--johnbot-warning) 3%, transparent)
  );
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--johnbot-warning) 26%, transparent);
  --whats-new-tone: var(--johnbot-warning-text);
}

.whats-new-notice-title {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  margin: 0 0 var(--johnbot-space-2);
  color: var(--johnbot-warning-text);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-semibold);
}

.whats-new-notice-title svg {
  width: 16px;
  height: 16px;
  flex: 0 0 auto;
}

.whats-new-group {
  --whats-new-tone: var(--johnbot-text-muted);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--johnbot-space-3);
}

.whats-new-group[data-type="added"] {
  --whats-new-tone: var(--johnbot-logo-production);
}

.whats-new-group[data-type="changed"] {
  --whats-new-tone: var(--johnbot-accent-text);
}

.whats-new-group[data-type="fixed"] {
  --whats-new-tone: var(--johnbot-success-text);
}

.whats-new-group-title {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  margin: 0;
  color: var(--whats-new-tone);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-semibold);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.whats-new-group-dot {
  width: 6px;
  height: 6px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--whats-new-tone);
  box-shadow: 0 0 10px color-mix(in srgb, var(--whats-new-tone) 70%, transparent);
}

.whats-new-group-count {
  padding: 0 var(--johnbot-space-1-5);
  border-radius: var(--johnbot-radius-pill);
  background: color-mix(in srgb, var(--whats-new-tone) 12%, transparent);
  font-family: var(--johnbot-font-mono);
  font-weight: var(--johnbot-weight-medium);
  letter-spacing: 0;
}

.whats-new-list {
  display: grid;
  width: 100%;
  gap: var(--johnbot-space-3);
  margin: 0;
  padding: 0;
  list-style: none;
}

/* A hanging mark in the group's colour, so a long item wraps under its own text. */
.whats-new-item {
  position: relative;
  padding-inline-start: var(--johnbot-space-6);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-md);
  line-height: var(--johnbot-leading-md);
  text-wrap: pretty;
}

.whats-new-item-headline {
  display: block;
  color: var(--johnbot-text-primary);
  font-weight: var(--johnbot-weight-medium);
}

.whats-new-item-detail {
  display: block;
  margin-block-start: var(--johnbot-space-0-5);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-sm);
}

.whats-new-item::before {
  content: "";
  position: absolute;
  inset-block-start: 0.75em;
  inset-inline-start: var(--johnbot-space-1);
  width: 8px;
  height: 1px;
  background: color-mix(in srgb, var(--whats-new-tone) 70%, transparent);
}

.whats-new-toggle {
  margin-inline-start: calc(-1 * var(--johnbot-space-2));
  color: var(--johnbot-text-muted);
}

.whats-new-actions .ui-button svg,
.whats-new-toggle svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: 0 0 auto;
  stroke-width: var(--johnbot-icon-stroke);
}

.whats-new-toggle svg {
  transition: transform var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.whats-new-toggle[data-expanded] svg {
  transform: rotate(180deg);
}

.whats-new-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-2);
  padding: var(--johnbot-space-3) var(--johnbot-space-4);
  border-block-start: 1px solid var(--johnbot-border);
}

@media (max-width: 560px) {
  .whats-new-backdrop {
    padding: var(--johnbot-space-3);
  }

  .whats-new-header {
    padding-inline: var(--johnbot-space-4);
  }

  .whats-new-body {
    padding-inline: var(--johnbot-space-4);
  }
}

@media (prefers-reduced-motion: reduce) {
  .whats-new-backdrop,
  .whats-new-toggle svg {
    animation: none;
    transition: none;
  }
}

/* The Help menu of the window rail. A long release headline ends in an ellipsis before its date. */
.help-menu {
  width: 320px;
}

.help-menu .help-menu-news {
  gap: var(--johnbot-space-3);
}

.help-menu-news-headline {
  min-width: 0;
  flex: 1 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.help-menu-news .ui-menu-trailing {
  flex: none;
}

