/* === from: @johnbot/ui/styles/reference-chip.css === */
.reference-chip,
/* Every composer token, including the ones for a reference whose agent or skill is gone. */
.composer-mention-token {
  display: inline-flex;
  box-sizing: border-box;
  min-width: 0;
  max-width: 100%;
  height: var(--johnbot-space-6);
  align-items: center;
  justify-content: flex-start;
  gap: var(--johnbot-space-1);
  margin: 0;
  overflow: hidden;
  border: 0;
  border-radius: var(--johnbot-radius-sm);
  background: var(--johnbot-border);
  padding: var(--johnbot-space-1) var(--johnbot-space-1-5) var(--johnbot-space-1) var(--johnbot-space-1);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-sm);
  font-weight: 500;
  line-height: var(--johnbot-space-4);
  vertical-align: middle;
  white-space: nowrap;
  text-decoration: none;
}

/* A plugin and an MCP server read as the skill chips do: each names something the agent was given. */
.reference-chip[data-kind="mcp"],
.reference-chip[data-kind="plugin"],
.reference-chip[data-kind="skill"] {
  background: var(--johnbot-accent-soft);
  color: var(--johnbot-accent-text);
}

/* A quote is a passage, not a name: it stops at a short width, and its title shows all of it. */
.reference-chip[data-kind="quote"] {
  max-width: min(240px, 100%);
  font-weight: 450;
}

.reference-chip[data-kind="agent"]:hover,
button.reference-chip[data-kind="quote"]:hover {
  background: var(--johnbot-border-strong);
  color: var(--johnbot-text-primary);
}

.reference-chip .reference-chip-icon {
  display: inline-grid;
  width: var(--johnbot-space-4);
  height: var(--johnbot-space-4);
  flex: 0 0 var(--johnbot-space-4);
  place-items: center;
  overflow: hidden;
  border-radius: var(--johnbot-radius-xs);
  color: inherit;
}

.reference-chip-icon > img,
.reference-chip-icon > svg {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

/* In the text, a line icon has the size and stroke of a file chip's page icon. Agent faces and logos
   keep the full box. */
:is(.message-reference-chip, .composer-mention-token) .reference-chip-icon > svg.lucide {
  width: var(--johnbot-icon-xs);
  height: var(--johnbot-icon-xs);
  stroke-width: var(--johnbot-icon-stroke);
}

.reference-chip-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* === from: @johnbot/ui/skill-preview.css === */
/* stagger.css */
:root {
  --stagger-dur: 500ms;
  --stagger-distance: 12px;
  --stagger-stagger: 40ms;
  --stagger-blur: 3px;
  --stagger-ease: cubic-bezier(0.22, 1, 0.36, 1);
}

/* Lines start translated down + blurred + invisible; .is-shown
   on the parent flips them to their resting state. The second
   line's transition-delay holds it back by --stagger-stagger
   so the eye lands on the headline first. */
.t-stagger-line {
  display: block;
  opacity: 0;
  transform: translateY(var(--stagger-distance));
  filter: blur(var(--stagger-blur));
  transition:
    opacity var(--stagger-dur) var(--stagger-ease),
    transform var(--stagger-dur) var(--stagger-ease),
    filter var(--stagger-dur) var(--stagger-ease);
  will-change: transform, opacity, filter;
}
.t-stagger-line--2 {
  transition-delay: var(--stagger-stagger);
}
.t-stagger-line--3 {
  transition-delay: calc(var(--stagger-stagger) * 2);
}

.t-stagger.is-shown .t-stagger-line {
  opacity: 1;
  transform: translateY(0);
  filter: blur(0);
}

@media (prefers-reduced-motion: reduce) {
  .t-stagger-line {
    transition: none !important;
  }
}


.skill-preview {
  display: grid;
  gap: var(--johnbot-space-6);
  min-width: 0;
}
.skill-preview-heading {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  column-gap: var(--johnbot-space-3);
  row-gap: var(--johnbot-space-3);
  align-items: center;
}
.skill-preview-heading .agent-skill-icon {
  grid-column: 1;
  align-self: center;
}
.skill-preview-name {
  grid-column: 2;
  min-width: 0;
}
.skill-preview-action {
  grid-column: 3;
  justify-self: end;
}
/* The one-line summary reads under the whole row, as the lead of the page. */
.skill-preview-summary {
  grid-column: 1 / -1;
}
.skill-preview-heading h2,
.skill-preview-heading p,
.skill-preview-request p {
  margin: 0;
}
.skill-preview-heading h2 {
  font-size: var(--johnbot-text-2xl);
  font-weight: var(--johnbot-weight-medium);
  overflow-wrap: anywhere;
}
.skill-preview-heading p,
.skill-preview-description {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-lg);
  line-height: 1.6;
  overflow-wrap: anywhere;
}
.skill-preview-heading .skill-preview-creator {
  margin-top: var(--johnbot-space-1);
  font-size: var(--johnbot-text-sm);
  line-height: var(--johnbot-leading-md);
}
.skill-preview-card {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 160px;
  overflow: hidden;
  isolation: isolate;
  border-radius: var(--johnbot-radius-xl);
  padding: var(--johnbot-space-6);
}
.skill-preview-gradient,
.skill-preview-gradient canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  /* The canvas composites on its own layer. Firefox does not apply an ancestor's rounded
     overflow clip to such a layer, so each level clips itself with clip-path, which does hold. */
  overflow: hidden;
  border-radius: inherit;
  clip-path: inset(0 round var(--johnbot-radius-xl));
}
/* The artwork stays behind the content by paint order alone. A z-index of its own puts it on a
   stacking context that Firefox paints without the rounded clip, and the card's corners come back
   square; the content is positioned instead, so it still paints over the artwork. */
.skill-preview-card > :not(.skill-preview-gradient) {
  position: relative;
}
.skill-preview-request {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-3);
  width: min(100%, 520px);
  min-width: 0;
  border-radius: var(--johnbot-radius-card);
  background: var(--johnbot-bg-canvas);
  padding: var(--johnbot-space-3);
  color: var(--johnbot-text-secondary);
  font-size: var(--johnbot-text-lg);
  line-height: 1.5;
}
.skill-preview-request p {
