  font-size: var(--johnbot-text-md);
}
.skill-preview-description > :first-child {
  margin-top: 0;
}
.skill-preview-description > :last-child {
  margin-bottom: 0;
}

.skill-preview-request .ui-icon-button {
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-border);
}
.agent-skills-modal:has(.agent-skill-detail) {
  width: min(760px, calc(100vw - 32px));
  height: min(640px, calc(100dvh - 48px));
}

:root {
  --page-slide-dur: 250ms;
  --page-fade-dur: 250ms;
  --page-slide-distance: 8px;
  --page-blur: 3px;
  --page-stagger: 0ms;
  --page-exit-enabled: 1;
  --page-slide-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --page-fade-ease: cubic-bezier(0.22, 1, 0.36, 1);
}

.t-page-slide {
  position: relative;
}
.t-page-slide .t-page[data-page-id="1"] {
  --t-page-from-x: calc(var(--page-slide-distance) * -1);
}
.t-page-slide .t-page[data-page-id="2"] {
  --t-page-from-x: var(--page-slide-distance);
}
.t-page-slide .t-page {
  position: absolute;
  inset: 0;
  opacity: 0;
  pointer-events: none;
  transform: translateX(calc(var(--t-page-from-x, 0px) * var(--page-exit-enabled)));
  filter: blur(calc(var(--page-blur) * var(--page-exit-enabled)));
  transition:
    opacity var(--page-fade-dur) var(--page-fade-ease),
    transform var(--page-slide-dur) var(--page-slide-ease),
    filter var(--page-slide-dur) var(--page-slide-ease);
  will-change: opacity, transform, filter;
}
.t-page-slide[data-page="1"] .t-page[data-page-id="1"],
.t-page-slide[data-page="2"] .t-page[data-page-id="2"] {
  opacity: 1;
  pointer-events: auto;
  transform: translateX(0);
  filter: blur(0);
  transition-delay: var(--page-stagger);
}

@media (prefers-reduced-motion: reduce) {
  .t-page-slide .t-page {
    transition: none !important;
  }
}

.agent-skills-pages {
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

/* Each page mounts on navigation, so its starting style supplies the entry state. */
@starting-style {
  .agent-skills-pages.t-page-slide .t-page {
    opacity: 0;
    transform: translateX(var(--t-page-from-x));
    filter: blur(var(--page-blur));
  }
}

:root {
  --resize-dur: 300ms;
  --resize-ease: cubic-bezier(0.22, 1, 0.36, 1);
}

.t-resize {
  transition:
    width var(--resize-dur) var(--resize-ease),
    height var(--resize-dur) var(--resize-ease);
  will-change: width, height;
}

@media (prefers-reduced-motion: reduce) {
  .t-resize {
    transition: none !important;
  }
}

.skill-preview-heading.t-stagger-line,
.skill-preview-card.t-stagger-line {
  display: grid;
}

/* Start each newly loaded preview at the entrance state without delaying its content. */
@starting-style {
  .skill-preview.t-stagger.is-shown .t-stagger-line {
    opacity: 0;
    transform: translateY(var(--stagger-distance));
    filter: blur(var(--stagger-blur));
  }
}

/* The fallback is what a preview whose logo yields no tint already uses, and it is needed here: a
   plugin listing reuses these classes without setting `--skill-logo-color`. Without it both
   declarations are invalid at computed-value time, so the chip loses its fill to `transparent`
   rather than falling back to the accent fill the base rule gives it. */
.skill-preview-request .skill-preview-chip {
  color: color-mix(in srgb, var(--skill-logo-color, var(--johnbot-accent-text)), var(--johnbot-text-primary) 35%);
  background: color-mix(in srgb, var(--skill-logo-color, var(--johnbot-accent-text)) 18%, transparent);
}

.agent-skills-tabs {
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.agent-skills-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--johnbot-space-2);
  flex-shrink: 0;
  margin: var(--johnbot-space-3);
}

.agent-skills-tab-content {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}

.agent-local-skill-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--johnbot-space-2);
}
.agent-skills-tab-slot {
  flex: 1;
  min-height: 0;
  overflow: hidden;
}
@starting-style {
  .agent-skills-tab-content[data-selected] {
    opacity: 0;
    transform: translateY(var(--sliding-tabs-content-distance));
    filter: blur(var(--sliding-tabs-content-blur));
  }
}

.agent-local-library:not(.agent-skill-detail) {
  gap: var(--johnbot-space-0-5);
  padding: 0;
}
.agent-local-skill-row:has(.agent-skill-update) {
  grid-template-columns: minmax(0, 1fr) auto auto;
}

/* === from: ./styles/window-glass.css === */
/* The transparent window on macOS. Main gives the main window the system blur and a clear
 * background, and sets `data-johnbot-window-glass` on the root. Only the layers that make the page
 * change here: the frame, the content card and the pages that fill the card. The surface tokens do
 * not change, so dialogs, menus, tooltips, toasts, the composer and the cards stay solid. A browser
 * tab, an iframe or a canvas stays opaque: CSS cannot make a native view clear. */
:root[data-johnbot-window-glass] {
  --window-glass-frame: color-mix(in srgb, var(--johnbot-bg-frame) 20%, transparent);
  --window-glass-card: color-mix(in srgb, var(--johnbot-bg-canvas) 45%, transparent);
}

:root[data-johnbot-window-glass] body {
  background: transparent;
}

:root[data-johnbot-window-glass] .app-window {
  --window-frame: var(--window-glass-frame);
}

/* The narrow window has no card: the panes sit on the frame. */
@media (max-width: 720px) {
  :root[data-johnbot-window-glass] .app-window > .app-frame-edge {
    background: var(--window-glass-card);
  }
}

@media (min-width: 721px) {
  /* The window paints the frame once. Opaque, these layers repeat its color; translucent, each one
   * would add its tint again, and the top row would show darker than the page rail. */
  :root[data-johnbot-window-glass] .app-window > .app-frame-edge,
  :root[data-johnbot-window-glass] .app-window > .app-frame-edge > .server-rail {
    background: transparent;
  }

  :root[data-johnbot-window-glass] .app-window > .app-frame-edge::before,
  :root[data-johnbot-window-glass]
    .app-window
    > .app-frame-edge
    .side-panel-maximized
    > :is(.settings-panel, .browser-panel),
  :root[data-johnbot-window-glass] .app-frame-edge .diagram-view-body {
    background: var(--window-glass-card);
  }
}

/* The sidebar, the card and the top row are clear, so no ring colour matches what shows through them:
 * an avatar outline there would be a halo. A row that paints its own hover or selected fill sets the
 * outline again. */
:root[data-johnbot-window-glass] .app-window > .app-frame-edge > .sidebar,
:root[data-johnbot-window-glass] .app-window > .app-frame-edge :is(.channel-empty, .channel-title),
:root[data-johnbot-window-glass]
  .app-window
  > .app-frame-edge
  > .sidebar
  :is(.sidebar-section-agent-drop-target, .sidebar-pinned-group-agent-drop-target)
  > * {
  --agent-avatar-outline: transparent;
}

/* With no outline, faces that overlap would merge into one shape, so the channel title and the empty
 * state put them side by side. This also covers the title's hover fill, which has no clear part. */
:root[data-johnbot-window-glass]
  .app-window
  > .app-frame-edge
  :is(.channel-empty, .channel-title)
  .channel-avatar
  .agent-avatar
  + .agent-avatar {
  margin-left: 0;
}

/* The pages in the card are clear, so the card's tint shows once and not twice. */
:root[data-johnbot-window-glass]
  .app-window
  :is(.schedule-pane, .agent-usage, .diagram-view, .settings-page-content .agent-files-view) {
  background: transparent;
}

:root[data-johnbot-window-glass] .app-window .diagram-board-viewport {
  background-color: transparent;
}

/* The Settings fades cover the rows that scroll under them, so they take the card's tint. */
:root[data-johnbot-window-glass] .app-window .settings-page-content .settings-modal-scroll-frame::before {
  background: linear-gradient(to bottom, var(--window-glass-card) 28%, transparent 100%);
}

:root[data-johnbot-window-glass] .app-window .settings-page-content .settings-modal-scroll-frame::after {
  background: linear-gradient(to top, var(--window-glass-card) 28%, transparent 100%);
}

/* The full-bleed browser covers the window with its own frame and card. */
:root[data-johnbot-window-glass] .browser-full-view {
  background: var(--window-glass-frame);
}

/* === from: @johnbot/ui/stagger.css === */:root {
  --stagger-dur: 500ms;
  --stagger-distance: 12px;
  --stagger-stagger: 40ms;
  --stagger-blur: 3px;
  --stagger-ease: cubic-bezier(0.22, 1, 0.36, 1);
}

/* Lines start translated down + blurred + invisible; .is-shown
   on the parent flips them to their resting state. The second
   line's transition-delay holds it back by --stagger-stagger
   so the eye lands on the headline first. */
.t-stagger-line {
  display: block;
  opacity: 0;
  transform: translateY(var(--stagger-distance));
  filter: blur(var(--stagger-blur));
  transition:
    opacity var(--stagger-dur) var(--stagger-ease),
    transform var(--stagger-dur) var(--stagger-ease),
    filter var(--stagger-dur) var(--stagger-ease);
  will-change: transform, opacity, filter;
}
.t-stagger-line--2 {
  transition-delay: var(--stagger-stagger);
}
.t-stagger-line--3 {
  transition-delay: calc(var(--stagger-stagger) * 2);
}

.t-stagger.is-shown .t-stagger-line {
  opacity: 1;
  transform: translateY(0);
  filter: blur(0);
}

@media (prefers-reduced-motion: reduce) {
  .t-stagger-line {
    transition: none !important;
  }
}

