/* upstream: packages/ui/src/features/marketplace/marketplace.css */
/* The Marketplace window: agents, apps and skills, and a page for each. Tokens only. */

/* ---------------------------------------------------------------- window */

/* A page of the window: the window card draws the surface, the line and the corner. */
.skills-marketplace {
  /* One inset for the whole window: the top bar title and the body start on it. */
  --marketplace-inset: var(--johnbot-space-6);
  display: grid;
  /* The side panel has the width of the settings page nav. The top row is above both columns. */
  grid-template-columns: max(var(--left-panel-width, 280px), 220px) minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  width: 100%;
  height: 100%;
  overflow: hidden;
  color: var(--johnbot-text-primary);
}

/* Menus and the connect and confirm dialogs open over the window. */
.marketplace-menu {
  z-index: calc(var(--johnbot-layer-dialog-host) + 1);
}

/* `MarketplacePage` sets the body attribute; a `body:has()` rule restyles the whole page on each chat change. */
body[data-skills-marketplace] :is(.integration-dialog-backdrop, .integration-wizard-dialog):not([data-nested]) {
  z-index: calc(var(--johnbot-layer-dialog-host) + 1);
}

.skills-marketplace-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-3);
  grid-column: 1 / -1;
  min-height: 48px;
  padding-block: var(--johnbot-space-2);
  padding-inline: var(--marketplace-inset) var(--johnbot-space-2);
  border-bottom: 1px solid var(--johnbot-border);
}

/* ---------------------------------------------------------------- side panel */

/* As the settings page nav: the title and the kinds, then the apps that the user connected. */
.marketplace-nav {
  display: flex;
  grid-row: 2;
  grid-column: 1;
  min-width: 0;
  min-height: 0;
  flex-direction: column;
  gap: var(--johnbot-space-1);
  overflow-y: auto;
  padding: var(--johnbot-space-4) var(--johnbot-space-3) var(--johnbot-space-3);
  border-inline-end: 1px solid var(--johnbot-border);
}

.marketplace-nav-title {
  margin: 0 0 var(--johnbot-space-3);
  padding: 0 var(--johnbot-space-2);
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-lg);
}

/* The title takes the focus when the page opens, only so a screen reader reads it. */
.marketplace-nav-title:focus {
  outline: none;
}

.marketplace-nav-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

/* The icon column holds an app logo, which has its own margin, so it is one step bigger than a line icon. The kind
   icons stay at their size in its center, so all names start at the same place. */
.marketplace-nav-item {
  grid-template-columns: var(--johnbot-icon-lg) minmax(0, 1fr) auto;
}

/* A row is a shared Button: it keeps the text of a settings row, not the larger text of a button. */
.ui-button.marketplace-nav-item {
  font: inherit;
  font-size: var(--johnbot-text-md);
  white-space: normal;
}

.ui-button.marketplace-nav-item[aria-current] {
  font-weight: var(--johnbot-weight-medium);
}

/* The kind that holds the open page is selected, as the page itself is. */
.marketplace-nav-item[aria-current="location"] {
  background: var(--johnbot-bg-control-hover);
  color: var(--johnbot-text-primary);
  font-weight: var(--johnbot-weight-medium);
}

.marketplace-nav-item > svg:first-child {
  justify-self: center;
}

.marketplace-nav-count {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-regular);
  font-variant-numeric: tabular-nums;
}

.marketplace-nav-heading {
  margin: var(--johnbot-space-4) 0 var(--johnbot-space-1);
  padding: 0 var(--johnbot-space-2);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-sm);
  font-weight: var(--johnbot-weight-medium);
  line-height: var(--johnbot-leading-sm);
}

.marketplace-nav-mark {
  display: grid;
  width: var(--johnbot-icon-lg);
  height: var(--johnbot-icon-lg);
  place-items: center;
  overflow: hidden;
  border-radius: var(--johnbot-radius-xs);
}

.marketplace-nav-mark > :is(svg, img) {
  width: 100%;
  height: 100%;
  stroke-width: var(--johnbot-icon-stroke-lg);
}

.marketplace-nav-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.marketplace-nav-item > .marketplace-nav-warning {
  color: var(--johnbot-warning-text);
}

.skills-marketplace-body {
  position: relative;
  grid-row: 2;
  grid-column: 2;
  overflow: auto;
  scrollbar-gutter: stable;
}

/* Each list and page has one width, so the content does not move when a page opens. The large list title needs more
   space below the top bar than the inset gives. */
.marketplace-frame {
  padding: calc(var(--johnbot-space-8) + var(--johnbot-space-2)) var(--marketplace-inset) var(--johnbot-space-8);
}

.marketplace-frame > * {
  width: min(100%, 880px);
  margin-inline: auto;
}

.skills-marketplace-error {
  position: sticky;
  bottom: var(--johnbot-space-4);
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  width: fit-content;
  max-width: calc(100% - 32px);
  margin: 0 auto var(--johnbot-space-4);
  padding-block: var(--johnbot-space-1);
  padding-inline: var(--johnbot-space-3) var(--johnbot-space-1);
  border: 1px solid var(--johnbot-danger);
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-bg-control);
  color: var(--johnbot-danger);
  box-shadow: 0 12px 32px var(--johnbot-shadow-dialog);
}

.marketplace-visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* ---------------------------------------------------------------- heading */

.marketplace-heading {
  display: flex;
  flex: 1;
  align-items: center;
  gap: var(--johnbot-space-1-5);
  min-width: 0;
}

.marketplace-title {
  min-width: 0;
  margin: 0;
  overflow: hidden;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-semibold);
  line-height: var(--johnbot-leading-lg);
  text-overflow: ellipsis;
  white-space: nowrap;
}

/*
 * A parent in the path is plain text until the pointer is on it: then it shows the outline button chip, as the parent
 * in the path did before. The start margin cancels the chip's padding and border, so the text stays on the inset. The
 * end margin cancels less, so the chip does not touch the separator.
 */
.skills-marketplace .marketplace-crumb-parent {
  flex: 0 1 auto;
  min-width: 0;
  margin-inline: calc(-1 * var(--johnbot-space-2) - 1px) calc(-1 * var(--johnbot-space-1));
  overflow: hidden;
  border-color: transparent;
  background: transparent;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.skills-marketplace .marketplace-crumb-parent:focus-visible {
  border-color: var(--johnbot-border);
  background: var(--johnbot-bg-control);
  color: var(--johnbot-text-primary);
}

@media (hover: hover) and (pointer: fine) {
  .skills-marketplace .marketplace-crumb-parent:hover:not(:disabled) {
    border-color: var(--johnbot-border);
    background: var(--johnbot-bg-control);
    color: var(--johnbot-text-primary);
  }
}

.marketplace-crumb-separator {
  flex: 0 0 auto;
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  color: var(--johnbot-text-muted);
}

/* Right to left, the arrow points the other way. */
.marketplace-crumb-separator:dir(rtl),
.marketplace-skill-group-head .ui-button > svg[class~="lucide-chevron-right"]:dir(rtl) {
  transform: scaleX(-1);
}

/* A title takes focus when its view opens. The focus is for screen readers, not a control. */
.marketplace-title:focus,
.skills-marketplace-body h3[tabindex="-1"]:focus {
  outline: none;
}

/* ---------------------------------------------------------------- views */

.marketplace-view,
.marketplace-stack {
  display: grid;
  align-content: start;
  gap: var(--johnbot-space-6);
  min-width: 0;
}

.marketplace-head {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-4);
}

/* Why an app does not connect here: it wraps, as cut to one line it would lose what to do. */
.marketplace-app-reason {
  white-space: normal;
}

.marketplace-command {
  overflow-wrap: anywhere;
  color: var(--johnbot-text-primary);
  font-family: var(--johnbot-font-mono);
  font-size: var(--johnbot-text-sm);
}

/* The head of a list: its title and one line, then the search and the filter on one row. */
.marketplace-browse {
  gap: var(--johnbot-space-8);
}

.marketplace-browse-head {
  display: grid;
  gap: var(--johnbot-space-6);
}

.marketplace-browse-copy {
  display: grid;
  gap: var(--johnbot-space-1);
}

.marketplace-browse-copy > p {
  margin: 0;
}

.marketplace-browse-title {
  margin: 0;
  font-size: var(--johnbot-text-3xl);
}

.marketplace-toolbar {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
}

.marketplace-search {
  position: relative;
  flex: 1;
  min-width: 0;
}

.marketplace-load-more {
  justify-self: center;
}

/* ---------------------------------------------------------------- avatars and marks */

.marketplace-avatar {
  --marketplace-avatar-size: 20px;
  display: inline-grid;
  flex: none;
  width: var(--marketplace-avatar-size);
  height: var(--marketplace-avatar-size);
}

.marketplace-avatar[data-size="xs"] {
  --marketplace-avatar-size: 16px;
}

.marketplace-avatar[data-size="md"] {
  --marketplace-avatar-size: 40px;
}

.marketplace-avatar[data-size="lg"] {
  --marketplace-avatar-size: 48px;
}

/* An agent avatar stands low in its box. Lift it to the middle, as the channel avatar does. */
.marketplace-avatar > .agent-avatar {
  --agent-avatar-optical-offset: calc(var(--marketplace-avatar-size) * -0.14);
  width: 100%;
  height: 100%;
}

/* A skill's icon, or a spark, on a quiet tile. */
.marketplace-skill-mark {
  display: inline-grid;
  flex: none;
  place-items: center;
  width: 20px;
  height: 20px;
  overflow: hidden;
  border-radius: var(--johnbot-radius-xs);
  background: var(--johnbot-bg-control);
  color: var(--johnbot-text-muted);
}

.marketplace-skill-mark[data-size="row"] {
  width: 36px;
  height: 36px;
  border-radius: var(--johnbot-radius-md);
}

.marketplace-skill-mark[data-size="md"] {
  width: 40px;
  height: 40px;
  border-radius: var(--johnbot-radius-md);
}

/* A plugin icon in a row. `PluginIcon` also draws the icon of the MCP connect dialog. */
.skills-marketplace-icon {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 42px;
  height: 42px;
  overflow: hidden;
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-control);
  color: var(--johnbot-accent-text);
}

.skills-marketplace-icon:has(img) {
  border: 0;
  background: transparent;
}

.skills-marketplace-icon img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.skills-marketplace-icon svg {
  width: 20px;
  height: 20px;
  stroke-width: var(--johnbot-icon-stroke-lg);
}

.marketplace-skill-mark[data-kind="icon"] > img {
  width: 100%;
  height: 100%;
}

.marketplace-skill-mark[data-kind="none"] > * {
  width: 60%;
  height: 60%;
}

/* ---------------------------------------------------------------- cards */

.marketplace-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: var(--johnbot-space-3);
}

.marketplace-card {
  position: relative;
  display: grid;
  min-width: 0;
  grid-template-rows: auto 1fr auto;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-4);
  border: 1px solid var(--johnbot-border-grouped);
  border-radius: var(--johnbot-radius-card);
  background: var(--johnbot-bg-grouped);
  transition: background var(--johnbot-duration-fast) var(--johnbot-ease-out);
}

.marketplace-card:hover:not(.marketplace-card-skeleton) {
  background: var(--johnbot-bg-control-hover);
}

.marketplace-card-head {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-3);
  min-width: 0;
}

.marketplace-card-name {
  flex: 1;
  min-width: 0;
  margin: 0;
  overflow-wrap: anywhere;
}

/* The action sits above the hit area, so "Add" adds and the rest of the card opens the page. */
.marketplace-card-action {
  position: relative;
  z-index: 2;
  display: inline-flex;
  flex: 0 1 auto;
  align-items: center;
  gap: var(--johnbot-space-2);
  min-width: 0;
  max-width: 60%;
}

.marketplace-card-body {
  display: -webkit-box;
  margin: 0;
  overflow: hidden;
  color: var(--johnbot-text-secondary);
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
}

.marketplace-card-foot {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
  min-height: 16px;
  font-variant-numeric: tabular-nums;
}

.marketplace-hitarea {
  position: absolute;
  inset: 0;
  z-index: 1;
  width: 100%;
  height: 100%;
  border-radius: inherit;
  background: transparent;
}

/* The card draws the hover. The shared ghost hover would cover the text above the hit area. */
.marketplace-hitarea:hover:not(:disabled) {
  background: transparent;
}

.marketplace-card-skeleton {
  grid-template-rows: auto auto auto;
}

.marketplace-skeleton-mark {
  width: 40px;
  height: 40px;
  border-radius: var(--johnbot-radius-md);
}

.marketplace-skeleton-line {
  width: 100%;
  height: 12px;
}

.marketplace-skeleton-line:last-child {
  width: 60%;
}

.marketplace-done {
  display: inline-flex;
  align-items: center;
  gap: var(--johnbot-space-1);
  color: var(--johnbot-success-text);
  font-size: var(--johnbot-text-sm);
  white-space: nowrap;
}

.marketplace-done > svg {
  width: var(--marketplace-done-icon, 14px);
  height: var(--marketplace-done-icon, 14px);
  color: var(--marketplace-done-mark, currentColor);
}

/* ---------------------------------------------------------------- app list */

.marketplace-app-group {
  display: grid;
  gap: var(--johnbot-space-3);
  padding-top: var(--johnbot-space-4);
  border-top: 1px solid var(--johnbot-border);
}

.marketplace-app-group-title {
  display: flex;
  align-items: baseline;
  gap: var(--johnbot-space-2);
  margin: 0;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-semibold);
}

.marketplace-app-group-count {
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-regular);
  font-variant-numeric: tabular-nums;
}

.marketplace-app-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  column-gap: var(--johnbot-space-6);
  row-gap: var(--johnbot-space-1);
  margin: 0;
  padding: 0;
  list-style: none;
}

/* The row opens the app page; the status control sits above the hit area. */
.marketplace-app-row {
  position: relative;
  display: flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-lg);
}

@media (hover: hover) and (pointer: fine) {
  .marketplace-app-row:hover {
    background: var(--johnbot-bg-control-hover);
  }

  /* The row hover has the color of the Connect button, so on a hovered row the button is one step lighter. */
  .marketplace-app-row:hover .marketplace-app-action[data-variant="secondary"]:not([data-disabled]) {
    background: var(--johnbot-bg-control-active);
  }
}

.skills-marketplace .marketplace-app-row-hit {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  padding: 0;
  border-radius: inherit;
  background: transparent;
}

/* The row draws the hover. The shared ghost hover would cover the text above the hit area. */
.skills-marketplace .marketplace-app-row-hit:hover:not(:disabled) {
  background: transparent;
}

/* A little bigger than the settings tile, so that a logo with its own margin still reads. */
.marketplace-app-row > .integration-logo-tile {
  --integration-tile: 40px;
  pointer-events: none;
}

.marketplace-app-row-copy {
  display: grid;
  flex: 1;
  min-width: 0;
  gap: var(--johnbot-space-0-5);
  pointer-events: none;
}

.marketplace-app-row-name {
  overflow: hidden;
  color: var(--johnbot-text-primary);
  font-size: var(--johnbot-text-lg);
  font-weight: var(--johnbot-weight-medium);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.marketplace-app-row-tagline {
  overflow: hidden;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.marketplace-app-row-status {
  position: relative;
  display: inline-flex;
  flex: none;
}

/* As tall as a button, so the rows keep one height. The check has the success color; the word stays quiet. */
.marketplace-app-row-status > .marketplace-done {
  height: var(--johnbot-control-md);
  gap: var(--johnbot-space-1-5);
  padding-inline: var(--johnbot-space-2);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  --marketplace-done-icon: var(--johnbot-icon-md);
  --marketplace-done-mark: var(--johnbot-success);
}

/* ---------------------------------------------------------------- pages */

/* `dt` and `dd` are direct children of the list, so each fact is one pair of grid rows. */
.marketplace-props {
  display: grid;
  gap: var(--johnbot-space-0-5);
  margin: 0;
}

.marketplace-props > dd {
  margin: 0 0 var(--johnbot-space-3);
}

.marketplace-props > dd:last-child {
  margin-bottom: 0;
}

/* The Information list of an app page: the label and the value side by side. */
.marketplace-info {
  grid-template-columns: minmax(120px, max-content) minmax(0, 1fr);
  column-gap: var(--johnbot-space-6);
  row-gap: var(--johnbot-space-2);
}

.marketplace-info > dd {
  margin: 0;
}

.skills-marketplace .marketplace-link {
  height: auto;
  padding: 0;
  /* The size of the other values in the list. */
  font-size: var(--johnbot-text-md);
}

/* The skill-preview card, with room for more than one request. */
.marketplace-try {
  display: grid;
  gap: var(--johnbot-space-2);
}

.skill-preview-card.marketplace-try-card {
  gap: var(--johnbot-space-2);
}

/* Every text line is as tall as the chip, so the chip and the text share one line. */
.marketplace-try-card .skill-preview-request {
  width: min(100%, 560px);
  line-height: var(--johnbot-space-6);
}

.marketplace-try-card .skill-preview-chip {
  margin-inline-end: var(--johnbot-space-0-5);
  vertical-align: top;
}

.marketplace-try-card .reference-chip-icon > :is(img, svg) {
  width: 100%;
  height: 100%;
}

/* The skill's SKILL.md, as the agent reads it. */
.marketplace-doc {
  min-width: 0;
  padding: var(--johnbot-space-4) var(--johnbot-space-6);
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-card);
  font-size: var(--johnbot-text-sm);
  overflow-wrap: anywhere;
}

.marketplace-doc > :first-child {
  margin-top: 0;
}

.marketplace-doc > :last-child {
  margin-bottom: 0;
}

/* ---------------------------------------------------------------- no results */

.marketplace-empty {
  display: grid;
  justify-items: center;
  gap: var(--johnbot-space-2);
  padding: var(--johnbot-space-8) var(--johnbot-space-6);
  border: 1px dashed var(--johnbot-border-strong);
  border-radius: var(--johnbot-radius-card);
  text-align: center;
}

/* The fishing plush of the "no match" state. */
.marketplace-empty-plush {
  display: block;
  width: 160px;
  aspect-ratio: 1;
  pointer-events: none;
  user-select: none;
}

.marketplace-empty-plush > img,
.marketplace-empty-plush > video {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.marketplace-empty > p {
  max-width: 440px;
  margin: 0;
}

.marketplace-empty > .ui-button {
  margin-top: var(--johnbot-space-2);
}

.marketplace-empty-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--johnbot-space-2);
}

/* ---------------------------------------------------------------- narrow */

/* A narrow window puts the kinds in a row above the list. The connected apps are in the list. */
/* ---------------------------------------------------------------- skills */

/* A state that needs the user: "Off", "Update available", "Changed by you", "Needs repair". */
.marketplace-skill-attention {
  color: var(--johnbot-text-secondary);
}

/* The skill mark sits under the row's hit area, as an app logo does. */
.marketplace-skill-row > .marketplace-skill-mark {
  pointer-events: none;
}

.marketplace-skill-row-actions {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-2);
}

/* The head keeps the height of its "See all" button, so the rows do not move when a search hides it. */
.marketplace-skill-group-head {
  display: flex;
  min-height: var(--johnbot-control-md);
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-2);
}

.marketplace-skill-empty {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-3);
  border: 1px dashed var(--johnbot-border);
  border-radius: var(--johnbot-radius-lg);
  padding: var(--johnbot-space-4);
}

/* The search icon, as in the Marketplace search. */
:is(.marketplace-skill-picker-search, .marketplace-skill-page-search) > svg {
  width: var(--johnbot-space-4);
  height: var(--johnbot-space-4);
  flex: none;
}

.marketplace-skill-agents-trigger {
  gap: var(--johnbot-space-1-5);
}

.marketplace-skill-stack {
  display: inline-flex;
}

.marketplace-skill-stack > :not(:first-child) {
  margin-inline-start: calc(var(--johnbot-space-1) * -1);
}

/* The agent picker in the agents dialog. */
.marketplace-skill-picker {
  display: flex;
  flex-direction: column;
  gap: var(--johnbot-space-1);
  font-size: var(--johnbot-text-md);
}

.marketplace-skill-picker-search {
  margin-block-end: var(--johnbot-space-1);
}

/* Many agents do not fit: the list scrolls under the search field. */
.marketplace-skill-picker-list {
  --marketplace-skill-fade-top: 0px;
  --marketplace-skill-fade-bottom: 0px;
  display: flex;
  max-height: calc(var(--johnbot-space-1) * 90);
  margin: 0;
  padding: 0;
  overflow-y: auto;
  flex-direction: column;
  list-style: none;
  scrollbar-width: none;
  mask-image: linear-gradient(
    to bottom,
    var(--johnbot-transparent),
    var(--johnbot-text-primary) var(--marketplace-skill-fade-top),
    var(--johnbot-text-primary) calc(100% - var(--marketplace-skill-fade-bottom)),
    var(--johnbot-transparent)
  );
}

/* No scroll bar: the fades show that more rows are above or below. */
.marketplace-skill-picker-list::-webkit-scrollbar {
  display: none;
}

.marketplace-skill-picker-list.scroll-fade-top {
  --marketplace-skill-fade-top: calc(var(--johnbot-space-1) * 6);
}

.marketplace-skill-picker-list.scroll-fade-bottom {
  --marketplace-skill-fade-bottom: calc(var(--johnbot-space-1) * 6);
}

/* A drag over the rows sets them all, so it must not select their text. */
.marketplace-skill-picker-list:has(label.marketplace-skill-picker-row) {
  user-select: none;
}

.marketplace-skill-picker-row {
  display: flex;
  width: 100%;
  min-height: calc(var(--johnbot-space-1) * 9);
  align-items: center;
  justify-content: flex-start;
  gap: var(--johnbot-space-2);
  border-radius: var(--johnbot-radius-md);
  padding-inline: var(--johnbot-space-2);
  cursor: pointer;
  font-weight: inherit;
  text-align: start;
}

label.marketplace-skill-picker-row:hover {
  background: var(--johnbot-hover);
}

/* While a drag runs, the row under the pointer does not light up: the check boxes show the range. */
.marketplace-skill-picker-list[data-dragging] label.marketplace-skill-picker-row:hover {
  background: none;
}

.marketplace-skill-picker-row[aria-current="true"] {
  background: var(--johnbot-bg-control-active);
}

.marketplace-skill-picker-all {
  border-block-end: 1px solid var(--johnbot-border);
  border-end-start-radius: 0;
  border-end-end-radius: 0;
}

.marketplace-skill-picker-name {
  min-width: 0;
  overflow: hidden;
  flex: 1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The name and the title of an agent stay together; the note stays at the end of the row. */
.marketplace-skill-picker-agent {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: center;
  gap: var(--johnbot-space-1);
}

/* As in the sidebar, a long title gets smaller before the name does, to two characters. */
.marketplace-skill-picker-agent:has(.agent-role-badge) {
  --agent-role-badge-collapsed-width: calc(2ch + 9px);

  display: grid;
  grid-template-columns:
    fit-content(calc(100% - var(--agent-role-badge-collapsed-width) - var(--johnbot-space-1)))
    minmax(var(--agent-role-badge-collapsed-width), 1fr);
}

.marketplace-skill-picker-none {
  padding: var(--johnbot-space-2);
}

/* The agents dialog names the skill, as a row does: its mark and its name. */
.marketplace-skill-dialog-head {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: var(--johnbot-space-3);
  margin-block: calc(var(--johnbot-space-2) * -1) calc(var(--johnbot-space-1) * -1);
}

.marketplace-skill-dialog-head h2 {
  min-width: 0;
  overflow: hidden;
  flex: 1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The dialog stays inside the window: the list takes the height that is left, and it scrolls. */
.integration-wizard-dialog.marketplace-skill-agents-dialog {
  overflow: hidden;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
}

.marketplace-skill-agents-dialog .integration-wizard-form {
  min-height: 0;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: minmax(0, 1fr) auto;
}

.marketplace-skill-agents-dialog .integration-wizard-body {
  display: flex;
  min-height: 0;
  flex-direction: column;
}

.marketplace-skill-agents-dialog .marketplace-skill-picker {
  min-height: 0;
}

.marketplace-skill-agents-dialog .marketplace-skill-picker-list {
  min-height: 0;
  flex: 1 1 auto;
}

/* A long list of agent names stops at the button edge; the title gives the full text. */
.marketplace-skill-agents-dialog .integration-wizard-foot > .ui-button {
  flex-shrink: 0;
}

.marketplace-skill-agents-dialog .integration-wizard-foot > .marketplace-skill-dialog-submit {
  min-width: 0;
  flex-shrink: 1;
}

.marketplace-skill-dialog-submit > span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The skill page: a search over the agents that have the skill. */
.marketplace-skill-page-search {
  width: calc(var(--johnbot-space-1) * 56);
}

/* The skill name and, for a skill that johnBot checked, the verified mark after it. */
.marketplace-skill-name {
  display: flex;
  align-items: center;
  gap: var(--johnbot-space-1);
  min-width: 0;
}

.marketplace-skill-verified {
  flex: none;
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  color: var(--johnbot-text-secondary);
}

/* The title on the left and the source switch (All, Verified, Public) on the right. */
.marketplace-skill-head-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--johnbot-space-4);
}

.marketplace-skill-source .ui-sliding-tabs-trigger {
  display: inline-flex;
  align-items: center;
  gap: var(--johnbot-space-1);
  white-space: nowrap;
}

/* A group page: the title, then the search and the sort, which stay at the top while the list scrolls. */
.marketplace-skill-group-page {
  display: grid;
  align-content: start;
  gap: var(--johnbot-space-4);
}

.marketplace-skill-group-bar {
  position: sticky;
  z-index: 1;
  top: 0;
  padding-block: var(--johnbot-space-3);
  border-bottom: 1px solid var(--johnbot-border);
  background: var(--johnbot-bg-canvas);
}

.marketplace-skill-group-list {
  display: grid;
  gap: var(--johnbot-space-3);
}

/* The highlights of a group: three cards over their artwork, so the page does not start as a flat list. */
.marketplace-skill-featured {
  display: grid;
  gap: var(--johnbot-space-3);
}

.marketplace-skill-featured-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--johnbot-space-3);
}

/* Its own stack, so "Add" above the hit area stays under the sticky search bar. */
.marketplace-skill-feature {
  isolation: isolate;
  grid-template-rows: auto auto 1fr auto;
  padding: var(--johnbot-space-3);
}

.marketplace-skill-feature > :not(.marketplace-hitarea, .marketplace-skill-feature-art) {
  padding-inline: var(--johnbot-space-1);
}

.marketplace-skill-feature-art {
  position: relative;
  display: grid;
  place-items: center;
  height: calc(var(--johnbot-space-1) * 24);
  overflow: hidden;
  isolation: isolate;
  border-radius: var(--johnbot-radius-xl);
}

.marketplace-skill-feature-art > :not(.skill-preview-gradient) {
  position: relative;
}

/* The mark stays beside the last word when a long name wraps. */
.marketplace-skill-feature .marketplace-skill-verified {
  display: inline-block;
  margin-inline-start: var(--johnbot-space-1);
  vertical-align: text-bottom;
}

/* ---------------------------------------------------------------- agents */

/* A featured agent: avatar and action, name and creator, two lines of text, then what it brings. The
   avatar carries the color, so the card has no artwork. Its own stack keeps "Add" under the sticky bar. */
.marketplace-agent-feature {
  isolation: isolate;
  grid-template-rows: auto auto 1fr auto;
}

.marketplace-agent-feature .marketplace-card-head {
  justify-content: space-between;
}

.marketplace-agent-feature-copy {
  display: grid;
  gap: var(--johnbot-space-0-5);
  min-width: 0;
}

/* The two lines of text keep their room, so the last line lines up across a row of cards. */
.marketplace-agent-feature .marketplace-card-body {
  align-self: start;
  min-height: 2lh;
}

.marketplace-agent-feature .marketplace-skill-verified {
  display: inline-block;
  margin-inline-start: var(--johnbot-space-1);
  vertical-align: text-bottom;
}

/* The creator after the name and the shield. It shrinks first, so the name stays. */
.marketplace-agent-by {
  flex: 0 100 auto;
  min-width: 0;
  overflow: hidden;
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The name and the creator share a baseline; the shield stays centred on the name. */
.marketplace-agent-row .marketplace-skill-name {
  align-items: baseline;
}

.marketplace-agent-row .marketplace-app-row-name {
  min-width: 0;
}

.marketplace-agent-row .marketplace-skill-verified {
  align-self: center;
}

/* Who made the agent and whether johnBot reviewed it, under the page header. */
.marketplace-agent-trust {
  display: flex;
  gap: var(--johnbot-space-1-5);
  align-items: center;
}

.marketplace-agent-trust svg {
  flex: none;
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
}

/* ---------------------------------------------------------------- view transitions */

/* View changes run in a view transition (`moveView`). The page slides a little in the way the
   user goes: a deeper view comes in from the end, back comes in from the start. Blur and fade
   carry the change, not travel. The old page leaves faster than the new one arrives. The names
   apply only during a Marketplace transition, so other transitions of the app do not capture them. */
html:active-view-transition-type(marketplace-forward, marketplace-back, marketplace-tab, marketplace-swap) {
  --marketplace-skill-blur: calc(var(--johnbot-space-0-5) * 1.5);
  --marketplace-skill-blur-small: var(--johnbot-space-0-5);
}

html:active-view-transition-type(marketplace-forward, marketplace-back, marketplace-tab, marketplace-swap)
  .skills-marketplace-body {
  view-transition-name: marketplace-page;
}

html:active-view-transition-type(marketplace-forward, marketplace-back, marketplace-tab, marketplace-swap)
  .skills-marketplace
  .marketplace-heading {
  view-transition-name: marketplace-crumbs;
}

/* Another source keeps the switch live, so its pill slides and does not fade over a copy. */
html:active-view-transition-type(marketplace-swap) .marketplace-skill-source {
  view-transition-name: marketplace-skill-source;
}

html:active-view-transition-type(
  marketplace-forward,
  marketplace-back,
  marketplace-tab,
  marketplace-swap
)::view-transition-group(root),
::view-transition-group(marketplace-page),
::view-transition-group(marketplace-crumbs) {
  animation-duration: var(--johnbot-duration-overlay);
  animation-timing-function: var(--johnbot-ease-out);
}

html:active-view-transition-type(marketplace-forward)::view-transition-old(marketplace-page) {
  --marketplace-skill-to: calc(var(--johnbot-space-2) * -1);
  animation: marketplace-skill-page-out var(--johnbot-duration-normal) var(--johnbot-ease-out) both;
}

html:active-view-transition-type(marketplace-forward)::view-transition-new(marketplace-page) {
  --marketplace-skill-from: var(--johnbot-space-2);
  animation: marketplace-skill-page-in var(--johnbot-duration-overlay) var(--johnbot-ease-out) both;
}

html:active-view-transition-type(marketplace-back)::view-transition-old(marketplace-page) {
  --marketplace-skill-to: var(--johnbot-space-2);
  animation: marketplace-skill-page-out var(--johnbot-duration-normal) var(--johnbot-ease-out) both;
}

html:active-view-transition-type(marketplace-back)::view-transition-new(marketplace-page) {
  --marketplace-skill-from: calc(var(--johnbot-space-2) * -1);
  animation: marketplace-skill-page-in var(--johnbot-duration-overlay) var(--johnbot-ease-out) both;
}

/* A right-to-left page steps the other way. */
html:dir(rtl):active-view-transition-type(marketplace-forward)::view-transition-old(marketplace-page) {
  --marketplace-skill-to: var(--johnbot-space-2);
}

html:dir(rtl):active-view-transition-type(marketplace-forward)::view-transition-new(marketplace-page) {
  --marketplace-skill-from: calc(var(--johnbot-space-2) * -1);
}

html:dir(rtl):active-view-transition-type(marketplace-back)::view-transition-old(marketplace-page) {
  --marketplace-skill-to: calc(var(--johnbot-space-2) * -1);
}

html:dir(rtl):active-view-transition-type(marketplace-back)::view-transition-new(marketplace-page) {
  --marketplace-skill-from: var(--johnbot-space-2);
}

/* Another kind in the side panel is a new list, not a step: it rises a little into place. */
html:active-view-transition-type(marketplace-tab)::view-transition-old(marketplace-page) {
  animation: marketplace-skill-blur-out var(--johnbot-duration-normal) var(--johnbot-ease-out) both;
}

html:active-view-transition-type(marketplace-tab)::view-transition-new(marketplace-page) {
  animation: marketplace-skill-rise-in var(--johnbot-duration-overlay) var(--johnbot-ease-out) both;
}

/* Another source or sort is the same list with other rows: the rows change through a blur in place. */
html:active-view-transition-type(marketplace-swap)::view-transition-old(marketplace-page) {
  animation: marketplace-skill-blur-out var(--johnbot-duration-fast) var(--johnbot-ease-out) both;
}

html:active-view-transition-type(marketplace-swap)::view-transition-new(marketplace-page) {
  animation: marketplace-skill-blur-in var(--johnbot-duration-normal) var(--johnbot-ease-out) both;
}

::view-transition-old(marketplace-skill-source) {
  animation: none;
  opacity: 0;
}

::view-transition-new(marketplace-skill-source) {
  animation: none;
}

/* "See all" and back on the Apps tab: the category title and its first rows are on both views, so
   they move to their new place and do not fade with the page. The rows are the same, so the new row
   comes in over the old one: an icon that loads late shows the old icon until it is ready. */
html:active-view-transition-type(marketplace-group)
  [data-marketplace-shared]
  :is(.marketplace-app-group-title, .marketplace-browse-title) {
  view-transition-name: marketplace-group-title;
}

html:active-view-transition-type(marketplace-group) [data-marketplace-shared] .marketplace-app-row:nth-child(1) {
  view-transition-name: marketplace-group-row-1;
}

html:active-view-transition-type(marketplace-group) [data-marketplace-shared] .marketplace-app-row:nth-child(2) {
  view-transition-name: marketplace-group-row-2;
}

html:active-view-transition-type(marketplace-group) [data-marketplace-shared] .marketplace-app-row:nth-child(3) {
  view-transition-name: marketplace-group-row-3;
}

html:active-view-transition-type(marketplace-group) [data-marketplace-shared] .marketplace-app-row:nth-child(4) {
  view-transition-name: marketplace-group-row-4;
}

html:active-view-transition-type(marketplace-group) [data-marketplace-shared] .marketplace-app-row:nth-child(5) {
  view-transition-name: marketplace-group-row-5;
}

html:active-view-transition-type(marketplace-group) [data-marketplace-shared] .marketplace-app-row:nth-child(6) {
  view-transition-name: marketplace-group-row-6;
}

::view-transition-group(marketplace-group-title),
::view-transition-group(marketplace-group-row-1),
::view-transition-group(marketplace-group-row-2),
::view-transition-group(marketplace-group-row-3),
::view-transition-group(marketplace-group-row-4),
::view-transition-group(marketplace-group-row-5),
::view-transition-group(marketplace-group-row-6) {
  animation-duration: var(--johnbot-duration-overlay);
  animation-timing-function: var(--johnbot-ease-out);
}

/* The title changes its size: both copies keep their shape and grow from the start edge. */
::view-transition-old(marketplace-group-title),
::view-transition-new(marketplace-group-title) {
  width: auto;
  height: 100%;
}

::view-transition-old(marketplace-group-title) {
  animation: marketplace-skill-blur-out var(--johnbot-duration-fast) var(--johnbot-ease-out) both;
}

::view-transition-new(marketplace-group-title) {
  animation: marketplace-skill-blur-in var(--johnbot-duration-normal) var(--johnbot-ease-out) both;
}

::view-transition-old(marketplace-group-row-1),
::view-transition-old(marketplace-group-row-2),
::view-transition-old(marketplace-group-row-3),
::view-transition-old(marketplace-group-row-4),
::view-transition-old(marketplace-group-row-5),
::view-transition-old(marketplace-group-row-6) {
  animation: none;
}

::view-transition-new(marketplace-group-row-1),
::view-transition-new(marketplace-group-row-2),
::view-transition-new(marketplace-group-row-3),
::view-transition-new(marketplace-group-row-4),
::view-transition-new(marketplace-group-row-5),
::view-transition-new(marketplace-group-row-6) {
  animation: marketplace-skill-blur-in var(--johnbot-duration-overlay) var(--johnbot-ease-out) both;
}

/* The crumbs change their last name in place. */
::view-transition-old(marketplace-crumbs) {
  animation: marketplace-skill-blur-out var(--johnbot-duration-fast) var(--johnbot-ease-out) both;
}

::view-transition-new(marketplace-crumbs) {
  animation: marketplace-skill-blur-in var(--johnbot-duration-normal) var(--johnbot-ease-out) both;
}

@keyframes marketplace-skill-page-out {
  to {
    opacity: 0;
    transform: translateX(var(--marketplace-skill-to));
    filter: blur(var(--marketplace-skill-blur));
  }
}

@keyframes marketplace-skill-page-in {
  from {
    opacity: 0;
    transform: translateX(var(--marketplace-skill-from));
    filter: blur(var(--marketplace-skill-blur));
  }
}

@keyframes marketplace-skill-rise-in {
  from {
    opacity: 0;
    transform: translateY(var(--johnbot-space-2));
    filter: blur(var(--marketplace-skill-blur));
  }
}

@keyframes marketplace-skill-blur-out {
  to {
    opacity: 0;
    filter: blur(var(--marketplace-skill-blur-small));
  }
}

@keyframes marketplace-skill-blur-in {
  from {
    opacity: 0;
    filter: blur(var(--marketplace-skill-blur-small));
  }
}

/* `moveView` skips the transition with reduced motion. This guard also stops one that starts. */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(marketplace-page),
  ::view-transition-group(marketplace-crumbs),
  ::view-transition-old(marketplace-page),
  ::view-transition-new(marketplace-page),
  ::view-transition-old(marketplace-crumbs),
  ::view-transition-new(marketplace-crumbs),
  ::view-transition-group(marketplace-group-title),
  ::view-transition-old(marketplace-group-title),
  ::view-transition-new(marketplace-group-title),
  ::view-transition-group(marketplace-group-row-1),
  ::view-transition-group(marketplace-group-row-2),
  ::view-transition-group(marketplace-group-row-3),
  ::view-transition-group(marketplace-group-row-4),
  ::view-transition-group(marketplace-group-row-5),
  ::view-transition-group(marketplace-group-row-6),
  ::view-transition-new(marketplace-group-row-1),
  ::view-transition-new(marketplace-group-row-2),
  ::view-transition-new(marketplace-group-row-3),
  ::view-transition-new(marketplace-group-row-4),
  ::view-transition-new(marketplace-group-row-5),
  ::view-transition-new(marketplace-group-row-6) {
    animation: none;
  }
}

@media (max-width: 720px) {
  .skills-marketplace {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto auto minmax(0, 1fr);
  }

  .marketplace-nav {
    grid-row: 2;
    overflow-x: auto;
    padding: var(--johnbot-space-2) var(--johnbot-space-3);
    border-inline-end: 0;
    border-bottom: 1px solid var(--johnbot-border);
  }

  .marketplace-nav-title,
  .marketplace-nav-group {
    display: none;
  }

  .marketplace-nav-list {
    grid-auto-columns: max-content;
    grid-auto-flow: column;
  }

  .skills-marketplace-body {
    grid-row: 3;
    grid-column: 1;
  }
}

@media (max-width: 860px) {
  .skills-marketplace {
    --marketplace-inset: var(--johnbot-space-4);
  }

  .marketplace-head {
    flex-wrap: wrap;
  }
}

/* Last, because it is the most specific icon rule: every button icon in the window is 16px. */
.skills-marketplace .ui-button > svg,
.marketplace-search > svg {
  width: 16px;
  height: 16px;
}

/* After the icon size rule, so that the warning color wins. */
.marketplace-app-action[data-status="attention"] > svg {
  color: var(--johnbot-warning-text);
}

/* After the icon size rule: an agent avatar draws past its box, so a button must not shrink it. */
:is(.marketplace-skill-agents-trigger, .marketplace-skill-picker-row) .agent-avatar > svg {
  width: 128%;
  height: 128%;
}

/* After the icon size rule: the source switch icons are small. */
.marketplace-skill-source .ui-sliding-tabs-trigger svg {
  width: var(--johnbot-icon-sm);
  height: var(--johnbot-icon-sm);
  flex: none;
}

/* The agent update dialog: the skills with local changes, each with a Replace box. */
.marketplace-agent-update-frame {
  border: 1px solid var(--johnbot-border);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-control);
  overflow: hidden;
}

.ui-confirm-dialog-body .marketplace-agent-update-list {
  --marketplace-agent-update-fade-top: 0px;
  --marketplace-agent-update-fade-bottom: 0px;
  display: flex;
  max-height: calc(var(--johnbot-space-8) * 7);
  margin: 0;
  border: 0;
  border-radius: 0;
  background: none;
  padding: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  flex-direction: column;
  list-style: none;
  scrollbar-width: none;
  mask-image: linear-gradient(
    to bottom,
    var(--johnbot-transparent),
    var(--johnbot-text-primary) var(--marketplace-agent-update-fade-top),
    var(--johnbot-text-primary) calc(100% - var(--marketplace-agent-update-fade-bottom)),
    var(--johnbot-transparent)
  );
}

/* No scroll bar: the fades show that more rows are above or below. */
.marketplace-agent-update-list::-webkit-scrollbar {
  display: none;
}

.marketplace-agent-update-list.scroll-fade-top {
  --marketplace-agent-update-fade-top: calc(var(--johnbot-space-1) * 6);
}

.marketplace-agent-update-list.scroll-fade-bottom {
  --marketplace-agent-update-fade-bottom: calc(var(--johnbot-space-1) * 6);
}

.marketplace-agent-update-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--johnbot-space-3);
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
}

.marketplace-agent-update-row + .marketplace-agent-update-row {
  border-top: 1px solid var(--johnbot-border);
}

.marketplace-agent-update-text {
  display: grid;
  min-width: 0;
}

.marketplace-agent-update-name {
  overflow: hidden;
  color: var(--johnbot-text-secondary);
  font-weight: var(--johnbot-weight-medium);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.marketplace-agent-update-state {
  color: var(--johnbot-text-dim);
  font-size: var(--johnbot-text-sm);
}

.marketplace-agent-update-row[data-replace] .marketplace-agent-update-state {
  color: var(--johnbot-warning-text);
}

/* Keep or Replace for one skill: the look of the window's sliding tabs, as a radio group. */
.marketplace-agent-update-choice {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: 3px;
  border-radius: var(--johnbot-radius-md);
  background: var(--johnbot-tabs-bar-bg);
  box-shadow: inset 0 0 0 1px var(--johnbot-border);
  padding: 3px;
}

.marketplace-agent-update-option {
  display: grid;
}

.marketplace-agent-update-option-label {
  display: inline-flex;
  height: var(--johnbot-control-sm);
  align-items: center;
  border-radius: var(--johnbot-radius-sm);
  padding: 0 var(--johnbot-space-3);
  color: var(--johnbot-text-muted);
  font-size: var(--johnbot-text-md);
  font-weight: var(--johnbot-weight-medium);
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color var(--johnbot-duration-fast) ease,
    color var(--johnbot-duration-fast) ease;
}

.marketplace-agent-update-option-label:hover,
.marketplace-agent-update-option[data-checked] .marketplace-agent-update-option-label {
  color: var(--johnbot-text-primary);
}

.marketplace-agent-update-option[data-checked] .marketplace-agent-update-option-label {
  background: var(--johnbot-tabs-pill-bg);
}

.marketplace-agent-update-option:has(input:focus-visible) .marketplace-agent-update-option-label {
  box-shadow: var(--johnbot-focus-ring);
}

/* Replace loses the user's files, so the chosen Replace wears the warning color. */
.marketplace-agent-update-option[data-choice="replace"][data-checked] .marketplace-agent-update-option-label {
  color: var(--johnbot-warning-text);
}

.marketplace-agent-update-others {
  margin: var(--johnbot-space-2) 0 0;
  color: var(--johnbot-text-dim);
  font-size: var(--johnbot-text-sm);
}


/* upstream: packages/ui/src/features/settings/slack-integration.css */
/* Marketplace > Apps > Slack, Discord, Telegram and WhatsApp: the channel pages (ChannelParts.tsx). */

.channel-stack {
  display: grid;
  gap: var(--johnbot-space-0-5);
  justify-items: start;
}

/* ------------------------------------------------ connect dialog */

.channel-checklist {
  display: grid;
  gap: var(--johnbot-space-2);
  margin: 0;
  padding: var(--johnbot-space-3) var(--johnbot-space-4);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-surface);
  list-style: none;
  font-size: var(--johnbot-text-sm);
}

.channel-checklist li {
  display: flex;
  gap: var(--johnbot-space-2);
  align-items: center;
}

.channel-checklist li[data-state="done"] {
