/* ------------------------------------------------ WhatsApp link dialog */

/* What the number is and how the phone links: cards with a radio dot, as in the mobile route choice. */
.whatsapp-choice {
  display: grid;
  gap: var(--johnbot-space-2);
}

.whatsapp-choice[data-layout="row"] {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.whatsapp-choice-option {
  display: flex;
  min-width: 0;
}

.whatsapp-choice-card {
  display: flex;
  flex: 1;
  align-items: flex-start;
  gap: var(--johnbot-space-3);
  min-width: 0;
  padding: var(--johnbot-space-2) var(--johnbot-space-3);
  border-radius: var(--johnbot-radius-lg);
  background: var(--johnbot-bg-control);
  box-shadow: inset 0 0 0 1px var(--johnbot-border);
  cursor: pointer;
  transition-property: background-color, box-shadow;
  transition-duration: var(--johnbot-duration-hover), var(--johnbot-duration-normal);
  transition-timing-function: var(--johnbot-ease-out);
}

.whatsapp-choice-card:hover {
  background: var(--johnbot-bg-control-hover);
}

.whatsapp-choice-card[data-disabled] {
  cursor: default;
}

.whatsapp-choice-card[data-checked] {
  box-shadow: inset 0 0 0 1.5px var(--johnbot-accent);
}

.whatsapp-choice-option:has(:focus-visible) .whatsapp-choice-card {
  box-shadow: var(--johnbot-focus-ring);
}

/* A ring, filled when the option is selected. */
.whatsapp-choice-dot {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: var(--johnbot-icon-md);
  height: var(--johnbot-icon-md);
  margin-top: 1px;
  border-radius: var(--johnbot-radius-pill);
  box-shadow: inset 0 0 0 1.5px var(--johnbot-text-muted);
  transition: box-shadow var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

.whatsapp-choice-dot::after {
  width: 8px;
  height: 8px;
  border-radius: var(--johnbot-radius-pill);
  background: var(--johnbot-accent);
  content: "";
  transform: scale(0);
  transition: transform var(--johnbot-duration-normal) var(--johnbot-ease-out);
}

.whatsapp-choice-card[data-checked] .whatsapp-choice-dot {
  box-shadow: inset 0 0 0 1.5px var(--johnbot-accent);
}

.whatsapp-choice-card[data-checked] .whatsapp-choice-dot::after {
  transform: scale(1);
}

.whatsapp-choice-text {
  display: grid;
  gap: var(--johnbot-space-0-5);
  min-width: 0;
}

.whatsapp-choice-name {
