}


/* upstream: onepassword-connector.css */
/* A vault secret: the labelled field, and its buttons in line with the field, not with the label. */
.vault-secret-form {
  display: flex;
  align-items: flex-end;
  gap: var(--johnbot-space-3);
}

.vault-secret-form > .ui-field {
  flex: 1;
  min-width: 0;
}

.vault-secret-actions {
  display: flex;
  gap: var(--johnbot-space-2);
  align-items: center;
}

/* A joined server's Bitwarden form: one field per row, the buttons under them. */
.bitwarden-connector-host-form {
  display: grid;
  gap: var(--johnbot-space-3);
}

.bitwarden-connector-actions {
  display: flex;
  gap: var(--johnbot-space-2);
  align-items: center;
}

/* A step's text is its instruction, so it wraps instead of ending in an ellipsis. */
.onepassword-connector-step .ui-item-description {
  white-space: normal;
}

.onepassword-connector-step .ui-item-media {
  color: var(--johnbot-text-muted);
}

.onepassword-connector-step[data-step="done"] .ui-item-media {
  color: var(--johnbot-success);
}

/* A step whose earlier step is not done is quieter, so the eye goes to the one to do now. */
.onepassword-connector-step[data-step="waiting"] .ui-item-title {
  color: var(--johnbot-text-muted);
}


/*
 * The plush loader: the lilac plush watches three felt balls bounce in a wave, and its eyes follow
 * the ball in the air. The parent sets --ui-plush-size, the width of the plush. With reduced motion
 * the plush and the balls stay still.
 */

.ui-plush-loader {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: flex-end;
  gap: calc(var(--ui-plush-size) * 0.18);
}

.ui-plush-loader[data-layout="stack"] {
  flex-direction: column;
  align-items: center;
  gap: calc(var(--ui-plush-size) * 0.3);
}

.ui-plush-mascot {
  --ui-plush-look: calc(var(--ui-plush-size) * 0.035);
  position: relative;
  display: block;
  width: var(--ui-plush-size);
  flex: 0 0 auto;
}

.ui-plush-body {
  position: relative;
  display: block;
  transform-origin: 50% 100%;
}

.ui-plush-body-image,
.ui-plush-ball {
  display: block;
  width: 100%;
  max-width: none;
  user-select: none;
  -webkit-user-drag: none;
}

.ui-plush-eyes,
.ui-plush-eye {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  max-width: none;
  user-select: none;
  -webkit-user-drag: none;
}

.ui-plush-eye {
  transform-origin: 35.6% 48.1%;
  transition: scale var(--johnbot-duration-overlay) var(--johnbot-ease-out);
}

.ui-plush-eye[data-side="right"] {
  transform-origin: 64.4% 48.1%;
}

.ui-plush-mascot[data-face="wide"] .ui-plush-eye {
  scale: 1.18;
}

.ui-plush-balls {
  display: flex;
  gap: calc(var(--ui-plush-size) * 0.08);
  padding-bottom: calc(var(--ui-plush-size) * 0.04);
}

.ui-plush-ball {
  width: calc(var(--ui-plush-size) * 0.24);
  transform-origin: 50% 100%;
}

.ui-plush-loader[data-layout="stack"] .ui-plush-balls {
  padding-bottom: 0;
}

.ui-plush-loader[data-layout="stack"] .ui-plush-ball {
  width: calc(var(--ui-plush-size) * 0.2);
}

@media (prefers-reduced-motion: no-preference) {
  .ui-plush-body {
    animation: ui-plush-breathe 3.2s ease-in-out 600ms infinite;
  }

  .ui-plush-eye {
    animation: ui-plush-blink 5.2s ease-in-out 1.8s infinite;
  }

  .ui-plush-eyes {
    animation: ui-plush-look 6s ease-in-out 2.2s infinite;
  }

  .ui-plush-mascot[data-face="wink"] .ui-plush-eye[data-side="left"] {
    animation: ui-plush-wink 600ms var(--johnbot-ease-out);
  }

  .ui-plush-mascot[data-face="happy"] .ui-plush-eye {
    animation: ui-plush-squint 220ms var(--johnbot-ease-out) forwards;
  }

  .ui-plush-loader > .ui-plush-mascot {
    animation: ui-plush-pop-in 520ms var(--johnbot-ease-out) both;
  }

  .ui-plush-loader .ui-plush-eyes {
    animation: ui-plush-follow 1.2s ease-in-out 700ms infinite;
  }

  .ui-plush-ball {
    animation:
      ui-plush-pop-in 360ms var(--johnbot-ease-out) 300ms backwards,
      ui-plush-ball-bounce 1.2s ease-in-out 700ms infinite;
  }

  .ui-plush-ball:nth-child(2) {
    animation-delay: 380ms, 850ms;
  }

  .ui-plush-ball:nth-child(3) {
    animation-delay: 460ms, 1s;
  }
}

@keyframes ui-plush-pop-in {
  from {
    opacity: 0;
    transform: scale(0.6);
  }
}

@keyframes ui-plush-breathe {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.012, 0.978);
  }
}

@keyframes ui-plush-blink {
  0%,
  93%,
  100% {
    transform: scaleY(1);
  }
  96% {
    transform: scaleY(0.1);
  }
}

@keyframes ui-plush-wink {
  0%,
  100% {
    transform: scaleY(1);
  }
  30%,
  60% {
    transform: scaleY(0.1);
  }
}

@keyframes ui-plush-squint {
  to {
    transform: translateY(-1.5%) scaleY(0.35);
  }
}

@keyframes ui-plush-look {
  0%,
  28%,
  86%,
  100% {
    transform: translate(0, 0);
  }
  34%,
  50% {
    transform: translate(calc(var(--ui-plush-look) * -1), calc(var(--ui-plush-look) * 0.2));
  }
  58%,
  78% {
    transform: translate(var(--ui-plush-look), calc(var(--ui-plush-look) * -0.3));
  }
}

@keyframes ui-plush-follow {
  0%,
  18% {
    transform: translate(calc(var(--ui-plush-look) * -0.9), calc(var(--ui-plush-look) * 0.6));
  }
  32% {
    transform: translate(0, calc(var(--ui-plush-look) * 0.6));
  }
  46%,
  70% {
    transform: translate(calc(var(--ui-plush-look) * 0.9), calc(var(--ui-plush-look) * 0.6));
  }
  100% {
    transform: translate(calc(var(--ui-plush-look) * -0.9), calc(var(--ui-plush-look) * 0.6));
  }
}

@keyframes ui-plush-ball-bounce {
  0%,
  60%,
  100% {
    transform: translateY(0) scale(1);
  }
  22% {
    transform: translateY(-110%) scale(0.95, 1.06);
  }
  42% {
    transform: translateY(0) scale(1.14, 0.84);
  }
  50% {
    transform: translateY(0) scale(1);
  }
}
